#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define ADC_CHANNEL 0        /* MCP3008 CH0 */
#define SAMPLE_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, or -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 Soil Moisture Sensor Reader\n");
    printf("SPI channel %d, speed %d Hz, ADC channel %d\n",
           SPI_CHANNEL, SPI_SPEED, ADC_CHANNEL);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — continuing\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char time_buf[32];

            if (localtime_r(&now, &tm_info) != NULL &&
                strftime(time_buf, sizeof(time_buf),
                         "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                printf("[%s] ADC CH%d: %4d\n", time_buf, ADC_CHANNEL, adc_value);
            } else {
                printf("ADC CH%d: %4d\n", ADC_CHANNEL, adc_value);
            }
            fflush(stdout);
        }

        /* Sleep 1 s, but wake early if a signal arrives */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "Warning: spiClose failed\n");
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

