/*
 * Raspberry Pi 4 Model B — MLX91219 Hall-Effect Current Sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V (Pi pin 1)
 *   MLX91219 GND  -> GND   (Pi pin 9)
 *   MLX91219 OUT  -> ADS1115 AIN0
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   ADS1115 SDA   -> GPIO2 / Pi pin 3
 *   ADS1115 SCL   -> GPIO3 / Pi pin 5
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx91219_ads1115 mlx91219_ads1115.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADS1115 register addresses ---- */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* ---- ADS1115 config bit fields ---- */
#define ADS1115_CFG_OS_SINGLE   0x8000  /* Bit 15: start single conversion */
#define ADS1115_CFG_MUX_AIN0    0x4000  /* Bits 14:12 = 100 -> AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V  0x0200  /* Bits 11:9  = 001 -> ±4.096 V */
#define ADS1115_CFG_MODE_SINGLE 0x0100  /* Bit 8     = 1   -> single-shot */
#define ADS1115_CFG_DR_128SPS   0x0080  /* Bits 7:5  = 100 -> 128 SPS */
#define ADS1115_CFG_CQUE_NONE   0x0003  /* Bits 2:0  = 11  -> disable comparator */

#define ADS1115_I2C_ADDR        0x48
#define I2C_BUS                 "/dev/i2c-1"
#define SAMPLE_INTERVAL_US      500000  /* 500 ms */
#define CONV_WAIT_US            10000   /* 10 ms — well above 128 SPS */

/*
 * MLX91219 transfer function (analog output):
 *   V_out = 0.0005 * I_out  (5 mV/A)
 *   4.096 V PGA  -> 1 A = 81.92 counts
 *   I_out = (raw / 81.92) A
 */
#define MLX91219_SENSITIVITY    0.0005f
#define PGA_FULL_SCALE_COUNTS   81.92f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * The ADS1115 expects big-endian (MSB first) on the bus.
 */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)((value >> 8) & 0xFF);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * The ADS1115 returns big-endian on the bus.
 */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg(0x%02X): select failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success and stores the signed 16-bit raw value in *raw.
 * Returns -1 on I2C error or if the conversion is not complete.
 */
static int ads1115_read_ain0(int fd, int16_t *raw)
{
    uint16_t config = ADS1115_CFG_OS_SINGLE
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096V
                    | ADS1115_CFG_MODE_SINGLE
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for the conversion to complete (128 SPS -> ~7.8 ms; 10 ms is safe) */
    usleep(CONV_WAIT_US);

    uint16_t cfg_read;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg_read) != 0)
        return -1;

    if (!(cfg_read & ADS1115_CFG_OS_SINGLE)) {
        fprintf(stderr, "ads1115_read_ain0: conversion not complete (cfg=0x%04X)\n",
                cfg_read);
        return -1;
    }

    uint16_t conv;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADS1115 slave address */
    if (ioctl(fd, I2C_SLAVE, ADS1115_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADS1115_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Verify the ADS1115 is present by reading the config register.
     * A non-zero value indicates the device responded.
     */
    uint16_t cfg_check;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg_check) != 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X — check wiring.\n",
                ADS1115_I2C_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX91219 via ADS1115 ready. Sampling every 500 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(fd, &raw) != 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = (float)raw * MLX91219_SENSITIVITY;
        printf("Current: %.4f A\n", current);

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    if (close(fd) != 0)
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

