/*
 * KY-026 Flame Sensor + MCP3008 ADC logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND   (Pin 9)
 *   KY-026 D0   -> GPIO4 (BCM 4, Pin 7)
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CLK -> GPIO11 (BCM 11, Pin 23)
 *   MCP3008 DOUT-> GPIO9  (BCM 9,  Pin 21)
 *   MCP3008 DIN -> GPIO10 (BCM 10, Pin 19)
 *   MCP3008 CS  -> GPIO8  (BCM 8,  Pin 24)
 *   MCP3008 CH0 -> KY-026 A0
 *
 * Build: gcc -O2 -Wall -o flame_logger flame_logger.c -lpigpio -lrt
 * Run:   sudo ./flame_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL       0
#define SPI_BAUD          1000000
#define SPI_FLAGS         0
#define LOG_FILE          "flame_data.csv"
#define SAMPLE_INTERVAL   1.0

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel select
     *   Byte 2: 0x00  (don't care, clocked out to capture low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in the two LSBs
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static float calculate_temperature(int adc_value)
{
    /*
     * Placeholder linear approximation:
     *   ADC 0 -> 20 °C, ADC 1023 -> 100 °C.
     * Replace with a calibrated curve from your specific sensor.
     */
    return 20.0f + ((float)adc_value / 1023.0f) * 80.0f;
}

static int log_data(int flame_detected, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure flame sensor digital input --- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flame_detected,temperature_c\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor logging started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_GPIO);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read flame sensor GPIO%d\n", FLAME_SENSOR_GPIO);
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "MCP3008 read failed; skipping sample\n");
            time_sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temperature = calculate_temperature(adc_value);

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        time_sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

