#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_AIN0_GND 0x4000
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 100000
#define BUZZER_DURATION_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    return gpioRead(FLAME_SENSOR_PIN);
}

static int read_temperature(float *temp_out) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid.\n");
        return -1;
    }

    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config.\n");
        return -1;
    }

    gpioDelay(10000);

    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion data.\n");
        return -1;
    }

    int16_t raw = (read_buf[0] << 8) | read_buf[1];
    *temp_out = (raw * 4.096) / 32768.0;
    return 0;
}

static void activate_buzzer(void) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(BUZZER_DURATION_US);
    gpioWrite(BUZZER_PIN, 0);
}

static void log_event(const char *message) {
    if (!log_file) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_state = read_flame_sensor();
        if (flame_state < 0) {
            fprintf(stderr, "Error: Failed to read flame sensor.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        gpioDelay(DEBOUNCE_DELAY_US);

        int flame_state_debounced = read_flame_sensor();
        if (flame_state_debounced < 0) {
            fprintf(stderr, "Error: Failed to read flame sensor during debounce.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float temperature;
        int temp_ok = read_temperature(&temperature);

        if (flame_state_debounced && flame_state_debounced == flame_state) {
            if (temp_ok == 0 && temperature > TEMPERATURE_THRESHOLD) {
                log_event("Fire detected! Flame and high temperature.");
                printf("Fire detected! Flame and high temperature.\n");
            } else if (temp_ok == 0) {
                char msg[128];
                snprintf(msg, sizeof(msg), "High temperature detected: %.2f C", temperature);
                log_event(msg);
                printf("High temperature detected: %.2f C\n", temperature);
            } else if (flame_state) {
                log_event("Flame detected!");
                printf("Flame detected!\n");
            }
            activate_buzzer();
        } else if (flame_state) {
            log_event("Flame detected!");
            printf("Flame detected!\n");
        } else if (temp_ok == 0 && temperature > TEMPERATURE_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg), "High temperature detected: %.2f C", temperature);
            log_event(msg);
            printf("High temperature detected: %.2f C\n", temperature);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

