#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          SPI_MODE_0

#define GPIO_CHIP_NAME    "gpiochip4"
#define FAN_GPIO_LINE     18
#define CURRENT_THRESHOLD 100.0f
#define LOG_FILE          "current_log.txt"
#define SAMPLE_INTERVAL_S 1

#define ADC_MAX_VALUE     1023
#define ADC_MIN_VALUE     0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int spi_fd, uint8_t channel, uint16_t *adc_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then 10-bit result */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static float adc_to_current(uint16_t adc_value)
{
    /*
     * Placeholder linear mapping.
     * Replace with the actual MLX91219 transfer function
     * after characterizing the sensor and calibrating.
     */
    return (float)adc_value * 0.1f;
}

static int log_data(float current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *fan_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * On the Raspberry Pi 5 the main GPIO controller is gpiochip4.
     * Try that first, then fall back to gpiochip0 for compatibility.
     */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                FAN_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device '%s': %s\n",
                SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Monitoring current sensor via MCP3008 on %s...\n", SPI_DEVICE);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(spi_fd, 0, &adc_value) < 0) {
            fprintf(stderr, "SPI read error — continuing.\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Sensor-absent heuristic: all-zero or all-ones */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC reads %u — sensor may be absent or disconnected.\n",
                    adc_value);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_data(current) < 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        int fan_state = (current > CURRENT_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "Failed to set fan GPIO: %s\n", strerror(errno));
        }

        printf("Current: %.2f A, Fan: %s\n", current, fan_state ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

