/*
 * CO Monitoring System for Raspberry Pi 4 Model B
 * Sensor: Honeywell/SGX MICROceL MICS-4514 (dual-element MOS, NO2/CO)
 * ADC:    External 16-bit ADC (e.g., ADS1115) or simulated raw reading
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 *
 * Build:  gcc -O2 -Wall -o co_monitor co_monitor.c -lm
 * Run:    ./co_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define I2C_ADDR             0x48          /* ADS1115 default address */
#define LOG_FILE             "co_log.txt"
#define SAMPLE_INTERVAL_SEC  5
#define MAX_RETRIES          3
#define ADC_MAX_VALUE        32767.0       /* 16-bit signed positive max */

/* ADS1115 registers */
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * ADS1115 config word (16-bit, big-endian on the bus):
 *   Bit 15    OS           = 1  (begin single conversion)
 *   Bits14:11 MUX          = 100 (AIN0 vs GND)
 *   Bits10:9  PGA          = 001 (±4.096 V)
 *   Bit  8    MODE         = 1  (single-shot)
 *   Bits7:5   DR           = 100 (128 SPS)
 *   Bit  4    COMP_MODE    = 0
 *   Bit  3    COMP_POL     = 0
 *   Bit  2    COMP_LAT     = 0
 *   Bits1:0   COMP_QUE     = 11 (disable comparator)
 * => 0xC183
 */
#define ADS1115_CONFIG_BASE  0xC183

/* Calibration constants (example values, replace with your calibration) */
#define CO_SCALE_FACTOR      0.1           /* ppm per ADC count */
#define CO_OFFSET            0.0

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  initialize(void);
static int  read_adc_raw(int16_t *raw_out);
static double calculate_co_ppm(int16_t raw);
static int  log_data(double ppm);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ---------------------------- */

static int initialize(void)
{
    /* --- pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* --- Configure ADS1115 for single-shot, AIN0, ±4.096 V, 128 SPS --- */
    uint16_t config = ADS1115_CONFIG_BASE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(config >> 8);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: ADS1115 config write failed.\n");
        cleanup();
        return -1;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return -1;
    }

    fprintf(g_log_file, "# CO Monitor started — I2C bus %d, ADS1115 @ 0x%02X\n",
            I2C_BUS, I2C_ADDR);
    fflush(g_log_file);

    return 0;
}

/* ----------------------------- ADC Read ---------------------------------- */

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success, -1 on error.
 */
static int read_adc_raw(int16_t *raw_out)
{
    char reg = ADS1115_REG_CONV;
    char data[2];

    /* Point to conversion register */
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: ADS1115 pointer write failed.\n");
        return -1;
    }

    /* Read 2 bytes (big-endian) */
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: ADS1115 conversion read failed.\n");
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) |
                         (uint16_t)(uint8_t)data[1]);
    return 0;
}

/* ----------------------------- CO Calculation ---------------------------- */

static double calculate_co_ppm(int16_t raw)
{
    /*
     * Logarithmic calibration:
     *   ppm = CO_SCALE_FACTOR * log10(raw + 1) + CO_OFFSET
     *
     * The raw value is a 16-bit signed ADC count; log10(0) is undefined,
     * so we add 1 to the raw value before taking the log to avoid it.
     */
    return CO_SCALE_FACTOR * log10((double)raw + 1.0) + CO_OFFSET;
}

/* ----------------------------- Logging ----------------------------------- */

static int log_data(double ppm)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f ppm\n", ts, ppm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("CO Monitoring System started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_adc_raw(&raw) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Warning: ADC read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(1);
            }
        }

        if (!ok) {
            fprintf(stderr, "Error: ADC read failed after %d attempts — "
                    "sensor may be absent or bus error.\n", MAX_RETRIES);
            /* Still log the error so gaps are visible in the log */
            log_data(-1.0);
        } else {
            double ppm = calculate_co_ppm(raw);
            if (log_data(ppm) != 0) {
                fprintf(stderr, "Error: failed to log data.\n");
            }
            printf("Raw=%d  CO=%.2f ppm\n", raw, ppm);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_SEC && g_running; ++s) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

