/*
 * KY-026 Flame Sensor + MCP3008 ADC logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND   (Pin 9)
 *   KY-026 D0   -> GPIO4 (BCM 4, Pin 7)
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CLK -> GPIO11 (BCM 11, Pin 23)
 *   MCP3008 DOUT-> GPIO9  (BCM 9,  Pin 21)
 *   MCP3008 DIN -> GPIO10 (BCM 10, Pin 19)
 *   MCP3008 CS  -> GPIO8  (BCM 8,  Pin 24)
 *   MCP3008 CH0 -> KY-026 A0
 *
 * Build: gcc -O2 -Wall -o flame_logger flame_logger.c -lpigpio -lrt
 * Run:   sudo ./flame_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL       0
#define SPI_SPEED         1000000  /* 1 MHz */
#define SPI_FLAGS         0
#define LOG_FILE          "flame_data.csv"
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel, upper nibble
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in the low 2 bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/*
 * Convert the 10-bit ADC value to a temperature in Celsius.
 * KY-026 module: 0 V -> 0 °C, 3.3 V -> 100 °C.
 * Returns -1.0 on invalid input.
 */
static float adc_to_temperature(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0f;
    }
    return (float)adc_value * (3.3f / 1024.0f) * 100.0f;
}

/*
 * Append a timestamped CSV row.
 * Returns 0 on success, -1 on error.
 */
static int log_data(int flame_detected, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure flame sensor GPIO as input --- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen(channel=%d, speed=%d) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor logging started. Press Ctrl-C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_GPIO);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", FLAME_SENSOR_GPIO);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        int adc_value = read_mcp3008(spi_handle, 0);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        if (temperature < 0.0f) {
            fprintf(stderr, "ADC value out of range — skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

