/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU analog MEMS microphone logger
 *
 * Wiring:
 *   IMP23ABSU #1 OUT  -> GPIO2 (BCM 2)
 *   IMP23ABSU #2 OUT  -> GPIO3 (BCM 3)
 *   IMP23ABSU VDD     -> 3.3 V
 *   IMP23ABSU GND     -> GND
 *   IMP23ABSU SDA     -> (unused)
 *   IMP23ABSU SCL     -> (unused)
 *
 * The IMP23ABSU OUT pin is read as a digital value (0 or 1) via bit-banged
 * I2C-style sampling.  A 100 ms period produces a 10 Hz sampling rate.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define MIC1_GPIO 2
#define MIC2_GPIO 3
#define SAMPLE_PERIOD_US 100000          /* 100 ms */
#define LOG_FILE        "audio_log.txt"
#define ERROR_VALUE     (-999.0f)
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C-style bit-bang read of an analog microphone OUT line            */
/* ------------------------------------------------------------------ */
/*
 * The IMP23ABSU OUT pin is a digital value (0 or 1) that is derived
 * from the analog sound pressure level.  We sample it as a digital
 * value by toggling the GPIO pin between input and output, reading
 * the level, and then returning the pin to input mode.
 *
 * Returns 0 on success (value stored in *out), -1 on persistent failure.
 */
static int read_mic_digital(int gpio, int *out)
{
    int retries = 0;

    while (retries < MAX_RETRIES) {
        /* Put pin into output drive mode (high) so we can read the line. */
        if (gpio_set_mode(gpio, GPIO_OUTPUT) != 0) {
            fprintf(stderr, "gpio_set_mode(OUTPUT) failed on GPIO %d: %s\n",
                    gpio, strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }
        if (gpio_write(gpio, 1) != 0) {
            fprintf(stderr, "gpio_write(1) failed on GPIO %d: %s\n",
                    gpio, strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }
        usleep(10);                       /* let line settle */

        /* Read the digital value. */
        int v = gpio_read(gpio);
        if (v < 0) {
            fprintf(stderr, "gpio_read failed on GPIO %d: %s\n",
                    gpio, strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }

        /* Return pin to input mode. */
        if (gpio_set_mode(gpio, GPIO_INPUT) != 0) {
            fprintf(stderr, "gpio_set_mode(INPUT) failed on GPIO %d: %s\n",
                    gpio, strerror(errno));
            retries++;
            usleep(1000);
            continue;
        }

        *out = v;
        return 0;
    }

    fprintf(stderr, "Failed to read GPIO %d after %d retries\n", gpio, MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Conversion to decibel                                               */
/* ------------------------------------------------------------------ */
/*
 * The IMP23ABSU is an analog MEMS microphone.  Its analog output
 * (0–3.3 V) is proportional to the sound pressure level.  We treat
 * the digital value (0 or 1) as a proxy for the analog level and
 * convert it to a decibel value.
 *
 * A digital value of 1 corresponds to a sound pressure level near
 * the microphone's maximum (~3.3 V).  A digital value of 0 is near
 * zero.  We scale linearly so that the digital range spans 0–90 dB.
 */
static float digital_to_db(int digital)
{
    const float max_db = 90.0f;
    const int digital_max = 1;

    if (digital < 0)
        digital = 0;
    if (digital > digital_max)
        digital = digital_max;

    return (float)digital * max_db / (float)digital_max;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float mic1_db, float mic2_db, float avg_db)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Mic1: %.2f dB, Mic2: %.2f dB, Avg: %.2f dB\n",
            ts, mic1_db, mic2_db, avg_db);

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /*
     * gpiod is the modern GPIO API on Raspberry Pi OS.  We use it
     * to configure the microphone pins as inputs so that the
     * bit-bang sampling below works correctly.
     */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        /* Fall back to the default chip (gpiochip0 on older kernels). */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(chip, MIC1_GPIO);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, MIC2_GPIO);
    if (line1 == NULL || line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as inputs. */
    if (gpiod_line_request_input(line1, "imp23abs_mic1") != 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                MIC1_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(line2, "imp23abs_mic2") != 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                MIC2_GPIO, strerror(errno));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Audio logger started.  Sampling every %d ms.  Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    while (g_running) {
        int d1 = 0, d2 = 0;
        int r1 = read_mic_digital(MIC1_GPIO, &d1);
        int r2 = read_mic_digital(MIC2_GPIO, &d2);

        float mic1_db = r1 ? ERROR_VALUE : digital_to_db(d1);
        float mic2_db = r2 ? ERROR_VALUE : digital_to_db(d2);
        float avg_db  = (mic1_db + mic2_db) / 2.0f;

        log_data(mic1_db, mic2_db, avg_db);

        usleep(SAMPLE_PERIOD_US);
    }

    /* Clean up */
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("\nAudio logger stopped.\n");
    return EXIT_SUCCESS;
}

