        log_data(mic1_db, mic2_db, avg_db);

        usleep(SAMPLE_PERIOD_US);
    }

    /* Clean up */
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("\nAudio logger stopped.\n");
    return EXIT_SUCCESS;
}

