#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define LED_GPIO 27

#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 1000
#define LED_ON_TIME_US 500000

#define HIGH_THRESHOLD 100.0

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

#define CSV_FILE "audio_events.csv"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_rms(const int *data, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)data[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / num_samples);
}

static int log_event(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("fopen(" CSV_FILE ")");
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&now, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, mic1_rms, mic2_rms) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    int mic1_data[NUM_SAMPLES];
    int mic2_data[NUM_SAMPLES];

    while (running) {
        int mic1_rms_count = 0;
        int mic2_rms_count = 0;

        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            int v1 = read_mcp3008(spi_handle, MIC1_CHANNEL);
            int v2 = read_mcp3008(spi_handle, MIC2_CHANNEL);

            if (v1 < 0 || v2 < 0) {
                fprintf(stderr, "SPI read error at sample %d\n", i);
                break;
            }

            mic1_data[i] = v1;
            mic2_data[i] = v2;

            if (v1 > HIGH_THRESHOLD) mic1_rms_count++;
            if (v2 > HIGH_THRESHOLD) mic2_rms_count++;

            if (i < NUM_SAMPLES - 1) {
                gpioDelay(SAMPLE_DELAY_US);
            }
        }

        if (!running) break;

        double mic1_rms = calculate_rms(mic1_data, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_data, NUM_SAMPLES);

        if (log_event(mic1_rms, mic2_rms) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        if (mic1_rms_count > 0 || mic2_rms_count > 0) {
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);
        }
    }

    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

