/*
 * MLX91204 Hall effect current sensor monitor using ADS1115 ADC.
 *
 * Hardware (Raspberry Pi 4 Model B):
 *   - ADS1115 SDA -> GPIO2 (BCM 2, I2C bus 1)
 *   - ADS1115 SCL -> GPIO3 (BCM 3, I2C bus 1)
 *   - ADS1115 ADDR -> GND (I2C address 0x48)
 *   - ADS1115 A0  -> MLX91204 analog output
 *   - Warning LED -> GPIO17 (BCM 17) with appropriate series resistor
 *
 * Build: gcc -O2 -Wall -o mlx91204_monitor mlx91204_monitor.c -lpigpio -lrt
 * Run:   sudo ./mlx91204_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48          /* ADDR pin tied to GND */

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config word: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS, start */
#define ADS1115_CFG_BASE     0x8083        /* MUX=AIN0/GND, PGA=+/-4.096V */
#define ADS1115_CFG_DR_128   0x0080        /* Data rate 128 SPS */
#define ADS1115_CFG_OS       0x8000        /* Operational status / single-shot */
#define ADS1115_CFG_DEFAULT  (ADS1115_CFG_BASE | ADS1115_CFG_DR_128 | ADS1115_CFG_OS)

#define CURRENT_THRESHOLD    50.0          /* Amperes */
#define BUFFER_SIZE          100
#define SAMPLE_PERIOD_US     10000         /* 10 Hz */
#define CONVERSION_TIMEOUT   100           /* ms */

#define LED_GPIO             17

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  ads1115_init(int handle);
static int  ads1115_read_raw(int handle, int16_t *raw_out);
static double raw_to_current(int16_t raw);
static void buffer_add(double current, double buffer[], int *idx, int size);
static double buffer_average(const double buffer[], int size);
static void check_threshold(double avg_current);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 helpers ---------------------------- */

static int ads1115_init(int handle)
{
    /* Write config register to start a single-shot conversion */
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (ADS1115_CFG_DEFAULT >> 8) & 0xFF;
    cfg[2] = ADS1115_CFG_DEFAULT & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    char reg = ADS1115_REG_CONV;
    char data[2];

    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register pointer\n");
        return -1;
    }

    /* Small delay so the bus settles after the pointer write */
    gpioDelay(1000);

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data\n");
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* ----------------------------- Conversion --------------------------------- */

static double raw_to_current(int16_t raw)
{
    /*
     * MLX91204 output is proportional to current.
     * ADS1115 PGA = +/-4.096 V -> 1 bit = 125 uV.
     * raw * 125 uV / 1000 = milli-Amperes.
     */
    return (double)raw * 0.000125;
}

/* ----------------------------- Circular buffer ---------------------------- */

static void buffer_add(double current, double buffer[], int *idx, int size)
{
    buffer[*idx] = current;
    *idx = (*idx + 1) % size;
}

static double buffer_average(const double buffer[], int size)
{
    double sum = 0.0;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (double)size;
}

/* ----------------------------- Threshold check ---------------------------- */

static void check_threshold(double avg_current)
{
    if (avg_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        printf("WARNING: Average current %.2f A exceeds threshold %.2f A\n",
               avg_current, CURRENT_THRESHOLD);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    double current_buffer[BUFFER_SIZE];
    int    buffer_index = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: ADS1115 not detected or not responding\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91204 current monitor started. Sampling at 10 Hz, threshold %.1f A.\n",
           CURRENT_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;

        if (ads1115_read_raw(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double current = raw_to_current(raw);
        buffer_add(current, current_buffer, &buffer_index, BUFFER_SIZE);
        double avg = buffer_average(current_buffer, BUFFER_SIZE);

        check_threshold(avg);

        printf("Current: %.2f A | Avg: %.2f A\n", current, avg);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

