        if (ads1115_read_raw(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double current = raw_to_current(raw);
        buffer_add(current, current_buffer, &buffer_index, BUFFER_SIZE);
        double avg = buffer_average(current_buffer, BUFFER_SIZE);

        check_threshold(avg);

        printf("Current: %.2f A | Avg: %.2f A\n", current, avg);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

