/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A

/* Expected device ID */
#define TCS34725_ID_VALUE 0x44

/* Enable register bits */
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

/* Integration time (ATIME) — powers of 2 × 2.4 ms  */
#define TCS34725_ATIME_2_4MS  0x00
#define TCS34725_ATIME_204MS  0x01
#define TCS34725_ATIME_614MS  0x02
#define TCS34725_ATIME_2_4S   0x03

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a TCS34725 register; return 0 on success, -1 error  */
/* ------------------------------------------------------------------ */
static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a TCS34725 register; return 0 on success, -1 error */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from a TCS34725 register           */
/* ------------------------------------------------------------------ */
static int tcs34725_read_word(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Warning: i2cReadI2CBlockData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725 sensor                                      */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (tcs34725_read_reg(handle, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error: cannot read TCS34725 ID register.\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Error: TCS34725 ID mismatch (got 0x%02X, expected 0x%02X).\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;

    /* Wait for power-on to complete (datasheet: 2.4 ms max) */
    gpioDelay(3000); /* 3 ms */

    /* Enable RGBC ADC */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE,
                           TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    /* Set integration time to 2.4 ms (fastest) */
    if (tcs34725_write_reg(handle, TCS34725_ATIME, TCS34725_ATIME_2_4MS) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read RGBC values from the TCS34725                                  */
/* ------------------------------------------------------------------ */
static int tcs34725_read_rgbc(int handle, uint16_t *clear,
                              uint16_t *red, uint16_t *green, uint16_t *blue)
{
    if (tcs34725_read_word(handle, TCS34725_CDATAL, clear) != 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_RDATAL, red)   != 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_GDATAL, green) != 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_BDATAL, blue)  != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line with a timestamp                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Warning: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n",
                timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Warning: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes file, I2C handle, releases pigpio          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

