    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TCS34725 address */
    g_i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: TCS34725 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty */
    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open color_log.csv: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,clear,red,green,blue\n") < 0) {
            fprintf(stderr, "Warning: cannot write CSV header: %s\n",
                    strerror(errno));
        }
        fflush(g_log_file);
    }

    printf("TCS34725 color logger started. Press Ctrl+C to stop.\n");

    int consecutive_failures = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_rgbc(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_failures = 0;
            if (log_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Warning: logging failed.\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: I2C read failed (consecutive: %d).\n",
                    consecutive_failures);
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Error: 3 consecutive I2C failures. Exiting.\n");
                break;
            }
        }

        /* Sleep 1 second using pigpio's high-resolution delay */
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

