#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define GPIO_CHIP "gpiochip4"
#define MOTOR_GPIO_LINE 17
#define OVERCURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_GPIO_LINE);
    if (!motor_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(motor_line, "motor_control", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        motor_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static float adc_to_current(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return (adc_value / 1023.0f) * OVERCURRENT_THRESHOLD;
}

static int log_current(float current) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Current (A)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, current);
    fclose(fp);
    return 0;
}

static void control_motor(int enable) {
    if (gpiod_line_set_value(motor_line, enable ? 1 : 0) < 0) {
        perror("Failed to set motor GPIO value");
    }
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float current = adc_to_current(adc_value);
        if (current < 0.0f) {
            fprintf(stderr, "Invalid current reading.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current reading.\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Current: %.2f A\n", current);
            control_motor(0);
            printf("Motor disabled.\n");
            sleep(1);
            control_motor(1);
            printf("Motor re-enabled.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

