/*
 * MLX90817 absolute pressure logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90817 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90817 VDD  -> 3.3 V
 *   MLX90817 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90817_log mlx90817_log.c -li2c -lm
 *
 * The sensor exposes a 16-bit big-endian register at address 0x00
 * that holds the current pressure in kPa.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90817_ADDR  0x50
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1           /* seconds between samples */
#define MAX_READ_ERRORS 10         /* consecutive failures before giving up */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a 16-bit big-endian register from the MLX90817.
 * Returns 0 on success and stores the value in *out;
 * returns -1 on any I2C error.
 */
static int mlx90817_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write(reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read two bytes back */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read(reg 0x%02X): got %zd bytes, %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(g_log_fp, "timestamp,pressure_kPa\n") < 0) {
        fprintf(stderr, "fprintf(header): %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
    }
    return 0;
}

static void log_write(float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf(data): %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus and set slave address */
    g_i2c_fd = i2c_open(I2C_BUS, MLX90817_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file once */
    if (log_open(LOG_FILE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int err_count = 0;

    while (g_running) {
        uint16_t raw = 0;
        if (mlx90817_read_reg16(g_i2c_fd, PRESSURE_REG, &raw) != 0) {
            err_count++;
            if (err_count >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C read failures; "
                                "sensor may be absent or bus error.\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }
        err_count = 0;

        /*
         * Convert raw 16-bit value to kPa.
         * The MLX90817 provides a 16-bit signed value that represents
         * the pressure in kPa.  A negative value indicates an error
         * condition; treat it as 0.0 kPa so the log reflects the
         * sensor-reported value even when the sensor itself is OK.
         */
        float pressure = (int16_t)raw;   /* sign-extends for free */
        if (pressure < 0.0f) {
            pressure = 0.0f;
        }

        log_write(pressure);
        sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

