/*
 * Raspberry Pi 4 Model B — MLX90834 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX90834 VCC  -> 3.3 V (Pin 1)
 *   MLX90834 GND  -> GND   (Pin 9)
 *   MLX90834 SDA  -> I2C SDA (GPIO2 / Pin 3)
 *   MLX90834 SCL  -> I2C SCL (GPIO3 / Pin 5)
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   ADS1115 SDA   -> I2C SDA
 *   ADS1115 SCL   -> I2C SCL
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *   ADS1115 AIN0  -> MLX90834 VOUT
 *   ADS1115 AIN1  -> NTC temperature sensor (e.g. MCP9700 on AIN1)
 *   Warning LED   -> GPIO17 (Pin 11) through 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90834_monitor mlx90834_monitor.c \
 *       -lm -lrt -lpigpio -lpigpiod_if2
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config word: single-shot, AIN0/GND, 4.096 V, 128 SPS, no comparator */
#define ADS1115_CFG_PRESS   0xC183
#define ADS1115_CFG_TEMP    0xC383

#define WARNING_LED_PIN     17
#define PRESSURE_THRESHOLD  105.0f   /* kPa */
#define SAMPLE_PERIOD_US    1000000  /* 1 s */
#define MAX_RETRIES         3

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ----------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ADS1115] write_reg(0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) != 0) {
        fprintf(stderr, "[ADS1115] write_reg_addr(0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ADS1115] read_reg(0x%02X) failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-ended conversion on the given channel and read the result.
 * Returns 0 on success and stores the raw signed 16-bit value in *raw;
 * -1 on failure.
 */
static int ads1115_read_channel(int handle, uint16_t config, int16_t *raw)
{
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for the conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    uint16_t cfg;
    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) != 0)
        return -1;

    if (cfg & 0x8000) {
        /* OS bit still set — conversion not complete */
        gpioDelay(2000);
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & 0x8000) {
            fprintf(stderr, "[ADS1115] conversion timeout\n");
            return -1;
        }
    }

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &conv) != 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/* --------------------------- Sensor data --------------------------------- */

typedef struct {
    float pressure;     /* kPa */
    float temperature;  /* °C */
} sensor_data_t;

/*
 * Read pressure (AIN0) and temperature (AIN1) from the ADS1115.
 * Returns 0 on success, -1 on failure.
 */
static int read_sensor_data(int handle, sensor_data_t *data)
{
    int16_t raw_p, raw_t;

    if (ads1115_read_channel(handle, ADS1115_CFG_PRESS, &raw_p) != 0)
        return -1;

    if (ads1115_read_channel(handle, ADS1115_CFG_TEMP, &raw_t) != 0)
        return -1;

    /*
     * Placeholder conversion factors for the MLX90834.
     * Replace with datasheet-derived formulas once the exact
     * transfer function is known.
     */
    data->pressure    = (float)raw_p * 0.0001f;   /* example: raw * 0.0001 kPa */
    data->temperature = (float)raw_t * 0.001f;    /* example: raw * 0.001 °C */

    return 0;
}

/* ------------------------------ Main loop -------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Warning LED pin --- */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", WARNING_LED_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 pressure monitor started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        sensor_data_t sd;
        bool read_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_sensor_data(g_i2c_handle, &sd) == 0) {
                read_ok = true;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000);  /* 100 ms backoff */
        }

        if (read_ok) {
            printf("Pressure: %.2f kPa | Temperature: %.2f °C\n",
                   sd.pressure, sd.temperature);

            if (sd.pressure > PRESSURE_THRESHOLD) {
                gpioWrite(WARNING_LED_PIN, 1);
                printf("  >>> WARNING: pressure %.2f kPa exceeds threshold %.2f kPa\n",
                       sd.pressure, PRESSURE_THRESHOLD);
            } else {
                gpioWrite(WARNING_LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d attempts; "
                            "continuing to retry...\n", MAX_RETRIES);
            gpioWrite(WARNING_LED_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    gpioWrite(WARNING_LED_PIN, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

