/*
 * Methane Monitor — Raspberry Pi 4 Model B
 * Sensor : Honeywell MICROpeL Model 41000-020 (analog)
 * ADC    : MCP3008 on SPI bus 0, channel 0, 1 MHz, mode 0
 * Wiring : VDD/VREF -> Pi 3.3V (pin 1), DGND/AGND -> Pi GND
 *          CLK  -> GPIO11 (SCLK, BCM 11)
 *          DOUT -> GPIO9  (MISO, BCM 9)
 *          DIN  -> GPIO10 (MOSI, BCM 10)
 *          CS   -> GPIO8  (CE0,  BCM 8)
 *
 * Build  : gcc -O2 -Wall -Wextra -o methane_monitor methane_monitor.c -lm
 * Run    : ./methane_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8) of SPI bus 0 */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 200 kHz–3.2 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, MSB-first */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define THRESHOLD_PPM  1000.0f    /* alarm when concentration exceeds this */
#define LOG_FILE       "methane_log.txt"
#define SAMPLE_PERIOD  1.0        /* seconds between readings */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_spi(void);
static int  read_adc(int channel, uint16_t *out_value);
static float adc_to_ppm(uint16_t adc_value);
static void log_data(float ppm);
static void check_threshold(float ppm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI init ----------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed (channel=%d, speed=%d, flags=%d): pigpio error %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- ADC read ----------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   TX[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 *
 * Returns 0 on success (value stored in *out_value),
 *        -1 on SPI transfer failure,
 *        -2 on invalid channel number.
 */
static int read_adc(int channel, uint16_t *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d (must be 0–7)\n", channel);
        return -2;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "[ERROR] spiXfer failed: returned %d (pigpio error %d)\n",
                ret, ret);
        return -1;
    }

    *out_value = (uint16_t)(((rx[1] & 0x03) << 8) | (uint8_t)rx[2]);
    return 0;
}

/* ----------------------------- Conversion --------------------------------- */
/*
 * Placeholder linear mapping from ADC count to ppm.
 * Replace with the sensor's calibration curve once its datasheet is known.
 */
static float adc_to_ppm(uint16_t adc_value)
{
    return (float)adc_value * 0.1f;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_data(float ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[WARN] time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[WARN] localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[WARN] strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, %.2f ppm\n", ts, ppm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }
}

/* ----------------------------- Threshold check ---------------------------- */
static void check_threshold(float ppm)
{
    if (ppm > THRESHOLD_PPM) {
        fprintf(stderr, "[ALARM] Methane leak detected! Concentration: %.2f ppm\n", ppm);
    }
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (initialize_spi() != 0) {
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Methane monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t adc_value = 0;
        int rc = read_adc(ADC_CHANNEL, &adc_value);

        if (rc == 0) {
            float ppm = adc_to_ppm(adc_value);
            log_data(ppm);
            check_threshold(ppm);
        } else if (rc == -2) {
            fprintf(stderr, "[ERROR] Invalid ADC channel %d\n", ADC_CHANNEL);
        } else {
            fprintf(stderr, "[ERROR] SPI transfer failed — continuing\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

