/*
 * Raspberry Pi 4 Model B — MLX90830 Pressure Sensor Reader
 *
 * Hardware:
 *   - MLX90830 analog pressure sensor (analog output) -> ADS1115 AIN0
 *   - ADS1115 I2C address 0x48 on /dev/i2c-1 (SDA=GPIO2, SCL=GPIO3)
 *   - MLX90830 VCC = 3.3 V, GND = GND
 *
 * The MLX90830 outputs a voltage proportional to pressure.
 * ADS1115 channel AIN0 is configured for single-ended, +/-4.096 V range.
 *
 * Build:  gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bit fields */
#define ADS1115_CFG_OS_BEGIN     (1u << 15)
#define ADS1115_CFG_MUX_AIN0     (0x04 << 12)   /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V   (0x01 << 9)    /* +/-4.096 V */
#define ADS1115_CFG_MODE_SINGLE  (0x01 << 8)
#define ADS1115_CFG_DR_128SPS    (0x04 << 5)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE    (0x03 << 0)

#define LOG_FILE            "pressure_log.txt"
#define SAMPLE_INTERVAL_US  1000000          /* 1 Hz */
#define ADC_SETTLE_US       10000            /* 10 ms for 128 SPS */
#define MAX_CONSECUTIVE_ERR 20               /* abort after this many failures */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read16 write(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read16 read(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                             */
/* ------------------------------------------------------------------ */
static int ads1115_init(int fd)
{
    /*
     * Config word:
     *   OS=1, MUX=AIN0, PGA=4.096V, Mode=Single, DR=128SPS, CQUE=None
     */
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096V
                    | ADS1115_CFG_MODE_SINGLE
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) == -1) {
        fprintf(stderr, "Failed to write ADS1115 config register\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw)
{
    uint16_t val;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &val) == -1) {
        return -1;
    }
    *raw = (int16_t)val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversion                                                          */
/* ------------------------------------------------------------------ */
/*
 * MLX90830 analog output is proportional to pressure.
 * At 3.3 V supply and +/-4.096 V PGA, 16-bit signed full-scale is
 * 32767 counts = 4.096 V.  Convert raw to kPa:
 *
 *    pressure_kPa = (raw / 32767.0) * 100.0
 */
static double raw_to_kpa(int16_t raw)
{
    return ((double)raw / 32767.0) * 100.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_pressure(double pressure_kpa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f kPa\n", ts, pressure_kpa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1) {
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    if (ads1115_init(fd) == -1) {
        fprintf(stderr, "ADS1115 initialization failed — check wiring and address\n");
        goto cleanup;
    }

    printf("MLX90830 pressure logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl-C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) == -1) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "Too many consecutive ADC errors — aborting.\n");
                goto cleanup;
            }
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        consecutive_errors = 0;

        double pressure = raw_to_kpa(raw);

        if (pressure < 0.0 || pressure > 100.0) {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        } else {
            if (log_pressure(pressure) == -1) {
                fprintf(stderr, "Logging failed\n");
            } else {
                printf("Pressure: %.2f kPa\n", pressure);
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

