#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity exceeded threshold!"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    unsigned char bits = SPI_BITS;
    unsigned char mode = SPI_MODE;

    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float calculate_humidity(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) {
        return -1.0;
    }
    return (float)adc_value / 4095.0 * 100.0;
}

static float calculate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) {
        return -1.0;
    }
    return (float)adc_value / 4095.0 * 165.0 - 40.0;
}

static int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
    return 0;
}

static int send_email_alert(float humidity, float temperature) {
    FILE *fp = popen("ssmtp " EMAIL_RECIPIENT, "w");
    if (fp == NULL) {
        perror("Failed to open pipe to ssmtp");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "To: %s\n", EMAIL_RECIPIENT);
    fprintf(fp, "Subject: %s\n\n", EMAIL_SUBJECT);
    fprintf(fp, "Timestamp: %s\n", timestamp);
    fprintf(fp, "Humidity: %.2f%%\n", humidity);
    fprintf(fp, "Temperature: %.2f°C\n");
    fprintf(fp, "%s\n", EMAIL_BODY);

    int status = pclose(fp);
    if (status == -1) {
        perror("pclose failed");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    int spi_fd = -1;
    if (spi_init(&spi_fd) < 0) {
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        if (humidity < 0 || temperature < 0) {
            fprintf(stderr, "Invalid sensor data\n");
            sleep(1);
            continue;
        }

        if (log_data(humidity, temperature) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Sending email alert.\n");
            if (send_email_alert(humidity, temperature) < 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        sleep(5);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("Humidity monitoring stopped.\n");
    return 0;
}

