/*
 * TMP36 temperature logger via MCP3208 ADC on Raspberry Pi 5.
 *
 * Wiring:
 *   MCP3208 VDD  -> 3.3 V (pin 1)
 *   MCP3208 VREF -> 3.3 V (pin 1)
 *   MCP3208 AGND -> GND  (pin 6)
 *   MCP3208 DGND -> GND  (pin 6)
 *   MCP3208 CLK  -> GPIO11 (BCM 11, pin 23)
 *   MCP3208 DOUT -> GPIO9  (BCM 9,  pin 21)
 *   MCP3208 DIN  -> GPIO10 (BCM 10, pin 19)
 *   MCP3208 CS   -> GPIO8  (BCM 8,  pin 24)  [chip-select, CE0]
 *   MCP3208 CH0  -> TMP36 VOUT (pin 1)
 *   TMP36 VCC    -> 3.3 V
 *   TMP36 GND    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tmp36_logger tmp36_logger.c -lgpiod
 *
 * Run:
 *   ./tmp36_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define GPIO_CHIP_NAME  "gpiochip4"
#define CS_GPIO_LINE    8          /* BCM 8, chip-select /CS0 */

#define ADC_CHANNEL     0          /* MCP3208 CH0 */
#define ADC_MAX_VALUE   4095       /* 12-bit */
#define ADC_VREF        3.3f
#define ADC_OFFSET      0.0f

#define TMP36_MIN_C     (-40.0f)
#define TMP36_MAX_C     (125.0f)

#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * MCP3208 single-ended read (3-byte transfer, mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low nibble)
 * Result: 12-bit value in rx[1] (low 4 bits) and rx[2] (8 bits).
 */
static int mcp3208_read(int spi_fd, struct gpiod_line *cs_line,
                         uint8_t channel, uint16_t *adc_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    /* Assert CS (active low) */
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(cs, 0)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI_IOC_MESSAGE");
        gpiod_line_set_value(cs_line, 1); /* best-effort release */
        return -1;
    }

    /* Deassert CS */
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(cs, 1)");
        return -1;
    }

    *adc_value = (uint16_t)(((rx[1] & 0x0F) << 8) | rx[2]);
    return 0;
}

static float adc_to_celsius(uint16_t adc_value)
{
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
    return (voltage - ADC_OFFSET) * 100.0f;
}

static int log_temperature(FILE *fp, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
