    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (cs_line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3208-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* --- Open log file (append); write header if new --- */
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    if (!file_exists) {
        if (fprintf(log_fp, "timestamp,temperature_celsius\n") < 0) {
            perror("fprintf(header)");
            goto cleanup;
        }
        if (fflush(log_fp) != 0) {
            perror("fflush(header)");
