    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3-byte transfer, mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (don't care)
 *   rx[1] low 2 bits + rx[2] 8 bits = 10-bit result
 */
static int mcp3008_read(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int x, int y, int z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s.%09ld,%d,%d,%d\n",
            timestamp, ts.tv_nsec, x, y, z);
    fflush(g_log_file);
}

static void log_impact(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s.%09ld,IMPACT DETECTED\n",
            timestamp, ts.tv_nsec);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring ADXL335 via MCP3008 on %s at %u Hz. Press Ctrl+C to exit.\n",
           SPI_DEVICE, SPI_SPEED_HZ);

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);

    while (g_running) {
        int x = mcp3008_read(ADC_CHANNEL_X);
        int y = mcp3008_read(ADC_CHANNEL_Y);
        int z = mcp3008_read(ADC_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
        } else {
            log_data(x, y, z);

            if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
                log_impact();
            }
        }

        /* Sleep until next sample period */
        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec  += 1;
            next.tv_nsec -= 1000000000L;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec < next.tv_sec ||
            (now.tv_sec == next.tv_sec && now.tv_nsec < next.tv_nsec)) {
            struct timespec sleep_ts;
            sleep_ts.tv_sec  = next.tv_sec  - now.tv_sec;
            sleep_ts.tv_nsec = next.tv_nsec - now.tv_nsec;
            if (sleep_ts.tv_nsec < 0) {
                sleep_ts.tv_sec  -= 1;
                sleep_ts.tv_nsec += 1000000000L;
            }
            nanosleep(&sleep_ts, NULL);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

