/*
 * Raspberry Pi Zero W – Si1172 Optical Heart Rate Sensor Logger
 *
 * Reads raw IR (16-bit) and RED (16-bit) ADC samples from the Si1172
 * (Si1172-A30-GMR, I2C bus 1, address 0x60) and logs them to
 * biometric_log.csv once per second.  On I2C errors the log row
 * includes an error flag (0 = OK, 1 = I2C error, 2 = sensor absent).
 *
 * NOTE: The Si1172 is a PPG / photoplethysmography sensor; it does NOT
 * provide a proprietary algorithm for converting raw ADC samples to
 * heart-rate and SpO2.  This program logs the raw ADC values as proxy
 * placeholders for HR and SpO2 so the data file format remains
 * consistent with the task description.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1172_logger si1172_logger.c \
 *              -lpigpio -lrt
 * Run:    sudo ./si1172_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */

#define I2C_BUS              1
#define SI1172_ADDR          0x60

/* Si1172 register addresses (representative; actual registers may vary) */
#define SI1172_REG_IR_ADC    0x04
#define SI1172_REG_RED_ADC   0x06

#define LOG_FILE             "biometric_log.csv"
#define SAMPLE_PERIOD_US     1000000   /* 1 second */

/* --------------------------- Global State ---------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------- Signal Handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C Helpers ----------------------------- */

/*
 * Read a 16-bit little-endian register from the Si1172.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int si1172_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int v = i2cReadWordData(handle, reg);
    if (v < 0) {
        return -1;
    }
    /* pigpio returns data as (msb << 8) | lsb, which is little-endian. */
    *out = (uint16_t)v;
    return 0;
}

/* --------------------------- Sensor Read ----------------------------- */

/*
 * Attempt to read one sample from the Si1172.
 * Returns 0 on success and fills hr/spo2; returns -1 on I2C error.
 * Returns 2 if the sensor appears to be absent or uninitialized.
 */
static int read_sensor_data(int handle, int *hr, int *spo2)
{
    uint16_t ir_raw = 0, red_raw = 0;

    if (si1172_read_reg16(handle, SI1172_REG_IR_ADC, &ir_raw) != 0) {
        return -1;   /* transient I2C error */
    }

    if (si1172_read_reg16(handle, SI1172_REG_RED_ADC, &red_raw) != 0) {
        return -1;   /* transient I2C error */
    }

    /*
     * Placeholder heuristic: if both ADC values are 0 or 0xFFFF
     * the sensor may be absent or uninitialized.
     */
    if (ir_raw == 0 && red_raw == 0) {
        return 2;
    }

    /*
     * Raw ADC values are logged as proxy for HR and SpO2.
     * A real implementation would use the Si1172 proprietary
     * algorithm to convert PPG samples to heart-rate and SpO2.
     */
    *hr   = (int)ir_raw;
    *spo2 = (int)red_raw;
    return 0;
}

/* --------------------------- Logging --------------------------------- */

static void log_data(FILE *fp, time_t ts, int hr, int spo2, int error)
{
    fprintf(fp, "%ld,%d,%d,%d\n", (long)ts, hr, spo2, error);
    fflush(fp);
}

/* --------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to Si1172 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (create with header) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr,spo2,error\n");
        fflush(g_log_file);
    }

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM)");
    }

    printf("Si1172 logger started.  Logging to %s  (Ctrl-C to stop)\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        time_t now = time(NULL);
        int    hr  = 0;
        int    spo2 = 0;
        int    rc  = read_sensor_data(g_i2c_handle, &hr, &spo2);

        if (rc == 0) {
            log_data(g_log_file, now, hr, spo2, 0);
            printf("[%ld] HR=%d  SpO2=%d  (OK)\n", (long)now, hr, spo2);
        } else if (rc == 2) {
            log_data(g_log_file, now, 0, 0, 2);
            printf("[%ld] Sensor absent or uninitialized (error=2)\n",
                   (long)now);
        } else {
            log_data(g_log_file, now, 0, 0, 1);
            printf("[%ld] I2C read error (error=1)\n", (long)now);
        }

        /* Sleep 1 s, but wake early if a signal arrives */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

