/*
 * Raspberry Pi 4 Model B — Honeywell SpiroQuant A+ ES1-005 Flow Sensor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 / GPIO8), SPI mode 0, 1 MHz
 *   - MCP3008 CH0 connected to the sensor analog output
 *   - Sensor: Honeywell SpiroQuant A+ ES1-005 (analog output)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_sensor flow_sensor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./flow_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8)                  */
#define SPI_SPEED      1000000    /* 1 MHz                                   */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                   */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0          */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code              */
#define ADC_VREF       3.3        /* MCP3008 VDD reference                   */
#define FLOW_MIN       0.0        /* Minimum flow rate (L/min)               */
#define FLOW_MAX       5.0        /* Maximum flow rate (L/min)               */
#define SAMPLE_US      1000000    /* 1 second between samples                */
#define LOG_FILE       "flow_log.csv"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  initialize(void);
static int  read_adc(int channel, int *out_value);
static float convert_to_flow_rate(int adc_value);
static int  log_data(float flow_rate);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ---------------------------- */

static int initialize(void)
{
    /* --- pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* --- SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, flags=%d).\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return -1;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_lpm\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ----------------------------- ADC Read ---------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* ----------------------------- Conversion -------------------------------- */

/*
 * Convert 10-bit ADC code to flow rate (L/min).
 *
 * The Honeywell SpiroQuant A+ ES1-005 is an analog output sensor.
 * A 0 ADC code corresponds to 0 flow (sensor absent / open circuit),
 * and the full-scale code corresponds to the maximum flow.
 *
 * NOTE: The exact transfer function depends on the sensor's calibration
 *       and the load cell's sensitivity factor. This linear mapping is
 *       a placeholder; replace with the calibrated coefficients for your
 *       specific sensor.
 */
static float convert_to_flow_rate(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /* Linear placeholder: 0 ADC -> 0 L/min, full ADC -> FLOW_MAX L/min */
    return (float)adc_value / (float)ADC_MAX * FLOW_MAX;
}

/* ----------------------------- Logging ----------------------------------- */

