/*
 * Raspberry Pi Zero W – TDK ICP-10125 I2C environmental logger
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o env_logger env_logger.c
 * Run:    ./env_logger   (user must be in the 'i2c' group or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x63          /* ICP-10125 default 7-bit I2C address */
#define CSV_FILENAME   "environmental_data.csv"
#define SAMPLE_PERIOD  5             /* seconds between samples */

/* ICP-10125 high-precision measurement command (0x3608) */
#define CMD_MSB        0x36
#define CMD_LSB        0x08

/* Calibration coefficients (example values – replace with your calibrated ones) */
#define T0_CAL         25.0f
#define P0_CAL         1000.0f
#define T1_CAL         0.01f
#define P1_CAL         0.01f
#define T2_CAL         -0.000002f
#define P2_CAL         -0.000002f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a 16-bit command to the ICP-10125.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t buf[2] = { msb, lsb };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed: %s (wrote %zd bytes)\n",
                strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the ICP-10125.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read failed: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/*
 * Trigger a high-precision measurement and read the 6-byte result.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor(int fd, float *temperature, float *pressure)
{
    if (i2c_write_cmd(fd, CMD_MSB, CMD_LSB) != 0)
        return -1;

    /* High-precision conversion takes ~45 ms; wait 50 ms to be safe. */
    usleep(50000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* CRC bytes are the two LSBs of the last two bytes; skip them. */
    uint16_t raw_p = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_t = ((uint16_t)data[3] << 8) | data[4];

    /* ICP-10125 calibration formulas (datasheet rev 1.0) */
    float t = T0_CAL + (T1_CAL * (float)raw_t) + (T2_CAL * (float)raw_t * (float)raw_t);
    float p = P0_CAL + (P1_CAL * (float)raw_p) + (P2_CAL * (float)raw_p * (float)raw_p);

    *temperature = t;
    *pressure    = p;
    return 0;
}

static void log_data(FILE *fp, float temperature, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, pressure);
    fflush(fp);
}

int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open CSV log file in append mode */
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_c,pressure_pa\n");
        fflush(fp);
    }

    printf("ICP-10125 environmental logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, pressure;

        if (read_sensor(fd, &temperature, &pressure) == 0) {
            log_data(fp, temperature, pressure);
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n",
                   temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

