/*
 * Raspberry Pi 4 Model B — Vegetronix VH400 soil moisture logger
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0), SPI mode 0, 1 MHz max clock
 *   - Vegetronix VH400 analog output -> MCP3008 CH0
 *   - 3.3 V supply (VH400 module is 3.3 V compatible)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o moisture_logger moisture_logger.c \
 *       -lpigpio -lrt
 *
 * Run:
 *   sudo ./moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO 8)                       */
#define SPI_SPEED      1000000    /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, MSB-first         */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0          */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC                              */

#define LOG_FILE       "moisture_log.txt"
#define SAMPLE_PERIOD  60         /* seconds between readings                */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 read ------------------------------ */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX: [0x01] [SGL/DIFF | D2 D1 D0 | 0x00] [0x00]
 *   RX: [xx]     [xx xx b9 b8] [xx xx xx b7 .. b0]
 *   10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    *out_value = adc_value;
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */

static int log_moisture_data(const char *filename, int adc_value)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, adc_value) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read failed; will retry next cycle.\n");
        } else {
            if (log_moisture_data(LOG_FILE, adc_value) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("ADC=%4d  ->  %s\n", adc_value, LOG_FILE);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

