#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define BUZZER_GPIO     18
#define ADC_CHANNEL     0
#define SAMPLE_DELAY_US 500000
#define MAX_RETRIES     3
#define TEMP_FILE       "ambient_temp.txt"
#define LOG_FILE        "flame_log.txt"
#define DEFAULT_TEMP    25.0f

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) return -1;

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    if (raw < 0 || raw > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", raw);
        return -1;
    }
    *out_value = raw;
    return 0;
}

static float read_temperature(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return DEFAULT_TEMP;
    }

    char buf[64];
    if (fgets(buf, sizeof(buf), fp) == NULL) {
        fprintf(stderr, "Cannot read %s\n", TEMP_FILE);
        fclose(fp);
        return DEFAULT_TEMP;
    }
    fclose(fp);

    char *endptr = NULL;
    float temp = strtof(buf, &endptr);
    if (endptr == buf || temp < -50.0f || temp > 150.0f) {
        fprintf(stderr, "Invalid temperature in %s\n", TEMP_FILE);
        return DEFAULT_TEMP;
    }
    return temp;
}

static float voltage_compensation(int adc_value, float temperature)
{
    /*
     * Placeholder linear approximation.
     * Replace with a real temperature-compensated curve from the
     * KY-026 datasheet (e.g. V_out = a * T + b * T^2 + c * T^3).
     */
    return (float)adc_value * (1.0f + (temperature - 25.0f) * 0.01f);
