#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define LED_PIN     17
#define HIGH_THRESH 75
#define LOW_THRESH  70
#define JSON_FILE   "water_levels.json"
#define SAMPLE_US  100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_percentage(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static void control_led(float percentage) {
    if (percentage > HIGH_THRESH) {
        gpioWrite(LED_PIN, 1);
    } else if (percentage < LOW_THRESH) {
        gpioWrite(LED_PIN, 0);
    }
}

static void log_data(float percentage) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(json_fp, "  {\"timestamp\": \"%s\", \"percentage\": %.2f}\n", timestamp, percentage);
    fflush(json_fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (json_fp != NULL) {
        fprintf(json_fp, "]\n");
        fclose(json_fp);
        json_fp = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    json_fp = fopen(JSON_FILE, "w");
    if (json_fp == NULL) {
        fprintf(stderr, "Failed to open JSON file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(json_fp, "[\n");
    fflush(json_fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float percentage = calculate_percentage(adc_value);
        control_led(percentage);
        log_data(percentage);

        printf("Water Level: %.2f%%\n", percentage);

        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(SAMPLE_US);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

