/*
 * Raspberry Pi Zero W – Honeywell AWM7300V airflow sensor reader
 *
 * Hardware:
 *   MCP3008 ADC on SPI0 (CE0 = physical pin 24, SCLK = 11, MOSI = 10, MISO = 9)
 *   AWM7300V analog output -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 *   (run as root for pigpio access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 (physical pin 24) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_US      100000     /* 100 ms */
#define LOG_FILE       "airflow_log.csv"

/* AWM7300V transfer function (example calibration):
 *   0 V   -> 0.0 L/min
 *   3.3 V -> 100.0 L/min
 *   Flow (L/min) = (voltage / 3.3) * 100.0
 */
#define VREF            3.3f
#define ADC_MAX         1023       /* 10-bit ADC */
#define FLOW_MAX_LPM    100.0f

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended mode).
 * Returns 0–1023 on success, -1 on SPI error.                         */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out low 8 bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static float adc_to_flow(int adc_value)
{
    float voltage = (float)adc_value / (float)ADC_MAX * VREF;
    return (voltage / VREF) * FLOW_MAX_LPM;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float flow_rate)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int ensure_log_header(void)
{
    long pos = ftell(g_log_file);
    if (pos < 0) {
        fprintf(stderr, "ftell failed\n");
        return -1;
    }

    if (pos == 0) {
        if (fprintf(g_log_file, "Timestamp,FlowRate_LPM\n") < 0) {
            fprintf(stderr, "Failed to write CSV header\n");
            return -1;
        }
        if (fflush(g_log_file) != 0) {
            fprintf(stderr, "fflush (header) failed\n");
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file ---------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open %s for append\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_log_header() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
