#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION 300
#define DEFAULT_MAX_CALIBRATION 800
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtprc"
#define LOG_FILE "plant_data.txt"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 500000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_mcp3008(int spi_fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx_buf[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

static float calibrate_moisture(int adc_value, int min_calibration, int max_calibration) {
    if (max_calibration <= min_calibration) {
        fprintf(stderr, "Error: Invalid calibration values (min = %d, max = %d)\n", min_calibration, max_calibration);
        return -1.0f;
    }

    float moisture = 100.0f - ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration) * 100.0f);

    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;

    return moisture;
}

static int log_data(const char *timestamp, float moisture) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, moisture) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int send_email_alert(float moisture, const char *recipient, const char *msmtp_config_file) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "msmtp -C %s %s", msmtp_config_file, recipient);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: Email command too long\n");
        return -1;
    }

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "To: %s\n", recipient);
    fprintf(fp, "From: plant_monitor@raspberrypi\n");
    fprintf(fp, "Subject: Plant Moisture Alert\n\n");
    fprintf(fp, "Plant moisture is low! Current moisture: %.2f%% at %s\n", moisture, timestamp);

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_calibration = DEFAULT_MIN_CALIBRATION;
    int max_calibration = DEFAULT_MAX_CALIBRATION;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_interval = DEFAULT_LOGGING_INTERVAL;
    char *recipient = DEFAULT_EMAIL_RECIPIENT;
    char *msmtp_config_file = DEFAULT_MSMTP_CONFIG_FILE;

    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:i:r:f:h")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_calibration = atoi(optarg); break;
            case 'M': max_calibration = atoi(optarg); break;
            case 't': moisture_threshold = atoi(optarg); break;
            case 'i': logging_interval = atoi(optarg); break;
            case 'r': recipient = optarg; break;
            case 'f': msmtp_config_file = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-M max_calibration] [-t moisture_threshold] [-i logging_interval] [-r recipient] [-f msmtp_config_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (spi_channel < 0 || spi_channel > 1) {
        fprintf(stderr, "Error: SPI channel must be 0 or 1\n");
        return EXIT_FAILURE;
    }
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: ADC channel must be 0-7\n");
        return EXIT_FAILURE;
    }
    if (moisture_threshold < 0 || moisture_threshold > 100) {
        fprintf(stderr, "Error: Moisture threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (logging_interval <= 0) {
        fprintf(stderr, "Error: Logging interval must be positive\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    char spi_device[32];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", spi_channel);

    int spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device %s: %s\n", spi_device, strerror(errno));
        return EXIT_FAILURE;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Could not set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Could not set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Plant monitor started. Logging to %s every %d seconds.\n", LOG_FILE, logging_interval);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(spi_fd, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        float moisture = calibrate_moisture(adc_value, min_calibration, max_calibration);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error: Failed to calibrate moisture, retrying in %d seconds...\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        if (log_data(timestamp, moisture) != 0) {
            fprintf(stderr, "Warning: Failed to log data.\n");
        }

        printf("Moisture: %.2f%% at %s\n", moisture, timestamp);

        if (moisture < moisture_threshold) {
            printf("Alert: Moisture below threshold (%.2f%% < %d%%). Sending email...\n", moisture, moisture_threshold);
            if (send_email_alert(moisture, recipient, msmtp_config_file) != 0) {
                fprintf(stderr, "Error: Failed to send email alert.\n");
            }
        }

        for (int i = 0; i < logging_interval && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (close(spi_fd) != 0) {
        fprintf(stderr, "Error: Failed to close SPI device: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

