                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-M max_calibration] [-t moisture_threshold] [-i logging_interval] [-r recipient] [-f msmtp_config_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (spi_channel < 0 || spi_channel > 1) {
        fprintf(stderr, "Error: SPI channel must be 0 or 1\n");
        return EXIT_FAILURE;
    }
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "Error: ADC channel must be 0-7\n");
        return EXIT_FAILURE;
    }
    if (moisture_threshold < 0 || moisture_threshold > 100) {
        fprintf(stderr, "Error: Moisture threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (logging_interval <= 0) {
        fprintf(stderr, "Error: Logging interval must be positive\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    char spi_device[32];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev0.%d", spi_channel);

    int spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device %s: %s\n", spi_device, strerror(errno));
        return EXIT_FAILURE;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Could not set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Could not set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Plant monitor started. Logging to %s every %d seconds.\n", LOG_FILE, logging_interval);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(spi_fd, adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        float moisture = calibrate_moisture(adc_value, min_calibration, max_calibration);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error: Failed to calibrate moisture, retrying in %d seconds...\n", logging_interval);
            sleep(logging_interval);
            continue;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        if (log_data(timestamp, moisture) != 0) {
            fprintf(stderr, "Warning: Failed to log data.\n");
        }

        printf("Moisture: %.2f%% at %s\n", moisture, timestamp);

        if (moisture < moisture_threshold) {
            printf("Alert: Moisture below threshold (%.2f%% < %d%%). Sending email...\n", moisture, moisture_threshold);
            if (send_email_alert(moisture, recipient, msmtp_config_file) != 0) {
                fprintf(stderr, "Error: Failed to send email alert.\n");
            }
        }

        for (int i = 0; i < logging_interval && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (close(spi_fd) != 0) {
        fprintf(stderr, "Error: Failed to close SPI device: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

