        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval = DEFAULT_INTERVAL;

    if (argc > 1) {
        char *endptr = NULL;
        long v = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || v <= 0) {
            fprintf(stderr, "Invalid interval '%s'; using default %d s\n",
                    argv[1], DEFAULT_INTERVAL);
            interval = DEFAULT_INTERVAL;
        } else {
            interval = (int)v;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, interval);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = mcp3008_read(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "Warning: SPI read failed; continuing.\n");
        } else {
            float moisture = (float)adc / (float)ADC_MAX_VALUE * 100.0f;
            log_reading(adc, moisture);
            printf("ADC=%4d  Moisture=%.2f%%\n", adc, moisture);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < interval * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

