/*
 * Raspberry Pi Zero W – DFRobot Soil Moisture Sensor v2.0 via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> Soil Moisture Sensor AOUT
 *
 * Build: gcc -O2 -Wall -o soil_moisture soil_moisture.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 spec */
#define SPI_BITS        8
#define SPI_DELAY_US    0
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD_S 5

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *adc_out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }
    if (adc_out == NULL) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = sizeof(tx),
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_US,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t adc_value, float moisture_pct)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] ADC Value: %4u, Moisture: %5.1f%%\n",
           timestamp, adc_value, moisture_pct);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
