        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reader\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("ADC channel: %u\n", ADC_CHANNEL);
    printf("Sample     : every %d seconds\n", SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(g_spi_fd, ADC_CHANNEL, &adc_value) < 0) {
