/*
 * MLX90823 Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 = GPIO8, MISO = GPIO9,
 *                                 MOSI = GPIO10, SCLK = GPIO11)
 *   - MLX90823 analog output wired to MCP3008 CH0
 *   - 3.3 V supply for both the Pi and the MCP3008
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90823_reader mlx90823_reader.c \
 *       -lpigpio -lrt
 *
 * Run:
 *   sudo ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_BAUD       1000000    /* 1 MHz — well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

/*
 * MLX90823 output is typically in the range 0–3.3 V.
 * At 0 V the sensor output is disconnected (sensor absent / fault).
 * At 3.3 V the sensor output is shorted to VCC (fault / over-pressure).
 */
#define ADC_MIN_VALID  10         /* Below ~0.3 V (330 mV) — sensor absent */
#define ADC_MAX_VALID  1000       /* Above ~2.9 V (2900 mV) — over-pressure */

#define SAMPLE_PERIOD_US 1000000 /* 1 second */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal Handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------- Helpers --------------------------------- */

/*
 * Read a single-ended sample from the MCP3008.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response (10-bit result):
 *   rx[1] bits 1:0  -> bits 9:8
 *   rx[2]          -> bits 7:0
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/*
 * Convert raw ADC count to a pressure-like value (0–3.3 V).
 *
 * The MLX90823 output is a voltage proportional to the pressure.
 * At 0 V the sensor is disconnected, at 3.3 V it is shorted to VCC.
 * We map the full 10-bit range to 0–3.3 V.
 */
static float adc_to_pressure(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * 3.3f;
}

/*
 * Validate the ADC reading.
 * Returns true if the reading is within a plausible range
 * (sensor present, not shorted to VCC or disconnected).
 */
static bool validate_adc(int adc_value)
{
    if (adc_value < ADC_MIN_VALID) {
        fprintf(stderr, "ADC value %d below minimum (sensor absent or disconnected)\n",
                adc_value);
        return false;
    }
    if (adc_value > ADC_MAX_VALID) {
        fprintf(stderr, "ADC value %d above maximum (over-pressure or sensor fault)\n",
                adc_value);
        return false;
    }
    return true;
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0 @ %d Hz | ADC CH0 | Sample every 1 s\n", SPI_BAUD);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — continuing\n");
        } else if (!validate_adc(adc_value)) {
            /* Sensor-absent or fault already reported */
        } else {
            float pressure = adc_to_pressure(adc_value);

            time_t now = time(NULL);
            struct tm tm_info;
            char timestamp[32];
            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(timestamp, sizeof(timestamp),
                         "%Y-%m-%dT%H:%M:%S", &tm_info);
            } else {
                snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
            }

            printf("[%s] ADC: %4d  Pressure: %.2f V\n",
                   timestamp, adc_value, pressure);
            fflush(stdout);
        }

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (g_spi_handle >= 0)
        spiClose(g_spi_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

