 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *adc_out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0–7)\n", channel);
        return -1;
    }
    if (adc_out == NULL) {
        return -1;
    }

