    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open ---------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- CSV open ---------------------------------------------------- */
    g_csv_file = fopen(CSV_FILENAME, "a");
    if (g_csv_file == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv_file) == 0) {
        fprintf(g_csv_file, "timestamp,sensor0,sensor1,sensor2,sensor3\n");
        fflush(g_csv_file);
    }

    /* --- Signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sampling %d sensors on SPI0 CE0 every %.1f s. Press Ctrl+C to stop.\n",
           NUM_SENSORS, SAMPLE_PERIOD);

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        int values[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(i);
            if (v < 0) {
                fprintf(stderr, "Sensor %d read error — skipping sample\n", i);
                error = 1;
                break;
            }
            values[i] = v;
        }

        if (error) {
            /* Brief back-off before retrying to avoid bus spam */
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(g_csv_file, values) != 0) {
