#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_BAUD       1000000
#define SPI_FLAGS      0
#define PUMP_GPIO      17
#define MOISTURE_LOW   300
#define MOISTURE_HIGH  600
#define BUFFER_SIZE    20
#define SAMPLE_US      5000000

typedef struct {
    time_t timestamp;
    int    moisture;
    bool   pump_state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static int      spi_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                 (start bit)
     *   tx[1] = (0x08 | channel)<<4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                 (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static void control_pump(int moisture) {
    static bool pump_on = false;

    if (moisture < MOISTURE_LOW && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = true;
            printf("Pump ON  (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to set pump GPIO high\n");
        }
    } else if (moisture > MOISTURE_HIGH && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = false;
            printf("Pump OFF (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to set pump GPIO low\n");
        }
    }
}

static void log_data(int moisture, bool pump_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].timestamp  = now;
    log_buffer[buffer_index].moisture   = moisture;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    printf("[%ld] Moisture=%4d  Pump=%s\n",
           (long)now, moisture, pump_state ? "ON" : "OFF");
}

static void print_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        if (tm) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        } else {
            snprintf(ts, sizeof(ts), "?");
        }
        printf("  [%s] Moisture=%4d  Pump=%s\n",
               ts, log_buffer[idx].moisture,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("------------------------------\n");
    fflush(stdout);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring System\n");
    printf("SPI channel %d, %d baud, pump GPIO %d\n",
           SPI_CHANNEL, SPI_BAUD, PUMP_GPIO);
    printf("Low threshold=%d, High threshold=%d\n", MOISTURE_LOW, MOISTURE_HIGH);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
        } else {
            control_pump(moisture);
            log_data(moisture, gpioRead(PUMP_GPIO) == 1);
            print_buffer();
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

