/*
 * MAX30102 Pulse Oximeter Monitor for Raspberry Pi Zero W
 *
 * Reads SpO2 and heart-rate from the MAX30102 on I2C bus 1 every second
 * and logs low SpO2 (<95%) or high heart-rate (>100 BPM) to health_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o max30102_monitor max30102_monitor.c -lpigpio -lrt
 * Run:    sudo ./max30102_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MAX30102 I2C address ---- */
#define MAX30102_I2C_ADDR 0x57

/* ---- MAX30102 register addresses ---- */
#define REG_INTR_STATUS_1   0x00
#define REG_INTR_STATUS_2   0x01
#define REG_INTR_ENABLE_1   0x02
#define REG_INTR_ENABLE_2   0x03
#define REG_FIFO_WR_PTR     0x04
#define REG_OVF_COUNTER     0x05
#define REG_FIFO_RD_PTR     0x06
#define REG_FIFO_DATA       0x07
#define REG_FIFO_CONFIG     0x08
#define REG_MODE_CONFIG     0x09
#define REG_SPO2_CONFIG     0x0A
#define REG_LED1_PA         0x0C
#define REG_LED2_PA         0x0D
#define REG_PART_ID         0xFF

/* ---- Expected Part ID ---- */
#define MAX30102_PART_ID    0x15

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Prototypes ---- */
static int  max30102_init(void);
static int  max30102_read_data(float *spo2, float *heart_rate);
static void log_health_data(float spo2, float heart_rate);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/*  Signal handler                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Initialize MAX30102                                                */
/* ------------------------------------------------------------------ */
static int max30102_init(void)
{
    /* 1. Verify Part ID */
    int part_id = i2cReadByteData(g_i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: I2C read failed for Part ID register (pigpio error %d).\n", part_id);
        return -1;
