#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define VREF        3.3
#define ADC_MAX     1023
#define SAMPLE_US  500000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(FILE *fp, int channel, int adc_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    double voltage = (adc_value / (double)ADC_MAX) * VREF;
    fprintf(fp, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("analog_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Channel,Voltage\n");
    fflush(log_file);

    while (running) {
        for (int ch = 0; ch < 3; ch++) {
            int adc;
            if (read_mcp3008(ch, &adc) == 0) {
                log_data(log_file, ch, adc);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", ch);
            }
        }
        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

