/*
 * Door lock controller for Raspberry Pi 5 (64-bit Bookworm).
 *
 * Hardware:
 *   - GP2Y0A21YK0F Sharp IR distance sensor  -> ADS1115 AIN0
 *   - ADS1115 ADC on /dev/i2c-1, address 0x48
 *     SDA = GPIO2 (BCM), SCL = GPIO3 (BCM), ADDR = GND
 *   - 5 V relay module on GPIO17 (BCM), active-high
 *   - Magnetic reed switch on GPIO27 (BCM), active-low, pull-up
 *
 * Behaviour:
 *   - Calibrate baseline distance after 10 samples (50 ms apart).
 *   - Sample ADC every 200 ms.
 *   - If distance < threshold, energise relay for 3 s, log "door opened".
 *   - De-energise relay.
 *   - Read reed switch: "door opened" if LOW, "door not opened" otherwise.
 *   - Log every event with millisecond timestamp to /var/log/door_events.log.
 *   - SIGINT / SIGTERM: de-energise relay, close I2C, exit cleanly.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01

/* Config: single-shot, AIN0 vs GND, 4.096 V, 128 SPS, single-shot */
#define ADS1115_CFG_BASE 0x8000  /* OS bit */
#define ADS1115_CFG_MUX  0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA  0x0200  /* 4.096 V */
#define ADS1115_CFG_DR   0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE 0x0003  /* Disable comparator */
#define ADS1115_CFG_MODE 0x0100  /* Single-shot */
#define ADS1115_CFG_OS   0x8000  /* Write 1 to start conversion */

#define RELAY_GPIO       17
#define REED_GPIO        27
#define LOG_FILE         "/var/log/door_events.log"
#define SAMPLE_DELAY_MS  200
#define CALIB_SAMPLES    10
#define CALIB_DELAY_MS   50
#define RELAY_PULSE_MS   3000
#define THRESHOLD_MM     50

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_relay_line = NULL;
static struct gpiod_line *g_reed_line = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm;
        localtime_r(&ts.tv_sec, &tm);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    } else {
        fprintf(fp, "[unknown time]: %s\n", msg);
    }
    fclose(fp);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2];
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0,            .len = 1, .buf = wbuf },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD,     .len = 2, .buf = rbuf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "i2c_read16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

static int read_adc(int fd, uint16_t *raw)
{
    if (i2c_write16(fd, ADS1115_REG_CFG, ADS1115_CFG_BASE | ADS1115_CFG_OS) < 0)
        return -1;
    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);
    uint16_t cfg;
    if (i2c_read16(fd, ADS1115_REG_CFG, &cfg) < 0)
        return -1;
    if (!(cfg & 0x8000)) {
        fprintf(stderr, "ADS1115 conversion not complete\n");
        return -1;
    }
    if (i2c_read16(fd, ADS1115_REG_CONV, raw) < 0)
        return -1;
    return 0;
}

static int calibrate(int fd, int *threshold_mm)
{
    long sum = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        uint16_t raw;
        if (read_adc(fd, &raw) < 0) {
            fprintf(stderr, "Calibration sample %d failed\n", i);
            return -1;
        }
        /* Convert raw to signed 16-bit and scale to mm (4.096 V -> 16384 LSB/V) */
        int16_t signed_raw = (int16_t)raw;
        int val = (int)((signed_raw * 1000) / 16384);
        sum += val;
        usleep(CALIB_DELAY_MS * 1000);
    }
    *threshold_mm = sum / CALIB_SAMPLES;
    printf("Calibration complete. Threshold: %d mm\n", *threshold_mm);
    return 0;
}

static void cleanup(void)
{
    if (g_relay_line) {
        gpiod_line_set_value(g_relay_line, 0);
        gpiod_line_release(g_relay_line);
        g_relay_line = NULL;
    }
    if (g_reed_line) {
        gpiod_line_release(g_reed_line);
        g_reed_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_relay_line = gpiod_chip_get_line(g_chip, RELAY_GPIO);
    if (!g_relay_line) {
        fprintf(stderr, "gpiod get relay line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_relay_line, "door_lock", 0) < 0) {
        fprintf(stderr, "gpiod request relay output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_reed_line = gpiod_chip_get_line(g_chip, REED_GPIO);
    if (!g_reed_line) {
        fprintf(stderr, "gpiod get reed line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(g_reed_line, "door_lock",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "gpiod request reed input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int threshold_mm = 0;
    if (calibrate(g_i2c_fd, &threshold_mm) < 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold %d mm)...\n", threshold_mm);

    while (g_running) {
        uint16_t raw;
        if (read_adc(g_i2c_fd, &raw) < 0) {
            log_event("I2C read error");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        int distance_mm = (int)((raw * 1000) / 16384);
        printf("Distance: %d mm\n", distance_mm);

        if (distance_mm < threshold_mm) {
            printf("Below threshold — releasing lock\n");
            log_event("Door lock released");

            if (gpiod_line_set_value(g_relay_line, 1) < 0) {
                fprintf(stderr, "Relay on: %s\n", strerror(errno));
                log_event("Relay activation failed");
            }

            int reed_state = gpiod_line_get_value(g_reed_line);
            if (reed_state < 0) {
                fprintf(stderr, "Reed read: %s\n", strerror(errno));
                log_event("Reed sensor read failed");
            } else if (reed_state == 0) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }

            usleep(RELAY_PULSE_MS * 1000);

            if (gpiod_line_set_value(g_relay_line, 0) < 0) {
                fprintf(stderr, "Relay off: %s\n", strerror(errno));
                log_event("Relay deactivation failed");
            }
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

