/*
 * irrigation.c — Raspberry Pi 4 Model B
 *
 * Reads a Vegetronix VH400 soil-moisture sensor via an MCP3008 ADC on SPI0
 * (CE0 / GPIO 8, 1 MHz, mode 0), compares the reading to a configurable
 * threshold, and activates a relay-driven water pump on GPIO 18 for a
 * configurable duration when the moisture level falls below the threshold.
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 * Run:    sudo ./irrigation [-t threshold] [-d pump_duration] [-s sleep_interval]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO 8)            */
#define SPI_SPEED      1000000    /* 1 MHz                                   */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                   */
#define PUMP_GPIO      18         /* BCM 18 — relay/transistor control       */
#define DEFAULT_THRESHOLD 30.0f   /* % of 0–3 V range                        */
#define DEFAULT_PUMP_DURATION 10  /* seconds                                 */
#define DEFAULT_SLEEP_INTERVAL 60 /* seconds                                 */
#define MAX_RETRIES    3
#define ADC_MAX        1023       /* 10-bit ADC                              */
#define ADC_VREF       3.3f       /* MCP3008 VDD/VREF                         */
#define LOG_FILE       "irrigation.log"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* SPI                                                                */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel requested");
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        int ret = spiXfer(g_spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return adc_value;
        }
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "SPI transfer failed (attempt %d/%d, ret=%d)",
                 attempt, MAX_RETRIES, ret);
        log_event(msg);
        gpioDelay(100000); /* 100 ms back-off */
    }

    log_event("SPI transfer failed after all retries");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Moisture                                                           */
/* ------------------------------------------------------------------ */
static float calculate_moisture_level(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Pump                                                               */
/* ------------------------------------------------------------------ */
static void pump_on(void)
{
    if (gpioWrite(PUMP_GPIO, 1) < 0) {
        log_event("Failed to set pump GPIO HIGH");
        return;
    }
    log_event("Pump activated");
}

static void pump_off(void)
{
    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        log_event("Failed to set pump GPIO LOW");
        return;
    }
    log_event("Pump deactivated");
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    pump_off();
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;
    int   pump_duration = DEFAULT_PUMP_DURATION;
    int   sleep_interval = DEFAULT_SLEEP_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:h")) != -1) {
        switch (opt) {
        case 't':
            threshold = atof(optarg);
            if (threshold < 0.0f || threshold > 100.0f) {
                fprintf(stderr, "Threshold must be 0–100\n");
                return EXIT_FAILURE;
            }
            break;
        case 'd':
            pump_duration = atoi(optarg);
            if (pump_duration <= 0) {
                fprintf(stderr, "Pump duration must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 's':
            sleep_interval = atoi(optarg);
            if (sleep_interval <= 0) {
                fprintf(stderr, "Sleep interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    pump_off();

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char msg[160];
    snprintf(msg, sizeof(msg),
             "Program started — threshold=%.1f%%, pump=%ds, sleep=%ds",
             threshold, pump_duration, sleep_interval);
    log_event(msg);

    /* Main loop */
    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Skipping irrigation cycle due to SPI read failure");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }

        float moisture = calculate_moisture_level(adc_value);

        char log_msg[160];
        snprintf(log_msg, sizeof(log_msg),
                 "Moisture level: %.2f%% (ADC=%d)", moisture, adc_value);
        log_event(log_msg);

        if (moisture < threshold) {
