/*
 * PCF8591 ADC monitor on Raspberry Pi (I2C bus 1, address 0x48).
 * Reads AIN0 every 100 ms and prints the 8-bit value.
 *
 * Wiring:
 *   PCF8591 SDA  -> GPIO2 (pin 3, I2C1 SDA)
 *   PCF8591 SCL  -> GPIO3 (pin 5, I2C1 SCL)
 *   PCF8591 VDD  -> 3.3 V
 *   PCF8591 GND  -> GND
 *   PCF8591 A0   -> GND  (AIN0 selected)
 *
 * Build:  gcc -O2 -Wall -Wextra -o pcf8591_mon pcf8591_mon.c
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define SAMPLE_MS      100

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_sigint(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_sigint() != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * The PCF8591 returns the result of the *previous* conversion when
     * the master performs a read.  A dummy read is needed to discard
     * that stale value so the first real sample is fresh.
     */
    uint8_t dummy;
    ssize_t n = read(fd, &dummy, 1);
    if (n < 0) {
        fprintf(stderr, "Initial read failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (n == 0) {
        fprintf(stderr, "Initial read: unexpected EOF (0 bytes)\n");
        goto cleanup;
    }

    while (!g_stop) {
        uint8_t value;
        n = read(fd, &value, 1);
        if (n < 0) {
            fprintf(stderr, "read() failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (n == 0) {
            fprintf(stderr, "read(): unexpected EOF (0 bytes)\n");
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)value);
        fflush(stdout);

        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        if (close(fd) < 0) {
            fprintf(stderr, "close() failed: %s\n", strerror(errno));
            rc = EXIT_FAILURE;
        }
    }
    return rc;
}

