#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

#define ADS1115_CONFIG_OS_BEGIN   (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0  (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096 (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128    (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

#define GPIO_MOTOR_SHUTDOWN 27
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define VREF 3.3
#define ADC_MAX 32767.0
#define PGA_GAIN 4.096
#define GAUSS_PER_VOLT (THRESHOLD_GAUSS / (VREF / PGA_GAIN))

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    double buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

