/*
 * Raspberry Pi Zero W — VH400 soil moisture monitor with MCP3008 ADC
 * and relay-driven water pump control.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> VH400 analog out
 *   Relay IN     -> GPIO18 (BCM)
 *   Relay VCC    -> 5 V (external supply recommended)
 *   Relay GND    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz                                  */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                  */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0         */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC                             */

#define MOISTURE_THRESHOLD 300    /* VH400 dry threshold (10-bit)           */
#define PUMP_GPIO       18        /* BCM 18 — relay IN                      */
#define PUMP_DURATION_S  10       /* seconds                                */
#define SAMPLE_INTERVAL_S 60     /* seconds between readings               */
#define LOG_FILE        "watering_events.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static int  read_adc(int channel, int *out_value);
static int  control_pump(int state);
static int  log_event(int moisture_level);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- ADC read -------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   TX[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d (must be 0–7)\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ------------------------------- Pump control ----------------------------- */

static int control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to %s pump on GPIO%d\n",
                state ? "activate" : "deactivate", PUMP_GPIO);
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging ---------------------------------- */

static int log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d — Moisture: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* Ensure pump is off before releasing resources. */
    if (g_spi_handle >= 0) {
        (void)control_pump(0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ----------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise pump GPIO%d LOW\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("VH400 watering controller started. Sampling every %d s.\n",
           SAMPLE_INTERVAL_S);
    printf("Threshold: %d (10-bit), pump on GPIO%d for %d s.\n",
           MOISTURE_THRESHOLD, PUMP_GPIO, PUMP_DURATION_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int moisture_level = 0;

        if (read_adc(ADC_CHANNEL, &moisture_level) != 0) {
            fprintf(stderr, "ADC read failed — skipping cycle\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (moisture_level < 0 || moisture_level > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value %d out of range — skipping\n",
                    moisture_level);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        printf("Moisture level: %d (threshold %d)\n",
               moisture_level, MOISTURE_THRESHOLD);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Below threshold — activating pump for %d s...\n",
                   PUMP_DURATION_S);

            if (control_pump(1) != 0) {
                fprintf(stderr, "Pump activation failed — aborting cycle\n");
                sleep(SAMPLE_INTERVAL_S);
                continue;
            }

            /*
             * Sleep in 1-second increments so we can respond to signals
             * promptly even if PUMP_DURATION_S is large.
             */
            for (int i = 0; i < PUMP_DURATION_S && g_running; i++) {
                sleep(1);
            }

            if (control_pump(0) != 0) {
                fprintf(stderr, "Pump deactivation failed\n");
            }

            if (log_event(moisture_level) != 0) {
                fprintf(stderr, "Failed to log watering event\n");
            }
        }

        /* Sleep in 1-second increments for responsive shutdown. */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

