    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("VH400 watering controller started. Sampling every %d s.\n",
           SAMPLE_INTERVAL_S);
    printf("Threshold: %d (10-bit), pump on GPIO%d for %d s.\n",
           MOISTURE_THRESHOLD, PUMP_GPIO, PUMP_DURATION_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int moisture_level = 0;

        if (read_adc(ADC_CHANNEL, &moisture_level) != 0) {
            fprintf(stderr, "ADC read failed — skipping cycle\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (moisture_level < 0 || moisture_level > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value %d out of range — skipping\n",
                    moisture_level);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        printf("Moisture level: %d (threshold %d)\n",
               moisture_level, MOISTURE_THRESHOLD);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Below threshold — activating pump for %d s...\n",
                   PUMP_DURATION_S);

            if (control_pump(1) != 0) {
                fprintf(stderr, "Pump activation failed — aborting cycle\n");
                sleep(SAMPLE_INTERVAL_S);
                continue;
            }

            /*
             * Sleep in 1-second increments so we can respond to signals
             * promptly even if PUMP_DURATION_S is large.
             */
            for (int i = 0; i < PUMP_DURATION_S && g_running; i++) {
                sleep(1);
            }

            if (control_pump(0) != 0) {
                fprintf(stderr, "Pump deactivation failed\n");
            }

            if (log_event(moisture_level) != 0) {
                fprintf(stderr, "Failed to log watering event\n");
            }
        }

        /* Sleep in 1-second increments for responsive shutdown. */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

