/*
 * Rain sensor reader using MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   YL-83 AOUT   -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rain_sensor rain_sensor.c -lpigpio -lrt
 * Run:
 *   sudo ./rain_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)  */
#define SPI_BAUD       1000000    /* 1 MHz              */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 CH0        */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC full-scale */

#define SAMPLE_PERIOD_US 1000000 /* 1 second           */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  initialize_spi(void);
static int  read_adc(int channel, int *out_value);
static float calculate_rainfall_intensity(int adc_value);
static void log_data(int adc_value, float intensity);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI setup ---------------------------------- */

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, baud=%d): %s\n",
                SPI_CHANNEL, SPI_BAUD, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- MCP3008 read ------------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   TX[2] = 0x00                       (clock out remaining bits)
 *   RX[1] bits 1..0 + RX[2] bits 7..0  -> 10-bit result
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d: %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *out_value = adc_value;
    return 0;
}

/* ----------------------------- Rainfall intensity -------------------------- */

static float calculate_rainfall_intensity(int adc_value)
{
    /*
     * YL-83 analog output is non-linear: higher voltage = more rain.
     * Map 0..1023 to 0.0..1.0.
     * A 10k-ohm resistor divider on the YL-83 output yields:
     *   Vout = Vref * (Rsense / (Rsense + Rload))
     * For Rsense = 10 kOhm, Rload = 10 kOhm the output is at 1/2 Vref.
     * We normalize to 0..1.0.
     */
    return (float)adc_value / (float)ADC_MAX_VALUE;
}

/* ----------------------------- Data logging ------------------------------- */

static void log_data(int adc_value, float intensity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - ADC: %4d  Intensity: %.4f\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
        } else {
            float intensity = calculate_rainfall_intensity(adc_value);
            log_data(adc_value, intensity);
        }

        /* Sleep for the remainder of the 1-second period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

