/*
 * Raspberry Pi MCP3008 PWM motor control via SPI0 CE0.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pi pin 1)
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pi pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pi pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pi pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pi pin 24)
 *   MCP3008 CH0  -> potentiometer wiper
 *   Motor PWM    -> GPIO18 (Pi pin 12) via NPN transistor/driver
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_pwm motor_pwm.c -lpigpio -lrt
 * Run:
 *   sudo ./motor_pwm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define MOTOR_PWM_PIN  18         /* BCM 18 */
#define PWM_FREQUENCY  1000       /* Hz */
#define PWM_RANGE      1024       /* duty 0..1023 */

#define ADC_CHANNEL    0          /* MCP3008 single-ended CH0 */
#define SAMPLE_US      100000     /* 100 ms between samples */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0..1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", MOTOR_PWM_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    /* Start with motor off */
    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        fprintf(stderr, "gpioPWM initial off failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 PWM motor control started (SPI0 CE0, CH0, PWM on GPIO18).\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* Transient SPI error: keep motor at current duty, retry next cycle */
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map 0..1023 ADC to 0..1023 PWM duty cycle */
        int pwm_value = adc_value;
        if (gpioPWM(MOTOR_PWM_PIN, pwm_value) != 0) {
            fprintf(stderr, "gpioPWM set failed\n");
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, pwm_value);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(MOTOR_PWM_PIN, 0);   /* motor off */
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

