        fprintf(stderr, "gpioSetPWMrange failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    /* Start with motor off */
    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        fprintf(stderr, "gpioPWM initial off failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 PWM motor control started (SPI0 CE0, CH0, PWM on GPIO18).\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* Transient SPI error: keep motor at current duty, retry next cycle */
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map 0..1023 ADC to 0..1023 PWM duty cycle */
        int pwm_value = adc_value;
        if (gpioPWM(MOTOR_PWM_PIN, pwm_value) != 0) {
            fprintf(stderr, "gpioPWM set failed\n");
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, pwm_value);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(MOTOR_PWM_PIN, 0);   /* motor off */
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

