/*
 * SS49E Hall-effect sensor monitor via ADS1115 ADC on Raspberry Pi 4.
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2 (I2C bus 1)
 *   ADS1115 SCL -> GPIO3 (I2C bus 1)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 AIN0 -> SS49E VOUT
 *   LED anode   -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build: gcc -O2 -Wall -o hall_monitor hall_monitor.c -lpigpio -lrt
 * Run:   sudo ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS             1
#define ADS1115_ADDR        0x48          /* ADDR pin tied to GND */

/* ADS1115 register addresses */
#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   [15]    OS           = 1  (begin single conversion)
 *   [14:12] MUX          = 100 (AIN0 single-ended, Gnd)
 *   [11:9]  PGA          = 001 (4.096 V)
 *   [8]     MODE         = 0  (continuous)
 *   [7:5]   DR           = 100 (128 SPS)
 *   [4]     COMP_MODE    = 0
 *   [3]     COMP_POL     = 0
 *   [2]     COMP_LAT     = 0
 *   [1:0]   COMP_QUE     = 11 (disable comparator)
 * => 0xC383
 */
#define ADS1115_CONFIG_BASE 0xC383

#define LED_GPIO            17
#define SAMPLE_PERIOD_US    100000       /* 100 ms */
#define BLINK_DURATION_US   1000000      /* 1 s total blink */
#define BLINK_HALF_US       50000        /* 50 ms on / 50 ms off */

#define DEFAULT_THRESHOLD   100.0        /* Gauss */
#define ADC_MAX_COUNT       32767.0      /* 16-bit signed, PGA 4.096 V */
#define ADC_VREF            4.096        /* volts */
#define GAUSS_PER_VOLT      0.0000000005 /* 1 Gauss per 200 mV */

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  ads1115_init(void);
static int  ads1115_read_voltage(double *voltage_out);
static double calculate_magnetic_field(double voltage);
static void blink_led(void);
static void cleanup(void);

/* ------------------------------ main ----------------------------------- */

int main(int argc, char *argv[])
{
    double threshold = DEFAULT_THRESHOLD;

    /* Parse optional threshold argument */
    if (argc > 1) {
        char *endptr = NULL;
        threshold = strtod(argv[1], &endptr);
        if (endptr == argv[1] || *endptr != '\0') {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Initialize ADS1115 */
    if (ads1115_init() != 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SS49E via ADS1115 (I2C 0x%02X). Threshold: %.2f Gauss\n",
           ADS1115_ADDR, threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        double voltage = 0.0;
        if (ads1115_read_voltage(&voltage) != 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double field = calculate_magnetic_field(voltage);
        printf("Magnetic Field: %.2f Gauss (V: %.4f)\n", field, voltage);

        if (field > threshold) {
            printf("Threshold exceeded — blinking LED for 1 s\n");
            blink_led();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 helpers ---------------------------- */

static int ads1115_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        return -1;
    }

    /* Write config register (big-endian on the bus) */
    uint16_t config = ADS1115_CONFIG_BASE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write ADS1115 config register\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/*
 * Read the raw 16-bit conversion result from the ADS1115.
 * Returns 0 on success and stores the voltage in *voltage_out.
 */
static int ads1115_read_voltage(double *voltage_out)
{
    char reg = ADS1115_REG_CONV;
    char data[2] = {0, 0};

    if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "I2C write (pointer) failed\n");
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) |
                            (uint8_t)data[1]);
    *voltage_out = (raw / ADC_MAX_COUNT) * ADC_VREF;
    return 0;
}

/* --------------------- Magnetic field calculation ----------------------- */

static double calculate_magnetic_field(double voltage)
{
    return voltage * GAUSS_PER_VOLT;
}

/* ----------------------------- LED blink -------------------------------- */

static void blink_led(void)
{
    uint32_t start = gpioTick();
    while (g_running && (gpioTick() - start) < BLINK_DURATION_US) {
        gpioWrite(LED_GPIO, 1);
        gpioDelay(BLINK_HALF_US);
        gpioWrite(LED_GPIO, 0);
        gpioDelay(BLINK_HALF_US);
    }
    gpioWrite(LED_GPIO, 0);
}

/* ----------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

