/*
 * Soil Moisture Monitoring System (Raspberry Pi 4 Model B)
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 / GPIO8, SCLK / GPIO11, MOSI / GPIO10, MISO / GPIO9)
 *   - HL-69 analog soil moisture sensor on MCP3008 CH0
 *   - Relay on GPIO17 (active-high)
 *
 * Behaviour:
 *   - Reads moisture every 60 s and publishes to "soil_moisture"
 *   - Subscribes to "pump_control" and acts on "pump_on"/"pump_off"
 *   - Hysteresis: pump ON below 30 %; pump OFF above 35 %
 *   - Sensor-absent / bus-error safe: logs and skips cycles
 *   - Clean shutdown on SIGINT/SIGTERM
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c \
 *       -lmosquitto -lpthread -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <mosquitto.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0

#define MCP3008_CHANNEL   0          /* HL-69 on CH0 */
#define ADC_MAX           1023       /* 10-bit ADC */

#define PUMP_GPIO         17         /* BCM 17 */

#define MOISTURE_THRESHOLD_LOW  30   /* % — pump ON below this */
#define MOISTURE_THRESHOLD_HIGH 35   /* % — pump OFF above this */

#define MQTT_HOST         "localhost"
#define MQTT_PORT         1883
#define MQTT_TOPIC_PUMP   "pump_control"
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_CLIENT_ID    "soil_monitor"
#define MQTT_KEEPALIVE    60

#define SAMPLE_INTERVAL_S 60

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static struct mosquitto *g_mosq = NULL;
static pthread_mutex_t g_state_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_init(void);
static int  mcp3008_read(int channel, int *out_value);
static int  pump_set(int state);
static int  moisture_read(int *out_percent);
static void pump_control(int moisture_percent);
static void on_connect(struct mosquitto *mosq, void *userdata, int result);
static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message);
static void on_subscribe(struct mosquitto *mosq, void *userdata,
                          int mid, int qos_count, const int *granted_qos);
static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI --------------------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        syslog(LOG_ERR, "open(%s): %s", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "SPI_IOC_WR_MODE: %s", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        syslog(LOG_ERR, "SPI_IOC_WR_BITS_PER_WORD: %s", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "SPI_IOC_WR_MAX_SPEED_HZ: %s", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    syslog(LOG_INFO, "SPI initialised: %s @ %u Hz, mode %u, %u bpw",
           SPI_DEVICE, speed, mode, bits);
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] low 2 bits + rx[2] 8 bits -> 10-bit result
 */
static int mcp3008_read(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "mcp3008_read: invalid channel %d", channel);
        return -1;
    }
    if (g_spi_fd < 0) {
        syslog(LOG_ERR, "mcp3008_read: SPI not initialised");
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "SPI_IOC_MESSAGE: %s", strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    if (raw < 0 || raw > ADC_MAX) {
        syslog(LOG_ERR, "mcp3008_read: out-of-range raw=%d", raw);
        return -1;
    }

    *out_value = raw;
    return 0;
}

/* ----------------------------- Pump -------------------------------------- */
static int pump_set(int state)
{
    int rc = gpioWrite(PUMP_GPIO, state ? 1 : 0);
    if (rc != 0) {
        syslog(LOG_ERR, "gpioWrite(PUMP_GPIO=%d, %d): rc=%d",
               PUMP_GPIO, state, rc);
        return -1;
    }
    syslog(LOG_INFO, "Pump set to %s", state ? "ON" : "OFF");
    return 0;
}

/* ----------------------------- Moisture ---------------------------------- */
static int moisture_read(int *out_percent)
{
    int raw;
    if (mcp3008_read(MCP3008_CHANNEL, &raw) != 0) {
        syslog(LOG_ERR, "moisture_read: ADC read failed");
        return -1;
    }

    int pct = (raw * 100) / ADC_MAX;
    if (pct < 0 || pct > 100) {
        syslog(LOG_ERR, "moisture_read: out-of-range reading %d (raw=%d)",
               pct, raw);
        return -1;
    }

    *out_percent = pct;
    return 0;
}

static void pump_control(int moisture_percent)
{
    pthread_mutex_lock(&g_state_mutex);

    if (moisture_percent < MOISTURE_THRESHOLD_LOW) {
        if (pump_set(1) == 0) {
            syslog(LOG_INFO, "Moisture %d%% < %d%% — pump ON",
                   moisture_percent, MOISTURE_THRESHOLD_LOW);
        }
    } else if (moisture_percent > MOISTURE_THRESHOLD_HIGH) {
        if (pump_set(0) == 0) {
            syslog(LOG_INFO, "Moisture %d%% > %d%% — pump OFF",
                   moisture_percent, MOISTURE_THRESHOLD_HIGH);
        }
    }

    pthread_mutex_unlock(&g_state_mutex);
}

/* ----------------------------- MQTT -------------------------------------- */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "subscribe(%s): rc=%d", MQTT_TOPIC_PUMP, rc);
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC_PUMP);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s",
               mosquitto_strerror(result));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq; (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_WARNING, "MQTT message on %s with no payload",
               message->topic);
        return;
    }

    char payload[256];
    int len = message->payloadlen < (int)sizeof(payload) - 1
              ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "MQTT message on %s: %s", message->topic, payload);

    if (strcmp(message->topic, MQTT_TOPIC_PUMP) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            pump_set(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            pump_set(0);
        } else {
            syslog(LOG_WARNING, "Unknown pump command: %s", payload);
        }
    }
}

static void on_subscribe(struct mosquitto *mosq, void *userdata,
                          int mid, int qos_count, const int *granted_qos)
{
    (void)userdata;
    if (mid > 0) {
        syslog(LOG_INFO, "Subscribe acknowledged: mid=%d, qos=%d",
               mid, granted_qos ? *granted_qos : -1);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq; (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected: %s",
           rc == MOSQ_ERR_SUCCESS ? "clean" : mosquitto_strerror(rc));
}

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    syslog(LOG_INFO, "Cleaning up...");

    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    pump_set(0);

    pthread_mutex_destroy(&g_state_mutex);
    closelog();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
