/*
 * MCP3008 channel 0 reader for Raspberry Pi (SPI0/CE0).
 *
 * Wiring (Raspberry Pi 40-pin header):
 *   MCP3008 CLK  -> GPIO11 (SPI0_SCLK,  BCM 11)
 *   MCP3008 DOUT -> GPIO9  (SPI0_MISO, BCM 9)
 *   MCP3008 DIN  -> GPIO10 (SPI0_MOSI, BCM 10)
 *   MCP3008 CS   -> GPIO8  (SPI0_CE0,  BCM 8)
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mcp3008_ch0 mcp3008_ch0.c
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define VREF            3.3f
#define ADC_MAX         1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out_raw)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
