#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define VREF        3.3
#define CSV_FILE    "sensor_data.csv"
#define SAMPLE_US   5000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

static int log_data(const char *filename, double v0, double v1, double v2) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, v0, v1, v2) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc0 = read_mcp3008(spi_handle, 0);
        int adc1 = read_mcp3008(spi_handle, 1);
        int adc2 = read_mcp3008(spi_handle, 2);

        if (adc0 < 0 || adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error reading MCP3008 channels\n");
            break;
        }

        double v0 = adc_to_voltage(adc0);
        double v1 = adc_to_voltage(adc1);
        double v2 = adc_to_voltage(adc2);

        if (log_data(CSV_FILE, v0, v1, v2) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        printf("Logged: V0=%.3f V, V1=%.3f V, V2=%.3f V\n", v0, v1, v2);

        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }

    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

