#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define MOTOR_GPIO_1    17
#define MOTOR_GPIO_2    27
#define PWM_FREQUENCY   100
#define PWM_RANGE       1000

#define THRESHOLD       500
#define SAMPLE_DELAY_US 10000
#define LOG_FILE        "vibration_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void motor_off(int gpio)
{
    gpioPWM(gpio, 0);
}

static void motor_on(int gpio, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(gpio, duty);
}

static void log_event(int noise_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Noise level: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, noise_level);
    } else {
        fprintf(fp, "(unknown time) - Noise level: %d\n", noise_level);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static void cleanup(void)
{
    motor_off(MOTOR_GPIO_1);
    motor_off(MOTOR_GPIO_2);

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_GPIO_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode\n", MOTOR_GPIO_1);
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_GPIO_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode\n", MOTOR_GPIO_2);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR_GPIO_1, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", MOTOR_GPIO_1);
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_GPIO_2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", MOTOR_GPIO_2);
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_GPIO_1, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", MOTOR_GPIO_1);
        cleanup();
        return 1;
    }
    if (gpioSetPWMrange(MOTOR_GPIO_2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", MOTOR_GPIO_2);
        cleanup();
        return 1;
    }

    motor_off(MOTOR_GPIO_1);
    motor_off(MOTOR_GPIO_2);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int noise_level = read_adc(0);
        if (noise_level < 0) {
            fprintf(stderr, "ADC read error, skipping iteration\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (noise_level > THRESHOLD) {
            int duty = (noise_level * PWM_RANGE) / 1023;
            motor_on(MOTOR_GPIO_1, duty);
            motor_on(MOTOR_GPIO_2, duty);
            log_event(noise_level);
        } else {
            motor_off(MOTOR_GPIO_1);
            motor_off(MOTOR_GPIO_2);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

