/*
 * tamper_log.c — Raspberry Pi 5
 *
 * Logs sound (MAX9814 via MCP3008 ADC on SPI0 CE0) and light (BH1750 on I2C /dev/i2c-1)
 * to tamper_log.csv every 5 seconds.  Handles SIGINT/SIGTERM cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tamper_log tamper_log.c
 *
 * Wiring:
 *   MAX9814 OUT  -> MCP3008 CH0
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   BH1750 SDA   -> GPIO2  (I2C1 SDA)
 *   BH1750 SCL   -> GPIO3  (I2C1 SCL)
 *   BH1750 VCC   -> 3.3 V
 *   BH1750 GND   -> GND
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_DEV        "/dev/i2c-1"
#define SPI_DEV        "/dev/spidev0.0"
#define BH1750_ADDR    0x23
#define BH1750_CMD_PWR 0x10
#define BH1750_CMD_RES 0x18
#define BH1750_CONV_MS 180
#define LOG_FILE       "tamper_log.csv"
#define SAMPLE_MS     5000

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int install_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    return 0;
}

/* ---------- BH1750 ---------- */

static int bh1750_write(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int bh1750_read(int fd, uint16_t *raw)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int bh1750_read_lux(int fd, float *lux)
{
    if (bh1750_write(fd, BH1750_CMD_PWR) < 0) return -1;
    if (bh1750_write(fd, BH1750_CMD_RES) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);

    uint16_t raw;
    if (bh1750_read(fd, &raw) < 0) return -1;
    *lux = (float)raw / 1.2f;
    return 0;
}

/* ---------- MCP3008 ---------- */

static int mcp3008_read(int fd, uint8_t ch, uint16_t *raw)
{
    if (ch > 7) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((ch & 0x07) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;

    *raw = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_db(uint16_t raw)
{
    if (raw == 0) return -90.0f;
    float v = (float)raw / 1023.0f * 3.3f;
    return 20.0f * log10f(v / 0.001f);
}

/* ---------- CSV ---------- */

static int log_open(FILE **fp)
{
    FILE *f = fopen(LOG_FILE, "a");
    if (!f) return -1;
    if (ftell(f) == 0)
        fprintf(f, "timestamp,sound_level_db,light_level_lux,error_code\n");
    *fp = f;
    return 0;
}

static void log_line(FILE *fp, float sl, float ll, int ec)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sl, ll, ec);
    fflush(fp);
}

/* ---------- main ---------- */

int main(void)
{
    if (install_signals() < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEV);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("open " SPI_DEV);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI config");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *csv = NULL;
    if (log_open(&csv) < 0) {
        perror("fopen " LOG_FILE);
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!g_stop) {
        uint16_t adc = 0;
        int ec = 0;

        if (mcp3008_read(spi_fd, 0, &adc) < 0) {
            ec = 1;
            adc = 0;
        }

        float sl = adc_to_db(adc);

        float ll = 0.0f;
        if (bh1750_read_lux(i2c_fd, &ll) < 0) {
            ec = 2;
            ll = 0.0f;
        }

        log_line(csv, sl, ll, ec);
        printf("sound: %.2f dB, light: %.2f lux, ec: %d\n", sl, ll, ec);

        for (int i = 0; i < SAMPLE_MS / 100 && !g_stop; i++)
            usleep(100000);
    }

    if (csv) fclose(csv);
    close(spi_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

