code:
/*
 * Raspberry Pi 4 Model B — MCP3008 soil-moisture monitor with relay-driven pump.
 *
 * Hardware:
 *   - Vegetronix VH400 analog output  -> MCP3008 CH0
 *   - MCP3008 SPI                    -> SPI0 CE0 (GPIO 8), SCLK (GPIO 11),
 *                                       MOSI (GPIO 10), MISO (GPIO 9)
 *   - Relay module                   -> BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on SPI0                              */
#define SPI_SPEED      1000000    /* 1 MHz                                    */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                    */

#define MCP3008_CHANNEL 0         /* VH400 on CH0                             */
#define ADC_MAX         1023       /* 10-bit ADC                              */
#define ADC_VREF        3.3f       /* VREF = 3.3 V                             */

#define PUMP_GPIO       17         /* BCM GPIO 17 — relay control             */
#define MOISTURE_THRESHOLD 30      /* %                                       */
#define SAMPLE_INTERVAL_S 60       /* seconds between readings                */
#define MAX_SPI_RETRIES 3          /* retries per read                         */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static float adc_to_moisture(int adc_value);
static void control_pump(bool activate);
static void log_data(float moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MCP3008 ---------------------------------- */
/*
 * Read a single-ended sample from the MCP3008.
 *
 * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
 *   tx[0] = 0x01                       Start bit
 *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1 (single) + channel, upper nibble
 *   tx[2] = 0x00                       Don't-care (clocks out low 2 bits)
 *
 *   rx[1] bits 1..0  -> high 2 bits of result
 *   rx[2]          -> low 8 bits of result
 *
 * Returns 0 on success (value stored in *out_value), -1 on failure.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        int ret = spiXfer(g_spi_handle, tx, rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
            *out_value = adc;
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt, MAX_SPI_RETRIES, ret);
        if (attempt < MAX_SPI_RETRIES) {
            gpioDelay(100000); /* 100 ms back-off */
        }
    }
    return -1;
}

/* Convert 10-bit ADC value to moisture percentage (0–100 %). */
static float adc_to_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;
