    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    printf("[%s] Moisture: %.2f%%  Pump: %s\n",
           ts, moisture_level,
           moisture_level < MOISTURE_THRESHOLD ? "ON" : "OFF");
    fflush(stdout);
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
