#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define RELAY_GPIO 17
#define DISTANCE_THRESHOLD 20.0
#define DEBOUNCE_DELAY_US 1000000
#define POLL_DELAY_US 100000
#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_distance(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0;
    }
    float voltage = (float)adc_value * 3.3 / 1024.0;
    if (voltage < 0.5) {
        return -1.0;
    }
    float distance = 27.0 / (voltage - 0.5) - 0.42;
    if (distance < 0 || distance > 100) {
        return -1.0;
    }
    return distance;
}

static void log_event(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Door monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float distance = calculate_distance(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance calculation (ADC=%d)\n", adc_value);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance below threshold: %.2f cm\n", distance);
            if (gpioWrite(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Error: Failed to activate relay\n");
            }
            log_event(distance);
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioWrite(RELAY_GPIO, 0) != 0) {
                fprintf(stderr, "Error: Failed to deactivate relay\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

