/*
 * irrigation.c — Raspberry Pi Zero W
 *
 * Reads three successive samples from a Vegetronix VH400 soil-moisture
 * sensor via an MCP3008 ADC on SPI channel 0 (CE0 / GPIO8), computes
 * the average, and drives an ASCO RedHat 8210 series proportional
 * solenoid valve on GPIO17 using PWM at 100 Hz, 0–100 range.
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 * Run:    sudo ./irrigation
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* CE0 / GPIO8                          */
#define SPI_SPEED        1000000    /* 1 MHz                                */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, MSB first      */

#define VALVE_GPIO       17         /* BCM 17 — hardware PWM-capable pin     */
#define PWM_FREQUENCY    100        /* Hz                                   */
#define PWM_RANGE        100        /* duty 0–100  → 0–100 %                 */

#define NUM_SAMPLES      3
#define SAMPLE_DELAY_US  100000     /* 100 ms between samples                */
#define LOOP_DELAY_US    5000000    /* 5 s between log entries               */
#define LOG_FILE         "irrigation.log"

/* MCP3008 single-ended channel select bits (SPI mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | (ch << 4))         (SGL/DIFF=1, D2 D1 D0 = ch)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
#define MCP3008_START_BIT  0x01
#define MCP3008_SGL_DIFF   0x08

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static int  read_mcp3008(int channel, int *out_value);
static int  compute_average(int samples[], int n);
static int  set_valve_position(int percentage);
static void log_data(int adc_values[], int average, int valve_position);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- Implementation ----------------------------- */

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out_value), -1 on error.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    tx[0] = MCP3008_START_BIT;
    tx[1] = (unsigned char)(MCP3008_SGL_DIFF | ((channel & 0x07) << 4));
    tx[2] = 0x00;

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    *out_value = adc_value;
    return 0;
}

/*
 * Compute the average of the first `n` elements of `samples`.
 * Returns -1 if `n` is 0 or `samples` is NULL.
 */
static int compute_average(int samples[], int n)
{
    if (n <= 0 || samples == NULL) {
        return -1;
    }

    long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += samples[i];
    }
    return (int)(sum / n);
}

/*
 * Set the valve PWM duty cycle.
 * percentage: 0–100 → 0–100 % valve opening.
 * Returns 0 on success, -1 on error.
 */
static int set_valve_position(int percentage)
{
    if (percentage < 0 || percentage > 100) {
        fprintf(stderr, "Invalid valve percentage %d (must be 0–100)\n",
                percentage);
        return -1;
    }

    int duty = (percentage * PWM_RANGE) / 100;
    if (gpioPWM(VALVE_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed for GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

/*
 * Log one irrigation cycle to the log file.
 */
static void log_data(int adc_values[], int average, int valve_position)
{
    if (g_log_file == NULL) {
        return;
    }

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file,
            "%s, ADC: [%d, %d, %d], Avg: %d, Valve: %d%%\n",
            timestamp,
            adc_values[0], adc_values[1], adc_values[2],
            average, valve_position);
    fflush(g_log_file);
}

/*
 * Release all resources.
 */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Ensure valve is closed before terminating pigpio */
    gpioPWM(VALVE_GPIO, 0);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/*
 * Signal handler — set flag so main loop exits cleanly.
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure valve GPIO for PWM */
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n",
                VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    /* Start with valve closed */
    if (gpioPWM(VALVE_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation system started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    int adc_values[NUM_SAMPLES];
    int average;
    int valve_position;

    while (g_running) {
        bool read_failed = false;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            if (read_mcp3008(i, &adc_values[i]) != 0) {
                fprintf(stderr, "Error reading ADC channel %d\n", i);
                read_failed = true;
                break;
            }
            gpioDelay(SAMPLE_DELAY_US);
        }

        if (read_failed) {
            /* On read failure, close valve for safety and continue */
            gpioPWM(VALVE_GPIO, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        average = compute_average(adc_values, NUM_SAMPLES);
        if (average < 0) {
            fprintf(stderr, "Error computing average\n");
            gpioPWM(VALVE_GPIO, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /*
         * Map average ADC value to valve percentage.
         * 0–1023 → 0–100 % (clamped).
         */
        valve_position = (average * 100) / 1023;
        if (valve_position > 100) valve_position = 100;
        if (valve_position < 0)   valve_position = 0;

        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Error setting valve position\n");
        }

        log_data(adc_values, average, valve_position);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

