/*
 * Theremin-like instrument for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - HC-SR04 ultrasonic sensor: Trig=GPIO23 (BCM), Echo=GPIO24 (BCM)
 *   - LDR photoresistor (analog): MCP3008 ADC on SPI0, channel 0
 *   - PWM output: /sys/class/pwm/pwmchip0/pwm0 (GPIO18, BCM)
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpthread -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/pwm.h>

#define TRIG_PIN          23
#define ECHO_PIN          24
#define PWM_CHIP          0
#define PWM_CHANNEL       0
#define PWM_PERIOD_NS     1000000000ULL  /* 1 s => 100 Hz base */
#define PWM_DUTY_MAX      1000000000ULL  /* 100 % */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000
#define CONFIG_FILE       "theremin_config.txt"
#define ECHO_TIMEOUT_US   30000
#define LOOP_DELAY_US     100000

#define MIN_DISTANCE_CM   2.0f
#define MAX_DISTANCE_CM   400.0f
#define MIN_VOLUME        0.0f
#define MAX_VOLUME        1.0f

#define PWM_BASE_PATH     "/sys/class/pwm/pwmchip0"
#define PWM_EXPORT_PATH   PWM_BASE_PATH "/export"
#define PWM_UNEXPORT_PATH PWM_BASE_PATH "/unexport"
#define PWM_PERIOD_PATH   PWM_BASE_PATH "/pwm0/period"
#define PWM_DUTY_PATH     PWM_BASE_PATH "/pwm0/duty_cycle"
#define PWM_ENABLE_PATH   PWM_BASE_PATH "/pwm0/enable"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- PWM helpers ---------- */

static int pwm_write_file(const char *path, const char *value)
{
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "write(%s, %s): %s\n", path, value, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int pwm_export(void)
{
    return pwm_write_file(PWM_EXPORT_PATH, "0");
}

static int pwm_unexport(void)
{
    return pwm_write_file(PWM_UNEXPORT_PATH, "0");
}

static int pwm_set_period(uint64_t period_ns)
{
    char buf[32];
    snprintf(buf, sizeof(buf), "%llu", (unsigned long long)period_ns);
    return pwm_write_file(PWM_PERIOD_PATH, buf);
}

static int pwm_set_duty(uint64_t duty_ns)
{
    char buf[32];
    snprintf(buf, sizeof(buf), "%llu", (unsigned long long)duty_ns);
    return pwm_write_file(PWM_DUTY_PATH, buf);
}

static int pwm_enable(int enable)
{
    return pwm_write_file(PWM_ENABLE_PATH, enable ? "1" : "0");
}

/* ---------- SPI / MCP3008 ---------- */

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    uint8_t  bits  = 8;
    uint8_t  mode  = SPI_MODE_0;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit + SGL/DIFF=1 + D2 D1 D0 */
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    /* rx[1] low nibble + rx[2] form the 10-bit result */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ---------- Theremin logic ---------- */

static void map_distance_to_frequency(float distance, float *frequency, float *volume)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float normalized = (distance - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    *frequency = MIN_VOLUME + normalized * (MAX_VOLUME - MIN_VOLUME);
    *volume    = *frequency;
}

static void generate_tone(float frequency, float volume)
{
    if (frequency <= 0.0f) {
        pwm_set_duty(0);
        return;
    }

    uint64_t period_ns = (uint64_t)(1.0e9 / frequency);
    uint64_t duty_ns   = (uint64_t)(period_ns * volume);

    if (duty_ns > PWM_DUTY_MAX) duty_ns = PWM_DUTY_MAX;
    if (period_ns > PWM_PERIOD_NS) period_ns = PWM_PERIOD_NS;

    if (pwm_set_period(period_ns) < 0) return;
    if (pwm_set_duty(duty_ns)   < 0) return;
    if (pwm_enable(1)           < 0) return;
}

/* ---------- Calibration ---------- */

static int load_calibration(float *min_distance, float *max_distance)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s — using defaults\n",
                CONFIG_FILE, strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%f %f", min_distance, max_distance) != 2) {
        fprintf(stderr, "Malformed config — using defaults\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int save_calibration(float min_distance, float max_distance)
{
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Cannot write %s: %s\n", CONFIG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%f %f\n", min_distance, max_distance);
    fclose(fp);
    return 0;
}

/* ---------- Main ---------- */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* PWM setup */
    if (pwm_export() < 0) {
        fprintf(stderr, "Failed to export PWM0\n");
        return EXIT_FAILURE;
    }
    usleep(100000);

    /* SPI setup */
    int spi_fd = spi_init();
    if (spi_fd < 0) {
        pwm_unexport();
        return EXIT_FAILURE;
    }

    /* Calibration */
    float min_distance = MIN_DISTANCE_CM;
    float max_distance = MAX_DISTANCE_CM;
    load_calibration(&min_distance, &max_distance);

    printf("Theremin ready.  Ctrl+C to exit.\n");
    printf("Calibration: %.2f cm – %.2f cm\n", min_distance, max_distance);

    float last_frequency = 0.0f;
    float last_volume    = 0.0f;

    while (g_running) {
        /* Trigger HC-SR04 */
        if (gpioWrite(TRIG_PIN, 1) < 0) {
            fprintf(stderr, "gpioWrite(TRIG, 1) failed\n");
            usleep(10);
            continue;
        }
        usleep(10);
        if (gpioWrite(TRIG_PIN, 0) < 0) {
            fprintf(stderr, "gpioWrite(TRIG, 0) failed\n");
            usleep(10);
            continue;
        }

        /* Wait for echo rising edge */
        uint32_t start_wait = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (g_running == 0) goto shutdown;
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo start timeout\n");
                goto loop_end;
            }
        }
        uint32_t echo_start = gpioTick();

        /* Wait for echo falling edge */
        while (gpioRead(ECHO_PIN) == 1) {
            if (g_running == 0) goto shutdown;
            if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo end timeout\n");
                goto loop_end;
            }
        }
        uint32_t echo_end = gpioTick();

        float distance = (float)(echo_end - echo_start) / 58.0f / 2.0f;

        /* LDR via MCP3008 */
        int ldr_raw = mcp3008_read(spi_fd, 0);
        float ldr_volume = 0.0f;
        if (ldr_raw < 0) {
            fprintf(stderr, "MCP3008 read failed\n");
        } else {
            ldr_volume = (float)ldr_raw / 1023.0f;
        }

        /* Map to frequency and volume */
        float frequency, volume;
        map_distance_to_frequency(distance, &frequency, &volume);

        /* Clamp LDR volume to frequency */
        if (volume > frequency) volume = frequency;

        /* Apply calibration */
        if (distance < min_distance) distance = min_distance;
        if (distance > max_distance) distance = max_distance;

        /* Generate tone */
        generate_tone(frequency, volume);

        /* Update last values for graceful shutdown */
        last_frequency = frequency;
        last_volume    = volume;

    loop_end:
        usleep(LOOP_DELAY_US);
    }

shutdown:
    printf("\nShutting down...\n");
    pwm_enable(0);
    pwm_unexport();
    close(spi_fd);
    save_calibration(min_distance, max_distance);
    printf("Theremin stopped.\n");
    return EXIT_SUCCESS;
}

