#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_S 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "Warning: SPI transfer failed (attempt %d/%d), code: %d\n",
                attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Error: SPI communication failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
    spiClose(spi_handle);
    spi_handle = -1;
    gpioDelay(100000);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to re-initialize SPI: %d\n", spi_handle);
        return -1;
    }

    return read_mcp3008(channel);
}

static float calculate_aqi(int adc_value) {
    if (adc_value < 0) return -1.0f;
    float resistance = (10000.0f * 10.0f) / (float)(adc_value + 1) - 10.0f;
    float log_resistance = log10(resistance);
    float aqi = 110.0f * (log_resistance - 2.51f) + 25.0f;
    if (aqi < 0) aqi = 0;
    if (aqi > 500) aqi = 500;
    return aqi;
}

static void control_fan(float aqi) {
    int state = (aqi > AQI_THRESHOLD) ? 1 : 0;
    if (gpioWrite(FAN_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to fan GPIO %d\n", FAN_GPIO);
    }
}

static void log_data(float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, aqi);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Continuing...\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        float aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "Error: Invalid AQI calculation. Continuing...\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        control_fan(aqi);
        log_data(aqi);

        printf("ADC: %d, AQI: %.2f\n", adc_value, aqi);
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

