/*
 * MQ-3 Alcohol Sensor Monitor (Raspberry Pi Zero W)
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (GPIO8), SPI mode 0, 1 MHz, 8-bit words
 *   - MQ-3 analog output wired to MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o alcohol_monitor alcohol_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./alcohol_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, 8-bit words */
#define ADC_CHANNEL    0          /* MQ-3 on MCP3008 CH0 */
#define ADC_MAX        1023       /* 10-bit ADC full-scale */
#define LOG_FILE       "alcohol_log.txt"
#define SAMPLE_US      1000000    /* 1 second */
#define RETRY_DELAY_US 100000     /* 100 ms between retries */
#define MAX_RETRIES     3

/* Calibration: raw ADC counts at known alcohol concentrations */
typedef struct {
    float voltage;
    int   adc_value;
} cal_point_t;

static const cal_point_t cal_points[] = {
    { 0.0f,   0 },
    { 0.1f,   100 },
    { 0.2f,   200 },
    { 0.3f,   300 },
    { 0.4f,   400 },
    { 0.5f,   500 },
    { 0.6f,   600 },
    { 0.7f,   700 },
    { 0.8f,   800 },
    { 0.9f,   900 },
    { 1.0f,  1000 }
};
static const int num_cal_points =
    (int)(sizeof(cal_points) / sizeof(cal_points[0]));

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                         */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    if (adc_value < 0)
        return 0.0f;

    if (adc_value >= ADC_MAX)
        return 1.0f;

    for (int i = 0; i < num_cal_points - 1; i++) {
        if (adc_value >= cal_points[i].adc_value &&
            adc_value <= cal_points[i + 1].adc_value) {
            float span = (float)(cal_points[i + 1].adc_value -
                                 cal_points[i].adc_value);
            if (span <= 0.0f)
                return cal_points[i].voltage;
            return cal_points[i].voltage +
                   (float)(adc_value - cal_points[i].adc_value) / span *
                   (cal_points[i + 1].voltage - cal_points[i].voltage);
        }
    }
    return 0.0f;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                        */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_alcohol_level(float voltage, int adc_value,
                              const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Voltage: %.3f V, ADC: %d, %s\n",
                ts, voltage, adc_value, message) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0)
        fprintf(stderr, "fflush failed\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        fclose(g_log_fp);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MQ-3 Alcohol Sensor Monitor started. Logging to '%s'.\n",
           LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        /* Retry loop for transient SPI errors */
        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
            if (adc_value >= 0)
                break;
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US);
        }

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed after %d retries\n", MAX_RETRIES);
            log_alcohol_level(0.0f, -1, "ERROR: ADC read failed");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Sensor-absent heuristic: ADC stuck at rail */
        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr,
                    "Warning: ADC at rail (%d) — sensor may be absent or "
                    "disconnected\n", adc_value);
        }

        float voltage = adc_to_voltage(adc_value);

        if (voltage > 0.5f) {
            log_alcohol_level(voltage, adc_value,
                              "Alcohol detected! Limit exceeded.");
        } else if (voltage < 0.2f) {
            log_alcohol_level(voltage, adc_value,
                              "Sobriety confirmed.");
        } else {
            log_alcohol_level(voltage, adc_value,
                              "Alcohol level within acceptable range.");
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "fclose failed\n");
        g_log_fp = NULL;
    }

    if (spiClose(spi_handle) != 0)
        fprintf(stderr, "spiClose failed\n");

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

