        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(int moisture_level, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Moisture: %d, Pump: %s\n",
                timestamp, moisture_level, pump_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void control_pump(int moisture_level) {
    int pump_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;

    if (gpioWrite(PUMP_GPIO, pump_state) != 0) {
        fprintf(stderr, "Failed to write to pump GPIO %d\n", PUMP_GPIO);
        return;
    }

    log_data(moisture_level, pump_state);
}

