#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PWM 18
#define MOTOR2_PWM 24
#define MOTOR1_DIR 23
#define MOTOR2_DIR 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

#define ACCELERATION_STEP_DELAY_US 10000
#define HOLD_DURATION_US 2000000
#define PAUSE_DURATION_US 5000000
#define DIRECTION_CHANGE_DELAY_US 100000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx_buf[3] = {0};

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed: %d\n", handle);
        return -1;
    }

    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    spiClose(handle);

    if (result != 0) {
        fprintf(stderr, "Error: spiXfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

int map_adc_to_speed(int adc_value) {
    if (adc_value < 0) return 0;
    if (adc_value > 1023) return 255;
    return (int)(((float)adc_value / 1023.0) * 255.0);
}

void set_motor_speed(int motor_num, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    int pwm_pin, dir_pin;
    if (motor_num == 1) {
        pwm_pin = MOTOR1_PWM;
        dir_pin = MOTOR1_DIR;
    } else if (motor_num == 2) {
        pwm_pin = MOTOR2_PWM;
        dir_pin = MOTOR2_DIR;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
        return;
    }

    gpioPWM(pwm_pin, speed);
    gpioWrite(dir_pin, (speed > 0) ? 1 : 0);
}

void accelerate_motor(int motor_num, int target_speed) {
    int current_speed = 0;
    while (current_speed < target_speed && program_running) {
        current_speed++;
        set_motor_speed(motor_num, current_speed);
        gpioDelay(ACCELERATION_STEP_DELAY_US);
    }
    set_motor_speed(motor_num, target_speed);
}

void decelerate_motor(int motor_num, int target_speed) {
    int current_speed = 255;
    while (current_speed > target_speed && program_running) {
        current_speed--;
        set_motor_speed(motor_num, current_speed);
        gpioDelay(ACCELERATION_STEP_DELAY_US);
    }
    set_motor_speed(motor_num, target_speed);
}

void reverse_motors() {
    gpioWrite(MOTOR1_DIR, 1);
    gpioWrite(MOTOR2_DIR, 0);
    gpioDelay(DIRECTION_CHANGE_DELAY_US);
}

void cleanup() {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR1_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR2_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        int speed1 = map_adc_to_speed(pot1_value);
        int speed2 = map_adc_to_speed(pot2_value);

        accelerate_motor(1, speed1);
        gpioDelay(HOLD_DURATION_US);
        decelerate_motor(1, 0);

        gpioDelay(PAUSE_DURATION_US);

        accelerate_motor(2, speed2);
        gpioDelay(HOLD_DURATION_US);
        decelerate_motor(2, 0);

        gpioDelay(PAUSE_DURATION_US);

        reverse_motors();
    }

    cleanup();
    return 0;
}

