#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN          17
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define ADC_CHANNEL      0
#define SAMPLE_RATE_HZ   100
#define DEBOUNCE_US      10000
#define CALIBRATION_SEC  5
#define THRESHOLD_OFFSET 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static int calibrate_noise(int handle, int channel, int duration_sec) {
    int min_value = 1023;
    int max_value = 0;
    int samples = 0;
    int elapsed = 0;

    printf("Calibrating noise level for %d seconds...\n", duration_sec);

    while (running && elapsed < duration_sec) {
        int value = read_mcp3008(handle, channel);
        if (value < 0) {
            fprintf(stderr, "Calibration read failed\n");
            return -1;
        }

        if (value < min_value) min_value = value;
        if (value > max_value) max_value = value;

        samples++;
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
        elapsed++;
    }

    if (!running) return -1;

    int noise_level = (max_value - min_value) / 2;
    printf("Calibration complete. Noise baseline: %d (min=%d, max=%d, samples=%d)\n",
           noise_level, min_value, max_value, samples);
    return noise_level;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int noise_level = calibrate_noise(spi_handle, ADC_CHANNEL, CALIBRATION_SEC);
    if (noise_level < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t last_toggle_tick = 0;
    int led_state = 0;

    printf("Monitoring sound level (threshold=%d)... Press Ctrl+C to exit.\n",
           noise_level + THRESHOLD_OFFSET);

    while (running) {
        int sound_level = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (sound_level < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        uint32_t now = gpioTick();
        if (sound_level > noise_level + THRESHOLD_OFFSET &&
            (now - last_toggle_tick) > DEBOUNCE_US) {
            led_state = 1;
            gpioWrite(LED_PIN, led_state);
            last_toggle_tick = now;
        } else if (sound_level <= noise_level + THRESHOLD_OFFSET && led_state) {
            led_state = 0;
            gpioWrite(LED_PIN, led_state);
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

