#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_airflow(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }

    float voltage = (float)adc_value * 3.3f / 1024.0f;

    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > 3.3f) voltage = 3.3f;

    float airflow = 0.0f;

    if (voltage < 0.5f) {
        airflow = 0.0f;
    } else if (voltage < 1.0f) {
        airflow = (voltage - 0.5f) * 10.0f;
    } else if (voltage < 1.5f) {
        airflow = (voltage - 1.0f) * 10.0f + 10.0f;
    } else if (voltage < 2.0f) {
        airflow = (voltage - 1.5f) * 10.0f + 20.0f;
    } else if (voltage < 2.5f) {
        airflow = (voltage - 2.0f) * 10.0f + 30.0f;
    } else if (voltage < 3.0f) {
        airflow = (voltage - 2.5f) * 10.0f + 40.0f;
    } else {
        airflow = 50.0f;
    }

    return airflow;
}

static void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);

        if (adc_value < 0) {
            log_error("ADC read failed");
        } else {
            float airflow = calculate_airflow(adc_value);
            if (airflow < 0.0f) {
                log_error("Airflow calculation failed");
            } else {
                log_data(airflow);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nAirflow monitoring stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

