/*
 * ADXL335 + MCP3008 accelerometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL335 VCC  -> 3.3 V (Pin 1)
 *   ADXL335 GND  -> GND   (Pin 9)
 *   ADXL335 XOUT -> MCP3008 CH0
 *   ADXL335 YOUT -> MCP3008 CH1
 *   ADXL335 ZOUT -> MCP3008 CH2
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *
 * Build: gcc -O2 -Wall -o adxl335_kalman adxl335_kalman.c -lm -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNELS    3
#define SAMPLE_RATE_HZ  10
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

#define VREF            3.3f
#define ADC_MAX         1023

/* Kalman filter parameters */
#define Q_NOISE         0.001f
#define R_NOISE         0.01f

typedef struct {
    float Q;
    float R;
    float P[2][2];
    float x[2];
} KalmanFilter;

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int mcp3008_init(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (mode 0, MSB-first):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during MCP3008 init on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    return 0;
}

static int read_adc(int fd, uint8_t channel, uint16_t *value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_g(uint16_t adc_value)
{
    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    /* ADXL335: 3.3 V supply -> 1.35 g/V */
    return voltage * 1.35f;
}

static void kalman_init(KalmanFilter *kf, float Q, float R)
{
    kf->Q = Q;
    kf->R = R;
    kf->P[0][0] = 1.0f;
    kf->P[0][1] = 0.0f;
    kf->P[1][0] = 0.0f;
    kf->P[1][1] = 1.0f;
    kf->x[0] = 0.0f;
    kf->x[1] = 0.0f;
}

static void kalman_update(KalmanFilter *kf, float measurement)
{
    float P00_P11 = kf->P[0][0] + kf->P[1][1];
    float S = kf->P[0][0] + kf->R;
    float K0 = P00_P11 / S;
    float K1 = kf->P[1][0] / S;

    kf->x[0] = kf->x[0] + K0 * (measurement - kf->x[0]);
    kf->x[1] = kf->x[1] + K1 * (measurement - kf->x[0]);

    float P00_new = kf->P[0][0] - K0 * P00_P11;
    float P11_new = kf->P[1][1] - K1 * P00_P11;
    kf->P[0][0] = P00_new;
    kf->P[0][1] = 0.0f;
    kf->P[1][0] = 0.0f;
    kf->P[1][1] = P11_new;
}

int main(void)
{
    int spi_fd = -1;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) < 0) {
        goto cleanup;
    }

    for (uint8_t ch = 0; ch < ADC_CHANNELS; ch++) {
        if (mcp3008_init(spi_fd, ch) < 0) {
            fprintf(stderr, "Error initializing MCP3008 channel %u\n", ch);
            goto cleanup;
        }
    }

    KalmanFilter kf;
    kalman_init(&kf, Q_NOISE, R_NOISE);

    struct timespec sleep_time = { 0, SAMPLE_PERIOD_NS };
    struct timespec remaining;

    printf("ADXL335 + MCP3008 Kalman Filter Reader\n");
    printf("Sampling at %d Hz. Press Ctrl+C to exit.\n\n", SAMPLE_RATE_HZ);

    while (g_running) {
        uint16_t raw_x = 0, raw_y = 0, raw_z = 0;
        bool read_ok = true;

        if (read_adc(spi_fd, 0, &raw_x) < 0) {
            read_ok = false;
        }
        if (read_ok && read_adc(spi_fd, 1, &raw_y) < 0) {
            read_ok = false;
        }
        if (read_ok && read_adc(spi_fd, 2, &raw_z) < 0) {
            read_ok = false;
        }

        if (!read_ok) {
            fprintf(stderr, "SPI read error — continuing.\n");
            nanosleep(&sleep_time, &remaining);
            continue;
        }

        float x_g = adc_to_g(raw_x);
        float y_g = adc_to_g(raw_y);
        float z_g = adc_to_g(raw_z);

        kalman_update(&kf, x_g);

        printf("X: %7.3f g  Y: %7.3f g  Z: %7.3f g\n",
               kf.x[0], kf.x[1], z_g);
        fflush(stdout);

        nanosleep(&sleep_time, &remaining);
    }

    printf("\nExiting cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret_code;
}

