        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) < 0) {
        goto cleanup;
    }

    for (uint8_t ch = 0; ch < ADC_CHANNELS; ch++) {
