/*
 * DRV5055VA Hall-Effect Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads three digital Hall sensors on GPIO4, GPIO17, GPIO27 every 100 ms,
 * converts HIGH (3.3 V) to +100 mT and LOW (0.0 V) to -100 mT, logs the
 * three magnetic field strengths to magnetic_log.txt, and flushes after
 * each write.  Handles SIGINT for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hall_log hall_log.c -lpigpio -lrt
 * Run:    sudo ./hall_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define LOG_FILE_NAME "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000   /* 100 ms */
#define ADC_MAX_VOLTAGE 3.3
#define ADC_MIN_VOLTAGE 0.0
#define MAGNETIC_FIELD_MIN -100.0   /* mT */
#define MAGNETIC_FIELD_MAX 100.0    /* mT */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a digital GPIO level; returns 0, 1, or -1 on error             */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n",
                pin, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Convert a digital reading to magnetic field strength (mT)          */
/* ------------------------------------------------------------------ */
static double convert_to_magnetic_field(int sensor_value)
{
    if (sensor_value == 1) {
        return (ADC_MAX_VOLTAGE / 2.0) / 1000.0;   /* +100 mT */
    }
    return -(ADC_MIN_VOLTAGE / 2.0) / 1000.0;      /* -100 mT */
}

/* ------------------------------------------------------------------ */
/* Log three magnetic field values to file; returns 0 on success,      */
/* non-zero on failure                                                */
/* ------------------------------------------------------------------ */
static int log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (fprintf(fp, "%.2f,%.2f,%.2f\n",
                sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: could not install SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: could not install SIGTERM handler");
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR3_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Enable internal pull-downs so sensors read LOW when open --- */
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_DOWN);

    printf("Hall-effect sensor logging started.  Press Ctrl-C to exit.\n");
    printf("Logging to: %s\n", LOG_FILE_NAME);

    /* --- Main sampling loop --- */
    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Warning: GPIO read error — skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double m1 = convert_to_magnetic_field(s1);
        double m2 = convert_to_magnetic_field(s2);
        double m3 = convert_to_magnetic_field(s3);

        if (m1 < MAGNETIC_FIELD_MIN || m1 > MAGNETIC_FIELD_MAX ||
            m2 < MAGNETIC_FIELD_MIN || m2 > MAGNETIC_FIELD_MAX ||
            m3 < MAGNETIC_FIELD_MIN || m3 > MAGNETIC_FIELD_MAX) {
            fprintf(stderr,
                    "Warning: magnetic field out of range "
                    "(s1=%.2f, s2=%.2f, s3=%.2f) — skipping log\n",
                    m1, m2, m3);
        } else {
            if (log_data(m1, m2, m3) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

