/*
 * Soil Moisture Monitor & Pump Controller
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MCP3008 on SPI0 (CE0), channel 0, 500 kHz, mode 0
 * Pump:   Relay on GPIO17 (BCM), active-high
 * Log:    watering.log
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 */
#define SPI_SPEED      500000     /* 500 kHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define PUMP_GPIO      17         /* BCM 17 */
#define MOISTURE_THRESHOLD 30.0f  /* % */
#define SAMPLE_INTERVAL_S 60
#define LOG_FILE       "watering.log"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_msg(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                       */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        log_msg("Error: invalid ADC channel requested");
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        log_msg("Error: SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Moisture conversion                                                */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 is 10-bit: 0..1023.
 * 0 % moisture  -> ADC near 0 (dry)
 * 100 % moisture-> ADC near 1023 (wet)
 * Linear map: 1023 -> 100.0 %
 */
static float adc_to_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Pump control                                                       */
/* ------------------------------------------------------------------ */
static void control_pump(float moisture)
{
    static int pump_on = 0;

    if (moisture < MOISTURE_THRESHOLD && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = 1;
            log_msg("Pump turned ON");
        } else {
            log_msg("Error: failed to turn pump ON");
        }
    } else if (moisture >= MOISTURE_THRESHOLD && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = 0;
            log_msg("Pump turned OFF");
        } else {
            log_msg("Error: failed to turn pump OFF");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    if (g_log_fp) {
        log_msg("Program terminated");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure pump GPIO ---- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        log_msg("Error: failed to set pump GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    /* ---- open SPI ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        log_msg("Error: SPI open failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_msg("Program started");

    /* ---- main loop ---- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            log_msg("Error: ADC read failed, skipping cycle");
        } else {
            float moisture = adc_to_moisture(adc);
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Moisture: %.2f%% (ADC: %d)", moisture, adc);
            log_msg(msg);
            control_pump(moisture);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

