/*
 * Raspberry Pi 4 Model B — MQTT LED controller
 *
 * Subscribes to "home/led_control" on mqtt.eclipseprojects.io:1883
 * with client ID "rpi_led_control" and QoS 0.  Expects JSON payloads
 * containing a single key "led_state" with a boolean value.
 *
 * LED on GPIO17 (BCM) — HIGH = ON, LOW = OFF.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpi_led_control rpi_led_control.c \
 *              -lmosquitto -lcjson
 *
 * Run:    ./rpi_led_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_HOST      "mqtt.eclipseprojects.io"
#define MQTT_PORT      1883
#define MQTT_TOPIC     "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS       0

#define GPIO_PIN       17          /* BCM 17 */
#define GPIO_CONSUMER  "rpi_led_control"

#define MAX_RECONNECT_DELAY 60     /* seconds */
#define STARTUP_DELAY       1      /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Timestamped logging                                                 */
/* ------------------------------------------------------------------ */
static void log_message(const char *level, const char *message)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(stderr, "[%s] [%s] %s\n", ts, level, message);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers (using pigpio)                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_message("ERROR", "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_message("ERROR", "Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_message("ERROR", "Failed to initialise GPIO17 LOW");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_set_led(bool on)
{
    if (gpioWrite(GPIO_PIN, on ? 1 : 0) != 0)
        log_message("WARN", "gpioWrite failed");
}

static void gpio_cleanup(void)
{
    gpioWrite(GPIO_PIN, 0);   /* best-effort LED off */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc == MOSQ_ERR_SUCCESS) {
            log_message("INFO", "Connected to MQTT broker and subscribed");
        } else {
            log_message("ERROR", "Subscribe failed");
        }
    } else {
        log_message("ERROR", "MQTT connection failed");
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == MOSQ_ERR_SUCCESS)
        log_message("INFO", "Disconnected cleanly");
    else
        log_message("WARN", "Unexpected disconnect");
}

static void on_message(struct mosquitto *mosq, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message == NULL || message->payload == NULL || message->payloadlen <= 0) {
        log_message("WARN", "Received empty message");
        return;
    }

    /*
     * cJSON does not support parsing a fragment, so we must first
     * assemble the payload into a NUL-terminated string.
     */
    char *payload_str = malloc((size_t)message->payloadlen + 1);
    if (payload_str == NULL) {
        log_message("ERROR", "malloc failed in on_message");
        return;
    }
    memcpy(payload_str, message->payload, (size_t)message->payloadlen);
    payload_str[message->payloadlen] = '\0';

    cJSON *json = cJSON_Parse(payload_str);
    free(payload_str);

    if (json == NULL) {
        log_message("ERROR", "JSON parse failed");
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (led_state == NULL) {
        log_message("ERROR", "Missing or invalid 'led_state' key");
        cJSON_Delete(json);
        return;
    }

    if (!cJSON_IsBool(led_state)) {
        log_message("ERROR", "Invalid 'led_state' value (not a boolean)");
        cJSON_Delete(json);
        return;
    }

    gpio_set_led(cJSON_IsTrue(led_state));
    log_message("INFO", "LED state updated");

    cJSON_Delete(json);
}

/* ------------------------------------------------------------------ */
/* MQTT reconnect loop                                                 */
/* ------------------------------------------------------------------ */
static int reconnect_mqtt(struct mosquitto **mosq)
{
    int delay = STARTUP_DELAY;

    while (g_running) {
        int rc = mosquitto_reconnect(*mosq);
        if (rc == MOSQ_ERR_SUCCESS) {
            log_message("INFO", "Reconnected to MQTT broker");
            return 0;
        }

        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Reconnect failed (rc=%d), retrying in %d s", rc, delay);
        log_message("WARN", msg);

        /*
         * Sleep in 1 s increments so we can respond to signals promptly.
         */
        for (int i = 0; i < delay && g_running; i++)
            sleep(1);

        if (delay < MAX_RECONNECT_DELAY)
            delay *= 2;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpio_init() != 0) {
        log_message("ERROR", "GPIO initialisation failed");
        return EXIT_FAILURE;
    }

    struct mosquitto *mosq = NULL;
    int rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("ERROR", "mosquitto_lib_init failed");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        log_message("ERROR", "mosquitto_new failed");
        mosquitto_lib_cleanup();
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Initial connect failed (rc=%d)", rc);
        log_message("ERROR", msg);
        mosquitto_lib_cleanup();
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    log_message("INFO", "Starting MQTT loop");

    while (g_running) {
        rc = mosquitto_loop(mosq, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            char msg[128];
            snprintf(msg, sizeof(msg), "mosquitto_loop error (rc=%d)", rc);
            log_message("ERROR", msg);
            if (reconnect_mqtt(&mosq) != 0)
                break;
        }
    }

    /*
     * Clean shutdown path.
     */
    mosquitto_disconnect(mosq);
    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    gpio_cleanup();

    log_message("INFO", "Shutdown complete");
    return EXIT_SUCCESS;
}

