/*
 * vibration_shutdown.c — SW-420 vibration sensor monitor for Raspberry Pi 4
 *
 * Wiring:
 *   SW-420 VCC  -> 3V3 (pin 1)
 *   SW-420 GND  -> GND (pin 9)
 *   SW-420 DO   -> GPIO17 (pin 11, BCM 17)
 *
 * The SW-420 DO line is active-low (idle HIGH, pulls LOW on vibration).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vibration_shutdown vibration_shutdown.c
 *
 * Run:
 *   sudo ./vibration_shutdown
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#include <linux/gpio.h>

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define CONSUMER        "vibration-monitor"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_open_chip(const char *path, int *fd_out)
{
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("open(GPIO chip)");
        return -1;
    }
    *fd_out = fd;
    return 0;
}

static int gpio_get_line(int fd, unsigned int offset, struct gpiohandle *h)
{
    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = offset;
    req.flags          = GPIOHANDLE_REQUEST_FLAG_ACTIVE_LOW;
    req.lines          = 1;
    strncpy(req.consumer_label, CONSUMER, sizeof(req.consumer_label) - 1);
    req.consumer_label[sizeof(req.consumer_label) - 1] = '\0';

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("GPIO_GET_LINEHANDLE_IOCTL");
        return -1;
    }

    memcpy(h, &req.handle, sizeof(*h));
    return 0;
}

static int gpio_request_event(int fd, struct gpiohandle *h, int event_type)
{
    struct gpioevent_request req;
    memset(&req, 0, sizeof(req));
    req.linehandle = *h;
    req.eventtype  = event_type;
    req.flags      = 0;

    if (ioctl(fd, GPIO_GET_LINEEVENT_IOCTL, &req) < 0) {
        perror("GPIO_GET_LINEEVENT_IOCTL");
        return -1;
    }
    return 0;
}

static int gpio_wait_event(int fd, struct gpioevent_request *req)
{
    while (g_running) {
        ssize_t n = read(req->fd, req, sizeof(*req));
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("read(GPIO event)");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read() returned 0 (unexpected EOF)\n");
            return -1;
        }
        return 0;
    }
    return 1;
}

static void gpio_release(int fd, struct gpiohandle *h)
{
    if (h->fd >= 0) {
        close(h->fd);
        h->fd = -1;
    }
    if (fd >= 0) {
        close(fd);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int gpio_fd = -1;
    struct gpiohandle line_h = { .fd = -1 };
    struct gpioevent_request event_req = { .fd = -1 };
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    if (gpio_open_chip(GPIO_CHIP, &gpio_fd) != 0) {
        goto cleanup;
    }

    if (gpio_get_line(gpio_fd, GPIO_LINE, &line_h) != 0) {
        goto cleanup;
    }

    if (gpio_request_event(gpio_fd, &line_h, GPIOEVENT_EVENT_FALLING_EDGE) != 0) {
        goto cleanup;
    }

    event_req.fd = line_h.fd;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (falling edge).\n",
           GPIO_LINE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int rc = gpio_wait_event(gpio_fd, &event_req);
        if (rc < 0) {
            goto cleanup;
        }
        if (rc == 1) {
            break;
        }

        if (log_event("Vibration detected — initiating shutdown.") != 0) {
            fprintf(stderr, "Warning: failed to log event.\n");
        }

        printf("Vibration detected — initiating shutdown.\n");
        fflush(stdout);

        int sys_rc = system("sudo shutdown -h now");
        if (sys_rc == -1) {
            perror("system()");
        } else if (sys_rc != 0) {
            fprintf(stderr, "shutdown command exited with status %d\n", sys_rc);
        }

        /*
         * After a successful shutdown the system exits.  If we
         * reach here the loop continues so the program can exit
         * cleanly if the signal handler sets g_running = 0.
         */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (event_req.fd >= 0) {
        close(event_req.fd);
    }
    gpio_release(gpio_fd, &line_h);
    return ret;
}

