/*
 * BMP280 barometric altitude logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   BMP280 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   BMP280 VDD  -> 3.3 V (pin 1)
 *   BMP280 GND  -> GND  (pin 6)
 *   BMP280 SDO  -> GND  (I2C address 0x76)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_altitude bmp280_altitude.c
 * Run:    ./bmp280_altitude
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BMP280 register definitions (datasheet rev 1.26) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_CHIP_ID_REG     0xD0
#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_REG       0xE0
#define BMP280_RESET_CMD       0xB6
#define BMP280_CTRL_MEAS_REG   0xF4
#define BMP280_CONFIG_REG      0xF5
#define BMP280_PRESS_MSB_REG   0xF7
#define BMP280_TEMP_MSB_REG    0xFA
#define BMP280_CALIB_START     0x88
#define BMP280_CALIB_LEN       24

/* Oversampling settings (x1 for pressure and temperature) */
#define CTRL_MEAS_OSRS_T_X1    (0x01 << 5)
#define CTRL_MEAS_OSRS_P_X1    (0x01 << 2)
#define CTRL_MEAS_MODE_NORMAL  (0x03)

/* Config register: t_sb = 500 ms (0x00), filter off (0x00), spi3w_en = 0 */
#define CONFIG_REG_VAL        0x00

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Calibration coefficients (read from sensor) ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static bmp280_calib_t g_cal;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X = 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- BMP280 driver ---- */
static int bmp280_init(int fd)
{
    uint8_t chip_id = 0;
    if (i2c_read_reg(fd, BMP280_CHIP_ID_REG, &chip_id) != 0)
        return -1;
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X "
                        "(sensor not present or wrong device)\n",
                chip_id, BMP280_CHIP_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, BMP280_RESET_REG, BMP280_RESET_CMD) != 0)
        return -1;
    usleep(2000);  /* 2 ms minimum after reset */

    /* Read calibration coefficients (24 bytes from 0x88) */
    uint8_t cal[BMP280_CALIB_LEN];
    if (i2c_read_block(fd, BMP280_CALIB_START, cal, sizeof(cal)) != 0)
        return -1;

    g_cal.dig_T1 = (uint16_t)((cal[1]  << 8) | cal[0]);
    g_cal.dig_T2 = (int16_t) ((cal[3]  << 8) | cal[2]);
    g_cal.dig_T3 = (int16_t) ((cal[5]  << 8) | cal[4]);
    g_cal.dig_P1 = (uint16_t)((cal[7]  << 8) | cal[6]);
    g_cal.dig_P2 = (int16_t) ((cal[9]  << 8) | cal[8]);
    g_cal.dig_P3 = (int16_t) ((cal[11] << 8) | cal[10]);
    g_cal.dig_P4 = (int16_t) ((cal[13] << 8) | cal[12]);
    g_cal.dig_P5 = (int16_t) ((cal[15] << 8) | cal[14]);
    g_cal.dig_P6 = (int16_t) ((cal[17] << 8) | cal[16]);
    g_cal.dig_P7 = (int16_t) ((cal[19] << 8) | cal[18]);
    g_cal.dig_P8 = (int16_t) ((cal[21] << 8) | cal[20]);
    g_cal.dig_P9 = (int16_t) ((cal[23] << 8) | cal[22]);

    /* Configure: t_sb=500ms (0x00), filter off (0x00), spi3w_en=0 */
    if (i2c_write_reg(fd, BMP280_CONFIG_REG, CONFIG_REG_VAL) != 0)
        return -1;

    /* Control: osrs_t=x1, osrs_p=x1, normal mode */
    uint8_t ctrl = CTRL_MEAS_OSRS_T_X1 | CTRL_MEAS_OSRS_P_X1 |
                   CTRL_MEAS_MODE_NORMAL;
    if (i2c_write_reg(fd, BMP280_CTRL_MEAS_REG, ctrl) != 0)
        return -1;

    return 0;
}

/*
 * Read raw temperature and pressure.
 * Returns 0 on success, -1 on error.
 */
static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_PRESS_MSB_REG, data, 6) != 0)
        return -1;

    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) |
             ((int32_t)data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) |
             ((int32_t)data[5] >> 4);
    return 0;
}

/*
 * Bosch BMP280 compensation (datasheet rev 1.26, section 4.2.3).
 * Returns altitude in meters.
 */
static double bmp280_compensate_altitude(int32_t raw_t, int32_t raw_p)
{
    double var1, var2, t_fine;
    double t, p;

    /* Temperature compensation */
    var1 = ((double)raw_t / 16384.0 - (double)g_cal.dig_T1 / 1024.0) *
           g_cal.dig_T2;
    var2 = ((double)raw_t / 131072.0 - (double)g_cal.dig_T1 / 8192.0);
    var2 = var2 * var2 * (double)g_cal.dig_T3;
    t_fine = (var1 + var2) * 5120.0;
    t = t_fine / 1024.0;

    /* Pressure compensation */
    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * (double)g_cal.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)g_cal.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)g_cal.dig_P4 * 65536.0);
    var1 = ((double)g_cal.dig_P3 * var1 * var1 / 524288.0 +
            (double)g_cal.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)g_cal.dig_P1;
    if (var1 == 0.0) {
        fprintf(stderr, "Pressure compensation division by zero\n");
        return NAN;
    }
    p = 1048576.0 - (double)raw_p;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)g_cal.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)g_cal.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)g_cal.dig_P7) / 16.0;

    /* Altitude from sea-level pressure (1013.25 hPa) */
    return 44330.0 * (1.0 - pow(p / 1013.25, 0.1903));
}

/* ---- Logging ---- */
static int log_altitude(FILE *fp, double altitude)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, altitude) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
