        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BMP280_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (bmp280_init(g_i2c_fd) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("altitude_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(altitude_log.txt) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 initialized. Logging to altitude_log.txt every 5 s. "
           "Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        int32_t raw_t = 0, raw_p = 0;

        if (bmp280_read_raw(g_i2c_fd, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "Read failed; retrying in 5 s\n");
        } else {
            double alt = bmp280_compensate_altitude(raw_t, raw_p);
            if (isnan(alt)) {
                fprintf(stderr, "Compensation produced NaN; skipping\n");
            } else {
                if (log_altitude(g_log_fp, alt) != 0) {
                    fprintf(stderr, "Logging failed\n");
                } else {
                    printf("Altitude: %.2f m\n", alt);
                }
            }
        }

        /* Sleep 5 s in 1 s increments so signals are caught promptly */
        for (int i = 0; i < 5 && g_running; i++)
            sleep(1);
    }

