#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, pin, state) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void alarm_triggered(int pin, int state) {
    printf("ALARM: Flame detected on GPIO %d (state=%d)\n", pin, state);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_PIN);
    fflush(stdout);

    while (program_running) {
        int state = gpioRead(FLAME_SENSOR_PIN);
        if (state < 0) {
            fprintf(stderr, "gpioRead failed for pin %d\n", FLAME_SENSOR_PIN);
            break;
        }

        if (log_event(FLAME_SENSOR_PIN, state) != 0) {
            fprintf(stderr, "Failed to log event\n");
            break;
        }

        if (state == 1) {
            alarm_triggered(FLAME_SENSOR_PIN, state);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

