    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d, mode %d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
            } else {
                if (log_data(i, adc_value) != 0) {
                    fprintf(stderr, "Error: Failed to log data for sensor %d\n", i);
                }
            }
        }

        if (!terminate) {
            sleep(SLEEP_SECONDS);
        }
    }

    printf("\nCaught SIGINT, cleaning up...\n");
    cleanup();
    printf("Exiting.\n");
    return 0;
}

