#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 3 Model B+ — four-relay light sequencer using pigpio.
 *
 * Relays (Songle SRD-05VDC-SL, active-high):
 *   Relay 1 -> BCM GPIO 17
 *   Relay 2 -> BCM GPIO 22
 *   Relay 3 -> BCM GPIO 23
 *   Relay 4 -> BCM GPIO 24
 *
 * Behaviour:
 *   - All relays start inactive (LOW).
 *   - Each relay is activated (set HIGH) for 1 s, then deactivated (set LOW)
 *     for 1 s, then the next relay is activated, and so on.
 *   - The loop repeats indefinitely until a signal is caught.
 *   - On exit, every relay is deactivated and pigpio is terminated.
 */

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.           */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate all four relays and release pigpio resources.           */
/* ------------------------------------------------------------------ */
static void cleanup_all(void)
{
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 0);   /* best-effort deactivation */
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure relay pins as outputs and set them LOW (inactive) ---- */
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM GPIO %d.\n",
                    relay_pins[i]);
            cleanup_all();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite(LOW) failed for BCM GPIO %d.\n",
                    relay_pins[i]);
            cleanup_all();
            return EXIT_FAILURE;
        }
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    /* ---- Main loop: activate each relay in turn ---- */
    while (g_running) {
        for (int i = 0; i < 4 && g_running; i++) {
            if (gpioWrite(relay_pins[i], 1) != 0) {
                fprintf(stderr, "Error: gpioWrite(HIGH) failed for BCM GPIO %d.\n",
                        relay_pins[i]);
                cleanup_all();
                return EXIT_FAILURE;
            }
            printf("Relay %d (BCM %d) activated.\n", i + 1, relay_pins[i]);
            fflush(stdout);

            /* Sleep 1 s; pigpio's gpioDelay is microseconds */
            gpioDelay(1000000);

            if (gpioWrite(relay_pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioWrite(LOW) failed for BCM GPIO %d.\n",
                        relay_pins[i]);
                cleanup_all();
                return EXIT_FAILURE;
            }
            printf("Relay %d (BCM %d) deactivated.\n", i + 1, relay_pins[i]);
            fflush(stdout);

            gpioDelay(1000000);
        }
    }

