        if (rain_level > RAIN_THRESHOLD) {
            printf("Rain detected! Closing window.\n");
            if (window_state) {
                motor_forward();
                sleep(MOTOR_RUN_TIME);
                motor_stop();
                window_state = 0;
            }
        } else {
            printf("No rain detected. Opening window.\n");
            if (!window_state) {
                motor_reverse();
                sleep(MOTOR_RUN_TIME);
                motor_stop();
                window_state = 1;
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

