#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN      26
#define LED_PIN      16
#define DEBOUNCE_MS  50
#define LED_ON_MS    500
#define SAMPLE_US    10
#define MAX_SAMPLES  1000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input.\n", MIC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED_PIN %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_adc(void)
{
    int count = 0;
    for (int i = 0; i < MAX_SAMPLES; i++) {
        if (gpioRead(MIC_PIN) == 1) {
            count++;
        }
        gpioDelay(SAMPLE_US);
    }
    return count;
}

static bool detect_clap(int prev_count, int current_count)
{
    if (current_count > prev_count + 5) {
        return true;
    }
    return false;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Clap detector started. Press Ctrl+C to exit.");

    int prev_count = 0;
    int current_count = 0;
    bool led_on = false;
    uint32_t led_off_tick = 0;

    while (g_running) {
        current_count = read_adc();

        if (detect_clap(prev_count, current_count)) {
            uint32_t now = gpioTick();
            if (!led_on || (now - led_off_tick) >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                if (gpioWrite(LED_PIN, 1) == 0) {
                    led_on = true;
                    led_off_tick = now;
                    log_event("Clap detected!");
                } else {
                    log_event("Error: failed to turn on LED.");
                }
            }
        }

        prev_count = current_count;

        if (led_on) {
            if ((gpioTick() - led_off_tick) >= (uint32_t)(LED_ON_MS * 1000)) {
                if (gpioWrite(LED_PIN, 0) == 0) {
                    led_on = false;
                } else {
                    log_event("Error: failed to turn off LED.");
                }
            }
        }

        gpioDelay(1000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    log_event("Clap detector stopped.");
    return EXIT_SUCCESS;
}

