#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 1
#define ERROR_RETRY_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gpio_value(int pin) {
    char path[64];
    int ret = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    if (ret < 0 || (size_t)ret >= sizeof(path)) {
        fprintf(stderr, "Error formatting GPIO path\n");
        return -1;
    }

    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO value file '%s': %s\n", path, strerror(errno));
        return -1;
    }

    char buf[2];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';

    if (close(fd) != 0) {
        fprintf(stderr, "Error closing GPIO value file: %s\n", strerror(errno));
        return -1;
    }

    return (buf[0] == '1') ? 1 : 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Starting distance monitoring on GPIO%d...\n", GPIO_PIN);

    while (g_running) {
        int distance = read_gpio_value(GPIO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Error reading GPIO value, retrying in %d seconds...\n", ERROR_RETRY_SEC);
            sleep(ERROR_RETRY_SEC);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance, retrying in %d seconds...\n", ERROR_RETRY_SEC);
            sleep(ERROR_RETRY_SEC);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        fflush(stdout);
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

