 * Run:   sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC */

#define PUMP_GPIO        17         /* BCM 17 */
#define PUMP_THRESHOLD   20         /* Percentage below which pump turns ON */

#define LOG_FILE         "soil_moisture.log"
#define SAMPLE_INTERVAL  60         /* Seconds between readings */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_adc(int channel);
static float adc_to_moisture_percent(int adc_value);
static void control_pump(int on);
static void log_data(float moisture_percent, int pump_status);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0..1023 on success, -1 on error.
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the low nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/*
 * Convert raw ADC value to moisture percentage (0–100 %).
 * VH400: dry ~1023, wet ~0.  We map 0->100, 1023->0.
 */
static float adc_to_moisture_percent(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0f;
    }
    return 100.0f - ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
}

/*
 * Drive the relay (active-high) to turn the pump ON or OFF.
 */
static void control_pump(int on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", PUMP_GPIO, on);
    }
}

/*
 * Append a timestamped reading to the log file.
 */
static void log_data(float moisture_percent, int pump_status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL || strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    }

    fprintf(g_log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
            ts, moisture_percent, pump_status ? "ON" : "OFF");
    fflush(g_log_file);
}

/*
 * SIGINT / SIGTERM handler — graceful shutdown.
 */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Release all resources.
 */
static void cleanup(void)
{
    control_pump(0);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* Pump OFF at startup */

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed — skipping sample\n");
        } else {
            float moisture_percent = adc_to_moisture_percent(adc_value);
            if (moisture_percent < 0.0f) {
                fprintf(stderr, "Moisture conversion failed — skipping sample\n");
            } else {
                int pump_on = (moisture_percent < PUMP_THRESHOLD) ? 1 : 0;
                control_pump(pump_on);
                log_data(moisture_percent, pump_on);
                printf("Moisture: %.2f%%  Pump: %s\n",
                       moisture_percent, pump_on ? "ON" : "OFF");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

