/*
 * DRV5055-A1 Hall-effect sensor reader via MCP3008 ADC on Raspberry Pi Zero W.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pi pin 1)
 *   MCP3008 VREF -> 3.3 V (Pi pin 1)
 *   MCP3008 AGND -> GND  (Pi pin 6)
 *   MCP3008 DGND -> GND  (Pi pin 6)
 *   MCP3008 CLK  -> GPIO11 (Pi pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (Pi pin 21, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (Pi pin 19, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (Pi pin 24, SPI0 CE0)
 *   MCP3008 CH0  -> DRV5055-A1 VOUT
 *   DRV5055-A1 VCC -> 3.3 V
 *   DRV5055-A1 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hall_log hall_log.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define GPIO_CHIP       "gpiochip0"
#define CS_GPIO_LINE    8          /* BCM 8 = SPI0 CE0 */

#define ADC_CHANNEL     0          /* MCP3008 channel 0 */
#define SAMPLE_PERIOD_MS 500
#define LOG_FILE        "magnetic_log.txt"

/* DRV5055-A1 transfer-resistance curve (10 mT range, 100 ohm -> 1000 ohm). */
#define RESISTANCE_MIN  100.0f     /* ohms */
#define RESISTANCE_MAX  1000.0f    /* ohms */
#define MAGNETIC_MIN    10.0f      /* mT */
#define MAGNETIC_MAX    100.0f     /* mT */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3-byte transfer, mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/*
 * DRV5055-A1 voltage -> magnetic field (mT).
 * Internal 3.3 V reference, 10 kohm pull-up, 100 ohm -> 1000 ohm.
 * Vout = Vref * (R_load / R_sensor)
 * B   = (Vout / Vref) * (R_max - R_min) / (R_load - R_sensor)
 */
static float voltage_to_magnetic(float vref, float voltage)
{
    if (voltage <= 0.0f)
        return 0.0f;

    float ratio = voltage / vref;
    float load  = RESISTANCE_MAX;
    float sensor = RESISTANCE_MIN;

    if (ratio <= 0.0f)
        return 0.0f;

    float b = (ratio * (MAGNETIC_MAX - MAGNETIC_MIN)) / (load - sensor);
    return b;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request CS line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "hall_log", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging DRV5055-A1 magnetic field to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t raw = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &raw) == -1) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        /* MCP3008 is 10-bit: 0..1023 */
        float voltage = (float)raw * 3.3f / 1024.0f;
        float magnetic = voltage_to_magnetic(3.3f, voltage);

        time_t now = time(NULL);
        if (fprintf(log_fp, "%ld,%.2f\n", (long)now, magnetic) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        } else {
            fflush(log_fp);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    if (spi_fd >= 0)
        close(spi_fd);

    return ret;
}

