/*
 * MLX91209 current sensor reader via MCP3008 ADC on Raspberry Pi 3 B+.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pi pin 1)
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> Pi GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91209 VOUT
 *   GPIO17       -> MLX91209 PEN (power enable)
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_log current_log.c
 * Run:    ./current_log   (user must be in the 'spi' group or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within MCP3008 spec */
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define GPIO_CHIP       "gpiochip4"   /* BCM GPIO on Pi 3 B+ */
#define PEN_LINE_OFFSET 17            /* BCM 17 */

#define ADC_CHANNEL     0             /* MCP3008 single-ended channel 0 */
#define ADC_MAX         1023          /* 10-bit ADC */
#define ADC_VREF        3.3           /* VREF tied to 3.3 V */

#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD_S 1             /* seconds between samples */

/* MLX91209: 0–5 V output, ~100 mV/A typical */
#define SENSOR_V_MIN    0.0
#define SENSOR_V_MAX    5.0
#define SENSOR_V_OFFSET 0.0           /* sensor zero-point (adjust per calibration) */
#define SENSOR_SCALE    ((SENSOR_V_MAX - SENSOR_V_MIN) / (ADC_MAX - 0))

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 8 bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static float adc_to_voltage(uint16_t adc)
{
    return (float)adc * ADC_VREF / (float)ADC_MAX;
}

static float voltage_to_current(float v)
{
    return (v - SENSOR_V_OFFSET) / SENSOR_SCALE;
}

static int log_line(FILE *fp, float current)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.4f\n", ts, current) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int  spi_fd = -1;
    FILE *fp   = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pen  = NULL;
    int  rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    /* --- Open GPIO chip and request PEN line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    pen = gpiod_chip_get_line(chip, PEN_LINE_OFFSET);
    if (pen == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(pen, "mlx91209-pen", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    /* Enable sensor power (PEN high) */
    if (gpiod_line_set_value(pen, 1) < 0) {
        perror("gpiod_line_set_value(high)");
        goto cleanup;
    }

    /* Allow sensor to settle after power-on */
    sleep(1);

    printf("MLX91209 current logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t adc = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc) != 0) {
            fprintf(stderr, "ADC read failed — sensor absent or bus error.\n");
            /* Keep PEN high so the sensor stays powered; retry next cycle */
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float voltage = adc_to_voltage(adc);
        float current = voltage_to_current(voltage);

        if (log_line(fp, current) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        printf("ADC=%4u  V=%.4f  I=%.4f A\n", adc, voltage, current);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (pen != NULL) {
        /* Ensure sensor is powered down on exit */
        (void)gpiod_line_set_value(pen, 0);
        gpiod_line_release(pen);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (fp != NULL)
        fclose(fp);
    if (spi_fd >= 0)
        close(spi_fd);

    return rc;
}

