#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W – MLX91211 current sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD/VREF -> Pi 5V (pin 2)
 *   MCP3008 DGND/AGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (pin 21, SPI0 MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (pin 19, SPI0 MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (pin 24, SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MCP3008 SPI: 1 MHz, mode 0 (CPOL=0, CPHA=0).
 * MLX91211: 5 V supply, 0–5 V output.
 */

#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8)            */
#define SPI_SPEED      1000000    /* 1 MHz                              */
#define SPI_FLAGS      0          /* mode 0, active-low CE              */
#define ADC_CHANNEL    0          /* MCP3008 channel 0                  */
#define ADC_MAX        1023       /* 10-bit ADC                         */
#define VREF           5.0        /* MCP3008 VREF = 5 V                 */
#define ADC_VOLTS_PER  1.0        /* 5 V / 1023 counts                  */
#define SAMPLE_US      100000     /* 100 ms                             */
#define LOG_FILE       "current_log.txt"
#define V_MIN          0.0
#define V_MAX          5.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended mode)                */
/* Returns 0 on success (value stored in *out), -1 on SPI error.      */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel, int *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    *out = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to current (A)                                   */
/* ------------------------------------------------------------------ */
static double adc_to_current(int adc_value)
{
    return (double)adc_value * ADC_VOLTS_PER / VREF;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static int log_current(FILE *fp, double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper – close log, terminate pigpio, exit                 */
/* ------------------------------------------------------------------ */
static void cleanup(int spi_handle)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_handle = -1;
    int adc_value;
    double current;
    int rc;

    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI0 CE0 at 1 MHz, mode 0 ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file for appending ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen log");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current logger started.  Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        rc = read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value);
        if (rc != 0) {
            fprintf(stderr, "SPI read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        current = adc_to_current(adc_value);

        if (current < V_MIN || current > V_MAX) {
            fprintf(stderr,
                    "Warning: voltage %.3f V out of range [%.1f, %.1f] – skipping sample\n",
                    current * VREF, V_MIN * VREF, V_MAX * VREF);
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_current(g_log, current) != 0) {
            fprintf(stderr, "Failed to log current reading\n");
            cleanup(spi_handle);
            return EXIT_FAILURE;
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup(spi_handle);
    return EXIT_SUCCESS;
}

