/*
 * Raspberry Pi 5 — Dual Omron B5W-DB01 proximity sensor monitor
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT  -> GPIO4  (active-low, internal pull-up)
 *   Sensor 2 OUT  -> GPIO17 (active-low, internal pull-up)
 *
 * The B5W-DB01 has an active-low digital output and an internal
 * pull-up; no analog output is available.  We read the sensor
 * five times, space reads 2 ms apart, and use the majority value.
 *
 * Build:  gcc -O2 -Wall -Wextra -o prox_monitor prox_monitor.c -lpigpio -lrt
 * Run:    sudo ./prox_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_READS 5
#define DEBOUNCE_DELAY_US 2000   /* 2 ms between reads */
#define POLL_INTERVAL_US 1000000 /* 1 s between log lines */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Debounced read of one sensor pin                                    */
/* ------------------------------------------------------------------ */
/* Returns 0 (object present / active-low) or 1 (no object / pulled-up). */
static int read_debounced(int pin)
{
    int high_count = 0;

    for (int i = 0; i < DEBOUNCE_READS; ++i) {
        int v = gpioRead(pin);
        if (v < 0) {
            fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                    pin, pigpio_error(v));
            return -1;
        }
        if (v == 1)
            ++high_count;
        if (i < DEBOUNCE_READS - 1)
            gpioDelay(DEBOUNCE_DELAY_US);
    }

    /* Majority: 0 = object present, 1 = no object */
    return (high_count > DEBOUNCE_READS / 2) ? 0 : 1;
}

/* ------------------------------------------------------------------ */
