 * pull-up; no analog output is available.  We read the sensor
 * five times, space reads 2 ms apart, and use the majority value.
 *
 * Build:  gcc -O2 -Wall -Wextra -o prox_monitor prox_monitor.c -lpigpio -lrt
 * Run:    sudo ./prox_monitor
 */

