#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <driver/spi.h>
#include <driver/spi_master.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static spi_device_handle_t spi_handle = NULL;
static volatile sig_atomic_t program_running = 1;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buf[3] = {0};

    spi_transaction_t trans = {
        .tx_buffer = tx_buf,
        .rx_buffer = rx_buf,
        .length = 3,
        .flags = 0
    };

    if (spi_device_transmit(spi_handle, &trans) != ESP_OK) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    printf("%s,%.2f\n", timestamp, moisture_level);
}

void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int spi_setup(spi_config_t config) {
    if (spi_bus_initialize(SPI_HOST, &config, 0) != ESP_OK) {
        fprintf(stderr, "Error: SPI bus initialization failed\n");
        return -1;
    }

    spi_device_interface_config_t dev_config = {
        .command_bits = 0,
        .address_bits = 0,
        .dummy_bits = 0,
        .mode = 0,
        .clock_speed_hz = SPI_BAUD,
        .input_delay_ns = 0,
        .spics_io_num = -1,
        .flags = 0,
        .queue_size = 1,
        .pre_cb = NULL,
        .post_cb = NULL
    };

    if (spi_bus_add_device(SPI_HOST, &dev_config, &spi_handle) != ESP_OK) {
        fprintf(stderr, "Error: SPI device addition failed\n");
        spi_bus_free(SPI_HOST);
        return -1;
    }

    return 0;
}

int main() {
    spi_config_t config = {
        .miso_io_num = 12,
        .mosi_io_num = 13,
        .sclk_io_num = 14,
        .quadwp_io_num = -1,
        .quadhd_io_num = -1,
        .max_transfer_sz = 0,
        .flags = 0
    };

    if (spi_setup(config) != 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    if (spi_handle != NULL) {
        spi_bus_remove_device(spi_handle);
    }
    spi_bus_free(SPI_HOST);

    return 0;
}

