#include <errno.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <pigpio.h>

#define PIR_GPIO          17
#define DEBOUNCE_MS       200
#define POLL_INTERVAL_US  50000   /* 50 ms */
#define CAPTURE_DIR       "/home/pi/security_cam"
#define CAPTURE_WIDTH     1280
#define CAPTURE_HEIGHT    720
#define CAPTURE_QUALITY   80

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/*
 * Read the PIR sensor.
 * Returns:  1  — motion confirmed
 *          0  — no motion
 *         -1  — read error
 */
static int read_pir_sensor(void)
{
    int level = gpioRead(PIR_GPIO);
    if (level < 0) {
        syslog(LOG_ERR, "gpioRead(%d) failed: %s", PIR_GPIO, strerror(errno));
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Timing                                                              */
/* ------------------------------------------------------------------ */

static void delay_ms(unsigned int ms)
{
    gpioDelay(ms * 1000); /* gpioDelay takes microseconds */
}

/* ------------------------------------------------------------------ */
/* File system                                                         */
/* ------------------------------------------------------------------ */

static int ensure_capture_directory(void)
{
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "%s exists but is not a directory", CAPTURE_DIR);
        return -1;
    }

    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat(%s) failed: %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }

    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "mkdir(%s) failed: %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Camera capture (libcamera-still)                                   */
/* ------------------------------------------------------------------ */

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child process */
        char width_str[16], height_str[16], quality_str[16];
        snprintf(width_str,  sizeof(width_str),  "%d", CAPTURE_WIDTH);
        snprintf(height_str, sizeof(height_str), "%d", CAPTURE_HEIGHT);
        snprintf(quality_str, sizeof(quality_str), "%d", CAPTURE_QUALITY);

        char *const argv[] = {
            "libcamera-still",
            "-o", (char *)filename,
            "--width",  width_str,
            "--height", height_str,
            "--quality", quality_str,
            "--encoding", "jpg",
            "--nopreview",
            NULL
        };

        execvp("libcamera-still", argv);

        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execvp(libcamera-still) failed: %s", strerror(errno));
        _exit(127);
    }

    /* Parent process */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR)
            continue;
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still failed (status=0x%04x)", status);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    if (install_signal_handlers() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_capture_directory() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on GPIO%d, %d ms debounce)",
           PIR_GPIO, DEBOUNCE_MS);

    int last_state = 0;

    while (g_running) {
        int motion = read_pir_sensor();
        if (motion < 0) {
            delay_ms(POLL_INTERVAL_US / 1000);
            continue;
        }

        if (motion != last_state) {
            delay_ms(DEBOUNCE_MS);

            int confirm = read_pir_sensor();
            if (confirm < 0) {
                delay_ms(POLL_INTERVAL_US / 1000);
                continue;
            }

            if (confirm != motion) {
                /* Transient glitch — ignore */
                last_state = confirm;
                continue;
            }

            if (motion == 1) {
                time_t rawtime;
                struct tm timeinfo;
                char timestamp[32];

                time(&rawtime);
                if (localtime_r(&rawtime, &timeinfo) == NULL) {
                    syslog(LOG_ERR, "localtime_r() failed: %s", strerror(errno));
                    last_state = confirm;
                    continue;
                }

                if (strftime(timestamp, sizeof(timestamp),
                             "%Y%m%d_%H%M%S", &timeinfo) == 0) {
                    syslog(LOG_ERR, "strftime() failed");
                    last_state = confirm;
                    continue;
                }

                char filename[256];
                int n = snprintf(filename, sizeof(filename),
                                 "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);
                if (n < 0 || (size_t)n >= sizeof(filename)) {
                    syslog(LOG_ERR, "Filename buffer too small");
                    last_state = confirm;
                    continue;
                }

                syslog(LOG_INFO, "Motion detected — capturing %s", filename);

                if (capture_image(filename) == 0) {
                    syslog(LOG_INFO, "Image saved: %s", filename);
                } else {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            }

            last_state = confirm;
        }

        delay_ms(POLL_INTERVAL_US / 1000);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

