#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE   "/dev/video0"
#define NUM_BUFFERS    4
#define FRAG_SIZE      128          /* UDP datagram payload (< 65507) */
#define FRAME_WIDTH    640
#define FRAME_HEIGHT   480
#define PIXELS_PER_FRAME ((FRAME_WIDTH * FRAME_HEIGHT) / 2) /* YUYV: 1 byte Y + 1 byte U/V */
#define MAX_FRAGMENTS  (PIXELS_PER_FRAME / FRAG_SIZE)

typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_device(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

static int init_device(int fd)
{
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP: %s\n", strerror(errno));
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = FRAME_WIDTH;
    fmt.fmt.pix.height      = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT: %s\n", strerror(errno));
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count  = NUM_BUFFERS;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", VIDEO_DEVICE);
        return -1;
    }

    buffer_t *buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        fprintf(stderr, "calloc(%d): %s\n", req.count, strerror(errno));
        return -1;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QUERYBUF[%u]: %s\n", i, strerror(errno));
            free(buffers);
            return -1;
        }
        buffers[i].length = buf.length;
        buffers[i].start  = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                                 MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "mmap[%u]: %s\n", i, strerror(errno));
            for (unsigned int j = 0; j < i; j++)
                munmap(buffers[j].start, buffers[j].length);
            free(buffers);
            return -1;
        }
    }

    for (unsigned int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF[%u]: %s\n", i, strerror(errno));
            for (unsigned int j = 0; j < req.count; j++)
                munmap(buffers[j].start, buffers[j].length);
            free(buffers);
            return -1;
        }
    }
    return 0;
}

static int start_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int unmap_buffers(buffer_t *buffers, unsigned int count)
{
    for (unsigned int i = 0; i < count; i++) {
        if (buffers[i].start != NULL &&
            buffers[i].start != MAP_FAILED) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                fprintf(stderr, "munmap[%u]: %s\n", i, strerror(errno));
                return -1;
            }
            buffers[i].start = NULL;
        }
    }
    return 0;
}

static int send_udp_fragment(int sockfd, const struct sockaddr_in *dest,
                             const char *data, size_t len,
                             uint32_t frame_index, uint32_t frag_index,
                             uint32_t total_frags, uint32_t payload_size)
{
    /*
     * Header: 12 bytes
     *   uint32_t frame_index
     *   uint32_t frag_index
     *   uint32_t total_frags
     *   uint32_t payload_size
     */
    uint8_t header[12];
    memcpy(&header[0],  &frame_index, 4);
    memcpy(&header[4],  &frag_index,  4);
    memcpy(&header[8],  &total_frags, 4);
    memcpy(&header[12], &payload_size, 4);

    size_t pkt_len = len + sizeof(header);
    uint8_t *pkt = malloc(pkt_len);
    if (!pkt) {
        fprintf(stderr, "malloc(%zu): %s\n", pkt_len, strerror(errno));
        return -1;
    }
    memcpy(pkt, header, sizeof(header));
    memcpy(pkt + sizeof(header), data, len);

    ssize_t sent = sendto(sockfd, pkt, pkt_len, 0,
                          (const struct sockaddr *)dest,
                          sizeof(*dest));
    free(pkt);

    if (sent == -1) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)sent != pkt_len) {
        fprintf(stderr, "sendto: short write (%zd of %zu)\n", sent, pkt_len);
        return -1;
    }
    return 0;
}

static int process_frame(int fd, int sockfd,
                         const struct sockaddr_in *dest,
                         uint32_t frame_index)
{
    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec  = 2;
    tv.tv_usec = 0;

    int rv = select(fd + 1, &fds, NULL, NULL, &tv);
    if (rv == -1) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select: %s\n", strerror(errno));
        return -1;
    }
    if (rv == 0) {
        fprintf(stderr, "select: timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
        return -1;
    }

    uint32_t total_frags = (PIXELS_PER_FRAME + FRAG_SIZE - 1) / FRAG_SIZE;
    if (total_frags > MAX_FRAGMENTS) total_frags = MAX_FRAGMENTS;

    for (uint32_t frag = 0; frag < total_frags; frag++) {
        size_t offset = frag * FRAG_SIZE;
        size_t frag_len = FRAG_SIZE;
        if (offset + frag_len > PIXELS_PER_FRAME)
            frag_len = PIXELS_PER_FRAME - offset;

        if (send_udp_fragment(sockfd, dest,
                              (const char *)buf.m.userptr + offset,
                              frag_len, frame_index, frag,
                              total_frags, frag_len) == -1) {
            return -1;
        }
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *target_ip   = argv[1];
    int         target_port = atoi(argv[2]);
    if (target_port <= 0 || target_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    int fd = open_device(VIDEO_DEVICE);
    if (fd == -1)
        return EXIT_FAILURE;

    buffer_t *buffers = NULL;
    int rc = EXIT_FAILURE;

    if (init_device(fd) == -1)
        goto cleanup;

    if (start_streaming(fd) == -1)
        goto cleanup;

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        goto cleanup;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_port        = htons((uint16_t)target_port);
    if (inet_pton(AF_INET, target_ip, &addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid IP address: %s\n", target_ip);
        goto cleanup;
    }

    uint32_t frame_index = 0;
    while (!g_stop) {
        if (process_frame(fd, sockfd, &addr, frame_index) == -1) {
            if (g_stop) break;
            fprintf(stderr, "Frame processing failed; continuing.\n");
        } else {
            frame_index++;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (sockfd != -1) close(sockfd);
    if (fd != -1) {
        stop_streaming(fd);
        unmap_buffers(buffers, NUM_BUFFERS);
        close(fd);
    }
    return rc;
}

