        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR, 0);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = 1;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", DEVICE_NAME);
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        goto cleanup;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("mmap");
            buffers[n_buffers].start = NULL;
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto streamoff;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Dequeued buffer has zero bytesused\n");
        goto streamoff;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen(" IMAGE_FILE ")");
        goto streamoff;
    }

    if (fwrite(buffers[buf.index].start, 1, buf.bytesused, fp) != buf.bytesused) {
        perror("fwrite");
        goto closefile;
    }

    printf("Saved %u bytes to %s\n", buf.bytesused, IMAGE_FILE);
    ret = EXIT_SUCCESS;

closefile:
    if (fclose(fp) == EOF) {
        perror("fclose");
        ret = EXIT_FAILURE;
    }
streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        ret = EXIT_FAILURE;
    }

cleanup:
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
                if (munmap(buffers[i].start, buffers[i].length) == -1) {
                    perror("munmap");
                }
            }
        }
        free(buffers);
    }
    if (fd != -1) {
        if (close(fd) == -1) {
            perror("close");
            ret = EXIT_FAILURE;
        }
    }
    return ret;
}

