    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        goto streamoff;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Dequeued buffer has zero bytesused\n");
        goto streamoff;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen(" IMAGE_FILE ")");
        goto streamoff;
    }

    if (fwrite(buffers[buf.index].start, 1, buf.bytesused, fp) != buf.bytesused) {
        perror("fwrite");
        goto closefile;
    }

    printf("Saved %u bytes to %s\n", buf.bytesused, IMAGE_FILE);
    ret = EXIT_SUCCESS;

closefile:
    if (fclose(fp) == EOF) {
        perror("fclose");
        ret = EXIT_FAILURE;
    }
streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        ret = EXIT_FAILURE;
    }

cleanup:
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
                if (munmap(buffers[i].start, buffers[i].length) == -1) {
                    perror("munmap");
                }
            }
        }
        free(buffers);
    }
    if (fd != -1) {
        if (close(fd) == -1) {
            perror("close");
            ret = EXIT_FAILURE;
        }
    }
    return ret;
}

