/*
 * Camera pan-tilt mount control for Raspberry Pi using libgpiod.
 *
 * Wiring (BCM numbering):
 *   GPIO4  -> Pan  servo signal
 *   GPIO5  -> Tilt servo signal
 *   GPIO6  -> Tilt-up button (internal pull-up)
 *   GPIO7  -> Tilt-down button (internal pull-up)
 *   GPIO8  -> Pan-left  button (internal pull-up)
 *   GPIO9  -> Pan-right button (internal pull-up)
 *
 * PWM: 50 Hz, period 20 ms, duty 1 ms -> 50, duty 2 ms -> 100.
 * Mid-position = 75.
 *
 * Build: gcc -O2 -Wall -Wextra -o pantilt pantilt.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define PAN_PIN        4
#define TILT_PIN       5
#define TILT_UP_PIN    6
#define TILT_DOWN_PIN  7
#define PAN_LEFT_PIN   8
#define PAN_RIGHT_PIN  9

#define PWM_PERIOD_MS  20          /* 50 Hz */
#define PWM_MIN_DUTY   50          /* 1 ms  -> 50/1000 */
#define PWM_MID_DUTY   75          /* 1.5 ms-> 75/1000 */
#define PWM_MAX_DUTY   100         /* 2 ms  -> 100/1000 */

#define MIN_POS        25
#define MAX_POS        125
#define STEP            5

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static long long now_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

static int set_pwm(struct gpiod_line *line, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;

    /* libgpiod has no hardware-PWM abstraction; we use a software-PWM-like
     * approach: drive the line high for duty ms, low for (100 - duty) ms. */
    long long on_ms  = (long long)duty * PWM_PERIOD_MS / 100;
    long long off_ms = PWM_PERIOD_MS - on_ms;

    if (on_ms > 0) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "set_value(1) failed: %s\n", strerror(errno));
            return -1;
        }
        usleep(on_ms * 1000);
    }
    if (off_ms > 0) {
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "set_value(0) failed: %s\n", strerror(errno));
            return -1;
        }
        usleep(off_ms * 1000);
    }
    return 0;
}

static int set_servo(struct gpiod_line *line, int pos)
{
    if (pos < MIN_POS) pos = MIN_POS;
    if (pos > MAX_POS) pos = MAX_POS;

    int duty = PWM_MIN_DUTY + (pos - MIN_POS) * (PWM_MAX_DUTY - PWM_MIN_DUTY) /
               (MAX_POS - MIN_POS);
    return set_pwm(line, duty);
}

static int read_button(struct gpiod_line *line)
{
    int v = gpiod_line_get_value(line);
    if (v < 0) {
        fprintf(stderr, "read_value failed: %s\n", strerror(errno));
        return -1;
    }
    return v;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL;
    struct gpiod_line *tilt_up = NULL, *tilt_down = NULL;
    struct gpiod_line *pan_left = NULL, *pan_right = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line   = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line  = gpiod_chip_get_line(chip, TILT_PIN);
    tilt_up    = gpiod_chip_get_line(chip, TILT_UP_PIN);
    tilt_down  = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    pan_left   = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    pan_right  = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_line || !tilt_line || !tilt_up || !tilt_down ||
        !pan_left || !pan_right) {
        fprintf(stderr, "gpiod_chip_get_line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pantilt-pan", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "pantilt-tilt", 0) < 0) {
        fprintf(stderr, "request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(tilt_up, "pantilt-tilt-up",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(tilt_down, "pantilt-tilt-down",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(pan_left, "pantilt-pan-left",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0 ||
        gpiod_line_request_input_flags(pan_right, "pantilt-pan-right",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "request_input_flags failed: %s\n", strerror(errno));
        goto cleanup;
    }

    int pan_pos = PWM_MID_DUTY;
    int tilt_pos = PWM_MID_DUTY;

    while (g_running) {
        int tu = read_button(tilt_up);
        int td = read_button(tilt_down);
        int pl = read_button(pan_left);
        int pr = read_button(pan_right);

        if (tu < 0 || td < 0 || pl < 0 || pr < 0) {
            fprintf(stderr, "Button read error, continuing...\n");
            usleep(50 * 1000);
            continue;
        }

        if (tu == 0) { tilt_pos += STEP; if (tilt_pos > MAX_POS) tilt_pos = MAX_POS; }
        if (td == 0) { tilt_pos -= STEP; if (tilt_pos < MIN_POS) tilt_pos = MIN_POS; }
        if (pl == 0) { pan_pos -= STEP;  if (pan_pos  < MIN_POS) pan_pos  = MIN_POS; }
        if (pr == 0) { pan_pos += STEP;  if (pan_pos  > MAX_POS) pan_pos  = MAX_POS; }

        if (set_servo(pan_line, pan_pos) < 0 || set_servo(tilt_line, tilt_pos) < 0) {
            fprintf(stderr, "Servo set failed, exiting.\n");
            goto cleanup;
        }

        usleep(50 * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line)   gpiod_line_release(pan_line);
    if (tilt_line)  gpiod_line_release(tilt_line);
    if (tilt_up)    gpiod_line_release(tilt_up);
    if (tilt_down)  gpiod_line_release(tilt_down);
    if (pan_left)   gpiod_line_release(pan_left);
    if (pan_right)  gpiod_line_release(pan_right);
    if (chip)       gpiod_chip_close(chip);
    return ret;
}

