#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int blur_image(unsigned char *rgb, int width, int height, int stride) {
    unsigned char *tmp = malloc((size_t)width * height * 3);
    if (!tmp) {
        fprintf(stderr, "malloc failed for blur temp buffer\n");
        return -1;
    }
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int y = i + di, x = j + dj;
                    if (y >= 0 && y < height && x >= 0 && x < width) {
                        int idx = y * stride + x * 2;
                        int y0 = rgb[idx];
                        int u  = rgb[idx + 1];
                        int y1 = rgb[idx + 2];
                        int v  = rgb[idx + 3];
                        int cr = u - 128, cg = v - 128;
                        int r0 = y0 + cr + (cr >> 1) + (cr >> 2);
                        int g0 = y0 - cg + (cg >> 1) + (cg >> 2);
                        int b0 = y0 + cg + (cg >> 1);
                        if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
                        if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
                        if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
                        sum_r += r0; sum_g += g0; sum_b += b0;
                    }
                }
            }
            int idx = i * stride + j * 3;
            tmp[idx]     = (sum_r / 9);
            tmp[idx + 1] = (sum_g / 9);
            tmp[idx + 2] = (sum_b / 9);
        }
    }
    memcpy(rgb, tmp, (size_t)width * height * 3);
    free(tmp);
    return 0;
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, int quality) {
    FILE *fp = fopen("capture.jpg", "wb");
    if (!fp) {
        fprintf(stderr, "fopen(capture.jpg) failed: %s\n", strerror(errno));
        return -1;
    }
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, fp);
    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row[0] = (unsigned char *)rgb + cinfo.next_scanline * width * 3;
        jpeg_write_scanlines(&cinfo, row, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(/dev/video0) failed: %s\n", strerror(errno));
        return 1;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        close(fd);
        return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming I/O\n");
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    if (select(fd + 1, &fds, NULL, NULL, &tv) == -1) {
