    int width = fmt.fmt.pix.width;
    int height = fmt.fmt.pix.height;
    int stride = width * 2;
    unsigned char *rgb = malloc((size_t)width * height * 3);
    if (!rgb) {
        fprintf(stderr, "malloc failed for RGB buffer\n");
        goto cleanup;
    }

    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int idx = i * stride + j * 2;
            int y0 = ((unsigned char *)buffer)[idx];
            int u  = ((unsigned char *)buffer)[idx + 1];
            int y1 = ((unsigned char *)buffer)[idx + 2];
