        fprintf(stderr, "JPEG encode failed\n");
        free(rgb);
        goto cleanup;
    }

    printf("Image captured and saved as capture.jpg\n");
    free(rgb);

cleanup:
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type);
    munmap(buffer, buf.length);
    close(fd);
    return 0;
