#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int blur_image(unsigned char *rgb, int width, int height, int stride) {
    unsigned char *tmp = malloc((size_t)width * height * 3);
    if (!tmp) {
        fprintf(stderr, "malloc failed for blur temp buffer\n");
        return -1;
    }
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int y = i + di, x = j + dj;
                    if (y >= 0 && y < height && x >= 0 && x < width) {
                        int idx = y * stride + x * 2;
                        int y0 = rgb[idx];
                        int u  = rgb[idx + 1];
                        int y1 = rgb[idx + 2];
                        int v  = rgb[idx + 3];
                        int cr = u - 128, cg = v - 128;
                        int r0 = y0 + cr + (cr >> 1) + (cr >> 2);
                        int g0 = y0 - cg + (cg >> 1) + (cg >> 2);
                        int b0 = y0 + cg + (cg >> 1);
                        if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
                        if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
                        if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
                        sum_r += r0; sum_g += g0; sum_b += b0;
                    }
                }
            }
            int idx = i * stride + j * 3;
            tmp[idx]     = (sum_r / 9);
            tmp[idx + 1] = (sum_g / 9);
            tmp[idx + 2] = (sum_b / 9);
        }
    }
    memcpy(rgb, tmp, (size_t)width * height * 3);
    free(tmp);
    return 0;
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, int quality) {
    FILE *fp = fopen("capture.jpg", "wb");
    if (!fp) {
        fprintf(stderr, "fopen(capture.jpg) failed: %s\n", strerror(errno));
        return -1;
    }
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, fp);
    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    JSAMPROW row[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row[0] = (unsigned char *)rgb + cinfo.next_scanline * width * 3;
        jpeg_write_scanlines(&cinfo, row, 1);
    }
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(fp);
    return 0;
}

