    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(/dev/video0) failed: %s\n", strerror(errno));
        return 1;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        close(fd);
        return 1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming I/O\n");
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
