/*
 * v4l2_csi_info.c — Summarize a CSI camera's V4L2 capabilities.
 *
 * Build:  gcc -O2 -Wall -Wextra -o v4l2_csi_info v4l2_csi_info.c
 * Run:    ./v4l2_csi_info
 *
 * Prerequisites:
 *   - A CSI camera must be connected to the Raspberry Pi's CSI port
 *     (e.g. a Raspberry Pi 400 with a Raspberry Pi Camera Module V2).
 *   - The kernel must have V4L2 support compiled in and the device
 *     node must exist (typically /dev/video0).
 */

#include <errno.h>
#include <fcntl.h>
#include <linux/videodev2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void print_capability(const struct v4l2_capability *cap)
{
    printf("Capabilities:\n");
    printf("  Driver : %s\n", cap->driver);
    printf("  Card   : %s\n", cap->card);
    printf("  Bus    : %s\n", cap->bus_info);
    printf("  Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8) & 0xFF,
           cap->version & 0xFF);
    printf("  Caps   : 0x%08x\n", cap->capabilities);
}

static void print_frame_size(const struct v4l2_frmsizeenum *fse)
{
    printf("    %ux%u\n", fse->discrete.width, fse->discrete.height);
}

static void print_frame_interval(const struct v4l2_frmivalenum *fie)
{
    if (fie->type == V4L2_FRMIVAL_TYPE_DISCRETE)
        printf("      %u/%u fps\n", fie->discrete.numerator, fie->discrete.denominator);
    else
        printf("      Stepwise: %u/%u - %u/%u fps\n",
               fie->stepwise.min.numerator, fie->stepwise.min.denominator,
               fie->stepwise.max.numerator, fie->stepwise.max.denominator);
}

static void print_focus_info(int fd)
{
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &qc) == -1) {
        if (errno == EINVAL)
            printf("  Autofocus: Not supported\n");
        else
            fprintf(stderr, "Warning: VIDIOC_QUERYCTRL failed: %s\n", strerror(errno));
        return;
    }

    printf("  Autofocus: Supported (CID_FOCUS_AUTO, %s)\n",
           qc.flags & V4L2_CTRL_FLAG_DISABLED ? "disabled" : "enabled");
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("CSI Camera Information\n");
    printf("======================\n");
    print_capability(&cap);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("\nSupported Resolutions:\n");
    struct v4l2_frmsizeenum fse;
    memset(&fse, 0, sizeof(fse));
    fse.index = 0;

    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) == 0) {
        if (fse.pixel_format != V4L2_PIX_FMT_YUYV)
            continue;

        printf("  %ux%u:\n", fse.discrete.width, fse.discrete.height);

        struct v4l2_frmivalenum fie;
        memset(&fie, 0, sizeof(fie));
        fie.index = 0;
        fie.width = fse.discrete.width;
        fie.height = fse.discrete.height;

        while (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fie) == 0) {
            print_frame_interval(&fie);
            fie.index++;
        }

        if (errno != EINVAL) {
            fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        fse.index++;
    }

    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("\nAutofocus Capability:\n");
    print_focus_info(fd);

    close(fd);
    return EXIT_SUCCESS;
}

