#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH  1000
#define MAX_PULSE_WIDTH  2000
#define CENTER_PULSE     1500
#define PULSE_INCREMENT  10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH)
        pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH)
        pulse_width = MAX_PULSE_WIDTH;

    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pw=%d)\n", pin, pulse_width);
        return -1;
    }
