#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <jansson.h>
#include <curl/curl.h>

#define PIR_PIN 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define IMAGE_QUALITY 85
#define MOTION_STATUS "motion_detected"
#define MOTION_STATUS_FALSE "motion_not_detected"
#define CAPTURE_DIR "motion_captures"

static volatile sig_atomic_t running = 1;
static char *ip_address = NULL;
static int port = 0;
static int pigpio_initialized = 0;
static int curl_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspistill -q %d -o %s", IMAGE_QUALITY, filename);
    int result = system(command);
    if (result == -1) {
        perror("system() failed");
        return -1;
    }
    if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "raspistill exited with status %d\n", WEXITSTATUS(result));
        return -1;
    }
    return 0;
}

static char *generate_timestamp(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return NULL;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char *timestamp = malloc(32);
    if (!timestamp) {
        perror("malloc");
        return NULL;
    }
    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, 32 - len, ".%06ld", ts.tv_nsec / 1000);
    return timestamp;
}

static char *generate_filename(const char *timestamp) {
    char *filename = malloc(256);
    if (!filename) {
        perror("malloc");
        return NULL;
    }
    snprintf(filename, 256, "%s/%s.jpg", CAPTURE_DIR, timestamp);
    return filename;
}

static json_t *create_json_payload(const char *filename, const char *timestamp,
                                   const char *motion_status, int gpio_pin) {
    json_t *root = json_object();
    if (!root) {
        fprintf(stderr, "Failed to create JSON object\n");
        return NULL;
    }
    if (json_object_set_new(root, "filename", json_string(filename)) != 0) {
        fprintf(stderr, "Failed to set filename\n");
        json_decref(root);
        return NULL;
    }
    if (json_object_set_new(root, "timestamp", json_string(timestamp)) != 0) {
        fprintf(stderr, "Failed to set timestamp\n");
        json_decref(root);
        return NULL;
    }
    if (json_object_set_new(root, "motion_status", json_string(motion_status)) != 0) {
        fprintf(stderr, "Failed to set motion_status\n");
        json_decref(root);
        return NULL;
    }
    if (json_object_set_new(root, "gpio_pin", json_integer(gpio_pin)) != 0) {
        fprintf(stderr, "Failed to set gpio_pin\n");
        json_decref(root);
        return NULL;
    }
    return root;
}

static int post_data(const char *json_string, const char *image_data, size_t image_size) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    char url[512];
    snprintf(url, sizeof(url), "http://%s:%d/upload", ip_address, port);

    struct curl_httppost *formpost = NULL;
    struct curl_httppost *lastptr = NULL;

    if (image_data && image_size > 0) {
        curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image",
                     CURLFORM_BUFFER, "image.jpg",
                     CURLFORM_BUFFERPTR, image_data,
                     CURLFORM_BUFFERLENGTH, (long)image_size,
                     CURLFORM_END);
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));
    curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (formpost) curl_formfree(formpost);

    return (res == CURLE_OK) ? 0 : -1;
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (curl_initialized) {
        curl_global_cleanup();
        curl_initialized = 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <ip_address> <port>\n", argv[0]);
        return 1;
    }

    ip_address = argv[1];
    port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_PIN);
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", PIR_PIN);
        cleanup();
        return 1;
    }

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "curl_global_init() failed\n");
        cleanup();
        return 1;
    }
    curl_initialized = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        cleanup();
        return 1;
    }

    printf("Monitoring PIR sensor on GPIO%d... Press Ctrl+C to exit.\n", PIR_PIN);

    while (running) {
        int motion_detected = gpioRead(PIR_PIN);
        if (motion_detected < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", PIR_PIN);
            break;
        }

        if (motion_detected) {
            printf("Motion detected!\n");
            char *timestamp = generate_timestamp();
            if (!timestamp) {
                fprintf(stderr, "Failed to generate timestamp\n");
                break;
            }

            char *filename = generate_filename(timestamp);
            if (!filename) {
                free(timestamp);
                fprintf(stderr, "Failed to generate filename\n");
                break;
            }

            if (capture_image(filename) != 0) {
                fprintf(stderr, "Failed to capture image\n");
                free(filename);
                free(timestamp);
                break;
            }

            json_t *json_payload = create_json_payload(filename, timestamp,
                                                       MOTION_STATUS, PIR_PIN);
            if (!json_payload) {
                fprintf(stderr, "Failed to create JSON payload\n");
                free(filename);
                free(timestamp);
                break;
            }

            char *json_string = json_dumps(json_payload, JSON_REAL_PRECISION(9));
            json_decref(json_payload);
            if (!json_string) {
                fprintf(stderr, "Failed to serialize JSON\n");
                free(filename);
                free(timestamp);
                break;
            }

            FILE *fp = fopen(filename, "rb");
            if (!fp) {
                perror("fopen");
                free(json_string);
                free(filename);
                free(timestamp);
                break;
            }

            fseek(fp, 0, SEEK_END);
            long file_size = ftell(fp);
            fseek(fp, 0, SEEK_SET);

            char *image_data = malloc(file_size);
            if (!image_data) {
                perror("malloc");
                fclose(fp);
                free(json_string);
                free(filename);
                free(timestamp);
                break;
            }

            if (fread(image_data, 1, file_size, fp) != (size_t)file_size) {
                fprintf(stderr, "Failed to read image file\n");
                free(image_data);
                fclose(fp);
                free(json_string);
                free(filename);
                free(timestamp);
                break;
            }

            fclose(fp);

            if (post_data(json_string, image_data, (size_t)file_size) != 0) {
                fprintf(stderr, "Failed to post data\n");
            }

            free(image_data);
            free(json_string);
            free(filename);
            free(timestamp);

            sleep(DEBOUNCE_SEC);
        } else {
            gpioDelay(POLL_INTERVAL_US);
        }
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

