#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>

#define PIR_GPIO_PIN 17
#define IMAGES_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int ensure_images_dir(void) {
    struct stat st;
    if (stat(IMAGES_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", IMAGES_DIR);
        return -1;
    }
    if (mkdir(IMAGES_DIR, 0755) != 0) {
        perror("Error creating images directory");
        return -1;
    }
    return 0;
}

static int capture_image(void) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[64];
    char command[256];
    char log_message[300];

    snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
             IMAGES_DIR,
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec,
             (int)(tm.tm_sec * 1000 + tm.tm_usec / 1000));

    snprintf(command, sizeof(command),
             "raspistill -o %s --width 640 --height 480 -q 85 --timeout %d --nopreview",
             filename, CAPTURE_TIMEOUT_MS);

    int result = system(command);
    if (result == -1) {
        snprintf(log_message, sizeof(log_message),
                 "Error: system() failed to execute raspistill: %s", strerror(errno));
        log_message(log_message);
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        snprintf(log_message, sizeof(log_message),
                 "Error: raspistill failed (raw=%d, exit=%d)",
                 result, WIFEXITED(result) ? WEXITSTATUS(result) : -1);
        log_message(log_message);
        return -1;
    }

    snprintf(log_message, sizeof(log_message), "Image captured: %s", filename);
    log_message(log_message);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error registering SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error registering SIGTERM handler");
        return 1;
    }

    if (ensure_images_dir() != 0) {
        return 1;
    }

    log_message("Motion capture service started");

    while (program_running) {
        int ret = wait_for_edge(PIR_GPIO_PIN, 0, DEBOUNCE_DELAY_MS);
        if (ret == 0) {
            if (capture_image() != 0) {
                log_message("Failed to capture image");
            }
        } else if (ret < 0) {
            log_message("Error waiting for PIR edge");
        }
    }

    log_message("Motion capture service stopped");
    return 0;
}

