/*
 * capture_crop.c — V4L2 YUYV capture with cropping on Raspberry Pi.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_crop capture_crop.c
 * Run:    ./capture_crop   (needs /dev/video0 and V4L2 permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_WIDTH  640
#define CAPTURE_HEIGHT 480
#define CROP_WIDTH     200
#define CROP_HEIGHT    150
#define FILENAME       "cropped.yuv"

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    void *buffer = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAPTURE_WIDTH;
    fmt.fmt.pix.height = CAPTURE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        goto cleanup;
    }
    if (fmt.fmt.pix.width != CAPTURE_WIDTH || fmt.fmt.pix.height != CAPTURE_HEIGHT) {
        fprintf(stderr, "Warning: driver adjusted format to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }
    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }
    if (xioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    while (!g_stop) {
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            perror("select");
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            goto cleanup;
        }

        if (buf.index != 0) {
            fprintf(stderr, "Unexpected buffer index %u\n", buf.index);
            goto cleanup;
        }

        if (buf.bytesused < (size_t)(CROP_WIDTH * CROP_HEIGHT * 2)) {
            fprintf(stderr, "Short frame: %u bytes\n", buf.bytesused);
            goto loop_continue;
        }

        if (buf.width != CAPTURE_WIDTH || buf.height != CAPTURE_HEIGHT ||
            buf.format.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Frame dimensions/format mismatch: %ux%u %s\n",
                    buf.width, buf.height,
                    buf.format.pixelformat == V4L2_PIX_FMT_YUYV ? "YUYV" : "UNKNOWN");
            goto loop_continue;
        }

        size_t crop_offset = (CROP_WIDTH / 2) * (CROP_HEIGHT / 2) * 2;
        size_t crop_size = (size_t)CROP_WIDTH * CROP_HEIGHT * 2;

        fp = fopen(FILENAME, "wb");
        if (!fp) {
            perror("fopen(" FILENAME ")");
            goto loop_continue;
        }

        size_t written = fwrite(buffer + crop_offset, 1, crop_size, fp);
        if (written != crop_size) {
            perror("fwrite");
            fclose(fp);
            fp = NULL;
            goto loop_continue;
        }

        if (fclose(fp) != 0) {
            perror("fclose");
            fp = NULL;
            goto loop_continue;
        }
        fp = NULL;

        printf("Cropped %ux%u YUYV frame saved as %s (%zu bytes)\n",
               CROP_WIDTH, CROP_HEIGHT, FILENAME, crop_size);

    loop_continue:
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
    }
    if (buffer && buffer != MAP_FAILED) {
        if (munmap(buffer, buffer_size) < 0) {
            perror("munmap");
        }
    }
    if (fp) {
        if (fclose(fp) != 0) {
            perror("fclose");
        }
    }
    if (fd >= 0) {
        if (close(fd) < 0) {
            perror("close");
        }
    }
    return ret;
}

