/*
 * Raspberry Pi 4 Model B — dual SG90 servo controller
 *
 * Reads arrow-key presses (left/right/up/down) and the 'q' character from stdin
 * and drives two SG90 servos on GPIO17 (pan) and GPIO18 (tilt) using the
 * pigpio hardware PWM bus.  Each servo is moved in 5-degree steps; angles
 * are clamped to [0, 180].  Cleanup on SIGINT/SIGTERM: servos are set to
 * neutral (90°) and pigpio is terminated.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_ctrl servo_ctrl.c -lpigpio -lrt
 * Run:    sudo ./servo_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    17
#define TILT_SERVO_PIN   18

#define SERVO_MIN_PULSE  500   /* microseconds  -> ~0°   */
#define SERVO_MAX_PULSE  2500  /* microseconds  -> ~180° */
#define SERVO_NEUTRAL    1500  /* microseconds  -> ~90°  */

#define STEP_DEGREES     5
#define LOOP_DELAY_US    100000  /* 100 ms between commands */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Convert a 0–180° angle to a 50 Hz servo pulse width in microseconds. */
static int angle_to_pulse(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return SERVO_MIN_PULSE +
           (int)((long)angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
}

/* ------------------------------------------------------------------ */
/* Set a servo to the given angle; returns 0 on success, -1 on error.  */
static int set_servo_angle(int pin, int angle)
{
    int pulse = angle_to_pulse(angle);
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pulse=%d) failed\n",
                pin, pulse);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int move_servo(int pin, int *angle, int delta)
{
    *angle += delta;
    if (*angle < 0)       *angle = 0;
    if (*angle > 180)     *angle = 180;

    if (set_servo_angle(pin, *angle) != 0)
        return -1;

    printf("Servo on GPIO%d moved to %d°\n", pin, *angle);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Return both servos to neutral before releasing pigpio. */
    gpioServo(PAN_SERVO_PIN,  SERVO_NEUTRAL);
    gpioServo(TILT_SERVO_PIN, SERVO_NEUTRAL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT,  &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Center both servos at startup ---- */
    if (set_servo_angle(PAN_SERVO_PIN,  90) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, 90) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo control ready.  Pan=GPIO%d  Tilt=GPIO%d\n",
           PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Press arrow keys (left/right/up/down) or 'q' to quit.\n");

    int pan_angle   = 90;
    int tilt_angle  = 90;

    /* ---- Main command loop ---- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            if (feof(stdin))
                break;          /* stdin closed — exit cleanly */
            /* If not EOF, keep looping; getchar() may return EOF later. */
        }

        switch (c) {
        case 'q':
        case 'Q':
            printf("Quitting.\n");
            g_running = 0;
            break;

        case '\033':            /* Escape — skip the next char */
            (void)getchar();    /* discard */
            break;

        case '[':               /* Start of an arrow-key sequence */
            c = getchar();
            if (c == 'A') {     /* Up    */
                if (move_servo(TILT_SERVO_PIN, &tilt_angle, -STEP_DEGREES) != 0)
                    goto fail;
            } else if (c == 'B') { /* Down  */
                if (move_servo(TILT_SERVO_PIN, &tilt_angle,  STEP_DEGREES) != 0)
                    goto fail;
            } else if (c == 'C') { /* Right */
                if (move_servo(PAN_SERVO_PIN,  &pan_angle,   STEP_DEGREES) != 0)
                    goto fail;
            } else if (c == 'D') { /* Left  */
                if (move_servo(PAN_SERVO_PIN,  &pan_angle,   -STEP_DEGREES) != 0)
                    goto fail;
            }
            break;

        default:
            /* Ignore other characters */
            break;
        }

        if (g_running)
            gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;

fail:
    cleanup();
    return EXIT_FAILURE;
}

