#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <lcd.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static volatile double current_flow_rate = 0.0;
static volatile double total_volume = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        uint32_t diff = tick - last_pulse_tick;
        if (diff > 0 && diff < 1000000) {
            pulse_count++;
        }
        last_pulse_tick = tick;
    }
}

static double calculate_flow_rate(uint32_t pulses, uint32_t last_pulses, double time_diff) {
    double flow_rate = 0.0;
    if (time_diff > 0.0) {
        uint32_t pulse_diff = pulses - last_pulses;
        flow_rate = (double)pulse_diff / time_diff;
    }
    return flow_rate;
}

static void log_data(double flow_rate, double total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Flow Rate: %.2f L/min | Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
}

static int update_lcd(double flow_rate, double total_volume) {
    char line1[16];
    char line2[16];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Total: %.2f L", total_volume);

    if (lcdInit(I2C_BUS, LCD_ADDR, 2, 16) != 0) {
        fprintf(stderr, "Error: Failed to initialize LCD.\n");
        return -1;
    }

    lcdClear();
    lcdPosition(0, 0);
    lcdPuts(line1);
    lcdPosition(1, 0);
    lcdPuts(line2);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO %d.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    uint32_t last_pulse_count = 0;
    time_t last_log_time = time(NULL);
    time_t last_lcd_update_time = time(NULL);

    while (running) {
        time_t current_time = time(NULL);

        if (difftime(current_time, last_log_time) >= 1.0) {
            uint32_t pulses = pulse_count;
            double time_diff = difftime(current_time, last_log_time);
            double flow_rate = calculate_flow_rate(pulses, last_pulse_count, time_diff);
            total_volume += flow_rate * time_diff / 60.0;

            log_data(flow_rate, total_volume);

            last_pulse_count = pulses;
            last_log_time = current_time;
        }

        if (difftime(current_time, last_lcd_update_time) >= 10.0) {
            if (update_lcd(current_flow_rate, total_volume) != 0) {
                fprintf(stderr, "Warning: LCD update failed.\n");
            }
            last_lcd_update_time = current_time;
        }

        gpioDelay(100000);
    }

    printf("\nShutting down gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

