        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    uint32_t last_pulse_count = 0;
    time_t last_log_time = time(NULL);
    time_t last_lcd_update_time = time(NULL);

    while (running) {
        time_t current_time = time(NULL);

        if (difftime(current_time, last_log_time) >= 1.0) {
            uint32_t pulses = pulse_count;
            double time_diff = difftime(current_time, last_log_time);
            double flow_rate = calculate_flow_rate(pulses, last_pulse_count, time_diff);
            total_volume += flow_rate * time_diff / 60.0;

            log_data(flow_rate, total_volume);

            last_pulse_count = pulses;
            last_log_time = current_time;
        }

        if (difftime(current_time, last_lcd_update_time) >= 10.0) {
            if (update_lcd(current_flow_rate, total_volume) != 0) {
                fprintf(stderr, "Warning: LCD update failed.\n");
            }
            last_lcd_update_time = current_time;
        }

        gpioDelay(100000);
    }

    printf("\nShutting down gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

