#define LCD_COLS               16
#define LCD_ROWS               2
#define LCD_CHR                1
#define LCD_CMD                0
#define LCD_BACKLIGHT          0x08
#define LCD_ENABLE             0x04
#define LCD_RW                 0x02
#define LCD_RS                 0x01

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static volatile uint32_t     g_last_tick   = 0;

/* --------------------------- Forward declarations ------------------------ */

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  read_mcp3008(int spi_handle, int channel, int *out_value);
static int  read_wind_direction(int spi_handle, int *out_direction);
static void lcd_send_byte(int handle, uint8_t val, uint8_t mode);
static void lcd_string(int handle, const char *s);
static void lcd_clear(int handle);
static void lcd_set_cursor(int handle, int col, int row);
static void lcd_init(int handle);
static void cleanup(int spi_handle, int i2c_handle);
static void signal_handler(int sig);

/* ------------------------------ Anemometer ------------------------------- */

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
