/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0 on success, -1 on error.
 */
static int read_mcp3008(int spi_handle, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

