     *                   4 = S, 5 = SW, 6 = W, 7 = NW.
     * Map 10-bit ADC value to 8 directions.
     */
    int dir = (adc_value * 8) / 1024;
    if (dir < 0) dir = 0;
    if (dir > 7) dir = 7;

