}

static void lcd_set_cursor(int handle, int col, int row)
{
    int addr = (row == 0) ? 0x00 : 0x40;
    addr += col;
    lcd_send_byte(handle, 0x80 | (uint8_t)addr, LCD_CMD);
}

static void lcd_init(int handle)
{
    gpioDelay(50000);                 /* wait > 40 ms after power-on */

    /* Force 4-bit mode (HD44780 datasheet) */
    lcd_send_byte(handle, 0x30, LCD_CMD);
    gpioDelay(5000);
    lcd_send_byte(handle, 0x30, LCD_CMD);
    gpioDelay(1000);
    lcd_send_byte(handle, 0x30, LCD_CMD);
    gpioDelay(1000);
    lcd_send_byte(handle, 0x20, LCD_CMD);  /* switch to 4-bit */
    gpioDelay(1000);

    /* Function set: 4-bit, 2-line, 5x8 font */
    lcd_send_byte(handle, 0x28, LCD_CMD);
    gpioDelay(1000);

    /* Display off */
    lcd_send_byte(handle, 0x08, LCD_CMD);
    gpioDelay(1000);

    /* Clear display */
    lcd_clear(handle);

    /* Entry mode: increment, no shift */
    lcd_send_byte(handle, 0x06, LCD_CMD);
    gpioDelay(1000);

    /* Display on, cursor off, blink off */
    lcd_send_byte(handle, 0x0C, LCD_CMD);
    gpioDelay(1000);
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(int spi_handle, int i2c_handle)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    int spi_handle = -1;
    int i2c_handle = -1;
    int ret = EXIT_FAILURE;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init (MCP3008 on CE0) --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        goto cleanup_gpio;
    }

    /* --- I2C init (PCF8574 backpack) --- */
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, LCD_ADDR, i2c_handle);
        goto cleanup_spi;
    }

    /* --- LCD init --- */
    lcd_init(i2c_handle);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        goto cleanup_all;
    }

    /* --- Anemometer ISR --- */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", ANEMOMETER_GPIO);
        goto cleanup_all;
    }
    if (gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", ANEMOMETER_GPIO);
        goto cleanup_all;
    }
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0,
                         anemometer_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed for GPIO%d\n", ANEMOMETER_GPIO);
        goto cleanup_all;
    }

    printf("Wind monitor running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        /* Wind speed: pulses per 500 ms * (3.6 km/h per pulse) */
        float wind_speed = (float)pulses * 0.277778f;

        int wind_direction = -1;
        if (read_wind_direction(spi_handle, &wind_direction) != 0) {
            fprintf(stderr, "Warning: failed to read wind direction\n");
            wind_direction = -1;
        }

        char line1[LCD_COLS + 1];
        char line2[LCD_COLS + 1];

        if (wind_direction < 0) {
            snprintf(line1, sizeof(line1), "Wind: %.1f km/h", wind_speed);
            snprintf(line2, sizeof(line2), "Dir: N/A");
        } else {
            snprintf(line1, sizeof(line1), "Wind: %.1f km/h", wind_speed);
            snprintf(line2, sizeof(line2), "Dir: %d deg", wind_direction);
        }

        lcd_clear(i2c_handle);
        lcd_set_cursor(i2c_handle, 0, 0);
        lcd_string(i2c_handle, line1);
        lcd_set_cursor(i2c_handle, 0, 1);
        lcd_string(i2c_handle, line2);

        printf("Wind: %.1f km/h | Dir: %d deg\n",
               wind_speed, wind_direction);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);
    lcd_clear(i2c_handle);
    lcd_string(i2c_handle, "Shutting down");
    gpioDelay(2000000);
    cleanup(spi_handle, i2c_handle);
    return ret;

cleanup_spi:
    spiClose(spi_handle);
cleanup_gpio:
    gpioTerminate();
    return EXIT_FAILURE;
}

