            fprintf(stderr, "Warning: failed to read wind direction\n");
            wind_direction = -1;
        }

        char line1[LCD_COLS + 1];
        char line2[LCD_COLS + 1];

        if (wind_direction < 0) {
            snprintf(line1, sizeof(line1), "Wind: %.1f km/h", wind_speed);
            snprintf(line2, sizeof(line2), "Dir: N/A");
        } else {
            snprintf(line1, sizeof(line1), "Wind: %.1f km/h", wind_speed);
            snprintf(line2, sizeof(line2), "Dir: %d deg", wind_direction);
        }

        lcd_clear(i2c_handle);
        lcd_set_cursor(i2c_handle, 0, 0);
        lcd_string(i2c_handle, line1);
        lcd_set_cursor(i2c_handle, 0, 1);
        lcd_string(i2c_handle, line2);

        printf("Wind: %.1f km/h | Dir: %d deg\n",
               wind_speed, wind_direction);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);
    lcd_clear(i2c_handle);
    lcd_string(i2c_handle, "Shutting down");
    gpioDelay(2000000);
    cleanup(spi_handle, i2c_handle);
    return ret;

cleanup_spi:
    spiClose(spi_handle);
cleanup_gpio:
    gpioTerminate();
    return EXIT_FAILURE;
}

