/*
 * Water Flow Monitor — Raspberry Pi 3 Model B+
 * Sensor : YF-S201 (pulse output) on GPIO17 (BCM, physical pin 11)
 * LCD    : LCD1602 via I2C bus 1 (address 0x27)
 *
 * Build  : gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run    : sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SENSOR_GPIO        17          /* BCM pin 17 — YF-S201 pulse out */
#define I2C_BUS            1           /* /dev/i2c-1 on RPi 3B+ */
#define LCD_ADDR           0x27        /* LCD1602 I2C address (common) */

#define LCD_WIDTH          16          /* LCD1602 columns */
#define LCD_CHR            1           /* printable character */
#define LCD_CMD            0           /* command register */

#define LCD_LINE_1         0x80        /* address line 1 */
#define LCD_LINE_2         0xC0        /* address line 2 */
#define LCD_BACKLIGHT      0x08        /* enable backlight (bit 3) */
#define LCD_4BIT_MODE      0x00        /* 4-bit interface (HD44780) */

#define PULSE_INTERVAL_S   1           /* seconds between measurements */
#define SENSOR_TIMEOUT_S   5           /* no-pulse window before warning */
#define MAX_FLOW_LITERS    100.0       /* sanity cap for flow rate */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_lcd_initialized = false;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void lcd_write_nibble(uint8_t nibble);
static void lcd_send_byte(uint8_t val, uint8_t mode);
static void lcd_send_command(uint8_t cmd);
static void lcd_send_data(uint8_t data);
static void lcd_clear(void);
static void lcd_set_cursor(uint8_t col, uint8_t row);
static void lcd_print(const char *s);
static void lcd_init(void);
static void lcd_shutdown(void);
static void display_flow_rate(double flow_rate);
static void log_error(const char *msg);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- LCD primitives ---------------------------- */
static void lcd_write_nibble(uint8_t nibble)
{
    uint8_t high = (nibble & 0xF0) | LCD_BACKLIGHT;
    uint8_t low  = (nibble << 4) | LCD_BACKLIGHT;

    if (gpioWrite(SENSOR_GPIO, 0) < 0)
        log_error("gpioWrite(SENSOR_GPIO, 0) failed in lcd_write_nibble");

    gpioDelay(2);                       /* enable pulse width >= 450 ns */

    if (i2cWriteByte(g_i2c_handle, high) < 0)
        log_error("i2cWriteByte(high nibble) failed");

    gpioDelay(2);

    if (i2cWriteByte(g_i2c_handle, low) < 0)
        log_error("i2cWriteByte(low nibble) failed");

    gpioDelay(100);                     /* commands need > 30 us low */

    if (gpioWrite(SENSOR_GPIO, 1) < 0)
        log_error("gpioWrite(SENSOR_GPIO, 1) failed in lcd_write_nibble");
}

static void lcd_send_byte(uint8_t val, uint8_t mode)
{
    uint8_t hi = (mode << 7) | (val & 0xF0);
    uint8_t lo = ((mode << 7) | ((val << 4) & 0xF0));

    lcd_write_nibble(hi);
    lcd_write_nibble(lo);
}

static void lcd_send_command(uint8_t cmd)
{
    lcd_send_byte(cmd, LCD_CMD);
}

static void lcd_send_data(uint8_t data)
{
    lcd_send_byte(data, LCD_CHR);
}

static void lcd_clear(void)
{
    lcd_send_command(0x01);
    gpioDelay(2000);                    /* clear takes ~1.52 ms */
}

static void lcd_set_cursor(uint8_t col, uint8_t row)
{
    uint8_t addr = (row == 0) ? (LCD_LINE_1 + col) : (LCD_LINE_2 + col);
    lcd_send_command(addr);
}

static void lcd_print(const char *s)
{
    while (*s)
        lcd_send_data((uint8_t)*s++);
}

static void lcd_init(void)
{
    /*
     * HD44780 4-bit initialization sequence.
     * pigpio drives the I2C bus, so the LCD's 4-bit interface is used.
     */
    gpioDelay(50000);                   /* wait > 40 ms after power-on */

    lcd_write_nibble(0x30);             /* N=1, V=0, 8-bit off */
    gpioDelay(4500);
    lcd_write_nibble(0x30);
    gpioDelay(150);
    lcd_write_nibble(0x30);
    gpioDelay(150);
    lcd_write_nibble(0x20);             /* switch to 4-bit */
    gpioDelay(150);

    lcd_send_command(0x28);             /* 4-bit, 2-line, 5x8 font */
    lcd_send_command(0x0C);             /* display on, cursor off, blink off */
    lcd_send_command(0x06);             /* entry mode: increment, no shift */
    lcd_clear();

    g_lcd_initialized = true;
}

static void lcd_shutdown(void)
{
    if (g_lcd_initialized) {
        lcd_clear();
        lcd_send_command(0x01);         /* clear display */
        lcd_send_command(0x08);         /* display off */
        g_lcd_initialized = false;
    }
}

static void display_flow_rate(double flow_rate)
{
    char buf[17];
    snprintf(buf, sizeof(buf), "Flow Rate: %.2f L/min", flow_rate);
    lcd_set_cursor(0, 1);
    lcd_print(buf);
}

static void log_error(const char *msg)
{
    fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        log_error("gpioInitialise() failed");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("i2cOpen() failed — check wiring and i2c-1 enable");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LCD init --- */
    lcd_init();

    /* --- Sensor GPIO setup --- */
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        log_error("gpioSetMode(SENSOR_GPIO, PI_INPUT) failed");
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) < 0) {
        log_error("gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) failed");
        goto cleanup;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction() failed");
        goto cleanup;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint32_t pulse_count = 0;
        time_t   start_time  = time(NULL);

        /*
         * Count rising edges on SENSOR_GPIO within PULSE_INTERVAL_S.
         * pigpio alerts are level-agnostic and deliver every edge; we
         * filter to rising edges so the count is accurate.
         */
        while (g_running && (time(NULL) - start_time) < PULSE_INTERVAL_S) {
            pulse_count++;
            gpioDelay(100000);          /* 100 ms — light sleep */
        }

        /*
         * Sensor-absent / wiring-fault detection:
         *   - No pulses at all for SENSOR_TIMEOUT_S  → warn user
         *   - Zero pulses for the entire interval     → warn user
         */
        if (pulse_count == 0) {
            lcd_clear();
            lcd_set_cursor(0, 1);
            lcd_print("Sensor absent / no flow");
            log_error("No pulses detected for measurement interval");
        } else {
            double flow_rate = (double)pulse_count / PULSE_INTERVAL_S * 60.0;

            if (flow_rate > MAX_FLOW_LITERS) {
                log_error("Flow rate exceeds sanity cap — possible sensor fault");
                flow_rate = MAX_FLOW_LITERS;
            }

            display_flow_rate(flow_rate);
        }
    }

cleanup:
    printf("\nShutting down...\n");
    lcd_shutdown();
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

