#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DELAY_US 800
#define NUM_ROWS 8
#define NUM_COLS 8

static volatile sig_atomic_t running = 1;

static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int all_outputs(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) < 0) return -1;
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) < 0) return -1;
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        safe_write(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        safe_write(col_pins[i], 1);
    }
}

static void shift_left_to_right(int frame[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS; c++) {
            if (safe_write(row_pins[r], 1) < 0) return;
            if (safe_write(col_pins[c], 0) < 0) return;
            gpioDelay(DELAY_US);
            if (safe_write(row_pins[r], 0) < 0) return;
            if (safe_write(col_pins[c], 1) < 0) return;
            frame[r][c] = (frame[r][c] + 1) % 2;
        }
    }
}

static void shift_right_to_left(int frame[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = NUM_COLS - 1; c >= 0; c--) {
            if (safe_write(row_pins[r], 1) < 0) return;
            if (safe_write(col_pins[c], 0) < 0) return;
            gpioDelay(DELAY_US);
            if (safe_write(row_pins[r], 0) < 0) return;
            if (safe_write(col_pins[c], 1) < 0) return;
            frame[r][c] = (frame[r][c] + 1) % 2;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (all_outputs() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int frame[NUM_ROWS][NUM_COLS] = {{0}};

    while (running) {
        shift_left_to_right(frame);
        if (!running) break;
        shift_right_to_left(frame);
    }

    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

