        for (int c = 0; c < NUM_COLS; c++) {
            if (safe_write(row_pins[r], 1) < 0) return;
            if (safe_write(col_pins[c], 0) < 0) return;
            gpioDelay(DELAY_US);
            if (safe_write(row_pins[r], 0) < 0) return;
            if (safe_write(col_pins[c], 1) < 0) return;
            frame[r][c] = (frame[r][c] + 1) % 2;
        }
    }
}

static void shift_right_to_left(int frame[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = NUM_COLS - 1; c >= 0; c--) {
            if (safe_write(row_pins[r], 1) < 0) return;
            if (safe_write(col_pins[c], 0) < 0) return;
            gpioDelay(DELAY_US);
            if (safe_write(row_pins[r], 0) < 0) return;
            if (safe_write(col_pins[c], 1) < 0) return;
            frame[r][c] = (frame[r][c] + 1) % 2;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (all_outputs() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int frame[NUM_ROWS][NUM_COLS] = {{0}};

    while (running) {
        shift_left_to_right(frame);
        if (!running) break;
        shift_right_to_left(frame);
    }

    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

