#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DELAY_MS 150

/* BCM pin numbers for row anodes (an) and column cathodes (cn) */
static const int row_pins[8] = {2, 3, 4, 17, 27, 22, 10, 9};
static const int col_pins[8] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int all_rows_off(void) {
    for (int i = 0; i < 8; i++)
        if (safe_write(row_pins[i], 0) < 0) return -1;
    return 0;
}

static int all_cols_on(void) {
    for (int i = 0; i < 8; i++)
        if (safe_write(col_pins[i], 1) < 0) return -1;
    return 0;
}

static int display_column(int col) {
    if (all_rows_off() < 0) return -1;
    if (safe_write(col_pins[col], 0) < 0) return -1;
    for (int row = 0; row < 8; row++) {
        if (safe_write(row_pins[row], 1) < 0) return -1;
        gpioDelay(DELAY_MS * 1000);
        if (safe_write(row_pins[row], 0) < 0) return -1;
    }
    if (safe_write(col_pins[col], 1) < 0) return -1;
    return 0;
}

