/*
 * VL53L3CX Multi-Target ToF Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads distance measurements from up to 8 targets using the STMicroelectronics
 * VL53L3CX Time-of-Flight sensor on I2C bus 1.
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (pin 3, I2C1 SDA)
 *   VL53L3CX SCL -> GPIO3 (pin 5, I2C1 SCL)
 *   VL53L3CX VDD -> 3.3 V
 *   VL53L3CX GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l3cx_reader vl53l3cx_reader.c
 *
 * Run:
 *   ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define VL53L3CX_ADDR   0x29

/* ---- VL53L3CX register map (16-bit addresses, big-endian on the bus) ---- */
#define REG_SOFT_RESET              0x0000
#define REG_MODEL_ID                0x010F
#define REG_SYSTEM_START            0x0187
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_TARGET_STATUS    0x008A
#define REG_RESULT_TARGET_COUNT     0x008B
#define REG_RESULT_DISTANCE_0       0x0096
#define REG_RESULT_DISTANCE_1       0x0098
#define REG_RESULT_DISTANCE_2       0x009A
#define REG_RESULT_DISTANCE_3       0x009C
#define REG_RESULT_DISTANCE_4       0x009E
#define REG_RESULT_DISTANCE_5       0x00A0
#define REG_RESULT_DISTANCE_6       0x00A2
#define REG_RESULT_DISTANCE_7       0x00A4

#define EXPECTED_MODEL_ID           0xEA
#define MAX_TARGETS                 8
#define POLL_DELAY_MS               100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write16 (addr) to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t val[2];
    if (read(fd, val, sizeof(val)) != (ssize_t)sizeof(val)) {
        fprintf(stderr, "I2C read16 from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)val[0] << 8) | val[1];
    return 0;
}

static int i2c_read8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write16 (addr) to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, out, sizeof(*out)) != (ssize_t)sizeof(*out)) {
        fprintf(stderr, "I2C read8 from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization (stubbed with descriptive comment)            */
/* ------------------------------------------------------------------ */
/*
 * The VL53L3CX requires a proprietary firmware download and complex
 * configuration sequence.  This implementation stubs the firmware
 * download with a descriptive comment while keeping the I2C communication
 * and error handling fully implemented.
 *
 * In a real deployment, replace the following stub with the actual
 * firmware download and configuration sequence from STMicroelectronics
 * VL53L3CX datasheet / application note.
 */
static int sensor_init(int fd)
{
    uint8_t model_id = 0;

    /* --- Verify model ID --- */
    if (i2c_read8(fd, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Cannot read model ID — sensor absent or bus error.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "Unexpected model ID 0x%02X (expected 0x%02X). "
                "Wrong sensor or not a VL53L3CX.\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* --- Stubbed firmware download and configuration --- */
    printf("[STUB] Downloading firmware and configuring sensor "
           "(Model ID 0x%02X)...\n", model_id);

    /*
     * Replace the following sleep with the actual firmware download
     * and configuration sequence from STMicroelectronics VL53L3CX
     * datasheet / application note.
     */
    usleep(200000); /* 200 ms */

    /* --- Start ranging --- */
    if (i2c_write16(fd, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance reading                                                    */
/* ------------------------------------------------------------------ */
static int read_distances(int fd, uint16_t distances[MAX_TARGETS])
{
    uint8_t status = 0;
    uint8_t count  = 0;

    /* Read range status */
    if (i2c_read8(fd, REG_RESULT_RANGE_STATUS, &status) != 0)
        return -1;

    if ((status & 0x1F) == 0) {
        /* No targets detected */
        return 0;
    }

    /* Read target count */
    if (i2c_read8(fd, REG_RESULT_TARGET_COUNT, &count) != 0)
        return -1;

    if (count > MAX_TARGETS) {
        fprintf(stderr, "Target count %u exceeds max %d — clamping.\n",
                count, MAX_TARGETS);
        count = MAX_TARGETS;
    }

    /* Read distances for each detected target */
    for (int i = 0; i < (int)count; i++) {
        uint16_t reg = REG_RESULT_DISTANCE_0 + (uint16_t)(i * 2);
        if (i2c_read16(fd, reg, &distances[i]) != 0)
            return -1;
    }

    return (int)count;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L3CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L3CX_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L3CX initialized. Reading distances every %d ms...\n",
           POLL_DELAY_MS);

    uint16_t distances[MAX_TARGETS];
    char ts[32];

    while (g_running) {
        int n = read_distances(g_i2c_fd, distances);
        if (n < 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
        } else if (n == 0) {
            get_timestamp(ts, sizeof(ts));
            printf("%s  No targets detected\n", ts);
        } else {
            get_timestamp(ts, sizeof(ts));
            printf("%s  Targets:", ts);
            for (int i = 0; i < n; i++) {
                printf(" %u", distances[i]);
            }
            printf("\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    i2c_write16(g_i2c_fd, REG_SYSTEM_START, 0x00); /* Stop ranging */
    close(g_i2c_fd);
    g_i2c_fd = -1;

    return EXIT_SUCCESS;
}

