/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L3CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L3CX_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L3CX initialized. Reading distances every %d ms...\n",
           POLL_DELAY_MS);

    uint16_t distances[MAX_TARGETS];
    char ts[32];

    while (g_running) {
        int n = read_distances(g_i2c_fd, distances);
        if (n < 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
        } else if (n == 0) {
            get_timestamp(ts, sizeof(ts));
            printf("%s  No targets detected\n", ts);
        } else {
            get_timestamp(ts, sizeof(ts));
            printf("%s  Targets:", ts);
            for (int i = 0; i < n; i++) {
                printf(" %u", distances[i]);
            }
            printf("\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    i2c_write16(g_i2c_fd, REG_SYSTEM_START, 0x00); /* Stop ranging */
    close(g_i2c_fd);
    g_i2c_fd = -1;

    return EXIT_SUCCESS;
}

