/*
 * MLX75031 Time-of-Flight distance logger for Raspberry Pi Zero W
 *
 * Uses the Linux I2C character-device interface (no driver library).
 * Bus 1, address 0x0A (7-bit).  Reads a 16-bit big-endian distance
 * value every 100 ms and appends timestamped rows to depth_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75031_log mlx75031_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75031_ADDR  0x0A
#define LOG_FILE       "depth_log.csv"
#define SAMPLE_MS      100
#define DIST_BYTES     2
#define DIST_MAX       0xFFFF

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Open the I2C bus and set the slave address.
 * Returns a file descriptor (>= 0) on success, or -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 16-bit big-endian distance value from the sensor.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_distance(int fd, uint16_t *out)
{
    uint8_t buf[DIST_BYTES];

    /*
     * MLX75031: a 16-bit read returns the distance in big-endian
     * format.  We issue a zero-length write (reg-less) to select the
     * current register and then read DIST_BYTES bytes.
     */
    if (write(fd, buf, 0) < 0) {
        fprintf(stderr, "I2C write (select register): %s\n", strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, DIST_BYTES);
    if (n != DIST_BYTES) {
        if (n < 0)
            fprintf(stderr, "I2C read: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read: short read (%zd bytes)\n", n);
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Append a timestamped distance row to the CSV log.
 * Returns 0 on success, -1 on error.
 */
static int log_data(FILE *fp, int distance)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", ts, (unsigned)distance) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "fprintf header: %s\n", strerror(errno));
            fclose(fp);
            return EXIT_FAILURE;
        }
        fflush(fp);
    }

    /* --- Initialize I2C --- */
    int fd = i2c_open(I2C_BUS, MLX75031_ADDR);
    if (fd < 0) {
        fclose(fp);
        return EXIT_FAILURE;
    }

    printf("MLX75031 logging started.  Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(fd, &distance) == 0) {
            if (distance > DIST_MAX) {
                fprintf(stderr, "Distance out of range: %u\n", distance);
                distance = DIST_MAX;
            }
            if (log_data(fp, distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            /*
             * I2C read failed: log -1 and attempt to re-open the bus.
             * A real application would back off and retry, but this
             * logger keeps going so the sensor is not dropped.
             */
            fprintf(stderr, "I2C read failed; logging -1.\n");
            log_data(fp, -1);

            close(fd);
            fd = -1;

            /*
             * Brief pause before retrying so the sensor does not
             * overwhelm the bus with retries.
             */
            usleep(50 * 1000);

            fd = i2c_open(I2C_BUS, MLX75031_ADDR);
            if (fd < 0) {
                fprintf(stderr, "Re-open I2C failed; will retry next cycle.\n");
            }
        }

        /* Sleep SAMPLE_MS milliseconds, interruptible by signals */
        struct timespec ts = {
            .tv_sec  = SAMPLE_MS / 1000,
            .tv_nsec = (SAMPLE_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    if (fd >= 0)
        close(fd);

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose log: %s\n", strerror(errno));

    printf("Done.\n");
    return EXIT_SUCCESS;
}

