#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000

/* Si1145 register addresses (representative; adjust per datasheet) */
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_PS1_DATA0     0x26
#define SI1145_REG_COMMAND       0x18
#define SI1145_CMD_RESET         0x01
#define SI1145_CMD_PS_FORCE      0x05
#define SI1145_CMD_ALS_FORCE     0x06

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cWriteByteData(g_i2c_handle, SI1145_REG_COMMAND, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int init_sensor(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Software reset */
    if (i2cWriteByteData(g_i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: sensor reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Force a measurement to confirm the device is present */
    if (i2cWriteByteData(g_i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: initial ALS force write failed\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int read_sensor_data(uint16_t *prox, uint16_t *als_vis, uint16_t *als_ir)
{
    int p, v, i;

    p = i2cReadWordData(g_i2c_handle, SI1145_REG_PS1_DATA0);
    v = i2cReadWordData(g_i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    i = i2cReadWordData(g_i2c_handle, SI1145_REG_ALS_IR_DATA0);

    if (p < 0 || v < 0 || i < 0) {
        fprintf(stderr, "Error: I2C read failure (p=%d v=%d i=%d)\n", p, v, i);
        return -1;
    }

    *prox    = (uint16_t)p;
    *als_vis = (uint16_t)v;
    *als_ir  = (uint16_t)i;
    return 0;
}

static void log_data(uint16_t prox, uint16_t als_vis, uint16_t als_ir)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Proximity: %u, Ambient Light (Visible): %u, Ambient Light (IR): %u\n",
            timestamp, prox, als_vis, als_ir);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    uint16_t prox, als_vis, als_ir;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1145 data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        if (read_sensor_data(&prox, &als_vis, &als_ir) == 0) {
            log_data(prox, als_vis, als_ir);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

