static void log_data(uint16_t prox, uint16_t als_vis, uint16_t als_ir)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Proximity: %u, Ambient Light (Visible): %u, Ambient Light (IR): %u\n",
            timestamp, prox, als_vis, als_ir);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    uint16_t prox, als_vis, als_ir;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1145 data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        if (read_sensor_data(&prox, &als_vis, &als_ir) == 0) {
            log_data(prox, als_vis, als_ir);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

