#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_data.log"

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x18

#define SI1145_PART_ID 0x45

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light) {
    uint8_t ps1_data0, als_vis_data0, ps1_data1, als_vis_data1;

    if (read_register(handle, SI1145_REG_PS1_DATA0, &ps1_data0) != 0) return -1;
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0, &als_vis_data0) != 0) return -1;

    if (read_register(handle, SI1145_REG_PS1_DATA0 + 1, &ps1_data1) != 0) return -1;
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0 + 1, &als_vis_data1) != 0) return -1;

    *proximity = ((uint16_t)ps1_data1 << 8) | ps1_data0;
    *ambient_light = ((uint16_t)als_vis_data1 << 8) | als_vis_data0;

    return 0;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint16_t proximity, ambient_light;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (read_register(i2c_handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading PART_ID. Sensor may be absent.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data logging. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            if (log_data(log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

