/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi Zero W
 *
 * Wiring:
 *   TRIGGER -> GPIO 17 (BCM)
 *   ECHO    -> GPIO 27 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000     /* 30 ms max echo wait */
#define LOOP_DELAY_US    1000000   /* 1 s between measurements */
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns elapsed microseconds between two pigpio tick values.        */
/* pigpio ticks are 32-bit and wrap every ~71.6 min; subtraction is    */
/* done modulo 2^32 so the result is always positive.                  */
/* ------------------------------------------------------------------ */
static inline uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned wrap handled by pigpio */
}

/* ------------------------------------------------------------------ */
/* Send a 10 µs trigger pulse.                                         */
/* ------------------------------------------------------------------ */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure echo pulse width in microseconds.                           */
/* Returns:                                                            */
/*   > 0  : pulse width in microseconds                                 */
/*   -1  : echo never went high (sensor absent / wiring fault)         */
/*   -2  : echo stayed high longer than ECHO_TIMEOUT_US                */
/* ------------------------------------------------------------------ */
static long measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;  /* sensor absent or not responding */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -2;  /* echo stuck high - timeout */
        }
    }
    end_tick = gpioTick();

    return (long)tick_diff(start_tick, end_tick);
}

/* ------------------------------------------------------------------ */
/* Convert echo pulse width (µs) to distance (cm).                     */
/* distance = (pulse_us * speed_of_sound) / 2 / 1e6                    */
/* ------------------------------------------------------------------ */
static double calculate_distance(long pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND / 2.0 / 1000000.0;
}

/* ------------------------------------------------------------------ */
/* Log a distance reading with an ISO-8601 timestamp.                  */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Log an error or timeout entry with an ISO-8601 timestamp.           */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, ERROR: %s\n", timestamp, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* --- Main measurement loop --- */
    while (g_running) {
        if (trigger_sensor() < 0) {
            log_error("Trigger pulse failed");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse_us = measure_echo_us();

        if (pulse_us < 0) {
            if (pulse_us == -1) {
                log_error("Echo never went high (sensor absent or wiring fault)");
            } else {
                log_error("Echo timeout - echo stuck high");
            }
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double distance = calculate_distance(pulse_us);

        if (distance < 2.0 || distance > 400.0) {
            log_error("Distance out of valid range (2-400 cm)");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        log_distance(distance);

        if (distance < 15.0) {
            fprintf(g_log_fp, "Time to water the plant!\n");
            fflush(g_log_fp);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

