#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x39

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_CONFIG1 0x8D
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_RDATAL 0x96
#define APDS9960_GDATAL 0x98
#define APDS9960_BDATAL 0x9A
#define APDS9960_PDATA 0x9C

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int apds9960_init(int handle) {
    if (i2cWriteByteData(handle, APDS9960_ENABLE, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2cWriteByteData(handle, APDS9960_ATIME, 0xFF) < 0) return -1;
    if (i2cWriteByteData(handle, APDS9960_PTIME, 0xFF) < 0) return -1;
    if (i2cWriteByteData(handle, APDS9960_WTIME, 0xFF) < 0) return -1;
    if (i2cWriteByteData(handle, APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (i2cWriteByteData(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, APDS9960_ENABLE, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int apds9960_read_proximity(int handle, uint16_t *proximity) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, APDS9960_PDATA, buf, 2) != 2) return -1;
    *proximity = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int apds9960_read_rgb(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, APDS9960_CDATAL, buf, 6) != 6) return -1;
    *r = (uint16_t)((buf[1] << 8) | buf[0]);
    *g = (uint16_t)((buf[3] << 8) | buf[2]);
    *b = (uint16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, uint16_t p) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, r, g, b, p);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (apds9960_init(i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        uint16_t proximity = 0, r = 0, g = 0, b = 0;

        if (apds9960_read_proximity(i2c_handle, &proximity) < 0) {
            fprintf(stderr, "I2C read error, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Re-open failed, exiting\n");
                break;
            }
            if (apds9960_init(i2c_handle) < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
            continue;
        }

        if (apds9960_read_rgb(i2c_handle, &r, &g, &b) < 0) {
            fprintf(stderr, "RGB read error, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Re-open failed, exiting\n");
                break;
            }
            if (apds9960_init(i2c_handle) < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
            continue;
        }

        if (proximity > PROXIMITY_THRESHOLD) {
            log_data(log_file, r, g, b, proximity);
        }

        gpioDelay(100000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

