/*
 * Si1182-A-GMR Heart-Rate Monitor (Raspberry Pi 5)
 *
 * Reads the Si1182 proximity data register every 100 ms, converts the
 * raw value to beats-per-minute, and appends a timestamped line to
 * heartrate.csv.  Uses the Linux I2C character-device interface
 * (/dev/i2c-1) and the standard Linux I2C SMBus helpers.
 *
 * Build:  gcc -O2 -Wall -Wextra -o heart_rate heart_rate.c
 * Run:    ./heart_rate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- Si1182 constants (per datasheet) ------------------------------ */
#define I2C_BUS          "/dev/i2c-1"
#define SI1182_ADDR      0x60          /* 7-bit I2C address */

#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE0   0x08
#define SI1182_REG_MEAS_RATE1   0x09
#define SI1182_REG_PS_LED21     0x0F
#define SI1182_REG_PS1_DATA0    0x10
#define SI1182_REG_PS1_DATA1    0x11

#define SI1182_HW_KEY_VAL       0x17
#define SI1182_EXPECTED_PART_ID 0x82

/* ---- Globals for signal-safe cleanup -------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register using SMBus.                   */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    union i2c_smbus_data data;
    data.byte = value;

    struct i2c_smbus_ioctl_data args;
    args.read_write = I2C_SMBUS_WRITE;
    args.command    = reg;
    args.size       = I2C_SMBUS_BYTE_DATA;
    args.data       = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register using SMBus.                  */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    union i2c_smbus_data data;
    data.byte = 0;

    struct i2c_smbus_ioctl_data args;
    args.read_write = I2C_SMBUS_READ;
    args.command    = reg;
    args.size       = I2C_SMBUS_BYTE_DATA;
    args.data       = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = data.byte;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1182 sensor.                                      */
/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id = 0;

    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;

    if (part_id != SI1182_EXPECTED_PART_ID) {
        fprintf(stderr,
                "Unexpected Part ID: 0x%02X (expected 0x%02X). "
                "Sensor not present or wrong device.\n",
                part_id, SI1182_EXPECTED_PART_ID);
        return -1;
    }

    /*
     * Proximity measurement rate: 100 ms (0x0064 = 100 ms * 31.25 us).
     * The Si1182 uses a 31.25 us clock tick; 0x64 = 100 ms / 31.25 us.
     */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x64) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    /*
     * LED current for PS1 channel (LED2): 0x0F = ~22.4 mA.
     * The Si1182 has two LED drivers; this sets LED2.
     */
    if (i2c_write_reg8(fd, SI1182_REG_PS_LED21, 0x0F) < 0)
        return -1;

    /*
     * Hardware key: required for proper operation.
     */
    if (i2c_write_reg8(fd, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit proximity data register.                           */
/* ------------------------------------------------------------------ */
static int si1182_read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo = 0, hi = 0;

    if (i2c_read_reg8(fd, SI1182_REG_PS1_DATA0, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, SI1182_REG_PS1_DATA1, &hi) < 0)
        return -1;

    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw proximity to beats-per-minute.                         */
/* ------------------------------------------------------------------ */
static float raw_to_bpm(uint16_t raw)
{
    /*
     * Placeholder conversion: a real application would use a
     * calibrated baseline and slope.  This maps raw 0..65535 to
     * 0..200 BPM.
     */
    return (float)raw * 0.5f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped BPM line to the CSV file.                     */
/* ------------------------------------------------------------------ */
static int log_bpm(FILE *fp, float bpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, bpm) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    /* Open the I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize the sensor. */
    if (si1182_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open the CSV file in append mode. */
    g_csv = fopen("heartrate.csv", "a");
    if (g_csv == NULL) {
        fprintf(stderr, "Cannot open heartrate.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Si1182 heart-rate monitor started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t raw = 0;

        if (si1182_read_proximity(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample.\n");
        } else {
            float bpm = raw_to_bpm(raw);
            if (log_bpm(g_csv, bpm) < 0) {
                fprintf(stderr, "Warning: CSV write failed.\n");
            }
        }

        /* 100 ms sampling interval. */
        usleep(100000);
    }

    /* ---- Clean shutdown ------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

