/*
 * VL53L0X Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 *
 * Uses the Linux I2C character-device interface (no VL53L0X driver library).
 *
 * Wiring:
 *   VL53L0X SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   VL53L0X SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   VL53L0X VDD  -> 3.3 V
 *   VL53L0X GND  -> GND
 *   Falling-edge trigger -> GPIO 17 (BCM) with internal pull-up
 *
 * Build:  gcc -O2 -Wall -o vl53l0x_logger vl53l0x_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L0X_ADDR     0x29
#define GPIO_TRIGGER     17
#define LOG_FILE         "distance_log.txt"

/* VL53L0X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET                0x0000
#define REG_SYSTEM_MODE_START         0x0001
#define REG_RESULT_INTERRUPT_STATUS   0x0044
#define REG_RESULT_RANGE_STATUS       0x0049
#define REG_RESULT_DISTANCE           0x0096
#define REG_SYSTEM_INTERRUPT_CLEAR    0x0086
#define REG_GPIO_HV_MUX_CTRL          0x0030
#define REG_GPIO_TIO_HV_STATUS        0x0031
#define REG_SYSTEM_INTERMEASUREMENT  0x004C
#define REG_SYSTEM_THRESH_HIGH       0x004E
#define REG_SYSTEM_THRESH_LOW        0x004F

#define EXPECTED_MODEL_ID             0xEA
#define MEASUREMENT_TIMEOUT_MS        100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */

static int i2c_write16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        val
    };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t wbuf[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    uint8_t rbuf[2];

    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "i2c_read16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, rbuf, sizeof(rbuf)) != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "i2c_read16 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

static int i2c_read8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t wbuf[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    uint8_t rbuf[1];

    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "i2c_read8 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, rbuf, sizeof(rbuf)) != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "i2c_read8 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = rbuf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L0X register access                                            */
/* ------------------------------------------------------------------ */

static int vl53l0x_init(int fd)
{
    uint8_t model_id = 0;

    /* Verify sensor identity */
    if (i2c_read8(fd, REG_SOFT_RESET, &model_id) < 0)
        return -1;
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "VL53L0X not detected (model ID 0x%02X, expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write16(fd, REG_SOFT_RESET, 0x00) < 0)
        return -1;
    usleep(10000);
    if (i2c_write16(fd, REG_SOFT_RESET, 0x01) < 0)
        return -1;
    usleep(10000);

    /* Configure GPIO 17 as falling-edge trigger input (GPIO HV MUX ctrl) */
    if (i2c_write16(fd, REG_GPIO_HV_MUX_CTRL, 0x00) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Set inter-measurement period to 20 ms (0x0014 = 20 * 1 ms units) */
    if (i2c_write16(fd, REG_SYSTEM_INTERMEASUREMENT, 0x0014) < 0)
        return -1;

    /* Set threshold window (1000 mm -> 0x03E8) */
    if (i2c_write16(fd, REG_SYSTEM_THRESH_HIGH, 0x03E8) < 0)
        return -1;
    if (i2c_write16(fd, REG_SYSTEM_THRESH_LOW, 0x03E8) < 0)
        return -1;

    /* Start continuous ranging (bit 0 = range mode) */
    if (i2c_write16(fd, REG_SYSTEM_MODE_START, 0x00) < 0)
        return -1;
    usleep(1000);
    if (i2c_write16(fd, REG_SYSTEM_MODE_START, 0x01) < 0)
        return -1;

    return 0;
}

static int vl53l0x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int elapsed = 0;

    /* Poll for data-ready (bit 0 of RESULT_INTERRUPT_STATUS) */
    while (elapsed < MEASUREMENT_TIMEOUT_MS) {
        if (i2c_read8(fd, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
        elapsed++;
    }

    if (elapsed >= MEASUREMENT_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for VL53L0X measurement\n");
        return -1;
    }

    /* Read 2-byte distance result */
    if (i2c_read16(fd, REG_RESULT_DISTANCE, distance_mm) < 0)
        return -1;

    /* Clear interrupt so the next falling edge can trigger again */
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
