/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        if (g_i2c_fd >= 0)
            i2c_write16(g_i2c_fd, REG_SYSTEM_MODE_START, 0x00);
