    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                VL53L0X_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (vl53l0x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        goto cleanup;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Install signal handlers */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("VL53L0X distance logger started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;

        if (vl53l0x_read_distance(g_i2c_fd, &distance) == 0) {
            log_distance(g_log_fp, distance);
            printf("Distance: %u mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        /* Sleep 50 ms between measurements */
        usleep(50000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup();
    return ret;
}

