/*
 * CH101 Ultrasonic Distance Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   CH101 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   CH101 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   CH101 VDD  -> 3.3 V
 *   CH101 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ch101_logger ch101_logger.c
 *
 * Run:
 *   ./ch101_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x20          /* default 7-bit I2C address */
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_MS      200           /* sampling interval */
#define TRIGGER_MS     50            /* measurement settle time */

/* CH101 register addresses (16-bit, big-endian on the bus) */
#define CH101_REG_MODE      0x00
#define CH101_REG_DISTANCE  0x04
#define CH101_REG_CONFIG    0x08

/* Mode: 0x01 = continuous measurement mode */
#define CH101_MODE_CONT     0x01

/* Config: 0x00 = default 100 kHz I2C clock, 100 ms period */
#define CH101_CONFIG_DEFAULT 0x00

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register (big-endian on the bus). */
static int ch101_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (big-endian on the bus). */
static int ch101_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Trigger a measurement and wait for the result. */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    /* Trigger a continuous-mode measurement. */
    if (ch101_write_reg16(fd, CH101_REG_MODE, CH101_MODE_CONT) != 0)
        return -1;

    usleep(TRIGGER_MS * 1000);

    uint16_t raw;
    if (ch101_read_reg16(fd, CH101_REG_DISTANCE, &raw) != 0)
        return -1;

    *distance_mm = raw;
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus and set slave address --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                CH101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Verify sensor presence by reading config register --- */
    uint16_t cfg;
    if (ch101_read_reg16(fd, CH101_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "CH101 not responding at 0x%02X on %s\n",
                CH101_ADDR, I2C_BUS);
        goto cleanup;
    }
    printf("CH101 detected (config = 0x%04X). Starting measurements...\n", cfg);

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance;

        if (ch101_read_distance(fd, &distance) != 0) {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            fprintf(log_fp, "%s, %u\n", ts, distance);
            fflush(log_fp);
            printf("%s, %u\n", ts, distance);
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int i = 0; i < SAMPLE_MS / 10 && g_running; i++)
            usleep(10 * 1000);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (fd >= 0)
        close(fd);
    return rc;
}

