                CH101_ADDR, I2C_BUS);
        goto cleanup;
    }
    printf("CH101 detected (config = 0x%04X). Starting measurements...\n", cfg);

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance;

        if (ch101_read_distance(fd, &distance) != 0) {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            fprintf(log_fp, "%s, %u\n", ts, distance);
            fflush(log_fp);
            printf("%s, %u\n", ts, distance);
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int i = 0; i < SAMPLE_MS / 10 && g_running; i++)
            usleep(10 * 1000);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (fd >= 0)
        close(fd);
    return rc;
}

