/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ultrasonic ToF sensor reader
 *
 * Wiring:
 *   ICU-20201 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   ICU-20201 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   ICU-20201 VDD -> 3.3 V
 *   ICU-20201 GND -> GND
 *   LED anode    -> GPIO 17 (BCM) via 330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_reader icu20201_reader.c \
 *       -lpigpio -lrt
 * Run:
 *   sudo ./icu20201_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x60          /* ICU-20201 default I2C address */
#define GPIO_LED             17            /* BCM pin for the warning LED  */
#define DISTANCE_THRESHOLD   20.0f         /* cm                            */
#define LOG_FILE             "distance_log.txt"
#define SAMPLE_PERIOD_US     100000        /* 100 ms                        */

/*
 * ICU-20201 register map (representative; adjust if your datasheet/driver
 * uses different register addresses).
 */
#define REG_DISTANCE_MSB     0x00
#define REG_DISTANCE_LSB     0x01
#define REG_STATUS           0x02

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static int  g_led_state  = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_distance(float *distance_cm);
static void control_led(float distance_cm);
static void log_data(float distance_cm);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- Read distance ------------------------------ */
static int read_distance(float *distance_cm)
{
    int msb, lsb, status;

    msb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error: failed to read DISTANCE_MSB: %d\n", msb);
        return -1;
    }

    lsb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error: failed to read DISTANCE_LSB: %d\n", lsb);
        return -1;
    }

    status = i2cReadByteData(g_i2c_handle, REG_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: failed to read STATUS: %d\n", status);
        return -1;
    }

    /*
     * Assemble the 16-bit distance value.
     * The exact byte order depends on the datasheet; adjust if needed.
     */
    uint16_t raw = ((uint16_t)(msb & 0xFF) << 8) | (uint16_t)(lsb & 0xFF);

    /*
     * Convert raw ADC counts to centimetres.
     * Replace with the sensor-specific conversion formula from the
     * ICU-20201 datasheet if available.
     */
    *distance_cm = (float)raw * 0.1f;

    return 0;
}

/* ----------------------------- LED control -------------------------------- */
static void control_led(float distance_cm)
{
    int new_state = (distance_cm < DISTANCE_THRESHOLD) ? 1 : 0;

    if (new_state != g_led_state) {
        g_led_state = new_state;
        if (gpioWrite(GPIO_LED, g_led_state) < 0) {
            fprintf(stderr, "Warning: gpioWrite failed for LED on GPIO %d\n",
                    GPIO_LED);
        }
    }
}

/* ----------------------------- Logging ------------------------------------ */
static void log_data(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error: time()");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error: localtime_r()");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance_cm) < 0) {
        perror("Error: fprintf()");
    }

    if (fclose(fp) != 0) {
        perror("Error: fclose()");
    }
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_led_state != 0) {
        gpioWrite(GPIO_LED, 0);
        g_led_state = 0;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance reader started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float distance_cm;

        if (read_distance(&distance_cm) == 0) {
            control_led(distance_cm);
            log_data(distance_cm);
            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            fprintf(stderr, "Warning: distance read failed; retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

