/*
 * Si1182-GMR Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   Si1182 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * The Si1182 is a high-revision part; the register map and command
 * protocol are different from the Si118x series.  This program uses
 * the high-revision command set and the Si1182-GMR datasheet.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000          /* 500 ms */
#define MAX_RETRIES    3

/* Si1182-GMR high-revision register addresses */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE  0x08
#define REG_ALS_RATE   0x09
#define REG_PS_RATE    0x0A
#define REG_PS_LED21   0x0F
#define REG_PS_LED3    0x10
#define REG_ALS_IR_ADC 0x12
#define REG_ALS_VIS_ADC 0x14
#define REG_PS1_ADC    0x16
#define REG_PS2_ADC    0x18
#define REG_PS3_ADC    0x1A
#define REG_COMMAND    0xC0

/* Si1182-GMR high-revision command codes */
#define CMD_RESET      0x01
#define CMD_PS_FORCE   0x05
#define CMD_ALS_FORCE  0x06
#define CMD_PSALS_FORCE 0x07

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0)
        fprintf(stderr, "[I2C] write reg 0x%02X val 0x%02X failed (rc=%d)\n",
                reg, value, rc);
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read word reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1182-GMR driver                                                   */
/* ------------------------------------------------------------------ */
static int si1182_reset(int handle)
{
    if (i2c_write_byte(handle, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    gpioDelay(10000);   /* 10 ms reset settling */
    return 0;
}

static int si1182_init(int handle)
{
    uint8_t part_id;

    if (i2c_read_byte(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[Si1182] Cannot read PART_ID — sensor absent or bus error\n");
        return -1;
    }
    printf("[Si1182] PART_ID = 0x%02X\n", part_id);

    /*
     * Proximity LED current for LED1 (visible) and LED2 (IR).
     * The Si1182-GMR uses a single LED1 and LED21 register pair.
     */
    if (i2c_write_byte(handle, REG_PS_LED21, 0x7F) < 0)   /* ~60 mA */
        return -1;
    if (i2c_write_byte(handle, REG_PS_LED3,   0x7F) < 0)   /* ~60 mA */
        return -1;

    /*
     * Measurement rates.
     * ALS_RATE = 0x0A  -> 100 ms ALS cycle
     * PS_RATE  = 0x0A  -> 100 ms PS  cycle
     * MEAS_RATE = 0x0A -> 100 ms measurement cycle
     */
    if (i2c_write_byte(handle, REG_MEAS_RATE, 0x0A) < 0)
        return -1;
    if (i2c_write_byte(handle, REG_ALS_RATE,  0x0A) < 0)
        return -1;
    if (i2c_write_byte(handle, REG_PS_RATE,   0x0A) < 0)
        return -1;

    /*
     * Hardware key (required for proper operation).
     * The Si1182-GMR uses a HW_KEY register; the value 0x17 is the
     * documented default for the high-revision parts.
     */
    if (i2c_write_byte(handle, REG_HW_KEY, 0x17) < 0)
        return -1;

    return 0;
}

static int si1182_read_proximity(int handle, uint16_t *prox)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(handle, REG_COMMAND, CMD_PS_FORCE) < 0) {
            gpioDelay(10000);
            continue;
        }
        gpioDelay(10000);   /* 10 ms conversion */

        if (i2c_read_word(handle, REG_PS1_ADC, prox) == 0)
            return 0;

        gpioDelay(10000);
    }
    return -1;
}

static int si1182_read_ambient_light(int handle, uint16_t *als_vis, uint16_t *als_ir)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
            gpioDelay(10000);
            continue;
        }
        gpioDelay(10000);   /* 10 ms conversion */

        if (i2c_read_word(handle, REG_ALS_VIS_ADC, als_vis) < 0) {
            gpioDelay(10000);
            continue;
        }
        if (i2c_read_word(handle, REG_ALS_IR_ADC, als_ir) < 0) {
            gpioDelay(10000);
            continue;
        }
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t prox, uint16_t als_vis, uint16_t als_ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[Log] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Proximity: %u, Ambient Light (Visible): %u, Ambient Light (IR): %u\n",
            ts, prox, als_vis, als_ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1182_reset(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1182 reset failed — sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1182 data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        uint16_t prox, als_vis, als_ir;

        if (si1182_read_proximity(g_i2c_handle, &prox) == 0 &&
            si1182_read_ambient_light(g_i2c_handle, &als_vis, &als_ir) == 0) {
            log_data(g_log_file, prox, als_vis, als_ir);
        } else {
            fprintf(stderr, "[Main] Sensor read failed — continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

