 * Reads distance from an TDK InvenSense ICU-20201 sensor on I2C bus 1
 * every 50 ms and lights an LED on GPIO 17 when the distance falls
 * below a configurable threshold.  Logs readings with timestamps to
 * tof_log.txt.  Handles SIGINT for clean shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    sudo ./tof_monitor [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x60          /* ICU-20201 default I2C address */
#define WHO_AM_I_REG         0x01
#define WHO_AM_I_EXPECTED    0x01          /* ICU-20201 WHO_AM_I value */
#define LED_GPIO             17            /* BCM pin 17 */
#define DEFAULT_THRESHOLD    100           /* mm */
#define LOG_FILE             "tof_log.txt"
#define POLL_DELAY_US        50000         /* 50 ms */

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE         0x04
#define REG_DISTANCE_HI      0x04
#define REG_DISTANCE_LO      0x05

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;
static int      threshold = DEFAULT_THRESHOLD;

/* --------------------------- Function prototypes ------------------------- */
static int  init_i2c(void);
static int  verify_sensor(void);
static int  read_distance(uint16_t *distance);
static void control_led(int on);
static void log_data(uint16_t distance);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------- Sensor presence check ------------------------- */
static int verify_sensor(void)
{
    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read of WHO_AM_I failed: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_EXPECTED);
        return -1;
    }
    printf("ICU-20201 detected (WHO_AM_I = 0x%02X)\n", who);
    return 0;
}

/* --------------------------- Read distance (mm) -------------------------- */
static int read_distance(uint16_t *distance)
{
    int hi = i2cReadByteData(i2c_handle, REG_DISTANCE_HI);
    if (hi < 0) {
        fprintf(stderr, "Error: I2C read of DISTANCE_HI failed: %d\n", hi);
        return -1;
    }
    int lo = i2cReadByteData(i2c_handle, REG_DISTANCE_LO);
    if (lo < 0) {
        fprintf(stderr, "Error: I2C read of DISTANCE_LO failed: %d\n", lo);
        return -1;
    }
    *distance = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------- LED control ----------------------------- */
static void control_led(int on)
{
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(uint16_t distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "(time error), Distance: %u mm\n", distance);
    }

    fclose(fp);
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(int argc, char *argv[])
{
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Warning: threshold must be positive; using default %d mm\n",
                    DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("Monitoring distance (threshold %d mm). Press Ctrl+C to exit.\n",
           threshold);

    while (!terminate) {
        uint16_t distance = 0;
        if (read_distance(&distance) == 0) {
            log_data(distance);
            control_led(distance < threshold ? 1 : 0);
        } else {
            control_led(0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

