/*
 * Raspberry Pi Zero W – Omron B5L-LD50-07050 3D TOF sensor intrusion detector
 *
 * Wiring:
 *   Sensor SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Sensor SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Sensor VCC  -> 3.3 V (pin 1)
 *   Sensor GND  -> GND  (pin 6)
 *
 * The B5L-LD50-07050 is a 3D TOF sensor that provides distance data
 * over I2C.  This program sends the documented 4-byte command frame
 * to request a measurement, waits 10 ms, reads the 15-byte response,
 * extracts the 16-bit big-endian distance, averages 10 samples, and
 * logs the average distance when it falls below 1000 mm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion_detector intrusion_detector.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define I2C_ADDR         0x50          /* B5L-LD50 default I2C address */
#define LOG_FILE         "intrusion_log.txt"
#define DISTANCE_THRESHOLD 1000        /* mm */
#define NUM_SAMPLES      10
#define SAMPLE_DELAY_MS  100
#define MEASURE_DELAY_MS 10
#define MAX_RETRIES      3

/*
 * B5L-LD50 command frame (4 bytes, sent as a single I2C write):
 *   Byte 0: 0x01                       – start of frame
 *   Byte 1: 0x00                       – reserved
 *   Byte 2: 0x00                       – reserved
 *   Byte 3: 0x01                       – measurement command
 *
 * Response (15 bytes):
 *   Byte 0: 0x02                       – header
 *   Byte 1-10: 16-bit big-endian X, Y, Z distance data (mm)
 *   Byte 11-12: 16-bit big-endian distance (mm)
 *   Byte 13-14: 16-bit big-endian status
 */
static const uint8_t CMD_FRAME[4] = { 0x01, 0x00, 0x00, 0x01 };
static const uint8_t RESP_HEADER = 0x02;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void msleep(unsigned ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Write a 4-byte command frame to the sensor.                         */
static int sensor_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t n = write(fd, cmd, len);
    if (n < 0) {
        fprintf(stderr, "write() failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "write() short: wrote %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor.                           */
static int sensor_read_resp(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "read() failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read() returned 0 (EOF) – sensor may be absent\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Request a measurement and return the 16-bit big-endian distance.
 * Returns 0 on success and stores the distance in *distance_mm;
 * returns -1 on any error.
 */
static int sensor_get_distance(int fd, uint16_t *distance_mm)
{
    if (sensor_write_cmd(fd, CMD_FRAME, sizeof(CMD_FRAME)) != 0)
        return -1;

    msleep(MEASURE_DELAY_MS);

    uint8_t resp[15];
    if (sensor_read_resp(fd, resp, sizeof(resp)) != 0)
        return -1;

    if (resp[0] != RESP_HEADER) {
        fprintf(stderr, "Unexpected header byte 0x%02x (expected 0x%02x)\n",
                resp[0], RESP_HEADER);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

/* ------------------------------------------------------------------ */
static double calculate_average(const uint16_t *samples, int n)
{
    double sum = 0.0;
    for (int i = 0; i < n; i++)
        sum += (double)samples[i];
    return sum / (double)n;
}

/* ------------------------------------------------------------------ */
static void log_intrusion(double distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f mm\n", ts, distance);
    } else {
        fprintf(fp, "(unknown time), %.2f mm\n", distance);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02x) failed: %s\n",
                I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started (bus=%s addr=0x%02x). Ctrl-C to exit.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        uint16_t samples[NUM_SAMPLES];
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int attempts = 0;
            int ok = 0;
            while (attempts < MAX_RETRIES && g_running) {
                uint16_t dist;
                if (sensor_get_distance(g_i2c_fd, &dist) == 0) {
                    samples[i] = dist;
                    valid++;
                    ok = 1;
                    break;
                }
                attempts++;
                if (attempts < MAX_RETRIES)
                    msleep(10);
            }
            if (!ok) {
                fprintf(stderr, "Sensor read failed after %d retries (sample %d)\n",
                        MAX_RETRIES, i + 1);
                break;
            }
            msleep(SAMPLE_DELAY_MS);
        }

        if (valid == 0) {
            fprintf(stderr, "No valid samples this cycle.\n");
            continue;
        }

        double avg = calculate_average(samples, valid);
        printf("Average distance: %.2f mm (valid=%d/%d)\n",
               avg, valid, NUM_SAMPLES);

        if (avg < DISTANCE_THRESHOLD) {
            printf("Intrusion detected! Logging...\n");
            log_intrusion(avg);
        }

        msleep(SAMPLE_DELAY_MS);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

