#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L0X register addresses (16-bit, big-endian on the bus) */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR   0x0086
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS  0x0089
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L0X_REG_SYSTEM_START             0x0087
#define VL53L0X_REG_SYSTEM_SEQUENCE_CONFIG   0x008A
#define VL53L0X_REG_SYSTEM_INTERMEASUREMENT  0x008B
#define VL53L0X_REG_SYSTEM_RANGE_START       0x0087

#define VL53L0X_MODEL_ID_EXPECTED 0xEA
#define I2C_BUS 1
#define SAMPLE_PERIOD_US 500000  /* 500 ms */
#define MEAS_TIMEOUT_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a 16-bit value. */
static int vl53l0x_write16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Write a 16-bit register address followed by an 8-bit value. */
static int vl53l0x_write8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit register (big-endian on the bus). */
static int vl53l0x_read16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) < 0)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Read an 8-bit register. */
static int vl53l0x_read8(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    char data[1];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 1) < 0)
        return -1;

    *out = (uint8_t)data[0];
    return 0;
}

static int vl53l0x_init(int handle)
{
    uint16_t model_id = 0;

    if (vl53l0x_read16(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Model ID mismatch: got 0x%04X, expected 0x%04X\n",
                model_id, VL53L0X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Clear any pending interrupts. */
    if (vl53l0x_write8(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    /* Start continuous ranging (simplified sequence). */
    if (vl53l0x_write8(handle, VL53L0X_REG_SYSTEM_SEQUENCE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring sequence: %s\n", strerror(errno));
        return -1;
    }

    if (vl53l0x_write8(handle, VL53L0X_REG_SYSTEM_INTERMEASUREMENT, 0x00) < 0) {
        fprintf(stderr, "Error setting inter-measurement: %s\n", strerror(errno));
        return -1;
    }

    if (vl53l0x_write8(handle, VL53L0X_REG_SYSTEM_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t range = 0;
    int elapsed = 0;

    /* Poll for data-ready with a timeout. */
    while (elapsed < MEAS_TIMEOUT_US) {
        if (vl53l0x_read8(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
