        gpioDelay(2000); /* 2 ms */
        elapsed += 2000;
    }

    if (elapsed >= MEAS_TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    if (vl53l0x_read16(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal. */
    if (vl53l0x_write8(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = range;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, 0x29, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X initialized. Reading distance every 500 ms...\n");
    fflush(stdout);

    while (g_running) {
        uint16_t distance = 0;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: I2C read error during distance measurement.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

