/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3)
 *   Si1182 SCL  -> GPIO3 (pin 5)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * I2C bus 1 (GPIO2/GPIO3), address 0x60.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c -lpigpio -lrt
 * Run:    sudo ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1182_ADDR    0x60

/* Si1182 register addresses (representative values; adjust per datasheet) */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE    0x08
#define SI1182_REG_PS_LED21     0x0F
#define SI1182_REG_PS1_DATA0    0x10
#define SI1182_REG_PS1_DATA1    0x11

/* Expected PART_ID for Si1182 (typical value) */
#define SI1182_PART_ID_EXPECTED  0x82

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a Si1182 register.
 * Returns 0 on success, -1 on error.
 */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1182 register.
 * Returns 0 on success and stores the byte in *out; -1 on error.
 */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/*
 * Read a 16-bit little-endian register pair (low byte at reg, high at reg+1).
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int si1182_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;

    if (si1182_read_reg(handle, reg, &lo) < 0)
        return -1;
    if (si1182_read_reg(handle, reg + 1, &hi) < 0)
        return -1;

    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1182 driver                                                       */
/* ------------------------------------------------------------------ */

/*
 * Initialise the Si1182 sensor.
 * Returns 0 on success, -1 on error.
 */
static int si1182_init(int handle)
{
    uint8_t part_id;

    /* Verify sensor presence with a zero-length write (probe) */
    if (i2cWriteByte(handle, SI1182_REG_PART_ID) < 0) {
        fprintf(stderr, "[ERROR] No ACK from Si1182 at address 0x%02X — sensor absent or bus error.\n",
                SI1182_ADDR);
        return -1;
    }

    /* Read PART_ID to confirm identity */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;

    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[WARN] Unexpected PART_ID 0x%02X (expected 0x%02X). Continuing anyway.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        /* Non-fatal: proceed with init */
    }

    /*
     * Minimal configuration for proximity measurement.
     * Replace HW_KEY with the actual value from your Si1182 datasheet.
     */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, 0x00) < 0)
        return -1;

    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE, 0x0A) < 0)
        return -1;

    if (si1182_write_reg(handle, SI1182_REG_PS_LED21, 0x0F) < 0)
        return -1;

    return 0;
}

/*
 * Read the 16-bit proximity value from the Si1182.
 * Returns 0 on success and stores the value in *prox; -1 on error.
 */
static int si1182_read_proximity(int handle, uint16_t *prox)
{
    return si1182_read_reg16(handle, SI1182_REG_PS1_DATA0, prox);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1182 address */
    handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_ADDR, handle);
        goto cleanup_gpio;
    }

    /* Initialise the Si1182 sensor */
    if (si1182_init(handle) < 0) {
        fprintf(stderr, "[ERROR] Si1182 initialisation failed.\n");
        goto cleanup_i2c;
    }

    printf("Si1182 proximity sensor reader started (bus %d, addr 0x%02X).\n",
           I2C_BUS, SI1182_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t prox;

        if (si1182_read_proximity(handle, &prox) == 0) {
            printf("Proximity: %u\n", (unsigned)prox);
        } else {
            fprintf(stderr, "[ERROR] Failed to read proximity data.\n");
        }

        /* Sleep 500 ms (500 000 microseconds) */
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0)
        i2cClose(handle);

cleanup_gpio:
    gpioTerminate();

    return rc;
}

