/*
 * MLX75030 Time-of-Flight distance sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * The MLX75030 is a Melexis ToF sensor; its I2C address is typically
 * 0x08 (7-bit).  Replace ADDR_7BIT with the actual 7-bit address of
 * your device if it differs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADDR_7BIT      0x08          /* MLX75030 default 7-bit I2C address */
#define POLL_MS        500           /* polling interval in milliseconds  */

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Sleep for the remainder of the current second.
 * Returns 0 on success, -1 on error.
 */
static int sleep_remainder_of_second(void)
{
    struct timespec now;
    if (clock_gettime(CLOCK_REALTIME, &now) == -1) {
        perror("clock_gettime");
        return -1;
    }
    struct timespec target = { .tv_sec = now.tv_sec + 1, .tv_nsec = 0 };
    struct timespec rem;
    while (nanosleep(&target, &rem) == -1) {
        if (errno != EINTR) {
            perror("nanosleep");
            return -1;
        }
        target = rem;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1) {
        goto out;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto out;
    }

    if (ioctl(fd, I2C_SLAVE, ADDR_7BIT) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADDR_7BIT, strerror(errno));
        goto cleanup;
    }

    /*
     * Quick presence check: a zero-length write to the device
     * should return success if the sensor acknowledges its address.
     */
    if (write(fd, NULL, 0) == -1) {
        fprintf(stderr, "Device not responding at 0x%02X: %s\n",
                ADDR_7BIT, strerror(errno));
        goto cleanup;
    }

    printf("MLX75030 distance sensor at I2C 0x%02X on %s\n",
           ADDR_7BIT, I2C_BUS);
    fflush(stdout);

    while (!g_stop) {
        uint8_t buf[2];
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == -1) {
            fprintf(stderr, "read: %s\n", strerror(errno));
        } else if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor may be absent)\n");
        } else if (n == 1) {
            printf("Distance: %u mm\n", (unsigned)buf[0]);
            fflush(stdout);
        } else {
            /* n == 2: distance + status */
            printf("Distance: %u mm\n", (unsigned)buf[0]);
            fflush(stdout);
        }

        if (sleep_remainder_of_second() == -1) {
            break;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        close(fd);
    }
out:
    return rc;
}

