code:
/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 *
 * Reads channel 0 distance (mm) and ambient light (raw) every 500 ms and
 * logs them to stdout.  Handles I2C errors and exits cleanly on SIGINT.
 *
 * Wiring:
 *   OPT3101 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   OPT3101 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   OPT3101 VDD  -> 3.3 V
 *   OPT3101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101_reader opt3101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3101_ADDR   0x30

/* OPT3101 register addresses (16-bit, big-endian on the bus) */
#define REG_SYSTEM_CTRL 0x0000
#define REG_DISTANCE_0  0x0010
#define REG_AMBIENT_0   0x0012
#define REG_ERROR_FLAGS 0x0014

/*
 * System control register (0x0000):
 *   [15]   SOFT_RESET
 *   [14:12] CLK_SEL (000 = 10 MHz)
 *   [11:10] MODE    (00 = standby)
 *   [9:8]   RANGE   (00 = 1000 mm)
 *   [7:6]   ALS_GAIN(00)
 *   [5:4]   ALS_INT (00)
 *   [3:2]   TOF_INT (00)
 *   [1:0]   TOF_RES (00 = 16-bit)
 *
 * Value 0x0000 puts the device in standby mode.
 */
#define SYSTEM_CTRL_STANDBY 0x0000

/*
 * Distance register (0x0010):
 *   [15:0]  distance in mm (16-bit, unsigned)
 */
#define DISTANCE_REG_LEN 2

/*
 * Ambient light register (0x0012):
 *   [15:0]  ambient light value (16-bit, unsigned)
 */
#define AMBIENT_REG_LEN 2

/*
 * Error flags register (0x0014):
 *   [15]    reserved
 *   [14]    reserved
 *   [13]    reserved
 *   [12]    reserved
 *   [11]    reserved
 *   [10]    reserved
 *   [9]     reserved
 *   [8]     reserved
 *   [7]     reserved
 *   [6]     reserved
 *   [5]     reserved
 *   [4]     reserved
 *   [3]     reserved
 *   [2]     reserved
 *   [1]     reserved
 *   [0]     reserved
 */
#define ERROR_FLAGS_REG_LEN 2

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Write a 16-bit value to an OPT3101 register.
 * OPT3101 register addresses are 16-bit big-endian on the bus.
 */
static int opt3101_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an OPT3101 register.
 * The register address must be written first, then a dummy write
 * of 0 bytes triggers a read of the current register value.
 */
static int opt3101_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr_buf[2];
    uint8_t data_buf[2];

    addr_buf[0] = (uint8_t)(reg >> 8);
    addr_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr_buf, sizeof(addr_buf)) != (ssize_t)sizeof(addr_buf)) {
        fprintf(stderr, "I2C write (addr) reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data_buf, sizeof(data_buf)) != (ssize_t)sizeof(data_buf)) {
        fprintf(stderr, "I2C read reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data_buf[0] << 8) | data_buf[1];
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the OPT3101 device */
    if (ioctl(fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Put the sensor in standby mode (clear any previous configuration) */
    if (opt3101_write_reg16(fd, REG_SYSTEM_CTRL, SYSTEM_CTRL_STANDBY) < 0) {
        fprintf(stderr, "Failed to configure OPT3101 (standby).\n");
        goto cleanup;
    }

    printf("OPT3101 reader started. Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t distance_raw = 0;
        uint16_t ambient_raw  = 0;
        uint16_t error_flags  = 0;
        bool read_failed = false;

        if (opt3101_read_reg16(fd, REG_DISTANCE_0, &distance_raw) < 0) {
            read_failed = true;
        }
        if (opt3101_read_reg16(fd, REG_AMBIENT_0, &ambient_raw) < 0) {
            read_failed = true;
        }
        if (opt3101_read_reg16(fd, REG_ERROR_FLAGS, &error_flags) < 0) {
            read_failed = true;
        }

        if (read_failed) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            printf("Distance: %5u mm  |  Ambient: %5u  |  Errors: 0x%04X\n",
                   distance_raw, ambient_raw, error_flags);
        }

        /* Sleep 500 ms (interruptible by signals) */
        usleep(500000);
    }

    printf("\nExiting gracefully.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

