/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm resistor
 *   HC-SR04 VCC  -> 5V (external 5V supply recommended)
 *   HC-SR04 GND  -> GND
 *
 * NOTE: The HC-SR04 operates at 5V. The Raspberry Pi GPIO pins are
 * 3.3V tolerant. A 1kOhm resistor is required between the GPIO pin
 * and the HC-SR04 ECHO pin to protect the GPIO pin from the 5V
 * signal.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US   200000      /* 200 ms max echo wait (~5 m)    */
#define LOOP_DELAY_US     1000000     /* 1 s between readings           */
#define MIN_VALID_US      10          /* HC-SR04 min range ~2.9 cm      */
#define MAX_VALID_US      38000       /* HC-SR04 max range ~400 cm      */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Measure distance in centimetres.                                    */
/* Returns:                                                            */
/*   >= 0  : distance in cm                                            */
/*   -1.0  : timeout waiting for echo rising edge                      */
/*   -2.0  : timeout waiting for echo falling edge                     */
/*   -3.0  : invalid pulse duration (out of HC-SR04 range)             */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, pulse_us;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -3.0f;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -3.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -3.0f;
    }

    /* Wait for echo rising edge (timeout 200 ms) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0f;  /* echo never went high */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 200 ms) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -2.0f;  /* echo never went low */
        }
    }
    end_tick = gpioTick();

    pulse_us = end_tick - start_tick;

    /* HC-SR04 range check: 10 µs min round trip ~2.9 cm, 38 000 µs ~400 cm */
    if (pulse_us < MIN_VALID_US || pulse_us > MAX_VALID_US) {
        return -3.0f;
    }

    /* distance = (pulse_us * 34300 cm/s) / 2  (round trip) */
    return (float)pulse_us * 0.01715f;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* let sensor settle */

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 Ultrasonic Distance Sensor\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float distance = measure_distance();

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (distance > 0.0f) {
            printf("[%s] Distance: %.2f cm\n", timestamp, distance);
        } else {
            const char *err;
            switch ((int)distance) {
                case -1:  err = "timeout waiting for echo rising edge";  break;
                case -2:  err = "timeout waiting for echo falling edge"; break;
                default:  err = "invalid pulse duration (out of range)"; break;
            }
            fprintf(stderr, "[%s] Error: %s\n", timestamp, err);
        }

        /* Sleep 1 s between readings */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean up: ensure trigger is low and terminate pigpio */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

