#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B115200
#define GPIO_LED         17
#define DISTANCE_THRESHOLD 1.0f   /* meters */
#define ALERT_DURATION   2       /* seconds */
#define LOG_FILE         "intrusion_log.csv"
#define READ_BUF_SIZE    512
#define MAGIC_WORD_LEN   8
#define RANGE_PROFILE_LEN 128
#define NUM_BINS         64

static const uint8_t MAGIC_WORD[MAGIC_WORD_LEN] = {
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08
};

static volatile sig_atomic_t g_terminate = 0;
static int  g_uart_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* UART                                                                */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open(UART)");
        return -1;
    }

    /* Clear O_NONBLOCK for normal blocking reads */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("fcntl(F_SETFL)");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag  = 0;
    tty.c_lflag  = 0;

    /* VMIN=1, VTIME=10 → 1 s inter-byte timeout */
    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_LED);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", GPIO_LED);
        gpioTerminate();
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_intrusion(float distance)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, distance) < 0) {
        perror("fprintf(log)");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush(log)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Frame processing                                                    */
/* ------------------------------------------------------------------ */
/*
 * IWR1443 range-profile frames:
 *   8-byte magic word  (01 02 03 04 05 06 07 08)
 *   128 bytes of little-endian 16-bit distance bins (mm)
 *   Each bin is a distance to the nearest object in that range bin.
 *   A value of 0xFFFF means "no object detected" in that bin.
 */
static int process_frame(const uint8_t *frame, float *max_distance)
{
    *max_distance = 0.0f;

    if (memcmp(frame, MAGIC_WORD, MAGIC_WORD_LEN) != 0) {
        fprintf(stderr, "Magic word mismatch — skipping\n");
        return -1;
    }

    for (int i = 0; i < NUM_BINS; i++) {
        uint16_t dist_mm = (uint16_t)frame[MAGIC_WORD_LEN + i * 2] |
                          ((uint16_t)frame[MAGIC_WORD_LEN + i * 2 + 1] << 8);

        /* 0xFFFF means "no object" in this bin */
        if (dist_mm != 0xFFFF) {
            float d = (float)dist_mm / 1000.0f;   /* mm → m */
            if (d > *max_distance)
                *max_distance = d;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        fprintf(stderr, "UART initialization failed — sensor absent or bus error\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(log)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_m\n");
        fflush(g_log_fp);
    }

    uint8_t  rx_buf[READ_BUF_SIZE];
    uint8_t  frame_buf[MAGIC_WORD_LEN + RANGE_PROFILE_LEN];
    size_t   frame_fill = 0;

    printf("Intrusion detection started on %s @ %d baud.\n",
           UART_DEVICE, BAUD_RATE);
    printf("Threshold: %.1f m, Alert LED on GPIO %d, 2 s pulse.\n",
           DISTANCE_THRESHOLD, GPIO_LED);
    printf("Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        ssize_t n = read(g_uart_fd, rx_buf, sizeof(rx_buf));
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK)
                continue;
            perror("read(UART)");
            break;
        }
        if (n == 0)
            continue;                 /* timeout — no data */

        /* Accumulate bytes into frame buffer */
        for (ssize_t i = 0; i < n && !g_terminate; i++) {
            if (frame_fill < MAGIC_WORD_LEN) {
                frame_buf[frame_fill++] = rx_buf[i];
                if (frame_fill == MAGIC_WORD_LEN) {
                    /* We have the magic word — keep collecting */
                }
            } else if (frame_fill < MAGIC_WORD_LEN + RANGE_PROFILE_LEN) {
                frame_buf[frame_fill++] = rx_buf[i];
                if (frame_fill == MAGIC_WORD_LEN + RANGE_PROFILE_LEN) {
                    float max_distance = 0.0f;
                    if (process_frame(frame_buf, &max_distance) == 0) {
                        if (max_distance > DISTANCE_THRESHOLD) {
                            printf("Intrusion detected! Max distance: %.2f m\n",
                                   max_distance);
                            if (log_intrusion(max_distance) != 0)
                                fprintf(stderr, "Logging failed\n");
                            if (gpioWrite(GPIO_LED, 1) != 0)
                                fprintf(stderr, "gpioWrite(HIGH) failed\n");
                            gpioDelay(ALERT_DURATION * 1000000);   /* 2 s */
                            if (gpioWrite(GPIO_LED, 0) != 0)
                                fprintf(stderr, "gpioWrite(LOW) failed\n");
                        }
                    }
                    frame_fill = 0;
                }
            } else {
                /* Over-long frame — resync */
                frame_fill = 0;
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

