/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance logger.
 *
 * Hardware:
 *   - ICU-20201 on I2C bus 1 (physical pins 3 = SDA, 5 = SCL), address 0x60.
 *   - Alert LED / buzzer on BCM GPIO 17 (physical pin 11).
 *
 * Behaviour:
 *   - Reads distance every 100 ms and logs to distance_log.txt.
 *   - Asserts GPIO 17 when distance < 10.0 cm.
 *   - Clean shutdown on SIGINT / SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_logger distance_logger.c \
 *       -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x60          /* ICU-20201 default I2C address */
#define ALERT_GPIO           17            /* BCM 17 – physical pin 11 */
#define DISTANCE_THRESHOLD   10.0f         /* cm */
#define LOG_FILE             "distance_log.txt"
#define SAMPLE_PERIOD_US     100000        /* 100 ms */

/*
 * ICU-20201 register map (example – adjust for your specific firmware
 * variant if the register addresses differ).
 */
#define REG_DISTANCE_MSB     0x00
#define REG_DISTANCE_LSB     0x01
#define REG_STATUS           0x02
#define REG_CONFIG           0x03

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  init_log(void);
static void cleanup(void);
static int  read_distance(float *distance_cm);
static void log_data(float distance);
static void check_threshold(float distance);

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_log() != 0) {
        fprintf(stderr, "Log file initialisation failed\n");
        gpioWrite(ALERT_GPIO, 0);
        gpioSetMode(ALERT_GPIO, PI_INPUT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance;

        if (read_distance(&distance) == 0) {
            log_data(distance);
            check_threshold(distance);
        } else {
            fprintf(stderr, "Error reading distance – continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- I2C / sensor helpers ------------------------ */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /*
     * Probe: a zero-length write to the status register should return 0
     * on success.
     */
    if (i2cWriteByteData(g_i2c_handle, REG_STATUS, 0x00) < 0) {
        fprintf(stderr, "ICU-20201 not responding at 0x%02X on bus %d\n",
                I2C_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_distance(float *distance_cm)
{
    int msb, lsb;

    msb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "I2C read MSB failed: %d\n", msb);
        return -1;
    }

    lsb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "I2C read LSB failed: %d\n", lsb);
        return -1;
    }

    uint16_t raw = ((uint16_t)(msb & 0xFF) << 8) | (uint16_t)(lsb & 0xFF);

    /*
     * Convert raw ADC value to distance in centimetres.
     * Adjust the scale factor per your firmware / calibration.
     */
    *distance_cm = (float)raw * 0.1f;
    return 0;
}

/* ------------------------------- GPIO / alert ---------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", ALERT_GPIO);
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        return -1;
    }
    return 0;
}

static void check_threshold(float distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(ALERT_GPIO, 1) != 0) {
            fprintf(stderr, "gpioWrite(%d, 1) failed\n", ALERT_GPIO);
        }
    } else {
        if (gpioWrite(ALERT_GPIO, 0) != 0) {
            fprintf(stderr, "gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        }
    }
}

/* ------------------------------- Logging --------------------------------- */
static int init_log(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    /* Write a session header so the log is self-describing. */
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00+0000");
    }

    fprintf(g_log_file, "# Session start: %s\n", ts);
    fprintf(g_log_file, "# Format: timestamp,distance_cm,alert\n");
    fflush(g_log_file);
    return 0;
}

static void log_data(float distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL) {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00+0000");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", t);
    }

    bool alert = (distance < DISTANCE_THRESHOLD) ? true : false;

    if (fprintf(g_log_file, "%s,%.2f,%s\n", ts, distance, alert ? "true" : "false") < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Ensure alert is off before releasing GPIO. */
    gpioWrite(ALERT_GPIO, 0);
    gpioSetMode(ALERT_GPIO, PI_INPUT);

    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

