/*
 * CH201 Ultrasonic ToF Distance Monitor (Raspberry Pi 4 Model B)
 *
 * Hardware:
 *   - CH201 I2C:  bus 1 (GPIO 2 = SDA, GPIO 3 = SCL), address 0x29
 *   - LED:       GPIO 18 (BCM), 330 ohm resistor to 3.3 V
 *
 * Behaviour:
 *   - Reads the 16-bit distance register every 100 ms.
 *   - LED blinks faster as distance decreases (1 Hz -> 10 Hz).
 *   - Each loop iteration performs one half-cycle of the blink so the
 *     blinking stays smooth across samples.
 *   - Retries I2C operations up to three times with 10 ms back-off.
 *   - Clean shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define CH201_ADDR           0x29
#define LED_GPIO             18

#define DISTANCE_REG         0x00
#define DISTANCE_MAX         1000   /* cm at 100 % range */
#define SAMPLE_PERIOD_US     100000 /* 100 ms */
#define RETRY_COUNT          3
#define RETRY_DELAY_US       10000  /* 10 ms */

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static int  read_distance(int handle, uint16_t *distance);
static void set_led_blink_freq(int freq_hz);
static void cleanup(void);

/* ------------------------------ Signal --------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers ------------------------------- */

/*
 * Read the 16-bit distance register.
 * Returns 0 on success, -1 on failure.
 */
static int read_distance(int handle, uint16_t *distance)
{
    char buf[2];

    for (int attempt = 0; attempt < RETRY_COUNT; ++attempt) {
        int rc = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
        if (rc == 2) {
            *distance = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr,
                "I2C read attempt %d/%d failed (rc=%d): %s\n",
                attempt + 1, RETRY_COUNT, rc, strerror(errno));
        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------ LED blink ------------------------------ */

/*
 * Drive the LED GPIO for one half-cycle so that the blink stays smooth
 * across samples.  Each call performs one half-cycle; the caller must
 * call twice per loop iteration to blink at the desired rate.
 */
static void set_led_blink_freq(int freq_hz)
{
    if (freq_hz <= 0) {
        gpioWrite(LED_GPIO, 0);
        return;
    }

    uint32_t half_period_us = 500000 / (uint32_t)freq_hz;          /* 500 ms / freq */
    uint32_t on_us          = half_period_us;
    uint32_t off_us         = half_period_us;

    if (gpioWrite(LED_GPIO, 1) < 0)
        fprintf(stderr, "Warning: gpioWrite(LED on) failed: %s\n",
                strerror(errno));
    gpioDelay(on_us);

    if (gpioWrite(LED_GPIO, 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(LED off) failed: %s\n",
                strerror(errno));
    gpioDelay(off_us);
}

/* ------------------------------ Cleanup -------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, CH201_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH201 distance monitor started (bus %d, addr 0x%02X, LED GPIO %d).\n",
           I2C_BUS, CH201_ADDR, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            float freq_hz = 1.0f + ((float)distance / DISTANCE_MAX) * 9.0f;
            int   freq_int = (int)(freq_hz + 0.5f);

            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("[%s] Distance: %u cm  ->  LED blink: %d Hz\n",
                   ts, distance, freq_int);

            /*
             * Two half-cycles per loop iteration keeps the blink smooth
             * across samples while still allowing the loop period to
             * remain constant.
             */
            set_led_blink_freq(freq_int);
            set_led_blink_freq(freq_int);
        } else {
            fprintf(stderr, "Failed to read distance after retries.\n");
            /* Turn LED off on error to indicate the sensor is unreachable */
            gpioWrite(LED_GPIO, 0);
        }

        /* Sleep for the remainder of the 100 ms period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

