/*
 * Raspberry Pi 4 Model B — Dual TCRT5000 IR Obstacle Avoidance Logger
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO 17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO 27 (physical pin 13)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND   (physical pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o proximity_logger proximity_logger.c -lpigpio -lrt
 * Run:    sudo ./proximity_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_US   50000   /* 50 ms debounce window */
#define POLL_US       10000   /* 10 ms polling interval */
#define LOG_FILE      "proximity_log.txt"

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static int log_event(int sensor_id, const char *event_type)
{
    time_t now;
    struct tm tm_utc;
    char ts[32];

    time(&now);
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - Sensor %d: %s\n", ts, sensor_id, event_type) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                 */
/* ------------------------------------------------------------------ */

typedef struct {
    int gpio;
    int last_state;
    uint32_t last_change_tick;
} sensor_t;

static int init_sensor(sensor_t *s, int gpio)
{
    s->gpio = gpio;
    s->last_state = gpioRead(gpio);
    if (s->last_state < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d\n", gpio);
        return -1;
    }
    s->last_change_tick = gpioTick();
    return 0;
}

/*
 * Returns:
 *   1  -> DETECTED  (HIGH -> LOW)
 *   0  -> CLEARED   (LOW  -> HIGH)
 *   0  -> no change
 *  -1  -> read error
 */
static int read_sensor(sensor_t *s)
{
    int v = gpioRead(s->gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d\n", s->gpio);
        return -1;
    }

    if (v != s->last_state) {
        uint32_t now = gpioTick();
        uint32_t elapsed = now - s->last_change_tick;

        if (elapsed >= DEBOUNCE_US) {
            s->last_state = v;
            s->last_change_tick = now;

            if (s->last_state == 1) {
                return 1;  /* DETECTED */
            }
            return 0;     /* CLEARED  */
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    sensor_t s1, s2;
    int rc;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-downs so sensors read LOW when no obstacle is present */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensors ---- */
    if (init_sensor(&s1, SENSOR_1_GPIO) != 0 ||
        init_sensor(&s2, SENSOR_2_GPIO) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity logger started.  Sensor 1=GPIO%d  Sensor 2=GPIO%d\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);
    printf("Logging to '%s'.  Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        rc = read_sensor(&s1);
        if (rc == 1) {
            log_event(1, "DETECTED");
        } else if (rc == -1) {
            fprintf(stderr, "Sensor 1 read error — continuing\n");
        }

        rc = read_sensor(&s2);
        if (rc == 1) {
            log_event(2, "DETECTED");
        } else if (rc == -1) {
            fprintf(stderr, "Sensor 2 read error — continuing\n");
        }

        gpioDelay(POLL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            perror("fclose");
        }
        g_log_fp = NULL;
    }

    /* Release pigpio resources */
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

