/*
 * Raspberry Pi 5 - TDK CH-101 Time-of-Flight distance logger
 *
 * Wiring:
 *   CH-101 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   CH-101 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   CH-101 VDD  -> 3.3 V
 *   CH-101 GND  -> GND
 *
 * The CH-101 is a 7-bit I2C device (address 0x20).  We use a helper
 * that performs a combined write-then-read transaction so the
 * register pointer is set before the read.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_logger ch101_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x20

/* CH-101 register map (example values) */
#define CH101_REG_MEAS_STATUS  0x00
#define CH101_REG_DISTANCE_MM  0x04

#define LOG_FILE        "distance_log.csv"
#define SAMPLE_PERIOD_US 500000   /* 500 ms between samples */
#define MEAS_TIMEOUT_US  50000    /* 50 ms max wait for a measurement */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on error.
 */
static int ch101_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read N bytes starting at the given register.
 * Returns 0 on success, -1 on error.
 */
static int ch101_read_regs(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    /* Set the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg-ptr=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read the data bytes */
    ssize_t got = read(fd, dst, n);
    if (got < 0 || (size_t)got != n) {
        fprintf(stderr, "read(reg=0x%02X, len=%zu) failed: %s (got %zd)\n",
                reg, n, strerror(errno), got);
        return -1;
    }
    return 0;
}

/*
 * Perform a combined write-then-read transaction in one I2C
 * transaction so the register pointer is set before the read.
 * Returns 0 on success, -1 on error.
 */
static int ch101_read_reg_combined(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[32];

    if (n > sizeof(rbuf)) {
        fprintf(stderr, "requested read length %zu exceeds buffer\n", n);
        return -1;
    }

    struct i2c_msg msgs[2] = {
        { .addr = CH101_ADDR, .flags = 0,            .len = 1, .buf = wbuf },
        { .addr = CH101_ADDR, .flags = I2C_M_RD,     .len = (uint16_t)n, .buf = rbuf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C_RDWR(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    memcpy(dst, rbuf, n);
    return 0;
}

/*
 * Wait for the MEAS_STATUS register to indicate data ready,
 * then read the distance in millimetres.
 * Returns 0 on success, -1 on error.
 */
static int ch101_read_distance_mm(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int elapsed = 0;

    /* Poll MEAS_STATUS until bit 0 is set (data ready) */
    while (elapsed < MEAS_TIMEOUT_US) {
        if (ch101_read_regs(fd, CH101_REG_MEAS_STATUS, &status, 1) != 0)
            return -1;
