        usleep(2000);
        elapsed += 2000;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "CH-101 measurement timeout (status=0x%02X)\n", status);
        return -1;
    }

    /* Read the 16-bit distance value */
    uint8_t raw[2];
    if (ch101_read_regs(fd, CH101_REG_DISTANCE_MM, raw, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)raw[0] << 8) | raw[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    /* Write a header only if the file is empty */
    long pos = ftell(g_log_fp);
    if (pos == 0) {
        fprintf(g_log_fp, "timestamp,distance_mm\n");
        fflush(g_log_fp);
    }
    return 0;
}

static void log_sample(uint16_t distance_mm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");

