/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * The MLX75030 exposes a 16-bit distance value via a 16-bit register
 * (0x00) that is read as two consecutive bytes.  The sensor is assumed
 * to be at I2C address 0x60.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c -lpigpio -lrt
 * Run:    sudo ./mlx75030
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define MLX75030_ADDR    0x60
#define DISTANCE_REG     0x00
#define SAMPLE_PERIOD_US 100000          /* 100 ms */
#define MAX_RETRIES      3
#define RETRY_DELAY_US   10000           /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "[timestamp-error]");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Read the 16-bit distance register (0x00).
 * Returns 0 on success and stores the distance in *distance;
 * returns -1 on failure.
 */
static int read_distance(int handle, uint16_t *distance)
{
    char buf[2];

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
        if (rc == 2) {
            *distance = ((uint16_t)(uint8_t)buf[0] << 8) |
                        (uint16_t)(uint8_t)buf[1];
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 distance reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("[%s] Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "[%s] Error: failed to read distance after %d retries.\n",
                    ts, MAX_RETRIES);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

