#define VL53L4CX_REG_DSS_RESULT_SPARE_75    0x00FE

/* Globals for signal handling */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (big-endian on the bus)                     */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error writing 0x%04X to register 0x%04X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian on the bus)                      */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint16_t)(data_buf[1] & 0xFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 32-bit register (big-endian on the bus)                      */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read32(int handle, uint16_t reg, uint32_t *value)
{
    char reg_buf[2];
    char data_buf[4];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 4) != 4) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint32_t)(data_buf[0] & 0xFF) << 24) |
             ((uint32_t)(data_buf[1] & 0xFF) << 16) |
             ((uint32_t)(data_buf[2] & 0xFF) << 8)  |
             ((uint32_t)(data_buf[3] & 0xFF));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor                                      */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    uint16_t model_id = 0;

    /* Read and verify model ID */
    if (vl53l4cx_read16(handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Unexpected model ID: 0x%04X (expected 0xEACC)\n", model_id);
        return -1;
    }

    /* Soft reset */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_SOFT_RESET, 0x0001) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    /* Clear any pending interrupt */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) != 0)
        return -1;

    /* Configure GPIO HV mux (optional: set to standard mode) */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_GPIO_HV_MUX_CTRL, 0x0000) != 0)
        return -1;

    /* Configure interrupt polarity (active high) */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_INT_POLARITY, 0x0000) != 0)
        return -1;

    /* Enable data ready interrupt on new sample ready */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_INT_MSK, 0x0001) != 0)
        return -1;

    /* Start ranging (bit 0 = start) */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_SYSTEM_START, 0x0001) != 0)
        return -1;

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from the VL53L4CX sensor                              */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance)
{
    uint16_t status = 0;
    uint32_t dist = 0;

    /* Check if data is ready */
    if (vl53l4cx_read16(handle, VL53L4CX_REG_GPIO_TIO_HV_STATUS, &status) != 0)
        return -1;

    if ((status & 0x0001) == 0) {
        /* Data not ready yet */
        return 1;
    }

    /* Read distance */
    if (vl53l4cx_read32(handle, VL53L4CX_REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    *distance = (uint16_t)(dist & 0xFFFF);

    /* Clear interrupt */
    if (vl53l4cx_write16(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    struct timespec ts;
    uint16_t distance = 0;
    int rc;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29 */
    g_i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                VL53L4CX_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l4cx_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance sensor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        rc = vl53l4cx_read_distance(g_i2c_handle, &distance);
        if (rc == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %u mm\n",
                   ts.tv_sec / 86400 + 24405,
                   (ts.tv_sec / 86400) % 7 + 1,
                   (ts.tv_sec % 86400) / 3600,
                   (ts.tv_sec % 3600) / 60,
                   ts.tv_sec % 60,
                   ts.tv_nsec / 1000,
                   distance);
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance data\n");
        }
        /* rc == 1: data not ready, just skip */

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

