#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define VL53L1X_ADDR    0x29
#define BUZZER_PIN      22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 500000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0014
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0084
#define VL53L1X_REG_SYSTEM_THRESHOLD_CONFIG 0x0088
#define VL53L1X_REG_SYSTEM_CONFIG           0x008A
#define VL53L1X_REG_RANGE_CONFIG_A          0x008C
#define VL53L1X_REG_RANGE_CONFIG_B          0x008E
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x0080
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0082

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte of data */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address + 2 bytes of data (big-endian) */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write16 to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes from a 16-bit register address */
static int i2c_read_reg(int fd, uint16_t reg, uint8_t *data, size_t len) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, data, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);

    /* Clear any pending interrupts */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    /* Configure interrupt polarity (active low) */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) return -1;

    /* Set threshold for new sample ready (0x0A = 10 mm) */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_THRESHOLD_CONFIG, 0x0A) < 0) return -1;

    /* Set config register (e.g., enable interrupt on new sample) */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_CONFIG, 0x01) < 0) return -1;

    /* Set range config A (e.g., timing budget) */
    if (i2c_write_reg16(fd, VL53L1X_REG_RANGE_CONFIG_A, 0x006B) < 0) return -1;

    /* Set range config B (e.g., intermeasurement period) */
    if (i2c_write_reg16(fd, VL53L1X_REG_RANGE_CONFIG_B, 0x006B) < 0) return -1;

    /* Set intermeasurement period to 100 ms (0x0064 = 100 ms * 100 = 10000) */
    if (i2c_write_reg16(fd, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x0064) < 0) return -1;

    /* Set system intermeasurement to 100 ms (0x0064 = 100 ms * 100 = 10000) */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x0064) < 0) return -1;

    /* Start continuous ranging mode */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    uint8_t data[2];

    /* Check if a new sample is ready */
    if (i2c_read_reg(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;

    if ((status & 0x01) == 0) {
        /* No new sample ready yet */
        return 1;
    }

    /* Read 2-byte distance (big-endian) */
    if (i2c_read_reg(fd, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0) return -1;

    *distance = ((uint16_t)data[0] << 8) | data[1];

    /* Clear the interrupt so the next measurement can trigger */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_PIN, 0);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_fd, &distance);

        if (rc == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance, skipping iteration.\n");
        }
        /* rc == 1 means no new sample ready; just wait */

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (g_i2c_fd >= 0) {
        /* Stop continuous ranging mode */
        i2c_write_reg8(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

