#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000
#define LOOP_DELAY_US     200000
#define MIN_DISTANCE_CM   2.0
#define MAX_DISTANCE_CM   400.0
#define SERVO_MIN_ANGLE   -90
#define SERVO_MAX_ANGLE   90
#define LOG_FILE          "sensor_data.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_data(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);
    } else {
        fprintf(fp, "(unknown time), Distance: %.2f cm\n", distance_cm);
    }

    fclose(fp);
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise TRIGGER_PIN low\n");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Stop servo pulses before releasing pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

static float read_distance_cm(void)
{
    /* Ensure trigger is low for a clean pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set trigger low\n");
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set trigger low\n");
        return -1.0f;
    }

    uint32_t start_tick = gpioTick();
    uint32_t timeout_tick = start_tick;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo start timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo end timeout\n");
            return -1.0f;
        }
    }
    uint32_t end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance_cm = (float)diff / 58.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance_cm);
        return -1.0f;
    }

    return distance_cm;
}

static int set_servo_angle(int angle)
{
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }

    int pulse_width = 1000 + (angle * 1000) / 180;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse_width);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance_cm();

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read failed; skipping servo update.\n");
        } else {
            float angle = (distance - MIN_DISTANCE_CM) *
                          (float)(SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) /
                          (MAX_DISTANCE_CM - MIN_DISTANCE_CM) +
                          SERVO_MIN_ANGLE;

            if (set_servo_angle((int)angle) < 0) {
                fprintf(stderr, "Servo set failed.\n");
            }

            log_data(distance);
            printf("Distance: %.2f cm, Angle: %d°\n", distance, (int)angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

