/*
 * VL53L1X distance monitor with buzzer alert on Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1 (SDA=GPIO2, SCL=GPIO3), address 0x29
 *   - Buzzer on GPIO23 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_buzzer vl53l1x_buzzer.c \
 *       -lpigpio -lrt -lm
 *
 * Run:
 *   sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <mqueue.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define BUZZER_GPIO          23
#define DISTANCE_THRESHOLD   100   /* mm */
#define TIMING_BUDGET_MS     50    /* 50 ms */
#define POLL_DELAY_US        50000 /* 50 ms */
#define MQ_NAME              "/vl53l1x_queue"

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_SYSTEM_INT_CLR   0x000B
#define VL53L1X_REG_RESULT_INT_STA   0x0044
#define VL53L1X_REG_RESULT_RANGE_VAL 0x0096
#define VL53L1X_REG_RANGE_CONFIG_A   0x005E
#define VL53L1X_REG_RANGE_CONFIG_B   0x0061
#define VL53L1X_REG_INTERMEAS_MS     0x006B
#define VL53L1X_REG_SYSTEM_THRESH    0x0089

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static mqd_t    g_mq         = (mqd_t)-1;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int h, uint16_t reg, uint8_t val);
static int  vl53l1x_read16(int h, uint16_t reg, uint16_t *out);
static int  vl53l1x_read_range(int h, uint16_t *distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */

/*
 * VL53L1X uses 16-bit register addresses (big-endian on the bus).
 * pigpio's i2cWriteI2CBlockData sends [reg_hi, reg_lo, data...], so we
 * pre-pend the 16-bit address to the payload.
 */
static int vl53l1x_write16(int h, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteI2CBlockData(h, buf[0], buf + 1, 2);
}

static int vl53l1x_read16(int h, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];
    int  rc;

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    rc = i2cWriteI2CBlockData(h, addr[0], addr, 1);
    if (rc < 0)
        return -1;

    rc = i2cReadI2CBlockData(h, addr[0], data, 2);
    if (rc < 0)
        return -1;
    if (rc != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ----------------------------- Sensor ------------------------------------- */

static int vl53l1x_init(int h)
{
    uint16_t id;

    /* Soft reset */
    if (vl53l1x_write16(h, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "VL53L1X: soft-reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    if (vl53l1x_write16(h, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "VL53L1X: soft-reset release failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Read model / revision ID (0x010F) to confirm sensor presence */
    if (vl53l1x_read16(h, 0x010F, &id) < 0) {
        fprintf(stderr, "VL53L1X: cannot read model ID (sensor absent?)\n");
        return -1;
    }
    if ((id & 0x00FF) != 0x10) {
        fprintf(stderr, "VL53L1X: unexpected model ID 0x%04X\n", id);
        return -1;
    }

    /* Set timing budget to 50 ms (0x0032) */
    if (vl53l1x_write16(h, VL53L1X_REG_RANGE_CONFIG_A, 0x0032) < 0) {
        fprintf(stderr, "VL53L1X: set timing budget failed\n");
        return -1;
    }

    /* Set inter-measurement period to 50 ms (0x0032) */
    if (vl53l1x_write16(h, VL53L1X_REG_INTERMEAS_MS, 0x0032) < 0) {
        fprintf(stderr, "VL53L1X: set inter-measurement failed\n");
        return -1;
    }

    /* Start continuous ranging (bit 0 = 1) */
    if (vl53l1x_write16(h, VL53L1X_REG_SYSTEM_MODE, 0x01) < 0) {
        fprintf(stderr, "VL53L1X: start ranging failed\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_range(int h, uint16_t *distance_mm)
{
    uint16_t status;
    int      rc;

    /* Poll for data-ready (bit 0 of RESULT_INT_STA) */
    for (int i = 0; i < 50; i++) {
        rc = vl53l1x_read16(h, VL53L1X_REG_RESULT_INT_STA, &status);
        if (rc < 0)
            return -1;
        if (status & 0x0001)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x0001)) {
        fprintf(stderr, "VL53L1X: timeout waiting for data-ready\n");
        return -1;
    }

    /* Read distance */
    rc = vl53l1x_read16(h, VL53L1X_REG_RESULT_RANGE_VAL, distance_mm);
    if (rc < 0)
        return -1;

    /* Clear interrupt so next measurement can trigger */
    if (vl53l1x_write16(h, VL53L1X_REG_SYSTEM_INT_CLR, 0x01) < 0)
        return -1;

    return 0;
}

/* ----------------------------- Buzzer ------------------------------------- */

static void buzzer_on(void)
{
    gpioWrite(BUZZER_GPIO, 1);
}

static void buzzer_off(void)
{
    gpioWrite(BUZZER_GPIO, 0);
}

/* ----------------------------- MQ ----------------------------------------- */

static int mq_send(uint16_t distance)
{
    char msg_buf[8];
    struct mq_attr attr;
    struct timespec ts;

    /* Create queue if it does not exist */
    attr.mq_flags   = 0;
    attr.mq_maxmsg  = 10;
    attr.mq_msgsize = sizeof(msg_buf);
    attr.mq_curmsgs = 0;

    g_mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (g_mq == (mqd_t)-1) {
        perror("mq_open");
        return -1;
    }

    /* Build message: timestamp_ms + distance_mm */
    ts = clock_gettime_nsec();
    uint64_t ts_ms = (uint64_t)ts.tv_sec * 1000ULL + (uint64_t)ts.tv_nsec / 1000000ULL;
    memcpy(msg_buf, &ts_ms, sizeof(ts_ms));
    memcpy(msg_buf + sizeof(ts_ms), &distance, sizeof(distance));

    if (mq_send(g_mq, msg_buf, sizeof(msg_buf), 0) == -1) {
        perror("mq_send");
        mq_close(g_mq);
        g_mq = (mqd_t)-1;
        return -1;
    }
    return 0;
}

/* ----------------------------- Signal / Cleanup --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Stop ranging */
        vl53l1x_write16(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    buzzer_off();
    gpioTerminate();
    if (g_mq != (mqd_t)-1) {
        mq_close(g_mq);
        g_mq = (mqd_t)-1;
    }
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    struct sigaction sa;

    /* Install signal handlers */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    buzzer_off();

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X initialized on I2C bus %d, addr 0x%02X. Monitoring distance...\n",
           I2C_BUS, VL53L1X_ADDR);

    /* Main loop */
    while (g_running) {
        uint16_t distance;

        if (vl53l1x_read_range(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            buzzer_on();
            gpioDelay(200000); /* 200 ms */
            buzzer_off();
        }

        if (mq_send(distance) < 0) {
            fprintf(stderr, "Failed to send message to MQ\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

