/*
 * Parking sensor using HC-SR04 ultrasonic sensor on a Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 27 (BCM)
 *   Buzzer       -> GPIO 22 (BCM)
 *
 * Behaviour:
 *   - Trigger a 10 us HIGH pulse on the TRIG pin every 100 ms.
 *   - Measure the echo pulse width using the pigpio interrupt-driven API.
 *   - Compute distance in cm and print it to stdout.
 *   - Activate the buzzer while distance < 30 cm and deactivate when >= 30 cm.
 *   - On SIGINT, turn off the buzzer and release pigpio resources.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o parking_sensor parking_sensor.c -lpigpio -lrt
 *   (run as root, or with appropriate gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define TRIGGER_PULSE_US 10
#define POLL_INTERVAL_US 100000           /* 100 ms */
#define ECHO_TIMEOUT_US  30000            /* 30 ms max echo wait */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define THRESHOLD_CM     30.0

/* Shared state between ISR and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_running    = true;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Echo ISR                                                            */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        if (g_start_tick != 0) {
            g_end_tick = tick;
            g_echo_seen = true;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static float measure_distance(void)
{
    /* Reset shared state */
    g_start_tick = 0;
    g_end_tick   = 0;
    g_echo_seen  = false;

    /* Generate 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN HIGH\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN LOW\n");
        return -1.0f;
    }

    /* Wait for echo with timeout */
    uint32_t waited = 0;
    while (!g_echo_seen && waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);
        waited += 100;
    }

    if (!g_echo_seen) {
        fprintf(stderr, "Warning: echo timeout - sensor absent or not responding\n");
        return -1.0f;
    }

    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t diff = g_end_tick - g_start_tick;
    if (diff == 0) {
        fprintf(stderr, "Warning: zero tick difference (wraparound)\n");
        return -1.0f;
    }

    /* distance = (time_us * speed_cm_per_us) / 2 */
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void control_buzzer(float distance)
{
    if (distance < 0.0f) {
        gpioWrite(BUZZER_PIN, 0);
        return;
    }

    if (distance < THRESHOLD_CM) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to activate buzzer\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to deactivate buzzer\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo interrupt */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo callback\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float distance = measure_distance();

        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Sensor read failed - check wiring and sensor presence.\n");
            gpioWrite(BUZZER_PIN, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

