        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo interrupt */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo callback\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        float distance = measure_distance();

        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Sensor read failed - check wiring and sensor presence.\n");
            gpioWrite(BUZZER_PIN, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

