/*
 * Gate controller for Raspberry Pi Zero W
 * Sensor : VL53L1X time-of-flight (I2C bus 1, addr 0x29)
 * Servo  : SG90 on GPIO18 (BCM), hardware PWM
 * Log    : gate_log.txt
 *
 * Build  : gcc -O2 -Wall -o gate gate.c -lpigpio -lrt
 * Run    : sudo ./gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18
#define DISTANCE_THRESHOLD   20          /* cm */
#define LOG_FILE             "gate_log.txt"
#define POLL_DELAY_US        50000       /* 50 ms */
#define SERVO_SETTLE_MS      500         /* ms */
#define SERVO_OPEN_US        1500        /* 1.5 ms */
#define SERVO_CLOSE_US       1000        /* 1.0 ms */
#define SERVO_RANGE_US       2000        /* 2.0 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_SYSTEM_INT_CLR   0x000B
#define VL53L1X_REG_RESULT_INT_STA   0x0044
#define VL53L1X_REG_RESULT_RANGE_VAL 0x0096
#define VL53L1X_REG_RANGE_START      0x0080

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static void log_event(const char *msg);
static int  i2c_write_reg16(int h, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int h, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int h);
static int  vl53l1x_read_distance(int h, uint16_t *distance);
static void servo_set_pulse_width(int pin, uint32_t pulse_us);
static void servo_open(void);
static void servo_close(void);
static void servo_stop(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_file);
}

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg16(int h, uint16_t reg, uint8_t val)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = val;
    return i2cWriteDevice(h, (char *)buf, 3);
}

static int i2c_read_reg16(int h, uint16_t reg, uint8_t *buf, uint32_t len)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (i2cWriteDevice(h, (char *)addr, 2) != 0)
        return -1;
    return i2cReadDevice(h, (char *)buf, len);
}

/* ----------------------------- VL53L1X ----------------------------------- */
static int vl53l1x_init(int h)
{
    /* Software reset */
    if (i2c_write_reg16(h, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        log_event("VL53L1X: soft reset write failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (i2c_write_reg16(h, VL53L1X_REG_SOFT_RESET, 0x01) != 0) {
        log_event("VL53L1X: soft reset release failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Wait for firmware to boot (bit 0 of SYSTEM_MODE toggles) */
    for (int i = 0; i < 50; i++) {
        uint8_t mode = 0;
        if (i2c_read_reg16(h, VL53L1X_REG_SYSTEM_MODE, &mode, 1) != 1) {
            log_event("VL53L1X: failed to read SYSTEM_MODE");
            return -1;
        }
        if (mode & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }

    /* Start continuous ranging */
    if (i2c_write_reg16(h, VL53L1X_REG_SYSTEM_MODE, 0x02) != 0) {
        log_event("VL53L1X: failed to start ranging");
        return -1;
    }

    log_event("VL53L1X initialized and ranging started");
    return 0;
}

static int vl53l1x_read_distance(int h, uint16_t *distance)
{
    uint8_t buf[2];
    int rc = i2c_read_reg16(h, VL53L1X_REG_RESULT_RANGE_VAL, buf, 2);
    if (rc != 2) {
        log_event("VL53L1X: I2C read error");
        return -1;
    }
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- Servo ------------------------------------- */
static void servo_set_pulse_width(int pin, uint32_t pulse_us)
{
    if (pulse_us < SERVO_RANGE_US)
        pulse_us = SERVO_RANGE_US;
    if (pulse_us > 20000)
        pulse_us = 20000;

    gpioServo(pin, pulse_us);
}

static void servo_open(void)
{
    servo_set_pulse_width(SERVO_PIN, SERVO_OPEN_US);
    log_event("Servo: gate opened");
}

static void servo_close(void)
{
    servo_set_pulse_width(SERVO_PIN, SERVO_CLOSE_US);
    log_event("Servo: gate closed");
}

static void servo_stop(void)
{
    gpioServo(SERVO_PIN, 0);
}

/* ----------------------------- Gate control ------------------------------ */
static void control_gate(uint16_t distance)
{
    if (distance > 0 && distance < DISTANCE_THRESHOLD) {
        servo_open();
        log_event("Object detected within threshold -> gate opened");
    } else {
        servo_close();
        log_event("Clear path -> gate closed");
    }
}

/* ----------------------------- Driver callbacks -------------------------- */
static void force_open(void)
{
    servo_open();
    log_event("Force open command received");
}

static void force_close(void)
{
    servo_close();
    log_event("Force close command received");
}

static void status_request(void)
{
    uint16_t dist = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &dist) == 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Status: distance=%u mm", dist);
        log_event(msg);
    } else {
        log_event("Status: sensor read error");
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        log_event("I2C open failed");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        log_event("VL53L1X init failed");
        i2cClose(g_i2c_handle);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure servo pin */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    servo_stop();

    /* Register callbacks (v2 API) */
    int cb_open   = gpioSetAlertFuncEx(SERVO_PIN, force_open, NULL);
    int cb_close  = gpioSetAlertFuncEx(SERVO_PIN + 1, force_close, NULL);
    int cb_status = gpioSetAlertFuncEx(SERVO_PIN + 2, status_request, NULL);
    if (cb_open != 0 || cb_close != 0 || cb_status != 0) {
        fprintf(stderr, "Failed to register callbacks\n");
        log_event("Callback registration failed");
        i2cClose(g_i2c_handle);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Gate controller started");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            control_gate(distance);
        } else {
            log_event("Sensor read error, retrying...");
            gpioDelay(100000); /* 100 ms backoff */
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    log_event("Shutting down");
    servo_stop();
    i2cClose(g_i2c_handle);
    fclose(g_log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

