/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM)
 *
 * NOTE: The ECHO line is 5 V and must be level-shifted or divided
 *       for the Pi's 3.3 V tolerance.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN          23
#define ECHO_PIN          24

#define TRIG_PULSE_US     10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_US  200000      /* 200 ms between measurements    */
#define ECHO_TIMEOUT_US   60000       /* 60 ms max echo wait            */
#define MIN_PULSE_US      100         /* reject noise below this        */
#define MAX_PULSE_US      30000       /* reject no-object / timeout     */

#define SPEED_OF_SOUND_CM_PER_US 0.0343  /* cm/µs at 20 °C               */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo edge timestamp capture (falling edge)                          */
/* ------------------------------------------------------------------ */
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
    bool     have_rising;
    bool     have_falling;
} echo_state_t;

static echo_state_t g_echo = {0, 0, false, false};

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge — start of echo pulse */
        g_echo.rising_tick   = tick;
        g_echo.have_rising   = true;
        g_echo.have_falling  = false;
    } else if (level == 0) {
        /* Falling edge — end of echo pulse */
        if (g_echo.have_rising) {
            g_echo.falling_tick  = tick;
            g_echo.have_falling  = true;
        }
    }
    /* level == 2 (timeout) is ignored here; pigpio reports it via
     * gpioSetAlertFuncEx timeout callback. */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* pigpio ticks are 32-bit microseconds and wrap every ~72 min.
 * Compute (b - a) modulo 2^32 so wraparound is handled correctly. */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;            /* unsigned subtraction wraps correctly */
}

static void log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(stdout);

    if (g_log_file) {
        fprintf(g_log_file, "%s Distance: %.2f cm\n", timestamp, distance_cm);
        fflush(g_log_file);
    }
}

static void log_warning(const char *msg)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "%s WARNING: %s\n", timestamp, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s WARNING: %s\n", timestamp, msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Release GPIO alert callbacks and terminate pigpio */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on ECHO so it reads LOW when idle */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIG_PIN %d LOW.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(500000);  /* 500 ms */

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, %.1f Hz sampling.\n",
           TRIG_PIN, ECHO_PIN, 1.0 / (SAMPLE_PERIOD_US / 1000000.0));

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset echo state for this cycle */
        g_echo.rising_tick   = 0;
        g_echo.falling_tick  = 0;
        g_echo.have_rising   = false;
        g_echo.have_falling  = false;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) < 0) {
            log_warning("Failed to set TRIG_PIN HIGH");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) < 0) {
            log_warning("Failed to set TRIG_PIN LOW");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo.have_falling && g_running) {
            if (tick_diff(wait_start, gpioTick()) > ECHO_TIMEOUT_US) {
                log_warning("Echo timeout — no object detected or sensor disconnected");
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_echo.have_falling) {
            /* Timeout already reported; skip this cycle */
            gpioDelay(SAMPLE_PERIOD_US - ECHO_TIMEOUT_US);
            continue;
        }

        /* Compute pulse width (handles 32-bit tick wraparound) */
        uint32_t pulse_us = tick_diff(g_echo.rising_tick, g_echo.falling_tick);

        /* Reject noise / timeout / no-object */
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Invalid pulse width %u µs (range %d–%d µs)",
                     pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            log_warning(msg);
            gpioDelay(SAMPLE_PERIOD_US - pulse_us);
            continue;
        }

        /* Compute distance: d = (pulse_us * speed_of_sound) / 2 */
        float distance_cm = (pulse_us * SPEED_OF_SOUND_CM_PER_US) / 2.0f;
        log_distance(distance_cm);

        /* Remaining sampling period (interruptible) */
        uint32_t elapsed = tick_diff(g_echo.falling_tick, wait_start);
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

