    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d, %.1f Hz sampling.\n",
           TRIG_PIN, ECHO_PIN, 1.0 / (SAMPLE_PERIOD_US / 1000000.0));

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset echo state for this cycle */
        g_echo.rising_tick   = 0;
