code:
/*
 * Smart Parking Gate Controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   - VL53L1X shutdown line  -> GPIO23 (BCM)
 *   - VL53L1X interrupt line  -> GPIO24 (BCM)
 *   - Servo motor on GPIO18 (BCM)
 *
 * Behaviour:
 *   - Opens gate when an object is within 50 cm.
 *   - Closes gate when an object is beyond 60 cm.
 *   - Logs state changes with distance to parking_log.txt.
 *   - Clean shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              "/dev/i2c-1"
#define VL53L1X_ADDR         0x29

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_MODEL_ID_EXPECTED           0xEA

#define SHUTDOWN_PIN          23
#define INTERRUPT_PIN         24
#define SERVO_PIN             18

#define DISTANCE_THRESHOLD_OPEN   50   /* cm */
#define DISTANCE_THRESHOLD_CLOSE  60   /* cm */
#define SERVO_OPEN_PULSE_US       1500
#define SERVO_CLOSE_PULSE_US      1000
#define SERVO_CENTER_PULSE_US     1300
#define SERVO_RANGE_US            2000
#define SERVO_FREQ_HZ             50

#define LOG_FILE              "parking_log.txt"
#define POLL_DELAY_US         100000   /* 100 ms */
#define MEAS_TIMEOUT_MS       100

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_servo_fd = -1;
static FILE *g_log_fp  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg16(int fd, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len);
static int  vl53l1x_init(int fd);
static int  vl53l1x_read_distance(int fd, uint16_t *distance_mm);
static void log_event(const char *event, uint16_t distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        val
    };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X ----------------------------------- */
static int vl53l1x_init(int fd)
{
    uint8_t model_id = 0;

    if (i2c_read_reg16(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID,
                       &model_id, 1) != 0) {
        fprintf(stderr, "Failed to read VL53L1X model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "VL53L1X model ID mismatch: got 0x%02X, expected 0x%02X\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Start ranging (bit 0 = mode_start) */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0, 0};
    int     elapsed = 0;

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    while (elapsed < MEAS_TIMEOUT_MS) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS,
                           &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }
    if (elapsed >= MEAS_TIMEOUT_MS) {
        fprintf(stderr, "VL53L1X measurement timeout\n");
        return -1;
    }

    /* Read 2-byte distance */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt so the next measurement can be flagged */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ----------------------------- Servo ------------------------------------- */
static int servo_init(void)
{
    /* pigpio hardware PWM on GPIO18 */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", SERVO_PIN);
        return -1;
    }
    if (gpioSetPWMrange(SERVO_PIN, SERVO_RANGE_US) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", SERVO_PIN);
        return -1;
    }
    if (gpioPWM(SERVO_PIN, SERVO_CENTER_PULSE_US) != 0) {
        fprintf(stderr, "Failed to initialise servo PWM on GPIO%d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void servo_set_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    /* Map 0..180 degrees to 1000..2000 us pulse width */
    int pulse_us = SERVO_CENTER_PULSE_US +
                   (int)((angle - 90) * (SERVO_RANGE_US / 180));

    if (pulse_us < SERVO_CENTER_PULSE_US - 50)
        pulse_us = SERVO_CENTER_PULSE_US - 50;
    if (pulse_us > SERVO_CENTER_PULSE_US + 50)
        pulse_us = SERVO_CENTER_PULSE_US + 50;

    gpioPWM(SERVO_PIN, pulse_us);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event, uint16_t distance_mm)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s - %s - Distance: %u mm\n",
            ts, event, distance_mm);
    fflush(g_log_fp);
}

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_servo_fd >= 0) {
        gpioPWM(SERVO_PIN, SERVO_CENTER_PULSE_US);
        gpioDelay(500000); /* 500 ms to let servo settle */
        gpioServo(SERVO_PIN, 0);
        close(g_servo_fd);
        g_servo_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        (void)i2c_write_reg16(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise servo */
    if (servo_init() != 0) {
        fprintf(stderr, "Servo initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set shutdown pin as output (high = active) */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 1);

    /* Set interrupt pin as input (sensor drives it) */
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", INTERRUPT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Parking Gate Controller started.\n");
    printf("Thresholds: open < %d cm, close > %d cm\n",
           DISTANCE_THRESHOLD_OPEN, DISTANCE_THRESHOLD_CLOSE);

    bool gate_open = false;

    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Sensor read error — keeping gate %s\n",
                    gate_open ? "OPEN" : "CLOSED");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int distance_cm = distance_mm / 10;

        if (distance_cm < DISTANCE_THRESHOLD_OPEN && !gate_open) {
            servo_set_angle(0);
            gate_open = true;
            log_event("Gate OPENED", distance_mm);
            printf("Gate OPENED (distance: %d cm)\n", distance_cm);
        } else if (distance_cm > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            servo_set_angle(180);
            gate_open = false;
            log_event("Gate CLOSED", distance_mm);
            printf("Gate CLOSED (distance: %d cm)\n", distance_cm);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

raw:
/*
 * Smart Parking Gate Controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   - VL53L1X shutdown line  -> GPIO23 (BCM)
 *   - VL53L1X interrupt line  -> GPIO24 (BCM)
 *   - Servo motor on GPIO18 (BCM)
 *
 * Behaviour:
 *   - Opens gate when an object is within 50 cm.
 *   - Closes gate when an object is beyond 60 cm.
 *   - Logs state changes with distance to parking_log.txt.
 *   - Clean shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              "/dev/i2c-1"
#define VL53L1X_ADDR         0x29

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_MODEL_ID_EXPECTED           0xEA

#define SHUTDOWN_PIN          23
#define INTERRUPT_PIN         24
#define SERVO_PIN             18

#define DISTANCE_THRESHOLD_OPEN   50   /* cm */
#define DISTANCE_THRESHOLD_CLOSE  60   /* cm */
#define SERVO_OPEN_PULSE_US       1500
#define SERVO_CLOSE_PULSE_US      1000
#define SERVO_CENTER_PULSE_US     1300
#define SERVO_RANGE_US            2000
#define SERVO_FREQ_HZ             50

#define LOG_FILE              "parking_log.txt"
#define POLL_DELAY_US         100000   /* 100 ms */
#define MEAS_TIMEOUT_MS       100

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static int  g_servo_fd = -1;
static FILE *g_log_fp  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg16(int fd, uint16_t reg, uint8_t val);
static int  i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len);
static int  vl53l1x_init(int fd);
static int  vl53l1x_read_distance(int fd, uint16_t *distance_mm);
static void log_event(const char *event, uint16_t distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        val
    };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X ----------------------------------- */
static int vl53l1x_init(int fd)
{
    uint8_t model_id = 0;

    if (i2c_read_reg16(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID,
                       &model_id, 1) != 0) {
        fprintf(stderr, "Failed to read VL53L1X model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "VL53L1X model ID mismatch: got 0x%02X, expected 0x%02X\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Start ranging (bit 0 = mode_start) */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0, 0};
    int     elapsed = 0;

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    while (elapsed < MEAS_TIMEOUT_MS) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS,
                           &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        elapsed++;
    }
    if (elapsed >= MEAS_TIMEOUT_MS) {
        fprintf(stderr, "VL53L1X measurement timeout\n");
        return -1;
    }

    /* Read 2-byte distance */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt so the next measurement can be flagged */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

/* ----------------------------- Servo ------------------------------------- */
static int servo_init(void)
{
    /* pigpio hardware PWM on GPIO18 */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", SERVO_PIN);
        return -1;
    }
    if (gpioSetPWMrange(SERVO_PIN, SERVO_RANGE_US) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", SERVO_PIN);
        return -1;
    }
    if (gpioPWM(SERVO_PIN, SERVO_CENTER_PULSE_US) != 0) {
        fprintf(stderr, "Failed to initialise servo PWM on GPIO%d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void servo_set_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    /* Map 0..180 degrees to 1000..2000 us pulse width */
    int pulse_us = SERVO_CENTER_PULSE_US +
                   (int)((angle - 90) * (SERVO_RANGE_US / 180));

    if (pulse_us < SERVO_CENTER_PULSE_US - 50)
        pulse_us = SERVO_CENTER_PULSE_US - 50;
    if (pulse_us > SERVO_CENTER_PULSE_US + 50)
        pulse_us = SERVO_CENTER_PULSE_US + 50;

    gpioPWM(SERVO_PIN, pulse_us);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event, uint16_t distance_mm)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s - %s - Distance: %u mm\n",
            ts, event, distance_mm);
    fflush(g_log_fp);
}

/* ----------------------------- Signal / Cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_servo_fd >= 0) {
        gpioPWM(SERVO_PIN, SERVO_CENTER_PULSE_US);
        gpioDelay(500000); /* 500 ms to let servo settle */
        gpioServo(SERVO_PIN, 0);
        close(g_servo_fd);
        g_servo_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        (void)i2c_write_reg16(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise servo */
    if (servo_init() != 0) {
        fprintf(stderr, "Servo initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set shutdown pin as output (high = active) */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 1);

    /* Set interrupt pin as input (sensor drives it) */
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", INTERRUPT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Parking Gate Controller started.\n");
    printf("Thresholds: open < %d cm, close > %d cm\n",
           DISTANCE_THRESHOLD_OPEN, DISTANCE_THRESHOLD_CLOSE);

    bool gate_open = false;

    while (g_running) {
        uint16_t distance_mm = 0;

        if (vl53l1x_read_distance(g_i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Sensor read error — keeping gate %s\n",
                    gate_open ? "OPEN" : "CLOSED");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int distance_cm = distance_mm / 10;

        if (distance_cm < DISTANCE_THRESHOLD_OPEN && !gate_open) {
            servo_set_angle(0);
            gate_open = true;
            log_event("Gate OPENED", distance_mm);
            printf("Gate OPENED (distance: %d cm)\n", distance_cm);
        } else if (distance_cm > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            servo_set_angle(180);
            gate_open = false;
            log_event("Gate CLOSED", distance_mm);
            printf("Gate CLOSED (distance: %d cm)\n", distance_cm);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * VL53L1X Gate Controller for Raspberry Pi 4 Model B
 *
 * Polls a VL53L1X time-of-flight sensor on I2C bus 1 every 500 ms,
 * opens the gate (GPIO 18 HIGH, GPIO 19 LOW) when an object is
 * within 20 cm, and closes it otherwise.  Logs open/close events
 * with timestamps to gate_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 * Run:    sudo ./gate_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* 7-bit I2C address */
#define GATE_OPEN_PIN        18            /* GPIO 18 – gate open  */
#define GATE_CLOSE_PIN       19            /* GPIO 19 – gate close */
#define DISTANCE_THRESHOLD   200           /* 20 cm in mm */
#define POLL_INTERVAL_US     500000        /* 500 ms */
#define LOG_FILE             "gate_events.log"

/* VL53L1X 16-bit register addresses (pigpio i2cWriteI2CBlockData uses
 * a 32-bit command byte: (reg_addr << 8) | (reg_addr >> 8).  The
 * sensor expects the 16-bit register address in big-endian order, so
 * we send (reg_addr << 8) | (reg_addr >> 8). */
#define VL53L1X_REG_SOFT_RESET                0x000B
#define VL53L1X_REG_SYSTEM_MODE_START         0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L1X_REG_RESULT_DISTANCE           0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR    0x0086
#define VL53L1X_REG_SYSTEM_THRESH_HIGH       0x008E
#define VL53L1X_REG_SYSTEM_THRESH_LOW        0x008F
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG   0x0081
#define VL53L1X_REG_SD_CONFIG_WOI_SD0         0x0080
#define VL53L1X_REG_PHASECAL_CONFIG_TIMEOUT   0x004E
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT      0x005E
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD   0x006B
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT  0x006C

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void control_gate(uint16_t distance_mm);
static void log_event(const char *event);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- VL53L1X helpers --------------------------- */
/*
 * Write a single byte to a 16-bit register address.
 * pigpio i2cWriteI2CBlockData sends: [reg_hi, reg_lo, value]
 * The sensor expects the 16-bit address in big-endian order.
 */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

/*
 * Read a block of bytes from a 16-bit register address.
 * pigpio i2cReadI2CBlockData sends: [reg_hi, reg_lo, 0, 0, ...]
 * The sensor returns: [reg_hi, reg_lo, data...]
 */
static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    if (i2cWriteI2CBlockData(handle, cmd[0], &cmd[1], 1) < 0)
        return -1;
    return i2cReadI2CBlockData(handle, cmd[0], (char *)buf, len);
}

/*
 * Initialize the VL53L1X: soft reset, configure timing budget,
 * and start continuous ranging.
 */
static int vl53l1x_init(int handle)
{
    uint8_t status;

    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: soft reset release failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: interrupt clear failed\n");
        return -1;
    }

    /* Set timing budget to ~20 ms (0x0014) */
    if (vl53l1x_write16(handle, VL53L1X_REG_RANGE_CONFIG_TIMEOUT, 0x0014) < 0) {
        fprintf(stderr, "Error: range config timeout failed\n");
        return -1;
    }

    /* Set inter-measurement period to 0 (continuous) */
    if (vl53l1x_write16(handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x0000) < 0) {
        fprintf(stderr, "Error: inter-measurement period failed\n");
        return -1;
    }

    /* Start continuous ranging */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: system mode start failed\n");
        return -1;
    }

    /* Wait for first measurement to be ready */
    gpioDelay(100000); /* 100 ms */

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 10; i++) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: range status read failed\n");
            return -1;
        }
        if (status & 0x01)
            return 0;
        gpioDelay(10000); /* 10 ms */
    }

    fprintf(stderr, "Error: VL53L1X not ready after init\n");
    return -1;
}

/*
 * Read the 16-bit distance value.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t buf[2];

    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) < 0) {
        fprintf(stderr, "Error: distance read failed\n");
        return -1;
    }

    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- Gate control ------------------------------ */
static void control_gate(uint16_t distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
        log_event("Gate Opened");
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
        log_event("Gate Closed");
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s - %s\n", timestamp, event);
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure gate is closed */
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
