/*
 * VL53L1X Gate Controller for Raspberry Pi 4 Model B
 *
 * Polls a VL53L1X time-of-flight sensor on I2C bus 1 every 500 ms,
 * opens the gate (GPIO 18 HIGH, GPIO 19 LOW) when an object is
 * within 20 cm, and closes it otherwise.  Logs open/close events
 * with timestamps to gate_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 * Run:    sudo ./gate_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* 7-bit I2C address */
#define GATE_OPEN_PIN        18            /* GPIO 18 – gate open  */
#define GATE_CLOSE_PIN       19            /* GPIO 19 – gate close */
#define DISTANCE_THRESHOLD   200           /* 20 cm in mm */
#define POLL_INTERVAL_US     500000        /* 500 ms */
#define LOG_FILE             "gate_events.log"

/* VL53L1X 16-bit register addresses (pigpio i2cWriteI2CBlockData uses
 * a 32-bit command byte: (reg_addr << 8) | (reg_addr >> 8).  The
 * sensor expects the 16-bit register address in big-endian order, so
 * we send (reg_addr << 8) | (reg_addr >> 8). */
#define VL53L1X_REG_SOFT_RESET                0x000B
#define VL53L1X_REG_SYSTEM_MODE_START         0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS       0x0014
#define VL53L1X_REG_RESULT_DISTANCE           0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR    0x0086
#define VL53L1X_REG_SYSTEM_THRESH_HIGH       0x008E
#define VL53L1X_REG_SYSTEM_THRESH_LOW        0x008F
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG   0x0081
#define VL53L1X_REG_SD_CONFIG_WOI_SD0         0x0080
#define VL53L1X_REG_PHASECAL_CONFIG_TIMEOUT   0x004E
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT      0x005E
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD   0x006B
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT  0x006C

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void control_gate(uint16_t distance_mm);
static void log_event(const char *event);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- VL53L1X helpers --------------------------- */
/*
 * Write a single byte to a 16-bit register address.
 * pigpio i2cWriteI2CBlockData sends: [reg_hi, reg_lo, value]
 * The sensor expects the 16-bit address in big-endian order.
 */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

/*
 * Read a block of bytes from a 16-bit register address.
 * pigpio i2cReadI2CBlockData sends: [reg_hi, reg_lo, 0, 0, ...]
 * The sensor returns: [reg_hi, reg_lo, data...]
 */
static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    if (i2cWriteI2CBlockData(handle, cmd[0], &cmd[1], 1) < 0)
        return -1;
    return i2cReadI2CBlockData(handle, cmd[0], (char *)buf, len);
}

/*
 * Initialize the VL53L1X: soft reset, configure timing budget,
 * and start continuous ranging.
 */
static int vl53l1x_init(int handle)
{
    uint8_t status;

    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: soft reset release failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: interrupt clear failed\n");
        return -1;
    }

    /* Set timing budget to ~20 ms (0x0014) */
    if (vl53l1x_write16(handle, VL53L1X_REG_RANGE_CONFIG_TIMEOUT, 0x0014) < 0) {
        fprintf(stderr, "Error: range config timeout failed\n");
        return -1;
    }

    /* Set inter-measurement period to 0 (continuous) */
    if (vl53l1x_write16(handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x0000) < 0) {
        fprintf(stderr, "Error: inter-measurement period failed\n");
        return -1;
    }

    /* Start continuous ranging */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: system mode start failed\n");
        return -1;
    }

    /* Wait for first measurement to be ready */
    gpioDelay(100000); /* 100 ms */

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 10; i++) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error: range status read failed\n");
            return -1;
        }
        if (status & 0x01)
            return 0;
        gpioDelay(10000); /* 10 ms */
    }

    fprintf(stderr, "Error: VL53L1X not ready after init\n");
    return -1;
}

/*
 * Read the 16-bit distance value.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t buf[2];

    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) < 0) {
        fprintf(stderr, "Error: distance read failed\n");
        return -1;
    }

    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- Gate control ------------------------------ */
static void control_gate(uint16_t distance_mm)
{
    if (distance_mm < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
        log_event("Gate Opened");
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
        log_event("Gate Closed");
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s - %s\n", timestamp, event);
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure gate is closed */
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    gpioTerminate();

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    uint16_t distance_mm;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    /* Main loop */
    while (running) {
        if (vl53l1x_read_distance(i2c_handle, &distance_mm) == 0) {
            control_gate(distance_mm);
        } else {
            /* On read error, attempt to restart ranging */
            vl53l1x_write16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
            gpioDelay(10000);
            vl53l1x_write16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
            log_event("Sensor read error, ranging restarted");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

