static void log_message(const char *msg);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 3)
            return 0;
        gpioDelay(1000 << attempt);   /* 1 ms, 2 ms, 4 ms, 8 ms */
    }
    return -1;
}

static int i2c_read_reg(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, addr, 2) != 2) {
            gpioDelay(1000 << attempt);
            continue;
        }
        if (i2cReadDevice(handle, (char *)buf, len) == (int)len)
            return 0;
        gpioDelay(1000 << attempt);
    }
    return -1;
}

/* ----------------------------- VL53L1X driver ----------------------------- */
static int vl53l1x_init(int handle)
{
    /* Soft reset: write 0x00 to register 0x0003 */
    if (i2c_write_reg(handle, 0x0003, 0x00) < 0) {
        log_message("VL53L1X: soft-reset write failed");
        return -1;
    }
    gpioDelay(1000);   /* 1 ms settle */

    /* Start ranging: write 0x01 to register 0x0000 */
    if (i2c_write_reg(handle, 0x0000, 0x01) < 0) {
        log_message("VL53L1X: start-ranging write failed");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};

    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 5) {
        if (i2c_read_reg(handle, 0x0014, &status, 1) < 0) {
            log_message("VL53L1X: status read failed");
            return -1;
        }
        if (status & 0x01)
            break;
        gpioDelay(5000);   /* 5 ms */
    }

    if (!(status & 0x01)) {
        log_message("VL53L1X: measurement timeout");
        return -1;
    }

    if (i2c_read_reg(handle, 0x0014, data, 2) < 0) {
        log_message("VL53L1X: distance read failed");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ----------------------------- Motor control ----------------------------- */
static void motor_forward(void)
{
    if (g_motor_state != 1) {
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        g_motor_state = 1;
        log_message("Motor: FORWARD");
    }
}

static void motor_backward(void)
{
    if (g_motor_state != 2) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 1);
        g_motor_state = 2;
        log_message("Motor: BACKWARD");
    }
}

static void motor_stop(void)
{
    if (g_motor_state != 0) {
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_BACKWARD_PIN, 0);
        g_motor_state = 0;
        log_message("Motor: STOP");
    }
}

/* ----------------------------- ISR & signal ------------------------------ */
static void trigger_callback(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;

    uint16_t distance = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Distance: %u mm", distance);
        log_message(msg);

        if (distance < DISTANCE_THRESHOLD_FORWARD)
            motor_forward();
        else if (distance > DISTANCE_THRESHOLD_BACKWARD)
            motor_backward();
        else
            motor_stop();
    } else {
        log_message("VL53L1X: read failed, stopping motor");
        motor_stop();
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);

    /* Configure trigger pin */
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", TRIGGER_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started. Press Ctrl+C to exit.");

    /* Main loop */
    while (g_running)
        gpioDelay(100000);   /* 100 ms */

    /* Cleanup */
    log_message("Shutting down...");
    gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);
    motor_stop();
    i2cClose(g_i2c_handle);
    gpioTerminate();
    log_message("Program terminated.");
    return EXIT_SUCCESS;
}

