/*
 * Proximity-based interactive art installation for Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 *   - 4x 330 ohm resistors to LED anodes (GPIO17, GPIO18, GPIO27, GPIO22)
 *   - LED cathodes to GND
 *
 * Behaviour:
 *   Polls the MPR121 every 50 ms; when any electrode is touched, lights
 *   the corresponding LED and logs the event with a timestamp.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o art_installation art_installation.c -lpigpio -lrt
 *   (run as root, or ensure /dev/i2c-1 is accessible)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x5C          /* A0=GND, A1=GND, A2=GND */

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET       0x80

#define NUM_ELECTRODES 12
#define NUM_LEDS       4

static const int led_pins[NUM_LEDS] = {17, 18, 27, 22};

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg(int fd, uint8_t reg, uint8_t *val);
static int  mpr121_init(int fd);
static int  mpr121_read_touch_status(int fd, uint16_t *status);
static void log_event(const char *msg);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 driver ----------------------------- */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* AFE config: FFI=00 (6 samples), CDC=16 µA, ESI=1 ms */
    if (i2c_write_reg(fd, 0x2B, 0x01) < 0)
        return -1;
    /* Control register: 12 electrodes, baseline tracking enabled */
    if (i2c_write_reg(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0)
        return -1;
    gpioDelay(2000);

    /* Verify configuration by reading back */
    uint8_t cfg;
    if (i2c_read_reg(fd, MPR121_ELECTRODE_CONFIG, &cfg) < 0)
        return -1;
    if (cfg != 0x0C) {
        fprintf(stderr, "MPR121 config verification failed (got 0x%02X)\n", cfg);
        return -1;
    }

    return 0;
}

static int mpr121_read_touch_status(int fd, uint16_t *status)
{
    uint8_t lo, hi;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_fp);
    }
}

/* ----------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    /* Turn off all LEDs */
    for (int i = 0; i < NUM_LEDS; i++)
        gpioWrite(led_pins[i], 0);

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen("art_installation.log", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence --- */
    uint8_t dummy;
    if (i2c_read_reg(g_i2c_fd, MPR121_TOUCHSTATUS_L, &dummy) < 0) {
        fprintf(stderr, "MPR121 not responding at 0x%02X\n", MPR121_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("MPR121 initialized successfully");

    /* --- Configure LED pins --- */
    for (int i = 0; i < NUM_LEDS; i++) {
        if (gpioSetMode(led_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", led_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(led_pins[i], 0);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Art installation started");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(g_i2c_fd, &touch_status) < 0) {
            log_event("Error reading touch status");
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        uint8_t led_pattern = 0;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1u << i)) {
                led_pattern |= (1u << i);
                gpioWrite(led_pins[i], 1);
            } else {
                gpioWrite(led_pins[i], 0);
            }
        }

        if (led_pattern != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Proximity detected (pattern=0x%04X)", led_pattern);
            log_event(msg);
        }

        gpioDelay(50000); /* 50 ms poll interval */
    }

    log_event("Art installation stopped");
    cleanup();
    return EXIT_SUCCESS;
}

