#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define MPR121_ADDR     0x5C
#define LED_GPIO        27
#define LOG_FILE        "proximity.log"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_MHD_F          0x2F
#define MPR121_NHD_F          0x30
#define MPR121_NCL_F          0x31
#define MPR121_FDL_F          0x32
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_ECR            0x5E
#define MPR121_AUTO_CONFIG0   0x7B
#define MPR121_AUTO_CONFIG1   0x7C
#define MPR121_USL            0x7D
#define MPR121_LSL            0x7E
#define MPR121_TL             0x7F
#define MPR121_E0FDL          0x80
#define MPR121_E0FCL          0x81
#define MPR121_E0RDL          0x82
#define MPR121_E0RCL          0x83
#define MPR121_SOFTRESET      0x80
#define MPR121_ELE_CONFIG     0x5E

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms */

    if (i2c_write_reg(fd, MPR121_ECR, 0x00) < 0) return -1;

    /* Baseline filtering */
    if (i2c_write_reg(fd, MPR121_MHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCL_R, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDL_R, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_MHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_NCL_F, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_FDL_F, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(fd, MPR121_E0TTH + 2 * i, 0x0C) < 0) return -1;
        if (i2c_write_reg(fd, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (i2c_write_reg(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, ESI=1 ms */
    if (i2c_write_reg(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (i2c_write_reg(fd, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(int fd, uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Proximity detected\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to MPR121");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    /* Verify device presence by reading the touch status register */
    uint8_t dummy;
    if (i2c_read_reg(i2c_fd, MPR121_TOUCHSTATUS_L, &dummy) < 0) {
        fprintf(stderr, "MPR121 not detected at address 0x%02X\n", MPR121_ADDR);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Proximity detector running. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        if (touch_status > 0) {
            printf("Proximity detected!\n");
            gpioWrite(LED_GPIO, 1);
            log_proximity_event();
            gpioDelay(1000000); /* 1 second */
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(10000); /* 10 ms polling interval */
    }

    /* Cleanup */
    gpioWrite(LED_GPIO, 0);
    if (i2c_fd >= 0) {
        i2c_write_reg(i2c_fd, MPR121_ECR, 0x00);
        close(i2c_fd);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

