#define SPEED_OF_SOUND   343.0          /* m/s at 20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define TIMEOUT_US       30000          /* 30 ms echo timeout */
#define TRIGGER_PULSE_US 10
#define SETTLE_US        5000           /* 5 ms settle after trigger */
#define SAMPLE_PERIOD_S  1.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on gpio read error.
 */
static long measure_echo_us(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge (timeout) */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* echo never rose */
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;                 /* echo stuck high */
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Convert pulse width (µs) to distance (cm).
 * Returns true on a valid reading within range.
 */
static bool calculate_distance(long pulse_us, double *distance_cm)
{
    double distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM)
        return false;

    *distance_cm = distance;
    return true;
}

/*
 * Generate an ISO-8601 UTC timestamp string.
 */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;

    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(SETTLE_US);

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Log: distance_log.txt\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /* 10 µs trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Warning: failed to set trigger high.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Warning: failed to set trigger low.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        long pulse_us = measure_echo_us();

        if (pulse_us < 0) {
            get_timestamp(timestamp, sizeof(timestamp));
            fprintf(g_log_file, "%s, Error: echo timeout (sensor absent or wiring fault)\n",
                    timestamp);
            fflush(g_log_file);
            fprintf(stderr, "Error: echo timeout (sensor absent or wiring fault)\n");
        } else {
            double distance;
            if (calculate_distance(pulse_us, &distance)) {
                get_timestamp(timestamp, sizeof(timestamp));
                fprintf(g_log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
                fflush(g_log_file);
                printf("%s, Distance: %.2f cm\n", timestamp, distance);
            } else {
                get_timestamp(timestamp, sizeof(timestamp));
                fprintf(g_log_file, "%s, Error: out of range (pulse %ld µs)\n",
                        timestamp, pulse_us);
                fflush(g_log_file);
                fprintf(stderr, "Error: out of range (pulse %ld µs)\n", pulse_us);
            }
        }

        /* Sleep for the remainder of the sample period (interruptible) */
        for (double s = 0.0; s < SAMPLE_PERIOD_S && g_running; s += 0.01)
            sleep(0.01);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

