/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi Zero W
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN        17
#define ECHO_PIN        18

#define TRIG_PULSE_US   10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US 30000       /* 30 ms max echo wait (~4 m)     */
#define MIN_PULSE_US    58          /* ~58 µs round trip ~1 cm        */
#define MAX_PULSE_US    25000       /* ~25 ms round trip ~4 m         */
#define SAMPLE_PERIOD_S 1           /* 1 Hz sampling                  */
#define LOG_FILE        "distance_log.txt"

/* Shared state between ISR and main thread */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile bool     g_echo_done = false;
static volatile bool     g_running   = true;
static FILE             *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* ISR callback (runs in pigpio thread)                                 */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rise_tick = tick;
        g_echo_done = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_fall_tick = tick;
        g_echo_done = true;
    }
    /* level == 2 indicates a watchdog timeout — ignore */
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 µs pulse on TRIG_PIN                                   */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute pulse width (µs) with wrap-around handling                  */
/* ------------------------------------------------------------------ */
static uint32_t pulse_width_us(uint32_t rise, uint32_t fall)
{
    return fall - rise;  /* pigpio ticks are uint32_t; subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (µs) to distance (m)                            */
/* speed_of_sound ≈ 343 m/s  =>  distance = pulse_us * 343 / 2 / 1e6    */
/* ------------------------------------------------------------------ */
static float calculate_distance(uint32_t pulse_us)
{
    return (float)pulse_us * 343.0f / 2.0f / 1000000.0f;
}

/* ------------------------------------------------------------------ */
/* Append a reading to the log file                                    */
/* ------------------------------------------------------------------ */
static void log_reading(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, Distance: %.2f m\n", timestamp, distance);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR before tearing down */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50 * 1000);  /* 50 ms settle */

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Register ISR on ECHO pin ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, ECHO_TIMEOUT_US,
                         echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d  ECHO=GPIO%d  Log=%s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state for this sample */
        g_echo_done = false;
        g_rise_tick = 0;
        g_fall_tick = 0;

        trigger_sensor();

        /* Wait for echo with timeout (poll every 10 ms) */
        uint32_t waited = 0;
        while (!g_echo_done && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(10 * 1000);  /* 10 ms */
            waited += 10 * 1000;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_done) {
            fprintf(stderr, "Warning: echo timeout (no object detected or sensor absent).\n");
            continue;
        }

        uint32_t pulse_us = pulse_width_us(g_rise_tick, g_fall_tick);

        if (pulse_us == 0 || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: implausible pulse width %u µs (out of range).\n", pulse_us);
            continue;
        }

        float distance = calculate_distance(pulse_us);
        log_reading(distance);
        printf("Distance: %.2f m  (pulse %u µs)\n", distance, pulse_us);

        /* Sleep for the remainder of the 1-second period */
        if (SAMPLE_PERIOD_S > 0) {
            gpioDelay((SAMPLE_PERIOD_S - 1) * 1000000);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

