#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>
#include <stdbool.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define XSHUT_PIN      27
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET       0x0003
#define VL53L1X_REG_SYSTEM_START     0x0008
#define VL53L1X_REG_RESULT_STATUS    0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by 1 byte of data. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit register address and return the 8-bit value. */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    char data[1];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;
    *value = (uint8_t)data[0];
    return 0;
}

/* Read a 16-bit register address and return the 16-bit value (big-endian). */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Read and verify model ID to confirm sensor is present. */
    if (vl53l1x_read_reg8(handle, 0x010F, &model_id) < 0) {
        syslog(LOG_ERR, "Failed to read VL53L1X model ID: %s", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        syslog(LOG_ERR, "VL53L1X model ID mismatch: 0x%02X (expected 0xEA)", model_id);
        return -1;
    }

    /* Soft reset: write 0x00 to SOFT_RESET, wait 2 ms, write 0x01 to start. */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to soft reset: %s", strerror(errno));
        return -1;
    }
    gpioDelay(2000); /* 2 ms */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to release soft reset: %s", strerror(errno));
        return -1;
    }
    gpioDelay(2000); /* 2 ms for device to boot */

    /* Start ranging (bit 0 = 1). */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start ranging: %s", strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X initialized successfully (model ID 0x%02X)", model_id);
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t dist = 0;

    /* Check if data is ready (bit 0 of RESULT_STATUS). */
    if (vl53l1x_read_reg8(handle, VL53L1X_REG_RESULT_STATUS, &status) < 0) {
