/* Write a 16-bit register address followed by 1 byte of data. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit register address and return the 8-bit value. */
static int vl53l1x_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    char data[1];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;
    *value = (uint8_t)data[0];
    return 0;
}

/* Read a 16-bit register address and return the 16-bit value (big-endian). */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
