#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int vl53l1x_write16(uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 4);
}

static int vl53l1x_read16(uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(data[0] & 0xFF) << 8) | (uint16_t)(data[1] & 0xFF);
    return 0;
}

static int vl53l1x_init(void) {
    if (vl53l1x_write16(VL53L1X_REG_SYSTEM_START, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(VL53L1X_REG_SYSTEM_START, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance_cm(float *distance_cm) {
    uint16_t status = 0;
    if (vl53l1x_read16(VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 1;
    uint16_t raw = 0;
    if (vl53l1x_read16(VL53L1X_REG_RESULT_DISTANCE, &raw) < 0) return -1;
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void control_gate(float distance_cm) {
    static int gate_open = 0;
    if (distance_cm < DISTANCE_THRESHOLD_CM && !gate_open) {
        if (gpioWrite(GATE_GPIO, 1) == 0) {
            gate_open = 1;
            log_event("Gate opened");
        } else {
            log_event("Error: Failed to set GPIO24 high");
        }
    } else if (distance_cm >= DISTANCE_THRESHOLD_CM && gate_open) {
        if (gpioWrite(GATE_GPIO, 0) == 0) {
            gate_open = 0;
            log_event("Gate closed");
        } else {
            log_event("Error: Failed to set GPIO24 low");
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO24 as output\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (program_running) {
        float distance_cm = 0.0f;
        int rc = read_distance_cm(&distance_cm);
        if (rc == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance_cm);
            log_event(msg);
            control_gate(distance_cm);
        } else if (rc < 0) {
            log_event("Error: I2C read failed");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

