#define ECHO_PIN         24
#define SERVO_PIN        18

#define SPEED_OF_SOUND   34300.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define SAMPLE_INTERVAL_US 100000
#define MOVING_AVG_SIZE 5
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end = 0;
static volatile bool new_pulse = false;
static volatile bool echo_active = false;

static FILE *log_file = NULL;
static double distance_history[MOVING_AVG_SIZE];
static int history_index = 0;
static int history_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_start = tick;
        echo_active = true;
    } else if (level == 0 && echo_active) {
        pulse_end = tick;
        new_pulse = true;
        echo_active = false;
    }
}

static double measure_distance(void) {
    new_pulse = false;
    echo_active = false;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = gpioTick();
    while (!new_pulse && running) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
        gpioDelay(100);
    }

    uint32_t pulse_duration = pulse_end - pulse_start;
    if (pulse_duration == 0 || pulse_duration > ECHO_TIMEOUT_US) {
        return -1.0;
    }

    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance;
}

static double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;
    if (history_count < MOVING_AVG_SIZE) {
        history_count++;
    }

    double sum = 0.0;
    for (int i = 0; i < history_count; i++) {
