/*
 * VL53L1X time-of-flight distance sensor reader for Raspberry Pi 4 Model B.
 *
 * I2C bus 1, address 0x29.  Reads distance every 50 ms, stores last 10 values
 * in a circular buffer, lights GPIO17 (BCM) high when a reading is < 200 mm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_demo vl53l1x_demo.c
 *
 * Requires libgpiod (libgpiod-dev) and pigpio (pigpio-dev).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <gpiod.h>

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define GPIO_LED             17
#define BUFFER_SIZE          10
#define DISTANCE_THRESHOLD   200   /* mm */
#define POLL_DELAY_US        50000 /* 50 ms */

/* ---- VL53L1X register addresses (16-bit, big-endian on the bus) ---- */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDR   0x0001
#define VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x000B
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_A 0x005E
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_B 0x0061
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x006B
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0046
#define VL53L1X_REG_SYSTEM_THRESHOLD_CONFIG_HIGH 0x004C
#define VL53L1X_REG_SYSTEM_THRESHOLD_CONFIG_LOW  0x004E
#define VL53L1X_REG_SYSTEM_MODE_START          0x0087
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS    0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS        0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Circular buffer ---- */
typedef struct {
    int  data[BUFFER_SIZE];
    int  head;
    int  count;
} CircularBuffer;

static CircularBuffer buffer;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "VL53L1X soft reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); /* 1 ms */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "VL53L1X soft reset release failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Set I2C address (already 0x29 on power-up, but configure anyway) */
    if (i2c_write_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDR, 0x29) < 0) {
        fprintf(stderr, "VL53L1X set I2C address failed: %s\n", strerror(errno));
        return -1;
    }

    /* Mandatory init registers (STM application note / datasheet) */
    if (i2c_write_reg16(handle, VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND, 0x09) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_A, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_B, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESHOLD_CONFIG_HIGH, 0x00) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESHOLD_CONFIG_LOW, 0x00) < 0) return -1;

    /* Start ranging (bit 0 = 1) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "VL53L1X start ranging failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2];

    /* Poll interrupt status until new data ready (bit 0) */
    for (int i = 0; i < 50; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X timeout waiting for data ready\n");
        return -1;
    }

    /* Read 2-byte distance */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0)
        return -1;

    *distance_mm = (data[0] << 8) | data[1];
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(CircularBuffer *buf)
{
    buf->head = 0;
    buf->count = 0;
    memset(buf->data, 0, sizeof(buf->data));
}

static void buffer_add(CircularBuffer *buf, int value)
{
    buf->data[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29 */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and get LED line */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "vl53l1x_demo", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    buffer_init(&buffer);

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
        } else {
            buffer_add(&buffer, distance);
            printf("Distance: %d mm\n", distance);

            /* LED control */
            if (distance < DISTANCE_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

