/*
 * Si1102 Proximity Sensor Logger for Raspberry Pi Zero W
 *
 * Reads the 16-bit proximity value from the Si1102 on I2C bus 1,
 * compares it to a threshold, and logs the result to proximity.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1102_logger si1102_logger.c
 * Run:    ./si1102_logger [-t threshold] [-a i2c_address]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS         "/dev/i2c-1"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       27
#define LOG_FILE        "proximity.log"
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_I2C_ADDR 0x60

/* Si1102 register addresses (from datasheet) */
#define SI1102_REG_PART_ID      0x00
#define SI1102_REG_REV_ID       0x01
#define SI1102_REG_SEQ_ID       0x02
#define SI1102_REG_INT_CFG      0x03
#define SI1102_REG_IRQ_ENABLE   0x04
#define SI1102_REG_IRQ_MODE1    0x05
#define SI1102_REG_IRQ_MODE2    0x06
#define SI1102_REG_HW_KEY       0x07
#define SI1102_REG_MEAS_RATE0   0x08
#define SI1102_REG_MEAS_RATE1   0x09
#define SI1102_REG_PS_LED21     0x0F
#define SI1102_REG_PS_LED3      0x10
#define SI1102_REG_PS1_DATA0    0x18
#define SI1102_REG_PS1_DATA1    0x19
#define SI1102_REG_COMMAND      0x18

#define SI1102_CMD_RESET        0x01
#define SI1102_CMD_PS_FORCE     0x05
#define SI1102_CMD_PS_AUTO      0x0D

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static int g_threshold = DEFAULT_THRESHOLD;
static int g_i2c_address = DEFAULT_I2C_ADDR;

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1102 driver                                                       */
/* ------------------------------------------------------------------ */

static int si1102_init(int fd)
{
    uint8_t part_id;

    if (i2c_read_reg8(fd, SI1102_REG_PART_ID, &part_id) < 0)
        return -1;

    if (part_id != 0x02) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    /* Reset the device */
    if (i2c_write_reg8(fd, SI1102_REG_COMMAND, SI1102_CMD_RESET) < 0)
        return -1;
    usleep(10000); /* 10 ms reset settling */

    /* Write HW_KEY to enable proper operation */
    if (i2c_write_reg8(fd, SI1102_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Configure LED current for PS1 (LED21 = 0x0F, LED3 = 0x0F) */
    if (i2c_write_reg8(fd, SI1102_REG_PS_LED21, 0x0F) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1102_REG_PS_LED3, 0x0F) < 0)
        return -1;

    /* Set measurement rate to 0 (manual / forced mode) */
    if (i2c_write_reg8(fd, SI1102_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1102_REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg8(fd, SI1102_REG_IRQ_MODE1, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1102_REG_IRQ_MODE2, 0x00) < 0)
        return -1;

    /* Enable PS1 interrupt on any change */
    if (i2c_write_reg8(fd, SI1102_REG_INT_CFG, 0x01) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1102_REG_IRQ_ENABLE, 0x01) < 0)
        return -1;

    return 0;
}

static int si1102_read_proximity(int fd, uint16_t *prox)
{
    /* Trigger a forced PS measurement */
    if (i2c_write_reg8(fd, SI1102_REG_COMMAND, SI1102_CMD_PS_FORCE) < 0)
        return -1;

    /* Allow time for the conversion to complete */
    usleep(20000); /* 20 ms */

    if (i2c_read_reg16(fd, SI1102_REG_PS1_DATA0, prox) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_proximity(uint16_t proximity, int threshold, const char *status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, %u, %s\n", timestamp, proximity, status);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Interrupt handler (thread-safe via queue)                           */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_interrupt_flag = 0;
static pthread_mutex_t g_interrupt_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_interrupt_cond = PTHREAD_COND_INITIALIZER;

static void interrupt_handler(int sig)
{
    (void)sig;
    pthread_mutex_lock(&g_interrupt_mutex);
    g_interrupt_flag = 1;
    pthread_cond_signal(&g_interrupt_cond);
    pthread_mutex_unlock(&g_interrupt_mutex);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int opt;
    struct sigaction sa;

    while ((opt = getopt(argc, argv, "t:a:h")) != -1) {
        switch (opt) {
        case 't':
            g_threshold = atoi(optarg);
            if (g_threshold <= 0) {
                fprintf(stderr, "Threshold must be a positive integer.\n");
                return EXIT_FAILURE;
            }
            break;
        case 'a':
            g_i2c_address = (int)strtol(optarg, NULL, 0);
            if (g_i2c_address < 0x03 || g_i2c_address > 0x77) {
                fprintf(stderr, "Invalid I2C address: 0x%02X\n", g_i2c_address);
                return EXIT_FAILURE;
            }
            break;
        case 'h':
        default:
            fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, g_i2c_address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                g_i2c_address, strerror(errno));
        close(g_i2c_fd);
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    /* Initialize Si1102 sensor */
    if (si1102_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1102 initialization failed.\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    /* Setup signal handler for Ctrl+C */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = interrupt_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        close(g_i2c_fd);
        fclose(g_log_fp);
        return EXIT_FAILURE;
    }

    printf("Si1102 proximity sensor logging started.\n");
    printf("  I2C bus: %s, address: 0x%02X, threshold: %d\n",
           I2C_BUS, g_i2c_address, g_threshold);
    printf("  Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        pthread_mutex_lock(&g_interrupt_mutex);
        while (!g_interrupt_flag && g_running) {
            pthread_cond_wait(&g_interrupt_cond, &g_interrupt_mutex);
        }
        g_interrupt_flag = 0;
        pthread_mutex_unlock(&g_interrupt_mutex);

        if (!g_running)
            break;

        uint16_t proximity;
        if (si1102_read_proximity(g_i2c_fd, &proximity) < 0) {
            fprintf(stderr, "Error reading proximity value.\n");
            continue;
        }

        const char *status = (proximity <= g_threshold) ? "SAFE" : "ALERT";
        log_proximity(proximity, g_threshold, status);
        printf("Proximity: %u, Status: %s\n", proximity, status);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    close(g_i2c_fd);
    g_i2c_fd = -1;
    fclose(g_log_fp);
    g_log_fp = NULL;

    return EXIT_SUCCESS;
}

