/*
 * Theremin-style distance-to-frequency converter using an HC-SR04 ultrasonic
 * sensor and a hardware-timed PWM on the Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   Speaker +    -> GPIO18 (BCM, hardware PWM0)
 *   Speaker -    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define LOOP_DELAY_US    100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm on success, or -1.0 on timeout / error.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    uint32_t start_tick = gpioTick();
    uint32_t timeout_tick = start_tick + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }

    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }

    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance = (float)pulse_us * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/*
 * Map distance to frequency on a logarithmic scale.
 * Returns 0 on success, -1 if distance is invalid.
 */
static int map_distance_to_frequency(float distance, int *out_freq)
{
    if (distance < 0.0f) {
        return -1;
    }

    if (distance < MIN_DISTANCE_CM) {
        distance = MIN_DISTANCE_CM;
    } else if (distance > MAX_DISTANCE_CM) {
        distance = MAX_DISTANCE_CM;
    }

    float normalized = (distance - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    float freq = MIN_FREQUENCY_HZ +
                 (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) *
                 (1.0f - powf(normalized, 2.0f));

    if (freq < MIN_FREQUENCY_HZ || freq > MAX_FREQUENCY_HZ) {
        fprintf(stderr, "Error: frequency %.2f Hz out of range [%.0f, %.0f]\n",
                freq, MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
        return -1;
    }

    *out_freq = (int)freq;
    return 0;
}

/*
 * Set PWM frequency and 50% duty cycle.
 * Returns 0 on success, -1 on error.
 */
static int set_pwm_frequency(int frequency)
{
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return -1;
    }

    if (gpioPWM(PWM_PIN, 128) < 0) {  /* 50% duty cycle (0-255 scale) */
        fprintf(stderr, "Error: gpioPWM(%d, 128) failed\n", PWM_PIN);
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    int previous_frequency = 0;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: measurement failed, preserving frequency\n");
        } else {
            int frequency = 0;
            if (map_distance_to_frequency(distance, &frequency) == 0) {
                if (frequency != previous_frequency) {
                    if (set_pwm_frequency(frequency) == 0) {
                        previous_frequency = frequency;
                        printf("Distance: %.2f cm -> Frequency: %d Hz\n",
                               distance, frequency);
                    } else {
                        fprintf(stderr, "Error: failed to set PWM frequency\n");
                    }
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);   /* Stop PWM */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

