#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE  5.0
#define MAX_DISTANCE  50.0

#define TIMEOUT_US    100000
#define TRIGGER_US    10
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low for a clean pulse */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo start\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo end\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double pulse_width_us = (double)(end_tick - start_tick);
    return pulse_width_us * 0.0343 / 2.0;
}

static double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return MIN_FREQUENCY +
           (distance - MIN_DISTANCE) *
           (MAX_FREQUENCY - MIN_FREQUENCY) /
           (MAX_DISTANCE - MIN_DISTANCE);
}

static void set_buzzer_frequency(double frequency) {
    if (frequency < 0) frequency = 0;
    if (gpioSetPWMfrequency(BUZZER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Warning: failed to set PWM frequency\n");
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Warning: failed to start PWM on buzzer\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable pull-down on echo pin */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize trigger low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    double last_valid_distance = MAX_DISTANCE;

    while (running) {
        double distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Sensor read error; using last valid distance.\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        double frequency = map_distance_to_frequency(distance);
        set_buzzer_frequency(frequency);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

