/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 ultrasonic ToF sensor
 * SPI interface (mode 0, 1 MHz, CE0 = GPIO8).
 *
 * Reads distance (200–5000 mm) every 100 ms and appends
 * timestamp,distance_mm to distance_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_log icu20201_log.c -lpigpio -lrt
 * Run:    sudo ./icu20201_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (GPIO8)                              */
#define SPI_SPEED      1000000    /* 1 MHz                                    */
#define SPI_FLAGS      0          /* mode 0, active-low CE                    */
#define SAMPLE_US      100000     /* 100 ms between readings                  */
#define LOG_FILE       "distance_log.csv"
#define MAX_RETRIES    3

/* ICU-20201 SPI command opcodes (vendor-specific) */
#define CMD_READ_DIST  0x01
#define CMD_READ_TOF   0x02
#define CMD_READ_ID    0x03

/* ----------------------------- Globals ----------------------------------- */
static int      spi_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_read_distance(uint16_t *distance_mm);
static int  spi_write_command(uint8_t cmd);
static int  spi_read_response(uint8_t *buf, int len);
static int  initialize_sensor(void);
static void log_data(uint16_t distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI helpers ------------------------------- */

/*
 * Write a single command byte to the ICU-20201.
 * Returns 0 on success, -1 on error.
 */
static int spi_write_command(uint8_t cmd)
{
    char tx = (char)cmd;
    char rx = 0;

    if (spiXfer(spi_handle, &tx, &rx, 1) != 1) {
        fprintf(stderr, "[SPI] write command 0x%02X failed\n", cmd);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the ICU-20201 into `buf`.
 * Returns 0 on success, -1 on error.
 */
static int spi_read_response(uint8_t *buf, int len)
{
    char tx[32] = {0};
    char rx[32] = {0};

    if (len > (int)sizeof(tx)) {
        fprintf(stderr, "[SPI] read request too large (%d)\n", len);
        return -1;
    }

    if (spiXfer(spi_handle, tx, rx, len) != len) {
        fprintf(stderr, "[SPI] read failed (requested %d bytes)\n", len);
        return -1;
    }

    memcpy(buf, rx, len);
    return 0;
}

/* ----------------------------- Sensor API -------------------------------- */

/*
 * Initialise the ICU-20201: send a software-reset command, then
 * poll its ID register until a valid response is received.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_sensor(void)
{
    uint8_t id = 0;
    int     ok = 0;

    /* Software reset */
    if (spi_write_command(0x00) != 0) {
        fprintf(stderr, "[Sensor] software reset failed\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle */

    /* Poll ID register (0x03) until sensor responds */
    for (int i = 0; i < 10; i++) {
        if (spi_write_command(CMD_READ_ID) != 0) {
            fprintf(stderr, "[Sensor] ID poll write failed (attempt %d)\n", i);
            gpioDelay(100000);
            continue;
        }
        gpioDelay(2000); /* 2 ms command settle */

        if (spi_read_response(&id, 1) != 0) {
            fprintf(stderr, "[Sensor] ID poll read failed (attempt %d)\n", i);
            gpioDelay(100000);
            continue;
        }
        /*
         * A valid ID response is typically 0x00–0x0F.
         * A zero-length response (all-0x00) typically means the
         * sensor is not present or not responding.
         */
        if (id != 0x00 && id != 0xFF) {
            ok = 1;
            break;
        }
        gpioDelay(100000);
    }

    if (!ok) {
        fprintf(stderr, "[Sensor] ICU-20201 not detected (ID=0x%02X)\n", id);
        return -1;
    }

    printf("[Sensor] ICU-20201 initialised (ID=0x%02X)\n", id);
    return 0;
}

/*
 * Read distance in millimetres.
 * Returns 0 on success and stores distance in *distance_mm,
 * -1 on SPI error.
 */
static int spi_read_distance(uint16_t *distance_mm)
{
    uint8_t rx[2] = {0};

    if (spi_write_command(CMD_READ_DIST) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms conversion time */

    if (spi_read_response(rx, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(uint16_t distance_mm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

/* ----------------------------- Signal handling --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "[pigpio] spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("[fopen] " LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "[Sensor] initialisation failed – continuing to log errors\n");
    }

    printf("[Main] logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main loop */
    while (!terminate) {
        uint16_t distance = 0;
        int      ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (spi_read_distance(&distance) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms back-off */
        }

        if (ok) {
            log_data(distance);
        } else {
            fprintf(stderr, "[Main] SPI read failed after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\n[Main] shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

