    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "[pigpio] spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("[fopen] " LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "[Sensor] initialisation failed – continuing to log errors\n");
    }

    printf("[Main] logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main loop */
    while (!terminate) {
        uint16_t distance = 0;
        int      ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (spi_read_distance(&distance) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms back-off */
        }

        if (ok) {
            log_data(distance);
        } else {
            fprintf(stderr, "[Main] SPI read failed after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\n[Main] shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

