#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1175_ADDR    0x60
#define LOG_FILE       "proximity_log.csv"
#define SAMPLE_PERIOD  5

/* Si1175 register addresses (16-bit registers, big-endian on the bus) */
#define REG_PART_ID     0x00
#define REG_ALS_VIS     0x22
#define REG_COMMAND     0x46
#define CMD_ALS_FORCE   0x0A

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit-addressed register. */
static int si1175_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit-addressed register. */
static int si1175_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write reg-addr 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a forced ALS measurement and read the visible-light value. */
static int si1175_read_als(int fd, uint16_t *als_vis)
{
    if (si1175_write_reg(fd, REG_COMMAND, CMD_ALS_FORCE) < 0)
        return -1;

    /* Allow the measurement to complete (~10 ms typical). */
    usleep(15000);

    return si1175_read_reg(fd, REG_ALS_VIS, als_vis);
}

/* Append a timestamped reading to the CSV log. */
static int log_data(FILE *fp, uint16_t als_vis)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", ts, als_vis) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus and set slave address --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Verify sensor presence via PART_ID --- */
    uint16_t part_id = 0;
    if (si1175_read_reg(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X\n", SI1175_ADDR);
        goto cleanup;
    }
    fprintf(stderr, "Si1175 detected (PART_ID=0x%04X)\n", part_id);

    /* --- Open log file (create with header) --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen %s failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,als_visible\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t als_vis = 0;
        if (si1175_read_als(fd, &als_vis) < 0) {
            fprintf(stderr, "ALS read failed; continuing\n");
        } else {
            if (log_data(fp, als_vis) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        }
        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            fprintf(stderr, "close I2C fd failed: %s\n", strerror(errno));
    }
    return rc;
}

