/*
 * Si1120 ambient light & proximity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1120 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Si1120 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Si1120 VDD  -> 3.3 V
 *   Si1120 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1120_log si1120_log.c -lpigpio -lrt
 * Run:    sudo ./si1120_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1120 constants (per datasheet) ---- */
#define SI1120_ADDR             0x60
#define SI1120_REG_PART_ID      0x00
#define SI1120_REG_REV_ID       0x01
#define SI1120_REG_SEQ_ID       0x02
#define SI1120_REG_INT_CFG      0x03
#define SI1120_REG_IRQ_ENABLE   0x04
#define SI1120_REG_IRQ_MODE1    0x05
#define SI1120_REG_IRQ_MODE2    0x06
#define SI1120_REG_HW_KEY       0x07
#define SI1120_REG_MEAS_RATE0   0x08
#define SI1120_REG_MEAS_RATE1   0x09
#define SI1120_REG_ALS_RATE     0x0A
#define SI1120_REG_ALS_IR_RATE  0x0B
#define SI1120_REG_ALS_VIS_RATE 0x0C
#define SI1120_REG_PS_RATE      0x0D
#define SI1120_REG_PS_LED21     0x0F
#define SI1120_REG_PS_LED3      0x10
#define SI1120_REG_PARAM_WR     0x17
#define SI1120_REG_COMMAND      0x18
#define SI1120_REG_RESPONSE     0x20
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_ALS_IR_DATA0  0x24
#define SI1120_REG_ALS_IR_DATA1  0x25
#define SI1120_REG_PS1_DATA0     0x26
#define SI1120_REG_PS1_DATA1     0x27
#define SI1120_REG_PS2_DATA0     0x28
#define SI1120_REG_PS2_DATA1     0x29
#define SI1120_REG_PS3_DATA0     0x2A
#define SI1120_REG_PS3_DATA1     0x2B

#define SI1120_CMD_RESET        0x01
#define SI1120_CMD_PS_FORCE     0x05
#define SI1120_CMD_ALS_FORCE    0x06
#define SI1120_CMD_PSALS_FORCE  0x07

#define SI1120_PART_ID_VAL      0x20
#define SI1120_HW_KEY_VAL       0x17

#define I2C_BUS                 1
#define SAMPLE_PERIOD_US        500000   /* 500 ms */
#define MAX_RETRIES             3
#define RETRY_DELAY_US          10000    /* 10 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register with retry.                      */
/* ------------------------------------------------------------------ */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteByteData(handle, reg, value) == 0)
            return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register with retry.                     */
/* ------------------------------------------------------------------ */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int v = i2cReadByteData(handle, reg);
        if (v >= 0) {
            *out = (uint8_t)v;
            return 0;
        }
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair with retry.              */
/* ------------------------------------------------------------------ */
static int reg_read16(int handle, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read(handle, reg_lo, &lo) != 0)
        return -1;
    if (reg_read(handle, reg_lo + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send a command and wait for the response register to clear.        */
/* ------------------------------------------------------------------ */
static int command_wait(int handle, uint8_t cmd)
{
    if (reg_write(handle, SI1120_REG_COMMAND, cmd) != 0)
        return -1;

    /* Poll RESPONSE register until it reads 0 (command completed). */
    for (int i = 0; i < 20; ++i) {
        uint8_t resp;
        if (reg_read(handle, SI1120_REG_RESPONSE, &resp) != 0)
            return -1;
        if (resp == 0)
            return 0;
        gpioDelay(1000);  /* 1 ms */
    }
    return -1;  /* timeout */
}

/* ------------------------------------------------------------------ */
static int si1120_init(int handle)
{
    uint8_t part_id;

    /* 1. Verify part ID so we know the sensor is actually present. */
    if (reg_read(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: cannot read PART_ID (sensor absent or bus error).\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_VAL) {
        fprintf(stderr, "Error: unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1120_PART_ID_VAL);
        return -1;
    }

    /* 2. Software reset. */
    if (reg_write(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Error: reset command failed.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms after reset */

    /* 3. Write HW_KEY to enable the device. */
    if (reg_write(handle, SI1120_REG_HW_KEY, SI1120_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Error: writing HW_KEY failed.\n");
        return -1;
    }

    /* 4. Configure measurement rate (~10 Hz). */
    if (reg_write(handle, SI1120_REG_MEAS_RATE0, 0x0A) != 0) {
        fprintf(stderr, "Error: writing MEAS_RATE0 failed.\n");
        return -1;
    }
    if (reg_write(handle, SI1120_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Error: writing MEAS_RATE1 failed.\n");
        return -1;
    }

    /* 5. Enable ALS_VIS and PS1 interrupts. */
    if (reg_write(handle, SI1120_REG_IRQ_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Error: writing IRQ_ENABLE failed.\n");
        return -1;
    }

    /* 6. Start autonomous measurements. */
    if (command_wait(handle, SI1120_CMD_PSALS_FORCE) != 0) {
        fprintf(stderr, "Error: starting PSALS_FORCE command failed.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, uint16_t *als_vis, uint16_t *als_ir,
                            uint16_t *prox)
{
    if (reg_read16(handle, SI1120_REG_ALS_VIS_DATA0, als_vis) != 0) {
        fprintf(stderr, "Error: reading ALS_VIS data.\n");
        return -1;
    }
    if (reg_read16(handle, SI1120_REG_ALS_IR_DATA0, als_ir) != 0) {
        fprintf(stderr, "Error: reading ALS_IR data.\n");
        return -1;
    }
    if (reg_read16(handle, SI1120_REG_PS1_DATA0, prox) != 0) {
        fprintf(stderr, "Error: reading PS1 data.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als_vis, uint16_t als_ir,
                     uint16_t prox)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s, ALS_VIS=%u, ALS_IR=%u, Proximity=%u\n",
            timestamp, als_vis, als_ir, prox);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1120 address. */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor. */
    if (si1120_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1120 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_file = fopen("si1120_log.txt", "a");
    if (g_log_file == NULL) {
