#define SI1145_PARAM_PSLED12_SELECT 0x02
#define SI1145_PARAM_PS1_ADCMUX 0x03
#define SI1145_PARAM_PS2_ADCMUX 0x04
#define SI1145_PARAM_PS3_ADCMUX 0x05
#define SI1145_PARAM_PS_ADC_GAIN 0x06
#define SI1145_PARAM_PS_ADC_COUNTER 0x07
#define SI1145_PARAM_ALS_VIS_ADC_GAIN 0x08
#define SI1145_PARAM_ALS_VIS_ADC_COUNTER 0x09
