static int write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed at register 0x%02X: %s", reg, pigpio_error(result));
        log_error(msg);
    }
    return result;
}

static int read_register(uint8_t reg) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed at register 0x%02X: %s", reg, pigpio_error(result));
        log_error(msg);
