    return -1;
}

static int initialize_si1145(void) {
    int part_id = read_register(SI1145_REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != 0x45) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Unexpected PART_ID: 0x%02X (expected 0x45)", part_id);
        log_error(msg);
        return -1;
    }

