    gpioDelay(10000);

    if (write_register(SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_register(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_register(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_register(SI1145_REG_ALS_RATE, 0x00) < 0) return -1;
    if (write_register(SI1145_REG_PS_LED21, 0x0F) < 0) return -1;
    if (write_register(SI1145_REG_PS_LED3, 0x00) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_CHLIST) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_CHLIST_EN_PS1 |
                                            SI1145_PARAM_CHLIST_EN_PS2 |
                                            SI1145_PARAM_CHLIST_EN_PS3 |
                                            SI1145_PARAM_CHLIST_EN_ALS_VIS |
                                            SI1145_PARAM_CHLIST_EN_ALS_IR) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_PSLED12_SELECT) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_PSLED12_SELECT_LED2) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_PS_ADC_GAIN) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_PS_ADC_GAIN_1X) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_PS_ADC_COUNTER) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_PS_ADC_COUNTER_16) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_VIS_ADC_GAIN) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_VIS_ADC_GAIN_1X) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_VIS_ADC_COUNTER) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_VIS_ADC_COUNTER_16) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_IR_ADC_GAIN) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_IR_ADC_GAIN_1X) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_IR_ADC_COUNTER) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;
    if (write_register(SI1145_REG_PARAM_WR, SI1145_PARAM_ALS_IR_ADC_COUNTER_16) < 0) return -1;
    if (write_register(SI1145_REG_COMMAND, 0xA0) < 0) return -1;

    if (write_register(SI1145_REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_register(SI1145_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (write_register(SI1145_REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (write_register(SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0) return -1;
    if (wait_for_response() < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *proximity) {
    if (write_register(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    if (wait_for_response() < 0) return -1;

    int low = read_register(SI1145_REG_PS1_DATA0);
    if (low < 0) return -1;
    int high = read_register(SI1145_REG_PS1_DATA1);
    if (high < 0) return -1;

    *proximity = (high << 8) | low;
    return 0;
}

static void log_proximity(uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Proximity: %u\n", timestamp, proximity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_si1145() != 0) {
        log_error("Si1145 initialisation failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 proximity logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t proximity = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_proximity(&proximity) == 0) {
                success = 1;
                break;
            }
            gpioDelay(10000);
        }

        if (success) {
            log_proximity(proximity);
        } else {
            log_error("Failed to read proximity after retries");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

