#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 200.0
#define MAX_DISTANCE_CM 20.0
#define MIN_ANGLE_US    500
#define MAX_ANGLE_US    2500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low for a clean pulse */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);

    /* Send 10 µs trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    /* Wait for echo to go high (start of pulse) */
    timeout_tick = gpioTick() + 50000; /* 50 ms timeout */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo start.\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    timeout_tick = gpioTick() + 50000; /* 50 ms timeout */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo end.\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range.\n", distance);
        return -1.0;
    }

    return distance;
}

static int set_servo_angle(float distance) {
    if (distance < 0.0) {
        return -1;
    }

    float angle = (distance - MAX_DISTANCE_CM) /
                  (MIN_DISTANCE_CM - MAX_DISTANCE_CM) *
                  (float)(MAX_ANGLE_US - MIN_ANGLE_US);

    if (angle < 0.0) {
        angle = 0.0;
    } else if (angle > (float)(MAX_ANGLE_US - MIN_ANGLE_US)) {
        angle = (float)(MAX_ANGLE_US - MIN_ANGLE_US);
    }

    int pulse_width = (int)(MIN_ANGLE_US + angle);

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us.\n", pulse_width);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Sensor error, retrying...\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (set_servo_angle(distance) < 0) {
                fprintf(stderr, "Servo set failed.\n");
            }
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");

    return EXIT_SUCCESS;
}

