/*
 * VL53L1X Gate Controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2 (I2C1 SDA)
 *   VL53L1X SCL  -> GPIO3 (I2C1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Servo signal -> GPIO18 (BCM 18, hardware PWM)
 *
 * Build:
 *   gcc -O2 -Wall -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 * Run:
 *   sudo ./gate_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (16-bit register addresses, big-endian on wire) ---- */
#define VL53L1X_ADDR             0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0087
#define VL53L1X_REG_RANGE_CONFIG_A          0x005E
#define VL53L1X_REG_RANGE_CONFIG_B          0x0061
#define VL53L1X_REG_PHASECAL_CONFIG         0x0044
#define VL53L1X_REG_DSS_CONFIG              0x0041
#define VL53L1X_REG_MSRC_CONFIG_CONTROL     0x0060
#define VL53L1X_REG_FINAL_RANGE_CONFIG_A    0x004E
#define VL53L1X_REG_FINAL_RANGE_CONFIG_B    0x0050
#define VL53L1X_REG_GPIO_HV_MUX_CTRL        0x0030
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0046
#define VL53L1X_REG_SYSTEM_THRESH_HIGH      0x004C
#define VL53L1X_REG_SYSTEM_THRESH_LOW       0x004E

#define VL53L1X_MODEL_ID_EXPECTED          0xEA

/* ---- Gate control constants ---- */
#define SERVO_PIN                          18
#define OPEN_PULSE_US                      1000
#define CLOSE_PULSE_US                     2000
#define DIST_THRESHOLD_MM                  250
#define DIST_HYSTERESIS_MM                 200
#define POLL_DELAY_US                      50000
#define LOG_FILE                           "gate_log.txt"

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- I2C helpers (16-bit register addressing) ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- VL53L1X initialization ---- */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Read and verify model ID */
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Program timing budget (40 ms intermeasurement, 20 ms timing budget) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_A, 0x006B) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_B, 0x006B) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_PHASECAL_CONFIG, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_DSS_CONFIG, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_MSRC_CONFIG_CONTROL, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_A, 0x006B) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_FINAL_RANGE_CONFIG_B, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_GPIO_HV_MUX_CTRL, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x0001) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_HIGH, 0x0000) < 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_LOW, 0x0000) < 0) return -1;

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0001) < 0) return -1;

    return 0;
