static int vl53l1x_read_distance(int handle)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};
    int distance = -1;

    /* Check if new data is ready */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
        return -1;

    if ((status & 0x01) == 0)
        return -1; /* No new data yet */

    /* Read 16-bit distance */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0)
        return -1;

    distance = (dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return distance;
}

/* ---- Gate control with hysteresis and pulse-width smoothing ---- */
static void control_gate(int distance_mm)
{
    static bool gate_open = false;
    static int current_pulse = CLOSE_PULSE_US;
    static int last_distance = DIST_THRESHOLD_MM + 1;

    if (distance_mm < 0) {
        /* Sensor error: close gate for safety */
        if (gate_open) {
            gpioServo(SERVO_PIN, CLOSE_PULSE_US);
            gate_open = false;
            log_event("Sensor error: closing gate");
        }
        return;
    }

    if (distance_mm > DIST_THRESHOLD_MM && !gate_open) {
        current_pulse = OPEN_PULSE_US;
        gate_open = true;
        gpioServo(SERVO_PIN, current_pulse);
        log_event("Object detected: opening gate");
    } else if (distance_mm < DIST_HYSTERESIS_MM && gate_open) {
        current_pulse = CLOSE_PULSE_US;
        gate_open = false;
        gpioServo(SERVO_PIN, current_pulse);
        log_event("Object close: closing gate");
    }

    /* Smooth transition between pulse widths */
    if (gate_open && distance_mm > DIST_THRESHOLD_MM && distance_mm < DIST_HYSTERESIS_MM) {
        int new_pulse = OPEN_PULSE_US + (int)(((float)(DIST_THRESHOLD_MM - distance_mm) /
                                              (float)(DIST_THRESHOLD_MM - DIST_HYSTERESIS_MM)) *
                                             (float)(OPEN_PULSE_US - CLOSE_PULSE_US));
        if (new_pulse != current_pulse) {
            current_pulse = new_pulse;
            gpioServo(SERVO_PIN, current_pulse);
        }
    }
}

/* ---- Logging ---- */
static void log_event(const char *event)
{
    if (!log_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x0000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, CLOSE_PULSE_US);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started: VL53L1X initialised, gate closed");

    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);
        control_gate(distance);
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

