/*
 * HC-SR04 ultrasonic distance sensor -> SG90 servo angle mapper
 * Board:  Raspberry Pi 4 Model B
 * Trigger: GPIO23 (BCM), Echo: GPIO24 (BCM)
 * Servo:   GPIO18 (BCM), 5 V power, common ground
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_servo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_S  34300.0   /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM      2.0
#define MAX_DISTANCE_CM      400.0
#define MIN_ANGLE_DEG        0.0
#define MAX_ANGLE_DEG        180.0
#define SERVO_MIN_PULSE_US   500       /* 0°   */
#define SERVO_MAX_PULSE_US   2500      /* 180° */
#define TRIGGER_PULSE_US     10
#define ECHO_TIMEOUT_US      50000     /* 50 ms */
#define LOOP_DELAY_US        100000    /* 100 ms between measurements */
#define INIT_DELAY_US        1000000   /* 1 s after init */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or -1.0 on timeout / error.                */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Warning: echo rising-edge timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Warning: echo falling-edge timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double distance = (diff / 1000000.0) * SPEED_OF_SOUND_CM_S / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance);
        return -1.0;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
/* Maps distance to servo angle. Returns 0 on success, -1 on error.   */
static int set_servo_angle(double distance)
{
    double angle;

    if (distance < 0.0) {
        angle = MIN_ANGLE_DEG;
    } else if (distance <= 20.0) {
        angle = MIN_ANGLE_DEG;
    } else if (distance >= 200.0) {
        angle = MAX_ANGLE_DEG;
    } else {
        angle = MIN_ANGLE_DEG +
                (distance - 20.0) * (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                (200.0 - 20.0);
    }

    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: invalid servo angle %.2f\n", angle);
        return -1;
    }

    int pulsewidth = (int)((angle / MAX_ANGLE_DEG) *
                           (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) +
                           SERVO_MIN_PULSE_US);

    if (gpioServo(SERVO_PIN, pulsewidth) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulsewidth);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(servo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* --- Install signal handler --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 -> SG90 servo. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Sensor read failed; keeping previous servo angle.\n");
        } else {
            printf("Distance: %.2f cm  ->  Angle: %.2f °\n", distance,
                   (distance - 20.0) * (180.0 / 180.0));
            if (set_servo_angle(distance) < 0) {
                fprintf(stderr, "Servo command failed.\n");
            }
        }

        /* 100 ms between measurements */
        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* stop servo PWM */
    gpioWrite(TRIGGER_PIN, 0); /* ensure trigger low */
    gpioTerminate();
    return EXIT_SUCCESS;
}

