#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* Si7005 I2C address (7-bit) */
#define SI7005_ADDR 0x40

/* Si7005 register addresses */
#define SI7005_REG_CONFIG  0x0E
#define SI7005_REG_MEAS    0x0F

/* Si7005 CONFIG register bits */
#define SI7005_CONFIG_RESET 0x80
#define SI7005_CONFIG_14BIT 0x00

/* Conversion time for 14-bit measurement (~7 ms; 10 ms is safe margin) */
#define SI7005_CONV_DELAY_US 10000

/* Polling interval between successful reads */
#define POLL_INTERVAL_US 2000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Initialize the Si7005 driver.
 * Returns 0 on success, -1 on failure.
 */
static int si7005_init(void)
{
    /*
     * Reset the device by writing 0x80 to the CONFIG register.
     * A read-modify-write is not strictly required for a reset, but
     * pigpio's i2cWriteByteData performs a write of the low byte of the
     * 16-bit value, so we use i2cWriteByteData with the high byte set
     * to 0x80.
     */
    if (i2cWriteByteData(g_i2c_handle, SI7005_REG_CONFIG, SI7005_CONFIG_RESET) < 0) {
        fprintf(stderr, "Error: failed to reset Si7005 (write CONFIG reset)\n");
        return -1;
    }

    /*
     * Wait for the reset to complete.  The Si7005 datasheet does not
     * specify a specific reset recovery time; 10 ms is a safe margin.
     */
    gpioDelay(10000);

    /*
     * Configure the sensor for 14-bit measurement mode.
     * Write 0x00 to the CONFIG register to select 14-bit resolution.
     */
    if (i2cWriteByteData(g_i2c_handle, SI7005_REG_CONFIG, SI7005_CONFIG_14BIT) < 0) {
        fprintf(stderr, "Error: failed to configure Si7005 (write CONFIG)\n");
        return -1;
    }

    return 0;
}

/*
 * Read a 16-bit value from a Si7005 register.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int si7005_read_reg16(uint8_t reg, uint16_t *out)
{
    int rc;

    /*
     * Write the register address to select the measurement.
     * i2cWriteByteData sends the low byte of the 16-bit value, so we
     * must send the address as the high byte of a 16-bit word.
     */
    rc = i2cWriteByteData(g_i2c_handle, reg, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C write failed for register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }

    /* Wait for the conversion to complete. */
    gpioDelay(SI7005_CONV_DELAY_US);

    /* Read 2 bytes of measurement data. */
    rc = i2cReadWordData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C read failed for register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }

    /*
     * pigpio returns the word in the host's byte order, which on a
     * little-endian Pi is already correct.  The Si7005 sends MSB
     * first, so the low byte of the word is the MSB of the 16-bit
     * measurement.
     */
    *out = (uint16_t)rc;
    return 0;
}

/*
 * Read temperature and humidity from the Si7005.
 * Returns 0 on success; -1 on failure.
 */
static int si7005_read(float *temperature, float *humidity)
{
    uint16_t raw_humidity, raw_temperature;

    if (si7005_read_reg16(SI7005_REG_MEAS, &raw_humidity) < 0)
        return -1;

    if (si7005_read_reg16(SI7005_REG_MEAS, &raw_temperature) < 0)
        return -1;

    /*
     * Convert raw 14-bit values to physical units.
     * Temperature: 14-bit value, 0.01 °C resolution.
     * Humidity:    14-bit value, 0.01 %RH resolution.
     */
    *temperature = (float)raw_temperature / 100.0f;
    *humidity    = (float)raw_humidity    / 100.0f;

    return 0;
}

int main(void)
{
    float temperature, humidity;

    /* Register signal handler for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si7005 address. */
    g_i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X (rc=%d)\n",
                SI7005_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si7005 sensor. */
    if (si7005_init() < 0) {
        fprintf(stderr, "Error: Si7005 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7005 sensor initialized. Reading every 2 seconds. Press Ctrl+C to exit.\n");

    /* Main loop: read and log data, re-open I2C on failure. */
    while (g_running) {
        if (si7005_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: failed to read sensor data. Re-opening I2C handle.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;

            /*
             * Brief delay before retrying to avoid hammering the bus
             * on persistent failures.
             */
            gpioDelay(100000);

            g_i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: failed to re-open I2C bus (rc=%d)\n", g_i2c_handle);
                /* Continue loop; the signal handler will exit. */
            } else {
                /* Re-initialize the sensor after re-opening. */
                if (si7005_init() < 0) {
                    fprintf(stderr, "Error: Si7005 re-initialization failed\n");
                    i2cClose(g_i2c_handle);
                    g_i2c_handle = -1;
                }
            }
        }

        /*
         * Sleep in small increments so SIGINT is caught promptly.
         * gpioDelay is interruptible by signals.
         */
        for (int i = 0; i < 20 && g_running; i++)
            gpioDelay(100000);
    }

    /* Graceful shutdown: close I2C handle and terminate pigpio. */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

