/*
 * MPU-6050 accelerometer & gyroscope reader for Raspberry Pi 3 Model B+
 * I2C bus 1 (SDA = GPIO2, SCL = GPIO3), address 0x68
 * Build: gcc -O2 -Wall -o mpu6050 mpu6050.c -lpigpio -lrt
 * Run:   sudo ./mpu6050
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define SAMPLE_PERIOD_US    100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/*
 * Read 14 bytes starting at ACCEL_XOUT_H (0x3B) using a single I2C block read.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *temp,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    char buf[14];

    if (i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) !=
        (int)sizeof(buf)) {
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
