/*
 * SHT40 Temperature & Humidity Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHT40 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   SHT40 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   SHT40 VDD  -> 3.3 V
 *   SHT40 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_reader sht40_reader.c -lpigpio -lrt
 * Run:    sudo ./sht40_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SHT40_ADDR           0x80          /* SHT40 default I2C address */
#define SHT40_CMD_MEASURE    0x2C          /* High-repeatability, clock stretching disabled */
#define SHT40_MEASURE_MS     10            /* Minimum measurement time (datasheet: 8.5 ms typ) */
#define SHT40_CRC_POLY       0x31          /* SHT40 CRC-8 polynomial */
#define SHT40_CRC_INIT       0xFF          /* SHT40 CRC-8 initial value */
#define SAMPLE_INTERVAL_S    5             /* Seconds between readings */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (SHT40 polynomial 0x31, init 0xFF)                */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SHT40_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and verify the sensor is present                   */
/* ------------------------------------------------------------------ */
static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from the SHT40                        */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch           */
/* ------------------------------------------------------------------ */
static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_MEASURE;
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (command 0x%02X) failed\n", cmd);
        return -1;
    }

    /* Wait for measurement to complete */
    gpioDelay(SHT40_MEASURE_MS * 1000);  /* microseconds */

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRCs */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch (calc 0x%02X, got 0x%02X)\n",
                sht40_crc8(&buf[0], 2), buf[2]);
        return -2;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch (calc 0x%02X, got 0x%02X)\n",
                sht40_crc8(&buf[3], 2), buf[5]);
        return -2;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C bus and verify sensor presence */
    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 reader started on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, SHT40_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float temperature, humidity;
        int rc = read_sht40(&temperature, &humidity);

        if (rc == 0) {
            printf("Temperature: %.2f °C  |  Humidity: %.2f %%\n",
                   temperature, humidity);
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C communication error — re-opening bus.\n");
            if (open_i2c() != 0) {
                fprintf(stderr, "[ERROR] Re-open failed; exiting.\n");
                break;
            }
        } else {
            fprintf(stderr, "[WARN] CRC validation failed — re-opening bus.\n");
            if (open_i2c() != 0) {
                fprintf(stderr, "[ERROR] Re-open failed; exiting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100 * 1000);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

