#define I2C_BUS         "/dev/i2c-1"
#define STS30_ADDR      0x48
#define LOG_FILE        "enclosure_temp_log.txt"
#define ERROR_LOG_FILE  "error_log.txt"
#define SAMPLE_INTERVAL 5
#define MEAS_DELAY_MS   20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] ERROR: %s\n", msg);
    }
    fclose(fp);
}

static void log_data(float temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    }
    fclose(fp);
}

/*
 * STS30-DIS temperature read (datasheet §4.2):
 *   Write command 0x78, 0x66 (start continuous measurement, high repeatability).
 *   Wait MEAS_DELAY_MS.
 *   Read 3 bytes: T_MSB, T_LSB, CRC.
 *   Temperature = (T_MSB << 8 | T_LSB) / 200.0.
 */
static int read_temperature(int fd, float *temp_out) {
    uint8_t cmd[2] = {0x78, 0x66};
    if (write(fd, cmd, 2) != 2) {
        log_error("I2C write failed (start measurement).");
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        log_error("I2C read failed (measurement data).");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_out = (float)raw / 200.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        log_error("Failed to open I2C bus.");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STS30_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        log_error("Failed to set I2C slave address.");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("STS30-DIS temperature logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) == 0) {
            log_data(temp);
            printf("Temperature: %.2f °C\n", temp);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

