/*
 * SDP810-125Pa differential pressure & temperature logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Sensirion SDP810-125Pa
 * Address: 0x25 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 *
 * Log file:  pressure_log.csv  (CSV: timestamp,pressure_pa,temperature_c)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SDP810_ADDR      0x25

/* SDP810 command bytes (14-bit measurement, no clock stretching) */
#define CMD_CONT_MEAS    0x361F  /* continuous measurement, mass flow / differential */
#define CMD_MEAS         0x362F  /* single measurement, mass flow / differential */

/* SDP810 scale factors (raw / factor = physical value) */
#define SCALE_PRESSURE   1.0f
#define SCALE_TEMP       1.0f

#define LOG_FILE         "pressure_log.csv"
#define SAMPLE_PERIOD_S  1
#define MEAS_DELAY_MS    1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;     /* Pa  */
    float temperature;  /* °C  */
} sensor_data_t;

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Layout: [p_msb p_lsb p_crc] [t_msb t_lsb t_crc]
 *         [s_msb s_lsb s_crc] [data_crc]
 * Returns 0 on success, -1 on error.
 */
static int read_sdp810(int fd, sensor_data_t *out)
{
    uint8_t buf[9];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC validation of each 2-byte + 1-byte triplet */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    out->pressure    = (float)raw_pressure * SCALE_PRESSURE;
    out->temperature = (float)raw_temp     * SCALE_TEMP;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int ensure_log_header(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (fp) {
        fclose(fp);
        return 0;          /* file already exists */
    }
    if (errno != ENOENT) {
        fprintf(stderr, "Cannot check log header: %s\n", strerror(errno));
        return -1;
    }

    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Cannot create log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *path, const sensor_data_t *data)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                path, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, data->pressure, data->temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto done;

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto done;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        goto cleanup_fd;
    }

    /* Start continuous measurement */
    if (i2c_write_cmd(fd, CMD_CONT_MEAS) != 0)
        goto cleanup_fd;

    /* Allow first measurement to complete */
    usleep(50000);  /* 50 ms */

    /* Create/verify CSV header */
    if (ensure_log_header(LOG_FILE) != 0)
        goto cleanup_fd;

    printf("SDP810 logging started.  Press Ctrl-C to stop.\n");

    while (g_running) {
        /* Trigger a single measurement */
        if (i2c_write_cmd(fd, CMD_MEAS) != 0) {
            fprintf(stderr, "Measurement trigger failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        usleep(MEAS_DELAY_MS * 1000);

        sensor_data_t data;
        if (read_sdp810(fd, &data) != 0) {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (log_data(LOG_FILE, &data) != 0)
            fprintf(stderr, "Logging failed (continuing).\n");

        printf("Pressure: %.2f Pa | Temperature: %.2f °C\n",
               data.pressure, data.temperature);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup_fd:
    if (fd >= 0)
        close(fd);
done:
    return rc;
}

