/*
 * SDP31 differential pressure & temperature logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP31 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP31 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP31 VDD  -> 3.3 V
 *   SDP31 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:
 *   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SDP31_ADDR           0x21          /* Sensirion SDP31 default I2C address */
#define LOG_FILE             "airflow.log"
#define SAMPLE_INTERVAL_US   100000        /* 100 ms */
#define MAX_RETRIES          3
#define RETRY_DELAY_BASE_US  1000          /* 1 ms */
#define RETRY_DELAY_MULTIPLIER 2

/* SDP31 continuous measurement command (no clock stretching) */
#define CMD_CONT_MEAS_NO_STRETCH 0x362F

/* SDP31 response: [P_msb, P_lsb, P_crc, T_msb, T_lsb, T_crc] */
#define RESP_LEN             6

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_log(void);
static int  read_sdp31(float *pressure_pa, float *temperature_c);
static int  log_data(float pressure_pa, float temperature_c);
static void cleanup(void);

/* ----------------------------- Signal handler -------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init ------------------------------ */

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, SDP31_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }
    return 0;
}

/* ------------------------------- Log file ------------------------------ */

static int init_log(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write a header only if the file was just created (size == 0). */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_log_file);
    }
    return 0;
}

/* --------------------------- SDP31 read -------------------------------- */

/*
 * Trigger continuous measurement, wait, then read the 6-byte response.
 * Returns 0 on success, -1 on failure.
 */
static int read_sdp31(float *pressure_pa, float *temperature_c)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_MEAS_NO_STRETCH >> 8) & 0xFF),
        (uint8_t)(CMD_CONT_MEAS_NO_STRETCH & 0xFF)
    };
    uint8_t buf[RESP_LEN];
    int     rc;
    int     retries = 0;

    while (retries < MAX_RETRIES) {
        /* --- Trigger measurement --- */
        rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
        if (rc < 0) {
            fprintf(stderr, "Warning: i2cWriteDevice (trigger) failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, pigpio_error(rc));
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(RETRY_DELAY_BASE_US * RETRY_DELAY_MULTIPLIER * retries);
            }
            continue;
        }

        /* --- Wait for conversion (datasheet: typ 2 ms, max 10 ms) --- */
        gpioDelay(2000);  /* 2 ms */

        /* --- Read 6 bytes --- */
        rc = i2cReadDevice(g_i2c_handle, (char *)buf, RESP_LEN);
        if (rc == RESP_LEN) {
            break;
        }

        fprintf(stderr, "Warning: i2cReadDevice failed (attempt %d/%d): got %d bytes, %s\n",
                retries + 1, MAX_RETRIES, rc,
                (rc < 0) ? pigpio_error(rc) : "short read");
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_BASE_US * RETRY_DELAY_MULTIPLIER * retries);
        }
    }

    if (rc != RESP_LEN) {
        fprintf(stderr, "Error: SDP31 read failed after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    /* CRC-8 check (polynomial 0x31, init 0xFF, no final XOR) */
    uint8_t crc_p = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc_p ^= buf[i];
        for (int b = 0; b < 8; b++) {
            if (crc_p & 0x80)
                crc_p = (uint8_t)((crc_p << 1) ^ 0x31);
            else
                crc_p = (uint8_t)(crc_p << 1);
        }
    }
    if (crc_p != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc_p, buf[2]);
        return -1;
    }

    /* CRC-8 check for temperature */
    crc_p = 0xFF;
    for (int i = 3; i < 5; i++) {
        crc_p ^= buf[i];
        for (int b = 0; b < 8; b++) {
            if (crc_p & 0x80)
                crc_p = (uint8_t)((crc_p << 1) ^ 0x31);
            else
                crc_p = (uint8_t)(crc_p << 1);
        }
    }
    if (crc_p != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc_p, buf[5]);
        return -1;
    }

    /*
     * SDP31: pressure = (P_msb << 8 | P_lsb) / 60.0  (Pa)
     *        temperature = (T_msb << 8 | T_lsb) / 200.0 + 45.0 (°C)
     */
    int16_t raw_p = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure_pa    = (float)raw_p / 60.0f;
    *temperature_c  = (float)raw_t / 200.0f + 45.0f;

    return 0;
}

/* ------------------------------- Logging -------------------------------- */

static int log_data(float pressure_pa, float temperature_c)
{
    time_t     now;
    struct tm  tm_info;
    char       ts[32];

    time(&now);
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup -------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main --------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize subsystems --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_log() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP31 airflow logger started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_INTERVAL_US / 1000);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        float pressure_pa = 0.0f;
        float temperature_c = 0.0f;

        if (read_sdp31(&pressure_pa, &temperature_c) == 0) {
            if (log_data(pressure_pa, temperature_c) != 0) {
                fprintf(stderr, "Error: logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly. */
        uint32_t remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 10000) ? 10000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

