#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000  /* 5 seconds */
#define MEASURE_MS     20       /* max conversion time */
#define RETRY_US       10000    /* 10 ms between retries */
#define MAX_RETRIES    10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian value from the Si7015.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_word(int handle, uint8_t cmd, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, strerror(errno));
        return -1;
    }

    /* Si7015 needs ~7 ms after issuing a hold-master command before
     * the result register is ready.  Poll for up to MEASURE_MS ms. */
    for (int i = 0; i < MEASURE_MS; i += 2) {
        gpioDelay(2000);  /* 2 ms */
        rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X): %s\n",
                    cmd, strerror(errno));
            return -1;
        }
    }

    fprintf(stderr, "Sensor measurement timeout (cmd 0x%02X)\n", cmd);
    return -1;
}

static int read_temperature(int handle, float *temp_c)
{
    uint16_t raw;
    if (read_sensor_word(handle, CMD_TEMP_HOLD, &raw) != 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *rh)
{
    uint16_t raw;
    if (read_sensor_word(handle, CMD_HUM_HOLD, &raw) != 0)
        return -1;
    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static void log_data(float temp_c, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

