#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x22
#define TRIGGER_CMD    0x362F
#define MEASURE_DELAY  45000   /* microseconds */
#define SAMPLE_DELAY   100000  /* microseconds */
#define DATA_FILE      "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t data[9];

    if (i2c_write_cmd(fd, TRIGGER_CMD) < 0)
        return -1;

    usleep(MEASURE_DELAY);

    if (i2c_read_block(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRC for each 3-byte word */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 200.0f;

    return 0;
}

static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f\n", pressure, temperature);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: a zero-length write is a valid NOP on many I2C adapters */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Create/append CSV with header */
    FILE *fp = fopen(DATA_FILE, "r");
    int need_header = (fp == NULL);
    if (fp) fclose(fp);

    fp = fopen(DATA_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", DATA_FILE, strerror(errno));
        goto cleanup;
    }
    if (need_header)
        fprintf(fp, "Timestamp,Pressure_Pa,Temperature_C\n");
    fclose(fp);

    printf("SDP800 airflow logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sdp800(fd, &pressure, &temperature) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            if (log_data(DATA_FILE, pressure, temperature) < 0)
                fprintf(stderr, "Logging failed.\n");
            else
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                       pressure, temperature);
        }

        usleep(SAMPLE_DELAY);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return rc;
}

