/*
 * Raspberry Pi Zero W – Sensirion STS30-DIS temperature logger
 *
 * Wiring:
 *   STS30-DIS SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   STS30-DIS SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   STS30-DIS VDD  -> 3.3 V
 *   STS30-DIS GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o enclosure_temp enclosure_temp.c
 * Run:    ./enclosure_temp
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define STS30_ADDR       0x48          /* STS30-DIS default I2C address */
#define MEAS_CMD         0x2400        /* single-shot, high repeatability, clock stretching disabled */
#define MEAS_DELAY_MS    15            /* max conversion time for high repeatability */
#define SAMPLE_INTERVAL  5             /* seconds between samples */
#define LOG_FILE         "enclosure_temp_log.txt"
#define ERROR_LOG_FILE   "error_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void timestamp_str(char *buf, size_t len)
