#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD  1000000   /* microseconds (1 s) */
#define MEAS_DELAY_US  1000      /* 1 ms measurement settling time */

/* SDP800 continuous measurement command (no clock stretching) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu (%s)\n",
                n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;     /* Pa  */
    float temperature;  /* °C  */
} sensor_data_t;

/*
 * Read one 6-byte measurement frame from the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int read_sdp800(int fd, sensor_data_t *out)
{
    uint8_t buf[6];

    if (i2c_read(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /* SDP800-500Pa conversion formulas */
    out->pressure    = (float)raw_pressure    / 240.0f;   /* Pa  */
    out->temperature = (float)raw_temperature / 200.0f;   /* °C  */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const sensor_data_t *d)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, d->pressure, d->temperature);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0)
        fprintf(g_log, "timestamp,pressure_pa,temperature_c\n");

    /* Start continuous measurement */
    if (i2c_write(g_i2c_fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
        fprintf(stderr, "Failed to start continuous measurement.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after the command */
    usleep(MEAS_DELAY_US);

    printf("SDP800 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        sensor_data_t d;

        if (read_sdp800(g_i2c_fd, &d) == 0) {
            log_data(g_log, &d);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   d.pressure, d.temperature);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

