#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  27.0f
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  2.0
#define FAN_DELAY_US   10000
#define MAX_RETRIES    3
#define MEAS_CMD       0xE3
#define MEAS_DELAY_US  25000

typedef struct {
    time_t timestamp;
    float  temperature;
} SensorData;

static SensorData buffer[BUFFER_SIZE];
static int        buf_head = 0;
static int        buf_count = 0;
static int        i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *out) {
    char cmd = MEAS_CMD;
    char buf[2];
    int  rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %d\n",
                    attempt + 1, MAX_RETRIES, rc);
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        rc = i2cReadDevice(i2c_handle, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *out = (175.72f * raw / 65536.0f) - 46.85f;
            return 0;
        }

        fprintf(stderr, "I2C read failed (attempt %d/%d): got %d bytes\n",
                attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

static void add_to_buffer(float temperature) {
    time(&buffer[buf_head].timestamp);
    buffer[buf_head].temperature = temperature;
    buf_head = (buf_head + 1) % BUFFER_SIZE;
    if (buf_count < BUFFER_SIZE) buf_count++;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Buffer (%d entries) ---\n", buf_count);
    for (int i = 0; i < buf_count; i++) {
        int idx = (buf_head - buf_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temperature: %.2f C\n", ts, buffer[idx].temperature);
    }
    printf("--- End Buffer ---\n\n");
}

static void control_fan(float temperature) {
    static int fan_on = 0;
    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON  (T=%.2f C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (T=%.2f C)\n", temperature);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 fan controller started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            control_fan(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries — sensor may be absent.\n",
                    MAX_RETRIES);
        }
        print_buffer();
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

