/*
 * SCD40 CO2 / Temperature / Humidity monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SCD40 constants (datasheet) ---- */
#define SCD40_I2C_ADDR             0x62
#define SCD40_BUS                  1
#define SCD40_CMD_START_PERIODIC   0x21B1   /* 0x21, 0xB1 — start periodic measurement */
#define SCD40_CMD_STOP_PERIODIC    0x3F06   /* 0x3F, 0x06 — stop periodic measurement  */
#define SCD40_CMD_DATA_READY       0xE4B8   /* 0xE4, 0xB8 — read data-ready flag        */
#define SCD40_CMD_READ_MEASUREMENT 0xEC05   /* 0xEC, 0x05 — read measurement result     */
#define SCD40_MEASUREMENT_INTERVAL 5        /* seconds between readings */
#define SCD40_FIRST_READ_DELAY     1        /* seconds after start before first read */
#define SCD40_DATA_READY_TIMEOUT   30       /* seconds to wait for first data-ready   */
#define SCD40_DATA_READY_POLL_MS  200       /* poll interval while waiting            */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t scd40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Low-level I2C helpers ---- */
static int scd40_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(int handle, uint8_t *buf, size_t len)
{
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected %zu bytes)\n", len);
        return -1;
    }
    return 0;
}

/* ---- Sensor operations ---- */
static int scd40_start_periodic(int handle)
{
    if (scd40_write_cmd(handle, SCD40_CMD_START_PERIODIC) != 0)
        return -1;
    return 0;
}

static int scd40_stop_periodic(int handle)
{
    if (scd40_write_cmd(handle, SCD40_CMD_STOP_PERIODIC) != 0)
        return -1;
    return 0;
}

static int scd40_data_ready(int handle, int *ready)
{
    if (scd40_write_cmd(handle, SCD40_CMD_DATA_READY) != 0)
        return -1;

    /* Datasheet: max 1 ms for command processing */
    gpioDelay(2000); /* 2 ms */

    uint8_t buf[3];
    if (scd40_read_data(handle, buf, sizeof(buf)) != 0)
        return -1;

    if (scd40_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }

    uint16_t word = ((uint16_t)buf[0] << 8) | buf[1];
    *ready = (word & 0x07FF) != 0;
    return 0;
}

static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temp, float *rh)
{
    if (scd40_write_cmd(handle, SCD40_CMD_READ_MEASUREMENT) != 0)
        return -1;

    /* Datasheet: max 1 ms for command processing, 9 bytes arrive in ~1 ms */
    gpioDelay(2000);

    uint8_t buf[9];
    if (scd40_read_data(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC checks for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (scd40_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw   = ((uint16_t)buf[6] << 8) | buf[7];

    *co2  = co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *rh   = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, uint16_t co2, float temp, float rh)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(fp);
}

/* ---- Signal handling ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_stop_periodic(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SCD40 address */
    g_i2c_handle = i2cOpen(SCD40_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("air_quality.log", "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open air_quality.log\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start periodic measurement */
    if (scd40_start_periodic(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Wait for first measurement to be ready (max ~5 s) */
    int data_ready = 0;
    for (int i = 0; i < SCD40_DATA_READY_TIMEOUT && g_running; i++) {
        if (scd40_data_ready(g_i2c_handle, &data_ready) != 0) {
            fprintf(stderr, "[WARN] Data-ready check failed; continuing\n");
            gpioDelay(1000000); /* 1 s */
            continue;
        }
        if (data_ready)
            break;
        gpioDelay(SCD40_DATA_READY_POLL_MS * 1000); /* 200 ms */
    }

    if (!data_ready) {
        fprintf(stderr, "[WARN] SCD40 first measurement not ready after %d s; "
                        "continuing with periodic mode\n", SCD40_DATA_READY_TIMEOUT);
    }

    /* Main loop */
    while (g_running) {
        /* Wait for next measurement to be ready */
        data_ready = 0;
        for (int i = 0; i < SCD40_DATA_READY_TIMEOUT && g_running; i++) {
            if (scd40_data_ready(g_i2c_handle, &data_ready) != 0) {
                fprintf(stderr, "[WARN] Data-ready check failed; retrying\n");
                gpioDelay(1000000);
                continue;
            }
            if (data_ready)
                break;
            gpioDelay(SCD40_DATA_READY_POLL_MS * 1000);
        }

        if (!data_ready) {
            fprintf(stderr, "[WARN] Data not ready; skipping cycle\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        /* Read measurement */
        uint16_t co2;
        float temp, rh;
        if (scd40_read_measurement(g_i2c_handle, &co2, &temp, &rh) != 0) {
            fprintf(stderr, "[WARN] Read measurement failed; retrying\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        /* Log */
        log_data(g_log_file, co2, temp, rh);

        /* Wait for next cycle */
        gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
    }

    /* Graceful shutdown */
    fprintf(stderr, "\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

