        sensor_data_t d;
        if (read_scd40(&d)) {
            add_to_buffer(&d);
            print_buffer();
            control_led(d.co2);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

