/*
 * SCD40 CO2 / Temperature / Humidity monitor with LED threshold indicator.
 *
 * Hardware:
 *   - Raspberry Pi 4 Model B
 *   - SCD40 on I2C bus 1, address 0x62
 *   - Warning LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SCD40_ADDR           0x62
#define GPIO_LED             17
#define CO2_THRESHOLD        1000          /* ppm */
#define BUFFER_SIZE          20
#define SAMPLE_INTERVAL_S    5

/* SCD40 command bytes (MSB = 0x36 for all) */
#define CMD_START_PERIODIC   0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_STOP_PERIODIC    0x0104
#define CMD_GET_DATA_READY   0x0202
#define CMD_GET_SERIAL      0x3682

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
    time_t   timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ----------------------------- Globals ----------------------------------- */
static int           i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static uint8_t  crc8(const uint8_t *data, size_t len);
static bool     init_i2c(void);
static bool     init_scd40(void);
static bool     read_scd40(sensor_data_t *out);
static void     add_to_buffer(const sensor_data_t *d);
static void     print_buffer(void);
static void     control_led(uint16_t co2);
static void     signal_handler(int sig);
static void     cleanup(void);

/* ----------------------------- CRC-8 (Sensirion) -------------------------- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ----------------------------- I2C / GPIO --------------------------------- */
static bool init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        return false;
    }
    return true;
}

/* ----------------------------- SCD40 -------------------------------------- */
static bool init_scd40(void)
{
    /* Start periodic measurement: 5-second interval, ambient pressure ~101325 */
    uint8_t cmd[3] = { 0x21, 0x00, 0x00 };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 3) != 3) {
        fprintf(stderr, "[ERROR] Failed to write start-periodic command\n");
        return false;
    }
    gpioDelay(500000); /* 500 ms settle */
    return true;
}

/*
 * Read one measurement.  Returns true on success, false on any I2C error.
 * The SCD40 returns 9 bytes: 3 words + 3 CRCs.
 */
static bool read_scd40(sensor_data_t *out)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_READ_MEASUREMENT >> 8),
                       (uint8_t)(CMD_READ_MEASUREMENT & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] Failed to write read-measurement command\n");
        return false;
    }

    gpioDelay(2000); /* 2 ms processing delay */

    uint8_t buf[9];
    int n = i2cReadDevice(i2c_handle, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read returned %d bytes (expected %zu)\n",
                n, sizeof(buf));
        return false;
    }

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return false;
        }
    }

    uint16_t co2        = (buf[0] << 8) | buf[1];
    uint16_t temp_raw   = (buf[3] << 8) | buf[4];
    uint16_t rh_raw     = (buf[6] << 8) | buf[7];

    out->co2           = co2;
    out->temperature   = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    out->humidity      = 100.0f * (float)rh_raw / 65535.0f;
    out->timestamp     = time(NULL);
    return true;
}

/* ----------------------------- Circular Buffer ---------------------------- */
static void add_to_buffer(const sensor_data_t *d)
{
    buffer.data[buffer.head] = *d;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
}

static void print_buffer(void)
{
    printf("\n--- Last %d Readings ---\n", buffer.count);
    for (int i = 0; i < buffer.count; i++) {
        int idx = (buffer.head - buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&buffer.data[idx].timestamp));
        printf("  [%s] CO2=%u ppm  T=%.2f C  RH=%.2f %%\n",
               ts, buffer.data[idx].co2,
               buffer.data[idx].temperature,
               buffer.data[idx].humidity);
    }
    printf("--------------------------\n");
    fflush(stdout);
}

/* ----------------------------- LED Control -------------------------------- */
static void control_led(uint16_t co2)
{
    gpioWrite(GPIO_LED, co2 > CO2_THRESHOLD ? 1 : 0);
}

/* ----------------------------- Signal / Cleanup --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        uint8_t cmd[2] = { (uint8_t)(CMD_STOP_PERIODIC >> 8),
                           (uint8_t)(CMD_STOP_PERIODIC & 0xFF) };
        i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO%d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    if (!init_i2c()) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!init_scd40()) {
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&buffer, 0, sizeof(buffer));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started.  Press Ctrl-C to exit.\n");

    while (!terminate) {
        sensor_data_t d;
        if (read_scd40(&d)) {
            add_to_buffer(&d);
            print_buffer();
            control_led(d.co2);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

