/*
 * TMP05 digital temperature sensor reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMP05 VCC  -> 3.3 V (pin 1)
 *   TMP05 GND  -> GND   (pin 9)
 *   TMP05 OUT  -> GPIO4 (pin 7, BCM 4)
 *
 * The TMP05 outputs a PWM-style signal: high time proportional to
 * temperature, low time fixed.  We sample the high time and total
 * period with busy-wait microsecond timestamps, compute the
 * temperature, and log it with an ISO-8601 timestamp.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_reader tmp05_reader.c -lpigpio -lrt
 * Run:    sudo ./tmp05_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          4          /* BCM 4, physical pin 7 */
#define LOG_FILE          "temperature_log.txt"
#define SAMPLE_INTERVAL_S 5          /* seconds between samples */
#define POLL_TIMEOUT_US   50000      /* 50 ms edge-wait timeout */
#define MAX_CONSEC_ERRORS 3          /* consecutive failures before alert */
#define TEMP_MIN_C        (-40.0f)
#define TEMP_MAX_C        (150.0f)

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_line(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* TMP05 measurement                                                  */
/* ------------------------------------------------------------------ */

/*
 * Busy-wait for a GPIO edge.  Returns 0 on success, -1 on timeout.
 * On success, *state is set to the level reached.
 */
static int wait_for_edge(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    int prev = gpioRead(gpio);
    if (prev < 0) {
        return -1;
    }

    while (g_running) {
        int cur = gpioRead(gpio);
        if (cur < 0) {
            return -1;
        }
        if (cur == level && prev != level) {
            return 0;
        }
        prev = cur;
        if ((gpioTick() - start) >= timeout_us) {
            return -1;
        }
    }
    return -1;
}

/*
 * Measure the high-pulse width (TH) and total period (TC) of the
 * TMP05 PWM output.  Returns 0 on success, -1 on error.
 */
static int measure_pulse(int gpio, uint32_t *th_us, uint32_t *tc_us)
{
    int rc;

    /* Wait for the output to go HIGH (start of high phase). */
    rc = wait_for_edge(gpio, 1, POLL_TIMEOUT_US);
    if (rc != 0) {
        return -1;
    }

    uint32_t hi_start = gpioTick();

    /* Wait for the output to go LOW (end of high phase). */
    rc = wait_for_edge(gpio, 0, POLL_TIMEOUT_US);
    if (rc != 0) {
        return -1;
    }

    uint32_t hi_end = gpioTick();
    *th_us = hi_end - hi_start;

    /*
     * Wait for the output to go HIGH again (start of low phase).
     * If it never does, the sensor is absent or stuck; treat as error.
     */
    rc = wait_for_edge(gpio, 1, POLL_TIMEOUT_US);
    if (rc != 0) {
        return -1;
    }

    uint32_t lo_start = gpioTick();

    /* Wait for the output to go LOW again (end of low phase). */
    rc = wait_for_edge(gpio, 0, POLL_TIMEOUT_US);
    if (rc != 0) {
        return -1;
    }

    uint32_t lo_end = gpioTick();
    *tc_us = lo_end - lo_start;

    return 0;
}

/*
 * Convert TMP05 PWM timing to temperature (°C).
 *
 * The TMP05 PWM output is a square wave: 50 % duty cycle.
 *   TH = high-pulse width (us)
 *   TC = total period     (us)
 *
 * Temperature (°C) = TH / TC * 150 - 40
 *
 * Guard against division by zero.
 */
static float calculate_temperature(uint32_t th_us, uint32_t tc_us)
{
    if (tc_us == 0) {
        return -999.0f;
    }
    float temp_c = ((float)th_us / (float)tc_us) * 150.0f - 40.0f;
    return temp_c;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the line is deterministic when
     * the sensor is disconnected. */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Allow the sensor to settle after power-up. */
    gpioDelay(100000); /* 100 ms */

    int consecutive_errors = 0;

    /* ---- Main loop ---- */
    while (g_running) {
        uint32_t th_us = 0;
        uint32_t tc_us = 0;

        if (measure_pulse(GPIO_PIN, &th_us, &tc_us) != 0) {
            consecutive_errors++;
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "ERROR: PWM measurement timeout (consecutive=%d)",
                     consecutive_errors);
            log_line(msg);

            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                log_line("ERROR: SENSOR MALFUNCTION - 3 consecutive failures");
                consecutive_errors = 0;
            }
        } else {
            float temp_c = calculate_temperature(th_us, tc_us);

            if (temp_c < TEMP_MIN_C || temp_c > TEMP_MAX_C) {
                char msg[128];
                snprintf(msg, sizeof(msg),
                         "ERROR: Temperature out of range: %.2f C", temp_c);
                log_line(msg);
                consecutive_errors++;
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Temperature: %.2f C", temp_c);
                log_line(msg);
                consecutive_errors = 0;
            }
        }

        /* Sleep SAMPLE_INTERVAL_S seconds, but wake early on signal. */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            gpioDelay(1000000); /* 1 s */
        }
    }

    /* ---- Cleanup ---- */
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

