#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2400
#define MEASURE_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_hum = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        *humidity = 100.0f * (float)raw_hum / 65535.0f;
        return 0;
    }

    fprintf(stderr, "Failed to read SHT35 after %d attempts\n", RETRY_COUNT);
    *temperature = NAN;
    *humidity = NAN;
    return -1;
}

static void add_noise(float *temperature, float *humidity) {
    float t_noise = (rand() % 400 - 200) / 100.0f;
    float h_noise = (rand() % 1000 - 500) / 1000.0f;
    *temperature += t_noise;
    *humidity += h_noise;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (isnan(temperature) || isnan(humidity)) {
        fprintf(log_file, "%s, ERROR: Sensor read failed\n", timestamp);
    } else {
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    }
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            add_noise(&temperature, &humidity);
            log_data(temperature, humidity);
        } else {
            log_data(NAN, NAN);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

