/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF).                       */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly.               */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and target the SDP810.                             */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Send the continuous-measurement command.                           */
/* ------------------------------------------------------------------ */
static int sdp810_start_continuous(int fd)
{
    if (write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS))
        != (ssize_t)sizeof(CMD_CONT_MEAS)) {
        fprintf(stderr, "write(start_continuous): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 9 bytes (3 × (2 data + 1 CRC)).                                */
/* ------------------------------------------------------------------ */
static int sdp810_read_measurement(int fd, uint8_t *buf)
{
    ssize_t n = read(fd, buf, 9);
    if (n != 9) {
        if (n < 0)
            fprintf(stderr, "read(): %s\n", strerror(errno));
        else
            fprintf(stderr, "read(): short read (%zd bytes)\n", n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate CRCs for each 2-byte data word.                            */
/* ------------------------------------------------------------------ */
static int sdp810_validate_crcs(const uint8_t *buf)
{
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr,
                    "CRC mismatch on word %d (calc=0x%02X, got=0x%02X)\n",
                    i, crc8(&buf[i * 3], 2), buf[i * 3 + 2]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw bytes to physical units (SDP810-125Pa).                */
/* ------------------------------------------------------------------ */
static void sdp810_convert(const uint8_t *buf,
                           float *pressure_pa,
                           float *temperature_c)
{
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    /*
     * Pressure (Pa) = raw_pressure / scale_factor
     * Temperature (°C) = raw_temperature / 200 - 50
     *
     * The scale factor is a signed 16-bit value; for the 125 Pa
     * variant it is typically in the range 2000–4000.
     */
    *pressure_pa    = (float)raw_pressure / (float)scale_factor;
    *temperature_c  = (float)raw_temperature / 200.0f - 50.0f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped CSV row.                                      */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure_pa, float temperature_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes open resources in reverse order.           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = i2c_open(I2C_BUS, SDP810_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* ---- Open log file (append mode) ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,pressure_pa,temperature_c\n") < 0) {
            fprintf(stderr, "fprintf(header): %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    /* ---- Start continuous measurement ---- */
    if (sdp810_start_continuous(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor absent or bus error — check wiring.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow the first conversion to complete. */
    usleep(CONV_DELAY_MS * 1000);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint8_t buf[9];

        if (sdp810_read_measurement(g_i2c_fd, buf) != 0) {
            fprintf(stderr, "Read failed; retrying in 1 s.\n");
            sleep(1);
            continue;
        }

        if (sdp810_validate_crcs(buf) != 0) {
            fprintf(stderr, "CRC validation failed; retrying in 1 s.\n");
            sleep(1);
            continue;
        }

        float pressure_pa, temperature_c;
        sdp810_convert(buf, &pressure_pa, &temperature_c);

        if (log_data(g_log_fp, pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
               pressure_pa, temperature_c);

        sleep(1);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

