/*
 * SHT35-DIS-B temperature/humidity logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT35 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SHT35 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SHT35 VDD  -> 3.3 V
 *   SHT35 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c -li2c
 *
 * The SHT35 single-shot, high-repeatability command (0x24 0x00) returns
 * 6 bytes: T_MSB T_LSB T_CRC RH_MSB RH_LSB RH_CRC
 * CRC-8 polynomial 0x31, initial value 0xFF.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT35_ADDR     0x44
#define CSV_FILE       "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_US  20000      /* 20 ms — covers 15 ms max conversion */

/* SHT35 single-shot, high-repeatability, clock-stretching disabled */
static const uint8_t CMD_MEASURE[2] = { 0x24, 0x00 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHT35 driver                                                        */
/* ------------------------------------------------------------------ */
static int sht35_init(int fd)
{
    /*
     * The SHT35-DIS-B requires no explicit driver-level initialization.
     * We simply send the measurement command.
     */
    return 0;
}

static int sht35_shutdown(int fd)
{
    /*
     * The SHT35-DIS-B has no dedicated shutdown command.
     * If the I2C handle is closed, the sensor enters a low-power state.
     */
    return 0;
}

static int sht35_read(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRCs */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int ensure_csv_header(void)
{
    FILE *fp = fopen(CSV_FILE, "r");
    if (fp) {
        fseek(fp, 0, SEEK_END);
        long sz = ftell(fp);
        fclose(fp);
        if (sz > 0)
            return 0;          /* file exists and is non-empty */
    }

    fp = fopen(CSV_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Cannot create %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    fclose(fp);
    return 0;
}

static int log_data(float temp, float rh)
{
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SHT35_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (sht35_init(g_i2c_fd) != 0) {
        fprintf(stderr, "SHT35 initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (ensure_csv_header() != 0) {
        sht35_shutdown(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl-C to stop.\n",
           CSV_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temp, rh;

        if (sht35_read(g_i2c_fd, &temp, &rh) == 0) {
            printf("T=%.2f C  RH=%.2f %%\n", temp, rh);
            if (log_data(temp, rh) != 0)
                fprintf(stderr, "Logging failed (continuing)\n");
        } else {
            fprintf(stderr, "Sensor read failed (continuing)\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    sht35_shutdown(g_i2c_fd);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

