/*
 * Si7021 greenhouse monitor — Raspberry Pi Zero W (I2C bus 1, addr 0x40)
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_monitor si7021_monitor.c
 * Run:    ./si7021_monitor   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_DELAY_US  10000   /* 10 ms between poll attempts */
#define MEAS_TIMEOUT_US 100000 /* 100 ms max wait for conversion */
#define SAMPLE_PERIOD_S 5

/* Si7021 commands (MSB of the 2-byte write) */
#define CMD_MEASURE_RH_HOLD   0xE5
#define CMD_MEASURE_TEMP_HOLD 0xE3
#define CMD_RESET             0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00) — Si7021 datasheet                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    uint8_t buf[1] = { cmd };
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n)
{
    ssize_t r = read(fd, buf, n);
    if (r < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)r != n) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", r, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int si7021_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) == -1)
        return -1;
    usleep(15000); /* datasheet: 15 ms reset settling */
    return 0;
}

/*
 * Trigger a measurement and poll until data is ready or the timeout
 * expires.  Returns 0 on success, -1 on error.
 */
static int si7021_wait_measurement(int fd, uint8_t cmd)
{
    if (i2c_write_cmd(fd, cmd) == -1)
        return -1;

    uint8_t data[3];
    size_t total = 0;
    int attempts = 0;

    while (total < 3 && attempts < (MEAS_TIMEOUT_US / POLL_DELAY_US)) {
        usleep(POLL_DELAY_US);
        if (i2c_read_n(fd, data + total, 3 - total) == -1)
            return -1;
        total += (3 - total);
        attempts++;
    }

    if (total < 3) {
        fprintf(stderr, "Sensor measurement timeout (cmd 0x%02X)\n", cmd);
        return -1;
    }
    return 0;
}

static int si7021_read_temperature(int fd, float *temp_c)
{
    if (si7021_wait_measurement(fd, CMD_MEASURE_TEMP_HOLD) == -1)
        return -1;

    uint8_t data[3];
    if (i2c_read_n(fd, data, 3) == -1)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X got=0x%02X)\n",
                crc8(data, 2), data[2]);
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int si7021_read_humidity(int fd, float *rh)
{
    if (si7021_wait_measurement(fd, CMD_MEASURE_RH_HOLD) == -1)
        return -1;

    uint8_t data[3];
    if (i2c_read_n(fd, data, 3) == -1)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Humidity CRC mismatch (calc=0x%02X got=0x%02X)\n",
                crc8(data, 2), data[2]);
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
        fflush(fp);
    }
    return 0;
}

static void log_line(FILE *fp, float temp_c, float rh)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv)) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        strncpy(ts, "1970-01-01T00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe: a NACK here typically means the sensor is absent */
    uint8_t probe = 0x00;
    if (write(g_i2c_fd, &probe, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (si7021_reset(g_i2c_fd) == -1) {
        fprintf(stderr, "Sensor reset failed — check wiring/power.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) == -1) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot reopen %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        int ok = 1;

        if (si7021_read_temperature(g_i2c_fd, &temp_c) == -1) {
            fprintf(stderr, "Temperature read failed — resetting.\n");
            si7021_reset(g_i2c_fd);
            ok = 0;
        }

        if (ok && si7021_read_humidity(g_i2c_fd, &rh) == -1) {
            fprintf(stderr, "Humidity read failed — resetting.\n");
            si7021_reset(g_i2c_fd);
            ok = 0;
        }

        if (ok) {
            log_line(log_fp, temp_c, rh);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
        } else {
            fprintf(stderr, "Logging ERROR row.\n");
            log_line(log_fp, -999.0f, -999.0f);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    fclose(log_fp);
    close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

