     * temperature CRC byte.  For the SDP8xx family the scale factor
     * is a fixed power-of-two value; the three bytes are the
     * exponent in the lower nibble of each byte.
     */
    int scale_factor = 0;
    for (int i = 6; i < 9; i++) {
        scale_factor |= (buf[i] & 0x0F) << ((i - 6) * 4);
    }

    /*
     * Pressure: raw * 2^scale_factor  (Pa)
     * Temperature: raw * 2^scale_factor / 200  (°C)
     */
    *pressure    = (float)raw_pressure    * (1 << scale_factor);
    *temperature = (float)raw_temperature * (1 << scale_factor) / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file open ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "wb");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s for writing\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 airflow logger started.  Press Ctrl-C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        float pressure, temperature;

        if (read_sensor(&pressure, &temperature) == 0) {
            if (fwrite(&pressure, sizeof(float), 1, g_log_file) != 1 ||
                fwrite(&temperature, sizeof(float), 1, g_log_file) != 1) {
                fprintf(stderr, "[ERROR] fwrite to log file failed\n");
                break;
            }
            fflush(g_log_file);
            printf("Pressure: %.2f Pa  |  Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

