            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Wait for conversion */
        gpioDelay(CONV_TIME_US);

        /* Read 9 bytes: 3 words × (2 data + 1 CRC) */
        char buf[9];
        int n = i2cReadDevice(g_i2c_handle, buf, sizeof(buf));
        if (n != (int)sizeof(buf)) {
            fprintf(stderr, "Warning: I2C read returned %d bytes (expected 9).\n", n);
            sleep(SAMPLE_INTERVAL_S);
            continue;
