        /* Validate CRC for each 3-byte word */
        for (int i = 0; i < 3; i++) {
            if (sdp_crc8((uint8_t *)(buf + i * 3), 2) != (uint8_t)buf[i * 3 + 2]) {
                fprintf(stderr, "Warning: CRC mismatch on word %d.\n", i);
                sleep(SAMPLE_INTERVAL_S);
                continue;
            }
        }

        /* Convert raw bytes to signed 16-bit big-endian values */
        int16_t dp_raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
        int16_t t_raw  = (int16_t)(((uint8_t)buf[3] << 8) | (uint8_t)buf[4]);

        /* --- timestamp --- */
        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        /* --- log --- */
        fprintf(g_log_file, "%s, DP: %d Pa, Temp: %d K\n", ts, dp_raw, t_raw);
        fflush(g_log_file);

        printf("%s, DP: %d Pa, Temp: %d K\n", ts, dp_raw, t_raw);

        /* --- sleep --- */
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

