#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_fan(void) {
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing PWM on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure) {
    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", bytes);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw / 100.0f;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    return pressure * 10.0f;
}

static void set_fan_speed(float flow_rate) {
    int duty = (int)((flow_rate / 100.0f) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
    }
}

static void log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

static void cleanup(void) {
