#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LPS33HW_ADDR 0x5C
#define LOG_FILE "environmental_data.txt"

/* LPS33HW register addresses */
#define LPS33HW_CTRL_REG1 0x20
#define LPS33HW_CTRL_REG2 0x21
#define LPS33HW_PRESS_OUT_XL 0x28
#define LPS33HW_TEMP_OUT_L 0x2B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, LPS33HW_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    /* CTRL_REG1: ODR=10 Hz (0x57), BDU=1, SIM=0 */
    if (i2cWriteByteData(i2c_handle, LPS33HW_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }
    /* CTRL_REG2: IF_ADD_INC=1 (0x04) */
    if (i2cWriteByteData(i2c_handle, LPS33HW_CTRL_REG2, 0x04) < 0) {
        fprintf(stderr, "Error writing CTRL_REG2\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    char buffer[5];
    int32_t raw_pressure, raw_temperature;

    if (i2cReadI2CBlockData(i2c_handle, LPS33HW_PRESS_OUT_XL, buffer, 5) != 5) {
        fprintf(stderr, "Error reading pressure/temperature data\n");
        return -1;
    }

    raw_pressure = (int32_t)((uint8_t)buffer[0])
                 | ((int32_t)((uint8_t)buffer[1]) << 8)
                 | ((int32_t)((uint8_t)buffer[2]) << 16);
    /* Sign-extend 24-bit value */
    if (raw_pressure & 0x00800000) {
        raw_pressure |= 0xFF000000;
    }

    raw_temperature = (int32_t)((uint8_t)buffer[3])
                    | ((int32_t)((uint8_t)buffer[4]) << 8);

    /* LPS33HW: pressure in hPa = raw / 4096.0 */
    *pressure = (float)raw_pressure / 4096.0f;
    /* Temperature in degrees Celsius = raw / 100.0 */
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            timestamp, pressure, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time for error log\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp for error log\n");
        return;
    }

    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        log_error("Sensor initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        log_error("Failed to set up signal handler");
        cleanup();
        return EXIT_FAILURE;
    }

    while (!terminate) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

