#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * STLM75 temperature register (0x00) returns two bytes, MSB first.
 * Resolution is 0.5 °C / LSB; the 12-bit two’s-complement value is
 * in bits 15:4 of the 16-bit word.
 */
static int read_temperature(int handle, float *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);
    raw >>= 4;                       /* keep the 12-bit value */
    *out = (float)raw * 0.5f;
    return 0;
}

int main(void)
{
    float  buffer[BUFFER_SIZE];
    int    idx = 0;
    int    handle = -1;
    int    rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        goto cleanup_gpio;
    }
    gpioWrite(GPIO_LED, 0);

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", handle);
        goto cleanup_gpio;
    }

    for (int i = 0; i < BUFFER_SIZE; i++)
        buffer[i] = 0.0f;

    while (g_running) {
        float temp;

        if (read_temperature(handle, &temp) != 0) {
            fprintf(stderr, "Skipping iteration due to read failure\n");
            time_sleep(POLL_INTERVAL);
            continue;
        }

        buffer[idx] = temp;
        idx = (idx + 1) % BUFFER_SIZE;

        float sum = 0.0f;
        for (int i = 0; i < BUFFER_SIZE; i++)
            sum += buffer[i];
        float avg = sum / (float)BUFFER_SIZE;

        gpioWrite(GPIO_LED, (avg > TEMP_THRESHOLD) ? 1 : 0);

        printf("Temperature: %.2f °C  Average: %.2f °C  LED: %s\n",
               temp, avg, (avg > TEMP_THRESHOLD) ? "ON" : "OFF");

        time_sleep(POLL_INTERVAL);
    }

    gpioWrite(GPIO_LED, 0);
    i2cClose(handle);
    rc = EXIT_SUCCESS;

cleanup_gpio:
    gpioTerminate();
    return rc;
}

