/*
 * SCD30 CO2 / Temperature / Humidity logger with ventilation control.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_logger scd30_logger.c -lpigpio -lrt
 * Run:    sudo ./scd30_logger
 *
 * Hardware: Raspberry Pi 4 Model B, SCD30 on I2C bus 1 (GPIO2=SDA, GPIO3=SCL).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SCD30_ADDR           0x61
#define LOG_FILE             "air_quality.log"
#define SAMPLE_INTERVAL_S    5
#define CO2_LOW_THRESHOLD    800
#define CO2_HIGH_THRESHOLD   1200
#define MAX_RETRIES          3
#define MEAS_DELAY_US        5000000   /* 5 s */
#define RESET_DELAY_US       2000000   /* 2 s */
#define RESET_CMD_LEN        2
#define RESET_CMD            0x30, 0x36

/* SCD30 command codes (MSB = 0x36, LSB = cmd byte) */
#define CMD_START_PERIODIC   0x00
#define CMD_STOP_PERIODIC    0x01
#define CMD_GET_DATA_READY   0x02
#define CMD_READ_MEASUREMENT 0x03
#define CMD_SOFT_RESET       0xD3

/* SCD30 data structure (12 bytes: 3 floats + 3 bytes CRC) */
typedef struct {
    float co2;
    float temperature;
    float humidity;
} scd30_data_t;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* SCD30 helpers                                                       */
/* ------------------------------------------------------------------ */
static int scd30_write_command(uint8_t msb, uint8_t lsb)
{
    uint8_t cmd[2] = { msb, lsb };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X 0x%02X) failed\n", msb, lsb);
        return -1;
    }
    return 0;
}

static int scd30_write_command_retry(uint8_t msb, uint8_t lsb)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (scd30_write_command(msb, lsb) == 0)
            return 0;
        gpioDelay(100000); /* 100 ms back-off */
    }
    fprintf(stderr, "[ERROR] scd30_write_command_retry(0x%02X 0x%02X) failed after %d retries\n",
            msb, lsb, MAX_RETRIES);
    return -1;
}

static int scd30_read_bytes(uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes, got %d\n", len, n);
        return -1;
    }
    return 0;
}

static int scd30_read_bytes_retry(uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (scd30_read_bytes(buf, len) == 0)
            return 0;
        gpioDelay(100000);
    }
    fprintf(stderr, "[ERROR] scd30_read_bytes_retry(%zu) failed after %d retries\n",
            len, MAX_RETRIES);
    return -1;
}

static int scd30_soft_reset(void)
{
    if (scd30_write_command_retry(0x36, 0x00) != 0)
        return -1;
    gpioDelay(RESET_DELAY_US);
    if (scd30_write_command_retry(0x36, 0x01) != 0)
        return -1;
    gpioDelay(RESET_DELAY_US);
    return 0;
}

static int scd30_start_periodic(void)
{
    if (scd30_write_command_retry(0x36, CMD_START_PERIODIC) != 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int scd30_stop_periodic(void)
{
    return scd30_write_command_retry(0x36, CMD_STOP_PERIODIC);
}

static int scd30_data_ready(bool *ready)
{
    if (scd30_write_command_retry(0x36, CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(10000);

    uint8_t buf[3];
    if (scd30_read_bytes_retry(buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    *ready = (word != 0);
    return 0;
}

static int scd30_read_measurement(scd30_data_t *data)
{
    if (scd30_write_command_retry(0x36, CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);

    uint8_t buf[18];
    if (scd30_read_bytes_retry(buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[WARN] CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw   = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t temp_raw  = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t hum_raw   = (uint16_t)((buf[6] << 8) | buf[7]);

    data->co2       = (float)co2_raw;
    data->temperature = (float)temp_raw / 100.0f;
    data->humidity   = (float)hum_raw  / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static void control_ventilation(float co2)
{
    if (co2 < CO2_LOW_THRESHOLD) {
        printf("[VENT] OFF  (CO2: %.0f ppm)\n", co2);
    } else if (co2 < CO2_HIGH_THRESHOLD) {
        printf("[VENT] LOW  (CO2: %.0f ppm)\n", co2);
    } else {
        printf("[VENT] HIGH (CO2: %.0f ppm)\n", co2);
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(float co2, float temp, float hum)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.0f,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd30_stop_periodic();
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD30_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Soft-reset the sensor to ensure a known state */
    if (scd30_soft_reset() != 0) {
        fprintf(stderr, "[WARN] SCD30 soft-reset failed — continuing with best-effort\n");
    }

    /* Start periodic measurement */
    if (scd30_start_periodic() != 0) {
        fprintf(stderr, "[ERROR] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] SCD30 logging started. Sampling every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        bool ready = false;
        if (scd30_data_ready(&ready) != 0) {
            fprintf(stderr, "[WARN] Data-ready check failed — skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        if (!ready) {
            fprintf(stderr, "[INFO] Data not ready yet — skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        scd30_data_t sample;
        if (scd30_read_measurement(&sample) != 0) {
            fprintf(stderr, "[WARN] Read measurement failed — skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        log_sample(sample.co2, sample.temperature, sample.humidity);
        control_ventilation(sample.co2);

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

