/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 *
 * Reads differential pressure from a Sensirion SDP32 (±125 Pa) over I2C
 * every 1000 ms (default) and prints timestamped readings to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 * Run:    ./sdp32_reader [sampling_interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SDP32_ADDR       0x22
#define CMD_CONT_MEAS    0x361F   /* continuous measurement, averaging */
#define CMD_READ_MEAS    0x0000   /* read measurement result */
#define MEAS_DELAY_MS    20       /* SDP32 conversion time */
#define READ_DELAY_MS    5        /* small settle after read */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_stop = 0;
static int g_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void on_signal(int sig)
{
    (void)sig;
    g_stop = 1;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int sdp32_start_continuous(int fd)
{
    if (i2c_write_cmd(fd, CMD_CONT_MEAS) == -1)
        return -1;
    usleep(2000);  /* first measurement takes ~1500 ms */
    return 0;
}

static int sdp32_read_measurement(int fd, float *pressure, float *temperature)
{
    if (i2c_write_cmd(fd, CMD_READ_MEAS) == -1)
        return -1;
    usleep(READ_DELAY_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, sizeof(data)) == -1)
        return -1;

    /* Verify CRC for each 3-byte word */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor    = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", ts);
    } else {
        printf("[?time?] ");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval_ms = 1000;
    if (argc > 1) {
        long v = strtol(argv[1], NULL, 10);
        if (v > 0)
            interval_ms = (int)v;
        else
            fprintf(stderr, "Invalid interval '%s'; using default %d ms\n",
                    argv[1], interval_ms);
    }

    install_signal_handlers();

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, SDP32_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP32_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    /*
     * Probe: issue a continuous-measurement command and wait briefly.
     * If the sensor NACKs or the bus hangs, the write will fail and we
     * treat it as "sensor absent".
     */
    if (sdp32_start_continuous(g_fd) == -1) {
        fprintf(stderr, "SDP32 not responding at 0x%02X on %s\n",
                SDP32_ADDR, I2C_BUS);
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started on %s (addr 0x%02X, interval %d ms)\n",
           I2C_BUS, SDP32_ADDR, interval_ms);
    fflush(stdout);

    int rc = EXIT_SUCCESS;

    while (!g_stop) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !g_stop; attempt++) {
            if (sdp32_read_measurement(g_fd, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);  /* 10 ms back-off before retry */
        }

        if (ok) {
            print_timestamp();
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            fflush(stdout);
        } else {
            print_timestamp();
            fprintf(stderr, "Read failed after %d retries; continuing\n",
                    MAX_RETRIES);
            fflush(stderr);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int ms = 0; ms < interval_ms && !g_stop; ms += 100)
            usleep(100000);
    }

    /* Graceful shutdown */
    if (g_fd >= 0) {
        /* Stop continuous measurement */
        (void)i2c_write_cmd(g_fd, 0x3FF9);
        close(g_fd);
        g_fd = -1;
    }
    printf("\nShutdown complete.\n");
    return rc;
}

