/*
 * SDP810-125Pa differential pressure & temperature reader for Raspberry Pi 4.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, pin 3)
 *   SDP810 SCL  -> GPIO3 (BCM 3, pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C bus 1, address 0x25.  Reads every second; 9-byte payload:
 *   bytes 0-1: differential pressure (signed, big-endian)
 *   bytes 2-3: differential pressure scale factor (signed, big-endian)
 *   bytes 4-5: temperature (signed, big-endian)
 *   bytes 6-7: temperature scale factor (signed, big-endian)
 *   bytes 8-9: raw status (big-endian)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x25
#define READ_CMD       0x362F   /* continuous measurement, no averaging */
#define READ_LEN       9
#define CONV_DELAY_US  45000   /* 45 ms conversion time */
#define SAMPLE_PERIOD  1       /* seconds between samples */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Returns 0 on success, -1 on I/O or CRC error.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((READ_CMD >> 8) & 0xFF),
        (uint8_t)(READ_CMD & 0xFF)
    };
    uint8_t buf[READ_LEN];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* CRC validation of each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on pressure word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on status word\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_pressure_sf = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_temperature = (int16_t)((buf[4] << 8) | buf[5]);
    int16_t raw_temp_sf     = (int16_t)((buf[6] << 8) | buf[7]);
    uint16_t status         = (uint16_t)((buf[8] << 8) | buf[9]);

    if (raw_pressure_sf == 0 || raw_temp_sf == 0) {
        fprintf(stderr, "[ERROR] Scale factor is zero (sensor absent or not configured)\n");
        return -1;
    }

    /*
     * SDP810 status bits (16-bit, big-endian):
     *   bit 15 = command mode (1 = command mode, 0 = data mode)
     *   bit 14 = data ready (1 = data ready)
     *   bit 13 = stale data (1 = stale)
     *   bit 12 = reserved
     *   bit 11 = reserved
     *   bit 10 = reserved
     *   bit 9  = reserved
     *   bit 8  = reserved
     *   bit 7  = reserved
     *   bit 6  = reserved
     *   bit 5  = reserved
     *   bit 4  = reserved
     *   bit 3  = reserved
     *   bit 2  = reserved
     *   bit 1  = reserved
     *   bit 0  = reserved
     *
     * We require bit 14 (data ready) to be set.
     */
    if ((status & 0x4000) == 0) {
        fprintf(stderr, "[WARN] Data not ready (status=0x%04X)\n", status);
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)raw_pressure_sf;
    *temperature = (float)raw_temperature / (float)raw_temp_sf;
    return 0;
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SDP810_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    printf("SDP810 reader started.  Bus %d, addr 0x%02X.  Press Ctrl-C to stop.\n",
           I2C_BUS, SDP810_ADDR);
    fflush(stdout);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp810(handle, &pressure, &temperature) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("[%s] Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   ts, pressure, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    rc = EXIT_SUCCESS;

    if (i2cClose(handle) != 0)
        fprintf(stderr, "[WARN] i2cClose failed: %s\n", strerror(errno));

cleanup_gpio:
    gpioTerminate();
    return rc;
}

