#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x40
#define CONFIG_REG     0x02
#define TEMP_REG       0x00
#define HUMID_REG      0x01
#define CONV_DELAY_MS  20
#define POLL_INTERVAL  5

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd bytes, %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_init(int fd) {
    /* Bit 12 = 1 -> 14-bit temp, 14-bit humidity; bits 11-10 = 00 -> 14-bit */
    if (i2c_write_reg8(fd, CONFIG_REG, 0x10) < 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum) {
    /* Trigger a single-shot measurement: bit 15 = 1 */
    if (i2c_write_reg8(fd, CONFIG_REG, 0x80) < 0)
        return -1;

    /* Wait for conversion to complete (>= 14-bit conversion time) */
    struct timespec ts = { 0, CONV_DELAY_MS * 1000000L };
    nanosleep(&ts, NULL);

    uint16_t raw_t, raw_h;
    if (i2c_read_reg16(fd, TEMP_REG, &raw_t) < 0)
        return -1;
    if (i2c_read_reg16(fd, HUMID_REG, &raw_h) < 0)
        return -1;

    *temp = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *hum  = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor may be absent)\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Logging every %d s.\n",
           I2C_BUS, HDC1000_ADDR, POLL_INTERVAL);

    while (g_running) {
        float temp, hum;
        if (hdc1000_read(g_fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        sleep(POLL_INTERVAL);
    }

    if (g_fd >= 0)
        close(g_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

