#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define SI7051_ADDR     0x40
#define SI7051_CMD_MEAS_TEMP_HOLD  0xE3
#define SI7051_CMD_READ_TEMP_PREV  0xE0
#define SI7051_CMD_RESET           0xFE
#define SI7051_CMD_READ_ID_1       0xFA
#define SI7051_CMD_READ_ID_2       0x0F
#define SI7051_CMD_READ_FW_REV     0x84
#define SI7051_CMD_READ_ELECT_ID   0xB8

#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES         3
#define MEAS_DELAY_MS       10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int si7051_reset(int fd) {
    if (i2c_write_cmd(fd, SI7051_CMD_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int si7051_read_id(int fd, uint8_t *id) {
    if (i2c_write_cmd(fd, SI7051_CMD_READ_ID_1) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(fd, id, 8) < 0) return -1;
    return 0;
}

static int si7051_read_fw_rev(int fd, uint8_t *rev) {
    if (i2c_write_cmd(fd, SI7051_CMD_READ_FW_REV) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(fd, rev, 1) < 0) return -1;
    return 0;
}

static int si7051_read_elect_id(int fd, uint8_t *id) {
    if (i2c_write_cmd(fd, SI7051_CMD_READ_ELECT_ID) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(fd, id, 8) < 0) return -1;
    return 0;
}

static int si7051_read_temperature(int fd, float *temp) {
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(fd, SI7051_CMD_MEAS_TEMP_HOLD) < 0) {
            retries++;
            usleep(100000);
            continue;
        }
        usleep(MEAS_DELAY_MS * 1000);

        if (i2c_write_cmd(fd, SI7051_CMD_READ_TEMP_PREV) < 0) {
            retries++;
            usleep(100000);
            continue;
        }
        usleep(10000);

        if (i2c_read_bytes(fd, buf, 2) < 0) {
            retries++;
            usleep(100000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *temp = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }

    fprintf(stderr, "Temperature read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_data(float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Temperature: %.2f C\n", ts, temp);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7051_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7051_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (si7051_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor reset failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    uint8_t id[8];
    if (si7051_read_id(g_i2c_fd, id) == 0) {
        printf("Si7051 ID: 0x%02X%02X%02X%02X%02X%02X%02X%02X\n",
               id[0], id[1], id[2], id[3], id[4], id[5], id[6], id[7]);
    }

    uint8_t fw_rev;
    if (si7051_read_fw_rev(g_i2c_fd, &fw_rev) == 0) {
        printf("Si7051 Firmware Revision: 0x%02X\n", fw_rev);
    }

    uint8_t elect_id[8];
    if (si7051_read_elect_id(g_i2c_fd, elect_id) == 0) {
        printf("Si7051 Electrical ID: 0x%02X%02X%02X%02X%02X%02X%02X%02X\n",
               elect_id[0], elect_id[1], elect_id[2], elect_id[3],
               elect_id[4], elect_id[5], elect_id[6], elect_id[7]);
    }

    printf("Starting temperature readings every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_SEC);

    while (g_running) {
        float temp;
        if (si7051_read_temperature(g_i2c_fd, &temp) == 0) {
            log_data(temp);
        } else {
            fprintf(stderr, "Sensor read failed. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

