               elect_id[4], elect_id[5], elect_id[6], elect_id[7]);
    }

    printf("Starting temperature readings every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_SEC);

    while (g_running) {
        float temp;
        if (si7051_read_temperature(g_i2c_fd, &temp) == 0) {
            log_data(temp);
        } else {
            fprintf(stderr, "Sensor read failed. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

