#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 4 Model B – MLX90833 pressure sensor reader
 *
 * Wiring:
 *   MLX90833 SDA  -> GPIO 2 (pin 3, I2C bus 1)
 *   MLX90833 SCL  -> GPIO 3 (pin 5, I2C bus 1)
 *   MLX90833 VDD  -> 3.3 V (pin 1)
 *   MLX90833 GND  -> GND  (pin 6)
 *
 * The MLX90833 is a 16-bit sensor; the driver reads 16-bit big-endian
 * data from registers 0x00 and 0x01.  The pressure value is derived
 * from the raw data by scaling and applying a calibration offset.
 */

#define I2C_BUS        1
#define I2C_ADDR       0x58          /* MLX90833 default I2C address */
#define REG_PRESSURE_H  0x00
#define REG_PRESSURE_L  0x01
#define REG_CALIB_H     0x02
#define REG_CALIB_L     0x03
#define SAMPLE_PERIOD_US 500000      /* 500 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                     */
/* ------------------------------------------------------------------ */

/*
 * Read a 16-bit big-endian register from the MLX90833.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Read the calibration coefficients from registers 0x02 and 0x03.
 * Returns 0 on success; on error the calibration values are left
 * unchanged so the caller can fall back to a default calibration.
 */
static int read_calibration(int handle, uint16_t *cal_h, uint16_t *cal_l)
{
    uint16_t h, l;

    if (read_reg16(handle, REG_CALIB_H, &h) != 0)
        return -1;
    if (read_reg16(handle, REG_CALIB_L, &l) != 0)
        return -1;

    *cal_h = h;
    *cal_l = l;
    return 0;
}

/*
 * Convert raw sensor data to absolute pressure (Pa).
 *
 * The MLX90833 provides a 16-bit signed value; the scale factor and
 * offset are derived from the calibration registers.  The exact
 * formula depends on the calibration; here we use a simplified
 * placeholder that produces a reasonable-looking pressure range.
 */
static float convert_to_pressure(uint16_t raw_h, uint16_t raw_l,
                                  uint16_t cal_h, uint16_t cal_l)
{
    /*
     * Placeholder calibration:
     *   pressure (Pa) = (raw_h << 16 | raw_l) * scale + offset
     *
     * Replace scale and offset with values obtained from the
     * MLX90833 datasheet or calibration procedure.
     */
    const float scale  = 100.0f;
    const float offset = 0.0f;

    int32_t raw = (int32_t)((uint32_t)raw_h << 16 | (uint32_t)raw_l);
    return (float)raw * scale + offset;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    uint16_t cal_h = 0, cal_l = 0;
    uint16_t raw_h = 0, raw_l = 0;
    int      rc;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Read calibration (non-fatal if read fails) --- */
    if (read_calibration(g_i2c_handle, &cal_h, &cal_l) != 0) {
        fprintf(stderr, "Warning: could not read calibration data; "
                        "using default values\n");
    } else {
        printf("Calibration: H=0x%04X L=0x%04X\n", cal_h, cal_l);
    }

    /* --- Install signal handlers --- */
    install_signal_handlers();

    /* --- Main sampling loop --- */
    while (g_running) {
        rc = read_reg16(g_i2c_handle, REG_PRESSURE_H, &raw_h);
        if (rc != 0) {
            fprintf(stderr, "Failed to read pressure high byte\n");
            break;
        }

        rc = read_reg16(g_i2c_handle, REG_PRESSURE_L, &raw_l);
        if (rc != 0) {
            fprintf(stderr, "Failed to read pressure low byte\n");
            break;
        }

        float pressure = convert_to_pressure(raw_h, raw_l, cal_h, cal_l);

        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));

        printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);   /* 500 ms */
    }

    /* --- Cleanup --- */
    cleanup();
    return EXIT_SUCCESS;
}

