    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    /* ICP-10101 returns data little-endian */
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    uint8_t id = 0;

    if (i2c_read_reg8(fd, REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read sensor ID – sensor may be absent or bus error.\n");
        return -1;
    }

    if (id != ICP10101_ID_EXPECTED) {
        fprintf(stderr,
                "Warning: sensor ID 0x%02X does not match expected 0x%02X.\n"
                "Continuing anyway – check wiring and address.\n",
                id, ICP10101_ID_EXPECTED);
        /* non-fatal: proceed with caution */
    }

    if (i2c_write_reg8(fd, REG_MEAS_CFG, MEAS_CFG_VAL) != 0) {
        fprintf(stderr, "Failed to configure measurement register.\n");
        return -1;
    }

    return 0;
}

static int read_sensor(int fd, float *temperature, float *pressure)
{
    /* Trigger a single-shot measurement */
    if (i2c_write_reg8(fd, REG_MEAS_CFG, MEAS_CFG_VAL) != 0) {
        return -1;
    }

    /* Wait for conversion to complete */
    usleep(MEAS_DELAY_MS * 1000);

    int16_t raw_t = 0, raw_p = 0;

    if (i2c_read_reg16_le(fd, REG_MEAS_VAL, &raw_t) != 0) {
        return -1;
    }
    if (i2c_read_reg16_le(fd, REG_MEAS_VAL + 2, &raw_p) != 0) {
        return -1;
    }

    /*
     * ICP-10101 conversion formulas (from datasheet):
     *   T (°C) = raw_t / 200.0
     *   P (Pa)  = raw_p / 100.0
     */
    *temperature = (float)raw_t / 200.0f;
    *pressure    = (float)raw_p / 100.0f;

    return 0;
}

static void log_data(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    }

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fd != -1) {
        close(g_fd);
        g_fd = -1;
    }
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 sensor initialized on %s (addr 0x%02X).\n", I2C_BUS, I2C_ADDR);
    printf("Reading every %d seconds. Press Ctrl+C to exit.\n", LOOP_DELAY_S);
    fflush(stdout);

    while (g_running) {
        float temperature = 0.0f, pressure = 0.0f;

        if (read_sensor(g_fd, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < LOOP_DELAY_S * 10 && g_running; i++) {
            usleep(100 * 1000);
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

