/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 B+
 * I2C bus 1 (BCM), SDA = GPIO2, SCL = GPIO3
 *
 * Build:  gcc -O2 -Wall -o sdp800_monitor sdp800_monitor.c
 * Run:    ./sdp800_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x22
#define LOG_FILE       "pressure_log.txt"
#define MEAS_DELAY_MS  45
#define SAMPLE_PERIOD  5000000   /* 5 s */

/* SDP800 command: trigger continuous measurement, no averaging */
static const uint8_t CMD_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;     /* Pa  */
    float temperature;  /* °C  */
} sensor_data_t;

/*
 * Read 9 bytes: 3 words × (2 data + 1 CRC) = 9.
 * Word layout: [MSB, LSB, CRC], each value is 16-bit two’s complement.
 */
static int read_sdp800(int fd, sensor_data_t *out)
{
    uint8_t buf[9];

    if (i2c_read(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /*
     * Conversion formulas from the SDP8xx datasheet.
     * Temperature scale factor is 20, pressure scale factor is 235.
     */
    out->temperature = (float)raw_temperature / 20.0f;
    out->pressure    = (float)raw_pressure    / 235.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(const sensor_data_t *data)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, data->pressure, data->temperature);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f\n",
                data->pressure, data->temperature);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Quick presence check: a zero-length write to the sensor address
     * should return an ACK (or NACK) rather than a sensor-absent error. */
    if (i2c_write(g_i2c_fd, NULL, 0) != 0) {
        fprintf(stderr, "SDP800 not responding at 0x%02X on %s\n",
                SDP800_ADDR, I2C_BUS);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        /* Trigger a single measurement */
        if (i2c_write(g_i2c_fd, CMD_MEAS, sizeof(CMD_MEAS)) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        usleep(MEAS_DELAY_MS * 1000);

        sensor_data_t data;
        if (read_sdp800(g_i2c_fd, &data) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        log_data(&data);
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
               data.pressure, data.temperature);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

