        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, data->pressure, data->temperature);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f\n",
                data->pressure, data->temperature);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Quick presence check: a zero-length write to the sensor address
     * should return an ACK (or NACK) rather than a sensor-absent error. */
    if (i2c_write(g_i2c_fd, NULL, 0) != 0) {
        fprintf(stderr, "SDP800 not responding at 0x%02X on %s\n",
                SDP800_ADDR, I2C_BUS);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        /* Trigger a single measurement */
        if (i2c_write(g_i2c_fd, CMD_MEAS, sizeof(CMD_MEAS)) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        usleep(MEAS_DELAY_MS * 1000);

        sensor_data_t data;
        if (read_sdp800(g_i2c_fd, &data) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        log_data(&data);
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
               data.pressure, data.temperature);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

