/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V (pin 1)
 *   SDP800 GND  -> GND  (pin 6)
 *
 * I2C address: 0x25 (Sensirion SDP800 default)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_log.csv"
#define SAMPLE_PERIOD  1000000   /* microseconds (1 s) */
#define MEAS_DELAY_US  8000      /* SDP800 measurement wait */

/* SDP800-500Pa scale factor: 1 Pa = 160 count */
#define SCALE_FACTOR   160.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 as used by Sensirion (poly 0x31, init 0xFF, no final XOR) */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/*
 * Read one differential-pressure sample from the SDP800.
 * Returns 0 on success and stores the pressure in *out_pa.
 * Returns -1 on I/O error, -2 on CRC mismatch, -3 if the file does not exist
 * (sensor absent or bus error).
 */
static int sdp800_read(int fd, float *out_pa)
{
    uint8_t cmd = 0x3615;  /* continuous measurement, mass flow / differential */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEAS_DELAY_US);

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != 3) {
        if (r < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of 3 bytes\n", r);
        return -1;
    }

    if (sdp_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on SDP800 data\n");
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_pa = (float)raw / SCALE_FACTOR;
    return 0;
}

static int log_open(const char *path, int *fd_out)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header only if the file is empty */
    if (fstat(fd, &(struct stat){0}) == 0 && st.st_size == 0) {
        if (write(fd, "Timestamp,Pressure_Pa\n", 21) != 21) {
            fprintf(stderr, "Cannot write header: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }

    *fd_out = fd;
    return 0;
}

static int log_write(int fd, float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    char line[64];
    int len = snprintf(line, sizeof(line), "%s,%.2f\n", ts, pressure);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf truncated\n");
        return -1;
    }

    ssize_t w = write(fd, line, (size_t)len);
    if (w != len) {
        fprintf(stderr, "write to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(fd) < 0)
        fprintf(stderr, "fsync warning: %s\n", strerror(errno));

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length write to confirm the device is present */
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "SDP800 not responding at 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    int log_fd = -1;
    if (log_open(LOG_FILE, &log_fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP800 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure;
        int rc = sdp800_read(fd, &pressure);

        if (rc == 0) {
            if (log_write(log_fd, pressure) < 0)
                fprintf(stderr, "Logging error; continuing.\n");
        } else if (rc == -3) {
            fprintf(stderr, "Sensor absent or bus error; retrying.\n");
        } else {
            fprintf(stderr, "Read error; retrying.\n");
        }

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    if (log_fd >= 0)
        close(log_fd);
    close(fd);
    return EXIT_SUCCESS;
}

