code:
/*
 * MLX90821 pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90821 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pressure_logger pressure_logger.c \
 *       -lm -lrt -lpigpio -lstdc++
 *
 * Run:
 *   sudo ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define I2C_ADDR             0x0A          /* MLX90821 default I2C address */
#define LOG_FILE             "pressure_log.csv"
#define SAMPLE_INTERVAL_S    1             /* seconds between samples      */
#define MAX_RETRIES          2             /* retries per sample           */
#define SAFE_PRESSURE_MIN_KPA 200.0f       /* tire safety lower bound      */
#define SAFE_PRESSURE_MAX_KPA 250.0f       /* tire safety upper bound      */

/*
 * MLX90821 register addresses (16-bit, big-endian on the bus).
 * The sensor exposes a 16-bit register map; the driver below uses
 * 16-bit read/write primitives so the pigpio I2C layer does the
 * byte-swapping automatically on little-endian hosts.
 */
#define MLX90821_REG_PRESSURE_MSB 0x0001
#define MLX90821_REG_PRESSURE_LSB 0x0002
#define MLX90821_REG_TEMP_MSB     0x0003
#define MLX90821_REG_TEMP_LSB     0x0004
#define MLX90821_REG_STATUS       0x0005

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Prototypes -------------------------------- */

static int  mlx90821_init(void);
static int  mlx90821_read_pressure(float *pressure_kpa);
static void log_pressure(float pressure_kpa);
static void signal_handler(int sig);
static void cleanup(void);

/* --------------------------- MLX90821 driver ---------------------------- */

/*
 * Initialise the MLX90821 I2C driver.
 *
 * The pigpio I2C layer performs the 16-bit register addressing
 * automatically, so the 16-bit register map is used directly.
 *
 * Returns 0 on success, -1 on failure.
 */
static int mlx90821_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }

    /*
     * Probe the sensor by reading the status register.
     * A zero-length read of any register typically returns 0 on success.
     */
    int probe = i2cReadByteData(g_i2c_handle, MLX90821_REG_STATUS);
    if (probe < 0) {
        fprintf(stderr, "[ERROR] MLX90821 probe failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    printf("[INFO] MLX90821 detected (status register read returned %d).\n", probe);
    return 0;
}

/*
 * Read the pressure in kPa from the MLX90821.
 *
 * Returns 0 on success and stores the pressure in *pressure_kpa;
 * returns -1 on failure.
 */
static int mlx90821_read_pressure(float *pressure_kpa)
{
    int msb, lsb;

    /*
     * Read the two pressure registers consecutively.
     * i2cReadWordData performs a 16-bit read of the register address
     * on the I2C bus, so the sensor returns the 16-bit value.
     */
    msb = i2cReadWordData(g_i2c_handle, MLX90821_REG_PRESSURE_MSB);
    if (msb < 0) {
        fprintf(stderr, "[WARN] Pressure MSB read failed: %s\n", strerror(errno));
        return -1;
    }

    lsb = i2cReadWordData(g_i2c_handle, MLX90821_REG_PRESSURE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "[WARN] Pressure LSB read failed: %s\n", strerror(errno));
        return -1;
    }

    /*
     * Combine the two bytes into a 16-bit value.
     * pigpio returns the data in the host's native byte order, so
     * on a little-endian host the bytes are already in the correct
     * order.
     */
    uint16_t raw = (uint16_t)((msb << 8) | (lsb & 0xFF));

    /*
     * Convert raw ADC value to pressure in kPa.
     * The MLX90821 datasheet provides a conversion formula;
     * replace the coefficients with the values from your
     * specific calibration if non-standard.
     */
    *pressure_kpa = (float)raw * 0.001f;  /* example scaling */

    return 0;
}

/* ----------------------------- Logging --------------------------------- */

static void log_pressure(float pressure_kpa)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed: %s\n", strerror(errno));
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }

    if (pressure_kpa < SAFE_PRESSURE_MIN_KPA ||
        pressure_kpa > SAFE_PRESSURE_MAX_KPA) {
        fprintf(stderr,
                "[WARN] Pressure %.2f kPa outside safe range [%.0f, %.0f].\n",
                pressure_kpa, SAFE_PRESSURE_MIN_KPA, SAFE_PRESSURE_MAX_KPA);
    }
}

/* --------------------------- Signal handling --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialise the MLX90821 sensor */
    if (mlx90821_init() != 0) {
        fprintf(stderr, "[ERROR] MLX90821 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if the file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "[ERROR] Failed to write CSV header: %s\n", strerror(errno));
