/*
 * HIH6130 Temperature & Humidity Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   HIH6130 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   HIH6130 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   HIH6130 VCC  -> 3.3 V (pin 1)
 *   HIH6130 GND  -> GND  (pin 6)
 *
 * The HIH6130 has an on-chip pull-up; no external pull-ups are required.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hih6130_logger hih6130_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define HIH6130_ADDR     0x27
#define LOG_FILE         "environmental_data.log"
#define LOG_FILE_SIZE    1048576   /* 1 MB */
#define READ_INTERVAL_S  5
#define MEASURE_DELAY_MS 40

/* HIH6130 register addresses (8-bit, no register map needed) */
#define HIH6130_REG_TEMP_H  0x00
#define HIH6130_REG_TEMP_L  0x01
#define HIH6130_REG_HUM_H   0x02
#define HIH6130_REG_HUM_L   0x03
#define HIH6130_REG_STATUS  0x04

/* Status register bit masks */
#define HIH6130_STATUS_READY 0x80
#define HIH6130_STATUS_HUM   0x20
#define HIH6130_STATUS_TEMP  0x10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file.                           */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                ts, temperature, humidity);
    } else {
        fprintf(fp, "(time-error), Temperature: %.2f C, Humidity: %.2f %%\n",
                temperature, humidity);
    }

    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Truncate the log file when it exceeds LOG_FILE_SIZE bytes.          */
/* ------------------------------------------------------------------ */
static void manage_log_size(void)
{
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        return;                       /* file does not exist yet */
    }

    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fclose(fp);

    if (sz > LOG_FILE_SIZE) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fclose(fp);
        } else {
            perror("fopen(" LOG_FILE " for truncate)");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature (°C) and humidity (%RH) from the HIH6130.           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_hih6130(int fd, float *temperature, float *humidity)
{
    uint8_t status = 0;

    /*
     * 1. Trigger a measurement by writing the command register
     *    (0x00) with a dummy byte (0x00).  The HIH6130 clocks out
     *    data on the following read.
     */
    uint8_t cmd = 0x00;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }

    /* 2. Wait for the conversion to complete (~40 ms). */
    usleep(MEASURE_DELAY_MS * 1000);

    /* 3. Read the status byte to confirm the measurement is ready. */
    if (i2c_read_reg8(fd, HIH6130_REG_STATUS, &status) != 0) {
        return -1;
    }

    if (!(status & HIH6130_STATUS_READY)) {
        fprintf(stderr, "HIH6130: measurement not ready (status=0x%02X)\n",
                status);
        return -1;
    }

    /* 4. Read temperature and humidity data. */
    uint8_t t_h, t_l, h_h, h_l;

    if (i2c_read_reg8(fd, HIH6130_REG_TEMP_H, &t_h) != 0 ||
        i2c_read_reg8(fd, HIH6130_REG_TEMP_L, &t_l) != 0 ||
        i2c_read_reg8(fd, HIH6130_REG_HUM_H,  &h_h) != 0 ||
        i2c_read_reg8(fd, HIH6130_REG_HUM_L,  &h_l) != 0) {
        return -1;
    }

    /* 5. Convert raw values. */
    int16_t raw_temp = (int16_t)((t_h << 8) | t_l);
    int16_t raw_hum  = (int16_t)((h_h << 8) | h_l);

    *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);

    /*
     * Humidity resolution is 1 %RH per LSB.  The HIH6130 reports
     * humidity only when the measurement is ready; the status bit
     * HIH6130_STATUS_HUM is set when humidity data is valid.
     */
    if (status & HIH6130_STATUS_HUM) {
        *humidity = (100.0f * (float)raw_hum / 65535.0f);
    } else {
        *humidity = 0.0f;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    /* Acquire the HIH6130 slave address. */
    if (ioctl(g_i2c_fd, I2C_SLAVE, HIH6130_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /*
     * Probe the sensor by reading the status register.
     * A NACK or short read indicates the device is absent or
     * not responding.
     */
    uint8_t probe = 0;
    if (read(g_i2c_fd, &probe, 1) != 1) {
        fprintf(stderr, "HIH6130 not detected at 0x%02X on %s\n",
                HIH6130_ADDR, I2C_BUS);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HIH6130 logger started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop. */
    while (g_running) {
        float temperature, humidity;

        if (read_hih6130(g_i2c_fd, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            manage_log_size();
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read HIH6130 data.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < READ_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown. */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

