/*
 * MLX90824 SENT pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor VCC  -> 3V3 (Pin 1)
 *   Sensor GND  -> GND (Pin 9)
 *   Sensor SDA  -> GPIO4 (Pin 7, BCM 4)
 *   Sensor SCL  -> (unused)
 *
 * SENT protocol:
 *   Tick time  = 3 µs  (3000 ns)
 *   Sync pulse = 56 ticks (1800 µs)
 *   Nibble     = 12–271 ticks (36–813 µs)
 *   Status     = nibble 0–15
 *   Data       = nibble 0–15
 *   Checksum   = nibble 0–15
 *
 * Build: gcc -O2 -Wall -o mlx90824 mlx90824.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO        4
#define TICK_US          3
#define SYNC_TICKS       56
#define MIN_NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define LOG_FILE         "pressure_log.txt"
#define READ_TIMEOUT_US  1000000   /* 1 s per-read timeout */
#define SAMPLE_PERIOD_US 1000000   /* 1 s between samples */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SENT helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Wait for the SENT line to reach the requested level, or timeout.
 * Returns 0 on success, -1 on timeout.
 */
static int sent_wait_level(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/*
 * Read one SENT nibble.  Returns 0–15 on success, -1 on timeout/error.
 */
static int sent_read_nibble(int gpio, uint32_t timeout_us)
{
    /* Sync pulse: wait for line to go LOW (start of sync) */
    if (sent_wait_level(gpio, 0, timeout_us) != 0)
        return -1;

    /* Sync pulse: measure high-time to determine tick length */
    uint32_t t0 = gpioTick();
    if (sent_wait_level(gpio, 1, timeout_us) != 0)
        return -1;
    uint32_t th = gpioTick();
    uint32_t tick_us = th - t0;

    /*
     * SENT tick time is 3 µs.  A 56-tick sync pulse is 1800 µs.
     * If the high-time is within ±20% of 1800 µs, accept it.
     */
    uint32_t expected = SYNC_TICKS * tick_us;
    if (expected < 1500 || expected > 2200)
        return -1;

    /* Data pulse: wait for line to go HIGH (end of sync + start of data) */
    if (sent_wait_level(gpio, 1, timeout_us) != 0)
        return -1;

    /* Data pulse: measure low-time to determine nibble width */
    uint32_t t1 = gpioTick();
    if (sent_wait_level(gpio, 0, timeout_us) != 0)
        return -1;
    uint32_t t2 = gpioTick();
    uint32_t width = t2 - t1;

    uint32_t nibble_ticks = width / tick_us;
    if (nibble_ticks < MIN_NIBBLE_TICKS || nibble_ticks > MAX_NIBBLE_TICKS)
        return -1;

    return (int)(nibble_ticks - MIN_NIBBLE_TICKS);
}

/*
 * Read one SENT frame.  Returns 0 on success, -1 on error.
 * On success, fills status, data[3], and checksum.
 */
static int sent_read_frame(int gpio, uint32_t timeout_us,
                           uint8_t *status, uint8_t *data, uint8_t *checksum)
{
    int n;

    n = sent_read_nibble(gpio, timeout_us);
    if (n < 0) return -1;
    *status = (uint8_t)n;

    for (int i = 0; i < 3; i++) {
        n = sent_read_nibble(gpio, timeout_us);
        if (n < 0) return -1;
        data[i] = (uint8_t)n;
    }

    n = sent_read_nibble(gpio, timeout_us);
    if (n < 0) return -1;
    *checksum = (uint8_t)n;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    } else {
        fprintf(fp, "<unknown time>, Pressure: %.2f Pa\n", pressure);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup ------------------------------------------------- */
    if (gpioSetMode(SENT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", SENT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);   /* SENT idles HIGH */

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 SENT reader started on GPIO%d.  Press Ctrl+C to exit.\n",
           SENT_GPIO);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        uint8_t status = 0, data[3] = {0}, checksum = 0;

        if (sent_read_frame(SENT_GPIO, READ_TIMEOUT_US,
                            &status, data, &checksum) == 0) {
            /*
             * Checksum: (status + d0 + d1 + d2) mod 16 == checksum
             * Nibble 0–15 are data values; nibble 15 is a special flag.
             */
            uint8_t calc = (status + data[0] + data[1] + data[2]) & 0x0F;
            if (calc != checksum) {
                fprintf(stderr,
                        "Warning: checksum mismatch (calc=%u, got=%u).\n",
                        calc, checksum);
            } else {
                /*
                 * Data[0] and Data[1] hold the 16-bit pressure value.
                 * Conversion: raw * 0.01 Pa.
                 */
                uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
                float pressure = (float)raw * 0.01f;
                log_pressure(pressure);
                printf("Pressure: %.2f Pa\n", pressure);
            }
        } else {
            fprintf(stderr, "Warning: SENT read timeout or bus error.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* --- Cleanup ---------------------------------------------------- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

