    *temperature = (float)raw_signed / 100.0f;
    return 0;
}

static int log_temperature(float temperature) {
    size_t written = fwrite(&temperature, sizeof(float), 1, log_file);
    if (written != 1) {
        fprintf(stderr, "Error writing temperature to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int verify_device_id(void) {
    int id = i2cReadWordData(i2c_handle, TMP117_REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        return -1;
    }
    uint16_t device_id = (uint16_t)id;
    if (device_id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: expected 0x%04X, got 0x%04X\n", TMP117_DEVICE_ID, device_id);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device_id() != 0) {
        fprintf(stderr, "TMP117 not detected or wrong device\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

