#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"
#define SAMPLE_INTERVAL_SEC 5

#define TMP117_REG_TEMP_RESULT 0x00
#define TMP117_REG_CONFIG 0x01
#define TMP117_REG_DEVICE_ID 0x0F

#define TMP117_DEVICE_ID 0x0117

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    int id = i2cReadByteData(i2c_handle, TMP117_REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if ((id & 0xFF) != TMP117_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", id & 0xFF, TMP117_DEVICE_ID);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    int cfg = i2cReadByteData(i2c_handle, TMP117_REG_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "Error reading config register: %d\n", cfg);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    cfg |= 0x01;
    if (i2cWriteByteData(i2c_handle, TMP117_REG_CONFIG, cfg) < 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TMP117_REG_TEMP_RESULT);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }

    int16_t val = (int16_t)raw;
    *temperature = (float)val / 10.0f;
    return 0;
}

static void buffer_init(CircularBuffer *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, time_t ts, float temp) {
    buf->readings[buf->head].timestamp = ts;
    buf->readings[buf->head].temperature = temp;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void buffer_flush(const CircularBuffer *buf, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing\n", filename);
        return;
    }

    int total = buf->count;
    int start = (buf->head - total + BUFFER_SIZE) % BUFFER_SIZE;

    for (int i = 0; i < total; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (fwrite(&buf->readings[idx], sizeof(TemperatureReading), 1, fp) != 1) {
            fprintf(stderr, "Error writing to %s\n", filename);
            fclose(fp);
            return;
        }
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s\n", filename);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&buffer);

    while (running) {
        time_t now = time(NULL);
        float temp;

        if (read_temperature(&temp) == 0) {
            buffer_add(&buffer, now, temp);
            printf("Timestamp: %ld, Temperature: %.2f C\n", (long)now, temp);
        } else {
            fprintf(stderr, "Failed to read temperature at %ld\n", (long)now);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    buffer_flush(&buffer, LOG_FILE);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

