#define CMD_WAKEUP     0x3517
#define CMD_MEASURE    0x7866  /* T-first, RH-first, clock stretching */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* CRC-8, polynomial 0x31, init 0xFF, as used by Sensirion SHTC3        */
/* ------------------------------------------------------------------ */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SHTC3                                 */
/* ------------------------------------------------------------------ */
static int shtc3_write_cmd(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for cmd 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes from the SHTC3 (T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC) */
/* ------------------------------------------------------------------ */
static int shtc3_read_measurement(int handle, float *temperature, float *humidity)
{
    uint8_t data[6];
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    /* CRC validation */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate physical ranges                                            */
/* ------------------------------------------------------------------ */
static int validate_reading(float temperature, float humidity)
{
    if (temperature < -40.0f || temperature > 125.0f) {
        fprintf(stderr, "[ERROR] Temperature out of range: %.2f °C\n", temperature);
        return -1;
    }
    if (humidity < 0.0f || humidity > 100.0f) {
        fprintf(stderr, "[ERROR] Humidity out of range: %.2f %%\n", humidity);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a valid reading to the CSV file                                 */
/* ------------------------------------------------------------------ */
static int log_reading(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s for append\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f\n", temperature, humidity);
    }

    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler — request graceful shutdown                          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put sensor back to sleep to save power */
        (void)shtc3_write_cmd(g_i2c_handle, CMD_SLEEP);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
