    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SHTC3_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- wake the sensor --- */
    if (shtc3_write_cmd(g_i2c_handle, CMD_WAKEUP) != 0) {
        fprintf(stderr, "[FATAL] SHTC3 wake-up command failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(5000);  /* 5 ms wake-up delay */

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("SHTC3 monitoring started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* --- main loop --- */
    while (g_running) {
        float temperature, humidity;

        if (shtc3_read_measurement(g_i2c_handle, &temperature, &humidity) == 0) {
            if (validate_reading(temperature, humidity) == 0) {
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n",
                       temperature, humidity);
                if (log_reading(temperature, humidity) != 0) {
                    fprintf(stderr, "[WARN] Logging failed for this sample\n");
                }
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

