#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

/*
 * Raspberry Pi 3 Model B+ - Si7202 I2C Hall-effect sensor reader
 *
 * Wiring:
 *   Si7202 SDA -> GPIO2 (pin 3)
 *   Si7202 SCL -> GPIO3 (pin 5)
 *   Si7202 VDD -> 3.3 V
 *   Si7202 GND -> GND
 *
 * I2C bus 1, address 0x40 (Si7202 default when ADDR pin tied low).
 */
#define I2C_BUS        1
#define SI7202_ADDR    0x40

/* Si7202 register addresses */
#define REG_DEVICE_ID  0x00
#define REG_SPEED      0x02
#define REG_TEMP       0x04
#define REG_CTRL       0x06

/* Expected device ID */
#define SI7202_DEVID   0x02

/*
 * Control register value:
 *   [15:12] reserved
 *   [11:10] speed range (00 = 100 Hz)
 *   [9:8]   reserved
 *   [7:6]   temperature range (00 = 14-bit)
 *   [5:4]   reserved
 *   [3:2]   conversion time (00 = 100 ms)
 *   [1:0]   reserved
 * => 0x0000
 */
#define CTRL_VALUE     0x0000

/* Sampling interval in microseconds (1 second) */
#define SAMPLE_INTERVAL_US 1000000

/* Maximum consecutive read failures before aborting */
#define MAX_CONSECUTIVE_ERRORS 10

/* Globals for signal-safe cleanup */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the Si7202                   */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                    */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int handle, float *speed, float *temperature)
{
    int16_t raw_speed, raw_temp;

    if (read_reg16(handle, REG_SPEED, &raw_speed) != 0) {
        fprintf(stderr, "Error: failed to read speed register.\n");
        return -1;
    }

    if (read_reg16(handle, REG_TEMP, &raw_temp) != 0) {
        fprintf(stderr, "Error: failed to read temperature register.\n");
        return -1;
    }

    /*
     * Si7202 speed output: 16-bit signed, LSB = 0.01220703125 Hz.
     * Temperature: 14-bit signed, LSB = 0.0625 C.
     */
    *speed       = (float)raw_speed / 100.0f;
    *temperature = (float)raw_temp  / 16.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float speed, float temperature)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, speed, temperature) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float speed, temperature;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    int devid = i2cReadByteData(g_i2c_handle, REG_DEVICE_ID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVICE_ID register.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != SI7202_DEVID) {
        fprintf(stderr, "Error: unexpected DEVICE_ID 0x%02X (expected 0x%02X).\n",
                devid, SI7202_DEVID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor: speed range 100 Hz, temp range 14-bit, 100 ms conv */
    if (i2cWriteWordData(g_i2c_handle, REG_CTRL, CTRL_VALUE) < 0) {
        fprintf(stderr, "Error: failed to write CTRL register.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_file = fopen("mag_temp_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,speed_Hz,temperature_C\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    printf("Si7202 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &speed, &temperature) == 0) {
            consecutive_errors = 0;
            if (log_data(g_log_file, speed, temperature) != 0) {
                fprintf(stderr, "Error: failed to write to log file.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: sensor read failed (%d/%d).\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);
            if (log_data(g_log_file, NAN, NAN) != 0) {
                fprintf(stderr, "Error: failed to write error row.\n");
            }
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Error: too many consecutive failures, aborting.\n");
                break;
            }
        }

        /* Sleep for the sampling interval (interruptible by signals) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

