#define I2C_BUS 1
#define I2C_ADDR 0x25
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define INITIAL_READ_DELAY_US 2000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *flow_rate, uint16_t *temperature) {
    char buffer[4];
    int result;

    result = i2cReadDevice(handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "I2C read error: expected 4 bytes, got %d\n", result);
        return -1;
    }

    /*
     * Honeywell HAF Series: 4-byte payload (no register pointer write required).
     * Byte 0: flow MSB, Byte 1: flow LSB, Byte 2: temperature MSB, Byte 3: temperature LSB
     * Flow  = (buffer[0] << 8) | buffer[1]
     * Temp  = (buffer[2] << 8) | buffer[3]
     *
     * Flow  = 14-bit signed value in bits 13:0 of the 16-bit word.
     * Temp  = 12-bit signed value in bits 11:0 of the 16-bit word.
     */
    uint16_t raw_flow = ((uint16_t)(uint8_t)buffer[0] << 8) | (uint8_t)buffer[1];
    uint16_t raw_temp = ((uint16_t)(uint8_t)buffer[2] << 8) | (uint8_t)buffer[3];

    *flow_rate = (uint16_t)(int16_t)raw_flow;
    *temperature = (uint16_t)(int16_t)raw_temp;

    return 0;
}

static void log_data(FILE *fp, uint16_t flow_rate, uint16_t temperature) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Flow Rate: %u SLPM, Temperature: %u C\n",
            timestamp, flow_rate, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting airflow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t flow_rate = 0;
        uint16_t temperature = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_sensor_data(i2c_handle, &flow_rate, &temperature) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (success) {
            log_data(log_file, flow_rate, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nCleaning up...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

