/*
 * DHT11 single-wire bit-bang reader for Raspberry Pi Zero W
 * Library API: pigpio (microsecond timing, GPIO control)
 *
 * Wiring:
 *   DHT11 VCC  -> 3V3 (pin 1)
 *   DHT11 DATA -> GPIO4 (BCM 4, physical pin 7)
 *   DHT11 GND  -> GND (pin 9)
 *
 * Build:  gcc -O2 -Wall -o dht11_bb dht11_bb.c -lpigpio -lrt
 * Run:    sudo ./dht11_bb
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO        4
#define DHT11_MAX_RETRIES 3
#define DHT11_TIMEOUT_US  2000   /* per-phase timeout (2 ms) */
#define DHT11_BIT_THRESH  50     /* >50 us high => '1', else '0' */
#define DHT11_SAMPLE_US   2      /* min sample period */
#define DHT11_READ_INTERVAL_S 2  /* DHT11 minimum 1 s between reads */
#define DHT11_START_LOW_US  18000 /* >= 18 ms start signal */
#define DHT11_RESP_LOW_US   80    /* 80 us response low */
#define DHT11_RESP_HIGH_US  80    /* 80 us response high */
#define DHT11_BIT_LOW_US    50    /* 50 us per bit start */
#define DHT11_BIT_HIGH_US   70    /* ~70 us for '1', ~26 us for '0' */

#define LOG_FILE "dht11_readings.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timing helpers                                                      */
/* ------------------------------------------------------------------ */

/* Busy-wait for a level change on the given pin. */
static int wait_level(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
