#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x44
#define MEASURE_CMD    0x2C
#define MEASURE_DELAY  20000   /* microseconds (20 ms) */
#define LOG_FILE       "sht31d_data.log"
#define MAX_RETRIES    3
#define SAMPLE_PERIOD  5       /* seconds */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF) — SHT31 datasheet                 */
/* ------------------------------------------------------------------ */
static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHT31-D                          */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int read_sht31d(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Issue measurement command */
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "[attempt %d] I2C write failed\n", attempt + 1);
            gpioDelay(10000); /* 10 ms back-off */
            continue;
        }

        gpioDelay(MEASURE_DELAY);

        /* Read 6 bytes: T_MSB, T_LSB, T_CRC, H_MSB, H_LSB, H_CRC */
        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "[attempt %d] I2C read failed\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        /* Validate CRC for temperature */
        if (sht31_crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] Temperature CRC mismatch\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        /* Validate CRC for humidity */
        if (sht31_crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] Humidity CRC mismatch\n", attempt + 1);
            gpioDelay(10000);
            continue;
        }

        /* Convert raw values to physical units */
        uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t hum_raw  = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity    = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the log file                                       */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, SHT31_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT31-D logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        float temperature, humidity;

        if (read_sht31d(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(g_log_file, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

