/*
 * ADPD105 Correlated Color Temperature Logger for Raspberry Pi Zero W
 *
 * Reads two ADPD105 photometric front-ends on I2C bus 1 (pins GPIO2/GPIO3)
 * and logs the average CCT to cct_log.csv once per second.
 *
 * Build:  gcc -O2 -Wall -Wextra -o cct_logger cct_logger.c
 * Run:    ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define ADPD105_ADDR     0x60

/* ADPD105 register addresses (16-bit, big-endian on the bus) */
#define REG_DEVID        0x0001
#define REG_MODE         0x0002
#define REG_DATA_LSB     0x0010
#define REG_DATA_MSB     0x0011

#define DEVID_EXPECTED   0x0055
#define LOG_FILE         "cct_log.csv"
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a 16-bit register address, then a 16-bit value (big-endian). */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%04X, 0x%04X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register (big-endian). */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg16: write addr 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val[2];
    if (read(fd, val, sizeof(val)) != (ssize_t)sizeof(val)) {
        fprintf(stderr, "i2c_read_reg16: read 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)val[0] << 8) | val[1];
    return 0;
}

/*
 * Convert raw sensor data to correlated color temperature (°C).
 * Returns 0 on success, -1 on invalid data.
 */
static int raw_to_cct(uint16_t raw_lsb, uint16_t raw_msb, float *cct)
{
    /*
     * ADPD105 CCT approximation (placeholder).
     * Replace with the datasheet-defined formula for your specific
     * calibration coefficients.
     */
    (void)raw_lsb;
    (void)raw_msb;
    *cct = 6500.0f;
    return 0;
}

static void log_cct(FILE *fp, float cct)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", ts, cct);
    fflush(fp);
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire both ADPD105 devices */
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADPD105_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint16_t devid = 0;
    if (i2c_read_reg16(i2c_fd, REG_DEVID, &devid) < 0) {
        fprintf(stderr, "ADPD105 not responding at 0x%02X\n", ADPD105_ADDR);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "ADPD105 DEVID mismatch: got 0x%04X, expected 0x%04X\n",
                devid, DEVID_EXPECTED);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure sensor mode (placeholder) */
    if (i2c_write_reg16(i2c_fd, REG_MODE, 0x0001) < 0) {
        fprintf(stderr, "Failed to configure ADPD105 mode\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file (append); create with header if new */
    int file_exists = (access(LOG_FILE, F_OK) == 0);
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        fprintf(fp, "Timestamp,Average_CCT\n");
        fflush(fp);
    }

    printf("Logging ADPD105 CCT to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        uint16_t raw_lsb = 0, raw_msb = 0;
        int ok = 1;

        if (i2c_read_reg16(i2c_fd, REG_DATA_LSB, &raw_lsb) < 0) {
            ok = 0;
        }
        if (ok && i2c_read_reg16(i2c_fd, REG_DATA_MSB, &raw_msb) < 0) {
            ok = 0;
        }

        if (!ok) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
        } else {
            float cct = 0.0f;
            if (raw_to_cct(raw_lsb, raw_msb, &cct) == 0) {
                log_cct(fp, cct);
                printf("CCT: %.2f °C\n", cct);
            } else {
                fprintf(stderr, "Invalid sensor data — skipping cycle\n");
            }
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

