#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x58
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/*
 * MLX90824 register map (example values — adjust for your specific
 * application if the datasheet differs).
 */
#define MLX90824_REG_PRESSURE_MSB 0x00
#define MLX90824_REG_PRESSURE_LSB 0x01
#define MLX90824_REG_TEMP_MSB     0x02
#define MLX90824_REG_TEMP_LSB     0x03
#define MLX90824_REG_STATUS       0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int read_sensor_data(int handle, float *pressure, float *temperature)
{
    int raw_pressure, raw_temperature;
    int status;

    raw_pressure = i2cReadWordData(handle, MLX90824_REG_PRESSURE_MSB);
    if (raw_pressure < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", raw_pressure);
        return -1;
    }

    raw_temperature = i2cReadWordData(handle, MLX90824_REG_TEMP_MSB);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temperature);
        return -1;
    }

    status = i2cReadByteData(handle, MLX90824_REG_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading status register: %d\n", status);
        return -1;
    }

    /*
     * Convert raw 16-bit values to physical units.
     * Adjust scale factors per the datasheet for your specific
     * MLX90824 variant.
     */
    *pressure = (float)raw_pressure / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
            timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(fp);
}

int main(void)
{
    float pressure, temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &pressure, &temperature) == 0) {
            log_data(g_log_file, pressure, temperature);
        } else {
            log_error(g_log_file, "Failed to read sensor data");
        }

        /*
         * Sleep in 1-second increments so signals are caught promptly.
         */
        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

