#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define LM75B_TEMP_REG 0x00
#define FAN_GPIO        18
#define BUFFER_SIZE     60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW  26.0
#define SAMPLE_INTERVAL_S   1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, double *out_temp) {
    int raw = i2cReadWordData(handle, LM75B_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }

    /* LM75B: 9-bit two's-complement, left-justified in 16-bit word */
    int16_t temp_raw = (int16_t)((raw & 0xFF00) >> 8);
    if (temp_raw & 0x100) {
        temp_raw |= 0xFE00;
    }

    *out_temp = (double)temp_raw * 0.125;
    return 0;
}

static void control_fan(double avg_temp) {
    static bool fan_on = false;

    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg %.2f°C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg %.2f°C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, LM75B_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    double temp_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    int   samples_filled = 0;

    while (g_running) {
        double temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            temp_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (samples_filled < BUFFER_SIZE) {
                samples_filled++;
            }

            double sum = 0.0;
            for (int i = 0; i < samples_filled; i++) {
                sum += temp_buffer[i];
            }
            double avg_temp = (samples_filled > 0) ? (sum / samples_filled) : 0.0;

            printf("Temperature: %.2f°C | Avg: %.2f°C\n", temperature, avg_temp);
            control_fan(avg_temp);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

