/*
 * Trigger a differential-pressure measurement and read 9 bytes.
 * Returns 0 on success, -1 on error.
 */
static int sdp810_read_measurement(int handle, float *pressure, float *temperature)
{
    uint8_t data[9];

    if (sdp810_send_command(handle, CMD_MEASURE_DP) != 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);   /* SDP810 needs ~45 ms after first measurement */

    if (sdp810_read_bytes(handle, data, sizeof(data)) != 0)
        return -1;

    /*
     * SDP810 9-byte frame (differential pressure, mass flow, temperature):
     *   data[0..1]  differential pressure,  MSB first
     *   data[2]     CRC-8 of bytes 0..1
     *   data[3..4]  mass flow,             MSB first
     *   data[5]     CRC-8 of bytes 3..4
     *   data[6..7]  temperature,           MSB first
     *   data[8]     CRC-8 of bytes 6..7
     */
    if (crc8_check(&data[0], 2, data[2]) != 0) {
        fprintf(stderr, "[ERROR] CRC mismatch on differential-pressure data\n");
        return -1;
    }
    if (crc8_check(&data[3], 2, data[5]) != 0) {
        fprintf(stderr, "[ERROR] CRC mismatch on mass-flow data\n");
        return -1;
    }
    if (crc8_check(&data[6], 2, data[8]) != 0) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature data\n");
        return -1;
    }

    int16_t raw_dp = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t  = (int16_t)((data[6] << 8) | data[7]);

    *pressure    = (float)raw_dp / 60.0f;   /* Pa */
    *temperature = (float)raw_t / 200.0f;   /* °C */

    return 0;
}

/* ----------------------------- Logging ---------------------------------- */

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
}

/* ------------------------------- Main ----------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signals\n");
    }

    printf("SDP810 airflow logger started.  Press Ctrl-C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp810_read_measurement(g_i2c_handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] measurement attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000);  /* 100 ms back-off */
        }

        if (ok) {
            log_data(g_log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr,
                        "[WARN] Pressure %.2f Pa exceeds threshold %.1f Pa\n",
                        pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed after %d attempts – "
                    "check wiring and I2C address 0x%02X\n",
                    MAX_RETRIES, I2C_ADDR);
        }

        /* sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    /* --- cleanup --- */
    printf("\nShutting down...\n");
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

