#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define STTS2004_REG_TEMP_H  0x00
#define STTS2004_REG_TEMP_L  0x01
#define STTS2004_REG_CTRL    0x04
#define STTS2004_CTRL_ON     0x01
#define STTS2004_CTRL_RESET  0x80

#define LED_GPIO        17
#define TEMP_HIGH       28.0f
#define TEMP_LOW        27.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int stts2004_init(int fd)
{
    if (i2c_write_reg8(fd, STTS2004_REG_CTRL, STTS2004_CTRL_RESET) < 0) {
        fprintf(stderr, "STTS2004 reset failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    if (i2c_write_reg8(fd, STTS2004_REG_CTRL, STTS2004_CTRL_ON) < 0) {
        fprintf(stderr, "STTS2004 power-on failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int stts2004_read_temp(int fd, float *temp_c)
{
    uint8_t hi, lo;
    if (i2c_read_reg8(fd, STTS2004_REG_TEMP_H, &hi) < 0)
        return -1;
    if (i2c_read_reg8(fd, STTS2004_REG_TEMP_L, &lo) < 0)
        return -1;
    int16_t raw = (int16_t)((hi << 8) | lo);
    *temp_c = (float)raw / 256.0f;
    return 0;
}

static void log_temperature(float temp_c)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] Temperature: %.2f C\n", ts, temp_c);
    fflush(stdout);
}

static void control_led(float temp_c)
{
    static bool led_on = false;
    if (temp_c > TEMP_HIGH && !led_on) {
        if (gpioWrite(LED_GPIO, 1) == 0)
            led_on = true;
        else
            fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
    } else if (temp_c < TEMP_LOW && led_on) {
        if (gpioWrite(LED_GPIO, 0) == 0)
            led_on = false;
        else
            fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", LED_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (stts2004_init(g_i2c_fd) < 0) {
        fprintf(stderr, "STTS2004 initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;
    while (g_running) {
        float temp_c;
        if (stts2004_read_temp(g_i2c_fd, &temp_c) == 0) {
            consecutive_errors = 0;
            log_temperature(temp_c);
            control_led(temp_c);
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (attempt %d): %s\n",
                    consecutive_errors, strerror(errno));
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many consecutive I2C errors, exiting.\n");
                break;
            }
        }
        sleep(1);
    }

    gpioWrite(LED_GPIO, 0);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

