/*
 * Si7021 temperature/humidity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   Si7021 SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7021_logger si7021_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./si7021_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40          /* Si7021 default I2C address */
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60            /* seconds between readings */
#define MAX_RETRIES    3
#define CONV_DELAY_US  20000         /* 20 ms conversion time */

/* Si7021 commands (no-hold / no-master mode) */
#define CMD_MEASURE_RH_NOHOLD   0xE5
#define CMD_MEASURE_TEMP_NOHOLD 0xE3
#define CMD_READ_RH_PREV        0xE0

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_file) {
        fprintf(g_log_file, "%s,%s\n", ts, msg);
        fflush(g_log_file);
    }
    printf("%s,%s\n", ts, msg);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_file) {
        fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0)
        fprintf(stderr, "i2cReadDevice(%u) failed: %d\n", len, rc);
    return rc;
}

/* ------------------------------------------------------------------ */
/* Si7021 measurement                                                  */
/* ------------------------------------------------------------------ */
/*
 * Trigger a no-hold measurement, wait for conversion, then read the
 * 2-byte result.  Returns 0 on success, -1 on failure.
 */
static int si7021_measure(int handle, uint8_t cmd, uint16_t *raw)
{
    if (i2c_write_cmd(handle, cmd) < 0)
        return -1;

    gpioDelay(CONV_DELAY_US);

    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) < 0)
        return -1;

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read temperature from the previous RH measurement (0xE0).
 * Returns 0 on success, -1 on failure.
 */
static int si7021_read_temp(int handle, uint16_t *raw)
{
    if (i2c_write_cmd(handle, CMD_READ_RH_PREV) < 0)
        return -1;

    gpioDelay(CONV_DELAY_US);

    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) < 0)
        return -1;

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversions                                                         */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Sensor presence check ------------------------------------- */
    /*
     * Issue a no-hold Read Electronic ID (0xFA 0x0F) and read 8 bytes.
     * If the transaction fails or the sensor returns all 0xFF the
     * sensor is likely absent or not responding.
     */
    uint8_t id[8];
    if (i2c_write_cmd(g_i2c_handle, 0xFA) < 0 ||
        i2c_write_cmd(g_i2c_handle, 0x0F) < 0 ||
        i2c_read_bytes(g_i2c_handle, id, sizeof(id)) < 0) {
        log_error("Si7021 not responding on I2C bus");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int all_ff = 1;
    for (int i = 0; i < 8; i++)
        if (id[i] != 0xFF) { all_ff = 0; break; }
    if (all_ff) {
        log_error("Si7021 returned all 0xFF — sensor absent or miswired");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 detected (Electronic ID: 0x%02X 0x%02X 0x%02X 0x%02X "
           "0x%02X 0x%02X 0x%02X 0x%02X)\n",
           id[0], id[1], id[2], id[3], id[4], id[5], id[6], id[7]);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t raw_rh = 0, raw_t = 0;
        int ok = 0;

        /* Measure RH first, then T from the previous RH measurement */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (si7021_measure(g_i2c_handle, CMD_MEASURE_RH_NOHOLD, &raw_rh) == 0) {
                if (si7021_read_temp(g_i2c_handle, &raw_t) == 0) {
                    ok = 1;
                    break;
                }
            }
            gpioDelay(10000); /* 10 ms back-off */
        }

        if (ok) {
            float temp = raw_to_celsius(raw_t);
            float hum  = raw_to_humidity(raw_rh);
            char line[128];
            snprintf(line, sizeof(line),
                     "temperature_c=%.2f,humidity_pct=%.2f", temp, hum);
            log_line(line);
        } else {
            log_error("Sensor read failed after retries");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    /* --- Cleanup ---------------------------------------------------- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    if (g_log_file)
        fclose(g_log_file);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

