#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x40
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC8: polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_temperature(int fd, float *temperature)
{
    uint8_t cmd = 0x78; /* STS40 continuous measurement command */
    uint8_t buf[3];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing trigger command: %s\n", strerror(errno));
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error reading temperature data (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *temperature = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static int log_temperature(FILE *fp, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            if (log_temperature(g_log_fp, temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            usleep(100 * 1000);
        }
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0) {
            fprintf(stderr, "Error closing I2C device: %s\n", strerror(errno));
        }
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

