        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0 || init_log() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    float pressure, temperature;

    while (!terminate) {
        if (read_sdp810(&pressure, &temperature) == 0) {
            log_sample(pressure, temperature);
        } else {
            log_error("I2C or CRC read failure");
        }
        time_sleep(SAMPLE_PERIOD);
    }

