/*
 * SCD40 CO2 Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   SCD40 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * I2C bus: /dev/i2c-1, address 0x62
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_logger scd40_logger.c \
 *       -lpigpio -lrt -lpthread
 *
 * Run:
 *   sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR        0x62
#define SCD40_CMD_START_PERIODIC 0x21B1
#define SCD40_CMD_STOP_PERIODIC  0x3F86
#define SCD40_CMD_READ_MEASUREMENT 0xEC05
#define SCD40_CMD_GET_DATA_READY   0xE4B8
#define SCD40_CMD_GET_SERIAL       0x3682

#define BUFFER_SIZE 100
#define LOG_DIR     "/var/log/scd40_data"
#define ERROR_LOG   "/var/log/scd40_error.log"

#define I2C_BUS 1

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
    time_t   timestamp;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static circular_buffer_t g_buffer;
static pthread_t g_logging_thread;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t scd40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Error logging ---- */
static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (!fp) {
        perror("fopen(error_log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(int handle, uint8_t *buf, size_t len) {
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

/* ---- SCD40 command with CRC ---- */
static int scd40_send_command(int handle, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        log_error("I2C write failed for command");
        return -1;
    }
    return 0;
}

/* ---- SCD40 data read ---- */
static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temperature, float *humidity) {
    uint8_t buf[9];

    if (i2c_read_data(handle, buf, sizeof(buf)) != 0)
        return -1;

    if (scd40_crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (scd40_crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (scd40_crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    *co2         = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t h_raw = (uint16_t)((buf[6] << 8) | buf[7]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *cb) {
    cb->head = cb->tail = cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_push(circular_buffer_t *cb, sensor_data_t d) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE)
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    else
        cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static int buffer_pop(circular_buffer_t *cb, sensor_data_t *out) {
    int rc = -1;
    pthread_mutex_lock(&cb->mutex);
    if (cb->count > 0) {
        *out = cb->data[cb->tail];
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
        cb->count--;
        rc = 0;
    }
    pthread_mutex_unlock(&cb->mutex);
    return rc;
}

static int buffer_count(const circular_buffer_t *cb) {
    int c;
    pthread_mutex_lock(&cb->mutex);
    c = cb->count;
    pthread_mutex_unlock(&cb->mutex);
    return c;
}

/* ---- CSV logging thread ---- */
static void *logging_thread(void *arg) {
    (void)arg;
    while (g_running) {
        sleep(60);
        if (!g_running) break;

        int cnt = buffer_count(&g_buffer);
        if (cnt == 0) continue;

        char filename[256];
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d.csv",
                 LOG_DIR,
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open CSV file for writing");
            continue;
        }
        fprintf(fp, "CO2_ppm,Temperature_C,Humidity_RH,Timestamp\n");

        sensor_data_t d;
        while (buffer_pop(&g_buffer, &d) == 0) {
            struct tm tm_local;
            localtime_r(&d.timestamp, &tm_local);
            fprintf(fp, "%u,%.2f,%.2f,%04d-%02d-%02d %02d:%02d:%02d\n",
                    d.co2, d.temperature, d.humidity,
                    tm_local.tm_year + 1900, tm_local.tm_mon + 1, tm_local.tm_mday,
                    tm_local.tm_hour, tm_local.tm_min, tm_local.tm_sec);
        }

        fclose(fp);
    }
    return NULL;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        scd40_send_command(g_i2c_handle, SCD40_CMD_STOP_PERIODIC);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    pthread_join(g_logging_thread, NULL);
    pthread_mutex_destroy(&g_buffer.mutex);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (mkdir(LOG_DIR, 0755) == -1 && errno != EEXIST) {
        log_error("Failed to create log directory");
        cleanup();
        return EXIT_FAILURE;
    }

    if (pthread_create(&g_logging_thread, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return EXIT_FAILURE;
    }

    if (scd40_send_command(g_i2c_handle, SCD40_CMD_START_PERIODIC) != 0) {
        log_error("Failed to start periodic measurement");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready ~5 s after start */
    sleep(5);

    while (g_running) {
        uint16_t co2;
        float temperature, humidity;

        if (scd40_read_measurement(g_i2c_handle, &co2, &temperature, &humidity) == 0) {
            sensor_data_t d;
            d.co2         = co2;
            d.temperature = temperature;
            d.humidity    = humidity;
            d.timestamp   = time(NULL);
            buffer_push(&g_buffer, d);
        }

        /* SCD40 measurement interval is 5 s */
        sleep(5);
    }

    cleanup();
    return EXIT_SUCCESS;
}

