#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x64
#define TRIGGER_CMD    0x20
#define READ_LEN       4
#define SAMPLE_PERIOD  5
#define TRIGGER_DELAY  10000   /* microseconds */
#define LOG_FILE       "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

static int read_sensor(int handle, float *pressure, float *temperature)
{
    char buf[READ_LEN];
    int rc;

    rc = i2cWriteByte(handle, TRIGGER_CMD);
    if (rc < 0) {
        fprintf(stderr, "Error: trigger write failed (rc=%d)\n", rc);
        return -1;
    }

    gpioDelay(TRIGGER_DELAY);

    rc = i2cReadDevice(handle, buf, READ_LEN);
    if (rc != READ_LEN) {
        fprintf(stderr, "Error: read returned %d bytes (expected %d)\n", rc, READ_LEN);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buf[0] << 24) |
                   ((uint32_t)(uint8_t)buf[1] << 16) |
                   ((uint32_t)(uint8_t)buf[2] << 8)  |
                   ((uint32_t)(uint8_t)buf[3]);

    /*
     * ICP-10110 24-bit conversion (datasheet):
     *   P = (raw / 2^24) * 1000  [Pa]
     *   T = (raw / 2^24) * 100   [°C]
     *   raw is a 24-bit signed value in two's complement.
     */
    int32_t signed_raw = (int32_t)raw;
    if (signed_raw & 0x00800000)
        signed_raw |= 0xFF000000;

    *pressure    = (float)signed_raw / 16777216.0f * 1000.0f;
    *temperature = (float)signed_raw / 16777216.0f * 100.0f;

    return 0;
}

int main(void)
{
    int handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", handle);
        goto cleanup_gpio;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
        goto cleanup_i2c;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (g_running) {
        float pressure, temperature;

        if (read_sensor(handle, &pressure, &temperature) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                    ts, pressure, temperature);
            fflush(fp);

            printf("%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                   ts, pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    rc = EXIT_SUCCESS;

    fclose(fp);
cleanup_i2c:
    i2cClose(handle);
cleanup_gpio:
    gpioTerminate();
    return rc;
}

