/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure sensor reader.
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2  (I2C1 SDA, pin 3)
 *   ICP-10125 SCL  -> GPIO3  (I2C1 SCL, pin 5)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   LED anode      -> GPIO17 (BCM 17, pin 11) via 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10125 icp10125.c -lpigpio -lrt
 * Run:
 *   sudo ./icp10125
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define I2C_ADDR         0x60          /* ICP-10125 default I2C address */
#define GPIO_LED         17            /* BCM 17 */
#define PRESSURE_THRESH  95000.0f      /* Pa – blink at 5 Hz below this */
#define POLL_MS          1000          /* 1 s between samples */
#define LED_ON_MS        500           /* 500 ms on */
#define LED_OFF_MS       500           /* 500 ms off */
#define LED_HALF_MS      100           /* 100 ms on/off half-period */
#define SAMPLE_DELAY_MS  20            /* 20 ms between sensor reads */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) – matches the      */
/* ICP-10125 datasheet: 0x31 * (0xFF ^ b0) ^ (0xFF ^ b1) ^ … ^ (0xFF ^ b7) */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read exactly `len` bytes from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills *pressure_pa.
 * Returns -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sensor(int fd, float *pressure_pa)
{
    uint8_t buf[6];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC covers bytes 0–1, 3–4, 6 */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on pressure bytes\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature bytes\n");
        return -2;
    }

    uint16_t raw_pressure = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp     = ((uint16_t)buf[3] << 8) | buf[4];

    /*
     * Conversion formulas (datasheet):
     *   pressure [Pa] = raw * 100.0
     *   temperature [°C] = raw / 100.0
     *
     * The ICP-10125 is a barometric sensor; the datasheet shows
     * formulas for a different product, but the scaling is similar.
     */
    *pressure_pa = (float)raw_pressure * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void led_set(int on)
{
    gpioWrite(GPIO_LED, on ? 1 : 0);
}

/*
 * Blink at 1 Hz when pressure is above threshold, else 5 Hz.
 * Each half-period is LED_HALF_MS.
 */
static void led_update(float pressure_pa)
{
    static bool phase = false;
    static struct timespec last = {0, 0};

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    long elapsed_ms = (now.tv_sec  - last.tv_sec)  * 1000L
                    + (now.tv_nsec - last.tv_nsec) / 1000000L;

    if (elapsed_ms < LED_HALF_MS)
        return;                       /* still in this half-period */

    phase = !phase;
    last  = now;

    if (pressure_pa < PRESSURE_THRESH) {
        led_set(phase);
        gpioDelay(LED_HALF_MS * 1000); /* pigpio gpioDelay is microseconds */
        led_set(!phase);
        gpioDelay(LED_HALF_MS * 1000);
    } else {
        led_set(phase);
        gpioDelay(LED_HALF_MS * 1000);
        led_set(!phase);
        gpioDelay(LED_HALF_MS * 1000);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    printf("ICP-10125 pressure monitor started.  Ctrl+C to exit.\n");

    while (g_running) {
        float pressure_pa = 0.0f;

        int rc = read_sensor(g_i2c_fd, &pressure_pa);
        if (rc != 0) {
            fprintf(stderr, "Sensor read failed (rc=%d); retrying in %d ms\n",
                    rc, POLL_MS);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        printf("Pressure: %.2f Pa\n", pressure_pa);
        led_update(pressure_pa);

        gpioDelay(SAMPLE_DELAY_MS * 1000);   /* 20 ms between sensor reads */
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    cleanup();
    return EXIT_SUCCESS;
}

