#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5B
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *ambient, float *object) {
    char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int rc = i2cReadDevice(handle, buf, 3);
        if (rc == 3) {
            int16_t raw_amb = (buf[0] << 8) | buf[1];
            int16_t raw_obj = (buf[2] << 8) | buf[3];
            *ambient = (float)raw_amb * 0.02f - 273.15f;
            *object  = (float)raw_obj  * 0.02f - 273.15f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", ts, ambient, object);
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (T=%.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (T=%.2f C)\n", object_temp);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90614 monitoring started. Logging to %s every 2 s.\n", LOG_FILE);

    while (running) {
        float ambient, object;
        if (read_temperature(i2c_handle, &ambient, &object) == 0) {
            log_temperature(ambient, object);
            control_fan(object);
        } else {
            fprintf(stderr, "Temperature read failed after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

