#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x40
#define SHT40_CMD_MEASURE 0x2C
#define SHT40_MEASURE_DELAY_US 10000
#define SHT40_READ_LEN 6
#define HTTP_PORT 8080
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(float *temperature, float *humidity) {
    unsigned char cmd = SHT40_CMD_MEASURE;
    unsigned char data[SHT40_READ_LEN];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(SHT40_MEASURE_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)data, SHT40_READ_LEN) != SHT40_READ_LEN) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        unsigned int t_ticks = ((unsigned int)data[0] << 8) | data[1];
        unsigned int h_ticks = ((unsigned int)data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)t_ticks / 65535.0f;
        *humidity = 100.0f * (float)h_ticks / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "SHT40 read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void send_all(int fd, const char *buf, size_t len) {
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, buf + sent, len - sent, 0);
        if (n <= 0) {
            if (errno == EINTR) continue;
            perror("send");
            break;
        }
        sent += (size_t)n;
    }
}

static void handle_client(int client_fd) {
    float temperature, humidity;

    if (read_sht40(&temperature, &humidity) != 0) {
        const char *err = "HTTP/1.1 500 Internal Server Error\r\n"
                          "Content-Type: text/html\r\n"
                          "Connection: close\r\n"
                          "\r\n"
                          "<html><body><h1>Sensor Error</h1></body></html>";
        send_all(client_fd, err, strlen(err));
        close(client_fd);
        return;
    }

    char body[256];
    snprintf(body, sizeof(body),
             "<html><body><h1>Temperature: %.2f &deg;C</h1>"
             "<h1>Humidity: %.2f %%</h1></body></html>",
             temperature, humidity);

    char header[512];
    int hlen = snprintf(header, sizeof(header),
                        "HTTP/1.1 200 OK\r\n"
                        "Content-Type: text/html\r\n"
                        "Content-Length: %zu\r\n"
                        "Connection: close\r\n"
                        "\r\n",
                        strlen(body));

    send_all(client_fd, header, (size_t)hlen);
    send_all(client_fd, body, strlen(body));
    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HTTP server listening on port %d\n", HTTP_PORT);

    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        int cfd = accept(server_fd, (struct sockaddr *)&caddr, &clen);
        if (cfd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        handle_client(cfd);
    }

    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

