#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x48
#define CSV_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5.0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read temperature from TMP102.
 * Returns 0 on success and stores Celsius in *out_temp;
 * returns -1 on any I2C or conversion error.
 */
static int read_temperature(int handle, float *out_temp)
{
    /*
     * TMP102 default register pointer (0x00) returns the
     * two-byte temperature result in the current resolution
     * (default 12-bit, 0.0625 °C / LSB).
     */
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed (errno=%d: %s)\n",
                errno, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 4) |
                            ((uint16_t)(uint8_t)buf[1] >> 4));

    /* Sign-extend 12-bit value to 16-bit */
    if (raw & 0x0800) {
        raw |= 0xF000;
    }

    *out_temp = (float)raw * 0.0625f;
    return 0;
}

static int log_temperature(float temperature)
{
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s (errno=%d: %s)\n",
                CSV_FILE, errno, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed (errno=%d: %s)\n",
                errno, strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error: fprintf() failed (errno=%d: %s)\n",
                errno, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose() failed (errno=%d: %s)\n",
                errno, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed (errno=%d: %s)\n",
                errno, strerror(errno));
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to TMP102 */
    int handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, TMP102_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP102 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping log entry\n");
        }

        /*
         * Sleep in 100 ms increments so SIGINT is caught promptly.
         * gpioDelay is non-blocking to other signals, but we still
         * check g_running so the loop exits promptly.
         */
        for (int i = 0; i < (int)(SAMPLE_PERIOD * 10.0) && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    if (i2cClose(handle) != 0) {
        fprintf(stderr, "Warning: i2cClose() failed (errno=%d: %s)\n",
                errno, strerror(errno));
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

