/*
 * HDC2010 Temperature & Humidity Sensor Reader
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: TI HDC2010 at address 0x40
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -lpigpio -lrt
 * Run:    sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HDC2010 constants (per TI datasheet) ---- */
#define HDC2010_ADDR             0x40
#define HDC2010_REG_TEMP         0x00
#define HDC2010_REG_HUMID        0x02
#define HDC2010_REG_MEAS_CFG     0x0F
#define HDC2010_REG_INT_CFG      0x0B
#define HDC2010_REG_INT_DR       0x0C

#define HDC2010_MEAS_TRIG        0x01   /* bit 0: start single measurement */
#define HDC2010_MEAS_RDY_BIT     0x01   /* bit 0 of MEAS_CFG is RDY */

#define POLL_TIMEOUT_MS          500
#define POLL_DELAY_US            2000
#define SAMPLE_INTERVAL_S        5
#define MAX_RETRIES              3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; returns 0 on success, -1 error */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register; returns 0 on success, -1 error */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success, -1 error */
static int reg16_read(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[1] << 8 | (uint8_t)buf[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single measurement and wait for completion.
 * Returns 0 on success, -1 on error, -2 on timeout. */
static int trigger_and_wait(int handle)
{
    if (reg_write(handle, HDC2010_REG_MEAS_CFG, HDC2010_MEAS_TRIG) != 0)
        return -1;

    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 5) {
        if (!g_running)
            return -1;

        uint8_t cfg;
        if (reg_read(handle, HDC2010_REG_MEAS_CFG, &cfg) != 0)
            return -1;

        if ((cfg & HDC2010_MEAS_RDY_BIT) == 0)
            return 0;

        gpioDelay(5000); /* 5 ms */
    }

    fprintf(stderr, "[ERROR] HDC2010 measurement-ready timeout (%d ms)\n",
            POLL_TIMEOUT_MS);
    return -2;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *temperature, float *humidity)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (!g_running)
            return -1;

        int rc = trigger_and_wait(handle);
        if (rc == 0)
            break;

        if (rc == -2)
            return -1;

        if (attempt < MAX_RETRIES) {
            fprintf(stderr, "[WARN] Attempt %d/%d failed; retrying in 1 s...\n",
                    attempt, MAX_RETRIES);
            sleep(1);
        }
    }

    uint16_t raw_t, raw_h;
    if (reg16_read(handle, HDC2010_REG_TEMP, &raw_t) != 0)
        return -1;
    if (reg16_read(handle, HDC2010_REG_HUMID, &raw_h) != 0)
        return -1;

    /* Per TI HDC2010 datasheet:
     *   T(°C) = raw / 65536 * 165 - 40
     *   RH(%) = raw / 65536 * 100
     */
    *temperature = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_h / 65536.0f) * 100.0f;

    /* Sanity-range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[WARN] Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[WARN] Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at HDC2010 address ---- */
    g_i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with a dummy read ---- */
    uint8_t dummy;
    if (reg_read(g_i2c_handle, HDC2010_REG_TEMP, &dummy) != 0) {
        fprintf(stderr, "[ERROR] No HDC2010 detected at 0x%02X (NAK/bus error)\n",
                HDC2010_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialized on I2C bus 1 at 0x%02X.\n", HDC2010_ADDR);
    printf("Sampling every %d s. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_S);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature, humidity;
        int rc = read_sensor(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            printf("Temperature: %.2f °C  |  Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; ++i)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

