/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *temperature, float *humidity)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (!g_running)
            return -1;

        int rc = trigger_and_wait(handle);
        if (rc == 0)
            break;

        if (rc == -2)
            return -1;

        if (attempt < MAX_RETRIES) {
            fprintf(stderr, "[WARN] Attempt %d/%d failed; retrying in 1 s...\n",
                    attempt, MAX_RETRIES);
            sleep(1);
        }
    }

    uint16_t raw_t, raw_h;
    if (reg16_read(handle, HDC2010_REG_TEMP, &raw_t) != 0)
        return -1;
    if (reg16_read(handle, HDC2010_REG_HUMID, &raw_h) != 0)
        return -1;

    /* Per TI HDC2010 datasheet:
     *   T(°C) = raw / 65536 * 165 - 40
     *   RH(%) = raw / 65536 * 100
     */
    *temperature = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_h / 65536.0f) * 100.0f;

    /* Sanity-range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[WARN] Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[WARN] Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at HDC2010 address ---- */
    g_i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence with a dummy read ---- */
    uint8_t dummy;
    if (reg_read(g_i2c_handle, HDC2010_REG_TEMP, &dummy) != 0) {
        fprintf(stderr, "[ERROR] No HDC2010 detected at 0x%02X (NAK/bus error)\n",
                HDC2010_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialized on I2C bus 1 at 0x%02X.\n", HDC2010_ADDR);
    printf("Sampling every %d s. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_S);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature, humidity;
        int rc = read_sensor(g_i2c_handle, &temperature, &humidity);

        if (rc == 0) {
            printf("Temperature: %.2f °C  |  Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; ++i)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

