/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   SDP800 VDD  -> Pi 3.3 V (Pin 1)
 *   SDP800 GND  -> Pi GND  (Pin 9)
 *   SDP800 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SDP800 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp800_reader sdp800_reader.c \
 *       -lgpiod -lrt
 *
 * Run:
 *   ./sdp800_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SDP800_I2C_ADDR      0x22          /* Sensirion SDP800 default address */
#define MEASURE_CMD          0x361F        /* Continuous measurement, mass flow */
#define MEASURE_DELAY_MS     45            /* Datasheet: max 45 ms */
#define LOOP_DELAY_MS        500           /* Sampling interval */
#define READ_LEN             6             /* 2 pressure + 1 CRC + 2 temp + 1 CRC */

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handler ---------------------------- */

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- CRC-8 (Sensirion) -------------------------- */

/*
 * CRC-8 polynomial: 0x31, initial value: 0xFF, no final XOR.
 * Used by Sensirion for all I2C applications.
 */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- I2C helpers -------------------------------- */

/*
 * Write a 16-bit command to the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(0x%04X) failed: %s (wrote %zd bytes)\n",
                cmd, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read exactly `len` bytes from the SDP800.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_read_data(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (got %zu of %zu bytes)\n",
                    total, len);
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* --------------------------- Sensor read -------------------------------- */

/*
 * Trigger a measurement and read the 6-byte result.
 * Returns 0 on success, -1 on error.
 */
static int sdp800_read(int fd, int16_t *pressure, int16_t *temperature)
{
    if (sdp800_write_cmd(fd, MEASURE_CMD) != 0)
        return -1;

    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t raw[READ_LEN];
    if (sdp800_read_data(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRCs */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc 0x%02X, got 0x%02X)\n",
                crc8(&raw[0], 2), raw[2]);
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "Temperature CRC mismatch (calc 0x%02X, got 0x%02X)\n",
                crc8(&raw[3], 2), raw[5]);
        return -1;
    }

    *pressure    = (int16_t)((raw[0] << 8) | raw[1]);
    *temperature = (int16_t)((raw[3] << 8) | raw[4]);
    return 0;
}

/* --------------------------- Main --------------------------------------- */

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the SDP800 slave address */
    if (ioctl(fd, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Main sampling loop */
    while (g_running) {
        int16_t pressure = 0, temperature = 0;

        if (sdp800_read(fd, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C\n",
                   pressure, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < LOOP_DELAY_MS / 100 && g_running; i++)
            usleep(100 * 1000);
    }

    /* Clean shutdown */
    if (close(fd) != 0)
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

