code:
/*
 * PID Reflow Oven Controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX6675 Thermocouple Amplifier on SPI0 (CE0)
 *   - Solid-State Relay on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o reflow_oven reflow_oven.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./reflow_oven
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM 8)  */
#define SPI_SPEED        1000000    /* 1 MHz              */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define SSR_GPIO         17         /* BCM 17 */

#define PID_PERIOD_US    1000000    /* 1 second in microseconds */
#define LOOP_DELAY_US    100000     /* 100 ms between readings   */

#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Function Prototypes -------------------------- */

static int  read_max6675(double *temperature);
static void set_ssr_duty(double duty);
static void log_data(double temperature);
static void load_profile(const char *filename, double *profile, int *count);
static double calculate_pid(double setpoint, double actual,
                            double *integral, double *prev_error,
                            double Kp, double Ki, double Kd,
                            double dt, double period);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MAX6675 ---------------------------------- */

/*
 * Read temperature from the MAX6675.
 *
 * Returns 0 on success and stores the temperature in *temperature.
 * Returns -1 on SPI bus error (sensor absent or bus fault).
 */
static int read_max6675(double *temperature)
{
    char rx[4] = {0, 0, 0, 0};
    int  ret;

    /*
     * MAX6675 SPI read: send 4 dummy bytes, the last 2 contain
     * the 14-bit thermocouple temperature (MSB first).
     */
    ret = spiXfer(g_spi_handle, rx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /*
     * rx[0] and rx[1] are valid data; rx[2] and rx[3] are a
     * 14-bit temperature plus a fault bit.
     */
    unsigned int raw = ((unsigned char)rx[0] << 8) | (unsigned char)rx[1];

    if (raw & 0x00000400) {
        /* Fault bit set — sensor absent or bus error */
        fprintf(stderr, "MAX6675 fault detected (raw=0x%04X)\n", raw);
        return -1;
    }

    /*
     * Thermocouple temperature is bits 31..18 of the 32-bit word.
     * Resolution is 0.25 °C / count.
     */
    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25;

    return 0;
}

/* ------------------------------- SSR Control ------------------------------ */

static void set_ssr_duty(double duty)
{
    if (duty < 0.0) duty = 0.0;
    if (duty > 1.0) duty = 1.0;

    unsigned int pwm_value = (unsigned int)(duty * 1000000.0); /* 0–1,000,000 */

    /*
     * pigpio hardware PWM on GPIO17: 1,000,000 range, 1 MHz clock.
     * gpioPWM sets the duty cycle in microseconds.
     */
    if (gpioPWM(SSR_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", SSR_GPIO);
    }
}

/* ------------------------------- Logging ---------------------------------- */

static void log_data(double temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f\n", ts, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    fflush(g_log_file);
}

/* ------------------------------- Profile ---------------------------------- */

static void load_profile(const char *filename, double *profile, int *count)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s — using default profile\n", filename);
        *count = 1;
        profile[0] = 250.0;
        return;
    }

    *count = 0;
    char line[256];

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0')
            continue;

        if (*count >= (int)sizeof(profile) / sizeof(profile[0])) {
            fprintf(stderr, "Profile too long — truncated\n");
            break;
        }

        if (sscanf(line, "%lf", &profile[*count]) != 1) {
            fprintf(stderr, "Invalid profile line: %s", line);
            continue;
        }
        (*count)++;
    }

    fclose(fp);
}

/* ------------------------------- PID -------------------------------------- */

static double calculate_pid(double setpoint, double actual,
                            double *integral, double *prev_error,
                            double Kp, double Ki, double Kd,
                            double dt, double period)
{
    double error = setpoint - actual;

    /* Integral term */
    *integral += error * dt;

    /* Derivative term */
    double derivative = (error - *prev_error) / dt;

    /* Clamp integral to prevent windup */
    if (*integral > period) *integral = period;
    if (*integral < -period) *integral = -period;

    double output = Kp * error + Ki * (*integral) + Kd * derivative;

    *prev_error = error;

    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

/* ------------------------------- Signal Handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */

static void cleanup(void)
{
    /* Turn off SSR */
    if (g_spi_handle >= 0) {
        set_ssr_duty(0.0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure SSR GPIO as output */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SSR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure SSR is off at startup */
    set_ssr_duty(0.0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,temperature_c\n");
        fflush(g_log_file);
    }

    /* Load temperature profile */
    double profile[100];
    int    profile_count = 0;
    load_profile(PROFILE_FILE, profile, &profile_count);

    if (profile_count == 0) {
        fprintf(stderr, "No profile data loaded — using default 250 °C\n");
        profile[0] = 250.0;
        profile_count = 1;
    }

    /* PID parameters */
    double Kp = 1.0, Ki = 0.1, Kd = 0.01;

    /* PID state */
    double integral    = 0.0;
    double prev_error  = 0.0;

    /* Timing */
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Reflow oven started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (g_running) {
        double temperature = 0.0;

        if (read_max6675(&temperature) != 0) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        /* Calculate PID output over the PID period */
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - start.tv_sec) +
                         (now.tv_nsec - start.tv_nsec) / 1e9;

        if (elapsed >= profile[0]) {
            /* Time to advance profile index */
            int idx = (int)(elapsed / profile[0]);
            if (idx >= profile_count) idx = profile_count - 1;

            double setpoint = profile[idx];
            double pid_output = calculate_pid(setpoint, temperature,
                                              &integral, &prev_error,
                                              Kp, Ki, Kd,
                                              PID_PERIOD_US / 1e6,
                                              profile[0]);

            set_ssr_duty(pid_output);

            /* Advance start time to the next profile step */
            double next_step = (idx + 1) * profile[0];
            start.tv_sec  += (time_t)(next_step);
            start.tv_nsec += (long)((next_step - (time_t)next_step) * 1e9);
            if (start.tv_nsec >= 1e9) {
                start.tv_sec  += 1;
                start.tv_nsec -= 1e9;
            }
        }

        log_data(temperature);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

