/*
 * greenhouse_heater.c — PID-controlled greenhouse heater for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_heater greenhouse_heater.c
 *
 * Hardware:
 *   - DS18B20 temperature sensor on 1-wire bus (w1-gpio module)
 *     Data line  -> GPIO4  (physical pin 7)
 *   - Relay module (active-high)
 *     IN  -> GPIO17 (physical pin 11)
 *     VCC -> 5 V
 *     GND -> GND
 *   - Hardware PWM via pigpio
 *     GPIO18 (physical pin 12) -> PWM0 (channel 0)
 *
 * Usage:
 *   ./greenhouse_heater <setpoint_C> <Kp> <Ki> <Kd>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define DS18B20_DIR        "/sys/bus/w1/devices/"
#define DS18B20_PREFIX     "28-"
#define DS18B20_DATA_FILE  "w1_slave"
#define DS18B20_DATA_LEN   512
#define PWM_FREQ_HZ        1000
#define PWM_RANGE          1000
#define LOG_FILE           "greenhouse.log"
#define SAMPLE_INTERVAL_S  5
#define MAX_SENSORS        4

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* DS18B20 temperature reading                                         */
/* ------------------------------------------------------------------ */
/*
 * Reads the DS18B20 temperature file and returns the temperature in
 * Celsius, or NAN on error.  The CRC is validated.
 */
static float read_temperature(void)
{
    char dirpath[256];
    char data[DS18B20_DATA_LEN];
    int  fd = -1;
    float temperature = NAN;

    /* Find the first DS18B20 sensor directory */
    int found = 0;
    for (int i = 0; i < MAX_SENSORS; i++) {
        snprintf(dirpath, sizeof(dirpath), "%s%s%d",
                 DS18B20_DIR, DS18B20_PREFIX, i);

        struct stat st;
        if (stat(dirpath, &st) != 0) {
            if (errno == ENOENT)
                continue;
            fprintf(stderr, "stat(%s): %s\n", dirpath, strerror(errno));
            return NAN;
        }
        if (!S_ISDIR(st.st_mode))
            continue;

        char data_path[300];
        snprintf(data_path, sizeof(data_path), "%s/%s",
                 dirpath, DS18B20_DATA_FILE);

        fd = open(data_path, O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "open(%s): %s\n", data_path, strerror(errno));
            return NAN;
        }

        ssize_t n = read(fd, data, sizeof(data) - 1);
        if (n < 0) {
            fprintf(stderr, "read(%s): %s\n", data_path, strerror(errno));
            close(fd);
            return NAN;
        }
        data[n] = '\0';

        /* DS18B20 data file starts with "YES" or "NO" */
        if (strstr(data, "YES") == NULL) {
            fprintf(stderr, "DS18B20 CRC check failed (%s)\n", data);
            close(fd);
            return NAN;
        }

        /* Extract the temperature value from the data file */
        char *t = strstr(data, "t=");
        if (t == NULL) {
            fprintf(stderr, "Temperature token not found in %s\n", data);
            close(fd);
            return NAN;
        }

        temperature = strtof(t + 2, NULL);
        temperature /= 1000.0f;

        close(fd);
        found = 1;
        break;
    }

    if (!found) {
        fprintf(stderr, "No DS18B20 sensor found in %s\n", DS18B20_DIR);
        return NAN;
    }

    return temperature;
}

/* ------------------------------------------------------------------ */
/* PID controller                                                       */
/* ------------------------------------------------------------------ */
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float prev_error;
} PIDController;

static void pid_init(PIDController *pid, float Kp, float Ki, float Kd)
{
    pid->Kp = Kp;
    pid->Ki = Ki;
    pid->Kd = Kd;
    pid->integral = 0.0f;
    pid->prev_error = 0.0f;
}

static float pid_compute(PIDController *pid, float setpoint, float actual)
{
    float error = setpoint - actual;

    /* Integral term with anti-windup clamping */
    pid->integral += error;
    if (pid->integral > 1000.0f)  pid->integral = 1000.0f;
    if (pid->integral < -1000.0f) pid->integral = -1000.0f;

    float derivative = error - pid->prev_error;
    pid->prev_error = error;

    return pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
}

/* ------------------------------------------------------------------ */
/* Heater control                                                      */
/* ------------------------------------------------------------------ */
static void heater_off(void)
{
    gpioWrite(17, 0);
}

static void heater_on(void)
{
    gpioWrite(17, 1);
}

static void set_pwm(int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int pwm_value = (duty_percent * PWM_RANGE) / 100;
    gpioPWM(18, pwm_value);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float setpoint,
                     float pid_output, int pwm_duty)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log, "%s,%.2f,%.2f,%.2f,%d\n",
            ts, temperature, setpoint, pid_output, pwm_duty);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    heater_off();
    set_pwm(0);

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 5) {
        fprintf(stderr,
                "Usage: %s <setpoint_C> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float setpoint = strtof(argv[1], NULL);
    float Kp = strtof(argv[2], NULL);
    float Ki = strtof(argv[3], NULL);
    float Kd = strtof(argv[4], NULL);

    if (setpoint <= 0.0f || setpoint > 100.0f) {
        fprintf(stderr, "Invalid setpoint: %.2f (must be 0-100 C)\n", setpoint);
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    heater_off();

    /* Configure PWM GPIO */
    if (gpioSetMode(18, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(18, PWM_FREQ_HZ);
    gpioSetPWMrange(18, PWM_RANGE);
    set_pwm(0);

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log, 0, SEEK_END);
    if (ftell(g_log) == 0)
        fprintf(g_log, "timestamp,temperature_C,setpoint_C,pid_output,pwm_duty\n");

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    PIDController pid;
    pid_init(&pid, Kp, Ki, Kd);

    printf("Greenhouse heater started.  Setpoint=%.2f C  Kp=%.2f Ki=%.2f Kd=%.2f\n",
           setpoint, Kp, Ki, Kd);
    printf("Logging to '%s' every %d s.  Press Ctrl-C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature = read_temperature();

        if (isnan(temperature)) {
            fprintf(stderr, "Sensor read error — heater off, PWM 0%%\n");
            heater_off();
            set_pwm(0);
        } else {
            float pid_output = pid_compute(&pid, setpoint, temperature);

            int pwm_duty = (int)pid_output;
            if (pwm_duty < 0)       pwm_duty = 0;
            if (pwm_duty > 100)     pwm_duty = 100;

            if (pwm_duty > 0)
                heater_on();
            else
                heater_off();

            set_pwm(pwm_duty);
            log_data(temperature, setpoint, pid_output, pwm_duty);

            printf("T=%.2f C  setpoint=%.2f C  PID=%.2f%%  heater=%s  PWM=%d%%\n",
                   temperature, setpoint, pid_output,
                   pwm_duty > 0 ? "ON" : "OFF", pwm_duty);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

