#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5
#define MAX_RETRIES     3
#define RETRY_DELAY_US  10000
#define MEASURE_DELAY_US 80000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n <= 0) return -1;
        total += n;
    }
    return 0;
}

static int read_aht20(int fd, float *humidity) {
    uint8_t buf[6];
    int retries = MAX_RETRIES;

    while (retries-- > 0) {
        if (i2c_write_cmd(fd, 0xAC) < 0) { usleep(RETRY_DELAY_US); continue; }
        usleep(MEASURE_DELAY_US);
        if (i2c_read_bytes(fd, buf, 6) < 0) { usleep(RETRY_DELAY_US); continue; }

        if (buf[0] & 0x80) {
            fprintf(stderr, "AHT20 status error: 0x%02X\n", buf[0]);
            return -1;
        }
        if (buf[0] & 0x08) {
            fprintf(stderr, "AHT20 busy\n");
            usleep(RETRY_DELAY_US);
            continue;
        }

        uint32_t raw = ((uint32_t)buf[1] << 12) |
                       ((uint32_t)buf[2] << 4) |
                       ((uint32_t)buf[3] >> 4);
        *humidity = ((float)raw / 1048576.0f) * 100.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;
        return 0;
    }
    return -1;
}

static void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(line, "aht20_dehum", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int dehum_state = 0;

    while (running) {
        float humidity;
        if (read_aht20(i2c_fd, &humidity) == 0) {
            log_data(humidity);
            if (humidity > HUMIDITY_HIGH && !dehum_state) {
                gpiod_line_set_value(line, 1);
                dehum_state = 1;
                printf("Dehumidifier ON\n");
            } else if (humidity < HUMIDITY_LOW && dehum_state) {
                gpiod_line_set_value(line, 0);
                dehum_state = 0;
                printf("Dehumidifier OFF\n");
            }
        } else {
            fprintf(stderr, "Failed to read AHT20 after %d retries\n", MAX_RETRIES);
        }
        for (int i = 0; i < POLL_INTERVAL && running; i++)
            sleep(1);
    }

    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

