#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60

#define CMD_TEMP_HOLD 0xE3
#define CMD_HUMID_HOLD 0xE5
#define CMD_SOFT_RESET 0xFE

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_reset(int fd) {
    if (i2c_write_byte(fd, CMD_SOFT_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int htu21d_read_temperature(int fd, float *temp) {
    if (i2c_write_byte(fd, CMD_TEMP_HOLD) < 0) return -1;
    usleep(50000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;

    uint32_t raw = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    raw &= 0xFFFC;
    *temp = -46.85 + 175.72 * (float)raw / 65536.0;
    return 0;
}

static int htu21d_read_humidity(int fd, float *humidity) {
    if (i2c_write_byte(fd, CMD_HUMID_HOLD) < 0) return -1;
    usleep(50000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;

    uint32_t raw = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    raw &= 0xFFFC;
    *humidity = -6.0 + 125.0 * (float)raw / 65536.0;
    return 0;
}

static int send_http_post(const char *json_data) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(API_ENDPOINT, "80", &hints, &res) != 0) {
        syslog(LOG_ERR, "getaddrinfo failed: %s", strerror(errno));
        return -1;
    }

    int sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        freeaddrinfo(res);
        return -1;
    }

    if (connect(sockfd, res->ai_addr, res->ai_addrlen) < 0) {
        syslog(LOG_ERR, "Connect failed: %s", strerror(errno));
        close(sockfd);
        freeaddrinfo(res);
        return -1;
    }

    freeaddrinfo(res);

    char request[1024];
    int req_len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s", strlen(json_data), json_data);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request formatting failed");
        close(sockfd);
        return -1;
    }

    if (write(sockfd, request, req_len) != req_len) {
        syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[1024];
    ssize_t bytes = read(sockfd, response, sizeof(response) - 1);
    if (bytes < 0) {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[bytes] = '\0';

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP server returned non-200 status");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    if (htu21d_reset(i2c_fd) < 0) {
        syslog(LOG_ERR, "HTU21D reset failed");
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity monitor started");

    while (running) {
        float humidity;
        if (htu21d_read_humidity(i2c_fd, &humidity) < 0) {
            syslog(LOG_ERR, "Failed to read humidity from HTU21D");
        } else {
            char json_data[128];
            int json_len = snprintf(json_data, sizeof(json_data),
                "{\"humidity\": %.2f}", humidity);
            if (json_len < 0 || (size_t)json_len >= sizeof(json_data)) {
                syslog(LOG_ERR, "JSON formatting failed");
            } else {
                if (send_http_post(json_data) < 0) {
                    syslog(LOG_ERR, "Failed to send HTTP POST");
                } else {
                    syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Humidity monitor shutting down");
    close(i2c_fd);
    closelog();
    return 0;
}

