#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_RESET_REG 0xE0
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CHIP_ID 0x58
#define LOG_FILE "pressure_log.txt"
#define I2C_BUS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_US 100000
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int bmp280_init(void) {
    i2c_handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, BMP280_I2C_ADDR, i2c_handle);
        return -1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_CHIP_ID_REG);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_RESET_REG, 0xB6) < 0) {
        fprintf(stderr, "Error resetting BMP280\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    gpioDelay(2000);

    if (i2cWriteByteData(i2c_handle, BMP280_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_PRESS_MSB_REG, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1 = ((double)raw_temperature / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temperature / 131072.0 - (double)dig_T1 / 8192.0) *
                  ((double)raw_temperature / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    double t_fine = var1 + var2;
    return t_fine / 5120.0;
}

static double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1 = (t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)dig_P4 * 65536.0);
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;

    if (var1 == 0.0) {
        return 0.0;
    }

    double p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;

    return p / 100.0;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f hPa\n", s, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (bmp280_init() != 0) {
        gpioTerminate();
        return 1;
    }

    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

    dig_T1 = i2cReadByteData(i2c_handle, 0x88);
    dig_T2 = i2cReadByteData(i2c_handle, 0x8A);
    dig_T3 = i2cReadByteData(i2c_handle, 0x8C);
    dig_P1 = i2cReadByteData(i2c_handle, 0x8E);
    dig_P2 = i2cReadByteData(i2c_handle, 0x90);
    dig_P3 = i2cReadByteData(i2c_handle, 0x92);
    dig_P4 = i2cReadByteData(i2c_handle, 0x94);
    dig_P5 = i2cReadByteData(i2c_handle, 0x96);
    dig_P6 = i2cReadByteData(i2c_handle, 0x98);
    dig_P7 = i2cReadByteData(i2c_handle, 0x9A);
    dig_P8 = i2cReadByteData(i2c_handle, 0x9C);
    dig_P9 = i2cReadByteData(i2c_handle, 0x9E);

    if (dig_T1 < 0 || dig_T2 < 0 || dig_T3 < 0 || dig_P1 < 0 || dig_P2 < 0 || dig_P3 < 0 ||
        dig_P4 < 0 || dig_P5 < 0 || dig_P6 < 0 || dig_P7 < 0 || dig_P8 < 0 || dig_P9 < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        int retry = 0;

        while (retry < RETRY_COUNT && !terminate) {
            if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) == 0) {
                break;
            }
            retry++;
            gpioDelay(RETRY_DELAY_US);
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor after %d retries. Re-initializing...\n", RETRY_COUNT);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(RETRY_DELAY_US);

            if (bmp280_init() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }

            dig_T1 = i2cReadByteData(i2c_handle, 0x88);
            dig_T2 = i2cReadByteData(i2c_handle, 0x8A);
            dig_T3 = i2cReadByteData(i2c_handle, 0x8C);
            dig_P1 = i2cReadByteData(i2c_handle, 0x8E);
            dig_P2 = i2cReadByteData(i2c_handle, 0x90);
            dig_P3 = i2cReadByteData(i2c_handle, 0x92);
            dig_P4 = i2cReadByteData(i2c_handle, 0x94);
            dig_P5 = i2cReadByteData(i2c_handle, 0x96);
            dig_P6 = i2cReadByteData(i2c_handle, 0x98);
            dig_P7 = i2cReadByteData(i2c_handle, 0x9A);
            dig_P8 = i2cReadByteData(i2c_handle, 0x9C);
            dig_P9 = i2cReadByteData(i2c_handle, 0x9E);

            if (dig_T1 < 0 || dig_T2 < 0 || dig_T3 < 0 || dig_P1 < 0 || dig_P2 < 0 || dig_P3 < 0 ||
                dig_P4 < 0 || dig_P5 < 0 || dig_P6 < 0 || dig_P7 < 0 || dig_P8 < 0 || dig_P9 < 0) {
                fprintf(stderr, "Error reading calibration data after re-initialization. Exiting.\n");
                break;
            }

            continue;
        }

        double t_fine = bmp280_compensate_temperature(raw_temperature);
        double pressure = bmp280_compensate_pressure(raw_pressure, t_fine);

        if (pressure > 1020.0 || pressure < 980.0) {
            log_pressure(pressure);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

