/*
 * Raspberry Pi 4B – TMP117 temperature, AHT20 humidity, PIR motion logger.
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 *
 * Wiring:
 *   TMP117  I2C  addr 0x4C  on /dev/i2c-1
 *   AHT20   I2C  addr 0x38  on /dev/i2c-1
 *   PIR     GPIO17 (gpiochip4 line 17), active-high
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define TMP117_ADDR      0x4C
#define AHT20_ADDR       0x38
#define PIR_GPIO_CHIP    "gpiochip4"
#define PIR_GPIO_LINE    17

#define LOG_FILE_NAME    "sensor_data.csv"
#define SAMPLE_INTERVAL  1          /* seconds between samples */
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

/* TMP117 registers (datasheet) */
#define TMP117_REG_TEMP_RESULT  0x00
#define TMP117_REG_CONFIG       0x01
#define TMP117_REG_DEVICE_ID    0x0F
#define TMP117_DEVICE_ID        0x0117

/* AHT20 commands (datasheet) */
#define AHT20_CMD_INIT          0xBE
#define AHT20_CMD_MEASURE       0xAC
#define AHT20_CMD_SOFT_RESET    0xBA

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------ I2C helpers ------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- TMP117 driver ----------------------------- */
static int tmp117_init(int fd)
{
    uint8_t id;
    if (i2c_read_bytes(fd, TMP117_REG_DEVICE_ID, &id, 1) != 0)
        return -1;
    if ((id & 0xFF) != TMP117_DEVICE_ID) {
        fprintf(stderr, "TMP117 not detected (Device ID = 0x%02X, expected 0x%02X)\n",
                id & 0xFF, TMP117_DEVICE_ID);
        return -1;
    }
    /* Config: 1 Hz continuous conversion, 16-bit resolution */
    if (i2c_write_byte(fd, TMP117_REG_CONFIG, 0x0100) != 0)
        return -1;
    return 0;
}

static int tmp117_read_temp(int fd, float *temp_c)
{
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_bytes(fd, TMP117_REG_TEMP_RESULT, buf, 2) == 0) {
            int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
            *temp_c = (float)raw / 128.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------- AHT20 driver ---------------------------- */
static int aht20_init(int fd)
{
    uint8_t buf[3];
    if (i2c_read_bytes(fd, 0x00, buf, 3) != 0)
        return -1;
    if ((buf[0] & 0x18) != 0x08) {   /* busy bit */
        fprintf(stderr, "AHT20 not ready (status=0x%02X%02X%02X)\n",
                buf[0], buf[1], buf[2]);
        return -1;
    }
    return 0;
}

static int aht20_soft_reset(int fd)
{
    return i2c_write_byte(fd, AHT20_CMD_SOFT_RESET, 0x08);
}

static int aht20_read(int fd, float *humidity, float *temp_c)
{
    if (i2c_write_byte(fd, AHT20_CMD_INIT, 0x08) != 0)
        return -1;
    usleep(20000);  /* 20 ms measurement wait */

    uint8_t buf[7];
    if (i2c_read_bytes(fd, AHT20_CMD_MEASURE, buf, 7) != 0)
        return -1;

    uint32_t hum_raw = ((uint32_t)buf[1] << 12) |
                       ((uint32_t)buf[2] << 4)  |
                       ((uint32_t)buf[3] >> 4);
    uint32_t temp_raw = ((uint32_t)(buf[3] & 0x0F) << 16) |
                        ((uint32_t)buf[4] << 8)  |
                        (uint32_t)buf[5];

    *humidity    = (float)hum_raw  / 1048576.0f;
    *temp_c      = (float)temp_raw / 1048576.0f * 200.0f - 50.0f;
    return 0;
}

/* ------------------------------- PIR driver ------------------------------ */
static int pir_init(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (gpiod_line_request_input(line, "pir-logger") < 0) {
        fprintf(stderr, "Failed to request PIR GPIO line: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int pir_read(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read PIR GPIO: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------- Logging --------------------------------- */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

static int open_log_file(const char *filename, bool *new_file)
{
    FILE *fp = fopen(filename, "r");
    if (fp) {
        fclose(fp);
        *new_file = false;
    } else {
        *new_file = true;
    }

    fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }
    return fileno(fp);
}

static int write_header_if_new(int fd)
{
    off_t pos = lseek(fd, 0, SEEK_END);
    if (pos < 0) {
        fprintf(stderr, "lseek failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        const char *header = "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n";
        if (write(fd, header, strlen(header)) != (ssize_t)strlen(header)) {
            fprintf(stderr, "Failed to write CSV header: %s\n",
                    strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int log_data(int fd, float temp_c, float humidity, int motion)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    char line[128];
    int len = snprintf(line, sizeof(line), "%s,%.2f,%.2f,%d\n",
                       ts, temp_c, humidity, motion);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "Log line truncated/error\n");
        return -1;
    }

    if (write(fd, line, (size_t)len) != (ssize_t)len) {
        fprintf(stderr, "Failed to write log entry: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    int  tmp117_fd = -1, aht20_fd = -1;
    FILE *log_fp   = NULL;
    char  log_path[256];
    bool  new_file = false;

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir  = NULL;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    tmp117_fd = open(I2C_BUS, O_RDWR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(tmp117_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set TMP117 slave 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        goto cleanup;
    }
    if (tmp117_init(tmp117_fd) != 0) {
        fprintf(stderr, "TMP117 init failed – sensor may be absent\n");
    }

    aht20_fd = open(I2C_BUS, O_RDWR);
    if (aht20_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(aht20_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set AHT20 slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }
    if (aht20_init(aht20_fd) != 0) {
        fprintf(stderr, "AHT20 init failed – sensor may be absent\n");
    }

    /* Open PIR GPIO */
    chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", PIR_GPIO_CHIP,
                strerror(errno));
        goto cleanup;
    }
    pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }
    if (pir_init(chip, pir) != 0)
        goto cleanup;

    /* Build log path */
    snprintf(log_path, sizeof(log_path), "%s.%04d%02d%02d",
             LOG_FILE_NAME,
             (int)time(NULL) / 86400,
             (int)time(NULL) / 3600 % 24,
             (int)time(NULL) / 60 % 60);

    /* Open log file */
    int log_fd = open_log_file(log_path, &new_file);
    if (log_fd < 0)
        goto cleanup;

    if (new_file) {
        if (write_header_if_new(log_fd) != 0)
            goto cleanup;
    }

    printf("Logging to %s every %d s. Press Ctrl-C to stop.\n",
           log_path, SAMPLE_INTERVAL);

    /* Main sampling loop */
    while (g_running) {
        float temp_c = 0.0f, humidity = 0.0f;
        int   motion  = -1;
        bool  ok      = true;

        if (tmp117_fd >= 0) {
            if (tmp117_read_temp(tmp117_fd, &temp_c) != 0)
                ok = false;
        }

        if (aht20_fd >= 0) {
            if (aht20_soft_reset(aht20_fd) != 0) {
                fprintf(stderr, "AHT20 soft reset failed\n");
                ok = false;
            } else if (aht20_read(aht20_fd, &humidity, &temp_c) != 0) {
                fprintf(stderr, "AHT20 read failed\n");
                ok = false;
            }
        }

        if (pir) {
            motion = pir_read(pir);
            if (motion < 0)
                ok = false;
        }

        if (ok) {
            if (log_data(log_fd, temp_c, humidity, motion) != 0)
                fprintf(stderr, "Log write failed\n");
        } else {
            fprintf(stderr, "Sensor read error – skipping sample\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    printf("\nShutting down...\n");
    if (log_fp)  fclose(log_fp);
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0)  close(aht20_fd);
    if (pir)           gpiod_line_release(pir);
    if (chip)          gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

