        fprintf(stderr, "lseek failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        const char *header = "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n";
        if (write(fd, header, strlen(header)) != (ssize_t)strlen(header)) {
            fprintf(stderr, "Failed to write CSV header: %s\n",
                    strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int log_data(int fd, float temp_c, float humidity, int motion)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    char line[128];
    int len = snprintf(line, sizeof(line), "%s,%.2f,%.2f,%d\n",
                       ts, temp_c, humidity, motion);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "Log line truncated/error\n");
        return -1;
    }

    if (write(fd, line, (size_t)len) != (ssize_t)len) {
        fprintf(stderr, "Failed to write log entry: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    int  tmp117_fd = -1, aht20_fd = -1;
    FILE *log_fp   = NULL;
    char  log_path[256];
    bool  new_file = false;

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir  = NULL;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    tmp117_fd = open(I2C_BUS, O_RDWR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(tmp117_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Cannot set TMP117 slave 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        goto cleanup;
    }
    if (tmp117_init(tmp117_fd) != 0) {
        fprintf(stderr, "TMP117 init failed – sensor may be absent\n");
    }

    aht20_fd = open(I2C_BUS, O_RDWR);
    if (aht20_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }
    if (ioctl(aht20_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set AHT20 slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }
    if (aht20_init(aht20_fd) != 0) {
        fprintf(stderr, "AHT20 init failed – sensor may be absent\n");
    }

    /* Open PIR GPIO */
    chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", PIR_GPIO_CHIP,
                strerror(errno));
        goto cleanup;
    }
    pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }
    if (pir_init(chip, pir) != 0)
        goto cleanup;

    /* Build log path */
    snprintf(log_path, sizeof(log_path), "%s.%04d%02d%02d",
             LOG_FILE_NAME,
             (int)time(NULL) / 86400,
             (int)time(NULL) / 3600 % 24,
             (int)time(NULL) / 60 % 60);

    /* Open log file */
    int log_fd = open_log_file(log_path, &new_file);
    if (log_fd < 0)
        goto cleanup;

    if (new_file) {
        if (write_header_if_new(log_fd) != 0)
            goto cleanup;
    }

    printf("Logging to %s every %d s. Press Ctrl-C to stop.\n",
           log_path, SAMPLE_INTERVAL);

    /* Main sampling loop */
    while (g_running) {
        float temp_c = 0.0f, humidity = 0.0f;
        int   motion  = -1;
        bool  ok      = true;

        if (tmp117_fd >= 0) {
            if (tmp117_read_temp(tmp117_fd, &temp_c) != 0)
                ok = false;
        }

        if (aht20_fd >= 0) {
            if (aht20_soft_reset(aht20_fd) != 0) {
                fprintf(stderr, "AHT20 soft reset failed\n");
                ok = false;
            } else if (aht20_read(aht20_fd, &humidity, &temp_c) != 0) {
                fprintf(stderr, "AHT20 read failed\n");
                ok = false;
            }
        }

        if (pir) {
            motion = pir_read(pir);
            if (motion < 0)
                ok = false;
        }

        if (ok) {
            if (log_data(log_fd, temp_c, humidity, motion) != 0)
                fprintf(stderr, "Log write failed\n");
        } else {
            fprintf(stderr, "Sensor read error – skipping sample\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    printf("\nShutting down...\n");
    if (log_fp)  fclose(log_fp);
    if (tmp117_fd >= 0) close(tmp117_fd);
    if (aht20_fd >= 0)  close(aht20_fd);
    if (pir)           gpiod_line_release(pir);
    if (chip)          gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

