#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN  22
#define MOTOR_IN1_PIN  23
#define MOTOR_IN2_PIN  24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC     5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];
    if (localtime_r(&now, &tm_buf)) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    int rc = 0;
    if (gpiod_line_set_value(ena, 0) < 0) { rc = -1; log_event("ERROR: ena stop failed"); }
    if (gpiod_line_set_value(in1, 0) < 0) { rc = -1; log_event("ERROR: in1 stop failed"); }
    if (gpiod_line_set_value(in2, 0) < 0) { rc = -1; log_event("ERROR: in2 stop failed"); }
    return rc;
}

static int motor_forward(struct gpiod_line *ena, struct gpiod_line *in1,
                         struct gpiod_line *in2)
{
    int rc = 0;
    if (gpiod_line_set_value(ena, 1) < 0) { rc = -1; log_event("ERROR: ena set failed"); }
    if (gpiod_line_set_value(in1, 1) < 0) { rc = -1; log_event("ERROR: in1 set failed"); }
    if (gpiod_line_set_value(in2, 0) < 0) { rc = -1; log_event("ERROR: in2 clear failed"); }
    return rc;
}

static void cleanup_motor(struct gpiod_line *ena, struct gpiod_line *in1,
                          struct gpiod_line *in2)
{
    (void)motor_stop(ena, in1, in2);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain)");
        goto cleanup;
    }
    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        perror("gpiod_line_request_output(ena)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2)");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started (GPIO17, L298N ENA22/IN123).");

    while (g_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            log_event("ERROR: failed to read rain sensor");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {
            log_event("Rain detected! Closing window...");

            if (motor_forward(ena_line, in1_line, in2_line) < 0) {
                log_event("ERROR: motor forward failed");
            } else {
                for (int i = 0; i < MOTOR_RUN_SEC && g_running; i++) {
                    sleep(1);
                }
                if (motor_stop(ena_line, in1_line, in2_line) < 0) {
                    log_event("ERROR: motor stop failed");
                } else {
                    log_event("Window closed.");
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    log_event("Shutting down...");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup_motor(ena_line, in1_line, in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (ena_line)  gpiod_line_release(ena_line);
    if (in1_line)  gpiod_line_release(in1_line);
    if (in2_line)  gpiod_line_release(in2_line);
    if (chip)     gpiod_chip_close(chip);
    return ret;
}

