#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_DRIVER_PATH "/lib/modules/pwmchip0/pwmchip0.ko"
#define PWM_CHIP_DIR "/sys/class/pwm/pwmchip0"
#define PWM_EXPORT_PATH PWM_CHIP_DIR "/export"
#define PWM_UNEXPORT_PATH PWM_CHIP_DIR "/unexport"
#define PWM_PERIOD_PATH PWM_CHIP_DIR "/pwm0/period"
#define PWM_DUTY_CYCLE_PATH_FMT PWM_CHIP_DIR "/pwm0/duty_cycle%d"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_file(const char *path, char *buf, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, size - 1);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    return 0;
}

static int pwm_export(void) {
    if (write_file(PWM_EXPORT_PATH, "0") != 0) {
        return -1;
    }
    usleep(100000);
    return 0;
}

static int pwm_unexport(void) {
    return write_file(PWM_UNEXPORT_PATH, "0");
}

static int pwm_set_period(unsigned int period_ns) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%u", period_ns);
    return write_file(PWM_PERIOD_PATH, buf);
}

static int pwm_set_duty_cycle(unsigned int channel, unsigned int duty_cycle_ns) {
    char path[128];
    snprintf(path, sizeof(path), PWM_DUTY_CYCLE_PATH_FMT, channel);
    char buf[32];
    snprintf(buf, sizeof(buf), "%u", duty_cycle_ns);
    return write_file(path, buf);
}

static int pwm_init(void) {
    if (pwm_export() != 0) {
        return -1;
    }
    if (pwm_set_period(1000000) != 0) {
        pwm_unexport();
        return -1;
    }
    return 0;
}

static void pwm_set_color(unsigned char r, unsigned char g, unsigned char b) {
    unsigned int period = 1000000;
    unsigned int on_time = (period * 255) / 1000;
    unsigned int off_time = period - on_time;

    if (r > 0) {
        pwm_set_duty_cycle(0, on_time);
    } else {
        pwm_set_duty_cycle(0, off_time);
    }
    if (g > 0) {
        pwm_set_duty_cycle(1, on_time);
    } else {
        pwm_set_duty_cycle(1, off_time);
    }
    if (b > 0) {
        pwm_set_duty_cycle(2, on_time);
    } else {
        pwm_set_duty_cycle(2, off_time);
    }
}

static void pwm_off(void) {
    pwm_set_color(0, 0, 0);
}

static void pwm_cleanup(void) {
    pwm_off();
    pwm_unexport();
}

static float calculate_cpu_load(const char *prev_stat, const char *curr_stat) {
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long long curr_user, curr_nice, curr_system, curr_idle, curr_iowait, curr_irq, curr_softirq, curr_steal, curr_guest, curr_guest_nice;

    if (sscanf(prev_stat, "%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        return 0.0f;
    }

    if (sscanf(curr_stat, "%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &curr_user, &curr_nice, &curr_system, &curr_idle, &curr_iowait, &curr_irq, &curr_softirq, &curr_steal, &curr_guest, &curr_guest_nice) != 10) {
        return 0.0f;
    }

    unsigned long long prev_idle_total = prev_idle + prev_iowait;
    unsigned long long curr_idle_total = curr_idle + curr_iowait;

    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal;
    unsigned long long curr_non_idle = curr_user + curr_nice + curr_system + curr_irq + curr_softirq + curr_steal;

    unsigned long long prev_total = prev_idle_total + prev_non_idle;
    unsigned long long curr_total = curr_idle_total + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle_total - prev_idle_total;

    if (totald == 0) {
        return 0.0f;
    }

    float cpu_usage = (float)(totald - idled) / (float)totald;
    return cpu_usage * 100.0f;
}

static void map_cpu_load_to_color(float cpu_load, unsigned char *r, unsigned char *g, unsigned char *b) {
    if (cpu_load < 0.0f) cpu_load = 0.0f;
    if (cpu_load > 100.0f) cpu_load = 100.0f;

    if (cpu_load < 50.0f) {
        *r = 0;
        *g = (unsigned char)(cpu_load * 2.0f);
        *b = 0;
    } else {
        *r = (unsigned char)((cpu_load - 50.0f) * 2.0f);
        *g = 255;
        *b = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (pwm_init() != 0) {
        fprintf(stderr, "Failed to initialize PWM. Ensure pwmchip0 is loaded and you have permission.\n");
        return 1;
    }

    char prev_stat[256];
    char curr_stat[256];

    if (read_file("/proc/stat", prev_stat, sizeof(prev_stat)) != 0) {
        pwm_cleanup();
        return 1;
    }

    while (g_running) {
        if (read_file("/proc/stat", curr_stat, sizeof(curr_stat)) != 0) {
            break;
        }

        float cpu_load = calculate_cpu_load(prev_stat, curr_stat);
        strncpy(prev_stat, curr_stat, sizeof(prev_stat) - 1);
        prev_stat[sizeof(prev_stat) - 1] = '\0';

        unsigned char r, g, b;
        map_cpu_load_to_color(cpu_load, &r, &g, &b);
        pwm_set_color(r, g, b);

        usleep(500000);
    }

    pwm_cleanup();
    return 0;
}

