    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X (block) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read block reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- BMP280 calibration ---- */
static int bmp280_read_calibration(int fd)
{
    uint8_t c1[2], c2[2], c3[2], c4[2], c5[2], c6[2], c7[2], c8[2];

    if (i2c_read_block(fd, BMP280_REG_CALIB_00, c1, 26) < 0) return -1;

    dig_T1 = (uint16_t)((c1[1] << 8) | c1[0]);
    dig_T2 = (int16_t)((c2[1] << 8) | c2[0]);
    dig_T3 = (int16_t)((c3[1] << 8) | c3[0]);
    dig_P1 = (uint16_t)((c4[1] << 8) | c4[0]);
    dig_P2 = (int16_t)((c5[1] << 8) | c5[0]);
    dig_P3 = (int16_t)((c6[1] << 8) | c6[0]);
    dig_P4 = (int16_t)((c7[1] << 8) | c7[0]);
    dig_P5 = (int16_t)((c8[1] << 8) | c8[0]);
    dig_P6 = (int16_t)((c9[1] << 8) | c9[0]);
    dig_P7 = (int16_t)((c10[1] << 8) | c10[0]);
    dig_P8 = (int16_t)((c11[1] << 8) | c11[0]);
    dig_P9 = (int16_t)((c12[1] << 8) | c12[0]);

    return 0;
}

/* ---- BMP280 compensation (datasheet formulae) ---- */
static int32_t bmp280_compensate_temp(int32_t adc_T)
{
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) *
            ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;  /* centi-degrees C */
}

static uint32_t bmp280_compensate_press(int32_t adc_P)
{
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)dig_P6);
    var2 = var2 + ((var1 * ((int32_t)dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)dig_P4) << 16);
    var1 = (((((var1 >> 2) * (var1 >> 2)) >> 13) * ((int32_t)dig_P3)) >> 3) +
           ((((var1 * ((int32_t)dig_P2)) >> 1)) + ((int32_t)dig_P1));
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1 << 31) - adc_P) - (var2 >> 12))) * 6250) / (uint32_t)var1;
    var1 = (((int32_t)dig_P9) * (int32_t)((p >> 3) * (p >> 3))) >> 13;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + ((int32_t)dig_P7)) >> 4));
    return p;  /* Pa */
}

/* ---- BMP280 init ---- */
static int bmp280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not found (ID=0x%02X, expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(fd, BMP280_REG_RESET, 0xB6) < 0) return -1;
    usleep(2000);

    /* Read calibration */
    if (bmp280_read_calibration(fd) < 0) return -1;

    /* Config: t_sb=500ms(0x05<<5), filter off(0x00<<2), spi3w_en=0 */
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, (BMP280_T_SB_500MS << 5) | (BMP280_FILTER_OFF << 2) | BMP280_SPI3W_DISABLE) < 0) return -1;

    /* ctrl_meas: osrs_t=x4(0x04<<5), osrs_p=x4(0x04<<2), normal(0x03) */
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL) < 0) return -1;

    return 0;
}

/* ---- BMP280 read with wait ---- */
static int bmp280_read(int fd, float *temp_c, float *press_pa)
{
    uint8_t status;
    uint8_t data[6];
    int32_t adc_T, adc_P;

    /* Wait for measurement to complete (bit 3 of status register) */
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg8(fd, BMP280_REG_STATUS, &status) < 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(5000);
    }
    if (status & 0x08) {
        fprintf(stderr, "BMP280 measurement timeout\n");
        return -1;
    }

    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    adc_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    adc_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);

    int32_t t_centi = bmp280_compensate_temp(adc_T);
    *temp_c = t_centi / 100.0f;
    *press_pa = bmp280_compensate_press(adc_P);
    return 0;
}

/* ---- UDP send ---- */
static int udp_send(int fd, const char *json)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid UDP address: %s\n", UDP_SERVER_IP);
        return -1;
    }

    if (sendto(fd, json, strlen(json), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "UDP send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_udp_fd >= 0) {
        close(g_udp_fd);
        g_udp_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (bmp280_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BMP280 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Create UDP socket */
    g_udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_fd < 0) {
        fprintf(stderr, "socket() failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 logger started. Sending to %s:%d every %d s.\n",
           UDP_SERVER_IP, UDP_SERVER_PORT, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c, press_pa;

        if (bmp280_read(g_i2c_fd, &temp_c, &press_pa) < 0) {
            fprintf(stderr, "Read error — continuing\n");
        } else {
            char json[128];
            snprintf(json, sizeof(json),
                     "{\"temperature\":%.2f,\"pressure\":%.2f}",
                     temp_c, press_pa);
            if (udp_send(g_udp_fd, json) < 0) {
                fprintf(stderr, "UDP send failed\n");
            } else {
                printf("Sent: %s\n", json);
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down.\n");
    cleanup();
    return EXIT_SUCCESS;
}

