/*
 * MAX31855 Thermocouple Fan Controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MAX31855 on SPI0 (CE0 / GPIO8), SPI mode 0, 500 kHz
 *   - PWM fan control on GPIO18 (BCM), 1 kHz, 0-255 duty
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_ctrl fan_ctrl.c -lpigpio -lrt
 *   (run as root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                       */
#define SPI_SPEED      500000     /* 500 kHz                                */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                  */
#define FAN_GPIO       18         /* BCM 18 — hardware PWM                  */
#define PWM_FREQ       1000       /* 1 kHz                                  */
#define PWM_RANGE      255        /* Duty-cycle range                       */
#define BUFFER_SIZE    20
#define SAMPLE_PERIOD  1          /* seconds                                */

/* ------------------------------- Data Types ------------------------------ */
typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} DataPoint;

typedef struct {
    DataPoint buffer[BUFFER_SIZE];
    int       head;
    int       count;
} CircularBuffer;

/* --------------------------- Global State -------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static CircularBuffer g_data_buffer;

/* --------------------------- Prototypes ---------------------------------- */
static int  init_spi(void);
static int  read_max31855(float *temperature);
static int  compute_duty_cycle(float temperature);
static void add_data_point(float temperature, int duty_cycle);
static void print_circular_buffer(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI ------------------------------------- */
static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/*
 * Read 4 bytes from the MAX31855 and convert to a thermocouple temperature.
 *
 * MAX31855 32-bit data layout (big-endian on the wire):
 *   D[31:18]  Thermocouple temperature, 14-bit signed, 0.25 °C / LSB
 *   D[15:4]   Internal reference-junction temperature, 12-bit signed, 0.0625 °C / LSB
 *   D[2]      Reserved
 *   D[1]      Fault bit (1 = fault)
 *   D[0]      Open-circuit bit (1 = open circuit)
 *
 * Faults:
 *   - Open circuit
 *   - Short to GND
 *   - Short to VCC
 *   - Thermocouple out of range (< -200 °C or > 1350 °C)
 *   - Internal reference-junction fault
 */
static int read_max31855(float *temperature)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes_xferred;

    bytes_xferred = spiXfer(g_spi_handle, rx, rx, 4);
    if (bytes_xferred != 4) {
        fprintf(stderr, "Error: SPI transfer failed (expected 4 bytes, got %d): %s\n",
                bytes_xferred, pigpio_error(bytes_xferred));
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit (D16) */
    if (raw & 0x00010000) {
        if (raw & 0x00000001)
            fprintf(stderr, "MAX31855 fault: Open circuit\n");
        else if (raw & 0x00000002)
            fprintf(stderr, "MAX31855 fault: Short to GND\n");
        else if (raw & 0x00000004)
            fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        else if (raw & 0x00000008)
            fprintf(stderr, "MAX31855 fault: Thermocouple out of range\n");
        else if (raw & 0x00000010)
            fprintf(stderr, "MAX31855 fault: Internal reference-junction fault\n");
        else
            fprintf(stderr, "MAX31855 fault: unknown\n");
        return -1;
    }

    /*
     * Thermocouple temperature: bits D[31:18] (14-bit signed, 2's complement).
     * Shift right 18 to get the 14-bit value, then sign-extend to int16_t.
     */
    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000)
        thermocouple_raw |= 0xC000;          /* sign-extend */

    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

/* --------------------------- Fan Control --------------------------------- */
static int compute_duty_cycle(float temperature)
{
    if (temperature < 25.0f)
        return 0;
    if (temperature < 40.0f)
        return (int)((temperature - 25.0f) / 15.0f * 127.0f);   /* 0–127 */
    if (temperature < 60.0f)
        return (int)((temperature - 40.0f) / 20.0f * 127.0f) + 127; /* 127–254 */
    return 255;
}

/* --------------------------- Circular Buffer ----------------------------- */
static void add_data_point(float temperature, int duty_cycle)
{
    g_data_buffer.buffer[g_data_buffer.head].timestamp   = time(NULL);
    g_data_buffer.buffer[g_data_buffer.head].temperature = temperature;
    g_data_buffer.buffer[g_data_buffer.head].duty_cycle  = duty_cycle;

    g_data_buffer.head = (g_data_buffer.head + 1) % BUFFER_SIZE;
    if (g_data_buffer.count < BUFFER_SIZE)
        g_data_buffer.count++;
}

static void print_circular_buffer(void)
{
    printf("\n--- Data Log (last %d entries) ---\n", g_data_buffer.count);
    int start = (g_data_buffer.count == BUFFER_SIZE)
                ? g_data_buffer.head
                : 0;

    for (int i = 0; i < g_data_buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_data_buffer.buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] Temp: %.2f C  Duty: %d/255\n",
               ts,
               g_data_buffer.buffer[idx].temperature,
               g_data_buffer.buffer[idx].duty_cycle);
    }
    printf("----------------------------------\n");
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Stop PWM */
    if (g_spi_handle >= 0) {
        gpioPWM(FAN_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO for hardware PWM */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n",
                FAN_GPIO, PWM_FREQ);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n",
                FAN_GPIO, PWM_RANGE);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, 0) initial state failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    g_data_buffer.head  = 0;
    g_data_buffer.count = 0;

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX31855 Fan Controller running. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        float temperature;

        if (read_max31855(&temperature) == 0) {
            int duty = compute_duty_cycle(temperature);

            if (gpioPWM(FAN_GPIO, duty) != 0) {
                fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n",
                        FAN_GPIO, duty);
            }

            add_data_point(temperature, duty);
            printf("Temp: %.2f C  Duty: %d/255\n", temperature, duty);
        } else {
            /* On read error, keep the fan at its current duty cycle. */
            fprintf(stderr, "Skipping fan update due to sensor error.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    print_circular_buffer();
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

