 *   D[15:4]   Internal reference-junction temperature, 12-bit signed, 0.0625 °C / LSB
 *   D[2]      Reserved
 *   D[1]      Fault bit (1 = fault)
 *   D[0]      Open-circuit bit (1 = open circuit)
 *
 * Faults:
 *   - Open circuit
 *   - Short to GND
 *   - Short to VCC
 *   - Thermocouple out of range (< -200 °C or > 1350 °C)
 *   - Internal reference-junction fault
 */
static int read_max31855(float *temperature)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes_xferred;

    bytes_xferred = spiXfer(g_spi_handle, rx, rx, 4);
    if (bytes_xferred != 4) {
