    }

    /*
     * Thermocouple temperature: bits D[31:18] (14-bit signed, 2's complement).
     * Shift right 18 to get the 14-bit value, then sign-extend to int16_t.
     */
    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000)
        thermocouple_raw |= 0xC000;          /* sign-extend */

    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

/* --------------------------- Fan Control --------------------------------- */
static int compute_duty_cycle(float temperature)
{
    if (temperature < 25.0f)
        return 0;
    if (temperature < 40.0f)
        return (int)((temperature - 25.0f) / 15.0f * 127.0f);   /* 0–127 */
    if (temperature < 60.0f)
        return (int)((temperature - 40.0f) / 20.0f * 127.0f) + 127; /* 127–254 */
    return 255;
}

/* --------------------------- Circular Buffer ----------------------------- */
static void add_data_point(float temperature, int duty_cycle)
{
    g_data_buffer.buffer[g_data_buffer.head].timestamp   = time(NULL);
    g_data_buffer.buffer[g_data_buffer.head].temperature = temperature;
    g_data_buffer.buffer[g_data_buffer.head].duty_cycle  = duty_cycle;

    g_data_buffer.head = (g_data_buffer.head + 1) % BUFFER_SIZE;
    if (g_data_buffer.count < BUFFER_SIZE)
        g_data_buffer.count++;
}

static void print_circular_buffer(void)
{
    printf("\n--- Data Log (last %d entries) ---\n", g_data_buffer.count);
    int start = (g_data_buffer.count == BUFFER_SIZE)
                ? g_data_buffer.head
                : 0;

    for (int i = 0; i < g_data_buffer.count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_data_buffer.buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        printf("[%s] Temp: %.2f C  Duty: %d/255\n",
               ts,
               g_data_buffer.buffer[idx].temperature,
               g_data_buffer.buffer[idx].duty_cycle);
    }
    printf("----------------------------------\n");
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Stop PWM */
    if (g_spi_handle >= 0) {
        gpioPWM(FAN_GPIO, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO for hardware PWM */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n",
                FAN_GPIO, PWM_FREQ);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n",
                FAN_GPIO, PWM_RANGE);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, 0) initial state failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize circular buffer */
    g_data_buffer.head  = 0;
    g_data_buffer.count = 0;

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX31855 Fan Controller running. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        float temperature;

        if (read_max31855(&temperature) == 0) {
            int duty = compute_duty_cycle(temperature);

            if (gpioPWM(FAN_GPIO, duty) != 0) {
                fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n",
                        FAN_GPIO, duty);
            }

            add_data_point(temperature, duty);
            printf("Temp: %.2f C  Duty: %d/255\n", temperature, duty);
        } else {
            /* On read error, keep the fan at its current duty cycle. */
            fprintf(stderr, "Skipping fan update due to sensor error.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    print_circular_buffer();
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

