/*
 * BME280 I2C reader for Raspberry Pi Zero W
 * Bus: /dev/i2c-1  (GPIO2 = SDA, GPIO3 = SCL)
 * BME280 I2C address: 0x76 (ADDR pin to GND)
 * Logs to bme280_log.csv every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bme280_log bme280_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BME280_ADDR    0x76
#define BME280_CHIP_ID 0x60

#define BME280_REG_ID          0xD0
#define BME280_REG_RESET       0xE0
#define BME280_REG_CTRL_HUM    0xF2
#define BME280_REG_STATUS      0xF3
#define BME280_REG_CTRL_MEAS   0xF4
#define BME280_REG_CONFIG      0xF5
#define BME280_REG_PRESS_MSB   0xF7
#define BME280_REG_TEMP_MSB    0xFA
#define BME280_REG_HUM_MSB     0xFD

#define LOG_FILE "bme280_log.csv"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, want %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id) != 0)
        return -1;
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n", id, BME280_CHIP_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) != 0)
        return -1;
    usleep(2000);

    /* Humidity x1, T standby 0.5 ms, filter off */
    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) != 0)
        return -1;

    /* Pressure x1, T x1, normal mode, filter off */
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) != 0)
        return -1;

    /* T standby 0.5 ms, filter off, spi3w_en off */
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) != 0)
        return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum, float *press)
{
    uint8_t status;
    if (i2c_read_reg(fd, BME280_REG_STATUS, &status) != 0)
        return -1;
    if (status & 0x01) {
        fprintf(stderr, "BME280 measurement not complete (status=0x%02X)\n", status);
        return -1;
    }

    uint8_t raw[8];
    if (i2c_read_block(fd, BME280_REG_PRESS_MSB, raw, 8) != 0)
        return -1;

    int32_t p = ((int32_t)raw[0] << 12) | ((int32_t)raw[1] << 4) | (raw[2] >> 4);
    int32_t t = ((int32_t)raw[3] << 12) | ((int32_t)raw[4] << 4) | (raw[5] >> 4);
    int32_t h = ((int32_t)raw[6] << 8) | raw[7];

    *press = (float)p / 256.0f;
    *temp  = (float)t / 100.0f;
    *hum   = (float)h / 1024.0f;
    return 0;
}

static void log_data(FILE *fp, float temp, float hum, float press)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, hum, press);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", BME280_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (bme280_init(fd) != 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) == 0) {
            log_data(fp, temp, hum, press);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

