        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) == 0) {
            log_data(fp, temp, hum, press);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

