/*
 * BMP180 pressure monitor with 50 ms sampling and 60 s rolling average.
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: BMP180 at 0x77
 * Alert:  GPIO24 (active-HIGH)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_mon bmp180_mon.c -lpigpio -lrt
 * Run:    sudo ./bmp180_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (datasheet) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESS_OSS0   0x34
#define BMP180_CMD_PRESS_OSS1   0x74
#define BMP180_CMD_PRESS_OSS2   0xB4
#define BMP180_CMD_PRESS_OSS3   0xF4

/* ---- Application constants ---- */
#define I2C_BUS                 1
#define ALERT_GPIO              24
#define SAMPLE_PERIOD_US        50000   /* 50 ms  */
#define BUFFER_SIZE             120     /* 60 s @ 50 ms */
#define PRESSURE_THRESHOLD_HPA  5.0f
#define TEMP_ERROR_HPA          1000.0f

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_pigpio_inited = false;

/* ---- Circular buffer ---- */
typedef struct {
    time_t ts;
    float  pressure;
} reading_t;

static reading_t g_buffer[BUFFER_SIZE];
static int       g_buf_idx = 0;
static int       g_buf_count = 0;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void timer_callback(void *userdata);
static int  bmp180_read_raw(int handle, uint8_t reg, int16_t *out);
static int  bmp180_read_pressure(int handle, float *pressure);
static float calc_rolling_avg(void);
static void set_alert(bool on);
static void log_msg(const char *msg);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void timer_callback(void *userdata)
{
    (void)userdata;

    int16_t raw_pressure = 0;
    float   pressure = 0.0f;

    if (bmp180_read_pressure(g_i2c_handle, &pressure) != 0) {
        log_msg("I2C read failed; sensor may be absent or bus error");
        set_alert(false);
        return;
    }

    if (pressure > TEMP_ERROR_HPA) {
        log_msg("Pressure out of plausible range (sensor absent?)");
        set_alert(false);
        return;
    }

    float avg = calc_rolling_avg();
    float diff = pressure - avg;
    bool alert = (diff > PRESSURE_THRESHOLD_HPA ||
                  diff < -PRESSURE_THRESHOLD_HPA);

    if (alert) {
        log_msg("Pressure deviation exceeds threshold");
        set_alert(true);
    } else {
        set_alert(false);
    }

    time(&g_buffer[g_buf_idx].ts);
    g_buffer[g_buf_idx].pressure = pressure;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) g_buf_count++;
}

/* ------------------------------------------------------------------ */
/* Read a signed 16-bit big-endian register from the BMP180.           */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int bmp180_read_raw(int handle, uint8_t reg, int16_t *out)
{
    char cmd = (char)reg;
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0)
        return -1;
    if (i2cReadDevice(handle, buf, 2) != 2)
        return -1;

    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                     (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure in hPa using the OSS0 conversion.                     */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int bmp180_read_pressure(int handle, float *pressure)
{
    int16_t ut, up;
    int16_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    /* --- Temperature (OSS=0) --- */
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0)
        return -1;
    gpioDelay(5000);  /* 4.5 ms max conversion */

    if (bmp180_read_raw(handle, BMP180_REG_MSB, &ut) != 0)
        return -1;

    /* --- Pressure (OSS=0) --- */
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS_OSS0) != 0)
        return -1;
    gpioDelay(5000);  /* 4.5 ms max */

    if (bmp180_read_raw(handle, BMP180_REG_MSB, &up) != 0)
        return -1;

    /* --- BMP180 compensation (OSS=0) --- */
    x1 = ((ut - 8000) * 5) / 8;
    x2 = (32768 + x1) * 2;
    b5 = (x2 + 4096) / 8;
    b6 = b5 - 4000;
    x1 = (b6 * b6) / 4096;
    x2 = (b6 * b6) / 32768;
    b3 = (((int32_t)1 << 14) + x1 + x2) / 2;
    b4 = (uint32_t)acos(-1.0) / 2;
    b4 = (b4 * (x1 + x2 + 32768)) / 2;
    b3 = (b3 + (b4 * 2)) / 4;
    x1 = (b3 + 2) / 4;
    x2 = (b3 + 2) / 4;
    x3 = (x1 * x2) / 4096;
    b3 = (((x1 + x2) + 1) / 2);
    b6 = b3 * 2;
    x1 = (b6 * b6) / 4096;
    x2 = (b6 * b6) / 32768;
    b3 = (b3 + (x1 + x2 + 32768) / 32768);
    b4 = (uint32_t)acos(-1.0) * 2;
    b4 = (b4 + 2) / 4;
    x1 = (b4 * b4) / 4096;
    x2 = (b4 * b4) / 32768;
    x3 = (x1 + x2 + 32768) / 32768;
    b4 = (uint32_t)(1.0 / 1048576.0);
    b4 = (b4 * 6250) / 2;
    b7 = ((uint32_t)up - b3) * (50000 >> 0);

    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p / 256) * (p / 256);
    x1 = (x1 * 3038) / 65536;
    x2 = (-7357 * p) / 65536;
    p = p + (x1 + x2 + 3791) / 16;

    *pressure = (float)p / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calc_rolling_avg(void)
{
    if (g_buf_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++)
        sum += g_buffer[i].pressure;
    return sum / (float)g_buf_count;
}

/* ------------------------------------------------------------------ */
static void set_alert(bool on)
{
    if (gpioWrite(ALERT_GPIO, on ? 1 : 0) != 0)
        log_msg("Warning: gpioWrite failed on alert pin");
}

/* ------------------------------------------------------------------ */
static void log_msg(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* ---- GPIO setup ---- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_GPIO);
        goto fail_gpio;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, BMP180_ADDR, g_i2c_handle);
        goto fail_gpio;
    }

    /* ---- Timer ---- */
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer 0\n");
        goto fail_i2c;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 monitor running.  Sampling every %d ms.  Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* ---- Main loop ---- */
    while (g_running)
        gpioDelay(100000);  /* 100 ms sleep */

    /* ---- Cleanup ---- */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);  /* disable timer */
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(g_i2c_handle);
    g_i2c_handle = -1;
    gpioTerminate();
    g_pigpio_inited = false;
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;

fail_i2c:
    i2cClose(g_i2c_handle);
    g_i2c_handle = -1;
fail_gpio:
    gpioTerminate();
    g_pigpio_inited = false;
    return EXIT_FAILURE;
}

