#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_PIN 18
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define MIN_DUTY 0
#define MAX_DUTY 255
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int map_temperature_to_duty(float temp) {
    if (temp < MIN_TEMP) return MIN_DUTY;
    if (temp > MAX_TEMP) return MAX_DUTY;
    return (int)(((temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * (MAX_DUTY - MIN_DUTY) + 0.5f);
}

static int log_data(float temp, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temp, duty);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting PWM pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp;
        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int duty = map_temperature_to_duty(temp);

        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle\n");
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d\n", temp, duty);
        sleep(SAMPLE_INTERVAL);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

