#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR    0x76          /* SDO -> GND */
#define BMP280_ADDR_ALT 0x77         /* SDO -> VDD */
