}

/* ---- Low-level I2C helpers ---- */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
