static int32_t bmp280_compensate_temp(int32_t adc_T, const bmp280_calib_t *c,
                                      int32_t *t_fine_out)
{
    int32_t var1, var2, T;
    var1 = ((((adc_T >> 3) - ((int32_t)c->dig_T1 << 1)))
            * ((int32_t)c->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)c->dig_T1))
              * ((adc_T >> 4) - ((int32_t)c->dig_T1))) >> 12)
            * ((int32_t)c->dig_T3)) >> 14;
    int32_t t_fine = var1 + var2;
    *t_fine_out = t_fine;
    T = (t_fine * 5 + 128) >> 8;   /* centi-degrees C */
    return T;
}

static uint32_t bmp280_compensate_press(int32_t adc_P, const bmp280_calib_t *c,
                                        int32_t t_fine)
{
    int32_t var1, var2;
    uint32_t p;
    var1 = (((int32_t)t_fine) >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)c->dig_P6);
    var2 = var2 + ((var1 * ((int32_t)c->dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)c->dig_P4) << 16);
    var1 = (((c->dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3)
            + ((((int32_t)c->dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)c->dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576 - adc_P) - (var2 >> 12))) * 3125));
    if (p < 0x80000000)
        p = (p << 1) / ((uint32_t)var1);
    else
        p = (p / (uint32_t)var1) * 2;
    var1 = (((int32_t)c->dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)c->dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + c->dig_P7) >> 4));
    return p;                       /* Pa */
}

/* ---- BMP280 driver ---- */

static int bmp280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, REG_ID, &id) != 0) return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not detected (id=0x%02X, expected 0x%02X)\n",
                id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_CONFIG, CONFIG_DEFAULT) != 0) return -1;
    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal,
                       float *temp_c, float *press_hpa)
{
    if (i2c_write_reg8(fd, REG_CTRL_MEAS, CTRL_MEAS_FORCED) != 0)
        return -1;

    /* Max conversion time for x1 oversampling is ~5.5 ms; wait 10 ms */
    usleep(10000);

    uint8_t buf[6];
    if (i2c_read_block(fd, REG_PRESS_MSB, buf, 6) != 0)
        return -1;

    int32_t adc_P = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4)
                  | ((int32_t)buf[2] >> 4);
    int32_t adc_T = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4)
                  | ((int32_t)buf[5] >> 4);

    int32_t t_fine;
    int32_t T_centi = bmp280_compensate_temp(adc_T, cal, &t_fine);
    *temp_c = T_centi / 100.0f;

    uint32_t P_pa = bmp280_compensate_press(adc_P, cal, t_fine);
    *press_hpa = P_pa / 100.0f;
    return 0;
}

/* ---- Logging ---- */

static int log_data(float temp_c, float press_hpa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                ts, temp_c, press_hpa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    int addr = BMP280_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) != 0) {
        fprintf(stderr, "BMP280 init failed (addr 0x%02X)\n", addr);
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calib(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP280 calibration data\n");
        close(fd);
        return 1;
    }

    printf("BMP280 logging started. Press Ctrl-C to stop.\n");

    while (g_running) {
        float temp_c, press_hpa;
        if (bmp280_read(fd, &cal, &temp_c, &press_hpa) == 0) {
            printf("T=%.2f °C  P=%.2f hPa\n", temp_c, press_hpa);
            if (log_data(temp_c, press_hpa) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

