        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    int addr = BMP280_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) != 0) {
        fprintf(stderr, "BMP280 init failed (addr 0x%02X)\n", addr);
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calib(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP280 calibration data\n");
        close(fd);
        return 1;
    }

    printf("BMP280 logging started. Press Ctrl-C to stop.\n");

    while (g_running) {
        float temp_c, press_hpa;
        if (bmp280_read(fd, &cal, &temp_c, &press_hpa) == 0) {
            printf("T=%.2f °C  P=%.2f hPa\n", temp_c, press_hpa);
            if (log_data(temp_c, press_hpa) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

