/*
 * LM75 temperature monitor with alert LED on GPIO18 (BCM).
 *
 * Hardware:
 *   - Raspberry Pi 4 Model B
 *   - LM75 on I2C bus 1, address 0x48
 *   - Alert LED on GPIO18 (BCM)
 *
 * Behavior:
 *   - Reads temperature once per second.
 *   - Stores 60 samples in a circular buffer protected by a mutex.
 *   - Computes a running average from the buffer.
 *   - Drives GPIO18 HIGH when temperature > 28.0 C, LOW otherwise.
 *   - Logs errors to stderr and attempts to re-initialize hardware.
 *   - Clean shutdown on SIGINT, all resources released.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define LM75_ADDR        0x48
#define LM75_TEMP_REG    0x00
#define GPIO_CHIP        "gpiochip4"
#define GPIO_LINE        18
#define BUFFER_SIZE      60
#define ALERT_THRESHOLD  28.0f
#define POLL_INTERVAL_S  1

/* ---- Circular buffer ---- */
typedef struct {
    float  data[BUFFER_SIZE];
    size_t head;
    size_t count;
    pthread_mutex_t mutex;
} CircularBuffer;

static CircularBuffer g_buffer;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ---- Prototypes ---- */
static int  i2c_init(void);
static int  i2c_read_temp(float *out);
static void buffer_init(CircularBuffer *cb);
static void buffer_add(CircularBuffer *cb, float value);
static float buffer_average(const CircularBuffer *cb);
static void *alert_thread(void *arg);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- I2C init ---- */
static int i2c_init(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ---- Read temperature from LM75 ---- */
static int i2c_read_temp(float *out)
{
    uint8_t reg = LM75_TEMP_REG;
    uint8_t buf[2];

    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read: %s\n", strerror(errno));
        return -1;
    }

    /* LM75: 9-bit two's-complement, 0.5 °C resolution */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 5;                       /* keep the 9 LSBs */
    *out = (float)raw * 0.5f;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(CircularBuffer *cb)
{
    memset(cb->data, 0, sizeof(cb->data));
    cb->head  = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(CircularBuffer *cb, float value)
{
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float buffer_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    pthread_mutex_lock(&cb->mutex);
    for (size_t i = 0; i < cb->count; i++)
        sum += cb->data[i];
    pthread_mutex_unlock(&cb->mutex);
    return sum / (float)cb->count;
}

/* ---- Alert thread ---- */
static void *alert_thread(void *arg)
{
    (void)arg;
    while (g_running) {
        float avg = buffer_average(&g_buffer);
        int val = (avg > ALERT_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(g_line, val) < 0) {
            fprintf(stderr, "gpiod_line_set_value(%d): %s\n",
                    val, strerror(errno));
        }
        sleep(POLL_INTERVAL_S);
    }
    return NULL;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    pthread_mutex_destroy(&g_buffer.mutex);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);

    g_i2c_fd = i2c_init();
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Initial I2C init failed; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_line, "lm75_alert", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75 monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (i2c_read_temp(&temp) == 0) {
            buffer_add(&g_buffer, temp);
            printf("Temperature: %.2f C  |  Avg: %.2f C\n", temp, buffer_average(&g_buffer));
        } else {
            fprintf(stderr, "Sensor read error; re-initializing I2C.\n");
            if (g_i2c_fd >= 0)
                close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            g_i2c_fd = i2c_init();
            if (g_i2c_fd < 0)
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
        }
        sleep(POLL_INTERVAL_S);
    }

    pthread_join(alert_tid, NULL);
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

