/*
 * PID heater controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - MAX31865 on SPI0 CE0 (mode 1, 500 kHz)
 *   - PT100 via 430 ohm reference resistor
 *   - MOSFET heater driver on GPIO18 (hardware PWM, 1 kHz, range 1000)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_pid heater_pid.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./heater_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        500000          /* 500 kHz */
#define SPI_FLAGS        0               /* mode 1, active-low CE */

#define PWM_GPIO         18
#define PWM_FREQUENCY    1000            /* Hz */
#define PWM_RANGE        1000            /* 0-1000 duty steps */

#define RREF             430.0           /* PT100 reference resistor (ohms) */
#define RNOMINAL         100.0           /* PT100 nominal resistance (ohms) */

#define CONFIG_FILE      "heater_config.json"
#define LOG_FILE         "heater_log.txt"

#define TARGET_TEMP_KEY  "target_temperature"
#define KP_KEY           "kp"
#define KI_KEY           "ki"
#define KD_KEY           "kd"

#define MAX_TEMP         80.0
#define SAMPLE_PERIOD_US 100000          /* 100 ms */

typedef struct {
    double target_temperature;
    double kp;
    double ki;
    double kd;
} Config;

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_message(const char *msg)
{
    if (!g_log_fp)
        return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* SPI / MAX31865                                                     */
/* ------------------------------------------------------------------ */

/*
 * MAX31865 32-bit SPI frame (mode 1, MSB first):
 *   D[31:18]  cold-junction temp (14-bit, 0.0625 °C / LSB)
 *   D[17:4]   internal temp (14-bit, 0.0625 °C / LSB)
 *   D[3]      reserved
 *   D[2]      fault bit
 *   D[1]      open-circuit bit
 *   D[0]      short-circuit bit
 *
 * Faults:
 *   - short-circuit (bit 0)
 *   - open-circuit  (bit 1)
 *   - reserved      (bit 2)
 *   - ref-junction (bit 3)
 *   - ref-ins      (bit 4)
 *   - ref-ext      (bit 5)
 *   - underrange   (bit 6)
 *   - overrange    (bit 7)
 */

static int read_max31865(double *temperature)
{
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(g_spi_handle, rx, rx, 4) != 4) {
        log_message("SPI transfer failed");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        /* Fault bit set */
        if (raw & 0x00000001)
            log_message("MAX31865 fault: short circuit");
        if (raw & 0x00000002)
            log_message("MAX31865 fault: open circuit");
        if (raw & 0x00000004)
            log_message("MAX31865 fault: ref junction");
        if (raw & 0x00000008)
            log_message("MAX31865 fault: ref insulation");
        if (raw & 0x00000010)
            log_message("MAX31865 fault: ref external");
        if (raw & 0x00000020)
            log_message("MAX31865 fault: underrange");
        if (raw & 0x00000040)
            log_message("MAX31865 fault: overrange");
        return -1;
    }

    /* Internal temperature: bits 16..4, 14-bit signed, 0.0625 °C/LSB */
    int16_t raw_temp = (int16_t)((raw >> 4) & 0x3FFF);
    if (raw_temp & 0x2000)
        raw_temp |= 0xC000;          /* sign-extend */

    *temperature = raw_temp * 0.0625;
    return 0;
}

static double calculate_resistance(double temp_c)
{
    /* PT100: R = Rnom * (1 + a * (T - T0)) */
    const double a = -0.00385;
    const double t0 = 0.0;
    return RNOMINAL * (1.0 + a * (temp_c - t0));
}

static double calculate_temperature(double resistance)
{
    /* PT100: T = (R - R0) / a + T0 */
    const double a = -0.00385;
    const double t0 = 0.0;
    return (resistance - RNOMINAL) / a + t0;
}

/* ------------------------------------------------------------------ */
/* PID                                                                */
/* ------------------------------------------------------------------ */

static double pid_update(double setpoint, double actual,
                         double kp, double ki, double kd,
                         double *integral, double *prev_error)
{
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                      */
/* ------------------------------------------------------------------ */

static int load_config(const char *filename, Config *cfg)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s; using defaults\n", filename);
        return -1;
    }

    char buf[2048];
    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);
    buf[n] = '\0';

    cJSON *root = cJSON_Parse(buf);
    if (!root) {
        fprintf(stderr, "Warning: JSON parse error; using defaults\n");
        return -1;
    }

    cJSON *t = cJSON_GetObjectItemCaseSensitive(root, TARGET_TEMP_KEY);
    cJSON *kp = cJSON_GetObjectItemCaseSensitive(root, KP_KEY);
    cJSON *ki = cJSON_GetObjectItemCaseSensitive(root, KI_KEY);
    cJSON *kd = cJSON_GetObjectItemCaseSensitive(root, KD_KEY);

    cfg->target_temperature = (t ? t->valuedouble : 25.0);
    cfg->kp = (kp ? kp->valuedouble : 1.0);
    cfg->ki = (ki ? ki->valuedouble : 0.1);
    cfg->kd = (kd ? kd->valuedouble : 0.01);

    cJSON_Delete(root);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    Config cfg = {
