#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS 0x34
#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0
#define LOG_FILE "breach_log.txt"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) { usleep(10000); continue; }
        if (read(fd, buf, len) == len) return 0;
        usleep(10000);
    }
    return -1;
}

static int read_calibration(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3,
                            uint16_t *ac4, uint16_t *ac5, uint16_t *ac6,
                            int16_t *b1, int16_t *b2, int16_t *mb,
                            int16_t *mc, int16_t *md) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, buf, 2) < 0) return -1;
    *ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC2, buf, 2) < 0) return -1;
    *ac2 = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC3, buf, 2) < 0) return -1;
    *ac3 = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC4, buf, 2) < 0) return -1;
    *ac4 = (uint16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC5, buf, 2) < 0) return -1;
    *ac5 = (uint16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC6, buf, 2) < 0) return -1;
    *ac6 = (uint16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_B1, buf, 2) < 0) return -1;
    *b1 = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_B2, buf, 2) < 0) return -1;
    *b2 = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_MB, buf, 2) < 0) return -1;
    *mb = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_MC, buf, 2) < 0) return -1;
    *mc = (int16_t)((buf[0] << 8) | buf[1]);
    if (i2c_read_bytes(fd, BMP180_REG_CAL_MD, buf, 2) < 0) return -1;
    *md = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS) < 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - 0);
    return 0;
}

static int32_t compute_b5(int32_t ut, const int16_t *ac1, int16_t *ac6,
                          const uint16_t *ac5, int16_t *mc, int16_t *md) {
    int32_t x1 = ((ut - (int32_t)*ac6) * (int32_t)*ac5) >> 15;
    int32_t x2 = ((int32_t)*mc << 11) / (x1 + (int32_t)*md);
    return x1 + x2;
}

static float calculate_temperature(int32_t b5) {
    return (float)((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t b5,
                                const int16_t *b1, const int16_t *b2,
                                const uint16_t *ac4) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)*b2 * (b6 * b6) >> 12) >> 11;
    int32_t x2 = ((int32_t)*ac4 * b6) >> 15;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)((*b1) << 15) + x3) + 1) >> 1;
    uint32_t b4 = ((uint32_t)*ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void log_breach(float temperature, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Temperature: %.2f C, Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open"); return 1; }
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl"); close(fd); return 1;
    }

    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
    if (read_calibration(fd, &ac1, &ac2, &ac3, &ac4, &ac5, &ac6,
                         &b1, &b2, &mb, &mc, &md) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(fd); return 1;
    }

    while (running) {
        int32_t ut, up;
        if (read_raw_temperature(fd, &ut) < 0) {
            fprintf(stderr, "Temperature read failed\n");
            sleep(1); continue;
        }
        if (read_raw_pressure(fd, &up) < 0) {
            fprintf(stderr, "Pressure read failed\n");
            sleep(1); continue;
        }

        int32_t b5 = compute_b5(ut, &ac1, &ac6, &ac5, &mc, &md);
        float temperature = calculate_temperature(b5);
        float pressure = calculate_pressure(up, b5, &b1, &b2, &ac4);

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            log_breach(temperature, pressure);
        }
        sleep(1);
    }

    close(fd);
    return 0;
}

