/*
 * BMP180 temperature/pressure monitor with fan control on Raspberry Pi 4.
 *
 * Wiring:
 *   BMP180 SDA -> GPIO2 (I2C bus 1)
 *   BMP180 SCL -> GPIO3 (I2C bus 1)
 *   BMP180 VCC -> 3.3 V
 *   BMP180 GND -> GND
 *   Fan control -> GPIO18 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bmp180_monitor bmp180_monitor.c \
 *       -lm -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- BMP180 constants (datasheet) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_LEN          22

#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESS_OSS0   0x34

#define FAN_GPIO                18
#define TEMP_THRESHOLD          30.0f
#define BUFFER_SIZE             60
#define SAMPLE_PERIOD_US        500000   /* 500 ms */

/* ---- Data structures ---- */
typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ---- Globals ---- */
static int               i2c_handle = -1;
static CircularBuffer    buffer;
static volatile sig_atomic_t running = 1;

/* ---- Calibration coefficients (BMP180 datasheet) ---- */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ---- Prototypes ---- */
static int  bmp180_init(void);
static int  bmp180_read_calibration(void);
static int  bmp180_read_raw_temperature(int32_t *raw_temp);
static int  bmp180_read_raw_pressure(int32_t *raw_pressure);
static int  bmp180_read_temperature(float *temperature);
static int  bmp180_read_pressure(float *pressure);
static void buffer_init(CircularBuffer *cb);
static void buffer_add(CircularBuffer *cb, SensorData sd);
static void timer_callback(void *userdata);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- BMP180 init ---- */
static int bmp180_init(void)
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n",
                BMP180_ADDR, i2c_handle);
        return -1;
    }

    if (bmp180_read_calibration() != 0) {
        fprintf(stderr, "Error reading BMP180 calibration data.\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ---- Read 11 calibration words ---- */
static int bmp180_read_calibration(void)
{
    uint8_t buf[BMP180_CAL_LEN];

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START,
                            (char *)buf, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Error reading BMP180 calibration block.\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

/* ---- Read raw temperature ---- */
static int bmp180_read_raw_temperature(int32_t *raw_temp)
{
    char cmd = BMP180_CMD_TEMP;

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing temperature command.\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    char reg = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting MSB register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data.\n");
        return -1;
    }

    *raw_temp = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ---- Read raw pressure (OSS = 0) ---- */
static int bmp180_read_raw_pressure(int32_t *raw_pressure)
{
    char cmd = BMP180_CMD_PRESS_OSS0;

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing pressure command.\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    char reg = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting MSB register pointer.\n");
        return -1;
    }

    char data[3];
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data.\n");
        return -1;
    }

    *raw_pressure = ((int32_t)(data[0] << 16) |
                     (int32_t)(data[1] << 8)  |
                     (int32_t)data[2]) >> 8;
    return 0;
}

/* ---- Read temperature (B5 already computed by pressure routine) ---- */
static int bmp180_read_temperature(float *temperature)
{
    int32_t ut;
    if (bmp180_read_raw_temperature(&ut) != 0)
        return -1;

    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *temperature = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

/* ---- Read pressure (OSS = 0) ---- */
static int bmp180_read_pressure(float *pressure)
{
    int32_t ut, up;
    if (bmp180_read_raw_temperature(&ut) != 0)
        return -1;

    if (bmp180_read_raw_pressure(&up) != 0)
        return -1;

    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (uint32_t)(50000UL);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *pressure = (float)(p + ((x1 + x2 + 3791) >> 4));
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, SensorData sd)
{
    cb->data[cb->head] = sd;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ---- Timer callback (runs in pigpio thread) ---- */
static void timer_callback(void *userdata)
{
    (void)userdata;

    float temperature, pressure;

    if (bmp180_read_temperature(&temperature) != 0)
        return;

    if (bmp180_read_pressure(&pressure) != 0)
        return;

    SensorData sd;
    sd.timestamp   = time(NULL);
    sd.temperature = temperature;
    sd.pressure    = pressure;

    buffer_add(&buffer, sd);

    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)sd.timestamp, sd.temperature, sd.pressure);

    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("Temperature above threshold! Fan ON.\n");
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Temperature below threshold. Fan OFF.\n");
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (bmp180_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output.\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting timer function.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Sampling every 500 ms.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running)
        gpioDelay(100000);  /* 100 ms sleep */

    cleanup();
    return EXIT_SUCCESS;
}

