#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS 0x34
#define GPIO_PIN 27
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_US 200000
#define SAMPLE_INTERVAL_S 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static int i2c_handle = -1;
static FILE *log_file = NULL;
static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }
    c->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc = (int16_t)((buf[18] << 8) | buf[19]);
    c->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int handle, int oss, int32_t *up) {
    uint8_t cmd = BMP180_CMD_PRESSURE_OSS;
    cmd |= (oss << 6);
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, cmd) < 0) return -1;
    gpioDelay(2000 + (3000 << oss));
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - oss);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int oss, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(0, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << oss) + 2) >> 2);
    uint32_t x1_u = ((uint32_t)c->ac3 * b6) >> 13;
    uint32_t x2_u = ((uint32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x3_u = ((x1_u + x2_u) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    if (tick - last_interrupt_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_tick = tick;
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Calibration read failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "ISR setup failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Press Ctrl+C to exit. Toggle logging with GPIO27.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(i2c_handle, &ut) < 0) {
                fprintf(stderr, "Temp read error\n");
                gpioDelay(1000000);
                continue;
            }
            if (read_raw_pressure(i2c_handle, 0, &up) < 0) {
                fprintf(stderr, "Pressure read error\n");
                gpioDelay(1000000);
                continue;
            }
            int32_t pressure = compute_pressure(up, 0, &cal);
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s, %ld\n", ts, (long)pressure);
            fflush(log_file);
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    cleanup();
    return 0;
}

