#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define CS_PIN 8
#define HEATER_PIN 17
#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80.0
#define KP 1.0
#define KI 0.1
#define INTEGRAL_LIMIT 100.0
#define ERROR_LIMIT 10.0
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float temp, float duty_cycle, const char *error_msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f,%s\n", timestamp, temp, duty_cycle, error_msg ? error_msg : "");
        fflush(log_file);
    }
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            return -2;
        } else if (raw & 0x00000002) {
            return -3;
        } else if (raw & 0x00000004) {
            return -4;
        }
        return -5;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25;
    return 0;
}

static float calculate_duty_cycle(float error) {
    static float integral = 0.0;
    float derivative = error - ERROR_LIMIT;
    integral += error;
    if (integral > INTEGRAL_LIMIT) integral = INTEGRAL_LIMIT;
    if (integral < -INTEGRAL_LIMIT) integral = -INTEGRAL_LIMIT;
    return KP * error + KI * integral + KP * derivative;
}

static void set_heater_duty(float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    int pwm_value = (int)(duty_cycle / 100.0 * 255.0);
    gpioPWM(HEATER_PIN, pwm_value);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(HEATER_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, 1000);
    gpioSetPWMrange(HEATER_PIN, 255);
    gpioPWM(HEATER_PIN, 0);

    log_file = fopen("heater_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0;

    while (running) {
        float temp = 0.0;
        int ret = read_max31855(&temp);

        if (ret == 0) {
            float error = TARGET_TEMP - temp;
            float duty = calculate_duty_cycle(error);
            set_heater_duty(duty);
            log_data(temp, duty, NULL);
            integral = 0.0;
        } else {
            const char *err_msg = NULL;
            switch (ret) {
                case -2: err_msg = "Open circuit"; break;
                case -3: err_msg = "Short to GND"; break;
                case -4: err_msg = "Short to VCC"; break;
                case -5: err_msg = "MAX31855 fault"; break;
                default: err_msg = "SPI read error"; break;
            }
            set_heater_duty(0.0);
            log_data(0.0, 0.0, err_msg);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

