#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define POLL_MS    500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int set_pwm(int pin, int duty)
{
    /*
     * Hardware PWM via the pigpio library.
     * pigpio's gpioPWM sets the duty cycle on a hardware PWM pin;
     * for a common-anode RGB LED the duty cycle is inverted:
     *   0   -> 255  (off)
     *   1..254-> 0..254 (on)
     *   255 -> 0   (on, full brightness)
     */
    int pigpio_duty = 255 - duty;
    if (pigpio_duty < 0)   pigpio_duty = 0;
    if (pigpio_duty > 255) pigpio_duty = 255;

    if (gpioPWM(pin, pigpio_duty) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO%d (duty=%d): %s\n",
                pin, duty, strerror(errno));
        return -1;
    }
    return 0;
}

static void set_led_color(int r, int g, int b)
{
    (void)set_pwm(RED_PIN,   r);
    (void)set_pwm(GREEN_PIN, g);
    (void)set_pwm(BLUE_PIN,  b);
}

static void temp_to_color(int temp_mC)
{
    if (temp_mC < 40000) {
        set_led_color(0, 0, 255);
    } else if (temp_mC < 60000) {
        set_led_color(0, 255, 0);
    } else {
        set_led_color(255, 0, 0);
    }
}

static int read_temperature(int *temp_mC)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[32];
    if (!fgets(buf, sizeof(buf), fp)) {
        fprintf(stderr, "Read failed on %s: %s\n", TEMP_FILE,
                ferror(fp) ? strerror(errno) : "unexpected EOF");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr = NULL;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Malformed temperature value: '%s'\n", buf);
        return -1;
    }

    *temp_mC = (int)val;
    return 0;
}

int main(void)
{
    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM pins as outputs --- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (g_running) {
        int temp_mC = 0;
        if (read_temperature(&temp_mC) != 0) {
            /* Error already reported; turn off LED and continue */
            set_led_color(0, 0, 0);
            usleep(POLL_MS * 1000);
            continue;
        }

        temp_to_color(temp_mC);
        printf("Temperature: %d mC, RGB: (%d, %d, %d)\n",
               temp_mC,
               gpioRead(RED_PIN)   == 0 ? 255 : 0,
               gpioRead(GREEN_PIN) == 0 ? 255 : 0,
               gpioRead(BLUE_PIN)  == 0 ? 255 : 0);
        fflush(stdout);

        usleep(POLL_MS * 1000);
    }

    /* --- Graceful shutdown --- */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

