#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if (terminate) return -1;
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int i, j;

    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_GPIO, 0) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(DHT22_GPIO, 1) < 0) return -1;
    gpioDelay(30);
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;

    if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) return -1;
        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;
        uint32_t duration = gpioTick() - start;
        data[i / 8] <<= 1;
        if (duration > 50) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

static int post_data(float humidity, float temperature) {
    char json[256];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f, \"temperature\": %.1f}", humidity, temperature);

    FILE *fp = popen("curl -s -X POST -H \"Content-Type: application/json\" -d '\"humidity\": %.1f, \"temperature\": %.1f' " SERVER_URL, "r");
    if (!fp) {
        fprintf(stderr, "popen failed: %s\n", strerror(errno));
        return -1;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        printf("%s", buffer);
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "pclose failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "curl exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

int main(void) {
