/*
 * BMP180 pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   BMP180 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   BMP180 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   BMP180 VCC  -> 3.3 V
 *   BMP180 GND  -> GND
 *   Button     -> GPIO 4 (internal pull-up, falling edge)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_logger bmp180_logger.c -lpigpio -lrt
 * Run:    sudo ./bmp180_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BMP180 constants (datasheet rev 1.26) ---- */
#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE

#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESS_OSS3   0xF4  /* OSS = 3 */

#define OSS                     3
#define LOG_FILE                "pressure_log.txt"
#define DEBOUNCE_US             200000  /* 200 ms */
#define CONVERSION_MS           26      /* OSS = 3: ~25.8 ms; round up */
#define SAMPLE_INTERVAL_S       2

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Calibration coefficients (signed/unsigned 16-bit) ---- */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "i2cWriteByte(0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "i2cReadDevice(0x%02X, %u) failed\n", reg, len);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "i2cWriteByteData(0x%02X, 0x%02X) failed\n", reg, val);
        return -1;
    }
    return 0;
}

/* ---- Read calibration coefficients ---- */
static int read_calibration(int handle)
{
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, sizeof(buf)) != 0)
        return -1;

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity-check: AC1/AC6 are never 0 or 0xFFFF on a real BMP180 */
    if (ac1 == 0 || ac1 == (int16_t)0x8000 ||
        ac6 == 0 || ac6 == 0xFFFF) {
        fprintf(stderr, "Calibration data invalid (sensor absent or not BMP180?)\n");
        return -1;
    }
    return 0;
}

/* ---- Read raw temperature ---- */
static int read_raw_temperature(int handle, int32_t *ut)
{
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0)
        return -1;
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) != 0)
        return -1;

    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- Read raw pressure (OSS = 3) ---- */
static int read_raw_pressure(int handle, int32_t *up)
{
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS_OSS3) != 0)
        return -1;
    gpioDelay(CONVERSION_MS * 1000);

    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) != 0)
        return -1;

    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

/* ---- Bosch integer compensation (full algorithm, OSS = 3) ---- */
static int32_t compute_b5(int32_t ut)
{
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5)
{
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (uint32_t)50000;

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;  /* Pa */
}

/* ---- Logging ---- */
static void log_pressure(int32_t pressure_pa)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s, %.2f hPa\n", timestamp, pressure_pa / 100.0);
        fflush(g_log_file);
    }
    printf("%s, %.2f hPa\n", timestamp, pressure_pa / 100.0);
}

/* ---- Button interrupt handler (falling edge) ---- */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    static uint32_t last_tick = 0;
    (void)gpio;
    (void)userdata;

    if (level != 0)            /* only falling edge */
        return;
    if (tick - last_tick < DEBOUNCE_US)
        return;
    last_tick = tick;

    static int logging_enabled = 0;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at BMP180 address */
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(1, 0x%02X) failed: %d\n", BMP180_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read calibration */
    if (read_calibration(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure button GPIO 4 as input with internal pull-up */
    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);

    /* Register ISR on falling edge */
    if (gpioSetISRFuncEx(4, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 logger started. Press button on GPIO 4 to toggle logging.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(4) == 0) {  /* button pressed (active low) */
            int32_t ut, up;
            if (read_raw_temperature(g_i2c_handle, &ut) != 0) {
                fprintf(stderr, "Temperature read failed\n");
                continue;
            }
            if (read_raw_pressure(g_i2c_handle, &up) != 0) {
                fprintf(stderr, "Pressure read failed\n");
                continue;
            }

            int32_t b5 = compute_b5(ut);
            int32_t pressure_pa = compute_pressure(up, b5);

            if (pressure_pa < 0 || pressure_pa > 110000) {
                fprintf(stderr, "Pressure out of range: %d Pa\n", pressure_pa);
                continue;
            }

            log_pressure(pressure_pa);
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);  /* 2 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

