/*
 * DHT22 humidity reader for Raspberry Pi 3 Model B+
 * Uses pigpio for microsecond-level edge timing on GPIO4 (BCM 4, physical pin 7).
 * Reads every 10 s, POSTs JSON to a configurable URL.
 *
 * Build:  gcc -O2 -Wall -Wextra -o dht22_reader dht22_reader.c -lpigpio -lcurl
 * Run:    sudo ./dht22_reader [-s http://your-api-url.com/api/humidity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO        4
#define DHT22_MAX_RETRIES 3
#define DHT22_RETRY_DELAY 2   /* seconds between retries */
#define DHT22_READ_INTERVAL 10 /* seconds between successful reads */
#define DHT22_TIMEOUT_US  100000 /* 100 ms max wait per edge */
#define DHT22_START_LOW_US 1000  /* ≥1 ms start low */
#define DHT22_START_HIGH_US 30   /* 20–40 µs start high */
#define DHT22_BIT_THRESHOLD 50   /* ≥50 µs high => bit '1', else '0' */

static volatile sig_atomic_t g_terminate = 0;
static char *g_api_url = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* DHT22 read                                                          */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills humidity (0–100 %RH) and temperature
 * (°C).  Returns -1 on any error.
 */
static int dht22_read(float *humidity, float *temperature)
{
    uint8_t data[5] = {0};
    uint32_t edges[85];
    int i, bit;

    /* --- Start signal: pull low >= 1 ms, then high 20–40 µs --- */
    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "dht22: gpioSetMode failed");
        return -1;
    }
    if (gpioWrite(DHT22_GPIO, 0) < 0) {
        syslog(LOG_ERR, "dht22: gpioWrite low failed");
        return -1;
    }
    gpioDelay(DHT22_START_LOW_US);
    if (gpioWrite(DHT22_GPIO, 1) < 0) {
        syslog(LOG_ERR, "dht22: gpioWrite high failed");
        return -1;
    }
    gpioDelay(DHT22_START_HIGH_US);

    /* Release line: switch to input (external pull-up keeps it high) */
    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) {
        syslog(LOG_ERR, "dht22: gpioSetMode input failed");
        return -1;
    }

    /* --- Wait for sensor response: low ~80 µs, high ~80 µs --- */
    uint32_t t0 = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - t0 > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "dht22: timeout waiting for response low");
            return -1;
        }
    }
    t0 = gpioTick();
    while (gpioRead(DHT22_GPIO) == 0) {
        if (gpioTick() - t0 > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "dht22: timeout waiting for response high");
            return -1;
        }
    }
    t0 = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - t0 > DHT22_TIMEOUT_US) {
            syslog(LOG_ERR, "dht22: timeout waiting for response low (2)");
            return -1;
        }
    }

    /* --- Read 40 data bits --- */
    for (bit = 0; bit < 40; bit++) {
        /* Low phase (~50 µs) */
        t0 = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - t0 > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "dht22: timeout on bit %d low", bit);
                return -1;
            }
        }
        /* High phase: duration determines bit value */
        t0 = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - t0 > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "dht22: timeout on bit %d high", bit);
                return -1;
            }
        }
        uint32_t high_us = gpioTick() - t0;
        data[bit / 8] <<= 1;
        if (high_us > DHT22_BIT_THRESHOLD)
            data[bit / 8] |= 1;
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        syslog(LOG_ERR, "dht22: checksum mismatch (calc=%u, recv=%u)",
               checksum, data[4]);
        return -1;
    }

    /* --- Convert --- */
    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];
    *humidity = (float)raw_h / 10.0f;
    *temperature = (float)(raw_t & 0x7FFF) / 10.0f;
    if (raw_t & 0x8000)
        *temperature = -*temperature;

    return 0;
}

/* ------------------------------------------------------------------ */
/* JSON formatting                                                     */
/* ------------------------------------------------------------------ */
static int format_json(float humidity, float temperature, char *buf, size_t len)
{
    int n = snprintf(buf, len,
                     "{\"humidity\": %.1f, \"temperature\": %.1f}",
                     humidity, temperature);
    return (n > 0 && (size_t)n < len) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* HTTP POST                                                           */
/* ------------------------------------------------------------------ */
static int post_data(const char *url, const char *json)
{
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "http: curl_easy_init failed");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "http: curl_slist_append failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 15L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    if (res == CURLE_OK)
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "http: curl_easy_perform failed: %s",
               curl_easy_strerror(res));
        return -1;
    }
    if (http_code < 200 || http_code >= 300) {
        syslog(LOG_ERR, "http: non-2xx response: %ld", http_code);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Library teardown                                                    */
/* ------------------------------------------------------------------ */
static void library_teardown(void)
{
    /* Placeholder for any library-level teardown */
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
        case 's':
            g_api_url = optarg;
            break;
        default:
            fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    openlog("dht22_reader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init failed");
        gpioTerminate();
        library_teardown();
        closelog();
        return EXIT_FAILURE;
    }

    if (!g_api_url) {
        g_api_url = strdup("http://your-api-url.com/api/humidity");
        if (!g_api_url) {
            syslog(LOG_ERR, "strdup failed: %m");
            curl_global_cleanup();
            gpioTerminate();
            library_teardown();
            closelog();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "DHT22 reader started (url=%s)", g_api_url);

    float humidity = 0.0f, temperature = 0.0f;
    char json[128];
    int retries;

    while (!g_terminate) {
        retries = DHT22_MAX_RETRIES;
        bool read_ok = false;

        while (retries > 0 && !g_terminate) {
            if (dht22_read(&humidity, &temperature) == 0) {
                read_ok = true;
                break;
            }
            retries--;
            if (retries > 0)
                sleep(DHT22_RETRY_DELAY);
        }

        if (!read_ok) {
            syslog(LOG_ERR, "DHT22 read failed after %d retries",
                   DHT22_MAX_RETRIES);
            goto next_cycle;
        }

        if (format_json(humidity, temperature, json, sizeof(json)) != 0) {
            syslog(LOG_ERR, "JSON formatting failed");
            goto next_cycle;
        }

        retries = DHT22_MAX_RETRIES;
        bool post_ok = false;
        while (retries > 0 && !g_terminate) {
            if (post_data(g_api_url, json) == 0) {
                post_ok = true;
                break;
            }
            retries--;
            if (retries > 0)
                sleep(DHT22_RETRY_DELAY);
        }

        if (post_ok) {
            syslog(LOG_INFO, "Humidity: %.1f%%, Temperature: %.1f°C",
                   humidity, temperature);
        } else {
            syslog(LOG_ERR, "POST failed after %d retries", DHT22_MAX_RETRIES);
        }

    next_cycle:
        if (!g_terminate)
            sleep(DHT22_READ_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down");
    curl_global_cleanup();
    gpioTerminate();
    library_teardown();
    free(g_api_url);
    closelog();
    return EXIT_SUCCESS;
}

