            syslog(LOG_ERR, "DHT22 read failed after %d retries",
                   DHT22_MAX_RETRIES);
            goto next_cycle;
        }

        if (format_json(humidity, temperature, json, sizeof(json)) != 0) {
            syslog(LOG_ERR, "JSON formatting failed");
            goto next_cycle;
        }

        retries = DHT22_MAX_RETRIES;
        bool post_ok = false;
        while (retries > 0 && !g_terminate) {
            if (post_data(g_api_url, json) == 0) {
                post_ok = true;
                break;
            }
            retries--;
            if (retries > 0)
                sleep(DHT22_RETRY_DELAY);
        }

        if (post_ok) {
            syslog(LOG_INFO, "Humidity: %.1f%%, Temperature: %.1f°C",
                   humidity, temperature);
        } else {
            syslog(LOG_ERR, "POST failed after %d retries", DHT22_MAX_RETRIES);
        }

    next_cycle:
        if (!g_terminate)
            sleep(DHT22_READ_INTERVAL);
    }

    syslog(LOG_INFO, "Shutting down");
    curl_global_cleanup();
    gpioTerminate();
    library_teardown();
    free(g_api_url);
    closelog();
    return EXIT_SUCCESS;
}

