#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp / 1000;
}

static int read_fan_state(void) {
    FILE *fp = fopen(FAN_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }
    int state;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return state;
}

static int read_fan_max_state(void) {
    FILE *fp = fopen(FAN_MAX_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_FILE, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading fan max_state from %s\n", FAN_MAX_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int set_fan_state(int state) {
    FILE *fp = fopen(FAN_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int calculate_fan_speed(int temperature) {
    if (temperature < 45) return 0;
    if (temperature < 55) return 1;
    if (temperature < 65) return 2;
    return 3;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int max_state = read_fan_max_state();
    if (max_state < 0) {
        fprintf(stderr, "Failed to read fan max_state. Exiting.\n");
        return 1;
    }
    if (max_state < 3) {
        fprintf(stderr, "Fan max_state is %d, expected 3 or more. Exiting.\n", max_state);
        return 1;
    }

    int current_fan_state = read_fan_state();
    if (current_fan_state < 0) {
        fprintf(stderr, "Failed to read initial fan state. Exiting.\n");
        return 1;
    }

    log_event("Fan control started");

    while (running) {
        int temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Temperature read failed, retrying in %d seconds...\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int new_fan_speed = calculate_fan_speed(temperature);
        if (new_fan_speed != current_fan_state) {
            if (set_fan_state(new_fan_speed) == 0) {
                current_fan_state = new_fan_speed;
                char log_message[128];
                snprintf(log_message, sizeof(log_message),
                         "Temperature: %d°C, Fan speed: %d", temperature, new_fan_speed);
                log_event(log_message);
            } else {
                fprintf(stderr, "Failed to set fan state, retrying in %d seconds...\n", POLL_INTERVAL);
            }
        }

        sleep(POLL_INTERVAL);
    }

    log_event("Fan control shutting down");
    set_fan_state(0);
    return 0;
}

