/*
 * PID controller for a resistive heater on GPIO18 (hardware PWM 1 kHz, 0-100 % duty).
 * MAX31855 thermocouple amplifier on SPI0: CLK=GPIO11, CS=GPIO8/CE0, DO=GPIO9.
 *
 * Build: gcc -O2 -Wall -o heater_pid heater_pid.c -lpigpio -lrt
 * Run:   sudo ./heater_pid
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_PIN        18
#define SPI_CHANNEL       0
#define SPI_SPEED         500000          /* 500 kHz — MAX31855 max is 5 MHz */
#define PWM_FREQUENCY     1000            /* 1 kHz hardware PWM */
#define PWM_RANGE         100             /* 0-100 % duty */
#define TARGET_TEMP       50.0
#define MAX_TEMP          100.0
#define MIN_TEMP          0.0
#define LOG_FILE          "heater_log.txt"
#define SAMPLE_PERIOD_US  1000000         /* 1 s */
#define MAX_CONSEC_ERRORS 10

/* PID gains */
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDGains;

/* PID state */
typedef struct {
    double integral;
    double previous_error;
} PIDState;

/* Globals for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 4 bytes from MAX31855 and return thermocouple temperature in °C.
 * Returns true on success, false on SPI or fault error. */
static bool read_max31855(int spi_handle, double *temperature)
{
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, rx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return false;
    }

    uint8_t fault = (uint8_t)rx[1] & 0x07;
    if (fault) {
        fprintf(stderr, "MAX31855 fault detected (0x%02X): ", fault);
        if (fault & 0x01) fprintf(stderr, "Open circuit ");
        if (fault & 0x02) fprintf(stderr, "Short to GND ");
        if (fault & 0x04) fprintf(stderr, "Short to VCC ");
        fprintf(stderr, "\n");
        return false;
    }

    /* Thermocouple temperature: 14-bit signed, bits 31..18 */
    int16_t raw = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    raw >>= 2;                       /* arithmetic shift sign-extends */
    *temperature = (double)raw * 0.25;
    return true;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, double temp, int duty, double pid_out)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temp: %.2f C, Duty: %d%%, PID: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temp, duty, pid_out);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void set_heater_duty(int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > 100) duty = 100;
    gpioPWM(HEATER_PIN, duty);
}

/* ------------------------------------------------------------------ */
static double pid_compute(double setpoint, double measured,
                          PIDGains gains, PIDState *state,
                          double dt)
{
    double error = setpoint - measured;

    state->integral += error * dt;
    if (state->integral > 1000.0)  state->integral = 1000.0;
    if (state->integral < -1000.0) state->integral = -1000.0;

    double derivative = (error - state->previous_error) / dt;
    double output = gains.Kp * error + gains.Ki * state->integral +
                    gains.Kd * derivative;

    state->previous_error = error;

    if (output < 0.0)   output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioPWM(HEATER_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- heater GPIO setup ------------------------------------------- */
    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    set_heater_duty(0);

    /* --- SPI init ----------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file ----------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- PID defaults ------------------------------------------------- */
    PIDGains gains = {1.0, 0.1, 0.01};
    PIDState state = {0.0, 0.0};
    double dt = (double)SAMPLE_PERIOD_US / 1.0e6;

    /* --- signals ------------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop ---------------------------------------------------- */
    int consec_errors = 0;

    while (g_running) {
        double temp = 0.0;
        bool ok = read_max31855(g_spi_handle, &temp);

        if (!ok) {
            consec_errors++;
            if (consec_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors — heater disabled\n");
                set_heater_duty(0);
                state.integral = 0.0;
                state.previous_error = 0.0;
                consec_errors = 0;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        consec_errors = 0;

        /* Failsafe */
        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C — heater disabled\n", temp);
            set_heater_duty(0);
            state.integral = 0.0;
            state.previous_error = 0.0;
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pid_out = pid_compute(TARGET_TEMP, temp, gains, &state, dt);
        int duty = (int)(pid_out + 0.5);
        set_heater_duty(duty);

        log_data(g_log_file, temp, duty, pid_out);
        printf("Temp: %.2f C, Duty: %d%%, PID: %.2f\n", temp, duty, pid_out);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- graceful shutdown ------------------------------------------- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

