    /* --- heater GPIO setup ------------------------------------------- */
    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    set_heater_duty(0);

    /* --- SPI init ----------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz)\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file ----------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- PID defaults ------------------------------------------------- */
    PIDGains gains = {1.0, 0.1, 0.01};
    PIDState state = {0.0, 0.0};
    double dt = (double)SAMPLE_PERIOD_US / 1.0e6;

    /* --- signals ------------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop ---------------------------------------------------- */
    int consec_errors = 0;

    while (g_running) {
        double temp = 0.0;
        bool ok = read_max31855(g_spi_handle, &temp);

        if (!ok) {
            consec_errors++;
            if (consec_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors — heater disabled\n");
                set_heater_duty(0);
                state.integral = 0.0;
                state.previous_error = 0.0;
                consec_errors = 0;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        consec_errors = 0;

        /* Failsafe */
        if (temp > MAX_TEMP || temp < MIN_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C — heater disabled\n", temp);
            set_heater_duty(0);
            state.integral = 0.0;
            state.previous_error = 0.0;
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pid_out = pid_compute(TARGET_TEMP, temp, gains, &state, dt);
        int duty = (int)(pid_out + 0.5);
        set_heater_duty(duty);

        log_data(g_log_file, temp, duty, pid_out);
        printf("Temp: %.2f C, Duty: %d%%, PID: %.2f\n", temp, duty, pid_out);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- graceful shutdown ------------------------------------------- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

