#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_LOW 40.0
#define TEMP_HIGH 70.0
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_temperature_to_duty_cycle(float temperature) {
    if (temperature <= TEMP_LOW) {
        return 0;
    } else if (temperature >= TEMP_HIGH) {
        return 100;
    } else {
        return (int)(((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW)) * 100.0);
    }
}

static int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

static int write_csv_header(void) {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp != NULL) {
        fclose(fp);
        return 0;
    }

    fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Error creating log file");
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set initial PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_csv_header() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = (float)gpioGetTemperature(FAN_GPIO);
        if (temperature < -100.0) {
            fprintf(stderr, "Error reading temperature\n");
        } else {
            int duty_cycle = map_temperature_to_duty_cycle(temperature);
            if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty_cycle);
            }
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Temperature: %.2f°C, Duty Cycle: %d%%\n", temperature, duty_cycle);
        }
        sleep(POLL_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");
    return EXIT_SUCCESS;
}

