/*
 * Raspberry Pi Zero W – Dual Sensirion SLF3S-1300F liquid flow sensor logger
 *
 * Wiring:
 *   I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 *   Sensor 1: address 0x41 (SF06 multiplexer channel 1)
 *   Sensor 2: address 0x42 (SF06 multiplexer channel 2)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 *   (run as root, or ensure /dev/i2c-1 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SENSOR1_ADDR         0x41
#define SENSOR2_ADDR         0x42
#define LOG_FILE             "flow_log.txt"
#define READ_RETRIES         3
#define POLL_INTERVAL_US     1000000   /* 1 second */

/* SLF3S-1300F: 3 bytes = 2 data + 1 CRC */
#define READ_LEN             3

static volatile sig_atomic_t g_running = 1;
static int g_handle1 = -1;
static int g_handle2 = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 3-byte frame from an SLF3S-1300F sensor                    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *flow_rate)
{
    uint8_t buf[READ_LEN];

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        int n = i2cReadDevice(handle, (char *)buf, READ_LEN);
        if (n == READ_LEN) {
            if (crc8(buf, 2) == buf[2]) {
                uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
                *flow_rate = (float)raw / 100.0f;   /* SLF3S-1300F: 1 LSB = 0.01 ml/min */
                return 0;
            }
            fprintf(stderr, "[WARN] CRC mismatch on handle %d (attempt %d)\n",
                    handle, attempt + 1);
        } else {
            fprintf(stderr, "[WARN] i2cReadDevice failed on handle %d (attempt %d): %d\n",
                    handle, attempt + 1, n);
        }
        gpioDelay(10000);   /* 10 ms back-off before retry */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flow-rate line to the log file                 */
/* ------------------------------------------------------------------ */
static int log_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, flow1, flow2);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_handle1 >= 0) {
        i2cClose(g_handle1);
        g_handle1 = -1;
    }
    if (g_handle2 >= 0) {
        i2cClose(g_handle2);
        g_handle2 = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C handles ------------------------------------------- */
    g_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_handle1 < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_handle2 < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_handle2);
        i2cClose(g_handle1);
        g_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow logger started.  Sensor1=0x%02X  Sensor2=0x%02X  Log=%s\n",
           SENSOR1_ADDR, SENSOR2_ADDR, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;

        if (read_sensor(g_handle1, &flow1) != 0)
            fprintf(stderr, "[ERROR] Sensor 1 (0x%02X) read failed after %d retries\n",
                    SENSOR1_ADDR, READ_RETRIES);

        if (read_sensor(g_handle2, &flow2) != 0)
            fprintf(stderr, "[ERROR] Sensor 2 (0x%02X) read failed after %d retries\n",
                    SENSOR2_ADDR, READ_RETRIES);

        if (log_data(flow1, flow2) != 0)
            fprintf(stderr, "[ERROR] Failed to write log entry\n");

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

