/*
 * ADPD144RI Red/IR Photometric Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - ADPD144RI on I2C bus 1, address 0x5C
 *   - LED + 330 Ω resistor on GPIO17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adpd144ri_logger adpd144ri_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./adpd144ri_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADPD144RI_ADDR       0x5C

#define RED_CHANNEL_REG      0x00
#define IR_CHANNEL_REG       0x02

#define GPIO_LED             17
#define IR_THRESHOLD         2000

#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define MAX_CONSECUTIVE_ERR  10

#define LOG_FILE_NAME        "adpd144ri_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function Prototypes ------------------------- */
static int  initialize_i2c(void);
static int  read_channel(uint8_t reg, uint16_t *value);
static int  log_data(uint16_t red, uint16_t ir);
static void control_led(uint16_t ir);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C Init -------------------------------- */
static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, ADPD144RI_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Read Channel Data ---------------------------- */
static int read_channel(uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cWriteByte(g_i2c_handle, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------- Log Data --------------------------------- */
static int log_data(uint16_t red, uint16_t ir)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%u,%u\n", timestamp, red, ir) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ------------------------------- LED Control ------------------------------ */
static void control_led(uint16_t ir)
{
    int level = (ir > IR_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GPIO_LED, level) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(LED=%d, %d) failed\n", GPIO_LED, level);
    }
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* --------------------------- Signal Handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    struct sigaction sa;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(LED=%d, OUTPUT) failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize I2C --- */
    if (initialize_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADPD144RI logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    uint16_t red = 0, ir = 0;
    int      consecutive_errors = 0;

    while (g_running) {
        if (read_channel(RED_CHANNEL_REG, &red) == 0 &&
            read_channel(IR_CHANNEL_REG,  &ir)  == 0) {
            consecutive_errors = 0;
            if (log_data(red, ir) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
            control_led(ir);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[ERROR] Sensor read failed (%d consecutive).\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] Max consecutive errors reached. "
                                "Sensor may be absent or bus error.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("ADPD144RI logger stopped.\n");
    return EXIT_SUCCESS;
}

