#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_US 10000  /* 10 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Select 60 dB gain: drive GAIN_SELECT_PIN LOW */
    if (gpioWrite(GAIN_SELECT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    int last_state = gpioRead(AUDIO_INPUT_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial read of GPIO%d failed.\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int current_state = gpioRead(AUDIO_INPUT_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: read of GPIO%d failed.\n", AUDIO_INPUT_PIN);
            break;
        }

        if (current_state != last_state) {
            if (log_event(current_state) != 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            }
            last_state = current_state;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("Audio event detection stopped.\n");
    return EXIT_SUCCESS;
}

