        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    int last_state = gpioRead(AUDIO_INPUT_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial read of GPIO%d failed.\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int current_state = gpioRead(AUDIO_INPUT_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: read of GPIO%d failed.\n", AUDIO_INPUT_PIN);
            break;
        }

        if (current_state != last_state) {
            if (log_event(current_state) != 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            }
            last_state = current_state;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    printf("Audio event detection stopped.\n");
