/*
 * flow_monitor.c — Raspberry Pi Zero W
 *
 * Continuously reads a Sensirion SLF3S-4000B liquid-flow sensor on I2C bus 1
 * (address 0x66) and logs timestamped flow-rate readings to flow_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x66
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000   /* 1 second */
#define READ_LEN       3         /* 2 data bytes + 1 CRC byte */

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion)                                                   */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_flow_rate(float flow_rate)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(g_log_file, "%s,%.2f\n", ts, flow_rate) < 0)
        perror("fprintf to log file");
    if (fflush(g_log_file) != 0)
        perror("fflush log file");
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and stores flow rate in *out_flow.
 * Returns -1 on I2C error, -2 on CRC mismatch.
 */
static int read_flow_rate(float *out_flow)
{
    uint8_t buf[READ_LEN];

    /*
     * SLF3S-4000B: trigger a measurement by writing 0x3608 to the
     * device (command 0x3608 = start continuous measurement).
     */
    uint8_t cmd[2] = { 0x36, 0x08 };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write (trigger) failed\n");
        return -1;
    }

    /*
     * The SLF3S-4000B needs ~45 ms to produce the first measurement.
     * We wait 50 ms to be safe.
     */
    gpioDelay(50000);

    /* Read 3 bytes: MSB, LSB, CRC */
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "I2C read failed (got %d bytes, expected %d)\n",
                n, READ_LEN);
        return -1;
    }

    /* Validate CRC */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -2;
    }

    /*
     * Flow rate is the 16-bit big-endian value.
     * The SLF3S-4000B reports flow rate in units of 1 / 60 s.
     * Convert to micro-litres per minute (uL/min) by multiplying
     * by 60 and scaling by the sensor's internal scaling factor.
     *
     * The exact scaling factor depends on the sensor variant and
     * the specific calibration; here we assume 1 LSB = 1 uL/min.
     */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out_flow = (float)raw * 60.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file open --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring flow rate. Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        float flow_rate;
        int rc = read_flow_rate(&flow_rate);

        if (rc == 0) {
            log_flow_rate(flow_rate);
            printf("Flow rate: %.2f uL/min\n", flow_rate);
        } else if (rc == -1) {
            /* I2C error: attempt recovery by re-opening the bus */
            fprintf(stderr, "I2C error — re-opening bus.\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Re-open failed (handle %d)\n", g_i2c_handle);
                g_running = 0;
            }
        }
        /* rc == -2: CRC failure — skip this sample */

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

