/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC sensor IAQ logger
 *
 * Wiring:
 *   VDD  -> 3V3 (Pin 1)
 *   GND  -> GND (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 * Run:
 *   sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define I2C_ADDR             0x69          /* MICS-VZ-89TE default I2C address */
#define LOG_FILE             "air_quality_log.csv"
#define SAMPLE_INTERVAL_S    5             /* seconds between samples */

/*
 * MICS-VZ-89TE register map (representative; adjust if your module
 * uses a different command set).
 */
#define REG_CMD              0x00
#define CMD_READ_DATA        0x01
#define REG_DATA_HIGH        0x01
#define REG_DATA_LOW         0x02
#define REG_DATA_TVOC_HIGH   0x03
#define REG_DATA_TVOC_LOW    0x04
#define REG_DATA_ECO2_HIGH   0x05
#define REG_DATA_ECO2_LOW    0x06

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_sensor_data(uint16_t *tvoc, uint16_t *eco2);
static float calculate_iaq(uint16_t tvoc, uint16_t eco2);
static int  log_data(float iaq, uint16_t tvoc, uint16_t eco2);
static void cleanup(void);

/* ----------------------------- Signal handler -------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* ------------------------------ I2C init ------------------------------- */

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ----------------------- Read sensor data (blocking) ------------------- */

static int read_sensor_data(uint16_t *tvoc, uint16_t *eco2)
{
    char cmd = CMD_READ_DATA;
    char buf[8];
    int  rc;

    /* Write the read-data command */
    rc = i2cWriteDevice(g_i2c_handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(cmd=0x%02X) failed: %d\n",
                (unsigned char)cmd, rc);
        return -1;
    }

    /* Small delay so the sensor has time to prepare the response */
    gpioDelay(2000);          /* 2 ms */

    /* Read 8 bytes: [cmd, hi, lo, hi, lo, hi, lo, hi, lo] */
    rc = i2cReadDevice(g_i2c_handle, buf, 8);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 8) {
        fprintf(stderr, "[ERROR] Short read: got %d bytes, expected 8\n", rc);
        return -1;
    }

    /*
     * Layout: [cmd, data_hi, data_lo, tvoc_hi, tvoc_lo, eco2_hi, eco2_lo, status]
     * We only use the first 6 bytes (data + TVOC + eCO2).
     */
    uint16_t raw_data   = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[2];
    *tvoc               = ((uint16_t)(uint8_t)buf[3] << 8) | (uint8_t)buf[4];
    *eco2               = ((uint16_t)(uint8_t)buf[5] << 8) | (uint8_t)buf[6];

    (void)raw_data;          /* silence unused warning */
    return 0;
}

/* --------------------------- Calculate IAQ index ------------------------ */

static float calculate_iaq(uint16_t tvoc, uint16_t eco2)
{
    /*
     * Placeholder IAQ formula.
     * Replace with a real calibration curve from your sensor datasheet.
     */
    return (float)tvoc * 0.1f + (float)eco2 * 0.01f;
}

/* ------------------------------ Log data ------------------------------- */

static int log_data(float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f,%u,%u\n",
                timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------ Cleanup -------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- main -------------------------------- */

int main(void)
{
    uint16_t tvoc = 0, eco2 = 0;
    float    iaq  = 0.0f;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,iaq_index,tvoc_ppb,eco2_ppm\n");
        fflush(g_log_file);
    }

    /* --- Initialize I2C --- */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signals\n");
    }

    printf("Air quality monitoring started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_sensor_data(&tvoc, &eco2) == 0) {
            iaq = calculate_iaq(tvoc, eco2);
            if (log_data(iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing\n");
            }
            printf("IAQ: %.2f  TVOC: %u ppb  eCO2: %u ppm\n",
                   iaq, tvoc, eco2);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);          /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

