/*
 * TTP223B capacitive touch sensor intrusion detector for Raspberry Pi 5.
 *
 * Wiring:
 *   TTP223B VCC  -> 3.3 V (pin 1)
 *   TTP223B GND  -> GND   (pin 9)
 *   TTP223B OUT  -> GPIO17 (pin 11, BCM 17)
 *
 * The TTP223B OUT line reads HIGH while the sensor is touched and LOW
 * when released.  A 10 kΩ pull-down resistor is recommended on the OUT
 * line so that it reads LOW when the sensor is disconnected.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp223_intrusion ttp223_intrusion.c -lpigpio -lrt
 * Run:    sudo ./ttp223_intrusion
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN          17          /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_US  100000      /* 100 ms */
#define ALERT_THRESHOLD_S  5          /* seconds */
#define CONSUMER_LABEL    "ttp223_tamper"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timing                                                              */
/* ------------------------------------------------------------------ */

static double elapsed_seconds(const struct timespec *start,
                              const struct timespec *end)
{
    return (double)(end->tv_sec - start->tv_sec)
         + (double)(end->tv_nsec - start->tv_nsec) / 1.0e9;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Release the GPIO line and terminate the pigpio library. */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* unregister callback */
    gpioSetMode(GPIO_PIN, PI_INPUT);            /* return to input     */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Alert                                                               */
/* ------------------------------------------------------------------ */

static void print_intrusion_alert(void)
{
    printf("[ALERT] Tamper detection: continuous touch on GPIO %d for "
           "%d seconds!\n", GPIO_PIN, ALERT_THRESHOLD_S);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback                                               */
/* ------------------------------------------------------------------ */

/*
 * pigpio dispatches this callback on the pigpio thread.  We keep the
 * logic here to a minimum: we only update the timer and print the
 * alert when the sensor is HIGH for the configured threshold.
 */
static void alert_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    static struct timespec touch_start = {0, 0};
    static int      touched          = 0;
    static int      alert_fired      = 0;

    if (level == 1) {                       /* HIGH  -> touched */
        if (!touched) {
            clock_gettime(CLOCK_MONOTONIC, &touch_start);
            touched = 1;
            alert_fired = 0;
        }
    } else if (level == 0) {                /* LOW   -> released */
        touched = 0;
    }
    /* level == PI_TIMEOUT / other: ignore */

    if (touched && !alert_fired) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = elapsed_seconds(&touch_start, &now);
        if (elapsed >= (double)ALERT_THRESHOLD_S) {
            print_intrusion_alert();
            alert_fired = 1;
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Enable the internal pull-down so that the line reads LOW when the
     * sensor is disconnected.  The TTP223B already has an on-board
     * pull-up/pull-down; this external pull is a safety net.
     */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed.\n",
                GPIO_PIN);
        /* non-fatal: continue anyway */
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, alert_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(%d) failed.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TTP223B intrusion detector running on GPIO %d.\n"
           "Threshold: %d s.  Press Ctrl+C to exit.\n",
           GPIO_PIN, ALERT_THRESHOLD_S);
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        gpioDelay(POLL_INTERVAL_US);   /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

