/*
 * INMP441 I2S MEMS Microphone Capture for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   INMP441 SCK  -> GPIO18 (I2S SCLK)
 *   INMP441 WS   -> GPIO19 (I2S LRCLK)
 *   INMP441 SD   -> GPIO21 (I2S DOUT)
 *   INMP441 L/R  -> GPIO17 (I2S LRSEL)
 *   INMP441 VDD  -> 3.3 V
 *   INMP441 GND  -> GND
 *
 * The L/R channel-select line (GPIO17) is driven HIGH to select the left
 * channel and LOW to select the right channel.  The I2S bus is opened via
 * the ALSA PCM subsystem (/dev/snd/pcmC0D0c on Raspberry Pi 4).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o audio_capture audio_capture.c -lasound -lpthread
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/soundcard.h>
#include <pthread.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define CHANNEL_SELECT_PIN 17
#define SAMPLE_FILE     "audio_capture.pcm"
#define SAMPLE_RATE     48000
#define NUM_CHANNELS    2
#define BITS_PER_SAMPLE 16
#define FRAMES_PER_BUF  1024
#define BUFFER_BYTES    (FRAMES_PER_BUF * NUM_CHANNELS * (BITS_PER_SAMPLE / 8))

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers using the Linux GPIO character-device interface        */
/* ------------------------------------------------------------------ */

static int gpio_export(unsigned int pin)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY)
            return 0;                       /* already exported */
        perror("open(/sys/class/gpio/export)");
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%u", pin);
    if (write(fd, buf, (size_t)len) != len) {
        perror("write(/sys/class/gpio/export)");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(unsigned int pin, const char *dir)
{
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/direction", pin);
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "GPIO path too long\n");
        return -1;
    }
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open(direction)");
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        perror("write(direction)");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(unsigned int pin, int value)
{
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/value", pin);
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "GPIO path too long\n");
        return -1;
    }
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open(value)");
        return -1;
    }
    char val = (char)(value ? '1' : '0');
    if (write(fd, &val, 1) != 1) {
        perror("write(value)");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* ALSA PCM helpers                                                    */
/* ------------------------------------------------------------------ */

static int alsa_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(ALSA PCM)");
        return -1;
    }
    return fd;
}

static int alsa_hw_params(int fd, int channels, int rate, int bits)
{
    struct snd_pcm_hw_params *params;
    snd_pcm_hw_params_alloca(&params);

    if (ioctl(fd, SNDRV_PCM_IOCTL_HW_PARAMS_CURRENT, params) < 0) {
        perror("ioctl(SNDRV_PCM_IOCTL_HW_PARAMS_CURRENT)");
        return -1;
    }

    unsigned int fmt = (bits == 16) ? SNDRV_PCM_FORMAT_S16_LE : SNDRV_PCM_FORMAT_S32_LE;

    if (snd_pcm_hw_params_set_access(fd, params, SNDRV_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        perror("snd_pcm_hw_params_set_access");
        return -1;
    }
    if (snd_pcm_hw_params_set_format(fd, params, fmt) < 0) {
        perror("snd_pcm_hw_params_set_format");
        return -1;
    }
    if (snd_pcm_hw_params_set_channels(fd, params, channels) < 0) {
        perror("snd_pcm_hw_params_set_channels");
        return -1;
    }
    if (snd_pcm_hw_params_set_rate_near(fd, params, (unsigned int *)&rate, 0) < 0) {
