#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <linux/soundcard.h>
#include <pthread.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define CHANNEL_SELECT_PIN 17
#define SAMPLE_FILE     "audio_capture.pcm"
#define SAMPLE_RATE     48000
#define NUM_CHANNELS    2
#define BITS_PER_SAMPLE 16
#define FRAMES_PER_BUF  1024
#define BUFFER_BYTES    (FRAMES_PER_BUF * NUM_CHANNELS * (BITS_PER_SAMPLE / 8))

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers using the Linux GPIO character-device interface        */
/* ------------------------------------------------------------------ */

static int gpio_export(unsigned int pin)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY)
            return 0;                       /* already exported */
        perror("open(/sys/class/gpio/export)");
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%u", pin);
    if (write(fd, buf, (size_t)len) != len) {
        perror("write(/sys/class/gpio/export)");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(unsigned int pin, const char *dir)
{
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/direction", pin);
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "GPIO path too long\n");
        return -1;
    }
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open(direction)");
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        perror("write(direction)");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(unsigned int pin, int value)
{
    char path[64];
    int len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%u/value", pin);
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "GPIO path too long\n");
        return -1;
    }
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("open(value)");
        return -1;
    }
    char val = (char)(value ? '1' : '0');
    if (write(fd, &val, 1) != 1) {
        perror("write(value)");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

