        perror("snd_pcm_hw_params_set_channels");
        return -1;
    }
    if (snd_pcm_hw_params_set_rate_near(fd, params, (unsigned int *)&rate, 0) < 0) {
        perror("snd_pcm_hw_params_set_rate_near");
        return -1;
    }
    if (snd_pcm_hw_params(fd, params) < 0) {
        perror("snd_pcm_hw_params");
        return -1;
    }
    return 0;
}

static int alsa_prepare(int fd)
{
    if (ioctl(fd, SNDRV_PCM_IOCTL_PREPARE) < 0) {
        perror("ioctl(SNDRV_PCM_IOCTL_PREPARE)");
        return -1;
    }
    return 0;
}

static int alsa_start(int fd)
{
    if (ioctl(fd, SNDRV_PCM_IOCTL_START) < 0) {
        perror("ioctl(SNDRV_PCM_IOCTL_START)");
        return -1;
    }
    return 0;
}

static int alsa_readi(int fd, void *buffer, size_t size)
{
    ssize_t n = read(fd, buffer, size);
    if (n < 0) {
        perror("read(ALSA PCM)");
        return -1;
    }
    if ((size_t)n != size) {
        fprintf(stderr, "Short read: %zd of %zu bytes\n", n, size);
        return -1;
    }
    return 0;
}

static int alsa_drain(int fd)
{
    if (ioctl(fd, SNDRV_PCM_IOCTL_DRAIN) < 0) {
        perror("ioctl(SNDRV_PCM_IOCTL_DRAIN)");
        return -1;
    }
    return 0;
}

static int alsa_close(int fd)
{
    if (close(fd) < 0) {
        perror("close(ALSA PCM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int pcm_fd = -1;
    int gpio_fd = -1;
    FILE *out = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() < 0) {
        perror("sigaction");
        goto cleanup;
    }

    /* Export and configure GPIO17 as output */
    if (gpio_export(CHANNEL_SELECT_PIN) < 0)
