    if (alsa_prepare(pcm_fd) < 0)
        goto cleanup;

    /* Start device */
    if (alsa_start(pcm_fd) < 0)
        goto cleanup;

    /* Open output file */
    out = fopen(SAMPLE_FILE, "wb");
    if (!out) {
        perror("fopen(output)");
        goto cleanup;
    }

    /* Main acquisition loop */
    while (g_running) {
