/*
 * Flame Detection System for Raspberry Pi 4 Model B
 * Sensor : SainSmart IR Flame Sensor Module (LM393 comparator)
 * Wiring : DO  -> GPIO4  (BCM 4, physical pin 7)
 *          VCC -> 3.3 V
 *          GND -> GND
 * Fan    : PWM signal on GPIO18 (BCM 18, physical pin 12)
 *          Use a logic-level MOSFET gate driver (e.g. IRLZ44N)
 *          between GPIO18 and the fan's PWM input.
 *
 * Build  : gcc -O2 -Wall -Wextra -o flame_detect flame_detect.c -lpigpio -lrt
 * Run    : sudo ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4          /* BCM 4  – digital output from sensor */
#define FAN_PWM_PIN      18         /* BCM 18 – hardware PWM output to fan */
#define PWM_FREQUENCY    100        /* Hz */
#define PWM_RANGE        1000       /* duty-cycle range 0–1000 */
#define PWM_DUTY_ON      700        /* 70 % of 1000 */
#define DEBOUNCE_MS      50         /* ms debounce between readings */
#define POLL_INTERVAL_US 50000      /* 50 ms between sensor polls */
#define SENSOR_TIMEOUT_S 5          /* seconds without a valid reading → sensor absent */
#define LOG_FILE         "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log, "%s %s\n", ts, msg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-up so the input is defined when the sensor is absent. */
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", FLAME_SENSOR_PIN);
    }

    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", FAN_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with fan off. */
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", FAN_PWM_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop fan first for safety. */
    if (gpioPWM(FAN_PWM_PIN, 0) != 0)
        fprintf(stderr, "Warning: failed to stop PWM during cleanup.\n");

    /* Reset pin modes to a safe input state. */
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PWM_PIN,     PI_INPUT);

    gpioTerminate();

    if (g_log) {
        log_event("Program terminated.");
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log file in append mode. */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_event("Program started.");

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Initialize pigpio and GPIO pins. */
    if (init_gpio() != 0) {
        fclose(g_log);
        return EXIT_FAILURE;
    }

    log_event("GPIO initialised: sensor input on GPIO4, fan PWM on GPIO18.");

    int fan_on = 0;
    time_t last_valid = time(NULL);

    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_PIN);

        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", FLAME_SENSOR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        last_valid = time(NULL);

        /* LOW (0) => flame detected (active-low sensor). */
        if (level == 0) {
            if (!fan_on) {
                if (gpioPWM(FAN_PWM_PIN, PWM_DUTY_ON) == 0) {
                    fan_on = 1;
                    log_event("Flame detected – fan activated.");
                } else {
                    fprintf(stderr, "Error: gpioPWM failed to start fan.\n");
                }
            }
        } else {
            /* No flame – ensure fan is off. */
            if (fan_on) {
                if (gpioPWM(FAN_PWM_PIN, 0) == 0) {
                    fan_on = 0;
                    log_event("Flame cleared – fan deactivated.");
                } else {
                    fprintf(stderr, "Error: gpioPWM failed to stop fan.\n");
                }
            }
        }

        gpioDelay(DEBOUNCE_MS * 1000); /* 50 ms debounce */
    }

    /* Sensor-absent timeout path. */
    if (!fan_on) {
        time_t now = time(NULL);
        if (difftime(now, last_valid) > SENSOR_TIMEOUT_S) {
            log_event("Sensor timeout: no valid reading for >5 s – sensor may be absent.");
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

