/*
 * AWR1642 mmWave radar SPI capture for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   AWR1642 SPI_CLK  -> GPIO11 (SCLK)
 *   AWR1642 SPI_MISO -> GPIO9  (MISO)
 *   AWR1642 SPI_MOSI -> GPIO10 (MOSI)
 *   AWR1642 SPI_CS   -> GPIO8  (CE0)
 *   AWR1642 TRIGGER -> GPIO23 (BCM)
 *   AWR1642 DATA_READY -> GPIO24 (BCM)
 *
 * The AWR1642 is pre-configured via the TI mmWave SDK to stream range-Doppler
 * data.  This program captures heatmap frames at 100 ms intervals and logs
 * them to a binary file with a header:
 *
 *   uint32_t magic = 0x1008
 *   uint32_t version = 0x0001
 *   uint64_t timestamp
 *   struct {
 *     uint32_t start_frequency_hz
 *     uint32_t end_frequency_hz
 *     uint32_t num_chirps
 *     uint32_t num_samples
 *   } config
 *   ... per-frame timestamps and frame numbers ...
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000
#define SPI_MODE          0
#define SPI_BITS_PER_WORD 8

#define TRIGGER_PIN       23
#define DATA_READY_PIN    24

#define FRAME_PERIOD_US   100000   /* 100 ms */
#define FRAME_SIZE_BYTES  32768    /* 1024 chirps × 32 samples */

#define LOG_FILE_NAME     "radar_data.bin"
#define LOG_MAGIC         0x1008
#define LOG_VERSION       0x0001

/* AWR1642 pre-configured range-Doppler parameters */
#define START_FREQUENCY_HZ 7700000000ULL
#define END_FREQUENCY_HZ   7900000000ULL
#define NUM_CHIRPS         64
#define NUM_SAMPLES        256

struct radar_config {
    uint32_t start_frequency_hz;
    uint32_t end_frequency_hz;
    uint32_t num_chirps;
    uint32_t num_samples;
};

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;
static uint64_t g_log_start_ns = 0;

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

static void spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE_NAME, "wb");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE_NAME ")");
        return -1;
    }

    struct {
        uint32_t magic;
        uint32_t version;
        uint64_t timestamp;
        struct radar_config config;
    } hdr;

    hdr.magic      = LOG_MAGIC;
    hdr.version    = LOG_VERSION;
    hdr.timestamp  = 0;
    hdr.config.start_frequency_hz = START_FREQUENCY_HZ;
    hdr.config.end_frequency_hz   = END_FREQUENCY_HZ;
    hdr.config.num_chirps         = NUM_CHIRPS;
    hdr.config.num_samples        = NUM_SAMPLES;

    if (fwrite(&hdr, sizeof(hdr), 1, g_log_fp) != 1) {
        perror("fwrite(header)");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
    }

    g_log_start_ns = g_log_fp ? (uint64_t)ftell(g_log_fp) : 0;
    return 0;
}

static void log_close(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

static int log_write_frame(uint64_t timestamp_ns, uint32_t frame_number,
                           const uint8_t *data, size_t len)
{
    if (!g_log_fp)
        return -1;

    if (fwrite(&timestamp_ns, sizeof(timestamp_ns), 1, g_log_fp) != 1)
        return -1;
    if (fwrite(&frame_number, sizeof(frame_number), 1, g_log_fp) != 1)
        return -1;
    if (fwrite(data, 1, len, g_log_fp) != len)
        return -1;

    fflush(g_log_fp);
    return 0;
}

/*
 * Full-duplex SPI transfer: send trigger command, then read the
 * response frame.  The AWR1642 protocol requires a 100 µs CS setup
 * time; gpioDelay() is sufficient for that on the Pi.
 */
static int spi_transfer_frame(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- pigpio init (GPIO23/24) --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 0);

    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(DATA_READY) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    if (log_open() < 0) {
        spi_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Radar data capture started.  Logging to %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to stop.\n");

    uint32_t frame_number = 0;
    uint8_t *tx = malloc(FRAME_SIZE_BYTES);
    uint8_t *rx = malloc(FRAME_SIZE_BYTES);
    if (!tx || !rx) {
        fprintf(stderr, "malloc failed\n");
        free(tx); free(rx);
        log_close();
        spi_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        /* Issue a frame-request trigger (active-low pulse) */
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(10);                 /* 10 µs setup */
        gpioWrite(TRIGGER_PIN, 1);

        /* Wait for DATA_READY (max 1 s) */
        int ready = 0;
        for (int i = 0; i < 100 && g_running; i++) {
            if (gpioRead(DATA_READY_PIN) == 1) { ready = 1; break; }
            gpioDelay(10000);          /* 10 ms */
        }
        if (!ready) {
            fprintf(stderr, "Warning: DATA_READY timeout, skipping frame\n");
            continue;
        }

        /* Full-duplex transfer: send dummy (0x00) and capture frame */
        memset(tx, 0x00, FRAME_SIZE_BYTES);
        memset(rx, 0x00, FRAME_SIZE_BYTES);

        if (spi_transfer_frame(tx, rx, FRAME_SIZE_BYTES) < 0) {
            fprintf(stderr, "SPI transfer failed, skipping frame\n");
            continue;
        }

        /* Timestamp in nanoseconds since log start */
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL
                              + (uint64_t)ts.tv_nsec;

        if (log_write_frame(timestamp_ns - g_log_start_ns,
                            frame_number, rx, FRAME_SIZE_BYTES) < 0) {
            fprintf(stderr, "Failed to write frame %u\n", frame_number);
            break;
        }

        frame_number++;

        /* 100 ms period (minus transfer time) */
        gpioDelay(FRAME_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    free(tx);
    free(rx);
    log_close();
    spi_close();
    gpioWrite(TRIGGER_PIN, 1);
    gpioTerminate();

    return EXIT_SUCCESS;
}

