/*
 * Flame sensor monitor for Raspberry Pi Zero W
 * Sensor : KY-026 flame sensor (digital output)
 * Pin    : GPIO20 (BCM), physical pin 38
 * Log    : flame_log.txt (ISO-8601 UTC timestamps)
 *
 * Build  : gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run    : sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 20          /* BCM pin 20, physical pin 38 */
#define LOG_FILE          "flame_log.txt"
#define POLL_DELAY_US     100000       /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Write an ISO-8601 UTC timestamp into buf (size >= 25).
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now;
    struct tm tm_utc;

    if (time(&now) == (time_t)-1) {
        return -1;
    }

    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }

    return 0;
}

/*
 * Append a single CSV line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(const char *timestamp, const char *state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%s\n", timestamp, state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_FAILURE;
    int last_state = -1;          /* unknown initial state */
    char timestamp[32];

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
