/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL  -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_logger light_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS         "/dev/i2c-1"
#define OPT3001_ADDR    0x44

/* OPT3001 register addresses */
#define REG_RESULT      0x00
#define REG_CONFIG      0x01
#define REG_MANUFACT_ID 0x7E
#define REG_DEVICE_ID   0x7F

/*
 * Configuration register (0x01) bit layout (16-bit, big-endian on bus):
 *   [15]    RN[2:0]   Range number
 *   [14:13] M[2:0]    Mode of conversion
 *   [12]    CT        Conversion time
 *   [11:6]  OVF       Overflow flag
 *   [5:4]   CRF       Conversion ready flag
 *   [3]     FL        Flag low
 *   [2]     L         Latch
 *   [1]     POL       Polarity
 *   [0]     ME        Mask exponent
 *
 * 0xC800 -> 1100 1000 0000 0000
 *   RN=100 (auto-range), M=000 (continuous), CT=0, ME=0, all flags clear
 */
#define CONFIG_VALUE    0xC800

/* Conversion time: 100 ms for auto-range, 800 ms for manual range */
#define CONVERSION_MS   100

#define LOG_FILE        "light_data.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit big-endian value to an OPT3001 register. */
static int opt3001_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from an OPT3001 register. */
static int opt3001_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Initialize the OPT3001: verify manufacturer ID and configure range. */
static int opt3001_init(int fd)
{
    uint16_t manuf_id = 0, device_id = 0;

    if (opt3001_read_reg(fd, REG_MANUFACT_ID, &manuf_id) != 0)
        return -1;
    if (manuf_id != 0x5449) {
        fprintf(stderr, "Manufacturer ID mismatch: 0x%04X (expected 0x5449)\n",
                manuf_id);
        return -1;
    }

    if (opt3001_read_reg(fd, REG_DEVICE_ID, &device_id) != 0)
        return -1;
    printf("OPT3001 detected (Manufacturer ID: 0x%04X, Device ID: 0x%04X)\n",
           manuf_id, device_id);

    if (opt3001_write_reg(fd, REG_CONFIG, CONFIG_VALUE) != 0)
        return -1;

    return 0;
}

/* Read the raw 16-bit result and convert to lux. */
static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw = 0;

    if (opt3001_read_reg(fd, REG_RESULT, &raw) != 0)
        return -1;

    /*
     * Result register (0x00) format (16-bit, big-endian):
     *   [15:12] Exponent
     *   [11:0]  Mantissa
     *
     * Conversion: lux = mantissa * 0.01 * (2 ^ exponent)
     */
    uint8_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1UL << exponent);
    return 0;
}

/* Append a timestamped lux reading to the log file. */
static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f lux\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret_code = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the OPT3001 slave address */
    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the sensor */
    if (opt3001_init(fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed (sensor may be absent or bus error)\n");
        goto cleanup;
    }

    printf("Logging OPT3001 data to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_MS);

    /* Main sampling loop */
    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(fd, &lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read lux value\n");
        }

        /* Sleep for the sample interval, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_INTERVAL_MS && g_running; ms += 10) {
            usleep(10 * 1000);
        }
    }

    printf("\nShutting down cleanly...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret_code;
}

