/*
 * flame_detect.c — Read SainSmart IR Flame Detection Sensor Module
 *                 over the GPIO character-device interface (libgpiod v2).
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 * Run:    ./flame_detect   (user must have access to /dev/gpiochip0)
 *
 * Wiring:
 *   VCC  -> 3V3 (Pin 1)
 *   GND  -> GND (Pin 9)
 *   DOUT -> GPIO17 (Pin 11, BCM 17)
 *
 * The SainSmart module has an active-low output: 0 = flame detected,
 * 1 = no flame.  We invert the logic so the program prints "YES" when
 * the sensor reads 0 and "NO" when it reads 1.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

