 *   TTP226 OUT1 -> GPIO2 (BCM 2)
 *   TTP226 OUT2 -> GPIO3 (BCM 3)
 *   TTP226 OUT3 -> GPIO4 (BCM 4)
 *   TTP226 OUT4 -> GPIO5 (BCM 5)
 *   TTP226 OUT5 -> GPIO6 (BCM 6)
 *   TTP226 OUT6 -> GPIO7 (BCM 7)
 *   TTP226 OUT7 -> GPIO8 (BCM 8)
 *   TTP226 OUT8 -> GPIO9 (BCM 9)
 *   TTP226 VCC  -> 3.3 V
 *   TTP226 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c \
 *       -lpigpio -lrt
 * Run:
 *   sudo ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* TTP226 output pins on the Raspberry Pi 3 Model B+ (BCM numbering). */
static const int OUT_PINS[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(OUT_PINS[i], PI_INPUT) != 0) {
            fprintf(stderr,
                    "Error: gpioSetMode failed for BCM pin %d.\n",
                    OUT_PINS[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(OUT_PINS[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr,
                    "Error: gpioSetPullUpDown failed for BCM pin %d.\n",
                    OUT_PINS[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* TTP226 driver API                                                   */
/* ------------------------------------------------------------------ */

/*
 * Read all eight channels into the caller-provided array.
 * Returns 0 on success, -1 on error.
 */
static int read_ttp226(uint8_t *values)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int level = gpioRead(OUT_PINS[i]);
        if (level < 0) {
            fprintf(stderr,
                    "Error: gpioRead failed for BCM pin %d.\n",
                    OUT_PINS[i]);
            return -1;
        }
        values[i] = (uint8_t)level;
    }
    return 0;
}

