/* Timing helper                                                       */
/* ------------------------------------------------------------------ */

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[+%ldms] ", (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L));
    } else {
