/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (pin 29)
 *   VCC -> 3.3 V, GND -> GND
 *   (External pull-ups on both OUT pins to 3.3 V)
 *
 * The TMAG5110 open-drain output reads HIGH when the magnetic field is
 * absent and LOW when a magnet is detected.
 *
 * Build: gcc -Wall -o hall_effect hall_effect.c -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * TMAG5110 open-drain output:
     *   HIGH  -> no magnet detected
     *   LOW   -> magnet present
     * External pull-ups keep the line defined when the sensor is absent.
     */
    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Sensor 1: BCM GPIO%d | Sensor 2: BCM GPIO%d\n", SENSOR_1_PIN, SENSOR_2_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1 == 0 ? "MAGNET_DETECTED" : "NO_MAGNET",
               s2 == 0 ? "MAGNET_DETECTED" : "NO_MAGNET");

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

