/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4.
 *
 * Wiring (BCM numbering):
 *   CH1 -> GPIO2  (physical pin 3)
 *   CH2 -> GPIO3  (physical pin 5)
 *   CH3 -> GPIO4  (physical pin 7)
 *   CH4 -> GPIO17 (physical pin 11)
 *   CH5 -> GPIO27 (physical pin 13)
 *   CH6 -> GPIO22 (physical pin 15)
 *   CH7 -> GPIO10 (physical pin 19)
 *   CH8 -> GPIO9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lpigpio -lrt
 * Run:    sudo ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000   /* 50 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write an ISO-8601 timestamp into buf (size >= 25).
 * Returns 0 on success, -1 on failure.
 */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0)
        return -1;

    return 0;
}

/*
 * Read all eight channels.
 * Returns 0 on success, -1 on failure.
 */
static int read_all_channels(int *states)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int v = gpioRead(channel_pins[i]);
        if (v < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d: %s\n",
                    channel_pins[i], pigpio_error(v));
            return -1;
        }
        states[i] = v;
    }
    return 0;
}

/*
 * Request the eight GPIO lines as inputs with bias disabled.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_gpio(void)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int rc = gpioSetMode(channel_pins[i], PI_INPUT);
        if (rc < 0) {
            fprintf(stderr, "gpioSetMode failed on GPIO%d: %s\n",
                    channel_pins[i], pigpio_error(rc));
            return -1;
        }

        rc = gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF);
        if (rc < 0) {
            fprintf(stderr, "gpioSetPullUpDown failed on GPIO%d: %s\n",
                    channel_pins[i], pigpio_error(rc));
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */

int main(void)
{
    int states[NUM_CHANNELS];
    char timestamp[32];

    /* --- Install SIGINT handler for graceful shutdown -------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO lines --------------------------------------- */
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    printf("Timestamp,CH1,CH2,CH3,CH4,CH5,CH6,CH7,CH8\n");
    fflush(stdout);

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        if (read_all_channels(states) != 0) {
            fprintf(stderr, "Error reading sensor data; continuing.\n");
        } else {
            if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                fprintf(stderr, "Error generating timestamp; continuing.\n");
            } else {
                printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
                       timestamp,
                       states[0], states[1], states[2], states[3],
                       states[4], states[5], states[6], states[7]);
                fflush(stdout);
            }
        }

        /* Sleep 50 ms while remaining responsive to SIGINT */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(POLL_DELAY_US / 10);
    }

    /* --- Cleanup ---------------------------------------------------- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

