code:
/*
 * Raspberry Pi Zero W – Omron D7E-1 tilt sensor monitor
 *
 * Wiring:
 *   D7E-1 VCC  -> 3.3 V (pin 1)
 *   D7E-1 GND  -> GND   (pin 9)
 *   D7E-1 OUT  -> GPIO4 (BCM 4, pin 7)  [internal pull-up enabled]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_PIN 4          /* BCM 4, physical pin 7 */
#define POLL_DELAY_US 100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * Initialise the tilt sensor pin as input with the internal pull-up
 * enabled.  Returns 0 on success, -1 on failure.
 */
static int init_tilt_pin(void)
{
    if (gpioSetMode(TILT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", TILT_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(TILT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", TILT_PIN);
        return -1;
    }

    return 0;
}

/*
 * Read the tilt sensor pin.  Returns 0 or 1 on success, -1 on failure.
 */
static int read_tilt_pin(void)
{
    int level = gpioRead(TILT_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed for pin %d\n", TILT_PIN);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_tilt_state(int tilted)
{
    if (tilted) {
        printf("Tilted\n");
    } else {
        printf("Not Tilted\n");
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_tilt_pin() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d. Press Ctrl-C to exit.\n",
           TILT_PIN);
    fflush(stdout);

    int last_tilt = -1;   /* force initial print */

    while (g_running) {
        int tilt = read_tilt_pin();
        if (tilt < 0) {
            ret = EXIT_FAILURE;
            break;
        }

        if (tilt != last_tilt) {
            log_tilt_state(tilt);
            last_tilt = tilt;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /*
     * Always invoke gpioTerminate() on every exit path so that the
     * pigpio daemon is told to release any resources held by the
     * library.
     */
    gpioTerminate();

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

