#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX0 0x2C

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE, 0x08) < 0) {
        return -1;
    }
    return 0;
}

static int read_uv_index(int fd, uint8_t *uv_index) {
    return i2c_read_reg8(fd, SI1145_REG_UV_INDEX0, uv_index);
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t data[2];
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &data[0]) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &data[1]) < 0) {
        return -1;
    }
    *als_visible = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static void log_data(FILE *fp, uint8_t uv_index, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, uv_index, als_visible);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,UV Index,ALS Visible\n");
        fflush(log_file);
    }

    printf("Si1145 sensor initialized. Logging to uv_als_log.csv. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t uv_index;
        uint16_t als_visible;

        if (read_uv_index(i2c_fd, &uv_index) < 0) {
            fprintf(stderr, "Error reading UV index.\n");
        } else if (read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible light.\n");
        } else {
            printf("UV Index: %u, ALS Visible: %u\n", uv_index, als_visible);
            log_data(log_file, uv_index, als_visible);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

