#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define SENSOR1_ADDR    0x41
#define SENSOR2_ADDR    0x42
#define ALARM_GPIO      17
#define FLOW_THRESHOLD  0.5f
#define LOG_FILE        "flow_log.txt"
#define SAMPLE_PERIOD_S 1
#define STARTUP_DELAY_MS 100

/* SLF3S-0600F commands (16-bit, big-endian on the bus) */
#define CMD_START_MEAS  0x362F
#define CMD_READ_MEAS   0x3663

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion 8-bit CRC (polynomial 0x31, init 0xFF)                     */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write 0x%04X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int fd, float *out)
{
    uint8_t buf[9];

    if (i2c_write_cmd(fd, CMD_READ_MEAS) != 0)
        return -1;

    /* Datasheet: read 9 bytes: 2 flow + 1 CRC, 2 temp + 1 CRC, 2 status + 1 CRC */
    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRCs */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Flow CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Status CRC mismatch\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out = (float)raw / 60.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Alarm control                                                       */
/* ------------------------------------------------------------------ */
static void set_alarm(int on)
{
    gpioWrite(ALARM_GPIO, on ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float f1, float f2, float avg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log, "%s, Sensor1: %.2f, Sensor2: %.2f, Average: %.2f\n",
            ts, f1, f2, avg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SENSOR1_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Start sensors --- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR1_ADDR) < 0 ||
        i2c_write_cmd(g_i2c_fd, CMD_START_MEAS) != 0) {
        fprintf(stderr, "Sensor 1 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR2_ADDR) < 0 ||
        i2c_write_cmd(g_i2c_fd, CMD_START_MEAS) != 0) {
        fprintf(stderr, "Sensor 2 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after ~100 ms */
    usleep(STARTUP_DELAY_MS * 1000);

    /* --- Main loop --- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int   ok1 = 0, ok2 = 0;

        if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR1_ADDR) == 0) {
            if (read_flow_rate(g_i2c_fd, &f1) == 0) ok1 = 1;
        }
        if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR2_ADDR) == 0) {
            if (read_flow_rate(g_i2c_fd, &f2) == 0) ok2 = 1;
        }

        float avg = (ok1 && ok2) ? (f1 + f2) / 2.0f : 0.0f;

        if (ok1 && ok2) {
            set_alarm(avg < FLOW_THRESHOLD);
        } else {
            set_alarm(0);
        }

        log_data(f1, f2, avg);

        sleep(SAMPLE_PERIOD_S);
    }

    /* --- Graceful shutdown --- */
    set_alarm(0);
    cleanup();
    return EXIT_SUCCESS;
}

