#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM pin 7 */
#define BUFFER_SIZE     100
#define SAMPLE_US       50000      /* 50 ms */

typedef struct {
    time_t timestamp;
    bool   obstacle_detected;     /* true if sensor output is LOW (obstacle) */
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int  buffer_index = 0;
static int  buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void add_to_buffer(time_t ts, bool detected)
{
    circular_buffer[buffer_index].timestamp       = ts;
    circular_buffer[buffer_index].obstacle_detected = detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void dump_buffer(void)
{
    printf("\n--- Sensor Data Dump (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        localtime_r(&circular_buffer[idx].timestamp, &tm_info);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Obstacle: %s\n",
               time_str,
               circular_buffer[idx].obstacle_detected ? "DETECTED" : "clear");
    }
    printf("--- End of Dump ---\n");
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pin as input with internal pull-up --- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance sensor monitoring started.\n");
    printf("  Sensor pin : BCM GPIO%d (physical pin 7)\n", SENSOR_PIN);
    printf("  Sampling   : every %d ms\n", SAMPLE_US / 1000);
    printf("  Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on pin %d (code %d).\n",
                    SENSOR_PIN, level);
            gpioDelay(SAMPLE_US);
            continue;
        }

        bool obstacle = (level == 0);   /* LOW => obstacle detected */
        time_t now = time(NULL);
        add_to_buffer(now, obstacle);

        if (obstacle)
            printf("[%ld] Obstacle detected!\n", (long)now);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    dump_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

