/*
 * fan_health.c — Raspberry Pi 5 (Bookworm)
 *
 * Reads X/Y/Z acceleration from an Omron D7S vibration sensor on I2C bus 1
 * (GPIO2 = SDA, GPIO3 = SCL) at up to 400 kHz, logs timestamped samples
 * to fan_health.csv, and exits cleanly on SIGINT / SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- I2C / D7S constants ------------------------------------------------ */
#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x20          /* D7S default 7-bit I2C address */
#define D7S_REG_MODE   0x00          /* Mode register (write 0x01 = active) */
#define D7S_REG_X_L    0x10          /* X-axis acceleration low byte */
#define D7S_REG_X_H    0x11
#define D7S_REG_Y_L    0x12
#define D7S_REG_Y_H    0x13
#define D7S_REG_Z_L    0x14
#define D7S_REG_Z_H    0x15

#define MODE_ACTIVE    0x01
#define POLL_MS        500           /* sampling interval */
#define ACTIVE_TIMEOUT 1000          /* ms to wait for sensor to become active */

/* ---- Globals for signal-safe cleanup ----------------------------------- */
static volatile sig_atomic_t g_stop = 0;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------------ */
static void on_signal(int sig)
{
    (void)sig;
    g_stop = 1;
}

/* ------------------------------------------------------------------------ */
/* Write one byte to a D7S register.                                        */
/* ------------------------------------------------------------------------ */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Read N bytes starting at a D7S register.                                 */
/* ------------------------------------------------------------------------ */
static int d7s_read_regs(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C set-register pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data bytes */
    ssize_t got = read(fd, dst, n);
    if (got < 0 || (size_t)got != n) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), got, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Initialise the D7S: set mode register to ACTIVE.                         */
/* ------------------------------------------------------------------------ */
static int d7s_init(int fd)
{
    if (d7s_write_reg(fd, D7S_REG_MODE, MODE_ACTIVE) != 0)
        return -1;

    /* Allow the sensor to settle into active mode */
    usleep(2000);
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Read X/Y/Z acceleration (16-bit signed, little-endian).                  */
/* ------------------------------------------------------------------------ */
static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (d7s_read_regs(fd, D7S_REG_X_L, &xl, 1) != 0) return -1;
    if (d7s_read_regs(fd, D7S_REG_X_H, &xh, 1) != 0) return -1;
    if (d7s_read_regs(fd, D7S_REG_Y_L, &yl, 1) != 0) return -1;
    if (d7s_read_regs(fd, D7S_REG_Y_H, &yh, 1) != 0) return -1;
    if (d7s_read_regs(fd, D7S_REG_Z_L, &zl, 1) != 0) return -1;
    if (d7s_read_regs(fd, D7S_REG_Z_H, &zh, 1) != 0) return -1;

    *x = (int16_t)((uint16_t)xl | ((uint16_t)xh << 8));
    *y = (int16_t)((uint16_t)yl | ((uint16_t)yh << 8));
    *z = (int16_t)((uint16_t)zl | ((uint16_t)zh << 8));
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Append one CSV row: timestamp,X,Y,Z                                      */
/* ------------------------------------------------------------------------ */
static int log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;

    if (localtime_r(&t, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus --------------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open CSV (append; write header if empty) ----------------------- */
    g_csv = fopen("fan_health.csv", "a+");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(fan_health.csv) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Determine whether file is empty so we can write a header */
    long pos = ftell(g_csv);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        fclose(g_csv);
        g_csv = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    if (pos == 0) {
        if (fprintf(g_csv, "timestamp,x,y,z\n") < 0 || fflush(g_csv) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(g_csv);
            g_csv = NULL;
