        g_csv = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Wait for sensor to become active ------------------------------- */
    int active = 0;
    for (int elapsed = 0; elapsed < ACTIVE_TIMEOUT; elapsed += 10) {
        uint8_t mode = 0;
        if (d7s_read_regs(g_i2c_fd, D7S_REG_MODE, &mode, 1) == 0) {
            if (mode == MODE_ACTIVE) {
                active = 1;
                break;
