        usleep(10000); /* 10 ms */
    }

    if (!active) {
        fprintf(stderr, "D7S did not become active within %d ms\n",
                ACTIVE_TIMEOUT);
        fclose(g_csv);
        g_csv = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
