    /* ---- Main sampling loop -------------------------------------------- */
    while (!g_stop) {
        int16_t x, y, z;

        if (d7s_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_sample(g_csv, x, y, z) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

