/*
 * Raspberry Pi 4 Model B – Dual KY-032 IR Obstacle Avoidance LED
 *
 * Wiring:
 *   KY-032 #1 OUT  -> GPIO23 (BCM)
 *   KY-032 #2 OUT  -> GPIO24 (BCM)
 *   LED anode     -> GPIO25 (BCM) via 220-330 ohm resistor to GND
 *
 * KY-032 OUT is active-LOW (0 = obstacle detected, 1 = clear).
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_avoidance obstacle_avoidance.c -lpigpio -lrt
 * Run:    sudo ./obstacle_avoidance
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN      25

#define POLL_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        return -1;
    }

    /* Enable internal pull-ups so sensors read HIGH when no obstacle is present. */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_2_PIN);
        return -1;
    }

    /* Start with LED off. */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: turn LED off and release pigpio resources. */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: failed to read sensor GPIO pins.\n");
            break;
        }

        /* Active-LOW: 0 => obstacle detected. */
        bool obstacle = (s1 == 0 || s2 == 0);

        if (gpioWrite(LED_PIN, obstacle ? 1 : 0) != 0) {
            fprintf(stderr, "Error: failed to write LED state.\n");
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    printf("Obstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

