/*
 * TMAG5170-Q1 3D Hall-Effect sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   TMAG5170 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   TMAG5170 VDD  -> 3.3 V (pin 1)
 *   TMAG5170 GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tmag5170_log tmag5170_log.c \
 *       -lm -lrt -lpigpio -lstdc++
 *
 * Run:
 *   sudo ./tmag5170_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- TMAG5170 constants (from TI datasheet) ---- */
#define TMAG5170_I2C_ADDR        0x30
#define TMAG5170_REG_DEVICE_ID   0x00
#define TMAG5170_REG_X_MSB       0x01
#define TMAG5170_REG_X_LSB       0x02
#define TMAG5170_REG_Y_MSB       0x03
#define TMAG5170_REG_Y_LSB       0x04
#define TMAG5170_REG_Z_MSB       0x05
#define TMAG5170_REG_Z_LSB       0x06
#define TMAG5170_REG_TEMP_MSB    0x07
#define TMAG5170_REG_TEMP_LSB    0x08
#define TMAG5170_REG_CONFIG      0x09
#define TMAG5170_REG_RANGE       0x0A
#define TMAG5170_REG_CONV_RATE   0x0B
#define TMAG5170_REG_STATUS      0x0C

#define TMAG5170_DEVICE_ID       0x5170

/*
 * CONFIG register (0x09):
 *   [15:14] Conversion mode (00 = continuous)
 *   [13:12] Operating mode (00 = continuous)
 *   [11:10] Range (00 = 50 mT)
 *   [9:8]   Conversion rate (00 = 100 Hz)
 *   [7:6]   Temperature sensor (00 = disabled)
 *   [5:4]   X-axis enable (11 = enabled)
 *   [3:2]   Y-axis enable (11 = enabled)
 *   [1:0]   Z-axis enable (11 = enabled)
 *
 * RANGE register (0x0A):
 *   [7:4]   X-axis range (0000 = 50 mT)
 *   [3:0]   Y-axis range (0000 = 50 mT)
 *
 * CONV_RATE register (0x0B):
 *   [7:4]   X-axis rate (0000 = 100 Hz)
 *   [3:0]   Y-axis rate (0000 = 100 Hz)
 *
 * Status register (0x0C):
 *   [7]     X-axis data ready
 *   [6]     Y-axis data ready
 *   [5]     Z-axis data ready
 *   [4]     Temperature data ready
 *   [3]     X-axis error
 *   [2]     Y-axis error
 *   [1]     Z-axis error
 *   [0]     Temperature error
 */
#define TMAG5170_CONFIG_VALUE    0x0000
#define TMAG5170_RANGE_VALUE     0x0000
#define TMAG5170_CONV_RATE_VALUE 0x0000

#define I2C_BUS                  1
#define LOG_FILE_NAME            "magnetic_log.csv"
#define SAMPLE_PERIOD_US         100000  /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* let main loop exit cleanly */
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register (big-endian on bus).   */
static int tmag_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register (big-endian on bus).  */
static int tmag_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int tmag5170_init(int handle)
{
    uint16_t dev_id = 0;

    /* Verify sensor presence by reading DEVICE_ID. */
    if (tmag_read_reg(handle, TMAG5170_REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (dev_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEVICE_ID 0x%04X (expected 0x%04X).\n",
                dev_id, TMAG5170_DEVICE_ID);
        return -1;
    }

    /* Configure sensor: continuous mode, 50 mT range, all axes enabled. */
    if (tmag_write_reg(handle, TMAG5170_REG_CONFIG, TMAG5170_CONFIG_VALUE) != 0)
        return -1;
    if (tmag_write_reg(handle, TMAG5170_REG_RANGE, TMAG5170_RANGE_VALUE) != 0)
        return -1;
    if (tmag_write_reg(handle, TMAG5170_REG_CONV_RATE, TMAG5170_CONV_RATE_VALUE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int tmag5170_read_xyz(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (tmag_read_reg(handle, TMAG5170_REG_X_MSB, &x_msb) != 0) return -1;
    if (tmag_read_reg(handle, TMAG5170_REG_X_LSB, &x_lsb) != 0) return -1;
    if (tmag_read_reg(handle, TMAG5170_REG_Y_MSB, &y_msb) != 0) return -1;
    if (tmag_read_reg(handle, TMAG5170_REG_Y_LSB, &y_lsb) != 0) return -1;
    if (tmag_read_reg(handle, TMAG5170_REG_Z_MSB, &z_msb) != 0) return -1;
    if (tmag_read_reg(handle, TMAG5170_REG_Z_LSB, &z_lsb) != 0) return -1;

    *x = (int16_t)((x_msb << 8) | (x_lsb & 0xFF));
    *y = (int16_t)((y_msb << 8) | (y_lsb & 0xFF));
    *z = (int16_t)((z_msb << 8) | (z_lsb & 0xFF));

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TMAG5170 default address. */
    g_i2c_handle = i2cOpen(I2C_BUS, TMAG5170_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, TMAG5170_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (tmag5170_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty. */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "timestamp,x,y,z\n");
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "[WARN] fseek failed: %s — continuing anyway.\n",
                strerror(errno));
    }

    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");
    printf("Logging to %s\n", LOG_FILE_NAME);

    /* Main sampling loop. */
    while (g_running) {
        int16_t x, y, z;

        if (tmag5170_read_xyz(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "[WARN] I2C read error — continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

