    /* Open log file in append mode; write header if empty. */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "timestamp,x,y,z\n");
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "[WARN] fseek failed: %s — continuing anyway.\n",
                strerror(errno));
    }

    /* Register signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");
    printf("Logging to %s\n", LOG_FILE_NAME);

    /* Main sampling loop. */
    while (g_running) {
        int16_t x, y, z;

        if (tmag5170_read_xyz(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "[WARN] I2C read error — continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

