/*
 * RPM measurement using Melexis MLX90217 Hall-effect sensor.
 *
 * Wiring (Raspberry Pi 4 Model B, BCM numbering):
 *   MLX90217 VCC  -> 3.3 V (pin 1)
 *   MLX90217 GND  -> GND   (pin 9)
 *   MLX90217 OUT  -> GPIO4 (pin 7)  [internal pull-up enabled]
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpm_log rpm_log.c -lpigpio -lpthread
 * Run:    sudo ./rpm_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_PERIOD_S 1.0        /* seconds between samples */
#define PULSES_PER_REV  12.0       /* MLX90217: 12 magnetic pulses per revolution */
#define PULSE_WINDOW_S  1.0        /* window for pulse counting */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_pulse_count = 0;
static FILE                *g_log_fp = NULL;
static pthread_mutex_t      g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handler — just flip the flag; cleanup happens in main().     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of the sensor pin.     */
/* We count rising edges only and reset the pulse counter periodically.*/
/* ------------------------------------------------------------------ */
static void sensor_alert_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {                       /* rising edge */
        g_pulse_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Append a timestamped RPM line to the log file and stdout.           */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_fp) {
        fprintf(g_log_fp, "%s %.2f\n", ts, rpm);
        fflush(g_log_fp);
    }
    pthread_mutex_unlock(&g_log_mutex);

    printf("%s RPM: %.2f\n", ts, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d) failed.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, sensor_alert_cb, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(%d) failed.\n", SENSOR_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM measurement started.  Logging to '%s'.  Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset pulse counter for this window */
        g_pulse_count = 0;

        /* Wait for the window to elapse (interruptible by signals) */
        time_sleep(PULSE_WINDOW_S);

        if (!g_running) {
            break;
        }

        /* Convert pulses to RPM */
        double pulses_in_window = (double)g_pulse_count;
        double rpm = (pulses_in_window / PULSES_PER_REV) * (60.0 / SAMPLE_PERIOD_S);

        log_rpm(rpm);
    }

    /* ---- Cleanup ---- */
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);   /* unregister callback */

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    pthread_mutex_unlock(&g_log_mutex);

    gpioTerminate();

    printf("\nRPM measurement stopped.\n");
    return EXIT_SUCCESS;
}

