/*
 * Quadrature Hall-effect sensor rotation logger for Raspberry Pi Zero W.
 *
 * Sensors : 2 × Melexis MLX90217 unipolar Hall-effect sensors
 * Wiring  : Sensor A OUT -> GPIO17 (BCM), Sensor B OUT -> GPIO27 (BCM)
 *           Internal pull-ups enabled (90° electrical offset).
 * Library : pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Build   : gcc -O2 -Wall -Wextra -o rotation_logger rotation_logger.c -lpigpio -lpthread
 * Run     : sudo ./rotation_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE     "rotation_log.txt"

/* Quadrature states (bit 0 = A, bit 1 = B) */
#define QUAD_STATE_A1 0x01
#define QUAD_STATE_B1 0x02
#define QUAD_STATE_A0 0x03
#define QUAD_STATE_B0 0x00

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static pthread_mutex_t       g_state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t        g_state_cond  = PTHREAD_COND_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
    pthread_cond_signal(&g_state_cond);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_rotation(const char *direction)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s.%03ld %s\n",
                timestamp, ts.tv_nsec / 1000000L, direction);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: log file not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* ISR callback (runs in pigpio thread)                                */
/* ------------------------------------------------------------------ */
static void quadrature_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    (void)userdata;

    if (gpio == SENSOR_A_PIN) {
        pthread_mutex_lock(&g_state_mutex);
        int state = (int)gpioRead(SENSOR_B_PIN);
        if (state < 0) {
            pthread_mutex_unlock(&g_state_mutex);
            return;
        }

        if (level == 1) {
            /* Rising edge on Sensor A */
            if (state == 0) {
                /* A1 B0 -> clockwise */
                log_rotation("CLOCKWISE");
            } else {
                /* A1 B1 -> counter-clockwise */
