/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_rotation(const char *direction)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s.%03ld %s\n",
                timestamp, ts.tv_nsec / 1000000L, direction);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: log file not open.\n");
    }
}

