/*
 * TTP223B capacitive touch sensor → LED indicator for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TTP223B VCC  → 3V3 (pin 1)
 *   TTP223B GND  → GND (pin 9)
 *   TTP223B OUT  → GPIO23 (pin 16, BCM 23)
 *   LED anode    → GPIO18 (pin 12, BCM 18) via 330 Ω resistor
 *   LED cathode  → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lpigpio -lrt
 * Run:    sudo ./touch_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 23   /* BCM 23, physical pin 16 */
#define LED_PIN          18   /* BCM 18, physical pin 12 */
#define POLL_DELAY_US    50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Best-effort LED off before releasing the line. */
    if (gpioInitialise() >= 0) {
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %m");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "pigpio initialised successfully");

    /* Configure the LED pin as an output and drive it low. */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED pin %d as output", LED_PIN);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED pin %d low", LED_PIN);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure the touch sensor pin as an input. */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set touch sensor pin %d as input", TOUCH_SENSOR_PIN);
        cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring TTP223B on GPIO%d, LED on GPIO%d",
           TOUCH_SENSOR_PIN, LED_PIN);

    /* Main polling loop. */
    while (g_running) {
        int level = gpioRead(TOUCH_SENSOR_PIN);
        if (level < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor pin %d", TOUCH_SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (level == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to turn LED on");
            } else {
                syslog(LOG_INFO, "Touch detected on GPIO%d", TOUCH_SENSOR_PIN);
            }
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to turn LED off");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    closelog();
    return EXIT_SUCCESS;
}

