#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 17
#define LED_PIN   18
#define DEBOUNCE_US 50000   /* 50 ms in microseconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Request rising-edge events on the touch sensor line.
     * pigpio's line event interface is level-agnostic: a rising edge
     * is reported as a PI_EVENT_RISING_EDGE event code.
     */
    int evt_handle = gpioEventStart(TOUCH_PIN, (PI_EVENT_RISING_EDGE | PI_EVENT_TIMEOUT));
    if (evt_handle < 0) {
        fprintf(stderr, "Error: gpioEventStart failed on GPIO%d (code %d).\n",
                TOUCH_PIN, evt_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool led_state = false;
    int  ret       = EXIT_SUCCESS;

    while (g_running) {
        /*
         * Block up to 1 s waiting for a rising edge or a timeout.
         * The pigpio event wait returns the number of events queued,
         * or a negative error code.
         */
        int rc = gpioEventWait(evt_handle, 1000000);
        if (rc < 0) {
            fprintf(stderr, "Error: gpioEventWait failed (code %d).\n", rc);
            ret = EXIT_FAILURE;
            break;
        }

        if (rc == 0) {
            /* Timeout — no event, loop back and re-check g_running. */
            continue;
        }

        /* Drain any queued events so we don't miss a burst. */
        while (gpioRead(TOUCH_PIN) == 1) {
            if (!g_running) {
                break;
            }
            gpioDelay(DEBOUNCE_US);
        }

        if (!g_running) {
            break;
        }

        led_state = !led_state;
        if (gpioWrite(LED_PIN, led_state ? 1 : 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", LED_PIN);
            ret = EXIT_FAILURE;
            break;
        }

        gpioDelay(DEBOUNCE_US);
    }

    /* Clean up resources on every exit path. */
    gpioEventStop(evt_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return ret;
}

