/*
 * Raspberry Pi Zero W — dual SainSmart TTP223B touch sensor logger.
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT  -> GPIO4
 *   Sensor 2 OUT  -> GPIO17
 *   LED 1 anode   -> GPIO27 (via ~330 Ω resistor)
 *   LED 2 anode   -> GPIO22 (via ~330 Ω resistor)
 *   VCC           -> 3.3 V
 *   GND           -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c -lpigpio -lrt
 * Run:    sudo ./touch_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22

#define POLL_DELAY_US  50000   /* 50 ms debounce / poll interval */
#define BUFFER_SIZE    100

/* ------------------------------------------------------------------ */
/* Circular log buffer                                                */
/* ------------------------------------------------------------------ */

typedef struct {
    int      sensor_pin;   /* BCM pin number of the touched sensor   */
    time_t   timestamp;    /* Unix epoch when the event occurred      */
    bool     touched;      /* true = touch detected, false = release  */
} touch_event_t;

typedef struct {
    touch_event_t events[BUFFER_SIZE];
    int           head;
    int           tail;
    int           count;
    int           overflow_count;
} circular_buffer_t;

static circular_buffer_t g_log;

static void buffer_init(circular_buffer_t *buf)
{
    buf->head  = 0;
    buf->tail  = 0;
    buf->count = 0;
    buf->overflow_count = 0;
}

static void buffer_add(circular_buffer_t *buf, int sensor_pin, time_t ts, bool touched)
{
    buf->events[buf->head].sensor_pin   = sensor_pin;
    buf->events[buf->head].timestamp    = ts;
    buf->events[buf->head].touched      = touched;
    buf->head = (buf->head + 1) % BUFFER_SIZE;

    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;   /* overwrite oldest */
        buf->overflow_count++;
    } else {
        buf->count++;
    }
}

static void buffer_print(const circular_buffer_t *buf)
{
    printf("\n--- Touch event log (%d entries, %d overflows) ---\n",
           buf->count, buf->overflow_count);

    int idx = buf->tail;
    for (int i = 0; i < buf->count; i++) {
        const touch_event_t *e = &buf->events[idx];
        char ts_str[32];
        struct tm tm_info;
        if (localtime_r(&e->timestamp, &tm_info) != NULL) {
            strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts_str, sizeof(ts_str), "<time-error>");
        }
        printf("  [%3d] %s  sensor=%-2d  %s\n",
               i, ts_str, e->sensor_pin,
               e->touched ? "TOUCHED" : "RELEASED");
        idx = (idx + 1) % BUFFER_SIZE;
    }
    printf("--- End of log ---\n\n");
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %u (mode %u): %s\n",
                pin, mode, pigpio_error(gpioGetMode(pin)));
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite failed for pin %u (level %u): %s\n",
                pin, level, pigpio_error(gpioRead(pin)));
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed for pin %u: %s\n",
                pin, pigpio_error(v));
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Turn off both LEDs before releasing pigpio */
    safe_write(LED_1_PIN, 0);
    safe_write(LED_2_PIN, 0);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure LED pins as outputs --- */
    if (safe_set_mode(LED_1_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(LED_2_PIN, PI_OUTPUT) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialise LEDs off --- */
    if (safe_write(LED_1_PIN, 0) < 0 || safe_write(LED_2_PIN, 0) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Initialise circular buffer --- */
    buffer_init(&g_log);

    printf("Touch sensor logger started.\n");
    printf("  Sensor 1: GPIO%d  -> LED GPIO%d\n", SENSOR_1_PIN, LED_1_PIN);
    printf("  Sensor 2: GPIO%d  -> LED GPIO%d\n", SENSOR_2_PIN, LED_2_PIN);
    printf("  Poll interval: %d ms\n", POLL_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = safe_read(SENSOR_1_PIN);
        int s2 = safe_read(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read failure — log and continue */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        bool s1_touched = (s1 == 1);
        bool s2_touched = (s2 == 1);

        if (safe_write(LED_1_PIN, s1_touched ? 1 : 0) < 0 ||
            safe_write(LED_2_PIN, s2_touched ? 1 : 0) < 0) {
            /* LED write failure — continue */
        }

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time");
        } else {
            buffer_add(&g_log, SENSOR_1_PIN, now, s1_touched);
            buffer_add(&g_log, SENSOR_2_PIN, now, s2_touched);
        }

        gpioDelay(POLL_DELAY_US);   /* 50 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    buffer_print(&g_log);
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

