    int current_state;
    int ret;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    gpioSetMode(RAINDROP_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAINDROP_GPIO, PI_PUD_UP);

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Raindrop sensor monitoring started on GPIO%d.\n", RAINDROP_GPIO);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        current_state = gpioRead(RAINDROP_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d\n", RAINDROP_GPIO);
            break;
        }

        /* Raindrop sensor: LOW (0) = rain detected, HIGH (1) = no rain */
        if (current_state != last_state) {
            if (current_state == 0) {
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Failed to log rain event\n");
                }
            } else {
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Failed to log no-rain event\n");
                }
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

