#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

double calculate_rpm(int sensor1_state, int sensor2_state, struct timespec *last_time) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    double time_diff = (current_time.tv_sec - last_time->tv_sec) +
                       (current_time.tv_nsec - last_time->tv_nsec) / 1000000000.0;

    if (time_diff <= 0.0) {
        return 0.0;
    }

    double rpm = 60.0 / time_diff;
    *last_time = current_time;
    return rpm;
}

int log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int sensor1_state = read_sensor(SENSOR1_GPIO);
    int sensor2_state = read_sensor(SENSOR2_GPIO);

    struct timespec last_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (program_running) {
        int current_sensor1_state = read_sensor(SENSOR1_GPIO);
        int current_sensor2_state = read_sensor(SENSOR2_GPIO);

        if (current_sensor1_state != sensor1_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            current_sensor1_state = read_sensor(SENSOR1_GPIO);
            if (current_sensor1_state == sensor1_state) {
                sensor1_state = current_sensor1_state;
            } else {
                sensor1_state = current_sensor1_state;
                double rpm = calculate_rpm(sensor1_state, sensor2_state, &last_time);
                printf("Sensor 1 State: %d, RPM: %.2f\n", sensor1_state, rpm);
                log_data(sensor1_state, sensor2_state);
            }
        }

        if (current_sensor2_state != sensor2_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            current_sensor2_state = read_sensor(SENSOR2_GPIO);
            if (current_sensor2_state == sensor2_state) {
                sensor2_state = current_sensor2_state;
            } else {
                sensor2_state = current_sensor2_state;
                double rpm = calculate_rpm(sensor1_state, sensor2_state, &last_time);
                printf("Sensor 2 State: %d, RPM: %.2f\n", sensor2_state, rpm);
                log_data(sensor1_state, sensor2_state);
            }
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    return 0;
}

