#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_SEC 1

/* Si1182 register addresses (example placeholders — adjust per datasheet) */
#define SI1182_REG_HR_DATA   0x01
#define SI1182_REG_SPO2_DATA 0x02
#define SI1182_REG_CMD       0x03
#define SI1182_CMD_RESET     0x01
#define SI1182_CMD_START     0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void)
{
    /* Software reset via command register */
    if (i2cWriteByteData(g_i2c_handle, SI1182_REG_CMD, SI1182_CMD_RESET) < 0) {
        fprintf(stderr, "Error writing reset command\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Start continuous measurement */
    if (i2cWriteByteData(g_i2c_handle, SI1182_REG_CMD, SI1182_CMD_START) < 0) {
        fprintf(stderr, "Error writing start command\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first conversion */
    return 0;
}

static int read_hr(int *hr)
{
    int v = i2cReadByteData(g_i2c_handle, SI1182_REG_HR_DATA);
    if (v < 0) {
        fprintf(stderr, "Error reading HR data: %d\n", v);
        return -1;
    }
    *hr = v;
    return 0;
}

static int read_spo2(int *spo2)
{
    int v = i2cReadByteData(g_i2c_handle, SI1182_REG_SPO2_DATA);
    if (v < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", v);
        return -1;
    }
    *spo2 = v;
    return 0;
}

static int log_data(int hr, int spo2)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n",
                timestamp, hr, spo2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int hr, spo2;

        if (read_hr(&hr) == 0 && read_spo2(&spo2) == 0) {
            if (log_data(hr, spo2) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            gpioDelay(1000000); /* 1 s */
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

