                    fprintf(stderr, "Failed to log tilt end event\n");
                }
                if (set_alarm(0) != 0) {
                    fprintf(stderr, "Failed to deactivate alarm\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

