/*
 * seismic.c — Raspberry Pi 3 Model B+
 * Omron D7S-A0011 seismic sensor on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Alert LED on GPIO17 (BCM)
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lrt -lm
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x48          /* D7S-A0011 default I2C address */
#define ALERT_LED_PIN        17            /* BCM pin for alert LED */
#define THRESHOLD            500.0         /* vibration magnitude threshold */
#define POLL_INTERVAL_US     100000        /* 100 ms between samples */
#define ALERT_LED_ON_US      1000000       /* 1 s alert LED pulse */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register addresses (16-bit, big-endian on the bus) */
#define REG_CTRL1            0x00
#define REG_CTRL2            0x02
#define REG_DATA_X           0x04
#define REG_DATA_Y           0x06
#define REG_DATA_Z           0x08
#define REG_TEMP             0x0A

/* CTRL1 bit fields */
#define CTRL1_POWER_DOWN     0x01
#define CTRL1_RESET          0x80

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_sensor_data(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void trigger_alert(float magnitude);
static void log_event(float magnitude);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C helpers ------------------------------- */

/*
 * Write a 16-bit value to a 16-bit register address.
 * pigpio's i2cWriteWordData sends [reg_hi, reg_lo, data_hi, data_lo]
 * on the wire, which is the correct order for the D7S-A0011.
 */
static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/*
 * Read a 16-bit value from a 16-bit register address.
 * pigpio's i2cReadWordData returns [data_hi, data_lo] in the low 16 bits
 * of the returned int, which is correct for the D7S-A0011.
 */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

/* ----------------------------- Sensor init -------------------------------- */
static int init_sensor(void)
{
    uint16_t ctrl1;

    /* Verify sensor presence by reading CTRL1 */
    if (i2c_read_reg16(i2c_handle, REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit and issue software reset */
    ctrl1 &= ~CTRL1_POWER_DOWN;
    ctrl1 |=  CTRL1_RESET;

    if (i2c_write_reg16(i2c_handle, REG_CTRL1, ctrl1) != 0) {
        fprintf(stderr, "Failed to write CTRL1\n");
        return -1;
    }

    /* Allow reset to complete */
    gpioDelay(20000);  /* 20 ms */

    /* Re-read and verify */
    if (i2c_read_reg16(i2c_handle, REG_CTRL1, &ctrl1) != 0) {
        fprintf(stderr, "Sensor disappeared after reset\n");
        return -1;
    }

    printf("D7S-A0011 initialized (CTRL1=0x%04X)\n", ctrl1);
    return 0;
}

/* ----------------------------- Data read --------------------------------- */
static int read_sensor_data(float *x, float *y, float *z)
{
    uint16_t raw_x, raw_y, raw_z;
    int      retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(i2c_handle, REG_DATA_X, &raw_x) == 0 &&
            i2c_read_reg16(i2c_handle, REG_DATA_Y, &raw_y) == 0 &&
            i2c_read_reg16(i2c_handle, REG_DATA_Z, &raw_z) == 0) {

            /* Convert two's-complement 16-bit signed values to float */
            *x = (float)(int16_t)raw_x;
            *y = (float)(int16_t)raw_y;
            *z = (float)(int16_t)raw_z;
            return 0;
        }

        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "I2C read error, retry %d/%d\n", retries, MAX_RETRIES);
            gpioDelay(10000);  /* 10 ms back-off */
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ----------------------------- Magnitude --------------------------------- */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ----------------------------- Alert ------------------------------------- */
static void trigger_alert(float magnitude)
{
    if (gpioWrite(ALERT_LED_PIN, 1) != 0) {
        fprintf(stderr, "Failed to turn on alert LED\n");
        return;
    }
    gpioDelay(ALERT_LED_ON_US);
    if (gpioWrite(ALERT_LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to turn off alert LED\n");
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s - Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file);
}

/* ----------------------------- Signal handling --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_LED_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    float x, y, z, magnitude;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure alert LED */
    if (gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_LED_PIN, 0);

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                printf("Threshold exceeded: %.2f\n", magnitude);
                trigger_alert(magnitude);
                log_event(magnitude);
            }
        } else {
            fprintf(stderr, "Skipping sample due to read failure\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

