#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int pins[4] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    int led_pin = LED_PIN;
    int i;
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    for (i = 0; i < 4; i++) {
        rc = gpioSetMode(pins[i], PI_INPUT);
        if (rc != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d (rc=%d).\n", pins[i], rc);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it starts OFF */
    rc = gpioSetMode(led_pin, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d (rc=%d).\n", led_pin, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioWrite(led_pin, 0);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioWrite failed for LED pin %d (rc=%d).\n", led_pin, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int any_detected = 0;

        for (i = 0; i < 4; i++) {
            int level = gpioRead(pins[i]);
            if (level == 0) {
                any_detected = 1;
                break;
            }
            /* level == 1 means no obstacle (active-low sensor) */
        }

        rc = gpioWrite(led_pin, any_detected ? 1 : 0);
        if (rc != 0) {
            fprintf(stderr, "Warning: gpioWrite failed for LED pin %d (rc=%d).\n", led_pin, rc);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(led_pin, 0);
    gpioTerminate();
    printf("\nObstacle detection system stopped.\n");
    return EXIT_SUCCESS;
}

