/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27
 * (physical pins 3, 5, 7, 11, 13) and logs a timestamped event to
 * /var/log/flame_events.log when a HIGH -> LOW transition is confirmed
 * after a 50 ms debounce read.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define TIMESTAMP_LEN    32
#define MSG_LEN          128

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {"A", "B", "C", "D", "E"};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Generate an ISO-8601 UTC timestamp string.
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (gmtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0)
        return -1;

    return 0;
}

/*
 * Append a flame event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(const char *timestamp, const char *sensor_id,
                           unsigned int gpio_pin)
{
    FILE *fp;
    int fd;
    int rc = 0;

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file '%s': %s",
               LOG_FILE, strerror(errno));
        return -1;
    }

    fd = fileno(fp);
    if (fd < 0) {
        syslog(LOG_ERR, "fileno() failed: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %s (GPIO %u) - Flame Detected\n",
                timestamp, sensor_id, gpio_pin) < 0) {
        syslog(LOG_ERR, "fprintf() to log file failed: %s", strerror(errno));
        rc = -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
        rc = -1;
    }

    if (flock(fd, LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN) failed: %s", strerror(errno));
        rc = -1;
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
        rc = -1;
    }

    return rc;
}

/*
 * Debounce: re-read the line after DEBOUNCE_MS and confirm HIGH -> LOW.
 * Returns 1 if confirmed, 0 if not, -1 on read error.
 */
static int debounce_read(struct gpiod_line *line)
{
    struct timespec ts = {0, DEBOUNCE_MS * 1000000L};

    nanosleep(&ts, NULL);

    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "Debounce read failed on GPIO %u: %s",
               gpiod_line_offset(line), strerror(errno));
        return -1;
    }

    return (val == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_values[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        prev_values[i] = -1;
    }

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    /* Acquire each sensor line */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get GPIO line %u: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request GPIO %u as input: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        int v = gpiod_line_get_value(lines[i]);
        if (v < 0) {
            syslog(LOG_ERR, "Initial read failed on GPIO %u: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_values[i] = v;
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (%d sensors)", NUM_SENSORS);

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Read failed on GPIO %u (sensor %s): %s",
                       sensor_pins[i], sensor_ids[i], strerror(errno));
                continue;
            }

            /* Detect HIGH -> LOW transition */
            if (val == 0 && prev_values[i] == 1) {
                int confirmed = debounce_read(lines[i]);
                if (confirmed < 0)
                    continue;

                if (confirmed) {
                    char timestamp[TIMESTAMP_LEN];
                    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                        if (log_flame_event(timestamp, sensor_ids[i],
                                            sensor_pins[i]) == 0) {
                            syslog(LOG_INFO,
                                   "Flame detected on sensor %s (GPIO %u)",
                                   sensor_ids[i], sensor_pins[i]);
                        } else {
                            syslog(LOG_ERR,
                                   "Failed to log flame event for sensor %s",
                                   sensor_ids[i]);
                        }
                    } else {
                        syslog(LOG_ERR,
                               "Failed to generate timestamp for sensor %s",
                               sensor_ids[i]);
                    }
                }
            }

            prev_values[i] = val;
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame sensor monitoring stopped");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all requested lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }

    if (chip != NULL)
        gpiod_chip_close(chip);

    closelog();
    return ret;
}

