/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (TTP226 OUT0..OUT7 -> Pi BCM GPIO):
 *   OUT0 -> GPIO5  (pin 29)
 *   OUT1 -> GPIO6  (pin 31)
 *   OUT2 -> GPIO13 (pin 33)
 *   OUT3 -> GPIO19 (pin 35)
 *   OUT4 -> GPIO26 (pin 37)
 *   OUT5 -> GPIO12 (pin 32)
 *   OUT6 -> GPIO16 (pin 36)
 *   OUT7 -> GPIO20 (pin 38)
 *
 * Build:  gcc -Wall -Wextra -O2 -o ttp226_touch ttp226_touch.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000  /* 50 ms */

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buf);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request_config req_cfg;
    int prev_values[NUM_CHANNELS];
    int ret;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Resolve all eight lines --- */
    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* --- Configure all lines as inputs --- */
    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer = "ttp226-touch";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request_bulk(&lines, &req_cfg, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* --- Read initial states --- */
    ret = gpiod_line_get_value_bulk(&lines, prev_values);
    if (ret != 0) {
        fprintf(stderr, "Failed to read initial GPIO values: %s\n",
                strerror(errno));
        gpiod_line_release_bulk(&lines, 0);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (program_running) {
        int values[NUM_CHANNELS];

        ret = gpiod_line_get_value_bulk(&lines, values);
        if (ret != 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (values[i] != prev_values[i]) {
                print_timestamp();
                printf("Sensor %d (BCM %u): %s\n",
                       i, touch_pins[i],
                       values[i] ? "TOUCHED" : "RELEASED");
                fflush(stdout);
                prev_values[i] = values[i];
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpiod_line_release_bulk(&lines, 0);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

