#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define VEML7700_ADDR   0x10
#define GPIO_LED        18
#define PWM_FREQ        1000
#define PWM_RANGE       100
#define LOG_FILE        "grow_log.txt"
#define SAMPLE_INTERVAL 1

#define VEML7700_ALS_CONF  0x00
#define VEML7700_ALS_DATA  0x04

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

static int veml7700_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, val, 1) != 1) return -1;
    return 0;
}

static int veml7700_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (veml7700_write_reg(VEML7700_ALS_CONF, 0x00) < 0) {
        fprintf(stderr, "VEML7700 not detected at 0x%02X\n", VEML7700_ADDR);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(uint16_t *lux) {
    uint8_t lo, hi;
    if (veml7700_read_reg(VEML7700_ALS_DATA, &lo) < 0) return -1;
    if (veml7700_read_reg(VEML7700_ALS_DATA + 1, &hi) < 0) return -1;
    *lux = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int map_lux_to_brightness(uint16_t lux) {
    if (lux < 100) return 100;
    if (lux < 500) return 75;
    if (lux < 1000) return 50;
    return 25;
}

static void log_data(uint16_t lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_fp, "%s,lux=%u,brightness=%d,error=%d\n", ts, lux, brightness, error_code);
    fflush(log_fp);
}

static void set_led_brightness(int brightness) {
    if (gpioPWM(GPIO_LED, brightness) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (veml7700_init() < 0) {
        fprintf(stderr, "VEML7700 init failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQ);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint16_t lux = 0;
        int err = 0;
        if (veml7700_read_lux(&lux) < 0) {
            fprintf(stderr, "I2C read error\n");
            err = 1;
        }

        int brightness = map_lux_to_brightness(lux);
        set_led_brightness(brightness);
        log_data(lux, brightness, err);

        sleep(SAMPLE_INTERVAL);
    }

    set_led_brightness(0);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

