        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set channel pin %d as input\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on channel pin %d\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int prev_state[NUM_CHANNELS] = {0};
    int led_on = 0;

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(channel_pins[i]);
            if (level < 0) {
                fprintf(stderr, "gpioRead failed on pin %d\n", channel_pins[i]);
                continue;
            }

            if (level == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
            }
            prev_state[i] = level;
            any_touched |= level;
        }

        if (any_touched && !led_on) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
            } else {
                led_on = 1;
            }
        } else if (!any_touched && led_on) {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off\n");
            } else {
                led_on = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

