/*
 * OPT3001 greenhouse light monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   OPT3001 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_monitor light_monitor.c -li2c
 *
 * The OPT3001 uses little-endian word order in its I2C transactions,
 * so we byte-swap the 16-bit configuration and result values.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1           /* seconds between readings */
#define SETTLE_DELAY   0.1         /* seconds after writing config */

/* OPT3001 register addresses (from datasheet) */
#define REG_RESULT      0x00
#define REG_CONFIG      0x01
#define REG_MANUFACT_ID 0x7E
#define REG_DEVICE_ID   0x7F

/*
 * Configuration register value (16-bit, big-endian on the wire):
 *   RN[1:0]   = 11  (auto-range, full-scale)
 *   CT        = 100 (100 ms conversion time)
 *   M[1:0]    = 11  (continuous mode)
 *   FC[1:0]   = 00  (1x filter)
 *   L          = 0   (default)
 *   POL       = 0   (active low)
 *   ME        = 0   (no mask)
 *   FL        = 0   (no fault)
 *   ... => 0xC410
 */
#define OPT3001_CONFIG_BE 0x10C4

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers (little-endian register access, big-endian data)        */
/* ------------------------------------------------------------------ */

/* Write a 16-bit value to an 8-bit-addressed register. */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);        /* low byte first  */
    buf[2] = (uint8_t)((value >> 8) & 0xFF); /* high byte second */

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an 8-bit-addressed register. */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): write reg failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* OPT3001 sends MSB first, then LSB. */
    *out = (uint16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* OPT3001 driver                                                      */
/* ------------------------------------------------------------------ */

static int opt3001_init(int fd)
{
    uint16_t manuf_id, device_id;

    if (i2c_read_reg16(fd, REG_MANUFACT_ID, &manuf_id) != 0)
        return -1;
    if (manuf_id != 0x5449) {
        fprintf(stderr, "OPT3001 manufacturer ID mismatch: 0x%04X (expected 0x5449)\n",
                manuf_id);
        return -1;
    }

    if (i2c_read_reg16(fd, REG_DEVICE_ID, &device_id) != 0)
        return -1;
    if (device_id != 0x3001) {
        fprintf(stderr, "OPT3001 device ID mismatch: 0x%04X (expected 0x3001)\n",
                device_id);
        return -1;
    }

    /*
     * OPT3001 expects the 16-bit config value in big-endian order on the
     * wire, so we pre-byte-swap before writing.
     */
    if (i2c_write_reg16(fd, REG_CONFIG, OPT3001_CONFIG_BE) != 0)
        return -1;

    /* Allow first conversion to complete (100 ms CT). */
    sleep(1);
    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;

    if (i2c_read_reg16(fd, REG_RESULT, &raw) != 0)
        return -1;

    /* OPT3001 sends MSB first, then LSB. */
    uint16_t swapped = (uint16_t)((raw >> 8) | (raw << 8));

    /*
     * Conversion formula (datasheet):
     *   lux = raw * 0.01
     *   raw = result / 100
     */
    *lux_out = (float)swapped * 0.01f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("OPT3001 greenhouse light monitor started. Logging to %s\n",
           LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Sensor read failed; skipping this sample.\n");
        } else {
            if (log_data(lux) != 0)
                fprintf(stderr, "Logging failed for this sample.\n");
            printf("%.2f lux\n", lux);
        }

        /*
         * Sleep in 100 ms increments so SIGINT is caught promptly.
         */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

