    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, int sensor_value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Sensor Value: %d\n", timestamp, sensor_value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int trigger_alert(int pin) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Failed to set alert pin HIGH: %s\n", pigpio_error(0));
        return -1;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW: %s\n", pigpio_error(0));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode: %s\n", pigpio_error(0));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set alert pin mode: %s\n", pigpio_error(0));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW: %s\n", pigpio_error(0));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading flame sensor: %s\n", pigpio_error(0));
        } else {
            if (log_event(log_file, sensor_value) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }

            if (sensor_value == 0) {
                printf("Flame detected!\n");
                if (trigger_alert(ALERT_PIN) != 0) {
                    fprintf(stderr, "Error triggering alert.\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

