/*
 * cooling_monitor.c — Raspberry Pi Zero W
 *
 * Monitors a Sensirion SLF3S-1300F liquid flow sensor on I2C bus 1
 * (GPIO2 = SDA, GPIO3 = SCL) and logs flow rate + status to
 * cooling_log.csv.  Handles SIGINT for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o cooling_monitor cooling_monitor.c
 * Run:    ./cooling_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SLF3S_ADDR       0x49
#define CMD_CONT_MEAS    0x361F   /* continuous measurement, no averaging */
#define FLOW_MIN         0.0f
#define FLOW_MAX         100.0f
#define SAMPLE_PERIOD_S  1
#define MEAS_DELAY_MS    2
#define CSV_FILENAME     "cooling_log.csv"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills *flow_rate.
 * Returns -1 on I2C error, -2 on CRC error, -3 on out-of-range.
 */
static int read_flow_rate(int fd, float *flow_rate)
{
    uint8_t data[3];

    if (i2c_write_cmd(fd, CMD_CONT_MEAS) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(data, 2), data[2]);
        return -2;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *flow_rate = (float)raw / 100.0f;

    if (*flow_rate < FLOW_MIN || *flow_rate > FLOW_MAX) {
        fprintf(stderr, "Flow out of range: %.2f ml/min\n", *flow_rate);
        return -3;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float flow_rate, uint8_t flags,
                    const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%u,%s\n", ts, flow_rate, flags, status) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen(" CSV_FILENAME ")");
        goto cleanup;
    }

    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,Flow Rate (ml/min),Status\n") < 0 ||
            fflush(fp) != 0) {
            perror("write header");
            goto cleanup;
        }
    }

    printf("Monitoring coolant flow on %s (addr 0x%02X). Ctrl+C to stop.\n",
           I2C_BUS, SLF3S_ADDR);

    while (g_running) {
        float flow_rate = 0.0f;
        uint8_t flags = 0;
        const char *status = "OK";
        int rv;

        rv = read_flow_rate(fd, &flow_rate);
        if (rv == 0) {
            rv = log_data(fp, flow_rate, flags, status);
            if (rv != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else if (rv == -2) {
            fprintf(stderr, "CRC error — attempting recovery.\n");
            rv = log_data(fp, 0.0f, 0, "CRC_ERROR");
            if (rv != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
            /* Re-open I2C handle to recover the bus */
            if (fd >= 0) {
                close(fd);
                fd = -1;
            }
            usleep(100 * 1000);
            fd = open(I2C_BUS, O_RDWR);
            if (fd < 0) {
                perror("open(" I2C_BUS ") after recovery");
                goto cleanup;
            }
            if (ioctl(fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
                perror("ioctl(I2C_SLAVE) after recovery");
                goto cleanup;
            }
        } else if (rv == -3) {
            fprintf(stderr, "Out-of-range reading — logging as INVALID.\n");
            rv = log_data(fp, flow_rate, flags, "INVALID");
            if (rv != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "I2C read error — logging as ERROR.\n");
            rv = log_data(fp, 0.0f, 0, "ERROR");
            if (rv != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    if (fp != NULL)
        fclose(fp);
    return rc;
}

