/*
 * KY-033 Obstacle Avoidance Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   Left sensor   -> GPIO17 (pin 11)
 *   Middle sensor -> GPIO27 (pin 13)
 *   Right sensor  -> GPIO22 (pin 15)
 *
 * The KY-033 digital output is pulled high when an obstacle is detected
 * and low when clear.  We log 0 or 1 for each sensor.
 *
 * Build:  gcc -O2 -Wall -Wextra -o path_logger path_logger.c -lpigpio -lrt
 * Run:    sudo ./path_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    17
#define MIDDLE_SENSOR_PIN  27
#define RIGHT_SENSOR_PIN   22

#define LOG_FILE_NAME      "path_log.csv"
#define SAMPLE_PERIOD_US   50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Write an ISO-8601 timestamp into buf (size >= 25).
 * Returns 0 on success, -1 on failure.
 */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0)
        return -1;

    return 0;
}

/*
 * Append one CSV row.  Returns 0 on success, -1 on failure.
 */
static int log_data(FILE *fp, const char *ts, int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0)
        return -1;

    if (fflush(fp) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    FILE *fp = NULL;
    int  left, middle, right;
    char ts[32];
    int  rc = EXIT_FAILURE;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    int pins[3] = { LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN };
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            goto cleanup_gpio;
        }
    }

    /* ---- Open log file ---- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup_gpio;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,left,middle,right\n") < 0) {
            fprintf(stderr, "Error: cannot write header: %s\n", strerror(errno));
            goto cleanup_all;
        }
        fflush(fp);
    }

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        left   = gpioRead(LEFT_SENSOR_PIN);
        middle = gpioRead(MIDDLE_SENSOR_PIN);
        right  = gpioRead(RIGHT_SENSOR_PIN);

        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "Error: failed to generate timestamp.\n");
            break;
        }

        if (log_data(fp, ts, left, middle, right) != 0) {
            fprintf(stderr, "Error: failed to write log entry: %s\n",
                    strerror(errno));
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 50 ms */
    }

    rc = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }

cleanup_gpio:
    gpioTerminate();

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return rc;
}

