#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define LOG_FILE "flame_events.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }

    fclose(fp);
}

static void alert_flame_detected(void) {
    printf("ALERT: Flame detected!\n");
    fflush(stdout);
    log_event("Flame detected!");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so the line is defined when the sensor is disconnected */
    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO %d\n", FLAME_SENSOR_GPIO);
    }

    /* Allow the pull-up to settle */
    gpioDelay(10000);

    int last_state = gpioRead(FLAME_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "Failed to read initial state of GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);
    fflush(stdout);

    while (program_running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Detect falling edge: 1 -> 0 transition (active-low sensor) */
        if (last_state == 1 && current_state == 0) {
            alert_flame_detected();
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

