/*
 * touch_lamp.c — Raspberry Pi 5 touch-activated lamp using TTP223 + pigpio
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c -lpigpio -lrt
 * Run:    sudo ./touch_lamp
 *
 * Wiring:
 *   TTP223 OUT  -> GPIO23 (BCM 23)
 *   LED anode   -> GPIO24 (BCM 24) via ~330 Ω resistor
 *   LED cathode -> GND
 *   TTP223 VCC  -> 3.3 V, TTP223 GND -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <pigpio.h>

#define TOUCH_PIN    23          /* BCM 23 — TTP223 OUT  */
#define LED_PIN      24          /* BCM 24 — LED anode   */
#define GPIO_CHIP    "/dev/gpiochip4"
#define LOG_FILE     "touch_log.txt"
#define POLL_TIMEOUT_MS 1000     /* 1 s poll timeout      */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(int led_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s LED=%s\n", ts, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log) != 0)
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int chip = gpioInitialise();
    if (chip < 0) {
        fprintf(stderr, "gpioInitialise() failed (code %d)\n", chip);
        return -1;
    }

    int ret = 0;

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_PIN) failed\n");
        ret = -1;
        goto fail;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        ret = -1;
        goto fail;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        ret = -1;
        goto fail;
    }

    return 0;

fail:
    gpioTerminate();
    return ret;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
