#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <pigpio.h>

#define TOUCH_PIN    23          /* BCM 23 — TTP223 OUT  */
#define LED_PIN      24          /* BCM 24 — LED anode   */
#define GPIO_CHIP    "/dev/gpiochip4"
#define LOG_FILE     "touch_log.txt"
#define POLL_TIMEOUT_MS 1000     /* 1 s poll timeout      */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(int led_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s LED=%s\n", ts, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log) != 0)
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
