    }

    printf("Touch lamp ready.  Touch GPIO%d to toggle GPIO%d.  Ctrl-C to exit.\n",
           TOUCH_PIN, LED_PIN);

    int led_state = 0;

    while (g_running) {
        int ev = gpioRead(TOUCH_PIN);
        if (ev < 0) {
            fprintf(stderr, "gpioRead(TOUCH_PIN) failed: %s\n", strerror(errno));
            break;
        }

        if (ev == 1) {
            led_state = !led_state;
            if (gpioWrite(LED_PIN, led_state) != 0) {
                fprintf(stderr, "gpioWrite(LED_PIN) failed\n");
                break;
            }
            log_event(led_state);

            /*
             * TTP223 is active-high: a rising edge means a new touch.
             * Debounce is handled by the TTP223 output register; we
             * consume the event and wait for the next one.
             */
