                int v = gpioRead(TOUCH_PIN);
                if (v < 0) {
                    fprintf(stderr, "gpioRead(TOUCH_PIN) failed: %s\n", strerror(errno));
                    goto shutdown;
                }
                if (v == 0)
                    break;
                gpioDelay(10000); /* 10 ms */
            }
        }

        gpioDelay(100000); /* 100 ms poll interval */
    }

shutdown:
    cleanup();
    return EXIT_SUCCESS;
