/*
 * Flame Detection Safety System — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 (digital, active-low)
 * Wiring : KY-026 DO  -> GPIO17 (BCM, physical pin 11)
 *          Buzzer +   -> GPIO18 (BCM, physical pin 12)
 *          KY-026 VCC -> 3.3 V, KY-026 GND -> GND
 *          Buzzer GND -> GND
 *
 * Behaviour:
 *   Polls the sensor every 500 ms (100 ms slices so we can respond
 *   promptly to SIGINT/SIGTERM).  On a HIGH-to-LOW transition of the
 *   sensor line (LOW = flame detected), logs a timestamped entry to
 *   alert_log.txt and activates the buzzer for 2 s.
 *
 * Build  : gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 * Run    : ./flame_alert
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17, physical pin 11 */
#define BUZZER_PIN        18   /* BCM 18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_S 2
#define POLL_SLICE_MS     100

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *log, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log, "%s: %s\n", ts, msg) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    if (fflush(log) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Get lines ------------------------------------------------ */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request lines -------------------------------------------- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") != 0) {
        fprintf(stderr, "gpiod_line_request_input(%d): %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Log startup ---------------------------------------------- */
    log_event(log_file, "System started");

    /* ---- Main loop ------------------------------------------------ */
    int prev_flame = gpiod_line_get_value(flame_line);
    if (prev_flame < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int flame = gpiod_line_get_value(flame_line);
        if (flame < 0) {
            fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
            break;
        }

        /* HIGH -> LOW transition = new flame detection */
        if (prev_flame == 1 && flame == 0) {
            log_event(log_file, "FLAME DETECTED");

            if (gpiod_line_set_value(buzzer_line, 1) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, 1): %s\n",
                        strerror(errno));
                break;
            }

            /* Buzzer on for 2 s (100 ms slices) */
            for (int i = 0; i < BUZZER_DURATION_S * 10 && g_running; i++)
                usleep(POLL_SLICE_MS * 1000);

            if (gpiod_line_set_value(buzzer_line, 0) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, 0): %s\n",
                        strerror(errno));
                break;
            }
        }

        prev_flame = flame;

        /* 500 ms poll interval (100 ms slices) */
        for (int i = 0; i < POLL_INTERVAL_MS / POLL_SLICE_MS && g_running; i++)
            usleep(POLL_SLICE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release resources ---------------------------------------- */
    if (buzzer_line) {
        if (gpiod_line_set_value(buzzer_line, 0) != 0)
            fprintf(stderr, "Warning: failed to turn off buzzer: %s\n",
                    strerror(errno));
        gpiod_line_release(buzzer_line);
    }
    if (flame_line)
        gpiod_line_release(flame_line);
    if (chip)
        gpiod_chip_close(chip);

    if (log_file) {
        log_event(log_file, "System stopped");
        if (fclose(log_file) != 0)
            fprintf(stderr, "fclose(log): %s\n", strerror(errno));
    }

    return ret;
}

