/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 has an open-drain output:
 *   - Magnet present  -> OUT low  (logic 0)
 *   - Magnet removed  -> OUT high (logic 1)
 *
 * The internal pull-up is enabled so the line is never floating.
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE    "magnet_log.txt"
#define POLL_US     100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s - Sensor %d: %s\n",
                ts, sensor_id, state ? "Magnet Present" : "Magnet Removed") < 0) {
        fprintf(stderr, "fprintf() to log failed\n");
        return;
    }

    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush() failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Sensor setup                                                        */
/* ------------------------------------------------------------------ */
static int setup_sensor(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", pin);
        return -1;
    }

    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d) failed\n", pin);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensors ----------------------------------------- */
    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (setup_sensor(pins[i]) != 0) {
            fprintf(stderr, "Failed to configure sensor %zu (GPIO%d)\n",
                    i + 1, pins[i]);
            fclose(g_log);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Initial read ----------------------------------------------- */
    int prev1 = gpioRead(SENSOR1_PIN);
    int prev2 = gpioRead(SENSOR2_PIN);
    int prev3 = gpioRead(SENSOR3_PIN);

    if (prev1 < 0 || prev2 < 0 || prev3 < 0) {
        fprintf(stderr, "Initial gpioRead() failed (s1=%d s2=%d s3=%d)\n",
                prev1, prev2, prev3);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int cur1 = gpioRead(SENSOR1_PIN);
        int cur2 = gpioRead(SENSOR2_PIN);
        int cur3 = gpioRead(SENSOR3_PIN);

        if (cur1 < 0 || cur2 < 0 || cur3 < 0) {
            fprintf(stderr, "gpioRead() error (s1=%d s2=%d s3=%d)\n",
                    cur1, cur2, cur3);
        } else {
            if (cur1 != prev1) { log_event(1, cur1); prev1 = cur1; }
            if (cur2 != prev2) { log_event(2, cur2); prev2 = cur2; }
            if (cur3 != prev3) { log_event(3, cur3); prev3 = cur3; }
        }

        gpioDelay(POLL_US);   /* 100 ms */
    }

    /* --- Clean shutdown -------------------------------------------- */
    gpioTerminate();
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    return EXIT_SUCCESS;
}

