/*
 * Si1182-A-GM Heart-Rate Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads the Si1182 heart-rate register once per second, applies a 5-sample
 * moving-average filter, validates the BPM range, and logs valid readings
 * to heart_rate.csv.  Handles SIGINT for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_hr si1182_hr.c -lpigpio -lrt
 * Run:    sudo ./si1182_hr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 constants (from datasheet) ---- */
#define SI1182_I2C_ADDR        0x60
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_HW_REV      0x01
#define SI1182_REG_SEQ_ID      0x02
#define SI1182_REG_INT_CFG     0x03
#define SI1182_REG_IRQ_ENABLE  0x04
#define SI1182_REG_IRQ_MODE1   0x05
#define SI1182_REG_IRQ_MODE2   0x06
#define SI1182_REG_HW_KEY      0x07
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_MEAS_RATE1  0x09
#define SI1182_REG_PS_LED21    0x0A
#define SI1182_REG_PS_LED3     0x0B
#define SI1182_REG_PS1_ADCMUX  0x0C
#define SI1182_REG_PS2_ADCMUX  0x0D
#define SI1182_REG_PS3_ADCMUX  0x0E
#define SI1182_REG_PS_ENCODING 0x0F
#define SI1182_REG_PS1_DATA0   0x10
#define SI1182_REG_PS1_DATA1   0x11
#define SI1182_REG_PS2_DATA0   0x12
#define SI1182_REG_PS2_DATA1   0x13
#define SI1182_REG_PS3_DATA0   0x14
#define SI1182_REG_PS3_DATA1   0x15
#define SI1182_REG_HR_DATA0    0x16
#define SI1182_REG_HR_DATA1    0x17
#define SI1182_REG_HR_CONFIG   0x18
#define SI1182_REG_HR_RATE0    0x19
#define SI1182_REG_HR_RATE1    0x1A
#define SI1182_REG_FIFO_CONFIG 0x1B
#define SI1182_REG_FIFO_READ   0x1C
#define SI1182_REG_COMMAND     0x1D

#define SI1182_PART_ID_VAL     0x82
#define SI1182_HW_REV_VAL      0x00

#define SI1182_CMD_RESET       0x01
#define SI1182_CMD_PS_FORCE    0x05
#define SI1182_CMD_ALS_FORCE   0x06
#define SI1182_CMD_PS_PAUSE    0x0B
#define SI1182_CMD_ALS_PAUSE   0x0C
#define SI1182_CMD_PS_AUTO     0x0D
#define SI1182_CMD_ALS_AUTO    0x0E
#define SI1182_CMD_PS_AUTO_FORCE 0x0F
#define SI1182_CMD_ALS_AUTO_FORCE 0x10

#define SI1182_HW_KEY_VAL      0x17

#define SI1182_FIFO_CONFIG_VAL 0x00

#define SI1182_HR_CONFIG_VAL   0x01
#define SI1182_HR_RATE0_VAL    0x0A
#define SI1182_HR_RATE1_VAL    0x00

#define SI1182_INT_CFG_VAL     0x01
#define SI1182_IRQ_ENABLE_VAL  0x01
#define SI1182_IRQ_MODE1_VAL   0x00
#define SI1182_IRQ_MODE2_VAL   0x00

#define SI1182_PS_LED21_VAL    0x0F
#define SI1182_PS_LED3_VAL     0x00
#define SI1182_PS_ENCODING_VAL 0x00

#define SI1182_PS1_ADCMUX_VAL  0x03
#define SI1182_PS2_ADCMUX_VAL  0x03
#define SI1182_PS3_ADCMUX_VAL  0x03

#define SI1182_MEAS_RATE0_VAL  0x0A
#define SI1182_MEAS_RATE1_VAL  0x00

#define SI1182_FIFO_READ_VAL   0x00

#define SI1182_FIFO_DEPTH      16

/* ---- Application constants ---- */
#define I2C_BUS               1
#define SAMPLE_INTERVAL_US    1000000  /* 1 second */
#define MOVING_AVG_SIZE       5
#define MIN_BPM               30
#define MAX_BPM               220
#define LOG_FILE_NAME         "heart_rate.csv"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Helper: write a single byte to a register ---- */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ---- Helper: read a single byte from a register ---- */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Helper: read a 16-bit little-endian register pair ---- */
static int si1182_read_reg16(int handle, uint8_t reg_lo, uint16_t *value)
{
    uint8_t lo, hi;
    if (si1182_read_reg(handle, reg_lo, &lo) < 0)
        return -1;
    if (si1182_read_reg(handle, reg_lo + 1, &hi) < 0)
        return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Initialize the Si1182 sensor ---- */
static int si1182_init(int handle)
{
    uint8_t part_id, hw_rev;

    /* 1. Verify PART_ID and HW_REV to confirm sensor is present */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1182_PART_ID_VAL) {
        fprintf(stderr, "[ERROR] PART_ID mismatch: got 0x%02X, expected 0x%02X "
                "(sensor absent or wrong device)\n",
                part_id, SI1182_PART_ID_VAL);
        return -1;
    }

    if (si1182_read_reg(handle, SI1182_REG_HW_REV, &hw_rev) < 0)
        return -1;
    if (hw_rev != SI1182_HW_REV_VAL) {
        fprintf(stderr, "[WARN] HW_REV mismatch: got 0x%02X, expected 0x%02X\n",
                hw_rev, SI1182_HW_REV_VAL);
    }

    /* 2. Software reset */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* 3. Write HW_KEY to enable register writes */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0)
        return -1;

    /* 4. Configure FIFO */
    if (si1182_write_reg(handle, SI1182_REG_FIFO_CONFIG, SI1182_FIFO_CONFIG_VAL) < 0)
        return -1;

    /* 5. Configure HR measurement */
    if (si1182_write_reg(handle, SI1182_REG_HR_CONFIG, SI1182_HR_CONFIG_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_HR_RATE0, SI1182_HR_RATE0_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_HR_RATE1, SI1182_HR_RATE1_VAL) < 0)
        return -1;

    /* 6. Configure interrupt / LED */
    if (si1182_write_reg(handle, SI1182_REG_INT_CFG, SI1182_INT_CFG_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_IRQ_ENABLE, SI1182_IRQ_ENABLE_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_IRQ_MODE1, SI1182_IRQ_MODE1_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_IRQ_MODE2, SI1182_IRQ_MODE2_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_LED21, SI1182_PS_LED21_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_LED3, SI1182_PS_LED3_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_ENCODING, SI1182_PS_ENCODING_VAL) < 0)
        return -1;

    /* 7. Configure photodiode mux / encoding */
    if (si1182_write_reg(handle, SI1182_REG_PS1_ADCMUX, SI1182_PS1_ADCMUX_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS2_ADCMUX, SI1182_PS2_ADCMUX_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS3_ADCMUX, SI1182_PS3_ADCMUX_VAL) < 0)
        return -1;

    /* 8. Configure measurement rate */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE0, SI1182_MEAS_RATE0_VAL) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE1, SI1182_MEAS_RATE1_VAL) < 0)
        return -1;

    /* 9. Start autonomous HR measurement */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_ALS_AUTO) < 0)
        return -1;

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

/* ---- Read heart-rate register (16-bit, little-endian) ---- */
static int si1182_read_hr(int handle, uint16_t *hr_out)
{
    uint16_t raw;
    if (si1182_read_reg16(handle, SI1182_REG_HR_DATA0, &raw) < 0)
        return -1;
    *hr_out = raw;
    return 0;
}

/* ---- Moving-average filter ---- */
static int moving_average_filter(const uint16_t *data, int size, int window)
{
    if (size < window)
        return -1;

    long sum = 0;
    for (int i = 0; i < window; i++)
        sum += data[i];

    long avg = sum / window;
    return (int)avg;
}

/* ---- Log a valid reading to CSV ---- */
static int log_heart_rate(FILE *fp, int bpm)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() on log file failed\n");
        return -1;
    }
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x60 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1182 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; continuing\n");
    }

    printf("Si1182 heart-rate logging started.  Press Ctrl+C to stop.\n");

    /* Ring buffer for moving-average window */
    uint16_t hr_buf[MOVING_AVG_SIZE];
    int      buf_idx = 0;
    int      buf_count = 0;

    while (g_running) {
        uint16_t raw_hr;
        if (si1182_read_hr(g_i2c_handle, &raw_hr) < 0) {
            fprintf(stderr, "[WARN] I2C read error; retrying next cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Update ring buffer */
        hr_buf[buf_idx] = raw_hr;
        buf_idx = (buf_idx + 1) % MOVING_AVG_SIZE;
        if (buf_count < MOVING_AVG_SIZE)
            buf_count++;

        int filtered = moving_average_filter(hr_buf, buf_count, MOVING_AVG_SIZE);
        if (filtered < 0) {
            fprintf(stderr, "[WARN] Buffer too small for filter; skipping\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Validate BPM range */
        if (filtered >= MIN_BPM && filtered <= MAX_BPM) {
            if (log_heart_rate(g_log_file, filtered) < 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing\n");
            } else {
                printf("BPM: %d\n", filtered);
            }
        } else {
            fprintf(stderr, "[WARN] BPM out of range: %d (valid %d-%d)\n",
                    filtered, MIN_BPM, MAX_BPM);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

