/*
 * Flame sensor monitor for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 (digital output, active-low)
 * Wiring : DO  -> GPIO17 (BCM 17, physical pin 11)
 *          VCC -> 3.3 V
 *          GND -> GND
 * Library: libgpiod (modern GPIO character-device API)
 *
 * Build  : gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_INTERVAL_MS 100
#define LOG_FILE_NAME    "flame_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_flame_event(FILE *log_file)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "FLAME DETECTED at %s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) == EOF) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
    }

    printf("FLAME DETECTED at %s\n", timestamp);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
