/*
 * touch_counter.c — 8-channel TTP226 touch sensor → 8-bit binary counter
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter
 *
 * Hardware:
 *   TTP226 OUT1..OUT8  →  BCM 5, 6, 7, 8, 9, 10, 11, 12  (3.3 V logic)
 *   Counter bits       →  BCM 17, 18, 19, 20, 21, 22, 23, 24
 *
 * Behaviour:
 *   After a 200 ms stabilization delay the program polls the sensor lines
 *   every 10 ms.  On a rising edge (0 V → 3.3 V) the counter is incremented
 *   and the eight output bits are updated via libgpiod bulk/config writes.
 *   Touch events are logged to touch_log.txt with an ISO-8601 UTC timestamp
 *   and printed to stdout.  SIGINT / SIGTERM trigger a clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US  10000   /* 10 ms  */
#define STABILIZE_DELAY_US 200000 /* 200 ms */

static const unsigned int sensor_pins[NUM_CHANNELS] = {
    5, 6, 7, 8, 9, 10, 11, 12
};
static const unsigned int counter_pins[NUM_CHANNELS] = {
    17, 18, 19, 20, 21, 22, 23, 24
};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *log_file, int channel, int counter_value)
{
    time_t rawtime;
    struct tm tm_utc;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, Channel: %d, Counter: %d\n",
                timestamp, channel, counter_value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Counter update                                                      */
/* ------------------------------------------------------------------ */
static int update_counter(struct gpiod_line_bulk *lines,
                          unsigned char *counter,
                          FILE *log_file)
{
    int i;
    int prev = *counter;
    *counter = (unsigned char)((*counter + 1) & 0xFF);

    for (i = 0; i < NUM_CHANNELS; i++) {
        int val = (*counter >> i) & 1;
        if (gpiod_line_set_value(lines[i].line, val) != 0) {
            fprintf(stderr,
                    "Failed to set counter bit %d (pin %u): %s\n",
                    i, counter_pins[i], strerror(errno));
            return -1;
        }
    }

    log_event(log_file, 0, *counter);
    printf("Touch on channel 0 | Counter: %d\n", *counter);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines[NUM_CHANNELS];
    struct gpiod_line_bulk prev_lines[NUM_CHANNELS];
    unsigned char counter = 0;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire sensor lines as inputs */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i].line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i].line == NULL) {
            fprintf(stderr,
                    "Failed to get sensor line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i].line, "ttp226-sensor") != 0) {
            fprintf(stderr,
                    "Failed to request sensor line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Acquire counter output lines as outputs, initial value 0 */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_lines[i].line = gpiod_chip_get_line(chip, counter_pins[i]);
        if (prev_lines[i].line == NULL) {
            fprintf(stderr,
                    "Failed to get counter line %u: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(prev_lines[i].line,
                                       "ttp226-counter", 0) != 0) {
            fprintf(stderr,
                    "Failed to request counter line %u as output: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Open log file in append mode */
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n",
                strerror(errno));
        /* Continue without logging, but stdout is still usable */
    }

    /* Stabilize sensors */
    usleep(STABILIZE_DELAY_US);

    /* Main polling loop */
    while (g_running) {
        int read_error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i].line);
            if (val < 0) {
                fprintf(stderr,
                        "Error reading sensor line %u: %s\n",
                        sensor_pins[i], strerror(errno));
                read_error = 1;
                continue;
            }

            /* Rising edge: 0 → 1 */
            if (val == 1 &&
                gpiod_line_get_value(prev_lines[i].line) == 0) {
                if (update_counter(&prev_lines[i], &counter, log_file) != 0) {
                    goto cleanup;
                }
            }

            /* Update previous state for next iteration */
            if (gpiod_line_set_value(prev_lines[i].line, val) != 0) {
                fprintf(stderr,
                        "Failed to update prev state on pin %u: %s\n",
                        counter_pins[i], strerror(errno));
            }
        }

        if (read_error) {
            usleep(POLL_INTERVAL_US);
            continue;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all output pins to 0 on exit */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (prev_lines[i].line != NULL) {
            (void)gpiod_line_set_value(prev_lines[i].line, 0);
            gpiod_line_release(prev_lines[i].line);
        }
    }

    /* Release sensor lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i].line != NULL) {
            gpiod_line_release(lines[i].line);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        }
    }

    return ret;
}

