        return -1;
    }

    if (fprintf(g_log, "%s, Sensor %d tilted\n", timestamp, sensor_id) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int prev1 = 1, prev2 = 1;
    int ret = EXIT_SUCCESS;

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

