    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen log file");
        return EXIT_FAILURE;
    }

    /* ---- initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO17 as input with pull-up ---- */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", SENSOR1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO18 as input with pull-up ---- */
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", SENSOR2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started (GPIO%d, GPIO%d).\n",
           SENSOR1_GPIO, SENSOR2_GPIO);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- main polling loop ---- */
    while (g_running) {
        int v1 = gpioRead(SENSOR1_GPIO);
        int v2 = gpioRead(SENSOR2_GPIO);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "gpioRead error (v1=%d, v2=%d)\n", v1, v2);
            ret = EXIT_FAILURE;
            break;
        }

        /* Sensor 1: inactive (high) -> active (low) -> log */
        if (v1 == 0 && prev1 == 1) {
            if (log_event(1) != 0) {
                ret = EXIT_FAILURE;
                break;
            }
        }

        /* Sensor 2: inactive (high) -> active (low) -> log */
        if (v2 == 0 && prev2 == 1) {
            if (log_event(2) != 0) {
                ret = EXIT_FAILURE;
                break;
            }
        }

        prev1 = v1;
        prev2 = v2;

        gpioDelay(POLL_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return ret;
}

