#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN     22
#define LOG_FILE    "obstacle_log.csv"
#define POLL_US     100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log != NULL) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }

    /* Ensure the LED is off before releasing the line. */
    gpioWrite(LED_PIN, 0);

    /* Release all pigpio resources. */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        return -1;
    }

    /* Start with the LED off. */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int init_log(void)
{
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("Error opening log file");
        return -1;
    }

    /* Write a header only if the file is empty. */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,sensor1,sensor2,led_state\n");
        fflush(g_log);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(int s1, int s2, int led)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed; logging with epoch.\n");
        fprintf(g_log, "%ld,%d,%d,%d\n", (long)rawtime, s1, s2, led);
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);
        fprintf(g_log, "%s,%d,%d,%d\n", ts, s1, s2, led);
    }
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;

    /* Install SIGINT handler for graceful shutdown. */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_log() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        /* TCRT5000 is active-low: 0 => obstacle detected, 1 => clear. */
        int led = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, led) != 0) {
            fprintf(stderr, "Warning: gpioWrite(LED) failed.\n");
        }

        log_data(s1, s2, led);

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

