/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICS-40180 analog MEMS microphone
 * sampling at ~8 kHz (125 µs period) and lighting an LED on GPIO17
 * (BCM, physical pin 11) for 100 ms on each sound-peak detection.
 *
 * Wiring:
 *   ICS-40180 VOUT  -> GPIO4  (BCM, physical pin 7)
 *   ICS-40180 GND   -> GND
 *   ICS-40180 VDD   -> 3.3 V
 *   LED anode       -> GPIO17 (BCM, physical pin 11) via 330 Ω resistor
 *   LED cathode     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mic_peak mic_peak.c -lpigpio -lrt
 * Run:
 *   sudo ./mic_peak
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN        4    /* BCM 4  – ICS-40180 analog output */
#define LED_PIN        17   /* BCM 17 – LED anode */

#define SAMPLE_US      125  /* 8 kHz sampling period */
#define LED_ON_US      100000 /* 100 ms LED on duration */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_local;
    localtime_r(&ts.tv_sec, &tm_local);
    printf("%04d-%02d-%02d %02d:%02d:%02d.%03ld\n",
           tm_local.tm_year + 1900, tm_local.tm_mon + 1, tm_local.tm_mday,
           tm_local.tm_hour, tm_local.tm_min, tm_local.tm_sec,
           ts.tv_nsec / 1000000L);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Best-effort LED off; ignore errors during shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n",
                LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sampling ICS-40180 on GPIO%d at ~8 kHz. Press Ctrl+C to exit.\n",
           MIC_PIN);
    fflush(stdout);

    while (g_running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", MIC_PIN);
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (level == 1) {
            print_timestamp_ms();

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite(ON) failed on GPIO%d.\n",
                        LED_PIN);
            }

            gpioDelay(LED_ON_US);

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite(OFF) failed on GPIO%d.\n",
                        LED_PIN);
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

