#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    17
#define CENTER_SENSOR_PIN  27
#define RIGHT_SENSOR_PIN   22
#define POLL_DELAY_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    unsigned pins[] = {LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        unsigned pin = pins[i];

        if (gpioSetMode(pin, PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %u as input.\n", pin);
            gpioTerminate();
            return -1;
        }

        if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: failed to set pull-up on GPIO %u.\n", pin);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static int read_sensor(unsigned pin, int *value)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: failed to read GPIO %u.\n", pin);
        return -1;
    }
    *value = v;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("SunFounder 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%d, Center: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int left, center, right;

        if (read_sensor(LEFT_SENSOR_PIN, &left) < 0 ||
            read_sensor(CENTER_SENSOR_PIN, &center) < 0 ||
            read_sensor(RIGHT_SENSOR_PIN, &right) < 0) {
            fprintf(stderr, "Error: sensor read failure, continuing...\n");
        } else {
            printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

