code:
/*
 * Si1175 Visible Ambient Light Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads the Si1175 visible ALS data (LSB + MSB registers) on I2C bus 1
 * every 100 ms and logs the raw 16-bit value to stdout.
 *
 * Wiring:
 *   Si1175 SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   Si1175 SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_als si1175_als.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1175 constants (per datasheet) ---- */
#define SI1175_I2C_ADDR        0x60
#define SI1175_REG_ALS_VIS_LSB 0x0A
#define SI1175_REG_ALS_VIS_MSB 0x0B

#define I2C_BUS_DEV            "/dev/i2c-1"
#define SAMPLE_PERIOD_US       100000  /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1175 register.                               */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si1175_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1175 register.                              */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int si1175_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    /* Send the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1175: verify it is present by reading the part ID.*/
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int si1175_init(int fd)
{
    uint8_t part_id;
    if (si1175_read_reg(fd, 0x00, &part_id) != 0) {
        fprintf(stderr, "Cannot read Si1175 part ID — sensor absent or bus error.\n");
        return -1;
    }

    /* Si1175 part ID should be 0x75 for the Si1175 variant */
    if (part_id != 0x75) {
        fprintf(stderr, "Unexpected Si1175 part ID 0x%02X (expected 0x75).\n", part_id);
        return -1;
    }

    /*
     * Optional: place the Si1175 in a known measurement state.
     * The exact sequence depends on the desired configuration;
     * here we enable the visible ALS channel.
     */
    if (si1175_write_reg(fd, 0x08, 0x01) != 0)  /* ALS_VIS_ADC_MISC */
        return -1;
    if (si1175_write_reg(fd, 0x09, 0x07) != 0)  /* ALS_VIS_ADC_GAIN */
        return -1;
    if (si1175_write_reg(fd, 0x0A, 0x00) != 0)  /* ALS_VIS_ADC_MISC2 */
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit visible ALS value.                                 */
/* Returns 0 on success and stores the value in *raw; -1 on error.    */
/* ------------------------------------------------------------------ */
static int si1175_read_als(int fd, uint16_t *raw)
{
    uint8_t lsb, msb;

    if (si1175_read_reg(fd, SI1175_REG_ALS_VIS_LSB, &lsb) != 0)
        return -1;
    if (si1175_read_reg(fd, SI1175_REG_ALS_VIS_MSB, &msb) != 0)
        return -1;

    *raw = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the I2C bus ---- */
