/*
 * Keywish 3-Way Tracking Sensor poller for Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   Left   sensor  -> GPIO2 (pin 3)
 *   Middle sensor  -> GPIO3 (pin 5)
 *   Right  sensor  -> GPIO4 (pin 7)
 *   VCC    -> 3.3 V (pin 1)
 *   GND    -> GND   (pin 6)
 *
 * Polls every 100 ms and logs "L:<0|1> M:<0|1> R:<0|1>" to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sensor_poll sensor_poll.c -lpigpio -lrt
 * Run:    sudo ./sensor_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN    2
#define MIDDLE_PIN  3
#define RIGHT_PIN   4
#define POLL_US     100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static int read_sensor(int pin, int *out)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    *out = v;
    return 0;
}

int main(void)
{
    int rc = EXIT_SUCCESS;

    if (install_sigint_handler() != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Request each line as an input. */
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetMode(MIDDLE_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIDDLE_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* Enable internal pull-downs so the lines read 0 when the sensor is
     * disconnected or its output is open. */
    gpioSetPullUpDown(LEFT_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(MIDDLE_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(RIGHT_PIN, PI_PUD_DOWN);

    while (g_running) {
        int l, m, r;

        if (read_sensor(LEFT_PIN, &l) != 0 ||
            read_sensor(MIDDLE_PIN, &m) != 0 ||
            read_sensor(RIGHT_PIN, &r) != 0) {
            rc = EXIT_FAILURE;
            break;
        }

        printf("L:%d M:%d R:%d\n", l, m, r);
        fflush(stdout);

        gpioDelay(POLL_US);
    }

cleanup:
    gpioTerminate();
    return rc;
}

