/*
 * TTP226 8-channel capacitive touch sensor poller for Raspberry Pi 3 Model B+
 *
 * Wiring (TTP226 -> Raspberry Pi 3 B+):
 *   VCC  -> Pin 1 (3.3 V)
 *   GND  -> Pin 9 (GND)
 *   OUT1 -> Pin 5 (BCM 5)  -> TP1
 *   OUT2 -> Pin 6 (BCM 6)  -> TP2
 *   OUT3 -> Pin 13 (BCM 13) -> TP3
 *   OUT4 -> Pin 19 (BCM 19) -> TP4
 *   OUT5 -> Pin 26 (BCM 26) -> TP5
 *   OUT6 -> Pin 12 (BCM 12) -> TP6
 *   OUT7 -> Pin 16 (BCM 16) -> TP7
 *   OUT8 -> Pin 20 (BCM 20) -> TP8
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_poll touch_poll.c -lrt
 *
 * Run:
 *   ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

/* BCM pin numbers */
static const unsigned int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%.3fs] ", (double)ts.tv_sec + (double)ts.tv_nsec / 1e9);
    } else {
        perror("clock_gettime");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for BCM %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor polling started. Press Ctrl+C to exit.\n");

    while (g_running) {
        print_timestamp();

        bool read_error = false;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for BCM %u: %s\n",
                        channel_pins[i], strerror(errno));
                read_error = true;
                break;
            }
            values[i] = v;
        }

        if (read_error) {
            ret = EXIT_FAILURE;
            break;
        }

        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);

        /* Sleep 200 ms using nanosleep for portability */
        struct timespec req = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        while (nanosleep(&req, &req) == -1 && errno == EINTR && g_running) {
            /* Retry if interrupted by signal */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all lines and close the chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

