#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcnth>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQ   1000
#define PWM_RANGE  255
#define FADE_STEPS 50
#define FADE_DELAY_US (5000000 / FADE_STEPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN %d as output", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN %d as output", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN %d as output", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on RED_PIN %d", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GREEN_PIN %d", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on BLUE_PIN %d", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on RED_PIN %d", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on GREEN_PIN %d", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on BLUE_PIN %d", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_led_color(uint8_t red, uint8_t green, uint8_t blue)
{
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

static void fade_to_color(uint8_t red, uint8_t green, uint8_t blue)
{
    uint8_t r_cur = gpioGetPWMdutycycle(RED_PIN);
    uint8_t g_cur = gpioGetPWMdutycycle(GREEN_PIN);
    uint8_t b_cur = gpioGetPWMdutycycle(BLUE_PIN);

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        uint8_t r = r_cur + (int)(red   - r_cur) * i / FADE_STEPS;
        uint8_t g = g_cur + (int)(green - g_cur) * i / FADE_STEPS;
        uint8_t b = b_cur + (int)(blue  - b_cur) * i / FADE_STEPS;

        set_led_color(r, g, b);
        usleep(FADE_DELAY_US);
    }

    set_led_color(red, green, blue);
}

static void generate_random_hue(uint8_t *red, uint8_t *green, uint8_t *blue)
{
    int hue = rand() % 360;
    float r = 0.0f, g = 0.0f, b = 0.0f;

    if (hue < 60) {
        r = 1.0f; g = (float)hue / 60.0f; b = 0.0f;
    } else if (hue < 120) {
        r = 1.0f - (float)(hue - 60) / 60.0f; g = 1.0f; b = 0.0f;
    } else if (hue < 180) {
        r = 0.0f; g = 1.0f; b = (float)(hue - 120) / 60.0f;
    } else if (hue < 240) {
        r = 0.0f; g = 1.0f - (float)(hue - 180) / 60.0f; b = 1.0f;
    } else if (hue < 300) {
        r = (float)(hue - 240) / 60.0f; g = 0.0f; b = 1.0f;
    } else {
        r = 1.0f; g = 0.0f; b = 1.0f - (float)(hue - 300) / 60.0f;
    }

    *red   = (uint8_t)(r * 255.0f);
    *green = (uint8_t)(g * 255.0f);
    *blue  = (uint8_t)(b * 255.0f);
}

static void cleanup(void)
{
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("rgb_led_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    int urandom = open("/dev/urandom", O_RDONLY);
    if (urandom < 0) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %m");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t red, green, blue;
    uint8_t next_red, next_green, next_blue;

    while (g_running) {
        uint8_t buf[4];
        ssize_t n = read(urandom, buf, sizeof(buf));
        if (n != (ssize_t)sizeof(buf)) {
            syslog(LOG_ERR, "Failed to read from /dev/urandom: %m");
            break;
        }

        uint32_t seed = ((uint32_t)buf[0] << 24) |
                        ((uint32_t)buf[1] << 16) |
                        ((uint32_t)buf[2] << 8)  |
                        (uint32_t)buf[3];
        srand(seed);

        generate_random_hue(&next_red, &next_green, &next_blue);

        syslog(LOG_INFO, "Fading to RGB(%d, %d, %d)", next_red, next_green, next_blue);

        fade_to_color(next_red, next_green, next_blue);

        if (!g_running) break;

        generate_random_hue(&red, &green, &blue);
        fade_to_color(red, green, blue);
    }

    close(urandom);
    cleanup();
    return EXIT_SUCCESS;
}

