/*
 * TCS34725 Color Sensor Reader with RGB LED Indicator
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1  (BCM pins 2 = SDA, 3 = SCL)
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o tcs34725_led tcs34725_led.c -lpigpio -lrt
 * Run:    sudo ./tcs34725_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- TCS34725 register definitions ---- */
#define TCS34725_ADDRESS        0x29
#define TCS34725_COMMAND_BIT    0x80

#define TCS34725_ENABLE         0x00
#define TCS34725_ATIME          0x01
#define TCS34725_CONTROL        0x0F
#define TCS34725_ID             0x12
#define TCS34725_STATUS         0x13
#define TCS34725_CDATAL         0x14
#define TCS34725_RDATAL         0x16
#define TCS34725_GDATAL         0x18
#define TCS34725_BDATAL         0x1A

#define TCS34725_ENABLE_PON     0x01
#define TCS34725_ENABLE_AEN     0x02

#define TCS34725_ID_VALUE       0x44

/* ---- Application constants ---- */
#define I2C_BUS                "/dev/i2c-1"
#define LED_GPIO               17
#define RED_THRESHOLD          200
#define POLL_DELAY_US          200000   /* 200 ms */
#define INTEGRATION_TIME_MS    154

/* ---- Globals for cleanup ---- */
static int g_i2c_fd = -1;
static int g_led_gpio = -1;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) for reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (cmd) for block reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int sensor_init(int fd)
{
    uint8_t id = 0;

    if (i2c_read_reg(fd, TCS34725_ID, &id) != 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    usleep(3000);  /* 2.4 ms minimum power-on delay */

    /* Enable RGBC ADC */
    if (i2c_write_reg(fd, TCS34725_ENABLE,
                      TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    /* Integration time ~154 ms (0xD5 = 213 cycles * 2.4 ms) */
    if (i2c_write_reg(fd, TCS34725_ATIME, 0xD5) != 0)
        return -1;

    /* Wait for first integration cycle to complete */
    usleep(INTEGRATION_TIME_MS * 1000);
    return 0;
}

/* ---- Read raw 16-bit channel values ---- */
static int read_raw_channels(int fd, uint16_t *r, uint16_t *g,
                             uint16_t *b, uint16_t *c)
{
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATAL, buf, 8) != 0)
        return -1;

    *c = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *r = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *g = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *b = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    return 0;
}

/* ---- Calibrated color values ---- */
static void calibrate_colors(uint16_t r, uint16_t g, uint16_t b,
                             uint16_t c,
                             float *cr, float *cg, float *cb)
{
    /*
     * TCS34725 default gain (0x00) gives 1x scaling.
     * Channel sensitivities (approximate):
     *   R ~ 0.0736 us/count, G ~ 0.0610 us/count, B ~ 0.0146 us/count
     *   C ~ 0.0030 us/count
     * Adjust constants if your specific breakout has different scaling.
     */
    const float r_scale = 0.0736f;
    const float g_scale = 0.0610f;
    const float b_scale = 0.0146f;
    const float c_scale = 0.0030f;

    *cr = (float)r / r_scale;
    *cg = (float)g / g_scale;
    *cb = (float)b / b_scale;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_led_gpio >= 0) {
        gpioWrite(g_led_gpio, 0);
        gpioSetMode(g_led_gpio, PI_INPUT);
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        (void)i2c_write_reg(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    g_led_gpio = LED_GPIO;
    if (gpioSetMode(g_led_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", g_led_gpio);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(g_led_gpio, 0);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TCS34725 color sensor ready. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t r, g, b, c;

        if (read_raw_channels(g_i2c_fd, &r, &g, &b, &c) == 0) {
            float cr, cg, cb;
            calibrate_colors(r, g, b, c, &cr, &cg, &cb);

            printf("R: %5u  G: %5u  B: %5u  C: %5u  |  R: %.2f  G: %.2f  B: %.2f\n",
                   r, g, b, c, cr, cg, cb);

            if (cr > RED_THRESHOLD) {
                gpioWrite(g_led_gpio, 1);
            } else {
                gpioWrite(g_led_gpio, 0);
            }
        } else {
            fprintf(stderr, "Read failed; attempting sensor re-initialization...\n");
            /* Power down first to clear any stale state */
            (void)i2c_write_reg(g_i2c_fd, TCS34725_ENABLE, 0x00);
            usleep(10000);
            if (sensor_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-initialization failed; retrying next cycle...\n");
            }
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

