/*
 * BH1750 ambient-light reader + WS2812B brightness controller.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: BH1750FVI on I2C bus 1, address 0x5C
 * LEDs:   10 WS2812B pixels on GPIO18 (BCM), PCM_CLK
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_led light_led.c -lpigpio -lrt
 * Run:    sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define BH1750_ADDR          0x5C
#define BH1750_CMD_CONT_HRES 0x10   /* continuous high-resolution mode */
#define BH1750_CONV_MS       180    /* conversion time after command */

#define LED_COUNT            10
#define LED_GPIO             18     /* BCM 18 = PCM_CLK */
#define PWM_RANGE            255
#define PWM_FREQ             800000 /* 800 kHz, well within WS2812B spec */

#define SAMPLE_PERIOD_US     500000 /* 0.5 s */
#define MAX_RETRIES          3

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */

static void signal_handler(int sig);
static int  bh1750_init(void);
static int  bh1750_read_lux(float *lux_out);
static void led_set_brightness(uint8_t brightness);
static uint8_t map_lux_to_brightness(float lux);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ BH1750 ----------------------------------- */

/*
 * Initialise the BH1750: open the I2C bus, set the continuous high-res
 * mode, and wait for the first conversion to complete.
 */
static int bh1750_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, BH1750_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }

    /* Issue the continuous high-resolution measurement command */
    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_CONT_HRES) < 0) {
        fprintf(stderr, "Error: failed to write BH1750 command\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow the first conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);
    return 0;
}

/*
 * Read the ambient light level in lux.
 * Returns 0 on success, -1 on error.
 */
static int bh1750_read_lux(float *lux_out)
{
    if (g_i2c_handle < 0)
        return -1;

    char buf[2];
    int n = i2cReadDevice(g_i2c_handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 2)\n", n);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------- LEDs ------------------------------------ */

/*
 * Generate a WS2812B bitstream using the pigpio hardware PWM/wave capability.
 *
 * The WS2812B expects a 1-bit stream at T0H ~0.4 us and T0L ~0.8 us,
 * T1H ~0.8 us, T1L ~0.4 us.  pigpio's gpioWaveAddGeneric() lets us specify
 * pulses in microseconds; we use a 50% duty cycle for simplicity.
 */
static void led_set_brightness(uint8_t brightness)
{
    if (brightness > 255)
        brightness = 255;

    /*
     * WS2812B expects ~800 kHz, 24-bit data.  We send 10 LEDs × 24 bits.
     * Each bit = 2 pulses: high + low.
     */
    int total_pulses = LED_COUNT * 24 * 2;
    gpioPulse_t *pulses = malloc((size_t)total_pulses * sizeof(gpioPulse_t));
    if (!pulses) {
        fprintf(stderr, "Error: out of memory for wave pulses\n");
        return;
    }

    int idx = 0;
    for (int led = 0; led < LED_COUNT; led++) {
        uint32_t grb = ((uint32_t)brightness << 16) |
                       ((uint32_t)brightness << 8)  |
                       (uint32_t)brightness;

        for (int bit = 23; bit >= 0; bit--) {
            int one_us = 1;
            if (grb & (1u << bit)) {
                /* Logic 1: T1H ~0.8 us, T1L ~0.4 us */
                pulses[idx].gpioOn  = (1 << LED_GPIO);
                pulses[idx].gpioOff = 0;
                pulses[idx].usDelay = 1;
                idx++;
                pulses[idx].gpioOn  = 0;
                pulses[idx].gpioOff = (1 << LED_GPIO);
                pulses[idx].usDelay = 1;
                idx++;
            } else {
                /* Logic 0: T0H ~0.4 us, T0L ~0.8 us */
                pulses[idx].gpioOn  = (1 << LED_GPIO);
                pulses[idx].gpioOff = 0;
                pulses[idx].usDelay = 1;
                idx++;
                pulses[idx].gpioOn  = 0;
                pulses[idx].gpioOff = (1 << LED_GPIO);
                pulses[idx].usDelay = 1;
                idx++;
            }
        }
    }

    gpioWaveClear();
    if (gpioWaveAddGeneric(idx, pulses) < 0) {
        fprintf(stderr, "Error: gpioWaveAddGeneric failed\n");
        free(pulses);
        return;
    }
    free(pulses);

    int wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Error: gpioWaveCreate failed: %s\n",
                pigpio_error(wave_id));
        return;
    }

    if (gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT) < 0) {
        fprintf(stderr, "Error: gpioWaveTxSend failed\n");
        gpioWaveDelete(wave_id);
        return;
    }

    /* Wait for the wave to complete before freeing the handle */
    while (gpioWaveTxBusy())
        gpioDelay(100);

    gpioWaveDelete(wave_id);
}

/*
 * Map the ambient light lux to a logarithmic brightness level.
 * Returns 0..255.
 */
static uint8_t map_lux_to_brightness(float lux)
{
    if (lux <= 0.0f)
        return 0;

    /*
     * Logarithmic mapping:
     *   lux   ->  brightness
     *   0.0   ->  0
     *   10.0  ->  10
     *   100.0 ->  100
     *   1000.0->  255
     */
    float b = 255.0f * log10f(lux + 1.0f) / log10f(1000.0f + 1.0f);
    if (b < 0.0f)   b = 0.0f;
    if (b > 255.0f) b = 255.0f;
    return (uint8_t)b;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Turn off LEDs */
    led_set_brightness(0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output (wave PWM) */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range (duty-cycle resolution) */
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency (800 kHz) */
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise BH1750 sensor */
    if (bh1750_init() < 0) {
        fprintf(stderr, "Error: BH1750 initialisation failed — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 initialised on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, BH1750_ADDR);
    printf("LEDs on GPIO%d (%d × WS2812B).  Sampling every %d ms.\n",
           LED_GPIO, LED_COUNT, SAMPLE_PERIOD_US / 1000);
    printf("Press Ctrl-C to exit.\n");

    /* Main loop */
    while (g_running) {
        float lux = 0.0f;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (bh1750_read_lux(&lux) == 0) {
                ok = true;
                break;
            }
            gpioDelay(10000); /* 10 ms back-off before retry */
        }

        if (!ok) {
            fprintf(stderr, "Warning: BH1750 read failed after %d attempts — "
                            "LEDs set to safe state (off).\n", MAX_RETRIES);
            led_set_brightness(0);
        } else {
            uint8_t brightness = map_lux_to_brightness(lux);
            led_set_brightness(brightness);
            printf("Lux: %6.2f  ->  brightness: %3u\n", lux, brightness);
        }

        /* Sleep SAMPLE_PERIOD_US, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(SAMPLE_PERIOD_US / 10);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

