/*
 * Raspberry Pi Zero W — BH1750 ambient light sensor → APA102 LED strip
 *
 * I2C bus 1 (BH1750): /dev/i2c-1   (address 0x23)
 * SPI bus 0 (APA102): /dev/spidev0.0 (1 MHz, mode 0)
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_led light_led.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_PWR_ON   0x01
#define BH1750_CMD_RESET    0x07
#define BH1750_CMD_CONT_HRES 0x10   /* continuous high-resolution mode */
#define BH1750_CONV_MS      120    /* max conversion time */

#define SPI_BUS        "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000
#define SPI_BITS       8
#define SPI_MODE       0

#define NUM_LEDS       30
#define MAX_BRIGHTNESS 255

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---------- BH1750 ---------- */

static int bh1750_init(int fd)
{
    if (i2c_write_cmd(fd, BH1750_CMD_PWR_ON) < 0)  return -1;
    if (i2c_write_cmd(fd, BH1750_CMD_RESET)  < 0)  return -1;
    if (i2c_write_cmd(fd, BH1750_CMD_CONT_HRES) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ---------- APA102 SPI ---------- */

static int spi_init(int *spi_fd)
{
    int fd = open(SPI_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_BUS, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd); return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd); return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd); return -1;
    }

    *spi_fd = fd;
    return 0;
}

static void apa102_send(int spi_fd, const uint8_t *data, size_t len)
{
    ssize_t total = (ssize_t)len;
    while (total > 0) {
        ssize_t n = write(spi_fd, data, (size_t)total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
            return;
        }
        total -= n;
    }
}

static void apa102_set_leds(int spi_fd, uint8_t r, uint8_t g, uint8_t b,
                            int num_leds)
{
    size_t frame_len = 4 + (num_leds * 4);
    uint8_t *frame = malloc(frame_len);
    if (!frame) {
        fprintf(stderr, "malloc failed: %s\n", strerror(errno));
        return;
    }

    /* Start frame: 4 × 0x00 */
    memset(frame, 0x00, 4);

    uint8_t *p = frame + 4;
    for (int i = 0; i < num_leds; i++) {
        /* APA102: 0–255 → 32–0 in each channel byte */
        *p++ = 0xE0 | (b >> 3);
        *p++ = 0xE0 | (g >> 3);
        *p++ = 0xE0 | (r >> 3);
        *p++ = 0x00;
    }

    /* End frame: 4 × 0xFF */
    memset(p, 0xFF, 4);

    apa102_send(spi_fd, frame, frame_len);
    free(frame);
}

static void apa102_off(int spi_fd, int num_leds)
{
    apa102_set_leds(spi_fd, 0, 0, 0, num_leds);
}

/* ---------- Main ---------- */

int main(void)
{
    int i2c_fd = -1, spi_fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE(0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Light-controlled LED strip running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error — turning LEDs off.\n");
            apa102_off(spi_fd, NUM_LEDS);
            break;
        }

        int brightness = (int)((lux / 1000.0f) * MAX_BRIGHTNESS);
        if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
        if (brightness < 0) brightness = 0;

        uint8_t r = (uint8_t)brightness;
        uint8_t g = (uint8_t)brightness;
        uint8_t b = (uint8_t)brightness;

        apa102_set_leds(spi_fd, r, g, b, NUM_LEDS);

        struct timespec ts = {0, 50 * 1000 * 1000}; /* 50 ms */
        nanosleep(&ts, NULL);
    }

    /* Graceful shutdown */
    apa102_off(spi_fd, NUM_LEDS);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

