/*
 * Raspberry Pi 3 Model B+ — dual BH1750 ambient-light sensor reader + APA102 brightness controller.
 *
 * Hardware:
 *   - 3 × BH1750FVI light sensors on I2C bus 1 (addresses 0x23 or 0x5C)
 *   - APA102 RGB LED strip on hardware SPI0: MOSI=GPIO10 (BCM), SCLK=GPIO11 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm -lpigpio -lrt
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define NUM_SENSORS          3
#define BH1750_ADDR_1        0x23
#define BH1750_ADDR_2        0x5C
#define BH1750_PWR_ON        0x01
#define BH1750_RESET         0x07
#define BH1750_CONT_HRES     0x10   /* continuous high-resolution mode */
#define BH1750_CONV_MS       180    /* conversion time (ms)            */
#define SPI_CHANNEL          0      /* SPI0 CE0 (GPIO8)                 */
#define SPI_SPEED_HZ         4000000 /* 4 MHz — well within APA102 spec */
#define SPI_FLAGS            0
#define LED_COUNT            32     /* APA102 strip length             */
#define FADE_MS              500    /* brightness fade duration (ms)   */
#define LOOP_DELAY_MS        100    /* main-loop sleep (ms)            */

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[NUM_SENSORS];
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  bh1750_init(int handle);
static int  bh1750_read_lux(int handle, float *lux_out);
static int  apa102_init(void);
static int  apa102_set_brightness(uint8_t brightness);
static void apa102_turn_off(void);
