/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- BH1750 helpers ---------------------------- */

static int bh1750_init(int handle)
{
    if (i2cWriteByte(handle, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "[BH1750] PWR_ON failed (handle %d)\n", handle);
        return -1;
    }
    if (i2cWriteByte(handle, BH1750_RESET) < 0) {
        fprintf(stderr, "[BH1750] RESET failed (handle %d)\n", handle);
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out)
{
    if (i2cWriteByte(handle, BH1750_CONT_HRES) < 0) {
        fprintf(stderr, "[BH1750] CONT_HRES failed (handle %d)\n", handle);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[BH1750] read failed (handle %d, got %d)\n", handle, n);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ----------------------------- APA102 helpers ---------------------------- */

static int apa102_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[APA102] spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

static int apa102_set_brightness(uint8_t brightness)
{
    if (g_spi_handle < 0)
        return -1;

    /*
     * APA102 frame: 4-byte start frame (0x00), then 32 × 4-byte LED records,
     * each record = (B, G, R, brightness).  We send the same value for all
     * three channels so the strip appears white at the requested intensity.
     */
    uint8_t frame[LED_COUNT * 4 + 4];
    memset(frame, 0x00, sizeof(frame));
    for (int i = 0; i < LED_COUNT; i++) {
        int idx = 4 + i * 4;
        frame[idx + 0] = brightness; /* B */
        frame[idx + 1] = brightness; /* G */
        frame[idx + 2] = brightness; /* R */
        frame[idx + 3] = brightness; /* brightness */
    }

    int rc = spiWrite(g_spi_handle, (char *)frame, sizeof(frame));
    if (rc < 0) {
        fprintf(stderr, "[APA102] spiWrite failed: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

static void apa102_turn_off(void)
{
    (void)apa102_set_brightness(0);
}

static void apa102_fade(uint8_t target, uint32_t duration_ms)
{
    if (target > 31) target = 31;

    float step = (float)(target - g_spi_handle) / (float)duration_ms * 50.0f;
    if (step <= 0.0f) step = 1.0f;

    uint32_t elapsed = 0;
    while (elapsed < duration_ms && g_running) {
        uint8_t val = (uint8_t)((float)g_spi_handle + step * (float)elapsed);
        if (val > target) val = target;
        if (apa102_set_brightness(val) < 0)
            break;
        gpioDelay(20000); /* 20 ms per step */
        elapsed += 20;
    }
    (void)apa102_set_brightness(target);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    apa102_turn_off();

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    int addrs[NUM_SENSORS] = { BH1750_ADDR_1, BH1750_ADDR_2 };
    int found = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        for (int a = 0; a < 2; a++) {
            int h = i2cOpen(I2C_BUS, addrs[a], 0);
            if (h < 0) {
                fprintf(stderr, "[I2C] open 0x%02X failed: %s\n",
                        addrs[a], pigpio_error(h));
                continue;
            }
            if (bh1750_init(h) == 0) {
                g_i2c_handles[i] = h;
                printf("[I2C] sensor %d at 0x%02X\n", i + 1, addrs[a]);
                found++;
                break;
            }
            i2cClose(h);
        }
        if (g_i2c_handles[i] < 0)
            fprintf(stderr, "[I2C] sensor %d not found\n", i + 1);
    }

    if (found == 0) {
        fprintf(stderr, "No BH1750 sensors found. Exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- APA102 init --- */
    if (apa102_init() < 0) {
        fprintf(stderr, "APA102 init failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- SIGINT / SIGTERM --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float lux[NUM_SENSORS];
        int   valid = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_i2c_handles[i] < 0)
                continue;
            if (bh1750_read_lux(g_i2c_handles[i], &lux[i]) == 0)
                valid++;
            else
                fprintf(stderr, "[I2C] sensor %d read error\n", i + 1);
        }

        if (valid == 0) {
            fprintf(stderr, "[MAIN] no valid readings, skipping cycle\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        float sum = 0.0f;
        for (int i = 0; i < valid; i++)
            sum += lux[i];
        float avg = sum / (float)valid;

        uint8_t target = (uint8_t)(avg / 1000.0f * 31.0f);
        if (target > 31) target = 31;

        apa102_fade(target, FADE_MS);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

