/*
 * Flame sensor monitor for Raspberry Pi 5 (BCM numbering).
 *
 * Hardware:
 *   - KY-026 flame sensor  DO -> BCM GPIO4  (active-low)
 *   - Buzzer              + -> BCM GPIO17
 *   - LED                 + -> BCM GPIO18
 *
 * Behaviour:
 *   On startup the LED blinks 500 ms on / 500 ms off twice, then the
 *   flame sensor is read five times at 100 ms intervals.  If any sample
 *   is LOW (flame detected) the LED blinks rapidly (100 ms on / 100 ms off)
 *   for five cycles, the buzzer sounds a short-short-long-short pattern
 *   (200 ms, 200 ms, 600 ms, 200 ms repeated three times), and the program
 *   exits with status 1.
 *
 *   In the main loop the flame sensor is polled every 50 ms.  When a LOW
 *   is observed the buzzer and LED are turned on; when a HIGH is observed
 *   they are turned off.  All events are logged with timestamps.
 *
 *   SIGINT (Ctrl-C) triggers a clean shutdown: all lines are released and
 *   the program exits with status 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN       17
#define LED_PIN          18

#define POLL_INTERVAL_US  50000   /* 50 ms  */
#define BLINK_INTERVAL_US 100000  /* 100 ms */
#define BLINK_CYCLES      5
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_DELAY   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "?");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/*
 * Blink the LED `count` times, `interval_us` apart.
 * Returns 0 on success, -1 on write failure.
 */
static int blink_led(int count, int interval_us)
{
    for (int i = 0; i < count && g_running; i++) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            log_event("ERROR: gpioWrite(LED on) failed");
            return -1;
        }
        gpioDelay(interval_us);
        if (!g_running) break;
        if (gpioWrite(LED_PIN, 0) < 0) {
            log_event("ERROR: gpioWrite(LED off) failed");
            return -1;
        }
        gpioDelay(interval_us);
    }
    return 0;
}

/*
 * Play a short-short-long-short buzzer pattern.
 * Returns 0 on success, -1 on write failure.
 */
static int buzzer_pattern(void)
{
    const int durations[] = {200000, 200000, 600000, 200000};
    const int n = sizeof(durations) / sizeof(durations[0]);

    for (int i = 0; i < n && g_running; i++) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            log_event("ERROR: gpioWrite(buzzer on) failed");
            return -1;
        }
        gpioDelay(durations[i]);
        if (!g_running) break;
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            log_event("ERROR: gpioWrite(buzzer off) failed");
            return -1;
        }
        gpioDelay(durations[i]);
    }
    return 0;
}

/*
 * Read the flame sensor.
 * Returns 0 (flame detected / LOW), 1 (no flame / HIGH), or -1 on error.
 */
static int read_flame_sensor(void)
{
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        log_event("ERROR: gpioRead(flame sensor) failed");
        return -1;
    }
    return v;
}

/*
 * Self-test: blink LED twice, read flame sensor five times, fail if any
 * sample is HIGH (no flame).
 * Returns 0 on success, -1 on failure.
 */
static int self_test(void)
{
    log_event("Starting self-test: LED blink, flame sensor readings");

    /* Blink LED twice: 500 ms on / 500 ms off */
    if (blink_led(2, BLINK_INTERVAL_US) < 0)
        return -1;

    log_event("Self-test: reading flame sensor 5 times");

    for (int i = 0; i < SELF_TEST_SAMPLES && g_running; i++) {
        int v = read_flame_sensor();
        if (v < 0)
            return -1;
        if (v == 0) {
            log_event("Self-test FAILED: flame detected on sample");
            return -1;
        }
        gpioDelay(SELF_TEST_DELAY);
    }

    log_event("Self-test PASSED: no flame detected");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Ensure outputs are off before releasing */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_INPUT);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise outputs to OFF --- */
    if (gpioWrite(BUZZER_PIN, 0) < 0 || gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise outputs to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Self-test --- */
    if (self_test() < 0) {
        log_event("ERROR: self-test failed, exiting");

        /* Rapid blink to indicate failure */
        blink_led(BLINK_CYCLES, BLINK_INTERVAL_US);

        /* Buzzer pattern to indicate failure */
        buzzer_pattern();

        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System ready: monitoring flame sensor");

    /* --- Main loop --- */
    bool flame_active = false;

    while (g_running) {
        int v = read_flame_sensor();
        if (v < 0) {
            /* Sensor read error — ensure outputs are off for safety */
            gpioWrite(BUZZER_PIN, 0);
            gpioWrite(LED_PIN, 0);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (v == 0) {
            /* Flame detected (active-low) */
            if (!flame_active) {
                log_event("Flame detected!");
                flame_active = true;
            }
            if (gpioWrite(BUZZER_PIN, 1) < 0 || gpioWrite(LED_PIN, 1) < 0) {
                log_event("ERROR: gpioWrite(on) failed during flame");
            }
        } else {
            /* No flame */
            if (flame_active) {
                log_event("Flame cleared.");
                flame_active = false;
            }
            if (gpioWrite(BUZZER_PIN, 0) < 0 || gpioWrite(LED_PIN, 0) < 0) {
                log_event("ERROR: gpioWrite(off) failed after flame clear");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    log_event("Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

