/*
 * BH1750 ambient-light monitor with LED frequency feedback.
 *
 * Hardware:
 *   - Raspberry Pi 4 Model B
 *   - BH1750FVI on /dev/i2c-1 (address 0x23)
 *   - LED + 330 Ω resistor on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o bh1750_led bh1750_led.c
 *
 * Run:
 *   ./bh1750_led
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_PWR 0x01   /* power on                          */
#define BH1750_CMD_RESET 0x07 /* software reset                    */
#define BH1750_CMD_OT_H  0x10 /* one-time high-res mode (1 lux)    */
#define BH1750_CMD_OT_L  0x20 /* one-time low-res  mode (0.5 lux)  */
#define BH1750_CMD_OT_LL 0x30 /* one-time low-res  mode (0.5 lux)  */

#define LED_GPIO        17
#define BUFFER_SIZE     60
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_power_on(int fd)
{
    return i2c_write_cmd(fd, BH1750_CMD_PWR);
}

static int bh1750_reset(int fd)
{
    return i2c_write_cmd(fd, BH1750_CMD_RESET);
}

/*
 * Trigger a one-time measurement and read the 2-byte result.
 * Returns lux >= 0 on success, -1 on error.
 */
static int bh1750_read_lux(int fd)
{
    /* One-time high-res mode: ~120 ms conversion, 1 lux resolution. */
    if (i2c_write_cmd(fd, BH1750_CMD_OT_H) < 0)
        return -1;

    usleep(180 * 1000);  /* conservative wait for conversion */

    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s\n", n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    return (int)raw;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    int  data[BUFFER_SIZE];
    int  head;
    int  count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_push(CircularBuffer *cb, int lux)
{
    cb->data[cb->head] = lux;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    long sum = 0;
    for (int i = 0; i < cb->count; i++)
        sum += cb->data[i];
    return (float)sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* GPIO (libgpiod-style unexport via sysfs)                            */
/* ------------------------------------------------------------------ */

static int gpio_export(int gpio)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY)
            return 0;                 /* already exported */
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    char val[4];
    int len = snprintf(val, sizeof(val), "%d", gpio);
    if (write(fd, val, (size_t)len) != (size_t)len) {
        fprintf(stderr, "gpio export failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int gpio)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    char val[4];
    int len = snprintf(val, sizeof(val), "%d", gpio);
    if (write(fd, val, (size_t)len) != (size_t)len) {
        fprintf(stderr, "gpio unexport failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int gpio, const char *dir)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "gpio direction failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int gpio, int val)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    char buf[2] = { (char)(val ? '1' : '0'), '\n' };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "gpio write failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus ---- */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- power on sensor ---- */
    if (bh1750_power_on(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 power-on failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- export GPIO17 ---- */
    if (gpio_export(LED_GPIO) < 0) {
        fprintf(stderr, "GPIO export failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- set GPIO17 as output ---- */
    if (gpio_set_direction(LED_GPIO, "out") < 0) {
        fprintf(stderr, "GPIO direction set failed\n");
        gpio_unexport(LED_GPIO);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- circular buffer ---- */
    CircularBuffer lux_buf;
    cb_init(&lux_buf);

    /* ---- main loop ---- */
    while (g_running) {
        int lux = bh1750_read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        } else {
            cb_push(&lux_buf, lux);
            float avg = cb_average(&lux_buf);

            /* LED frequency: 0.5 Hz in darkness, 5 Hz at 1000 lux */
            float freq = 0.5f + (avg / 1000.0f) * 4.5f;
            if (freq < 0.5f) freq = 0.5f;
            if (freq > 5.0f) freq = 5.0f;

            /* 50% duty cycle square wave */
            int half_period_us = (int)(1.0e6f / freq);
            if (half_period_us < 1) half_period_us = 1;

            if (gpio_write(LED_GPIO, 1) < 0)
                break;
            usleep(half_period_us);
            if (gpio_write(LED_GPIO, 0) < 0)
                break;
            usleep(half_period_us);
        }

        /* Sleep for the remainder of the sample period */
        sleep(SAMPLE_PERIOD_S);
    }

    /* ---- cleanup ---- */
    gpio_write(LED_GPIO, 0);
    gpio_unexport(LED_GPIO);
    close(i2c_fd);

    fprintf(stderr, "\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

