#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

/* 74HC595 output order: Q0..Q7 mapped to segments a,b,c,d,e,f,g,dp */
static const int seg_map[8] = {
    1, 2, 4, 5, 3, 6, 0, 7  /* a,b,c,d,e,f,g,dp */
};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Bit-bang a single byte MSB-first into the 74HC595.
 * pigpio's gpioWrite is a low-level operation; we manage the clock
 * and latch lines manually for full control.
 */
static int shift_out(uint8_t data) {
    for (int i = 0; i < 8; i++) {
        if (gpioWrite(DATA_PIN, (data >> (7 - i)) & 1) < 0) {
            fprintf(stderr, "gpioWrite(DATA) failed\n");
            return -1;
        }
        if (gpioWrite(CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "gpioWrite(CLOCK high) failed\n");
            return -1;
        }
