/*
 * blink_button.c — Blink an LED on GPIO17 while waiting for a falling edge
 * on GPIO18 (button press) using libgpiod.
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    ./blink_button   (Ctrl-C to exit)
 */
#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CHIP_NAME  "gpiochip0"
#define CONSUMER   "blink_button"

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int sig)
{
    (void)sig;
    g_stop = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    struct gpiod_line *button = NULL;
    struct gpiod_line_event event;
    struct timespec ts = { 1, 0 };   /* 1 s timeout */
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name(" CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    /* --- Get LED line --- */
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    /* --- Get button line --- */
    button = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button) {
        perror("gpiod_chip_get_line(button)");
        goto cleanup;
    }

    /* --- Request LED as output, initially low --- */
    if (gpiod_line_request_output(led, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* --- Request button as input with pull-up and falling-edge events --- */
    if (gpiod_line_request_input_flags(button, CONSUMER,
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
                                       GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE) < 0) {
        perror("gpiod_line_request_input_flags(button)");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d while waiting for falling edge on GPIO%d.\n",
           LED_PIN, BUTTON_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* --- Main blink loop --- */
    while (!g_stop) {
        /* Turn LED on */
        if (gpiod_line_set_value(led, 1) < 0) {
            perror("gpiod_line_set_value(LED on)");
            goto cleanup;
        }
        printf("LED on\n");
        fflush(stdout);

        /* Wait 1 s (interruptible by signals) */
        while (!g_stop) {
            int ret = gpiod_line_event_wait(button, &ts);
            if (ret < 0) {
                if (errno == EINTR)
                    continue;
                perror("gpiod_line_event_wait");
                goto cleanup;
            }
            if (ret == 0)
                break;          /* timeout, turn off */

            /* Event detected — read it to clear the queue */
            if (gpiod_line_event_read(button, &event) < 0) {
                perror("gpiod_line_event_read");
                goto cleanup;
            }
            printf("Button pressed (event on GPIO%d)\n", BUTTON_PIN);
            fflush(stdout);
            g_stop = 1;
            break;
        }

        if (g_stop)
            break;

        /* Turn LED off */
        if (gpiod_line_set_value(led, 0) < 0) {
            perror("gpiod_line_set_value(LED off)");
            goto cleanup;
        }
        printf("LED off\n");
        fflush(stdout);

        /* Wait 1 s (interruptible by signals) */
        while (!g_stop) {
            int ret = gpiod_line_event_wait(button, &ts);
            if (ret < 0) {
                if (errno == EINTR)
                    continue;
                perror("gpiod_line_event_wait");
                goto cleanup;
            }
            if (ret == 0)
                break;          /* timeout, blink again */

            /* Event detected — read it to clear the queue */
            if (gpiod_line_event_read(button, &event) < 0) {
                perror("gpiod_line_event_read");
                goto cleanup;
            }
            printf("Button pressed (event on GPIO%d)\n", BUTTON_PIN);
            fflush(stdout);
            g_stop = 1;
            break;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* --- Release lines and close chip --- */
    if (led)
        gpiod_line_release(led);
    if (button)
        gpiod_line_release(button);
    if (chip)
        gpiod_chip_close(chip);

    printf("Exiting.\n");
    return rc;
}

