/*
 * Raspberry Pi GPIO blinker with button-controlled LED.
 *
 * Wiring (BCM numbering):
 *   GPIO24 (physical pin 18) -> LED anode via 330 ohm -> GND
 *   GPIO22 (physical pin 15) -> button between it and 3.3V
 *                               button pull-down to GND (or use internal
 *                               pull-down if available)
 *
 * Behaviour:
 *   LED starts OFF.  While the button is held, the LED blinks 500 ms ON
 *   followed by 500 ms OFF.  When the button is released the LED turns
 *   OFF and stays off until the button is pressed again.  Ctrl-C / SIGTERM
 *   turns off the LED and releases all resources.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define LED_PIN    24
#define BUTTON_PIN 22
#define CHIP_NAME  "gpiochip4"   /* BCM GPIO on Pi 5; use "gpiochip0" on Pi 3/4 */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            break;
        }
        /* Retry with remaining time after signal interruption */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led  = NULL;
    struct gpiod_line *btn  = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (led == NULL) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    btn = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (btn == NULL) {
        fprintf(stderr, "Failed to get button line %d: %s\n", BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "blink_led", 0) != 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(btn, "blink_btn",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        fprintf(stderr, "Failed to request button line as input with pull-down: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Blinker ready.  LED on GPIO%d, button on GPIO%d.  Press Ctrl-C to exit.\n",
           LED_PIN, BUTTON_PIN);

    while (g_running) {
        int val = gpiod_line_get_value(btn);
        if (val < 0) {
            fprintf(stderr, "Failed to read button: %s\n", strerror(errno));
            break;
        }

        if (val == 1) {
            if (gpiod_line_set_value(led, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
                break;
            }
            sleep_ms(500);

            if (!g_running)
                break;

            if (gpiod_line_set_value(led, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                break;
            }
            sleep_ms(500);
        } else {
            /* Button not pressed: ensure LED is off and sleep briefly */
            if (gpiod_line_set_value(led, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                break;
            }
            sleep_ms(10);
        }
    }

    /* Ensure LED is off on exit */
    if (led != NULL)
        (void)gpiod_line_set_value(led, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (led != NULL)
        gpiod_line_release(led);
    if (btn != NULL)
        gpiod_line_release(btn);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

