#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_FREQ  100   /* Hz */
#define PWM_PERIOD_US (1000000 / PWM_FREQ)  /* 10000 µs = 10 ms */
#define STEP_US   100   /* 100 µs granularity for sub-ms timing */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Software PWM for a single GPIO line at the given frequency.
 * pigpio's gpioPWM() is a hardware-driven PWM; we need a software loop.
 *
 * pigpio's gpioWrite() is used to drive the line high or low for the
 * on-time, then a short busy-wait sleep of STEP_US microseconds.
 * This keeps the loop tight and avoids the overhead of a full nanosleep().
 */
static void software_pwm(int pin, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int on_us  = (PWM_PERIOD_US * duty_percent) / 100;
    int off_us = PWM_PERIOD_US - on_us;

    if (on_us > 0) {
        gpioWrite(pin, 1);
        gpioDelay(on_us);
    }
    if (off_us > 0) {
        gpioWrite(pin, 0);
        gpioDelay(off_us);
    }
}

static void set_led_color(int r, int g, int b) {
    software_pwm(RED_PIN,   r);
    software_pwm(GREEN_PIN, g);
    software_pwm(BLUE_PIN,  b);
}

static void cleanup(void) {
    /* Turn off all LED channels */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    /* Release GPIO lines */
    gpioSetMode(RED_PIN,   PI_INPUT);
    gpioSetMode(GREEN_PIN, PI_INPUT);
    gpioSetMode(BLUE_PIN,  PI_INPUT);

    gpioTerminate();
}

int main(void) {
    /* Seed PRNG */
    srand((unsigned)time(NULL));

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GREEN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BLUE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure LEDs start off */
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    printf("RGB LED PWM running. Press Ctrl+C to exit.\n");

    while (running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        set_led_color(r, g, b);

        /*
         * Sleep for the remainder of the 10 ms period to avoid
         * generating new values too quickly.
         */
        gpioDelay(PWM_PERIOD_US);
    }

    printf("\nExiting...\n");
    cleanup();
    return EXIT_SUCCESS;
}

