/*
 * LSM303DLHC Impact Detector for Raspberry Pi Zero W
 *
 * Polls an LSM303DLHC accelerometer on I2C bus 1 at 10 Hz, computes the
 * total G-force magnitude, and triggers an impact interrupt on GPIO17
 * (BCM) when the magnitude exceeds a configurable threshold.
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_detector impact_detector.c -lm
 * Run:    ./impact_detector [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x19          /* LSM303DLHC accelerometer address (SA0 tied to GND) */

#define WHO_AM_I_REG         0x0F
#define WHO_AM_I_VAL         0x49          /* LSM303DLHC identification byte */

#define CTRL_REG1_A          0x20
#define CTRL_REG4_A          0x23
#define OUT_X_L_A            0x28

#define GPIO_INTERRUPT       17            /* BCM pin 17 */
#define DEFAULT_THRESHOLD    2.0           /* G-force threshold */
#define LOG_FILE             "impact_log.txt"
#define SAMPLE_PERIOD_US     100000        /* 10 Hz */
#define INTERRUPT_PULSE_US   50000         /* 50 ms */

/* ---- Globals ---- */
static int      i2c_handle = -1;
static double   threshold  = DEFAULT_THRESHOLD;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Types ---- */
typedef struct {
    float x, y, z;
} AccelData;

/* ---- Prototypes ---- */
static int  init_i2c(void);
static int  init_accelerometer(void);
static int  read_accelerometer(AccelData *data);
static double calculate_magnitude(const AccelData *data);
static void trigger_interrupt(void);
static void log_data(const AccelData *data);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- I2C helpers ---- */
static int i2c_write_byte(uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int n = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, want %u, got %d): %s\n",
                reg, len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Initialization ---- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_accelerometer(void)
{
    uint8_t whoami = 0;

    if (i2c_read_block(WHO_AM_I_REG, &whoami, 1) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }

    /* Accelerometer: 100 Hz, normal mode, XYZ axes enabled */
    if (i2c_write_byte(CTRL_REG1_A, 0x27) < 0) return -1;

    /* Block Data Update, 100 Hz ODR */
    if (i2c_write_byte(CTRL_REG4_A, 0x08) < 0) return -1;

    return 0;
}

/* ---- Data acquisition ---- */
static int read_accelerometer(AccelData *data)
{
    uint8_t buf[6];

    if (i2c_read_block(OUT_X_L_A, buf, sizeof(buf)) < 0)
        return -1;

    /* LSM303DLHC is little-endian: LSB first */
    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    /* Convert to mg (1 mg = 0.001 G) */
    data->x = (float)x / 1000.0f;
    data->y = (float)y / 1000.0f;
    data->z = (float)z / 1000.0f;

    return 0;
}

static double calculate_magnitude(const AccelData *data)
{
    return sqrt((double)data->x * data->x +
                (double)data->y * data->y +
                (double)data->z * data->z);
}

/* ---- Impact detection & logging ---- */
static void trigger_interrupt(void)
{
    if (gpioWrite(GPIO_INTERRUPT, 1) < 0)
        fprintf(stderr, "Warning: failed to set GPIO%d HIGH: %s\n",
                GPIO_INTERRUPT, strerror(errno));
    gpioDelay(INTERRUPT_PULSE_US);
    if (gpioWrite(GPIO_INTERRUPT, 0) < 0)
        fprintf(stderr, "Warning: failed to set GPIO%d LOW: %s\n",
                GPIO_INTERRUPT, strerror(errno));
}

static void log_data(const AccelData *data)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %.3f, Y: %.3f, Z: %.3f, Magnitude: %.3f G\n",
            timestamp, data->x, data->y, data->z,
            sqrt((double)data->x * data->x +
                 (double)data->y * data->y +
                 (double)data->z * data->z));
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold = atof(optarg);
            if (threshold <= 0.0) {
                fprintf(stderr, "Threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_accelerometer() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_INTERRUPT, PI_OUTPUT) < 0) {
