#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ADPD188BI I2C address (7-bit) */
#define ADPD188BI_ADDR 0x50

/* ADPD188BI register addresses */
#define ADPD188BI_REG_ALS_LSB 0x04
#define ADPD188BI_REG_ALS_MSB 0x05
#define ADPD188BI_REG_RED_LSB 0x06
#define ADPD188BI_REG_RED_MSB 0x07
#define ADPD188BI_REG_GREEN_LSB 0x08
#define ADPD188BI_REG_GREEN_MSB 0x09
#define ADPD188BI_REG_BLUE_LSB 0x0A
#define ADPD188BI_REG_BLUE_MSB 0x0B

/* GPIO pin for LED control (BCM numbering) */
#define LED_PIN 18

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Retry delay in microseconds */
#define RETRY_DELAY_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADPD188BI register                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian channel value                           */
/* ------------------------------------------------------------------ */
static int read_channel(int handle, uint8_t lsb_reg, uint8_t msb_reg,
                        uint16_t *value)
{
    uint8_t lsb, msb;
    if (read_register(handle, lsb_reg, &lsb) != 0)
        return -1;
    if (read_register(handle, msb_reg, &msb) != 0)
        return -1;
    *value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one CSV row                                                     */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t als, uint16_t red,
                     uint16_t green, uint16_t blue)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(timestamp, sizeof(timestamp), "1970-01-01 00:00:00");
    }

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Map ambient light to PWM duty cycle (0–255)                         */
/* ------------------------------------------------------------------ */
static int map_als_to_pwm(uint16_t als)
{
    /* Scale logarithmically: dark → low LED, bright → high LED */
    double normalized = (double)als / 65535.0;
    if (normalized < 0.0) normalized = 0.0;
    if (normalized > 1.0) normalized = 1.0;

    double pwm_val = 255.0 * (1.0 - normalized);
    if (pwm_val < 0.0) pwm_val = 0.0;
    if (pwm_val > 255.0) pwm_val = 255.0;

    return (int)(pwm_val + 0.5);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Turn off LED */
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADPD188BI address */
    g_i2c_handle = i2cOpen(1, ADPD188BI_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n",
                ADPD188BI_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV log file (write header) */
    g_log_file = fopen("color_log.csv", "w");
    if (g_log_file == NULL) {
        perror("Error opening color_log.csv");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "timestamp,als,red,green,blue\n");
    fflush(g_log_file);

    /* Configure LED pin as PWM output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMrange(LED_PIN, 255);
    gpioPWM(LED_PIN, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADPD188BI color sensor logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t als = 0, red = 0, green = 0, blue = 0;
        int error = 0;

        if (read_channel(g_i2c_handle, ADPD188BI_REG_ALS_LSB,
                         ADPD188BI_REG_ALS_MSB, &als) != 0) {
            error = 1;
        }
        if (read_channel(g_i2c_handle, ADPD188BI_REG_RED_LSB,
                         ADPD188BI_REG_RED_MSB, &red) != 0) {
            error = 1;
        }
        if (read_channel(g_i2c_handle, ADPD188BI_REG_GREEN_LSB,
                         ADPD188BI_REG_GREEN_MSB, &green) != 0) {
            error = 1;
        }
        if (read_channel(g_i2c_handle, ADPD188BI_REG_BLUE_LSB,
                         ADPD188BI_REG_BLUE_MSB, &blue) != 0) {
            error = 1;
        }

        if (error) {
            fprintf(stderr, "Sensor read error — retrying in 100 ms\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Log the data */
        log_data(g_log_file, als, red, green, blue);

        /* Map ALS to PWM and apply to LED */
        int pwm_val = map_als_to_pwm(als);
        gpioPWM(LED_PIN, pwm_val);

        /* Wait for next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

