 * FXOS8700CQ Impact Logger for Raspberry Pi Zero W
 *
 * Reads acceleration data from the Adafruit FXOS8700CQ (I2C addr 0x1C)
 * at 200 Hz, logs impact events to impact_log.txt.
 *
 * Build:  gcc -O2 -Wall -o impact_logger impact_logger.c -lpigpio -lrt
 * Run:    sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ constants ---- */
#define FXOS8700_ADDR        0x1C
#define FXOS8700_WHO_AM_I    0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7

#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_CTRL_REG2   0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB   0x01

#define IMPACT_THRESHOLD     0.5f   /* g */
#define SAMPLE_PERIOD_US     50000  /* 50 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, pigpio_error(rc));
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0)
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %s\n",
                reg, len, pigpio_error(rc));
    return rc;
}

/* ---- FXOS8700CQ init ---- */
static int fxos8700_init(int handle)
{
    int rc;

    /* Standby first so configuration changes take effect */
    rc = i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00);
    if (rc < 0) return -1;

    /* Reset */
    rc = i2c_write_byte(handle, FXOS8700_CTRL_REG2, 0x40);
    if (rc < 0) return -1;
    gpioDelay(2000); /* 2 ms settle */

    /* Verify identity */
    int who = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", pigpio_error(who));
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Configure accelerometer: ±2 g (0x00), 200 Hz (0x0E) */
    rc = i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x0E);
    if (rc < 0) return -1;

    /* Configure magnetometer: hybrid auto-increment, 80 Hz OSR */
    rc = i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, 0x1F);
    if (rc < 0) return -1;

    /* M_CTRL_REG2: ±4 g sensitivity, continuous conversion */
    rc = i2c_write_byte(handle, FXOS8700_M_CTRL_REG2, 0x20);
    if (rc < 0) return -1;

    /* Active mode */
    rc = i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x0D);
    if (rc < 0) return -1;

    gpioDelay(2000); /* 2 ms settle */
    return 0;
}

/* ---- Read acceleration (g) ---- */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int rc = i2c_read_block(handle, FXOS8700_OUT_X_MSB, buf, 6);
    if (rc < 0) return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* ±2 g range: 1 g = 16384 LSB */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

/* ---- Impact detection ---- */
static int detect_impact(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    return (mag > IMPACT_THRESHOLD);
}

/* ---- Log impact ---- */
static void log_impact(float x, float y, float z, float mag)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("fopen(impact_log.txt)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, mag);
    } else {
        fprintf(fp, "(time-error),%.3f,%.3f,%.3f,%.3f\n", x, y, z, mag);
    }

    fclose(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(1, 0x%02X) failed: %s\n",
                FXOS8700_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos8700_init(g_i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl-C to exit.\n");

    /* Main loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            if (detect_impact(x, y, z)) {
                float mag = sqrtf(x * x + y * y + z * z);
                log_impact(x, y, z, mag);
                printf("Impact detected: x=%.3f g, y=%.3f g, z=%.3f g, mag=%.3f g\n",
                       x, y, z, mag);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

