 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c
 * Run:    ./gyro_log
 *
 * The L3G4200D WHO_AM_I register (0x0F) returns 0xD3 when the device is
 * present.  The gyro is configured for 1000 dps full-scale (0x00), and
 * the output data rate is set to 100 Hz (0x60).  A 100-sample stationary
 * calibration computes X/Y/Z zero-rate offsets from the first 100
 * samples.  Alert lines are appended to gyro_log.txt when any axis
 * exceeds 50 dps, and warnings are printed to stderr.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0xD2          /* GY-50 default I2C address */
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define SAMPLE_COUNT   100
#define THRESHOLD_DPS  50.0f
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_PERIOD  50000         /* microseconds (20 Hz) */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst: read %zd bytes from 0x%02X failed: %s\n",
                n, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_burst(fd, WHO_AM_I, &who, 1) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR = 100 Hz (0x60), gyro X/Y/Z enable (0x07) */
    if (i2c_write_byte(fd, CTRL_REG1, 0x67) < 0)
        return -1;

    /* CTRL_REG4: full-scale = 1000 dps (0x00) */
    if (i2c_write_byte(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUT_X_L, raw, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* 1000 dps full-scale => 16.384 LSB/dps */
    *x = (float)rx / 16.384f;
    *y = (float)ry / 16.384f;
    *z = (float)rz / 16.384f;
    return 0;
}

static void calibrate(int fd, float *x_off, float *y_off, float *z_off)
{
    float sx = 0, sy = 0, sz = 0;
    int ok = 0;

    printf("Calibrating (keep sensor still)...\n");
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        float x, y, z;
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            break;
        }
        sx += x; sy += y; sz += z;
        usleep(50000);
    }

    if (ok) {
        *x_off = sx / SAMPLE_COUNT;
        *y_off = sy / SAMPLE_COUNT;
        *z_off = sz / SAMPLE_COUNT;
        printf("Calibration done. Offsets -> X: %.3f, Y: %.3f, Z: %.3f\n",
               *x_off, *y_off, *z_off);
    } else {
        fprintf(stderr, "Calibration aborted.\n");
    }
}

static void log_data(FILE *fp, float x, float y, float z, int alert)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%s\n", ts, x, y, z, alert ? "ALERT" : "OK");
    fflush(fp);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    float x_off = 0, y_off = 0, z_off = 0;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                GYRO_ADDR, strerror(errno));
        goto cleanup;
    }

    if (gyro_init(fd) < 0) {
        fprintf(stderr, "Gyro init failed.\n");
        goto cleanup;
    }

    calibrate(fd, &x_off, &y_off, &z_off);

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_gyro(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        x -= x_off; y -= y_off; z -= z_off;

        int alert = (fabsf(x) > THRESHOLD_DPS ||
                     fabsf(y) > THRESHOLD_DPS ||
                     fabsf(z) > THRESHOLD_DPS);

        if (alert)
            fprintf(stderr, "ALERT: X=%.2f Y=%.2f Z=%.2f dps\n", x, y, z);

        log_data(fp, x, y, z, alert);
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

