/*
 * ADXL345 accelerometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -o accel_log accel_log.c -lpigpio -lrt
 * Run:    sudo ./accel_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants (datasheet DS-000069) ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_DEVID          0x00
#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C
#define ADXL345_RANGE          0x2C

#define ADXL345_RANGE_2G       0x00
#define ADXL345_RANGE_4G       0x01
#define ADXL345_RANGE_8G       0x02
#define ADXL345_RANGE_16G      0x03

#define ADXL345_BW_100HZ       0x0A
#define ADXL345_BW_50HZ        0x05
#define ADXL345_BW_25HZ        0x06
#define ADXL345_BW_12_5HZ      0x08
#define ADXL345_BW_6_25HZ      0x09

#define ADXL345_DATA_FULL_RES  0x0B
#define ADXL345_MEASURE        0x08

/* ---- Application constants ---- */
#define I2C_BUS               1
#define SAMPLE_PERIOD_US      100000   /* 100 ms -> 10 Hz */
#define GPIO_LED              17
#define ACCEL_THRESHOLD_G     2.0f
#define LOG_FILE              "accel_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl_write_byte(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "[ADXL345] write reg 0x%02X val 0x%02X failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ADXL345] read reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345: verify device ID, set full-resolution mode,
 * ±2 g range, 100 Hz output data rate, then enter measurement mode. */
static int adxl_init(int handle)
{
    uint8_t devid = 0;

    if (adxl_read_byte(handle, ADXL345_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr,
                "[ADXL345] DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby first so configuration changes take effect. */
    if (adxl_write_byte(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full resolution, ±2 g range. */
    if (adxl_write_byte(handle, ADXL345_DATA_FORMAT,
                        ADXL345_DATA_FULL_RES) != 0)
        return -1;

    if (adxl_write_byte(handle, ADXL345_RANGE, ADXL345_RANGE_2G) != 0)
        return -1;

    /* 100 Hz output data rate (bandwidth register). */
    if (adxl_write_byte(handle, ADXL345_BW_RATE, ADXL345_BW_100HZ) != 0)
        return -1;

    /* Enter measurement mode. */
    if (adxl_write_byte(handle, ADXL345_POWER_CTL, ADXL345_MEASURE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (DATAX0..DATAZ1) and convert to
 * g units.  Returns 0 on success, -1 on I2C error. */
static int adxl_read_accel(int handle, float *x, float *y, float *z)
{
    char raw[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "[ADXL345] block read failed\n");
        return -1;
    }

    /* Full-resolution mode: 10-bit left-justified in 16-bit fields. */
    int16_t rx = (int16_t)(((uint16_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t ry = (int16_t)(((uint16_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t rz = (int16_t)(((uint16_t)raw[5] << 8) | (uint8_t)raw[4]);

    /* Sign-extend 10-bit values (two's complement). */
    if (rx & 0x0200) rx |= 0xFC00;
    if (ry & 0x0200) ry |= 0xFC00;
    if (rz & 0x0200) rz |= 0xFC00;

    /* ±2 g range => 3.9 mg/LSB => 0.0039 g/LSB. */
    const float scale = 0.0039f;
    *x = (float)rx * scale;
    *y = (float)ry * scale;
    *z = (float)rz * scale;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_buf;
    struct tm *tm = localtime_r(&ts.tv_sec, &tm_buf);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s.%03ld,%.3f,%.3f,%.3f\n",
            tbuf, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (adxl_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started (10 Hz, threshold %.1f g). Ctrl-C to stop.\n",
           ACCEL_THRESHOLD_G);

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;

        if (adxl_read_accel(g_i2c_handle, &x, &y, &z) == 0) {
            log_sample(g_log_file, x, y, z);

            bool exceeded = (fabsf(x) > ACCEL_THRESHOLD_G) ||
                            (fabsf(y) > ACCEL_THRESHOLD_G) ||
                            (fabsf(z) > ACCEL_THRESHOLD_G);

            gpioWrite(GPIO_LED, exceeded ? 1 : 0);
        } else {
            /* On read failure, turn LED off and keep running. */
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

