/*
 * GY-51 LSM303DLHC Compass Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC VIN  -> Pi 3V3 (Pin 1)
 *   LSM303DLHC GND  -> Pi GND (Pin 9)
 *   LSM303DLHC SCL  -> Pi SCL (GPIO3 / Pin 5)
 *   LSM303DLHC SDA  -> Pi SDA (GPIO2 / Pin 3)
 *
 * Build:
 *   gcc -O2 -Wall -o compass_logger compass_logger.c -lm -lpigpio -lrt
 * Run:
 *   sudo ./compass_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Sensitivity adjustments (from datasheet) ---- */
#define ACCEL_SENSITIVITY 0.000244f  /* g/LSB at +/- 2g */
#define MAG_SENSITIVITY   0.00014f   /* gauss/LSB at +/- 2 gauss */

/* ---- Globals for cleanup ---- */
static int i2c_accel = -1;
static int i2c_mag   = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} sensor_data_t;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    i2c_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_accel < 0) {
        fprintf(stderr, "Error: Could not open I2C for accelerometer (addr 0x%02X): %d\n",
                LSM303_ACCEL_ADDR, i2c_accel);
        gpioTerminate();
        return -1;
    }

    i2c_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_mag < 0) {
        fprintf(stderr, "Error: Could not open I2C for magnetometer (addr 0x%02X): %d\n",
                LSM303_MAG_ADDR, i2c_mag);
        i2cClose(i2c_accel);
        i2c_accel = -1;
        gpioTerminate();
        return -1;
    }

    /* Enable accelerometer: 100 Hz, all axes enabled */
    if (i2cWriteByteData(i2c_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: Could not write accelerometer control register.\n");
        goto fail;
    }

    /* Enable magnetometer: continuous conversion mode */
    if (i2cWriteByteData(i2c_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write magnetometer control register.\n");
        goto fail;
    }

    return 0;

fail:
    i2cClose(i2c_accel);
    i2c_accel = -1;
    i2cClose(i2c_mag);
    i2c_mag = -1;
    gpioTerminate();
    return -1;
}

/* ------------------------------------------------------------------ */
static int read_accelerometer(sensor_data_t *data)
{
    char raw[6];

    if (i2cReadI2CBlockData(i2c_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, raw, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data.\n");
        return -1;
    }

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    data->x = (float)x * ACCEL_SENSITIVITY;
    data->y = (float)y * ACCEL_SENSITIVITY;
    data->z = (float)z * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(sensor_data_t *data)
{
    char raw[6];

    if (i2cReadI2CBlockData(i2c_mag, LSM303_MAG_OUT_X_H_M, raw, 6) != 6) {
        fprintf(stderr, "Error: Could not read magnetometer data.\n");
        return -1;
    }

    int16_t x = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t z = (int16_t)((raw[2] << 8) | raw[3]);
    int16_t y = (int16_t)((raw[4] << 8) | raw[5]);

    data->x = (float)x * MAG_SENSITIVITY;
    data->y = (float)y * MAG_SENSITIVITY;
    data->z = (float)z * MAG_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_heading(const sensor_data_t *accel,
                               const sensor_data_t *mag)
{
    float pitch = asinf(-accel->x);
    float roll  = asinf(accel->y / cosf(pitch));

    float mx = mag->x * cosf(pitch) + mag->z * sinf(pitch);
    float my = mag->x * sinf(roll) * sinf(pitch) +
               mag->y * cosf(roll) -
               mag->z * sinf(roll) * cosf(pitch);

    float heading = atan2f(my, mx) * 180.0f / M_PI;
    if (heading < 0)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
static void log_data(float heading,
                     const sensor_data_t *accel,
                     const sensor_data_t *mag)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts, heading,
            accel->x, accel->y, accel->z,
            mag->x, mag->y, mag->z);

    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_accel >= 0) {
        i2cClose(i2c_accel);
        i2c_accel = -1;
    }
    if (i2c_mag >= 0) {
        i2cClose(i2c_mag);
        i2c_mag = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0)
        return EXIT_FAILURE;

    /* Create CSV header if file does not exist */
    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    sensor_data_t accel, mag;

    while (!terminate) {
        if (read_accelerometer(&accel) == 0 &&
            read_magnetometer(&mag)   == 0) {
            float heading = calculate_heading(&accel, &mag);
            log_data(heading, &accel, &mag);
        } else {
            fprintf(stderr, "Warning: Sensor read error, skipping sample.\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

