#define REG_RESULT_RANGE_VAL              0x0062
#define REG_RESULT_INTERRUPT_STATUS       0x004F
#define REG_SYSTEM_INTERRUPT_CLEAR        0x0015
#define REG_SYSTEM_FRESH_OUT_OF_RESET     0x0016
#define REG_SYSRANGE_MAX_TIMING_BUDGET    0x006B
#define REG_SYSRANGE_VHV_RECAL            0x006C
#define REG_SYSRANGE_TIMING               0x006E
#define REG_SYSTEM_MODE_GPIO1             0x0010
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO  0x0014
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO_NEW 0x0017
#define REG_SYSTEM_INTERRUPT_CLEAR        0x0015
#define REG_SYSTEM_FRESH_OUT_OF_RESET     0x0016
#define REG_SYSRANGE_START                0x0000
#define REG_SYSTEM_MODE_GPIO1             0x0010
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO  0x0014
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO_NEW 0x0017
#define REG_SYSTEM_INTERRUPT_CLEAR        0x0015
#define REG_SYSTEM_FRESH_OUT_OF_RESET     0x0016
#define REG_SYSRANGE_START                0x0000
#define REG_SYSRANGE_MAX_TIMING_BUDGET    0x006B
#define REG_SYSRANGE_VHV_RECAL            0x006C
#define REG_SYSRANGE_TIMING               0x006E

#define LOG_FILE       "distance_log.txt"
#define DISTANCE_THRESHOLD_MM 100
#define SAMPLE_PERIOD_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */

static int i2c_write16(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        val
    };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(0x%04X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint8_t *val)
{
    uint8_t addr[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read16 write(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read16 read(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL6180X register access                                            */
/* ------------------------------------------------------------------ */

static int vl6180x_init(int fd)
{
    uint8_t id = 0;

    /* Mandatory reset: write 0x00 to SYSRANGE_START, then read back */
    if (i2c_write16(fd, REG_SYSRANGE_START, 0x00) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    if (i2c_read16(fd, REG_SYSTEM_FRESH_OUT_OF_RESET, &id) < 0)
        return -1;

    if (id != 0x01) {
        fprintf(stderr, "VL6180X not responding (id=0x%02X, expected 0x01)\n", id);
        return -1;
    }

    /* Mandatory init sequence (datasheet §3.2.2) */
    if (i2c_write16(fd, REG_SYSRANGE_VHV_RECAL, 0x01) < 0) return -1;
    if (i2c_write16(fd, REG_SYSRANGE_MAX_TIMING_BUDGET, 0x0B) < 0) return -1;
    if (i2c_write16(fd, REG_SYSRANGE_TIMING, 0x00) < 0) return -1;
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) return -1;
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CONFIG_GPIO_NEW, 0x04) < 0) return -1;
    if (i2c_write16(fd, REG_SYSTEM_MODE_GPIO1, 0x10) < 0) return -1;

    /* Clear any pending interrupt */
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;

    return 0;
}

static int vl6180x_read_distance(int fd, uint8_t *distance)
{
