    /* Start a single ranging measurement */
    if (i2c_write16(fd, REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll for completion (bit 0 of REG_RESULT_INTERRUPT_STATUS) */
    for (int i = 0; i < 50; i++) {
        if (i2c_read16(fd, REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(2000);  /* 2 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "VL6180X measurement timeout\n");
        return -1;
    }

    /* Read the 16-bit range value */
    if (i2c_read16(fd, REG_RESULT_RANGE_VAL, distance) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal */
    if (i2c_write16(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_data(uint8_t distance, const char *status)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%u,%s\n", ts, distance, status);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL6180X_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                VL6180X_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (vl6180x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL6180X initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL6180X initialized. Logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        uint8_t distance = 0;

        if (vl6180x_read_distance(g_i2c_fd, &distance) < 0) {
            fprintf(stderr, "Read error — attempting re-initialization\n");
            usleep(100000);
            if (vl6180x_init(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, retrying in 1 s\n");
                sleep(1);
            }
            continue;
        }

        const char *status = (distance < DISTANCE_THRESHOLD_MM)
                             ? "DOOR_OPEN" : "DOOR_CLOSED";
        log_data(distance, status);
        printf("Distance: %u mm  %s\n", distance, status);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
