/*
 * Raspberry Pi 4 Model B — Dual IMP23ABSU Ultrasonic MEMS Microphone TDOA Logger
 *
 * Wiring:
 *   I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 *   Sensor 1: I2C address 0x1D (ADDR pin tied to GND)
 *   Sensor 2: I2C address 0x1E (ADDR pin tied to VDD)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o audio_tdoa audio_tdoa.c -li2c -lm
 *
 * Run:
 *   ./audio_tdoa
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS              1
#define I2C_ADDR_1           0x1D
#define I2C_ADDR_2           0x1E
#define SAMPLE_INTERVAL_US   10000   /* 10 ms */
#define LOG_FILE             "audio_log.dat"
#define SAMPLE_BYTES         2
#define MAX_RETRIES          3

/* IMP23ABSU register addresses (datasheet-derived) */
#define REG_OUT_L            0x00
#define REG_OUT_H            0x01
#define REG_CTRL1            0x10
#define REG_CTRL2            0x11

/* CTRL1 bits: ODR=100 Hz (0x80), LP=0, ZEN=0, FS=00 (±240 dB) */
#define CTRL1_VAL            0x80

/* CTRL2 bits: BOOT=0, RST=0, ST=0, SIMPLE=0, FS=00 (±240 dB) */
#define CTRL2_VAL            0x00

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_h1 = -1;
static int g_h2 = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_h1 >= 0) {
        i2cClose(g_h1);
        g_h1 = -1;
    }
    if (g_h2 >= 0) {
        i2cClose(g_h2);
        g_h2 = -1;
    }
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/*
 * Initialise an IMP23ABSU: write CTRL1 then CTRL2.
 * Returns 0 on success, -1 on failure.
 */
static int init_sensor(int handle)
{
    if (i2cWriteByteData(handle, REG_CTRL1, CTRL1_VAL) < 0) {
        fprintf(stderr, "init_sensor: write CTRL1 failed (h=%d): %s\n",
                handle, strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, REG_CTRL2, CTRL2_VAL) < 0) {
        fprintf(stderr, "init_sensor: write CTRL2 failed (h=%d): %s\n",
                handle, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit signed sample from the sensor.
 * Returns 0 on success and stores the sample in *out; returns -1 on error.
 */
static int read_sample(int handle, int16_t *out)
{
    char buf[SAMPLE_BYTES];

    if (i2cReadI2CBlockData(handle, REG_OUT_L, buf, SAMPLE_BYTES) != SAMPLE_BYTES) {
        fprintf(stderr, "read_sample: I2C read failed (h=%d): %s\n",
                handle, strerror(errno));
        return -1;
    }

    uint16_t raw = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    *out = (int16_t)raw;
    return 0;
}

static void log_sample(const struct timespec *ts, int16_t s1, int16_t s2,
                       double tdoa)
{
    fprintf(g_log, "%ld,%ld,%d,%d,%.6f\n",
            (long)ts->tv_sec, (long)ts->tv_nsec, s1, s2, tdoa);
    fflush(g_log);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_h1 = i2cOpen(I2C_BUS, I2C_ADDR_1, 0);
    if (g_h1 < 0) {
        fprintf(stderr, "i2cOpen(0x%02X) failed: %s\n",
                I2C_ADDR_1, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_h2 = i2cOpen(I2C_BUS, I2C_ADDR_2, 0);
    if (g_h2 < 0) {
        fprintf(stderr, "i2cOpen(0x%02X) failed: %s\n",
                I2C_ADDR_2, strerror(errno));
        i2cClose(g_h1);
        g_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_h1) != 0 || init_sensor(g_h2) != 0) {
        fprintf(stderr, "Sensor init failed; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp_sec, timestamp_nsec, sensor1, sensor2, tdoa_s\n");
    fflush(g_log);

    struct timespec ts;
    int16_t s1, s2;
    int rc = EXIT_SUCCESS;

    while (g_running) {
        int ok1 = 0, ok2 = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sample(g_h1, &s1) == 0) {
                ok1 = 1;
                break;
            }
            usleep(1000);
        }

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sample(g_h2, &s2) == 0) {
                ok2 = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sample read failure (ok1=%d ok2=%d); skipping.\n",
                    ok1, ok2);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            continue;
        }

        double tdoa = (double)(ts.tv_sec - ts.tv_sec)
                    + (double)(ts.tv_nsec - ts.tv_nsec) / 1e9;

        log_sample(&ts, s1, s2, tdoa);
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return rc;
}

