        fprintf(stderr, "i2cOpen(0x%02X) failed: %s\n",
                I2C_ADDR_2, strerror(errno));
        i2cClose(g_h1);
        g_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_h1) != 0 || init_sensor(g_h2) != 0) {
        fprintf(stderr, "Sensor init failed; aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log, "# timestamp_sec, timestamp_nsec, sensor1, sensor2, tdoa_s\n");
    fflush(g_log);

    struct timespec ts;
    int16_t s1, s2;
    int rc = EXIT_SUCCESS;

    while (g_running) {
        int ok1 = 0, ok2 = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sample(g_h1, &s1) == 0) {
                ok1 = 1;
                break;
            }
            usleep(1000);
        }

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sample(g_h2, &s2) == 0) {
                ok2 = 1;
                break;
            }
            usleep(1000);
        }

        if (!ok1 || !ok2) {
            fprintf(stderr, "Sample read failure (ok1=%d ok2=%d); skipping.\n",
                    ok1, ok2);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            continue;
        }

        double tdoa = (double)(ts.tv_sec - ts.tv_sec)
                    + (double)(ts.tv_nsec - ts.tv_nsec) / 1e9;

        log_sample(&ts, s1, s2, tdoa);
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return rc;
}

