/*
 * ADIS16488A IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16488A CS  -> GPIO8  (SPI0 CE0)
 *   ADIS16488A SCLK-> GPIO11 (SPI0 SCLK)
 *   ADIS16488A DOUT-> GPIO9  (SPI0 MISO)
 *   ADIS16488A DIN -> GPIO10 (SPI0 MOSI)
 *   ADIS16488A VDD -> 3.3 V
 *   ADIS16488A GND -> GND
 *
 * SPI: 1 MHz, mode 3 (CPOL=1, CPHA=1), 16-bit words.
 * Stall time: >= 40 us between command and data transfer.
 *
 * Build: gcc -O2 -Wall -o imu_reader imu_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16488A constants ---- */
#define ADIS16488A_SENSITIVITY_GYRO   0.005f   /* deg/sec/LSB */
#define ADIS16488A_SENSITIVITY_ACCEL  0.00025f /* g/LSB */

/* ---- SPI / timing ---- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0x03       /* mode 3: CPOL=1, CPHA=1 */
#define STALL_US       40         /* >= 40 us stall between command and data */
#define SAMPLE_MS      100        /* 100 ms sampling interval */

/* ---- Register addresses ---- */
#define REG_GYRO_XOUT  0x04
#define REG_GYRO_YOUT  0x06
#define REG_GYRO_ZOUT  0x08
#define REG_ACCEL_XOUT 0x0A
#define REG_ACCEL_YOUT 0x0C
#define REG_ACCEL_ZOUT 0x0E

/* ---- Globals for cleanup ---- */
static int  g_spi_handle = -1;
static FILE *g_fp        = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_fp) {
        fclose(g_fp);
        g_fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit register from the ADIS16488A.
 * Returns 0 on success, -1 on SPI error.                              */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw;

    if (read_register(REG_GYRO_XOUT, &raw) != 0) return -1;
    *gyro_x = (float)raw * ADIS16488A_SENSITIVITY_GYRO;

    if (read_register(REG_GYRO_YOUT, &raw) != 0) return -1;
    *gyro_y = (float)raw * ADIS16488A_SENSITIVITY_GYRO;

    if (read_register(REG_GYRO_ZOUT, &raw) != 0) return -1;
    *gyro_z = (float)raw * ADIS16488A_SENSITIVITY_GYRO;

    if (read_register(REG_ACCEL_XOUT, &raw) != 0) return -1;
    *accel_x = (float)raw * ADIS16488A_SENSITIVITY_ACCEL;

    if (read_register(REG_ACCEL_YOUT, &raw) != 0) return -1;
    *accel_y = (float)raw * ADIS16488A_SENSITIVITY_ACCEL;

    if (read_register(REG_ACCEL_ZOUT, &raw) != 0) return -1;
    *accel_z = (float)raw * ADIS16488A_SENSITIVITY_ACCEL;

    return 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
static int write_to_csv(const char *ts, float gx, float gy, float gz,
                        float ax, float ay, float az)
{
    if (fprintf(g_fp, "%s,%.4f,%.4f,%.4f,%.6f,%.6f,%.6f\n",
                ts, gx, gy, gz, ax, ay, az) < 0) {
        fprintf(stderr, "fprintf to CSV failed\n");
        return -1;
    }
    if (fflush(g_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel=%d, speed=%d, flags=0x%02X)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- CSV open ---- */
    g_fp = fopen("imu_data.csv", "w");
    if (!g_fp) {
        perror("fopen imu_data.csv");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(g_fp);

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- cleanup on exit ---- */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit registration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (write_to_csv(ts, gx, gy, gz, ax, ay, az) != 0) {
                fprintf(stderr, "CSV write failed; aborting.\n");
                break;
            }
        } else {
            fprintf(stderr, "IMU read error — skipping sample.\n");
        }

        /* Non-blocking 100 ms delay so signals are checked promptly. */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(10000); /* 10 ms */
    }

    printf("\nShutting down cleanly.\n");
    return EXIT_SUCCESS;
}

