 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16448 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM 9,  SPI0 MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * SPI: bus 0, mode 3 (CPOL=1, CPHA=1), max 1 MHz.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adis16448_reader adis16448_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADIS16448 register map (single-register read protocol) ---- */
#define ADIS16448_REG_GYRO_XOUT  0x04
#define ADIS16448_REG_GYRO_YOUT  0x06
#define ADIS16448_REG_GYRO_ZOUT  0x08
#define ADIS16448_REG_ACCEL_XOUT 0x0A
#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

/* ---- Scales (from datasheet) ---- */
#define GYRO_SCALE  0.02f   /* dps/LSB */
#define ACCEL_SCALE 0.00025f /* g/LSB */

/* ---- SPI configuration ---- */
#define SPI_DEVICE   "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000U
#define SPI_MODE     3
#define SPI_BITS     8

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * ADIS16448 single-register read:
 *   tx[0] = 0x80 | (reg & 0x7F)  (bit 7 = read)
 *   tx[1] = 0x00                 (dummy to clock out data)
 *   rx[1] contains the 16-bit data (MSB first)
 */
static int adis_read_reg(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(0x80 | (reg & 0x7F)), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int fd, uint8_t reg, float scale, float *value)
{
    int16_t raw;
    if (adis_read_reg(fd, reg, &raw) < 0)
        return -1;
    *value = (float)raw * scale;
    return 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI mode ---- */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Configure SPI bits per word ---- */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Configure SPI max speed ---- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 reader started (SPI0 CE0, %u Hz, mode %d)\n",
           speed, mode);
    printf("Press Ctrl+C to stop.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float gx = 0.0f, gy = 0.0f, gz = 0.0f;
        float ax = 0.0f, ay = 0.0f, az = 0.0f;
        bool ok = true;

        if (read_sensor(g_spi_fd, ADIS16448_REG_GYRO_XOUT,   GYRO_SCALE,   &gx) < 0) ok = false;
        if (read_sensor(g_spi_fd, ADIS16448_REG_GYRO_YOUT,   GYRO_SCALE,   &gy) < 0) ok = false;
        if (read_sensor(g_spi_fd, ADIS16448_REG_GYRO_ZOUT,   GYRO_SCALE,   &gz) < 0) ok = false;
        if (read_sensor(g_spi_fd, ADIS16448_REG_ACCEL_XOUT, ACCEL_SCALE, &ax) < 0) ok = false;
        if (read_sensor(g_spi_fd, ADIS16448_REG_ACCEL_YOUT, ACCEL_SCALE, &ay) < 0) ok = false;
        if (read_sensor(g_spi_fd, ADIS16448_REG_ACCEL_ZOUT, ACCEL_SCALE, &az) < 0) ok = false;

        if (!ok) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            printf("Gyro:  X=%+.4f dps  Y=%+.4f dps  Z=%+.4f dps\n"
                   "Accel: X=%+.6f g    Y=%+.6f g    Z=%+.6f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        sleep_ms(100);
    }

    printf("\nExiting cleanly.\n");

cleanup:
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return EXIT_SUCCESS;
}

