/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM, SPI CE0)
 *   ADIS16448 SCLK-> GPIO11 (BCM, SPI SCLK)
 *   ADIS16448 DOUT-> GPIO9  (BCM, SPI MISO)
 *   ADIS16448 DIN -> GPIO10 (BCM, SPI MOSI)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o adis16448_reader adis16448_reader.c -lpigpio -lrt
 * Run:
 *   sudo ./adis16448_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 constants (from datasheet) ---- */
#define ADIS16448_SPI_SPEED      1000000U   /* 1 MHz – well within 20 MHz limit */
#define ADIS16448_SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit */
#define ADIS16448_SPI_CHANNEL    0          /* CE0 on GPIO8 */

#define ADIS16448_READ_BIT       0x8000     /* Bit 15 = 1 for read */
#define ADIS16448_GYRO_XOUT_REG  0x04       /* Gyro X output */
#define ADIS16448_GYRO_YOUT_REG  0x06       /* Gyro Y output */
#define ADIS16448_GYRO_ZOUT_REG  0x08       /* Gyro Z output */
#define ADIS16448_AUX_XOUT_REG   0x0A       /* Auxiliary X output */
#define ADIS16448_AUX_YOUT_REG   0x0C       /* Auxiliary Y output */
#define ADIS16448_AUX_ZOUT_REG   0x0E       /* Auxiliary Z output */

#define ADIS16448_GYRO_SCALE     0.05f      /* deg/sec per LSB */
#define ADIS16448_ACCEL_SCALE    0.00025f   /* g per LSB */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read one 16-bit register via two-cycle SPI ----
 *
 * The ADIS16448 requires two 16-bit transfers:
 *   1. Send the read command (reg | 0x8000) in the first 16-bit word.
 *   2. Send a dummy address (0x0000) in the second word to clock out
 *      the 16-bit data.
 *
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int adis16448_read_reg(int spi_handle, uint16_t reg, int16_t *out)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    /* Phase 1: send read command */
    tx[0] = (reg >> 8) & 0xFF;
    tx[1] = reg & 0xFF;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed (phase 1, reg 0x%02X)\n", reg);
        return -1;
    }

    /* Stall for at least 40 us (datasheet: t_stall ≥ 40 µs) */
    gpioDelay(40);

    /* Phase 2: dummy address to clock out data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed (phase 2, reg 0x%02X)\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ---- Read all six channels ---- */
static int adis16448_read_all(int spi_handle,
                              float *gyro_x, float *gyro_y, float *gyro_z,
                              float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw;

    if (adis16448_read_reg(spi_handle, ADIS16448_GYRO_XOUT_REG, &raw) != 0) return -1;
    *gyro_x = (float)raw * ADIS16448_GYRO_SCALE;

    if (adis16448_read_reg(spi_handle, ADIS16448_GYRO_YOUT_REG, &raw) != 0) return -1;
    *gyro_y = (float)raw * ADIS16448_GYRO_SCALE;

    if (adis16448_read_reg(spi_handle, ADIS16448_GYRO_ZOUT_REG, &raw) != 0) return -1;
    *gyro_z = (float)raw * ADIS16448_GYRO_SCALE;

    if (adis16448_read_reg(spi_handle, ADIS16448_AUX_XOUT_REG, &raw) != 0) return -1;
    *accel_x = (float)raw * ADIS16448_ACCEL_SCALE;

    if (adis16448_read_reg(spi_handle, ADIS16448_AUX_YOUT_REG, &raw) != 0) return -1;
    *accel_y = (float)raw * ADIS16448_ACCEL_SCALE;

    if (adis16448_read_reg(spi_handle, ADIS16448_AUX_ZOUT_REG, &raw) != 0) return -1;
    *accel_z = (float)raw * ADIS16448_ACCEL_SCALE;

    return 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0 on GPIO8), 1 MHz, Mode 0 */
    g_spi_handle = spiOpen(ADIS16448_SPI_CHANNEL, ADIS16448_SPI_SPEED, ADIS16448_SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %u Hz): %d\n",
                ADIS16448_SPI_CHANNEL, ADIS16448_SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 reader started. Press Ctrl-C to stop.\n");

    while (g_running) {
        float gyro_x, gyro_y, gyro_z;
        float accel_x, accel_y, accel_z;

        if (adis16448_read_all(g_spi_handle,
                               &gyro_x, &gyro_y, &gyro_z,
                               &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Read error – continuing\n");
        } else {
            printf("Gyro X: %+.2f deg/s, Gyro Y: %+.2f deg/s, Gyro Z: %+.2f deg/s  "
                   "Accel X: %+.4f g, Accel Y: %+.4f g, Accel Z: %+.4f g\n",
                   gyro_x, gyro_y, gyro_z,
                   accel_x, accel_y, accel_z);
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

