/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x68
 * Build: gcc -O2 -Wall -o mpu6886 mpu6886.c
 *
 * Reads accel + gyro X/Y/Z (16-bit signed) every 50 ms and prints to stdout.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR    0x68

/* MPU-6886 register addresses */
#define REG_SMPLRT_DIV   0x19
#define REG_CONFIG       0x1A
#define REG_GYRO_CONFIG  0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43
#define REG_WHO_AM_I     0x75
#define WHO_AM_I_VAL     0x68

#define SAMPLE_PERIOD_US 50000  /* 50 ms */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read N bytes starting at an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C set reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    /* Read data */
    ssize_t total = 0;
    while ((size_t)total < n) {
        ssize_t r = read(fd, dst + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                    reg, strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read from reg 0x%02X: unexpected EOF (got %zd of %zu)\n",
                    reg, total, n);
            return -1;
        }
        total += r;
    }
    return 0;
}

/* Read a 16-bit big-endian signed value from two consecutive registers. */
static int read_axis(int fd, uint8_t reg_hi, int16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_regs(fd, reg_hi, buf, sizeof(buf)) != 0)
        return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6886(int fd)
{
    uint8_t who;
