/*
 * ADXL345 impact detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_detector impact_detector.c -lpigpio -lrt
 * Run:    sudo ./impact_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (datasheet) ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_DEVID          0x00
#define ADXL345_DEVID_VALUE    0xE5
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C
#define ADXL345_RANGE          0x31
#define ADXL345_RANGE_2G       0x00

/* ---- Application constants ---- */
#define I2C_BUS               1
#define LED_GPIO              17
#define IMPACT_THRESHOLD_G    2.5f
#define SAMPLE_PERIOD_US      10000   /* 10 ms */
#define LED_ON_US             500000  /* 500 ms */
#define LOG_FILE              "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Safe to call even if pigpio not initialised */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Read a single byte register ---- */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return -1;
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Write a single byte register ---- */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    return i2cWriteByteData(handle, reg, value);
}

/* ---- Initialise ADXL345 ---- */
static int init_adxl345(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (read_register(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Error: cannot read DEVID register (I2C bus error).\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                        devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby first (clear measure bit) so configuration takes effect */
    if (write_register(handle, ADXL345_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error: cannot write POWER_CTL (standby).\n");
        return -1;
    }

    /* Data format: full resolution, right-justified, +/-2g range */
    if (write_register(handle, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Error: cannot write DATA_FORMAT.\n");
        return -1;
    }

    /* Data rate: 100 Hz (0x0A) */
    if (write_register(handle, ADXL345_BW_RATE, 0x0A) != 0) {
        fprintf(stderr, "Error: cannot write BW_RATE.\n");
        return -1;
    }

    /* Range: +/-2g */
    if (write_register(handle, ADXL345_RANGE, ADXL345_RANGE_2G) != 0) {
        fprintf(stderr, "Error: cannot write RANGE.\n");
        return -1;
    }

    /* Measurement mode */
    if (write_register(handle, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error: cannot write POWER_CTL (measure).\n");
        return -1;
    }

    return 0;
}

/* ---- Read acceleration (full resolution, +/-2g) ---- */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char data[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error: cannot read 6-byte acceleration block.\n");
        return -1;
    }

    /* Full resolution, little-endian: 16-bit signed, 4 mg/LSB */
    int16_t raw_x = (int16_t)((data[1] << 8) | (uint8_t)data[0]);
    int16_t raw_y = (int16_t)((data[3] << 8) | (uint8_t)data[2]);
    int16_t raw_z = (int16_t)((data[5] << 8) | (uint8_t)data[4]);

    /* ±2g range => 256 LSB/g */
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

/* ---- Compute total acceleration magnitude ---- */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ---- Log impact event ---- */
static void log_impact(float magnitude, float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s - Impact detected! Magnitude: %.2f g (X: %.2f, Y: %.2f, Z: %.2f)\n",
            timestamp, magnitude, x, y, z);
    fflush(g_log_file);
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at address 0x%02X (rc=%d).\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (init_adxl345(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Threshold: %.1f g. Press Ctrl+C to exit.\n",
           IMPACT_THRESHOLD_G);

    /* Main polling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD_G) {
                printf("Impact detected! Magnitude: %.2f g (X: %.2f, Y: %.2f, Z: %.2f)\n",
                       magnitude, x, y, z);

                gpioWrite(LED_GPIO, 1);
                log_impact(magnitude, x, y, z);

                /* Keep LED on for 500 ms, checking for shutdown */
                uint32_t elapsed = 0;
                while (g_running && elapsed < LED_ON_US) {
                    gpioDelay(10000); /* 10 ms slices */
                    elapsed += 10000;
                }
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            /* Bus error: back off briefly and retry */
            gpioDelay(100000);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

