/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define PWR_MGMT_1   0x06
#define ACCEL_XOUT_H 0x2D
#define GYRO_XOUT_H  0x33

/* Scaling factors for default ±2g/250°/s range */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_imu(void) {
    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */
    return 0;
}

static int read_imu_data(float *ax, float *ay, float *az,
                         float *gx, float *gy, float *gz) {
    char buf[12];
    int16_t raw_ax, raw_ay, raw_az, raw_gx, raw_gy, raw_gz;

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf + 6, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    raw_ax = (int16_t)((buf[0] << 8) | buf[1]);
    raw_ay = (int16_t)((buf[2] << 8) | buf[3]);
    raw_az = (int16_t)((buf[4] << 8) | buf[5]);
    raw_gx = (int16_t)((buf[6] << 8) | buf[7]);
    raw_gy = (int16_t)((buf[8] << 8) | buf[9]);
    raw_gz = (int16_t)((buf[10] << 8) | buf[11]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;

    return 0;
}

static void log_data(float ax, float ay, float az,
                     float gx, float gy, float gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

int main(void) {
    float ax, ay, az, gx, gy, gz;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_imu() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open imu_log.csv for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        if (read_imu_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
        }
        gpioDelay(100000); /* 100 ms = 10 Hz */
    }

    fprintf(stderr, "\nExiting gracefully...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

