    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an I2C register                             */
/* ------------------------------------------------------------------ */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return -1;
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an I2C register                              */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    return i2cWriteByteData(handle, reg, value);
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (6 bytes starting at OUT_X_MSB)              */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(handle, MMA8451_REG_OUT_X_MSB, buffer, 6) != 6)
        return -1;

    *x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MMA8451Q accelerometer                               */
/* ------------------------------------------------------------------ */
static int init_mma8451q(int handle)
{
    uint8_t whoami;

    /* Verify sensor identity */
    if (i2c_read_reg(handle, MMA8451_REG_WHOAMI, &whoami) != 0) {
        fprintf(stderr, "Error: failed to read WHOAMI register\n");
        return -1;
    }
    if (whoami != MMA8451_WHOAMI_VALUE) {
        fprintf(stderr, "Error: WHOAMI mismatch (got 0x%02X, expected 0x%02X)\n",
                whoami, MMA8451_WHOAMI_VALUE);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (i2c_write_reg(handle, MMA8451_REG_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error: failed to set standby mode\n");
        return -1;
    }

    /* Set ±2 g full-scale range (bits 3:2 of XYZ_DATA_CFG = 00) */
    if (i2c_write_reg(handle, MMA8451_REG_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to set data range\n");
        return -1;
    }

    /* Active mode, 100 Hz ODR (CTRL_REG1 = 0x01) */
    if (i2c_write_reg(handle, MMA8451_REG_CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error: failed to set active mode\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                        */
/* ------------------------------------------------------------------ */
static void log_reading(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        snprintf(timestamp, sizeof(timestamp), "unknown-time");
    }

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Check if any axis exceeds the impact threshold                      */
/* ------------------------------------------------------------------ */
static bool check_impact(int16_t x, int16_t y, int16_t z, float threshold)
{
    float xg = (float)x / 1024.0f;
    float yg = (float)y / 1024.0f;
    float zg = (float)z / 1024.0f;

    return (fabsf(xg) > threshold ||
            fabsf(yg) > threshold ||
            fabsf(zg) > threshold);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;
    float threshold = IMPACT_THRESHOLD;

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MMA8451 address */
    g_i2c_handle = i2cOpen(1, MMA8451_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (init_mma8451q(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: MMA8451Q initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file */
    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open impact_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MMA8451Q impact detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            log_reading(g_log_file, x, y, z);

            if (check_impact(x, y, z, threshold)) {
                gpioWrite(LED_PIN, 1);
                gpioDelay(500000); /* 500 ms */
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

