#define I2C_BUS        "/dev/i2c-1"
#define TMAG5273_ADDR  0x2D
#define CSV_FILENAME   "magnetic_field_log.csv"
#define SAMPLE_PERIOD  1  /* seconds */

/* TMAG5273 register addresses (from datasheet) */
#define REG_DEVICE_CONFIG_1 0x00
#define REG_DEVICE_CONFIG_2 0x01
#define REG_X_CH_RESULT     0x02
#define REG_Y_CH_RESULT     0x04
#define REG_Z_CH_RESULT     0x06
#define REG_TEMP_RESULT     0x08

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd)
{
    /*
     * TMAG5273 DEVICE_CONFIG_1 (0x00):
     *   Bits [7:6] = 0x00 (default power-up mode)
     *   Bit  [5]   = 0    (continuous conversion)
     *   Bits [4:3] = 0x00 (default gain)
     *   Bit  [2]   = 0    (default)
     *   Bit  [1]   = 0    (default)
     *   Bit  [0]   = 0    (default)
     * Value = 0x00.
     */
    if (i2c_write_reg8(fd, REG_DEVICE_CONFIG_1, 0x00) < 0)
        return -1;

    /*
     * TMAG5273 DEVICE_CONFIG_2 (0x01):
     *   Bits [7:6] = 0x00 (default)
     *   Bit  [5]   = 0    (default)
     *   Bits [4:3] = 0x00 (default)
     *   Bit  [2]   = 0    (default)
     *   Bit  [1]   = 0    (default)
     *   Bit  [0]   = 0    (default)
     * Value = 0x00.
     */
    if (i2c_write_reg8(fd, REG_DEVICE_CONFIG_2, 0x00) < 0)
        return -1;

    return 0;
}

static int read_magnetic_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t x_raw, y_raw, z_raw;

    if (i2c_read_reg8(fd, REG_X_CH_RESULT, &x_raw) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_Y_CH_RESULT, &y_raw) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_Z_CH_RESULT, &z_raw) < 0)
        return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;

    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TMAG5273_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(CSV_FILENAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long file_size = ftell(g_log_fp);
        if (file_size == 0) {
            if (fprintf(g_log_fp, "Timestamp,X,Y,Z\n") < 0) {
                fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
            fflush(g_log_fp);
        }
    } else {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging TMAG5273 magnetic field data to %s. Press Ctrl+C to stop.\n",
           CSV_FILENAME);

    while (g_running) {
        int16_t x, y, z;

        if (read_magnetic_data(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Failed to read magnetic data.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

