/*
 * ADXL345 Free-Fall Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA, physical pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL, physical pin 5)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall_logger freefall_logger.c \
 *       -lgpiod -lm
 *
 * Run:
 *   ./freefall_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <poll.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 register definitions ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_DEVID          0x00
#define ADXL345_DEVID_VALUE    0xE5
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_INT_ENABLE     0x2E
#define ADXL345_INT_MAP        0x2F
#define ADXL345_INT_SOURCE     0x30
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C

/* ---- Free-fall parameters ---- */
#define FREEFALL_THRESHOLD     7.0   /* g */
#define FREEFALL_DURATION_MS   100   /* ms */

/* ---- GPIO / I2C ---- */
#define I2C_BUS                "/dev/i2c-1"
#define GPIO_CHIP              "gpiochip4"
#define GPIO_LINE              17
#define LOG_FILE               "freefall_log.csv"

/* ---- Data structures ---- */
typedef struct {
    float x, y, z;
} AccelerationData;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 operations ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) != 0)
        return -1;
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr,
                "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/-2g range, right-justified */
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Bandwidth rate: 100 Hz (0x0A) */
    if (i2c_write_reg8(fd, ADXL345_BW_RATE, 0x0A) != 0)
        return -1;

