    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_fp, "timestamp,x,y,z\n");
    fflush(g_log_fp);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /*
     * Poll loop:
     *   - On rising edge of INT1, read acceleration and log while
     *     free-fall is active.
     *   - On timeout, check g_running and loop.
     */
    struct timespec poll_ts = { 0, 100 * 1000 * 1000 }; /* 100 ms */
    struct timespec start_ts;
    bool freefall_active = false;
    struct timespec freefall_start;

    while (g_running) {
        int ret = ppoll(NULL, 0, &poll_ts, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "ppoll error: %s\n", strerror(errno));
            break;
        }

        if (ret > 0) {
            /* Event pending — read and act */
            uint8_t int_src = 0;
            if (i2c_read_reg8(g_i2c_fd, ADXL345_INT_SOURCE, &int_src) != 0)
                break;

            if (int_src & 0x02) {
                /* Free-fall interrupt */
                if (!freefall_active) {
                    freefall_active = true;
                    clock_gettime(CLOCK_MONOTONIC, &freefall_start);
                } else {
                    struct timespec now;
                    clock_gettime(CLOCK_MONOTONIC, &now);
                    long elapsed_ms =
                        (now.tv_sec - freefall_start.tv_sec) * 1000L +
                        (now.tv_nsec - freefall_start.tv_nsec) / 1000000L;

                    if (elapsed_ms >= FREEFALL_DURATION_MS) {
                        AccelerationData acc;
                        if (adxl345_read_accel(g_i2c_fd, &acc) == 0) {
                            log_data(g_log_fp, &acc);
                            printf("Free-fall detected! Logged.\n");
                        } else {
                            fprintf(stderr, "Failed to read acceleration.\n");
                        }
                        freefall_active = false;
                    }
                }
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

