/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (BCM pins 2 = SDA, 3 = SCL), address 0x6A
 * Logs timestamped accel/gyro data to motion_log.txt
 * Detects freefall (< 0.2 g) -> impact (> 2.5 g within 1 s)
 *
 * Build: gcc -O2 -Wall -o imu imu.c -lm -lpigpio -lrt
 * Run:   sudo ./imu
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR register definitions ---- */
#define LSM6DSR_ADDR        0x6A
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x6A
#define CTRL1_XL            0x10
#define CTRL2_G             0x11
#define OUTX_L_G            0x22
#define OUTX_H_G            0x23
#define OUTY_L_G            0x24
#define OUTY_H_G            0x25
#define OUTZ_L_G            0x26
#define OUTZ_H_G            0x27
#define OUTX_L_XL           0x28
#define OUTX_H_XL           0x29
#define OUTY_L_XL           0x2A
#define OUTY_H_XL           0x2B
#define OUTZ_L_XL           0x2C
#define OUTZ_H_XL           0x2D

/* ---- Configuration ---- */
#define I2C_BUS             1
#define SAMPLE_PERIOD_US    10000   /* 100 Hz -> 10 ms */
#define FREEFALL_THRESHOLD  0.2f    /* g */
#define IMPACT_THRESHOLD    2.5f    /* g */
#define IMPACT_WINDOW_S     1.0f    /* seconds */
#define ACCEL_SCALE         0.000244f /* g/LSB at ±2 g */
#define GYRO_SCALE          0.00875f  /* dps/LSB at ±250 dps */

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- State machine ---- */
typedef enum {
    STATE_IDLE,
    STATE_FREEFALL,
    STATE_IMPACT
} fall_state_t;

static fall_state_t current_state = STATE_IDLE;
static struct timespec freefall_start;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0)
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, val, rc);
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed: reg=0x%02X rc=%d (expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_imu(void)
{
    uint8_t who;
    if (i2c_read_reg(WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Accel: ODR=104 Hz (0x40), FS=±2 g (0x00) -> 0x40 */
    if (i2c_write_reg(CTRL1_XL, 0x40) != 0) return -1;
    /* Gyro: ODR=104 Hz (0x40), FS=±250 dps (0x00) -> 0x40 */
    if (i2c_write_reg(CTRL2_G, 0x40) != 0) return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_imu(float *ax, float *ay, float *az,
                    float *gx, float *gy, float *gz)
{
    uint8_t g_buf[6], a_buf[6];

    if (i2c_read_burst(OUTX_L_G, g_buf, 6) != 0) return -1;
    if (i2c_read_burst(OUTX_L_XL, a_buf, 6) != 0) return -1;

    int16_t rgx = (int16_t)((g_buf[1] << 8) | g_buf[0]);
    int16_t rgy = (int16_t)((g_buf[3] << 8) | g_buf[2]);
    int16_t rgz = (int16_t)((g_buf[5] << 8) | g_buf[4]);
    int16_t rax = (int16_t)((a_buf[1] << 8) | a_buf[0]);
    int16_t ray = (int16_t)((a_buf[3] << 8) | a_buf[2]);
    int16_t raz = (int16_t)((a_buf[5] << 8) | a_buf[4]);

    *gx = (float)rgx * GYRO_SCALE;
    *gy = (float)rgy * GYRO_SCALE;
    *gz = (float)rgz * GYRO_SCALE;
    *ax = (float)rax * ACCEL_SCALE;
    *ay = (float)ray * ACCEL_SCALE;
    *az = (float)raz * ACCEL_SCALE;
    return 0;
}

/* ---- Logging ---- */
static void log_data(float ax, float ay, float az,
                     float gx, float gy, float gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            tbuf, ts.tv_nsec / 1000000,
            ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

/* ---- Fall detection ---- */
static void check_fall(float ax, float ay, float az)
{
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    if (mag < FREEFALL_THRESHOLD) {
        if (current_state == STATE_IDLE) {
            current_state = STATE_FREEFALL;
            clock_gettime(CLOCK_MONOTONIC, &freefall_start);
            printf("[FREEFALL] mag=%.3f g\n", mag);
        }
    } else {
        if (current_state == STATE_FREEFALL) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - freefall_start.tv_sec)
                           + (now.tv_nsec - freefall_start.tv_nsec) / 1e9;
            if (elapsed <= IMPACT_WINDOW_S) {
                current_state = STATE_IMPACT;
                printf("[IMPACT] mag=%.3f g (freefall %.3f s)\n",
                       mag, (float)elapsed);
            } else {
                current_state = STATE_IDLE;
            }
        }
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_imu() != 0) {
        fprintf(stderr, "IMU init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("fopen motion_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "# timestamp,ax,ay,az,gx,gy,gz\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM6DSR ready. Sampling at 100 Hz. Ctrl+C to exit.\n");

    while (!terminate) {
        float ax, ay, az, gx, gy, gz;

        if (read_imu(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
            check_fall(ax, ay, az);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

