            current_state = STATE_FREEFALL;
            clock_gettime(CLOCK_MONOTONIC, &freefall_start);
            printf("[FREEFALL] mag=%.3f g\n", mag);
        }
    } else {
        if (current_state == STATE_FREEFALL) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - freefall_start.tv_sec)
                           + (now.tv_nsec - freefall_start.tv_nsec) / 1e9;
            if (elapsed <= IMPACT_WINDOW_S) {
