 *   (pigpio library must be installed; run with sudo if pigpio daemon is not already running.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16266 constants ---- */
#define ADIS16266_WHO_AM_I_REG  0x02
#define ADIS16266_WHO_AM_I_VAL  0xAD
#define ADIS16266_GLOB_CMD_REG  0x04
#define ADIS16266_GLOB_CMD_READ 0x80
#define ADIS16266_SMPL_PRD_REG  0x36
#define ADIS16266_SMPL_PRD_VAL  0x00
#define ADIS16266_GYRO_OUT_REG  0x04
#define ADIS16266_GYRO_SCALE    0.0305f   /* deg/sec/LSB */

/* ---- SPI / pigpio constants ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz */
#define SPI_FLAGS   0x0C             /* mode 3: CPOL=1, CPHA=1, active-low CS */
#define CS_PIN      8                /* BCM GPIO8 = CE0 */

#define LOG_FILE    "gyro_log.csv"
#define SAMPLE_US   10000            /* 10 ms */

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit ADIS16266 register.
 * Returns 0 on success, -1 on SPI error.                              */
static int adis_write_reg(uint8_t reg, uint16_t value)
{
    char tx[2];
    char rx[2];

    tx[0] = (char)(reg & 0x7F);          /* write: bit7 = 0 */
    tx[1] = (char)(value & 0xFF);

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit ADIS16266 register.
 * Returns 0 on success and stores value in *out, -1 on SPI error.     */
static int adis_read_reg(uint8_t reg, uint16_t *out)
{
    char tx[2];
    char rx[2];

    tx[0] = (char)(reg | 0x80);          /* read: bit7 = 1 */
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int adis_verify_id(void)
{
    uint16_t id = 0;
    if (adis_read_reg(ADIS16266_WHO_AM_I_REG, &id) != 0)
        return -1;
    if (id != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                id, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }
    printf("ADIS16266 verified (WHO_AM_I = 0x%04X)\n", id);
    return 0;
}

/* ------------------------------------------------------------------ */
static int adis_init(void)
{
    /* Set sample period to 0 (default) for continuous sampling. */
    if (adis_write_reg(ADIS16266_SMPL_PRD_REG, ADIS16266_SMPL_PRD_VAL) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_rate(float *rate_dps)
{
    uint16_t raw = 0;
    if (adis_read_reg(ADIS16266_GYRO_OUT_REG, &raw) != 0)
        return -1;
    *rate_dps = (float)((int16_t)raw) * ADIS16266_GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float rate_dps)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%03ld,%.4f\n", tbuf, ts.tv_nsec / 1000000L, rate_dps);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- CS pin setup (manual control via spiOpen flags, but we also
     *      configure it as an output and drive it high so the device
     *      sees a defined idle state.                                  */
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    /* ---- Open log file once ---- */
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,gyro_rate_dps\n");
    fflush(log_file);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (adis_init() != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (adis_verify_id() != 0) {
        fprintf(stderr, "ADIS16266 not detected\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyro data to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (!terminate) {
        float rate = 0.0f;
        if (read_gyro_rate(&rate) == 0) {
            log_data(rate);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

