/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   GY-50 VCC  -> Pi 3.3V (Pin 1)
 *   GY-50 GND  -> Pi GND  (Pin 9)
 *   GY-50 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *   GY-50 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *
 * Build:
 *   gcc -O2 -Wall -o gyro_logger gyro_logger.c -lm -li2c
 *
 * Run:
 *   sudo ./gyro_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- L3G4200D constants (per datasheet) ---- */
#define L3G4200D_WHO_AM_I   0x0F
#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_CTRL_REG1  0x20
#define L3G4200D_OUT_X_L    0x28
#define L3G4200D_OUT_X_H    0x29
#define L3G4200D_OUT_Y_L    0x2A
#define L3G4200D_OUT_Y_H    0x2B
#define L3G4200D_OUT_Z_L    0x2C
#define L3G4200D_OUT_Z_H    0x2D

#define CTRL_REG1_VAL       0x0F  /* 100 Hz ODR, all axes enabled */
#define SAMPLE_PERIOD_US    10000 /* 10 ms */
#define I2C_BUS             1
#define MAX_RETRIES         3
#define LOG_FILENAME        "gyro_log.csv"

/* ---- Globals for signal handler ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- Timestamp helper with nanoseconds ---- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01 00:00:00.000000000");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);

    size_t cur = strlen(buf);
    snprintf(buf + cur, len - cur, ".%09ld", ts.tv_nsec);
}

/* ---- Write a register with retry ---- */
static int write_reg_retry(int handle, uint8_t reg, uint8_t val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, val);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* ---- Read a 16-bit little-endian axis ---- */
static int read_axis(int handle, uint8_t reg_l, uint8_t reg_h, float *out)
{
    int lo = i2cReadByteData(handle, reg_l);
    if (lo < 0) {
        fprintf(stderr, "Error: I2C read of reg 0x%02X failed: %s\n",
                reg_l, strerror(errno));
        return -1;
    }
    int hi = i2cReadByteData(handle, reg_h);
    if (hi < 0) {
        fprintf(stderr, "Error: I2C read of reg 0x%02X failed: %s\n",
                reg_h, strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)((hi << 8) | (lo & 0xFF));
    *out = (float)raw / 114.285f; /* 8.75 mdps/LSB */
    return 0;
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0xD3 (SA1 tied to GND) */
    g_i2c_handle = i2cOpen(I2C_BUS, 0xD3, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    int who = i2cReadByteData(g_i2c_handle, L3G4200D_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (who != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor not present or wrong address.\n",
                        who, L3G4200D_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure CTRL_REG1: 100 Hz ODR, all axes enabled */
    if (write_reg_retry(g_i2c_handle, L3G4200D_CTRL_REG1, CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Error: Failed to configure CTRL_REG1 after retries.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILENAME, "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Cannot open %s: %s\n",
                LOG_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "Timestamp,X,Y,Z\n");
    fflush(g_log_file);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("Logging GY-50 L3G4200D gyroscope data to %s (Ctrl+C to stop)...\n",
           LOG_FILENAME);

    /* Main sampling loop */
    while (!g_terminate) {
        float x = 0.0f, y = 0.0f, z = 0.0f;
        int err = 0;

        if (read_axis(g_i2c_handle, L3G4200D_OUT_X_L, L3G4200D_OUT_X_H, &x) != 0)
            err = 1;
        if (read_axis(g_i2c_handle, L3G4200D_OUT_Y_L, L3G4200D_OUT_Y_H, &y) != 0)
            err = 1;
        if (read_axis(g_i2c_handle, L3G4200D_OUT_Z_L, L3G4200D_OUT_Z_H, &z) != 0)
            err = 1;

        if (err) {
            fprintf(stderr, "Error: I2C read failure — continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        char ts[40];
        get_timestamp(ts, sizeof(ts));

        if (fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z) < 0) {
            fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                    strerror(errno));
            break;
        }
        if (fflush(g_log_file) != 0) {
            fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

