/*
 * Raspberry Pi 5 – Omron D7S-0001 vibration sensor logger
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   D7S SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   D7S VCC  -> 3.3 V
 *   D7S GND  -> GND
 *
 * The D7S-0001 is a 3-axis vibration sensor that presents as an I2C
 * device at a fixed 7-bit address (0x50).  It returns 6 bytes of
 * acceleration data on every read: 2 bytes X, 2 bytes Y, 2 bytes Z.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vibration_logger vibration_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_I2C_ADDR   0x50
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */

/*
 * D7S-0001 I2C protocol (datasheet):
 *   Register 0x00 – 6 bytes of acceleration data (X, Y, Z).
 *   Each axis is a signed 16-bit value in two's complement.
 *
 *   Byte 0: X_L (low byte)
 *   Byte 1: X_H (high byte)
 *   Byte 2: Y_L
 *   Byte 3: Y_H
 *   Byte 4: Z_L
 *   Byte 5: Z_H
 *
 * A sensor-absent / bus-error condition is typically reported as
 * a short read (< 6 bytes) or a read that returns all 0xFF bytes.
 */
#define D7S_REG_DATA   0x00
#define D7S_READ_LEN   6
#define D7S_ERR_BYTES  0xFFFF  /* all 0xFF on a bus-error read */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read 6 bytes of acceleration data from the D7S.
 * Returns 0 on success, -1 on error.
 */
static int read_d7s(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t reg = D7S_REG_DATA;
    ssize_t w = write(fd, &reg, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n",
                strerror(errno));
        return -1;
    }

    uint8_t buf[D7S_READ_LEN];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        if (r < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of %d bytes\n",
                    r, (int)sizeof(buf));
        return -1;
    }

    /* Sensor-absent / bus-error heuristic: all 0xFF or 0x00 */
    if (buf[0] == 0xFF && buf[1] == 0xFF &&
        buf[2] == 0xFF && buf[3] == 0xFF &&
        buf[4] == 0xFF && buf[5] == 0xFF) {
        fprintf(stderr, "Warning: D7S returned 0xFF – sensor may be absent or not responding\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Open CSV log file --- */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,X,Y,Z\n");
        fflush(log_fp);
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t x, y, z;

        if (read_d7s(i2c_fd, &x, &y, &z) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(log_fp, "%s,%d,%d,%d\n", ts, x, y, z);
            fflush(log_fp);
        }
        /* On error, the loop simply retries next iteration. */

        usleep(SAMPLE_PERIOD);
    }

    /* --- Clean shutdown --- */
    fprintf(stderr, "\nShutting down...\n");
    fclose(log_fp);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

