/*
 * conveyor_monitor.c — Raspberry Pi 4 Model B
 *
 * Monitors two TI DRV5032 Hall-effect sensors on GPIO17 and GPIO27
 * (BCM numbering) with internal pull-ups enabled.  Logs each edge
 * with a millisecond-precision timestamp to conveyor_log.txt every
 * 50 ms.  When both sensors read logic 1 the program prints a
 * "Halt" message to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o conveyor_monitor conveyor_monitor.c -lpigpio -lrt
 * Run:    sudo ./conveyor_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LOG_FILE     "conveyor_log.txt"
#define POLL_DELAY_US 50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_sensor_state(FILE *fp, int pin, int value)
{
    struct timespec ts;
    struct tm tm_info;
    char time_buf[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld, GPIO%d, %d\n",
                time_buf, ts.tv_nsec / 1000000L, pin, value) < 0) {
        perror("fprintf");
    } else {
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Conveyor control                                                    */
/* ------------------------------------------------------------------ */

static void control_conveyor(int s1, int s2)
{
    if (s1 == 1 && s2 == 1) {
        printf("Halt\n");
        fflush(stdout);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_gpio;
    }

    /*
     * Request both pins as inputs with the internal pull-up enabled.
     * The DRV5032 open-collector output idles high when no magnetic
     * field is present, so the pull-up keeps the line defined when
     * the sensor is disconnected.
     */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_1_PIN) failed\n");
        goto cleanup_file;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_1_PIN) failed\n");
        goto cleanup_file;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_2_PIN) failed\n");
        goto cleanup_file;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(SENSOR_2_PIN) failed\n");
        goto cleanup_file;
    }

    printf("Conveyor monitoring started.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        log_sensor_state(fp, SENSOR_1_PIN, s1);
        log_sensor_state(fp, SENSOR_2_PIN, s2);

        control_conveyor(s1, s2);

        gpioDelay(POLL_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup_file:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

