#define LIS3MDL_OUT_Y_H     0x2B
#define LIS3MDL_OUT_Z_L     0x2C
#define LIS3MDL_OUT_Z_H     0x2D

/* ---- Calibration constants (replace with your calibrated values) ---- */
#define OFFSET_X 0.0f
#define OFFSET_Y 0.0f
#define OFFSET_Z 0.0f
#define SCALE_X  1.0f
#define SCALE_Y  1.0f
#define SCALE_Z  1.0f

/* ---- Application constants ---- */
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "magnetic_log.txt"
#define SAMPLE_PERIOD_US   100000  /* 10 Hz */
#define MAX_RETRIES        3
#define ALERT_THRESHOLD_MG 800.0f  /* 800 mG = 800 gauss */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
