        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_lis3mdl(int fd)
{
    uint8_t who;
    if (i2c_read_reg(fd, LIS3MDL_WHO_AM_I, &who) != 0)
        return -1;
    if (who != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: temp sensor enable, ODR = 10 Hz (0x70) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG1, 0x70) != 0)
        return -1;

    /* CTRL_REG2: full-scale = +/- 4 gauss (0x00) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG2, 0x00) != 0)
        return -1;

    /* CTRL_REG3: continuous-conversion mode (0x00) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG3, 0x00) != 0)
        return -1;

    /* CTRL_REG4: little-endian, high-resolution mode (0x0C) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG4, 0x0C) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetic_data(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LIS3MDL_OUT_X_L, raw, 6) != 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* ±4 gauss range, 14-bit left-justified → 1 mG = 0.146 gauss */
    *x = (float)rx * 0.146f;
    *y = (float)ry * 0.146f;
    *z = (float)rz * 0.146f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void check_alert(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > ALERT_THRESHOLD_MG) {
        fprintf(stderr,
                "[ALERT] Magnetic field magnitude: %.2f mG (X:%.2f Y:%.2f Z:%.2f)\n",
                mag, x, y, z);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                LIS3MDL_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int init_ok = 0;
    for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "LIS3MDL init attempt %d/%d failed\n",
                attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES)
            usleep(100000);
    }

    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after %d attempts.\n",
                MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "LIS3MDL initialized. Logging to %s at 10 Hz. Ctrl+C to stop.\n",
            LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_magnetic_data(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error — continuing after 100 ms backoff.\n");
            usleep(100000);
            continue;
        }

        x = (x - OFFSET_X) * SCALE_X;
        y = (y - OFFSET_Y) * SCALE_Y;
        z = (z - OFFSET_Z) * SCALE_Z;

        log_data(g_log_fp, x, y, z);
        check_alert(x, y, z);

        usleep(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

