/*
 * ADXL354B Vibration Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B CS  -> GPIO8  (BCM, SPI0 CE0)
 *   ADXL354B SDO -> GPIO9  (BCM, SPI0 MISO)
 *   ADXL354B SDA -> GPIO10 (BCM, SPI0 MOSI)
 *   ADXL354B SCL -> GPIO11 (BCM, SPI0 SCLK)
 *   ADXL354B VDD -> 3.3 V
 *   ADXL354B GND -> GND
 *
 * Build: gcc -O2 -Wall -o vibration_logger vibration_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADXL354B register map (datasheet rev 2.0) ---- */
#define ADXL354B_REG_STATUS       0x04
#define ADXL354B_REG_POWER_CTL    0x2D
#define ADXL354B_REG_RESET        0x2F
#define ADXL354B_REG_PARTID       0x02
#define ADXL354B_REG_XDATA_H      0x08
#define ADXL354B_REG_XDATA_L      0x09
#define ADXL354B_REG_YDATA_H      0x0A
#define ADXL354B_REG_YDATA_L      0x0B
#define ADXL354B_REG_ZDATA_H      0x0C
#define ADXL354B_REG_ZDATA_L      0x0D

#define ADXL354B_PARTID_VAL       0xAD  /* ADXL354B part ID */
#define ADXL354B_RESET_VAL        0x52

#define SPI_DEVICE               "/dev/spidev0.0"
#define SPI_SPEED_HZ             1000000
#define SPI_BITS_PER_WORD        8
#define SPI_MODE                 0

#define LOG_FILE_NAME            "vibration_log.txt"
#define SAMPLE_INTERVAL_US       100000  /* 100 ms */
#define MAX_RETRIES              3
#define RETRY_DELAY_US           10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL354B register.                            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int adxl_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x3F), value };  /* bit7=0 = write */
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL354B register.                           */
/* Returns 0 on success and stores the value in *out, -1 on error.    */
/* ------------------------------------------------------------------ */
static int adxl_read_reg(uint8_t reg, uint8_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };  /* bit7=1 = read */
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 20-bit signed axis value (two data registers, 3 bytes).     */
/* Returns 0 on success and stores the value in *out, -1 on error.    */
/* ------------------------------------------------------------------ */
static int adxl_read_axis(uint8_t reg_h, int32_t *out)
{
    uint8_t h, m, l;

    if (adxl_read_reg(reg_h, &h) < 0) return -1;
    if (adxl_read_reg(reg_h + 1, &m) < 0) return -1;
    if (adxl_read_reg(reg_h + 2, &l) < 0) return -1;

    /* 20-bit left-justified: [23:12] in bits 6..0 of h, m; [11:0] in l */
    int32_t raw = ((int32_t)h << 12) | ((int32_t)m << 4) | ((int32_t)l >> 4);

    /* Sign-extend from 20 bits to 32 bits */
    if (raw & 0x80000) raw |= 0xFFF00000;

    *out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl_reset(void)
{
    if (adxl_write_reg(ADXL354B_REG_RESET, ADXL354B_RESET_VAL) < 0)
        return -1;
    usleep(1000);  /* wait > 1 ms after reset */
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl_verify_partid(void)
{
    uint8_t partid;
    if (adxl_read_reg(ADXL354B_REG_PARTID, &partid) < 0)
        return -1;
    if (partid != ADXL354B_PARTID_VAL) {
        fprintf(stderr, "PARTID mismatch: got 0x%02X, expected 0x%02X\n",
                partid, ADXL354B_PARTID_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl_init(void)
{
    if (adxl_reset() < 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        return -1;
    }

    if (adxl_verify_partid() < 0) {
        fprintf(stderr, "ADXL354B not detected\n");
        return -1;
    }

    /* Clear RUN bit to enter standby */
    if (adxl_write_reg(ADXL354B_REG_POWER_CTL, 0x00) < 0)
        return -1;

    /* Wait for STABLE bit to set (max ~50 ms) */
    for (int i = 0; i < 50; i++) {
        uint8_t status;
        if (adxl_read_reg(ADXL354B_REG_STATUS, &status) < 0)
            return -1;
        if (status & 0x01) break;
        usleep(1000);
    }

    /* Set RUN bit to start normal operation */
    if (adxl_write_reg(ADXL354B_REG_POWER_CTL, 0x02) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl_init() < 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# ADXL354B vibration log started\n");
    fflush(g_log_fp);

    printf("Logging ADXL354B vibration data to %s (Ctrl+C to stop)\n",
           LOG_FILE_NAME);

    while (g_running) {
        int32_t x, y, z;
        int ok = 1;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (adxl_read_axis(ADXL354B_REG_XDATA_H, &x) == 0 &&
                adxl_read_axis(ADXL354B_REG_YDATA_H, &y) == 0 &&
                adxl_read_axis(ADXL354B_REG_ZDATA_H, &z) == 0)
                break;
            usleep(RETRY_DELAY_US);
        }

        if (attempt >= MAX_RETRIES) {
            fprintf(stderr, "SPI read failed after %d retries; skipping sample\n",
                    MAX_RETRIES);
            ok = 0;
        }

        if (ok) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
            fflush(g_log_fp);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

