#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses (from datasheet) */
#define ADIS16362_REG_X_GYRO_OUT  0x04
#define ADIS16362_REG_Y_GYRO_OUT  0x06
#define ADIS16362_REG_Z_GYRO_OUT  0x08
#define ADIS16362_REG_X_ACCEL_OUT 0x0A
#define ADIS16362_REG_Y_ACCEL_OUT 0x0C
#define ADIS16362_REG_Z_ACCEL_OUT 0x0E

/* Scaling factors (from datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   3       /* Mode 3: CPOL=1, CPHA=1 (active high, sample on trailing) */

/* Sampling */
#define SAMPLE_DELAY_US 10000 /* 10 ms */

/* Global state for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362 via SPI */
static int read_register(int handle, uint8_t reg, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADIS16362 SPI read protocol: send address with MSB set, then dummy byte,
       then read 2 bytes on the next transfer. */
    tx_buf[0] = reg | 0x80; /* MSB set for read */
    tx_buf[1] = 0x00;       /* Dummy byte to clock out data */

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Data is returned in the lower 16 bits of the 2-byte response */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[0]);
    return 0;
}

/* Read all sensor data from the ADIS16362 */
static int read_sensor_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register(handle, ADIS16362_REG_X_GYRO_OUT, &raw_gyro_x) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_Y_GYRO_OUT, &raw_gyro_y) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_Z_GYRO_OUT, &raw_gyro_z) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_X_ACCEL_OUT, &raw_accel_x) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_Y_ACCEL_OUT, &raw_accel_y) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_Z_ACCEL_OUT, &raw_accel_z) != 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

/* Log sensor data to the CSV file */
static void log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open imu_log.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(spi_handle, &gyro_x, &gyro_y, &gyro_z,
                             &accel_x, &accel_y, &accel_z) == 0) {
            log_data(log_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

