 * Logic:  LOW  = obstacle within ~30 cm detected
 *         HIGH = clear
 *
 * Build:  gcc -O2 -Wall -Wextra -o self_park self_park.c -lpigpio -lrt
 * Run:    sudo ./self_park
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO17 on Pi 5 */
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_US 1000000      /* 1 second */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
        printf("[%s] %s\n", ts, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Simulated self-parking routine (100 ms of busy-waiting)            */
/* ------------------------------------------------------------------ */
static void self_park(void)
{
    log_message("Self-parking sequence started");
    gpioDelay(100000);          /* 100 ms */
    log_message("Self-parking sequence completed");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;
    int gpio_initialised = 0;
    int line_requested = 0;

    /* --- Install SIGINT handler for clean shutdown ------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio ------------------------------------------ */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", ret);
        fprintf(stderr, "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }
    gpio_initialised = 1;

    /* --- Open the GPIO chip ----------------------------------------- */
    int chip = gpioGetChipByName(GPIO_CHIP_NAME);
    if (chip < 0) {
        fprintf(stderr, "Failed to open %s (code %d).\n", GPIO_CHIP_NAME, chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Request the GPIO line -------------------------------------- */
    int line = gpioGetLine(chip, GPIO_LINE_OFFSET);
    if (line < 0) {
        fprintf(stderr, "Failed to get line %d on %s (code %d).\n",
                GPIO_LINE_OFFSET, GPIO_CHIP_NAME, line);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(line, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set line %d as input (code %d).\n",
                GPIO_LINE_OFFSET, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    line_requested = 1;

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int level = gpioRead(line);
        if (level < 0) {
            fprintf(stderr, "Failed to read line %d (code %d).\n",
                    GPIO_LINE_OFFSET, level);
            break;
        }

        if (level == 0) {
            /* LOW  => obstacle detected within ~30 cm */
            self_park();
        }

        /* Sleep 1 s, but wake early if signalled */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(POLL_INTERVAL_US / 10);
        }
    }

    /* --- Clean shutdown --------------------------------------------- */
    if (line_requested) {
        gpioRelease(line);
    }
    if (gpio_initialised) {
        gpioTerminate();
    }

    return EXIT_SUCCESS;
}

