/*
 * KY-032 dual IR obstacle-avoidance sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   Sensor 1 OUT  -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT  -> GPIO27 (physical pin 13)
 *   VCC           -> 3.3 V (physical pin 1)
 *   GND           -> GND   (physical pin 9)
 *
 * The KY-032 module has an onboard LED and the logic-level output is
 * active-low: 0 = obstacle detected, 1 = path clear.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ky032_dual ky032_dual.c -lpigpio -lrt
 * Run:
 *   sudo ./ky032_dual
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define POLL_DELAY_US 100000          /* 100 ms */
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "----");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "----");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int rc;

    /* --- Initialise pigpio ------------------------------------------ */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        fprintf(stderr, "       Is the pigpio daemon running? Stop it first:\n");
        fprintf(stderr, "       sudo killall -q pigpiod\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs ---------------------------- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Enable internal pull-ups so the line is defined when the
     *     sensor is disconnected (active-low output idles high). ------ */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", SENSOR1_PIN);
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", SENSOR2_PIN);
    }

    /* --- Install signal handlers ------------------------------------ */
    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-032 dual sensor reader started.\n");
    printf("  Sensor 1: GPIO%d\n", SENSOR1_PIN);
    printf("  Sensor 2: GPIO%d\n", SENSOR2_PIN);
    printf("  Poll interval: %d ms\n", POLL_DELAY_US / 1000);
    printf("  Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int v1 = gpioRead(SENSOR1_PIN);
        int v2 = gpioRead(SENSOR2_PIN);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", v1, v2);
            break;
        }

        /* Active-low: 0 => obstacle detected, 1 => path clear. */
        bool obstacle1 = (v1 == 0);
        bool obstacle2 = (v2 == 0);

        char ts[TIMESTAMP_LEN];
        get_timestamp(ts, sizeof(ts));

        printf("[%s] Sensor 1: %s  Sensor 2: %s\n",
               ts, obstacle1 ? "OBSTACLE" : "CLEAR",
               obstacle2 ? "OBSTACLE" : "CLEAR");
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);   /* 100 ms */
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

