/*
 * ADIS16266 Gyroscope reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, /dev/spidev0.0)
 *   ADIS16266 SCLK-> GPIO11 (SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (SPI0 MOSI)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * SPI: /dev/spidev0.0, Mode 3 (CPOL=1, CPHA=1), 1 MHz, MSB first.
 *
 * Build: gcc -O2 -Wall -o adis16266_gyro adis16266_gyro.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD_NS 100000000L  /* 100 ms */
#define GYRO_SCALE      0.02f        /* deg/sec per LSB */

/* ADIS16266 register addresses (8-bit, upper nibble = 0x0 for data registers) */
#define REG_X_GYRO_OUT  0x04
#define REG_Y_GYRO_OUT  0x06
#define REG_Z_GYRO_OUT  0x08
#define REG_STATUS      0x02
#define REG_SMPL_PRD   0x36

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Perform a two-transfer SPI read of a 16-bit register.
 *
 * The ADIS16266 SPI protocol requires a 32-bit word where the MSB of
 * the first byte is set (bit 7 = 1) to indicate a read, and the
 * address occupies the next 7 bits (bits 6..0).  The remaining 24
 * bits are padding.  The device returns 24 bits of data in the
 * response, which are assembled into a 16-bit value.
 *
 * Returns 0 on success, -1 on error.
 */
static int spi_read_reg16(int fd, uint8_t addr, int16_t *out)
{
    uint8_t tx[4] = { (uint8_t)(addr | 0x80), 0x00, 0x00, 0x00 };
    uint8_t rx[4] = { 0 };
    struct spi_ioc_transfer tr;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X: %s\n",
                addr, strerror(errno));
        return -1;
    }

    /*
     * rx[0] = sent command byte
     * rx[1..2] = 16-bit data (MSB first)
     * rx[3] = padding
     */
    *out = (int16_t)(((uint16_t)rx[1] << 8) | rx[2]);
    return 0;
}

static int spi_write_reg8(int fd, uint8_t addr, uint8_t value)
{
    uint8_t tx[4] = { (uint8_t)(addr & 0x7F), value, 0x00, 0x00 };
    uint8_t rx[4] = { 0 };
    struct spi_ioc_transfer tr;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
