#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6A

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22
#define OUTX_L_XL    0x28

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6C

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read a single byte from an I2C register; returns 0 on success, -1 on error */
static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Write a single byte to an I2C register; returns 0 on success, -1 on error */
static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* Read multiple bytes starting at reg; returns 0 on success, -1 on error */
static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading burst from 0x%02X: got %d, expected %u\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* Initialize the LSM6DSR: verify WHO_AM_I, configure ODR */
static int init_lsm6dsr(int handle) {
    uint8_t who_am_i = 0;

    if (read_reg(handle, WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }

    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Accelerometer: ODR 104 Hz, FS 2 g, BW filter 408 Hz */
    if (write_reg(handle, CTRL1_XL, 0x40) != 0) {
        return -1;
    }

    /* Gyroscope: ODR 104 Hz, FS 245 dps */
    if (write_reg(handle, CTRL2_G, 0x40) != 0) {
        return -1;
    }

    return 0;
}

/* Read accelerometer and gyroscope data; returns 0 on success, -1 on error */
static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];

    /* Burst read 6 bytes starting at OUTX_L_G (0x22) */
    if (read_burst(handle, OUTX_L_G, buf, 6) != 0) {
        return -1;
    }

    *gx = (int16_t)((buf[1] << 8) | buf[0]);
    *gy = (int16_t)((buf[3] << 8) | buf[2]);
    *gz = (int16_t)((buf[5] << 8) | buf[4]);

    /* Burst read 6 bytes starting at OUTX_L_XL (0x28) */
    if (read_burst(handle, OUTX_L_XL, buf, 6) != 0) {
        return -1;
    }

    *ax = (int16_t)((buf[1] << 8) | buf[0]);
    *ay = (int16_t)((buf[3] << 8) | buf[2]);
    *az = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

int main(void) {
    int handle = -1;
    int16_t ax, ay, az, gx, gy, gz;

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM6DSR address */
    handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize LSM6DSR */
    if (init_lsm6dsr(handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: read and print data every 100 ms */
    while (g_running) {
        if (read_sensor_data(handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%d %d %d %d %d %d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }
        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Clean shutdown */
    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

