/*
 * FXOS8700 breakout reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   FXOS8700 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   FXOS8700 ADDR -> GND  (I2C address 0x1C)
 *   FXOS8700 VCC  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lpigpio -lrt
 * Run:    sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 constants -------------------------------------------------- */
#define FXOS8700_ADDR        0x1C          /* ADDR pin tied to GND */
#define FXOS8700_REG_STATUS  0x00
#define FXOS8700_REG_OUT_X_MSB 0x01        /* 12-byte block: accel + mag */
#define FXOS8700_REG_WHOAMI  0x0D
#define FXOS8700_WHOAMI_VAL  0xC7          /* expected identity byte */

#define FXOS8700_CTRL_REG1   0x2A          /* active mode, 100 Hz ODR */
#define FXOS8700_CTRL_REG2   0x2B          /* 14-bit accel, 16-bit mag */
#define FXOS8700_M_CTRL_REG1 0x5B          /* hybrid auto-increment */

/* ---- Globals for signal-safe cleanup ------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ----------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- I2C helpers -------------------------------------------------------- */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: rc=%d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: rc=%d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ---- Sensor init -------------------------------------------------------- */
static int init_fxos8700(int handle)
{
    /* 1. Verify device identity */
    int whoami = i2cReadByteData(handle, FXOS8700_REG_WHOAMI);
    if (whoami < 0) {
        fprintf(stderr, "Failed to read WHOAMI register: %d\n", whoami);
        return -1;
    }
    if (whoami != FXOS8700_WHOAMI_VAL) {
        fprintf(stderr, "WHOAMI mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, FXOS8700_WHOAMI_VAL);
        return -1;
    }

    /* 2. Standby mode so configuration changes take effect */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x00) < 0)
        return -1;

    /* 3. Reset device (bit 7 of CTRL_REG2) */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG2, 0x80) < 0)
        return -1;
    gpioDelay(2000);  /* 2 ms settle after reset */

    /* 4. Active mode, 100 Hz ODR (0x0D) */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x0D) < 0)
        return -1;

    /* 5. Hybrid auto-increment for mag (M_CTRL_REG1 = 0x20) */
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, 0x20) < 0)
        return -1;

    /* 6. 14-bit accel, 16-bit mag (CTRL_REG2 = 0x3D) */
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG2, 0x3D) < 0)
        return -1;

    gpioDelay(2000);  /* 2 ms for first conversion */
    return 0;
}

/* ---- Read combined block ------------------------------------------------ */
static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t buf[12];

    if (i2c_read_block(handle, FXOS8700_REG_OUT_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    /* Accel: 14-bit left-aligned, shift right 2 to get 16-bit signed */
    *ax = (int16_t)((buf[0]  << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2]  << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4]  << 8) | buf[5]) >> 2;

    /* Mag: 16-bit signed */
    *mx = (int16_t)((buf[6]  << 8) | buf[7]);
    *my = (int16_t)((buf[8]  << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

/* ---- Main --------------------------------------------------------------- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(g_i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialised. Reading every 100 ms (Ctrl-C to stop).\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        gpioDelay(100000);  /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

