/*
 * ADXL345 Tilt Monitor for Raspberry Pi 5
 *
 * Reads acceleration data from an ADXL345 over I2C, computes the tilt
 * angle, and logs events to /var/log/tilt_events.log when the tilt
 * exceeds a threshold of 30.0 degrees.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lm
 * Run:    sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Constants ----------------------------- */

#define I2C_BUS            "/dev/i2c-1"
#define ADXL345_ADDRESS    0x53

#define REG_DEVID          0x00
#define REG_POWER_CTL      0x2D
#define REG_DATA_FORMAT    0x31
#define REG_DATAX0         0x32
#define REG_BW_RATE        0x2C
#define REG_RANGE          0x31

#define DEVID_EXPECTED     0xE5
#define TILT_THRESHOLD     30.0f
#define SAMPLE_PERIOD_US   100000  /* 100 ms */
#define LOG_FILE           "/var/log/tilt_events.log"

/* --------------------------- Global State ---------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------- Function Prototypes ----------------------- */

static int  i2c_write_reg(uint8_t reg, uint8_t value);
static int  i2c_read_regs(uint8_t reg, uint8_t *buf, size_t len);
static int  adxl345_init(void);
static int  read_acceleration(float *x, float *y, float *z);
static float calculate_tilt_angle(float x, float y, float z);
static void log_tilt_event(float tilt_angle);
static void signal_handler(int sig);

/* --------------------------- I2C Helpers ----------------------------- */

static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(g_i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------- ADXL345 Initialization --------------------- */

static int adxl345_init(void)
{
    uint8_t devid = 0;

    if (i2c_read_regs(REG_DEVID, &devid, 1) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, DEVID_EXPECTED);
        return -1;
    }

    /* Standby mode so configuration changes take effect */
    if (i2c_write_reg(REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/-2g range, right-justified */
    if (i2c_write_reg(REG_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Data rate: 100 Hz (0x0A) */
    if (i2c_write_reg(REG_BW_RATE, 0x0A) != 0)
        return -1;

    /* Full resolution, +/-2g range */
    if (i2c_write_reg(REG_RANGE, 0x00) != 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_reg(REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* --------------------- Acceleration Read & Conversion ----------------- */

static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t raw[6];

    if (i2c_read_regs(REG_DATAX0, raw, 6) != 0)
        return -1;

    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    /*
     * Full resolution, +/-2g range  =>  sensitivity ~7.81 mg/LSB
     * Convert to g-force (1 g = 9.81 m/s^2).
     */
    *x = (float)x_raw / 256.0f * 0.0078125f;
    *y = (float)y_raw / 256.0f * 0.0078125f;
    *z = (float)z_raw / 256.0f * 0.0078125f;

    return 0;
}

/* --------------------------- Tilt Angle Math -------------------------- */

static float calculate_tilt_angle(float x, float y, float z)
{
    /*
     * Tilt angle from the X-Y plane.
     * Atan2 returns [-π, π] — convert to [0, 180] degrees.
     */
    float angle = atan2f(y, x) * 180.0f / (float)M_PI;
    if (angle < 0.0f)
        angle += 360.0f;
    return angle;
}

/* ------------------------------ Logging ------------------------------ */

static void log_tilt_event(float tilt_angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Tilt Angle: %.2f degrees\n", ts, tilt_angle);
    } else {
        fprintf(fp, "(time error) - Tilt Angle: %.2f degrees\n", tilt_angle);
    }

    fclose(fp);
}

/* --------------------------- Signal Handling ------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ------------------------------ */

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize the ADXL345 */
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ADXL345 initialized. Monitoring tilt (threshold %.1f°)...\n",
           TILT_THRESHOLD);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float tilt = calculate_tilt_angle(x, y, z);

        if (tilt > TILT_THRESHOLD) {
            printf("Tilt event: %.2f degrees\n", tilt);
            log_tilt_event(tilt);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby mode before closing */
        (void)i2c_write_reg(REG_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

