/*
 * KY-038 sound sensor monitor for Raspberry Pi 3 Model B+
 * Sensor OUT -> GPIO17 (BCM, physical pin 11)
 * 5-second window, 1 ms sample interval, threshold on high-readings.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_monitor sound_monitor.c -lpigpio -lrt
 * Run:    sudo ./sound_monitor <threshold>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN      17          /* BCM 17, physical pin 11 */
#define WINDOW_SECONDS  5
#define SAMPLE_US       1000        /* 1 ms */
#define STATUS_DELAY_S  1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t     now;
    struct tm  tm_buf;
    char       ts[32];

    time(&now);
    if (localtime_r(&now, &tm_buf) != NULL) {
        if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf) > 0)
            printf("[%s] ", ts);
    }
}

/* ------------------------------------------------------------------ */
/* Returns 1 if threshold is a valid positive integer, 0 otherwise.    */
static int parse_threshold(const char *arg, int *out)
{
    char *end = NULL;
    long  val = strtol(arg, &end, 10);

    if (end == arg) {
        fprintf(stderr, "Error: '%s' is not a valid integer.\n", arg);
        return 0;
    }
    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer (got %ld).\n", val);
        return 0;
    }
    if (val > 1000000) {
        fprintf(stderr, "Error: threshold too large (max 1000000).\n");
        return 0;
    }
    *out = (int)val;
    return 1;
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on GPIO error.                            */
static int read_sensor(int pin, int *out_high)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed (pigpio code %d).\n", pin, v);
        return -1;
    }
    *out_high = (v == 1) ? 1 : 0;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold : minimum high readings per 5-second window\n");
        return EXIT_FAILURE;
    }

    if (!parse_threshold(argv[1], &threshold))
        return EXIT_FAILURE;

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the line is deterministic when the
     * sensor is disconnected or its OUT line is low. */
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed.\n", SENSOR_PIN);
    }

    printf("Monitoring KY-038 on GPIO%d for %d high readings in %d s windows.\n",
           SENSOR_PIN, threshold, WINDOW_SECONDS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int high_count = 0;
        int error_flag = 0;

        /* 5-second window: sample every 1 ms for 5 s. */
        for (int i = 0; i < WINDOW_SECONDS * 1000 && g_running; i++) {
            int h = 0;
            if (read_sensor(SENSOR_PIN, &h) != 0) {
                error_flag = 1;
                break;
            }
            if (h)
                high_count++;
            gpioDelay(SAMPLE_US);   /* 1 ms */
        }

        if (!g_running)
            break;

        if (error_flag) {
            print_timestamp();
            printf("ERROR: GPIO read failure during window.\n");
        } else {
            print_timestamp();
            if (high_count > threshold)
                printf("ALERT  ");
            else
                printf("OK     ");
            printf("High Readings: %d/%d\n", high_count, WINDOW_SECONDS * 1000);
        }
        fflush(stdout);

        /* Sleep 1 s between windows (interruptible). */
        for (int s = 0; s < STATUS_DELAY_S && g_running; s++)
            sleep(1);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

