/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12 V electromagnetic door locks are controlled via TIP120-driven
 * 5 V active-HIGH relay modules on the GPIO bus.  GPIO17 (BCM) and
 * GPIO27 (BCM) are initialized as outputs with a default LOW state
 * (locks energized / closed) and a HIGH level (relay de-energized /
 * unlocked) for 5 seconds after a correct security code is entered.
 *
 * A random six-digit security code is generated and printed to stdout.
 * User input is read from stdin; non-numeric input is skipped and the
 * user is re-prompted.  On a match the access event is logged to
 * access_log.txt in CSV format and the door is unlocked for 5 s.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"
#define CODE_MIN    100000
#define CODE_MAX    999999

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(int *code)
{
    if (code == NULL)
        return -1;

    int r = rand() % (CODE_MAX - CODE_MIN + 1) + CODE_MIN;
    *code = r;
    return 0;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, code) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) != 0) {
        perror("gpiod_line_request_output(DOOR_A_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) != 0) {
        perror("gpiod_line_request_output(DOOR_B_PIN)");
        goto cleanup;
    }

    printf("Doors locked.  Enter security code: ");
    fflush(stdout);

    int code = 0;
    if (generate_code(&code) != 0) {
        fprintf(stderr, "Failed to generate security code.\n");
        goto cleanup;
    }
    printf("%d\n", code);
    fflush(stdout);

    char input[16];
    int entered = 0;

    while (g_running && !entered) {
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                fprintf(stderr, "EOF received on stdin.\n");
                break;
            }
            if (errno == EINTR) {
                clearerr(stdin);
                continue;
            }
            perror("fgets()");
            break;
        }

        long val = strtol(input, NULL, 10);
        if (errno == ERANGE || val < CODE_MIN || val > CODE_MAX) {
            fprintf(stderr, "Invalid input. Please enter a six-digit number.\n");
            fflush(stdout);
            continue;
        }

        if ((int)val == code) {
            printf("Access granted.\n");
            fflush(stdout);

            if (log_access(code) != 0)
                fprintf(stderr, "Warning: failed to log access event.\n");

            if (gpiod_line_set_value(line_a, 1) != 0)
                perror("gpiod_line_set_value(DOOR_A_PIN, 1)");
            if (gpiod_line_set_value(line_b, 1) != 0)
