#define BH1750_CONT_H  0x10
#define BH1750_CONT_L  0x20
#define BH1750_ONE_T   0x21
#define BH1750_ONE_H   0x22
#define BH1750_ONE_L   0x23
#define LOG_FILE       "light_log.txt"
#define SAMPLE_INTERVAL 5
#define CONV_TIME_MS   180

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_byte: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("i2c_read_bytes: read failed");
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    return 0;
}

