    if (i2c_write_byte(fd, BH1750_ONE_T) < 0) return -1;
    usleep(CONV_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("log_data: fopen failed");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("log_data: localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus failed");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE failed");
        close(fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor may be absent)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor initialized. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl-C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Error reading lux value.\n");
        } else {
