static int read_touch_data(int fd, uint16_t *touch_status) {
    uint8_t lo, hi;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) return -1;
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(PWM_PIN, 128) < 0) {
        fprintf(stderr, "Failed to start PWM on GPIO%d\n", PWM_PIN);
        return -1;
    }
    usleep(duration_ms * 1000);
    gpioPWM(PWM_PIN, 0);
    return 0;
}

static int log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fclose(fp);
    return 0;
}

static int authenticate_message(const char *message) {
    if (!message) return 0;
    size_t len = strlen(message);
    if (len < AUTH_PREFIX_LEN + SECRET_LEN) return 0;
    if (strncmp(message, AUTH_PREFIX, AUTH_PREFIX_LEN) != 0) return 0;
    if (strncmp(message + len - SECRET_LEN, SECRET_KEY, SECRET_LEN) != 0) return 0;
    return 1;
}

static int process_message(int client_fd, int *frequency) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        if (n < 0) perror("recv");
        return -1;
    }
    buffer[n] = '\0';
    if (!authenticate_message(buffer)) {
        fprintf(stderr, "Authentication failed for message: %s\n", buffer);
        return -1;
    }
    char *freq_str = strchr(buffer, ':');
    if (!freq_str) {
        fprintf(stderr, "Frequency not found in message\n");
        return -1;
    }
    freq_str++;
    *frequency = atoi(freq_str);
    if (*frequency <= 0) {
        fprintf(stderr, "Invalid frequency: %s\n", freq_str);
        return -1;
    }
    return 0;
}

