/*
 * LSM303DLHC Magnetometer → LED PWM on Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA  → Pi SDA1 (GPIO2 / physical pin 3)
 *   LSM303DLHC SCL  → Pi SCL1 (GPIO3 / physical pin 5)
 *   LSM303DLHC VCC → 3.3 V
 *   LSM303DLHC GND → GND
 *   LED anode     → GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode   → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_led mag_led.c -lpigpio -lrt
 * Run:
 *   sudo ./mag_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS         "/dev/i2c-1"
#define LSM303_ADDR     0x1D          /* LSM303DLHC accelerometer / magnetometer */

#define LSM303_REG_CTRL_REG1_M  0x20  /* Magnetometer control register 1 */
#define LSM303_REG_OUT_X_L_M   0x08  /* Magnetometer X-axis low byte */

#define LED_GPIO         17
#define PWM_RANGE        255
#define PWM_FREQ_HZ      1000
#define SAMPLE_PERIOD_US 100000       /* 100 ms */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int  init_magnetometer(int fd);
static int  read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z);
static void set_led_brightness(int gpio, int level);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Magnetometer ------------------------------ */
static int init_magnetometer(int fd)
{
    /*
     * LSM303DLHC magnetometer: CTRL_REG1_M (0x20) = 0x70
     *   TEMP_EN = 0, OM = high-performance, DO = 0
     *   MD = continuous-conversion mode, FAST_ODR = 0
     */
    if (i2c_write_reg(fd, LSM303_REG_CTRL_REG1_M, 0x70) < 0)
        return -1;
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, LSM303_REG_OUT_X_L_M, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *z = (int16_t)((buf[3] << 8) | buf[2]);
    *y = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ----------------------------- LED control ------------------------------- */
static void set_led_brightness(int gpio, int level)
{
    if (gpioPWM(gpio, level) < 0)
        fprintf(stderr, "gpioPWM failed on GPIO %d: %s\n",
                gpio, pigpio_error(gpioGetMode(gpio)));
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before releasing pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ_HZ);
    gpioPWM(LED_GPIO, 0);

    /* --- I2C open --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer init failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Log file (optional) --- */
    g_log_fp = fopen("magnetometer.log", "a");
    if (!g_log_fp)
        perror("Warning: cannot open log file");

    printf("LSM303DLHC magnetometer → LED PWM on GPIO%d. Ctrl+C to exit.\n",
           LED_GPIO);

    /* --- Main loop --- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Magnetometer read error — skipping sample\n");
            if (g_log_fp)
                fprintf(g_log_fp, "Magnetometer read error — skipping sample\n");
        } else {
            int magnitude = (int)((int32_t)z);
            if (magnitude < 0)           magnitude = 0;
            if (magnitude > PWM_RANGE)   magnitude = PWM_RANGE;

            set_led_brightness(LED_GPIO, magnitude);

            if (g_log_fp) {
                fprintf(g_log_fp, "X=%6d  Y=%6d  Z=%6d  |mag|=%3d\n",
                        x, y, z, magnitude);
                fflush(g_log_fp);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

