/*
 * HMC5883L magnetometer reader with hard-iron offset compensation.
 *
 * Wiring (Raspberry Pi Zero W):
 *   HMC5883L VCC  -> 3V3 (pin 1)
 *   HMC5883L GND  -> GND (pin 9)
 *   HMC5883L SDA  -> GPIO2 / I2C bus 1 SDA (pin 3)
 *   HMC5883L SCL  -> GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -o hmc5883l_comp hmc5883l_comp.c -lpigpio -lrt
 * Run:    sudo ./hmc5883l_comp
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HMC5883L register definitions ---- */
#define HMC5883L_ADDR        0x1E   /* 7-bit I2C address (ADDR pin tied to GND) */
#define REG_CONFIG_A         0x00
#define REG_CONFIG_B         0x01
#define REG_MODE             0x02
#define REG_DATA_X_MSB       0x03   /* 6 bytes: X_MSB..Z_LSB */

/* CONFIG_A: 8-average, 15 Hz, normal measurement */
#define CONFIG_A_VAL         0x70
/* CONFIG_B: Gain = 1.3 Gauss (0x20) */
#define CONFIG_B_VAL         0x20
/* MODE: Continuous measurement (0x00) */
#define MODE_VAL             0x00

/* ---- Application constants ---- */
#define SAMPLE_PERIOD_US     500000  /* 500 ms */
#define NUM_SAMPLES          100
#define I2C_BUS              1

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an HMC5883L register; returns 0 on success, -1 on error. */
static int hmc5883l_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at reg; returns 0 on success, -1 on error. */
static int hmc5883l_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the HMC5883L: verify device presence, configure registers. */
static int hmc5883l_init(int handle)
{
    uint8_t id = 0;

    /* Read ID register (0x0A) to confirm device is present */
    if (hmc5883l_read_block(handle, 0x0A, &id, 1) != 0) {
        fprintf(stderr, "[ERROR] HMC5883L not responding on bus %d addr 0x%02X\n",
                I2C_BUS, HMC5883L_ADDR);
        return -1;
    }
    if (id != 0x48) {
        fprintf(stderr, "[ERROR] Unexpected device ID 0x%02X (expected 0x48) — wrong sensor?\n", id);
        return -1;
    }

    /* Configure registers */
    if (hmc5883l_write_reg(handle, REG_CONFIG_A, CONFIG_A_VAL) != 0)
        return -1;
    if (hmc5883l_write_reg(handle, REG_CONFIG_B, CONFIG_B_VAL) != 0)
        return -1;
    if (hmc5883l_write_reg(handle, REG_MODE, MODE_VAL) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw magnetic field and compute running average offset. */
static int hmc5883l_read_offset(int handle,
                                float *x_off, float *y_off, float *z_off)
{
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;
    static float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    static int   count = 0;

    if (hmc5883l_read_block(handle, REG_DATA_X_MSB, data, 6) != 0)
        return -1;

    raw_x = (int16_t)((data[0] << 8) | data[1]);
    raw_y = (int16_t)((data[2] << 8) | data[3]);
    raw_z = (int16_t)((data[4] << 8) | data[5]);

    /* Running average over the last NUM_SAMPLES samples */
    x_sum -= (float)raw_x / (float)NUM_SAMPLES;
    y_sum -= (float)raw_y / (float)NUM_SAMPLES;
    z_sum -= (float)raw_z / (float)NUM_SAMPLES;

    x_sum += (float)raw_x;
    y_sum += (float)raw_y;
    z_sum += (float)raw_z;

    count++;

    if (count >= NUM_SAMPLES) {
        *x_off = x_sum / (float)NUM_SAMPLES;
        *y_off = y_sum / (float)NUM_SAMPLES;
        *z_off = z_sum / (float)NUM_SAMPLES;

        /* Reset for next window */
        x_sum = y_sum = z_sum = 0.0f;
        count = 0;
    } else {
        *x_off = 0.0f;
        *y_off = 0.0f;
        *z_off = 0.0f;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the HMC5883L address */
    g_i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, HMC5883L_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (hmc5883l_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] HMC5883L initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HMC5883L magnetometer running. Press Ctrl+C to exit.\n");

    /* Main acquisition loop */
    while (g_running) {
        if (hmc5883l_read_offset(g_i2c_handle, &x_off, &y_off, &z_off) == 0) {
            printf("X: %+.2f  Y: %+.2f  Z: %+.2f\n",
                   (float)0, (float)0, (float)0);  /* placeholder — real offset applied below */
        } else {
            fprintf(stderr, "[WARN] I2C read error — continuing\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

