code:
/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * I2C bus 1 (GPIO2=SDA, GPIO3=SCL), accelerometer at 0x19.
 * INT1 on BCM GPIO23 (physical pin 16) triggers dump of the last 10 samples.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ACCEL_ADDR        0x19
#define LSM303D_ACCEL_WHO_AM_I    0x0F
#define LSM303D_ACCEL_WHO_AM_I_VAL 0x49
#define LSM303D_ACCEL_CTRL_REG1_A 0x20
#define LSM303D_ACCEL_CTRL_REG4_A 0x23
#define LSM303D_ACCEL_OUT_X_L_A   0x28
#define LSM303D_ACCEL_OUT_X_H_A   0x29
#define LSM303D_ACCEL_OUT_Y_L_A   0x2A
#define LSM303D_ACCEL_OUT_Y_H_A   0x2B
#define LSM303D_ACCEL_OUT_Z_L_A   0x2C
#define LSM303D_ACCEL_OUT_Z_H_A   0x2D
#define LSM303D_ACCEL_INT1_CFG    0x30
#define LSM303D_ACCEL_INT1_THS    0x32
#define LSM303D_ACCEL_INT1_DURATION 0x33

/* ---- App constants ---- */
#define I2C_BUS_NAME             "/dev/i2c-1"
#define GPIO_CHIP_NAME           "gpiochip4"
#define INT1_BCM_PIN             23
#define SAMPLE_PERIOD_US         10000   /* 10 ms */
#define BUFFER_SIZE              64
#define SENSITIVITY_MG_PER_LSB   0.061f  /* ±2 g, 12-bit */
#define THRESHOLD_MG             2000.0f

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Prototypes ---- */
static int  i2c_write_reg(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_reg(int fd, uint8_t reg, uint8_t *val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len);
static int  init_accelerometer(int fd);
static int  read_acceleration(int fd, accel_sample_t *out);
static void buffer_add(circular_buffer_t *buf, accel_sample_t sample);
static void buffer_dump_last_n(const circular_buffer_t *buf, int n);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C block read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer init ---- */
static int init_accelerometer(int fd)
{
    uint8_t who_am_i = 0;
