#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS 500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_line_low(int pin)
{
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

static int cleanup(void)
{
    int rc = 0;
    if (set_line_low(SOLENOID_1_PIN) < 0) rc = -1;
    if (set_line_low(SOLENOID_2_PIN) < 0) rc = -1;
    gpioTerminate();
    return rc;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_line_low(SOLENOID_1_PIN) < 0 || set_line_low(SOLENOID_2_PIN) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int other_pin  = SOLENOID_2_PIN;

    while (g_running) {
        if (gpioWrite(active_pin, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", active_pin);
            break;
        }
        if (gpioWrite(other_pin, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", other_pin);
            break;
        }

        struct timespec ts;
        ts.tv_sec  = DELAY_MS / 1000;
        ts.tv_nsec = (DELAY_MS % 1000) * 1000000L;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            if (!g_running) break;
        }

        if (!g_running) break;

        active_pin = other_pin;
        other_pin  = (active_pin == SOLENOID_1_PIN) ? SOLENOID_2_PIN : SOLENOID_1_PIN;
    }

    return cleanup();
}

