        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_line_low(SOLENOID_1_PIN) < 0 || set_line_low(SOLENOID_2_PIN) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int other_pin  = SOLENOID_2_PIN;

    while (g_running) {
        if (gpioWrite(active_pin, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", active_pin);
            break;
        }
        if (gpioWrite(other_pin, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", other_pin);
            break;
        }

        struct timespec ts;
        ts.tv_sec  = DELAY_MS / 1000;
        ts.tv_nsec = (DELAY_MS % 1000) * 1000000L;
        while (nanosleep(&ts, &ts) < 0 && errno == EINTR) {
            if (!g_running) break;
        }

        if (!g_running) break;

        active_pin = other_pin;
        other_pin  = (active_pin == SOLENOID_1_PIN) ? SOLENOID_2_PIN : SOLENOID_1_PIN;
    }

    return cleanup();
}

