/*
 * Dual-factor door lock authentication for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - Two active-HIGH relay modules driving 12 V door locks.
 *   - Relay 1: GPIO17 (BCM).
 *   - Relay 2: GPIO27 (BCM).
 *   - Primary UART: /dev/serial0 (GPIO14/15).
 *   - Secondary UART: /dev/serial1.
 *
 * Behaviour:
 *   - Reads 6-digit codes from both UARTs simultaneously using non-blocking
 *     reads with a 5-second per-port timeout.
 *   - When both codes match and equal the expected constant "123456",
 *     energises both relay GPIOs for 2 seconds, then de-energises them.
 *   - On any mismatch or read error, both relays are de-energised (locked).
 *   - SIGINT / SIGTERM trigger a clean shutdown: both relays are de-energised
 *     and the pigpio library is terminated.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 *   (run as root, pigpio daemon must be stopped)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define RELAY_PIN_1      17          /* BCM GPIO17 — first lock relay      */
#define RELAY_PIN_2      27          /* BCM GPIO27 — second lock relay     */

#define UART_PORT_1      "/dev/serial0"
#define UART_PORT_2      "/dev/serial1"

#define BAUD_RATE        9600
#define READ_TIMEOUT_S   5           /* per-port read timeout              */
#define CODE_LENGTH      6
#define EXPECTED_CODE    "123456"
#define UNLOCK_DURATION  2           /* seconds to energise both relays   */

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void cleanup(void);
static int  init_gpio(void);
static int  init_uart(const char *port, int baud);
static int  read_code(int handle, char *buf, size_t len);
static bool compare_codes(const char *a, const char *b);
static int  unlock_doors(void);
static int  lock_doors(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* De-energise both relays (locked state) */
    gpioWrite(RELAY_PIN_1, 0);
    gpioWrite(RELAY_PIN_2, 0);

    /* Release pigpio resources */
    gpioTerminate();
}

/* ----------------------------- GPIO init --------------------------------- */

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(RELAY_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN_1);
        return -1;
    }
    if (gpioSetMode(RELAY_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN_2);
        return -1;
    }

    /* Ensure both relays are de-energised (locked) at startup */
    if (gpioWrite(RELAY_PIN_1, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN_1);
        return -1;
    }
    if (gpioWrite(RELAY_PIN_2, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN_2);
        return -1;
    }

    return 0;
}

/* ----------------------------- UART init --------------------------------- */

static int init_uart(const char *port, int baud)
{
    int handle = serOpen((char *)port, baud, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: serOpen(%s, %d) failed (code %d).\n",
                port, baud, handle);
        return -1;
    }
    return handle;
}

/* ----------------------------- Read code --------------------------------- */

/*
 * Reads exactly `len` digits from the UART into `buf`.
 * Returns 0 on success, -1 on read error, -2 on timeout.
 * Resets the input buffer on any non-digit character.
 */
static int read_code(int handle, char *buf, size_t len)
{
    size_t idx = 0;
    char ch;

    while (idx < len) {
        int n = serRead(handle, &ch, 1);

        if (n < 0) {
            fprintf(stderr, "Error: serRead failed on handle %d (code %d).\n",
                    handle, n);
            return -1;
        }
        if (n == 0) {
            /* Timeout — pigpio serRead returns 0 after the timeout */
            return -2;
        }

        if (ch >= '0' && ch <= '9') {
            buf[idx++] = ch;
        } else {
            /* Reset on non-digit */
            buf[0] = '\0';
            idx = 0;
        }
    }

    buf[len] = '\0';
    return 0;
}

/* ----------------------------- Code compare ------------------------------ */

/*
 * Constant-time string comparison to avoid timing side-channels.
 */
static bool compare_codes(const char *a, const char *b)
{
    if (a == NULL || b == NULL) {
        return false;
    }

    size_t len = strlen(a);
    if (strlen(b) != len) {
        return false;
    }

    int diff = 0;
    for (size_t i = 0; i < len; i++) {
        diff |= (unsigned char)a[i] ^ (unsigned char)b[i];
    }
    return diff == 0;
}

/* ----------------------------- Unlock doors ------------------------------ */

static int unlock_doors(void)
{
    printf("Unlocking doors...\n");
    fflush(stdout);

    if (gpioWrite(RELAY_PIN_1, 1) != 0) {
        fprintf(stderr, "Error: failed to energise relay GPIO%d.\n", RELAY_PIN_1);
        return -1;
    }
    if (gpioWrite(RELAY_PIN_2, 1) != 0) {
        fprintf(stderr, "Error: failed to energise relay GPIO%d.\n", RELAY_PIN_2);
        gpioWrite(RELAY_PIN_1, 0);
        return -1;
    }

    /* Hold unlock for 2 seconds (interruptible by signals) */
    for (int i = 0; i < UNLOCK_DURATION && g_running; i++) {
        sleep(1);
    }

    if (!g_running) {
        fprintf(stderr, "Warning: unlock interrupted by signal.\n");
    }

    if (lock_doors() != 0) {
        fprintf(stderr, "Warning: failed to lock doors after unlock.\n");
    }
    return 0;
}

/* ----------------------------- Lock doors -------------------------------- */

static int lock_doors(void)
{
    printf("Locking doors...\n");
    fflush(stdout);

    if (gpioWrite(RELAY_PIN_1, 0) != 0) {
        fprintf(stderr, "Error: failed to de-energise relay GPIO%d.\n", RELAY_PIN_1);
        return -1;
    }
    if (gpioWrite(RELAY_PIN_2, 0) != 0) {
        fprintf(stderr, "Error: failed to de-energise relay GPIO%d.\n", RELAY_PIN_2);
        return -1;
    }
    return 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise GPIO */
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialise UARTs */
    int handle1 = init_uart(UART_PORT_1, BAUD_RATE);
    if (handle1 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int handle2 = init_uart(UART_PORT_2, BAUD_RATE);
    if (handle2 < 0) {
        serClose(handle1);
        cleanup();
        return EXIT_FAILURE;
    }

    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];

    printf("Door lock authentication system started.\n");
    printf("Reading codes from %s and %s...\n", UART_PORT_1, UART_PORT_2);
    fflush(stdout);

    while (g_running) {
        code1[0] = '\0';
        code2[0] = '\0';

        int rc1 = read_code(handle1, code1, CODE_LENGTH);
        int rc2 = read_code(handle2, code2, CODE_LENGTH);

        if (rc1 == -2 || rc2 == -2) {
            /* Timeout — no data available this cycle */
            continue;
        }

        if (rc1 != 0 || rc2 != 0) {
            fprintf(stderr, "Error: UART read failure (handle1=%d, handle2=%d).\n",
                    rc1, rc2);
            lock_doors();
            continue;
        }

        /*
         * Both codes received.
         * Check for matching codes.
         */
        if (compare_codes(code1, code2)) {
            if (compare_codes(code1, EXPECTED_CODE)) {
                if (unlock_doors() != 0) {
                    fprintf(stderr, "Error: unlock_doors() failed.\n");
                }
            } else {
                fprintf(stderr, "Warning: codes match but do not equal expected.\n");
                lock_doors();
            }
        } else {
            fprintf(stderr, "Warning: codes do not match.\n");
            lock_doors();
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    cleanup();
    serClose(handle1);
    serClose(handle2);
    printf("Door lock authentication system stopped.\n");
    return EXIT_SUCCESS;
}

