#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <dlfcn.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define RELAY_ON_TIME_MS 1000
#define FAILSAFE_TIMEOUT_MS 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int priority, const char *message) {
    openlog("door_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static void log_timestamp(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    log_event(priority, log_message);
}

static void log_timestamp_value(int priority, const char *message, int value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s (value=%d)", timestamp, message, value);
    log_event(priority, log_message);
}

typedef struct {
    int pir_pin;
    int relay_pin;
    int relay_state;
    int last_pir_value;
    int failsafe_active;
    struct timespec failsafe_start;
    struct timespec last_poll;
    void *chip;
    void *line_pir;
    void *line_relay;
} DoorMonitor;

static DoorMonitor *door_monitor = NULL;

static void *load_gpio_chip(void) {
    void *handle = dlopen("libgpiod.so.4", RTLD_LAZY);
    if (!handle) {
        handle = dlopen("libgpiod.so.2", RTLD_LAZY);
    }
    if (!handle) {
        handle = dlopen("libgpiod.so", RTLD_LAZY);
    }
    if (!handle) {
        log_event(LOG_ERR, "Failed to load libgpiod: " + dlerror());
        return NULL;
    }
    return handle;
}

static void *gpio_chip_open(void *handle) {
    typedef struct gpiod_chip *(*open_chip_fn)(const char *);
    open_chip_fn open_chip = dlsym(handle, "gpiod_chip_open");
    if (!open_chip) {
        log_event(LOG_ERR, "Failed to find gpiod_chip_open: " + dlerror());
        return NULL;
    }
    return open_chip("gpiochip0");
}

static void *gpio_chip_get_line(void *chip, int pin) {
    typedef struct gpiod_line *(*get_line_fn)(struct gpiod_chip *, unsigned int);
    get_line_fn get_line = dlsym(RTLD_DEFAULT, "gpiod_chip_get_line");
    if (!get_line) {
        log_event(LOG_ERR, "Failed to find gpiod_chip_get_line: " + dlerror());
        return NULL;
    }
    return get_line((struct gpiod_chip *)chip, pin);
}

static int gpio_line_request_input(void *line, const char *consumer) {
    typedef int (*request_input_fn)(struct gpiod_line *, const char *);
    request_input_fn request_input = dlsym(RTLD_DEFAULT, "gpiod_line_request_input");
    if (!request_input) {
        log_event(LOG_ERR, "Failed to find gpiod_line_request_input: " + dlerror());
        return -1;
    }
    return request_input((struct gpiod_line *)line, consumer);
}

