#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON  0   /* active-LOW: 0 = relay OFF (conducting) */
#define RELAY_OFF 1   /* active-LOW: 1 = relay ON  (open circuit) */

#define CYCLE_DURATION_SEC 300   /* 5 minutes per zone */
#define PAUSE_DURATION_SEC  60   /* 1 minute between zones */
#define TIMER_INTERVAL_SEC  60   /* 60 s timer tick */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event)
{
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(LOG_INFO, "[%s] %s", ts, event);
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on pin %u", pin);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite failed on pin %u", pin);
        return -1;
    }
    return 0;
}

static int all_relays_off(void)
{
    int rc = 0;
    rc |= safe_write(RELAY1_PIN, RELAY_ON);
    rc |= safe_write(RELAY2_PIN, RELAY_ON);
    rc |= safe_write(RELAY3_PIN, RELAY_ON);
    rc |= safe_write(RELAY4_PIN, RELAY_ON);
    return rc;
}

static void timer_callback(void *userdata)
{
    (void)userdata;
    static int zone = 1;
    char msg[128];

    snprintf(msg, sizeof(msg), "Zone %d: ON", zone);
    log_event(msg);

    if (safe_write(RELAY1_PIN, RELAY_OFF) < 0 ||
        safe_write(RELAY2_PIN, RELAY_OFF) < 0 ||
        safe_write(RELAY3_PIN, RELAY_OFF) < 0 ||
        safe_write(RELAY4_PIN, RELAY_OFF) < 0) {
        log_event("Error: failed to activate relays");
        g_running = 0;
        return;
    }

    /*
     * Sleep in 1-second slices so the timer callback returns promptly
     * and the main loop can detect g_running == 0 promptly on SIGINT/SIGTERM.
     */
    for (int i = 0; i < CYCLE_DURATION_SEC && g_running; i++)
        sleep(1);

    snprintf(msg, sizeof(msg), "Zone %d: OFF", zone);
    log_event(msg);

    if (safe_write(RELAY1_PIN, RELAY_ON) < 0 ||
        safe_write(RELAY2_PIN, RELAY_ON) < 0 ||
        safe_write(RELAY3_PIN, RELAY_ON) < 0 ||
        safe_write(RELAY4_PIN, RELAY_ON) < 0) {
        log_event("Error: failed to deactivate relays");
        g_running = 0;
        return;
    }

    zone++;
    if (zone > 4)
        zone = 1;

    /* Pause between activations */
    for (int i = 0; i < PAUSE_DURATION_SEC && g_running; i++)
        sleep(1);
}

int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    unsigned pins[4] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };
    for (int i = 0; i < 4; i++) {
