/*
 * mpu6050_accel_driver.c — MPU6050 100 Hz sampling driver for Raspberry Pi 4.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050_accel_driver mpu6050_accel_driver.c
 * Run:    sudo ./mpu6050_accel_driver   (or ensure user is in the 'i2c' group)
 *
 * The driver exposes a sysfs-style interface at /sys/kernel/mpu6050_accel/
 *   latest  (reads the most recent sample)
 *   samples (reads the number of samples currently buffered)
 *   rate    (reads the sampling rate in Hz)
 *
 * The driver uses a POSIX per-process timer (SIGEV_SIGNAL) to schedule
 * 100 Hz sampling.  The timer callback writes the latest sample into
 * a circular buffer and increments a monotonic sample counter.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <poll.h>

#define I2C_BUS          "/dev/i2c-1"
#define MPU6050_ADDR     0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_XOUT_L 0x3C
#define MPU6050_REG_ACCEL_YOUT_H 0x3D
#define MPU6050_REG_ACCEL_YOUT_L 0x3E
#define MPU6050_REG_ACCEL_ZOUT_H 0x3F
#define MPU6050_REG_ACCEL_ZOUT_L 0x40

#define SAMPLE_RATE_HZ   100
#define BUFFER_SIZE      100
#define DRIVER_PATH      "/sys/kernel/mpu6050_accel"
#define LATEST_FILE      DRIVER_PATH "/latest"
#define SAMPLES_FILE     DRIVER_PATH "/samples"
#define RATE_FILE        DRIVER_PATH "/rate"

#define ACCEL_SCALE      16384.0f

typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static accel_sample_t *g_buffer = NULL;
static int g_buf_size = 0;
static int g_buf_head = 0;
static int g_buf_count = 0;
static int g_timer_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050 (sensor absent or bus error)\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static void timer_cb(int fd, short events, void *arg) {
    (void)fd; (void)events; (void)arg;

    accel_sample_t sample;
    if (i2c_read_reg16(g_i2c_fd, MPU6050_REG_ACCEL_XOUT_H, &sample.x) < 0 ||
        i2c_read_reg16(g_i2c_fd, MPU6050_REG_ACCEL_YOUT_H, &sample.y) < 0 ||
        i2c_read_reg16(g_i2c_fd, MPU6050_REG_ACCEL_ZOUT_H, &sample.z) < 0) {
        return;
    }

    g_buffer[g_buf_head] = sample;
    g_buf_head = (g_buf_head + 1) % g_buf_size;
    if (g_buf_count < g_buf_size) g_buf_count++;
}

static int create_sysfs_file(const char *path) {
    if (access(path, F_OK) == 0) return 0;
    int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

static int write_sysfs(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "write(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int read_sysfs(const char *path, char *buf, size_t len) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len - 1);
    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    return 0;
}

static void cleanup(void) {
    if (g_timer_fd >= 0) {
        close(g_timer_fd);
        g_timer_fd = -1;
    }
    if (g_buffer) {
        free(g_buffer);
        g_buffer = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    rmdir(DRIVER_PATH);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (mkdir(DRIVER_PATH, 0755) < 0 && errno != EEXIST) {
        perror("mkdir");
        return EXIT_FAILURE;
    }

    if (create_sysfs_file(LATEST_FILE) < 0 ||
        create_sysfs_file(SAMPLES_FILE) < 0 ||
        create_sysfs_file(RATE_FILE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_buf_size = BUFFER_SIZE;
    g_buffer = calloc(g_buf_size, sizeof(accel_sample_t));
    if (!g_buffer) {
        fprintf(stderr, "calloc: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &g_timer_fd;

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value = its.it_interval;

    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timer_fd) < 0) {
        fprintf(stderr, "timer_create: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (timer_settime(g_timer_fd, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_handler = timer_cb;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = 0;
    if (sigaction(SIGRTMIN, &sa_timer, NULL) < 0) {
        perror("sigaction(SIGRTMIN)");
        cleanup();
        return EXIT_FAILURE;
    }

    char rate_str[32];
    snprintf(rate_str, sizeof(rate_str), "%d", SAMPLE_RATE_HZ);
    write_sysfs(RATE_FILE, rate_str);

    printf("MPU6050 driver ready. Sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        struct pollfd pfd;
        pfd.fd = g_timer_fd;
        pfd.events = POLLIN;
        pfd.revents = 0;

        int pr = poll(&pfd, 1, 100);
        if (pr < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }
        if (pr > 0 && (pfd.revents & POLLIN)) {
            uint64_t expirations;
            ssize_t n = read(g_timer_fd, &expirations, sizeof(expirations));
            if (n < 0) {
                if (errno == EINTR) continue;
                perror("read timerfd");
                break;
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

