        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_buf_size = BUFFER_SIZE;
    g_buffer = calloc(g_buf_size, sizeof(accel_sample_t));
    if (!g_buffer) {
        fprintf(stderr, "calloc: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &g_timer_fd;

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 1000000000L / SAMPLE_RATE_HZ;
    its.it_value = its.it_interval;

    if (timer_create(CLOCK_MONOTONIC, &sev, &g_timer_fd) < 0) {
        fprintf(stderr, "timer_create: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (timer_settime(g_timer_fd, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_handler = timer_cb;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = 0;
    if (sigaction(SIGRTMIN, &sa_timer, NULL) < 0) {
        perror("sigaction(SIGRTMIN)");
        cleanup();
        return EXIT_FAILURE;
    }

    char rate_str[32];
    snprintf(rate_str, sizeof(rate_str), "%d", SAMPLE_RATE_HZ);
    write_sysfs(RATE_FILE, rate_str);

    printf("MPU6050 driver ready. Sampling at %d Hz. Press Ctrl+C to exit.\n", SAMPLE_RATE_HZ);

    while (g_running) {
        struct pollfd pfd;
        pfd.fd = g_timer_fd;
        pfd.events = POLLIN;
        pfd.revents = 0;

        int pr = poll(&pfd, 1, 100);
        if (pr < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }
        if (pr > 0 && (pfd.revents & POLLIN)) {
            uint64_t expirations;
            ssize_t n = read(g_timer_fd, &expirations, sizeof(expirations));
            if (n < 0) {
                if (errno == EINTR) continue;
                perror("read timerfd");
                break;
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

