#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define NUM_RELAYS 4

static const unsigned int relay_pins[NUM_RELAYS] = {
    RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN
};

static const long interval_seconds[NUM_RELAYS] = {
    2, 3, 5, 7
};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int all_relays_off(struct gpiod_line *lines[NUM_RELAYS]) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i] && gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Error turning off relay %d: %s\n", i + 1, strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "relay_toggle", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    struct timespec next_toggle[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        clock_gettime(CLOCK_MONOTONIC, &next_toggle[i]);
        next_toggle[i].tv_sec += interval_seconds[i];
    }

    int relay_state[NUM_RELAYS] = {0, 0, 0, 0};

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (now.tv_sec > next_toggle[i].tv_sec ||
                (now.tv_sec == next_toggle[i].tv_sec && now.tv_nsec >= next_toggle[i].tv_nsec)) {

                relay_state[i] = !relay_state[i];

                if (set_relay(lines[i], relay_state[i]) < 0) {
                    running = 0;
                    break;
                }

                next_toggle[i].tv_sec += interval_seconds[i];
                if (next_toggle[i].tv_nsec >= 1000000000L) {
                    next_toggle[i].tv_sec += 1;
                    next_toggle[i].tv_nsec -= 1000000000L;
                }
            }
        }

        if (running) {
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = 100000000; /* 100 ms */
            nanosleep(&sleep_time, NULL);
        }
    }

    all_relays_off(lines);

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

