#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define LOG_FILE "alarm_log.txt"
#define POLL_INTERVAL_US 100000
#define RELAY_ACTIVE_US 3000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started on GPIO%d. Relay on GPIO%d. Press Ctrl+C to exit.\n",
           SOUND_SENSOR_GPIO, RELAY_GPIO);

    while (running) {
        int sound_level = gpioRead(SOUND_SENSOR_GPIO);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SOUND_SENSOR_GPIO);
            break;
        }

        if (sound_level == 1) {
            printf("Sound detected! Activating relay for 3 seconds...\n");

            if (gpioWrite(RELAY_GPIO, 1) != 0) {
                fprintf(stderr, "Error activating relay\n");
                break;
            }

            if (log_timestamp(LOG_FILE) != 0) {
                fprintf(stderr, "Error logging timestamp\n");
            }

            gpioDelay(RELAY_ACTIVE_US);

            if (gpioWrite(RELAY_GPIO, 0) != 0) {
                fprintf(stderr, "Error deactivating relay\n");
                break;
            }

            printf("Relay deactivated.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

