#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_GYRO_XOUT_L  0x44
#define MPU6050_REG_GYRO_YOUT_H  0x45
#define MPU6050_REG_GYRO_YOUT_L  0x46
#define MPU6050_REG_GYRO_ZOUT_H  0x47
#define MPU6050_REG_GYRO_ZOUT_L  0x48

#define BUFFER_SIZE 100
#define THRESHOLD_DPS 50.0f

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, gyro_data_t *data) {
    int16_t x, y, z;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_XOUT_H, &x) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_YOUT_H, &y) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_ZOUT_H, &z) < 0) return -1;
    data->x = (float)x / 131.0f;
    data->y = (float)y / 131.0f;
    data->z = (float)z / 131.0f;
    return 0;
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
    if (buf->count == BUFFER_SIZE) buf->tail = (buf->tail + 1) % BUFFER_SIZE;
}

static void check_threshold(circular_buffer_t *buf, float threshold) {
    if (buf->count < 2) return;
    int idx = (buf->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    gyro_data_t latest = buf->data[idx];
    gyro_data_t prev = buf->data[buf->tail];
