        printf("Threshold exceeded! Magnitude: %.2f degrees/second\n", magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    circular_buffer_t gyro_buffer = {0};

    printf("MPU-6050 initialized. Reading gyro data... (Ctrl+C to exit)\n");

    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            usleep(100000);
            continue;
        }
        buffer_add(&gyro_buffer, gyro_data);
        check_threshold(&gyro_buffer, THRESHOLD_DPS);
        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
