/*
 * MH-Z19B CO2 Monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 (9600 baud, 8N1)
 * TXD:  GPIO14 (BCM), RXD: GPIO15 (BCM)
 *
 * Reads CO2 concentration every 5 seconds, logs JSON to co2_log.json
 * and error events to co2_error.log.
 *
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pthread.h>
#include <the_driver.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds */
#define RESPONSE_TIMEOUT 1000000    /* microseconds (1 second) */
#define MAX_RETRIES      3
#define READ_BUF_SIZE    256

/* MH-Z19B command to request a continuous measurement with read */
static const uint8_t CMD_READ_CO2[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timeval tv;
    struct tm tm_info;

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%06ld", (long)tv.tv_usec);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* UART initialization                                                 */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        log_error("open() failed for UART device");
        return -1;
    }

    /* Clear O_NONBLOCK for blocking reads with VTIME timeout */
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0 || fcntl(fd, F_SETFL, flags & ~O_NONBLOCK) < 0) {
        log_error("fcntl() failed to set blocking mode");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr() failed");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag  = 0;
    tty.c_lflag  = 0;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;   /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr() failed");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* MH-Z19B read with retry                                             */
/* ------------------------------------------------------------------ */
static int read_mhz19b(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    int retries = 0;

    while (total < len && retries < MAX_RETRIES) {
        fd_set rfds;
        struct timeval tv;

        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);
        tv.tv_sec  = 0;
        tv.tv_usec = 10000;  /* 10 ms poll interval */

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            log_error("select() failed");
            return -1;
        }
        if (rv == 0) {
            retries++;
            continue;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR || errno == EAGAIN) continue;
            log_error("read() failed");
            return -1;
        }
        if (n == 0) {
            retries++;
            continue;
        }

        total += (size_t)n;
    }

    if (total != len) {
        log_error("MH-Z19B read incomplete: got partial data");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CO2 logging                                                         */
/* ------------------------------------------------------------------ */
static void log_co2(int ppm, int error)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp) {
        fprintf(g_log_fp,
                "{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
                ts, ppm, error);
        fflush(g_log_fp);
    }
    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
           ts, ppm, error);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction() failed");
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        log_error("fopen() failed for log file");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        log_error("fopen() failed for error log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 Monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Send the 9-byte command */
        ssize_t w = write(g_uart_fd, CMD_READ_CO2, sizeof(CMD_READ_CO2));
        if (w < 0) {
            log_error("write() failed to send command");
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        if (w != (ssize_t)sizeof(CMD_READ_CO2)) {
            log_error("write() partial command");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Wait for the sensor to respond (100 ms timeout) */
        struct timeval tv_wait;
        tv_wait.tv_sec  = 0;
        tv_wait.tv_usec = 100000;
        select(g_uart_fd + 1, NULL, NULL, NULL, &tv_wait);

        /* Read the 9-byte response */
        uint8_t resp[9];
        if (read_mhz19b(g_uart_fd, resp, sizeof(resp)) != 0) {
            log_error("read_mhz19b() failed");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Validate checksum */
        uint8_t checksum = 0;
        for (int i = 1; i < 8; i++)
            checksum += resp[i];
        checksum = 0xFF - checksum + 1;

        if (checksum != resp[8]) {
            log_error("Checksum mismatch");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Parse ppm: bytes 2 and 3 (big-endian) */
        int ppm = (resp[2] << 8) | resp[3];
        log_co2(ppm, 0);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

