        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction() failed");
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        log_error("fopen() failed for log file");
        cleanup();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        log_error("fopen() failed for error log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 Monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Send the 9-byte command */
        ssize_t w = write(g_uart_fd, CMD_READ_CO2, sizeof(CMD_READ_CO2));
        if (w < 0) {
            log_error("write() failed to send command");
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        if (w != (ssize_t)sizeof(CMD_READ_CO2)) {
            log_error("write() partial command");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Wait for the sensor to respond (100 ms timeout) */
        struct timeval tv_wait;
        tv_wait.tv_sec  = 0;
        tv_wait.tv_usec = 100000;
        select(g_uart_fd + 1, NULL, NULL, NULL, &tv_wait);

        /* Read the 9-byte response */
        uint8_t resp[9];
        if (read_mhz19b(g_uart_fd, resp, sizeof(resp)) != 0) {
            log_error("read_mhz19b() failed");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Validate checksum */
        uint8_t checksum = 0;
        for (int i = 1; i < 8; i++)
            checksum += resp[i];
        checksum = 0xFF - checksum + 1;

        if (checksum != resp[8]) {
            log_error("Checksum mismatch");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Parse ppm: bytes 2 and 3 (big-endian) */
        int ppm = (resp[2] << 8) | resp[3];
        log_co2(ppm, 0);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

