#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define HMC5883L_ADDR  0x1E
#define GPIO_PIN       17
#define BUFFER_SIZE    100
#define SAMPLE_US      100000   /* 100 ms */
#define DEVIATION_THRESHOLD 10.0
#define TARGET_HEADING 90.0

/* HMC5883L registers */
#define REG_CONFIG_A   0x00
#define REG_CONFIG_B   0x01
#define REG_MODE       0x02
#define REG_DATA_X_MSB 0x03
#define REG_DATA_X_LSB 0x04
#define REG_DATA_Z_MSB 0x05
#define REG_DATA_Z_LSB 0x06
#define REG_DATA_Y_MSB 0x07
#define REG_DATA_Y_LSB 0x08

/* Configuration A: 8-average, 15 Hz, normal measurement */
#define CONFIG_A_VAL   0x70
/* Configuration B: Gain 1.3 Ga */
#define CONFIG_B_VAL   0x20
/* Mode: Continuous */
#define MODE_VAL       0x00

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(g_i2c_handle, REG_CONFIG_A, CONFIG_A_VAL) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, REG_CONFIG_B, CONFIG_B_VAL) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, REG_MODE, MODE_VAL) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(g_i2c_handle, REG_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y, int16_t z) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static float apply_hard_iron_compensation(float heading, int16_t x, int16_t y) {
    float x_comp = heading - (100.0f - (float)x);
    float y_comp = heading - (-50.0f - (float)y);
    float comp = (x_comp * x_comp) + (y_comp * y_comp);
    if (comp < 0) comp = 0;
    return sqrtf(comp);
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CircularBuffer heading_buffer = {0};

    while (g_running) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            float heading = calculate_heading(x, y, z);
            float comp = apply_hard_iron_compensation(heading, x, y);
            add_to_buffer(&heading_buffer, comp);

            int deviation = (int)fabsf(heading - TARGET_HEADING);
            if (deviation > DEVIATION_THRESHOLD) {
                gpioWrite(GPIO_PIN, 1);
            } else {
                gpioWrite(GPIO_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading magnetometer, retrying...\n");
        }
        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

