#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_PWR_ON  0x01
#define BH1750_CMD_RESET   0x07
#define BH1750_CMD_CONT_H  0x10
#define BH1750_CONV_MS    120

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define LUX_THRESHOLD_LOW   50
#define LUX_THRESHOLD_MID   150
#define LUX_THRESHOLD_HIGH  300

#define LOG_FILE "lighting_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_cmd(fd, BH1750_CMD_PWR_ON) < 0) return -1;
    if (i2c_write_cmd(fd, BH1750_CMD_RESET) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_cmd(fd, BH1750_CMD_CONT_H) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: %s\n", n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux, int r, int g, int b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %d, %d, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, r, g, b);
    fflush(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb_ctrl", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_ctrl", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor may be absent)\n");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying in 1 s...\n");
            sleep(1);
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (lux < LUX_THRESHOLD_LOW) {
            r = 1;
        } else if (lux < LUX_THRESHOLD_MID) {
            g = 1;
        } else if (lux < LUX_THRESHOLD_HIGH) {
            b = 1;
        } else {
            r = g = b = 1;
        }

        if (gpiod_line_set_value(red_line, r) < 0 ||
            gpiod_line_set_value(green_line, g) < 0 ||
            gpiod_line_set_value(blue_line, b) < 0) {
            fprintf(stderr, "Failed to set GPIO values: %s\n", strerror(errno));
        }

        log_data(log_fp, lux, r, g, b);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

