#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define DISTANCE_THRESHOLD 50
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_direction(int in1, int in2, int in3, int in4, int forward) {
    if (gpioWrite(in1, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in2, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in3, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in4, forward ? 1 : 0) < 0) return -1;
    return 0;
}

static int set_motor_pwm(int in2, int in4, int duty) {
    if (gpioPWM(in2, duty) < 0) return -1;
    if (gpioPWM(in4, duty) < 0) return -1;
    return 0;
}

static int stop_motor(int in1, int in2, int in3, int in4) {
    if (gpioWrite(in1, 0) < 0) return -1;
    if (gpioWrite(in2, 0) < 0) return -1;
    if (gpioWrite(in3, 0) < 0) return -1;
    if (gpioWrite(in4, 0) < 0) return -1;
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) return -1;

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) return -1;
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) return -1;

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) return -1;

    return 0;
}

static int calculate_pwm_duty(int distance) {
    if (distance < 0) distance = 0;
    if (distance > 100) distance = 100;

    int duty = (int)(((float)(100 - distance) / 100.0f) * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

