        if (motor_a_distance < DISTANCE_THRESHOLD) {
            if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 1) < 0) {
                fprintf(stderr, "Error setting motor A direction\n");
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_pwm(MOTOR_A_IN2, MOTOR_B_IN4, duty_a) < 0) {
                fprintf(stderr, "Error setting motor A PWM\n");
                exit_code = EXIT_FAILURE;
                break;
            }
        } else {
            if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 0) < 0) {
                fprintf(stderr, "Error setting motor A direction\n");
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_pwm(MOTOR_A_IN2, MOTOR_B_IN4, duty_a) < 0) {
                fprintf(stderr, "Error setting motor A PWM\n");
                exit_code = EXIT_FAILURE;
                break;
            }
        }

        if (motor_b_distance < DISTANCE_THRESHOLD) {
            if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 1) < 0) {
                fprintf(stderr, "Error setting motor B direction\n");
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_pwm(MOTOR_A_IN2, MOTOR_B_IN4, duty_b) < 0) {
                fprintf(stderr, "Error setting motor B PWM\n");
                exit_code = EXIT_FAILURE;
                break;
            }
        } else {
            if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 0) < 0) {
                fprintf(stderr, "Error setting motor B direction\n");
                exit_code = EXIT_FAILURE;
                break;
            }
            if (set_motor_pwm(MOTOR_A_IN2, MOTOR_B_IN4, duty_b) < 0) {
                fprintf(stderr, "Error setting motor B PWM\n");
                exit_code = EXIT_FAILURE;
                break;
            }
        }

        usleep(LOOP_DELAY_US);
    }

    if (stop_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4) < 0) {
        fprintf(stderr, "Error stopping motors\n");
        exit_code = EXIT_FAILURE;
    }

    gpioTerminate();
    return exit_code;
}

