    /* Start with coils de-energized */
    gpioWrite(IN1_PIN, 0);
    gpioWrite(IN2_PIN, 0);
    gpioWrite(IN3_PIN, 0);
    gpioWrite(IN4_PIN, 0);

    return 0;
}

/* ------------------------------------------------------------------ */
static void rotate_stepper(int steps, int direction)
{
    int phase = 0;
    for (int i = 0; i < steps && g_running; i++) {
        phase = (phase + direction) & 3;
        gpioWrite(IN1_PIN, step_sequence[phase][0]);
        gpioWrite(IN2_PIN, step_sequence[phase][1]);
        gpioWrite(IN3_PIN, step_sequence[phase][2]);
        gpioWrite(IN4_PIN, step_sequence[phase][3]);
        gpioDelay(STEP_DELAY_US);
    }
}

/* ------------------------------------------------------------------ */
static void lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    rotate_stepper(STEPS_PER_QUARTER_TURN, 1);
    printf("Door locked.\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    rotate_stepper(STEPS_PER_QUARTER_TURN, 0);
    printf("Door unlocked.\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door control system started. Press Ctrl+C to exit.\n");
    printf("  LOCK  button : GPIO24 (active-low)\n");
    printf("  UNLOCK button: GPIO23 (active-low)\n");
    fflush(stdout);

    bool lock_pressed    = false;
    bool unlock_pressed  = false;

    while (g_running) {
        int lock_state    = gpioRead(LOCK_PIN);
        int unlock_state  = gpioRead(UNLOCK_PIN);

        /* Active-low: 0 = pressed */
        if (lock_state == 0 && !lock_pressed) {
            lock_pressed = true;
            lock_door();
        } else if (lock_state == 1) {
            lock_pressed = false;
        }

        if (unlock_state == 0 && !unlock_pressed) {
            unlock_pressed = true;
            unlock_door();
        } else if (unlock_state == 1) {
            unlock_pressed = false;
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

