#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x1C
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_CYCLE_NS 1500000
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }
    return 0;
}

static int read_accel_data(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    if (i2c_read_reg16(fd, ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H + 2, ay) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_XOUT_H + 4, az) < 0) return -1;
    return 0;
}

static void calculate_pitch_roll(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    *pitch = atan2((float)ax, sqrt((float)ay * ay + (float)az * az)) * 180.0 / M_PI;
    *roll = atan2((float)ay, sqrt((float)ax * ax + (float)az * az)) * 180.0 / M_PI;
}

static int set_servo_angle(int angle) {
    char path[64];
    char buf[32];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        return -1;
    }
    int duty_ns = (int)(((float)angle / 180.0) * PWM_PERIOD_NS);
    if (duty_ns < 0) duty_ns = 0;
    if (duty_ns > PWM_PERIOD_NS) duty_ns = PWM_PERIOD_NS;
    snprintf(buf, sizeof(buf), "%d", duty_ns);
    if (write(fd, buf, strlen(buf)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int log_data(FILE *fp, float pitch, float roll, int angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                pitch, roll, angle) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

static int i2c_open_with_retry(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

int main(void) {
    int16_t ax, ay, az;
    float pitch, roll;
    int angle;
    int retries;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    i2c_fd = i2c_open_with_retry(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    retries = 0;
    while (init_mpu6050(i2c_fd) < 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "MPU6050 init failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize MPU6050 after %d retries.\n", MAX_RETRIES);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    while (running) {
        if (read_accel_data(i2c_fd, &ax, &ay, &az) == 0) {
            calculate_pitch_roll(ax, ay, az, &pitch, &roll);
            angle = (int)pitch;
            if (set_servo_angle(angle) == 0) {
                if (log_data(log_file, pitch, roll, angle) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }
            } else {
                fprintf(stderr, "Failed to set servo angle.\n");
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }
        usleep(100000);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    return 0;
}

