        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &schedule[count].hour,
                   &schedule[count].minute,
                   &schedule[count].second,
                   &schedule[count].relay_number,
                   &schedule[count].on_off) == 5) {
            if (schedule[count].relay_number < 1 || schedule[count].relay_number > NUM_RELAYS) {
                fprintf(stderr, "Invalid relay number in schedule: %d\n", schedule[count].relay_number);
                fclose(fp);
                return -1;
            }
            if (schedule[count].on_off != 0 && schedule[count].on_off != 1) {
                fprintf(stderr, "Invalid on/off value in schedule: %d\n", schedule[count].on_off);
                fclose(fp);
                return -1;
            }
            count++;
        } else {
            fprintf(stderr, "Invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return count;
}

static int calculate_time_difference(time_t now, time_t scheduled_time) {
    struct tm *now_tm = localtime(&now);
    struct tm *sched_tm = localtime(&scheduled_time);
    if (!now_tm || !sched_tm) return 0;

    int diff = (now_tm->tm_hour - sched_tm->tm_hour) * 3600 +
               (now_tm->tm_min - sched_tm->tm_min) * 60 +
               (now_tm->tm_sec - sched_tm->tm_sec);

    if (diff < 0) diff += 86400;
    return diff;
}

static int perform_fade(int relay_pin, int target_state) {
    if (fade_active) return 0;

    int current = current_state[relay_pin - 4];
    if (current == target_state) return 1;

    int diff = target_state ? 1 : -1;
    int step_size = (PWM_RANGE * FADE_DURATION) / 100;
    int elapsed = 0;

    fade_active = 1;

    while (elapsed < FADE_DURATION && program_running) {
        int duty = (elapsed / step_size) * diff;
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        if (gpioPWM(relay_pin, duty) < 0) {
            fprintf(stderr, "PWM write failed on pin %d\n", relay_pin);
            fade_active = 0;
            return 0;
        }

        gpioDelay(10000);
        elapsed++;
    }

    if (gpioPWM(relay_pin, target_state ? PWM_RANGE : 0) < 0) {
        fprintf(stderr, "PWM write failed on pin %d\n", relay_pin);
        fade_active = 0;
        return 0;
    }

    current_state[relay_pin - 4] = target_state;
    fade_active = 0;
    return 1;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", relay_pins[i]);
            cleanup();
            return 1;
        }
        if (gpioPWM(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", relay_pins[i]);
            cleanup();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handlers");
        cleanup();
        return 1;
    }

    schedule_entry_t schedule[100];
    int schedule_count = read_schedule(SCHEDULE_FILE, schedule, 100);
    if (schedule_count <= 0) {
        fprintf(stderr, "Failed to read schedule file\n");
        cleanup();
        return 1;
    }

    time_t last_check = time(NULL);

    while (program_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time() failed");
            break;
        }

        if (difftime(now, last_check) >= 1.0) {
            last_check = now;

            for (int i = 0; i < schedule_count; i++) {
                int diff = calculate_time_difference(now,
                    mktime(&(struct tm){
                        .tm_year = now - (now % 86400) + schedule[i].second,
                        .tm_mon = 0, .tm_mday = 1,
                        .tm_hour = schedule[i].hour,
                        .tm_min = schedule[i].minute,
                        .tm_sec = schedule[i].second,
                        .tm_isdst = -1
                    }));

                if (diff == 0) {
                    if (schedule[i].on_off != current_state[schedule[i].relay_number - 1]) {
                        if (!perform_fade(relay_pins[schedule[i].relay_number - 1], schedule[i].on_off)) {
                            fprintf(stderr, "Fade failed for relay %d\n", schedule[i].relay_number);
                        }
                    }
                } else if (diff < 0) {
                    diff += 86400;
                }

                if (diff < 60 && diff > 0) {
                    int relay_pin = relay_pins[schedule[i].relay_number - 1];
                    if (schedule[i].on_off && !current_state[schedule[i].relay_number - 1]) {
                        if (!perform_fade(relay_pin, 1)) {
                            fprintf(stderr, "Fade failed for relay %d\n", schedule[i].relay_number);
                        }
                    } else if (!schedule[i].on_off && current_state[schedule[i].relay_number - 1]) {
                        if (!perform_fade(relay_pin, 0)) {
                            fprintf(stderr, "Fade failed for relay %d\n", schedule[i].relay_number);
                        }
                    }
                }
            }
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

