/*
 * Rudimentary theremin for Raspberry Pi Zero W
 *
 * HC-SR04:
 *   Trigger  -> GPIO23 (BCM)
 *   Echo     -> GPIO24 (BCM)
 * Buzzer:
 *   PWM output -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_FREQUENCY    200   /* Hz */
#define MAX_FREQUENCY    2000  /* Hz */
#define MIN_DISTANCE     2.0   /* cm */
#define MAX_DISTANCE     400.0 /* cm */

#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    20000 /* 50 Hz */
#define MEASURE_GAP_US   60000 /* 60 ms between measurements */
#define ECHO_TIMEOUT_US  38000 /* 38 ms max round-trip for 400 cm */
#define SENSOR_TIMEOUT_US 100000 /* 100 ms between successful reads */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm on success, or -1.0 on error.
 */
static float get_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (stuck high?)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    /* Speed of sound 343 m/s => 0.0343 cm/µs; round-trip / 2 */
    return (float)diff * 0.0343f / 2.0f;
}

/*
 * Map distance to PWM frequency.
 * Returns frequency in Hz, or -1 if the distance is invalid.
 */
static int map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }

    /* Linear mapping: closer -> higher frequency */
    float freq = MIN_FREQUENCY +
                 (distance - MIN_DISTANCE) *
                 (MAX_FREQUENCY - MIN_FREQUENCY) /
                 (MAX_DISTANCE - MIN_DISTANCE);

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    return (int)freq;
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency < 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Warning: gpioSetPWMfrequency(%d) failed\n", frequency);
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) { /* 50% duty cycle */
        fprintf(stderr, "Warning: gpioPWM(%d) failed\n", frequency);
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Main loop */
    while (g_running) {
        float distance = get_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance read failed, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        if (frequency < 0) {
            fprintf(stderr, "Warning: distance %.2f cm out of range, skipping\n",
                    distance);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        set_buzzer_frequency(frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    set_buzzer_frequency(0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

