#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN, r) < 0)   return -1;
    if (gpioPWM(GREEN_PIN, g) < 0) return -1;
    if (gpioPWM(BLUE_PIN, b) < 0)  return -1;
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0)   return -1;
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0)  return -1;

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0)   return -1;
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) return -1;
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0)  return -1;

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0)   return -1;
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) return -1;
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0)  return -1;

    return 0;
}

static void cleanup(void) {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    while (running) {
        double t = time_time();
        double proximity = 0.5 * (1.0 + sin(2.0 * M_PI * 0.1 * t));

        int r = (int)(proximity * 255.0);
        int g = (int)((1.0 - proximity) * 255.0);
        int b = 0;

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Error: Failed to set LED color.\n");
            break;
        }

        time_sleep(0.01);
    }

    cleanup();
    return EXIT_SUCCESS;
}

