#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18

#define DEBOUNCE_US 50000
#define PWM_DUTY 50000

typedef struct {
    int frequency;
    int duration_ms;
} Note;

static const Note melody[] = {
    {262, 500}, {0, 100}, {330, 500}, {0, 100}, {392, 500}, {0, 100}, {523, 500}, {0, 100}
};
static const int melody_length = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile sig_atomic_t melody_playing = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 0) {
        if (!melody_playing) {
            button_pressed = 1;
        }
    }
}

static int play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) {
        gpioDelay(duration_ms * 1000);
        return 0;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for %d Hz\n", frequency);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM start failed\n");
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM stop failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, DEBOUNCE_US, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell program started. Press the button (GPIO17) to play the melody.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            if (!melody_playing) {
                melody_playing = 1;
                printf("Playing melody...\n");
                for (int i = 0; i < melody_length && running; i++) {
                    if (play_tone(melody[i].frequency, melody[i].duration_ms) < 0) {
                        fprintf(stderr, "Error during melody playback\n");
                        break;
                    }
                }
                melody_playing = 0;
            } else {
                printf("Stopping melody...\n");
                gpioPWM(BUZZER_PIN, 0);
                melody_playing = 0;
            }
        }
        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

