/*
 * Earthquake detection using an SW-420 vibration sensor module.
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   SW-420 VCC  -> 3.3 V (pin 1)
 *   SW-420 GND  -> GND   (pin 9)
 *   SW-420 D0   -> GPIO17 (pin 11, BCM 17)
 *
 * The module's digital output is active-high; a HIGH level indicates
 * vibration above the module's threshold.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vib_detect vib_detect.c -lpigpio -lrt
 * Run:    ./vib_detect [poll_timeout_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define WINDOW_SIZE       5
#define EARTHQUAKE_COUNT  3
#define LOG_FILE          "vibration_events.log"
#define DEFAULT_TIMEOUT   1000   /* ms */
#define POLL_TIMEOUT_US   1000000 /* 1 s (pigpio gpioRead) */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int value)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_local) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, GPIO%d, %d\n", ts, GPIO_PIN, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Earthquake detection                                                */
/* ------------------------------------------------------------------ */
static void check_earthquake(const int window[], int count)
{
    int high_count = 0;
    for (int i = 0; i < count; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= EARTHQUAKE_COUNT) {
        time_t now = time(NULL);
        if (now != (time_t)-1) {
            struct tm tm_local;
            if (localtime_r(&now, &tm_local) != NULL) {
                char ts[32];
                if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_local) > 0) {
                    printf("EARTHQUAKE ALERT at %s\n", ts);
                    fflush(stdout);
                }
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int timeout_ms = DEFAULT_TIMEOUT;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout '%s'; using default %d ms\n",
                    argv[1], DEFAULT_TIMEOUT);
            timeout_ms = DEFAULT_TIMEOUT;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the line is deterministic when the
     * sensor module is disconnected or its output is idle. */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    if (install_signal_handlers() != 0) {
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sliding window ---- */
    int window[WINDOW_SIZE];
    for (int i = 0; i < WINDOW_SIZE; i++) {
        window[i] = 0;
    }
    int idx = 0;

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_PIN);
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed: %s\n",
                    GPIO_PIN, pigpio_error(level));
            gpioDelay(100000); /* 100 ms back-off */
            continue;
        }

        log_event(level);

        /* Slide the window: push out the oldest sample and append the newest. */
        window[idx] = level;
        idx = (idx + 1) % WINDOW_SIZE;

        check_earthquake(window, WINDOW_SIZE);

        /* gpioDelay is a busy-wait; use usleep for the timeout. */
        usleep((useconds_t)timeout_ms * 1000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    fflush(stdout);

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose log failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

