/*
 * LSM303DLHC magnetometer reader with hard-iron calibration.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    /dev/i2c-1  (physical pins 3 = SDA, 5 = SCL)
 * Address: 0x1E (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_log mag_log.c
 *
 * Hard-iron calibration offsets (user-adjusted):
 *   X_OFFSET = 10
 *   Y_OFFSET = -5
 *   Z_OFFSET = 20
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC magnetometer register addresses ---- */
#define LSM303_MAG_ADDR        0x1E
#define LSM303_MAG_CRA_REG_M   0x00
#define LSM303_MAG_MR_REG_M    0x02
#define LSM303_MAG_OUT_X_H_M   0x03
#define LSM303_MAG_OUT_X_L_M   0x04
#define LSM303_MAG_OUT_Z_H_M   0x05
#define LSM303_MAG_OUT_Z_L_M   0x06
#define LSM303_MAG_OUT_Y_H_M   0x07
#define LSM303_MAG_OUT_Y_L_M   0x08

/* CRA: temp enable | ODR 10 Hz | 1.3 Gauss full-scale */
#define LSM303_MAG_CRA_VAL     0x1C
/* MR: continuous-conversion mode */
#define LSM303_MAG_MR_VAL      0x00

/* ---- Calibration offsets (user-adjusted) ---- */
#define X_OFFSET  10
#define Y_OFFSET  -5
#define Z_OFFSET  20

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, sizeof(reg));
    if (n != (ssize_t)sizeof(reg)) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, val, sizeof(*val));
    if (n != (ssize_t)sizeof(*val)) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_magnetometer(int fd)
{
    if (i2c_write_reg8(fd, LSM303_MAG_CRA_REG_M, LSM303_MAG_CRA_VAL) == -1)
        return -1;
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, LSM303_MAG_MR_VAL) == -1)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xh, xl, zh, zl, yh, yl;

    if (i2c_read_reg8(fd, LSM303_MAG_OUT_X_H_M, &xh) == -1) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_X_L_M, &xl) == -1) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Z_H_M, &zh) == -1) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Z_L_M, &zl) == -1) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Y_H_M, &yh) == -1) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Y_L_M, &yl) == -1) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *z = (int16_t)((zh << 8) | zl);
    *y = (int16_t)((yh << 8) | yl);
    return 0;
}

/* ------------------------------------------------------------------ */
static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           int16_t *cal_x, int16_t *cal_y, int16_t *cal_z)
{
    *cal_x = (int16_t)(raw_x - X_OFFSET);
    *cal_y = (int16_t)(raw_y - Y_OFFSET);
    *cal_z = (int16_t)(raw_z - Z_OFFSET);
}

/* ------------------------------------------------------------------ */
static double calculate_heading(int16_t cal_x, int16_t cal_y)
{
    double heading = atan2((double)cal_y, (double)cal_x) * 180.0 / M_PI;
    if (heading < 0.0)
        heading += 360.0;
    return heading;
}

static const char *determine_direction(double heading)
{
    if (heading >= 337.5 || heading < 22.5)  return "N";
    if (heading < 67.5)                      return "NE";
    if (heading < 112.5)                     return "E";
    if (heading < 157.5)                     return "SE";
    if (heading < 202.5)                     return "S";
    if (heading < 247.5)                     return "SW";
    if (heading < 292.5)                     return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t cal_x, int16_t cal_y,
                    int16_t cal_z, double heading)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%.2f\n", ts, cal_x, cal_y, cal_z, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    const char *log_file = "mag_log.csv";

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "open(%s) failed: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_magnetometer(g_i2c_fd) == -1) {
        fprintf(stderr, "Failed to initialize magnetometer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append); write header if empty */
    int file_exists = (access(log_file, F_OK) == 0);
    g_log_fp = fopen(log_file, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", log_file, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        if (fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,"
                           "Calibrated Z,Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        int16_t cal_x, cal_y, cal_z;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) == -1) {
            fprintf(stderr, "Skipping sample due to I2C read failure.\n");
            sleep(1);
            continue;
        }

        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        double heading = calculate_heading(cal_x, cal_y);
        const char *direction = determine_direction(heading);

        if (log_data(g_log_fp, cal_x, cal_y, cal_z, heading) == -1) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Heading: %s (%.2f degrees)\n", direction, heading);
        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

