    if (heading < 0.0)
        heading += 360.0;
    return heading;
}

static const char *determine_direction(double heading)
{
    if (heading >= 337.5 || heading < 22.5)  return "N";
    if (heading < 67.5)                      return "NE";
    if (heading < 112.5)                     return "E";
    if (heading < 157.5)                     return "SE";
    if (heading < 202.5)                     return "S";
    if (heading < 247.5)                     return "SW";
    if (heading < 292.5)                     return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t cal_x, int16_t cal_y,
                    int16_t cal_z, double heading)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%.2f\n", ts, cal_x, cal_y, cal_z, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd != -1) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    const char *log_file = "mag_log.csv";

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "open(%s) failed: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_magnetometer(g_i2c_fd) == -1) {
        fprintf(stderr, "Failed to initialize magnetometer.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append); write header if empty */
    int file_exists = (access(log_file, F_OK) == 0);
    g_log_fp = fopen(log_file, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", log_file, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        if (fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,"
                           "Calibrated Z,Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        int16_t cal_x, cal_y, cal_z;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) == -1) {
            fprintf(stderr, "Skipping sample due to I2C read failure.\n");
            sleep(1);
            continue;
        }

        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        double heading = calculate_heading(cal_x, cal_y);
        const char *direction = determine_direction(heading);

        if (log_data(g_log_fp, cal_x, cal_y, cal_z, heading) == -1) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Heading: %s (%.2f degrees)\n", direction, heading);
        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

