/*
 * TTP223 capacitive touch sensor → relay toggle on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TTP223 OUT  → GPIO4  (BCM)
 *   TTP223 VCC  → 3.3 V
 *   TTP223 GND  → GND
 *   Relay IN    → GPIO17 (BCM)
 *   Relay VCC   → 5 V
 *   Relay GND   → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c -lpigpio -lrt
 * Run:    sudo ./relay_toggle
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEBOUNCE_MS    200
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_state(const char *filename, int relay_state)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen(log_file)");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp,
            "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
            ts,
            relay_state ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("fclose(log_file)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */

static int set_relay(int state)
{
    int rc = gpioWrite(RELAY_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN=%d, %d) failed: %s\n",
                RELAY_PIN, state, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* TTP223 interrupt callback                                           */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_last_tick = 0;

static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) {            /* only act on rising edge */
        return;
    }

    /* pigpio tick wraps every ~72 minutes (32-bit microseconds). */
    uint32_t elapsed = tick - g_last_tick;
    g_last_tick = tick;

    if (elapsed < DEBOUNCE_MS * 1000) {
        return;                 /* within debounce window → ignore */
    }

    int relay_state = !gpioRead(RELAY_PIN);
    if (set_relay(relay_state) != 0) {
        return;
    }

    if (log_state(LOG_FILE, relay_state) != 0) {
        fprintf(stderr, "Warning: failed to log state change.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Initialization                                                      */
/* ------------------------------------------------------------------ */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_PIN=%d, PI_INPUT) failed\n", TOUCH_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN=%d, PI_OUTPUT) failed\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_PIN=%d, PI_PUD_DOWN) failed\n",
                TOUCH_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN=%d, 0) failed\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx(TOUCH_PIN=%d) failed\n", TOUCH_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Force relay OFF before terminating pigpio. */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to force relay OFF during cleanup.\n");
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO%d to toggle GPIO%d.\n",
           TOUCH_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        sleep(1);
    }

    printf("\nShutting down...\n");

    /* Log the final OFF state. */
    if (log_state(LOG_FILE, 0) != 0) {
        fprintf(stderr, "Warning: failed to log final OFF state.\n");
    }

    cleanup();
    return EXIT_SUCCESS;
}

