/*
 * Smart Irrigation System — Raspberry Pi Zero W
 *
 * Relays (active-low, 5 V):
 *   GPIO17
 *   GPIO23
 *   GPIO24
 *   GPIO25
 *
 * Behaviour:
 *   - Every 10 s a simulated moisture value (0–100) is generated.
 *   - If the value is below 30, each relay is driven LOW for 5 s,
 *     with a 1 s gap between relays, and an entry appended to
 *     irrigation_log.txt with an ISO-8601 timestamp.
 *   - SIGINT / SIGTERM: relays deactivated, GPIO released, file closed, exit.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 *   (pigpio daemon must be running or pigpio_init must be passed
 *   PIGPIO_INIT_MANUAL flag for daemonless operation.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN      17
#define RELAY2_PIN      23
#define RELAY3_PIN      24
#define RELAY4_PIN      25

#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME_US  5000000   /* 5 s  */
#define RELAY_GAP_US      1000000   /* 1 s  */
#define LOOP_DELAY_US     10000000  /* 10 s */

static const int relay_pins[4] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * Drive a relay (active-low) LOW for duration_us, then HIGH.
 * Returns 0 on success, -1 on write failure.
 */
static int activate_relay(int pin, unsigned duration_us)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "gpioWrite(pin=%d, 0) failed\n", pin);
        return -1;
    }

    gpioDelay(duration_us);

    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "gpioWrite(pin=%d, 1) failed\n", pin);
        return -1;
    }
    return 0;
}

/*
 * Deactivate all relays (drive HIGH).
 */
static void deactivate_all_relays(void)
{
    for (int i = 0; i < 4; i++)
        gpioWrite(relay_pins[i], 1);
}

/*
 * Request each relay pin as an output and drive it HIGH (inactive).
 * Returns 0 on success, -1 on failure.
 */
static int initialize_gpio(void)
{
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode(pin=%d, OUTPUT) failed\n", relay_pins[i]);
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "gpioWrite(pin=%d, 1) initial failed\n", relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_irrigation_event(int relay_number, int moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s - Relay %d activated. Moisture level: %d\n",
                timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }

    if (fflush(g_log_file) != 0)
        fprintf(stderr, "fflush on log file failed\n");
}

/* ------------------------------------------------------------------ */
/* Simulated moisture reading                                          */
/* ------------------------------------------------------------------ */
static int generate_moisture_level(void)
{
    return rand() % 101;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_SUCCESS;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("irrigation_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(irrigation_log.txt)");
        deactivate_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int moisture_level = generate_moisture_level();

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level %d below threshold %d. Irrigating...\n",
                   moisture_level, MOISTURE_THRESHOLD);

            for (int i = 0; i < 4 && g_running; i++) {
                printf("Activating relay %d (GPIO %d)...\n", i + 1, relay_pins[i]);
                if (activate_relay(relay_pins[i], RELAY_ON_TIME_US) != 0) {
                    fprintf(stderr, "Failed to activate relay %d\n", i + 1);
                    rc = EXIT_FAILURE;
                    break;
                }
                log_irrigation_event(i + 1, moisture_level);

                if (i < 3 && g_running)
                    gpioDelay(RELAY_GAP_US);
            }
        } else {
            printf("Moisture level %d above threshold %d. No irrigation.\n",
                   moisture_level, MOISTURE_THRESHOLD);
        }

        if (g_running)
            gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    deactivate_all_relays();

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0)
            perror("fclose(log file)");
        g_log_file = NULL;
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return rc;
}

