/*
 * Automated plant watering system for Raspberry Pi Zero W
 * Uses the pigpio library to control two SG90 servos:
 *   GPIO17 (BCM) -> Valve servo (opens/closes valve)
 *   GPIO18 (BCM) -> Nozzle servo (sprays water)
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PIN      17
#define NOZZLE_PIN     18

#define VALVE_OPEN_US  1500   /* 90 degrees  */
#define VALVE_CLOSE_US 500    /* 0 degrees   */

#define NOZZLE_0_US    500    /* 0 degrees   */
#define NOZZLE_45_US   1000   /* 45 degrees  */
#define NOZZLE_90_US   1500   /* 90 degrees  */
#define NOZZLE_135_US  2000   /* 135 degrees */
#define NOZZLE_180_US  2500   /* 180 degrees */

#define MOISTURE_THRESHOLD 50
#define WATERING_DURATION  5   /* seconds */
#define CYCLE_DELAY        5   /* seconds */
#define RETRY_COUNT        3
#define RETRY_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — only pigpio API calls here, no GPIO calls         */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helper: set servo to a given pulse width with retries              */
/* ------------------------------------------------------------------ */
static int set_servo_pulse(int pin, int pulse_us, int max_retries)
{
    for (int attempt = 0; attempt < max_retries; ++attempt) {
        int rc = servo(pin, pulse_us);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "Warning: servo(pin=%d, pulse=%d) failed (rc=%d), attempt %d/%d\n",
                pin, pulse_us, rc, attempt + 1, max_retries);
        if (attempt < max_retries - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Helper: stop a servo (pulse width 0)                               */
/* ------------------------------------------------------------------ */
static int stop_servo(int pin)
{
    return set_servo_pulse(pin, 0, 1);
}

/* ------------------------------------------------------------------ */
/* Watering sequence: open valve, sweep nozzle, close valve           */
/* ------------------------------------------------------------------ */
static int water_plant(void)
{
    printf("Watering plant...\n");
    fflush(stdout);

    /* Open valve */
    if (set_servo_pulse(VALVE_PIN, VALVE_OPEN_US, RETRY_COUNT) != 0) {
        fprintf(stderr, "Error: failed to open valve after %d retries.\n",
                RETRY_COUNT);
        return -1;
    }
    printf("Valve opened.\n");
    fflush(stdout);

    /* Sweep nozzle through five positions */
    const int angles[] = {0, 45, 90, 135, 180};
    const int n = (int)(sizeof(angles) / sizeof(angles[0]));

    for (int i = 0; i < n && g_running; ++i) {
        int pulse = 0;
        switch (angles[i]) {
            case 0:   pulse = NOZZLE_0_US;   break;
            case 45:  pulse = NOZZLE_45_US;  break;
            case 90:  pulse = NOZZLE_90_US;  break;
            case 135: pulse = NOZZLE_135_US; break;
            case 180: pulse = NOZZLE_180_US; break;
            default:
                fprintf(stderr, "Warning: invalid angle %d, skipping.\n",
                        angles[i]);
                continue;
        }

        if (set_servo_pulse(NOZZLE_PIN, pulse, RETRY_COUNT) != 0) {
            fprintf(stderr,
                    "Warning: failed to set nozzle to %d degrees "
                    "(pulse %d us).\n", angles[i], pulse);
            continue;
        }

        printf("Nozzle at %d degrees.\n", angles[i]);
        fflush(stdout);

        /* Spend WATERING_DURATION seconds at this position */
        for (int s = 0; s < WATERING_DURATION && g_running; ++s)
            gpioDelay(1000000);  /* 1 s */
    }

    /* Close valve */
    if (set_servo_pulse(VALVE_PIN, VALVE_CLOSE_US, RETRY_COUNT) != 0) {
        fprintf(stderr,
                "Critical: failed to close valve after %d retries.\n",
                RETRY_COUNT);
        return -1;
    }
    printf("Valve closed.\n");
    fflush(stdout);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Simulated moisture reading (cycles 20, 40, 60, 80, 100)            */
/* ------------------------------------------------------------------ */
static int read_moisture(void)
{
    static const int levels[] = {20, 40, 60, 80, 100};
    static int idx = 0;
    return levels[idx++ % (int)(sizeof(levels) / sizeof(levels[0]))];
}

/* ------------------------------------------------------------------ */
/* Cleanup — stop servos and terminate pigpio                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop both servos first */
    stop_servo(VALVE_PIN);
    stop_servo(NOZZLE_PIN);

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int moisture = read_moisture();
        printf("Moisture level: %d\n", moisture);
        fflush(stdout);

        if (moisture < MOISTURE_THRESHOLD) {
            if (water_plant() != 0) {
                fprintf(stderr, "Error: watering cycle failed.\n");
                break;
            }
        } else {
            printf("Moisture above threshold (%d). Skipping watering.\n",
                   moisture);
            fflush(stdout);
        }

        /* Wait before next cycle (interruptible) */
        for (int s = 0; s < CYCLE_DELAY && g_running; ++s)
            gpioDelay(1000000);  /* 1 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

