/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC -> Pi 3.3V (Pin 1)
 *   MPU-6050 GND -> Pi GND  (Pin 9)
 *   MPU-6050 SCL -> Pi GPIO3 / SCL (Pin 5)
 *   MPU-6050 SDA -> Pi GPIO2 / SDA (Pin 3)
 *
 * I2C Bus: /dev/i2c-1
 * I2C Address: 0x68 (AD0 tied to GND)
 *
 * Build: gcc -O2 -Wall -o gyro_logger gyro_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

/* MPU-6050 Registers */
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_YOUT_H    0x45
#define GYRO_ZOUT_H    0x47

#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_HZ      10
#define SAMPLE_DELAY_US (1000000 / SAMPLE_HZ)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine(uint8_t high, uint8_t low)
{
    return (int16_t)((uint16_t)high << 8 | (uint16_t)low);
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) != 0)
        return -1;

    *x = combine(buf[0], buf[1]);
    *y = combine(buf[2], buf[3]);
    *z = combine(buf[4], buf[5]);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Wake up the MPU-6050 (clear SLEEP bit in PWR_MGMT_1) */
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "MPU-6050 not responding at address 0x%02X\n", MPU6050_ADDR);
        goto cleanup;
    }

    /* Allow time for the sensor to stabilize after waking */
    usleep(100000);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging MPU-6050 gyroscope data to %s at %d Hz. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_HZ);

    while (g_running) {
        int16_t x, y, z;

        if (read_gyro_data(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading gyroscope data. Continuing...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(fp, x, y, z) != 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL)
        fclose(fp);
    if (fd >= 0)
        close(fd);
    return rc;
}

