/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi 4 (64-bit, Bookworm).
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM), 5 V
 *   HC-SR04 ECHO -> GPIO18 (BCM), 5 V (via voltage divider to 3.3 V)
 *   HC-SR04 VCC  -> 5 V, GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_log distance_log.c -lpigpio -lrt
 * Run:
 *   sudo ./distance_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define SPEED_OF_SOUND   34300.0          /* cm/s at 20 °C */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000            /* 50 ms */
#define SAMPLE_INTERVAL_US 1000000       /* 1 s */
#define MEASURE_DELAY_US 60000           /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Wait for the echo line to reach the requested level, or timeout.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_for_level(int pin, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(pin) != level) {
        if (!g_running)
            return -1;
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/*
 * Measure the distance in cm. Returns >= 0 on success, -1 on error.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
