/*
 * VL53L1X distance sensor reader with relay control on Raspberry Pi 4.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   VL53L1X SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Relay IN   -> GPIO18 (BCM, pin 12)
 *   Relay VCC  -> 5 V (or 3.3 V if relay is 3.3 V logic)
 *   Relay GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_relay vl53l1x_relay.c \
 *       -lgpiod -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x29
#define RELAY_PIN        18
#define DISTANCE_THRESHOLD 50   /* cm */
#define POLL_DELAY_MS    100

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET       0x0000
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_RESULT_RANGE_VAL 0x0014
#define VL53L1X_REG_RESULT_INT_STAT  0x0015
#define VL53L1X_REG_RESULT_INT_CLEAR 0x0016

#define VL53L1X_SOFT_RESET_VAL       0x00
#define VL53L1X_MODE_START_RANGING   0x00
#define VL53L1X_MODE_STOP_RANGING    0x01
#define VL53L1X_INT_CLEAR_MASK       0x01

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 byte of data. */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then read `len` bytes. */
static int i2c_read_reg(int fd, uint16_t reg, uint8_t *data, size_t len)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_read_reg read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd)
{
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VAL) < 0)
        return -1;
    usleep(10000); /* 10 ms settle after reset */

    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE, VL53L1X_MODE_START_RANGING) < 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t int_status = 0;
    uint8_t range_val = 0;

    /* Check if a new measurement is ready */
    if (i2c_read_reg(fd, VL53L1X_REG_RESULT_INT_STAT, &int_status, 1) < 0)
        return -1;

    if ((int_status & 0x01) == 0)
        return 1; /* no new data yet */

    /* Read the 16-bit range value */
    if (i2c_read_reg(fd, VL53L1X_REG_RESULT_RANGE_VAL, &range_val, 1) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal */
    if (i2c_write_reg8(fd, VL53L1X_REG_RESULT_INT_CLEAR, VL53L1X_INT_CLEAR_MASK) < 0)
        return -1;

    *distance_mm = (uint16_t)range_val;
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", VL53L1X_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor may be absent or bus error)\n");
        goto cleanup;
    }

    /* Open GPIO chip and get relay line */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "vl53l1x_relay", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("VL53L1X distance sensor ready. Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_DELAY_MS);

    /* Main loop */
    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(i2c_fd, &distance_mm);

        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            printf("Distance: %d cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD) {
                if (gpiod_line_set_value(relay_line, 1) < 0)
                    fprintf(stderr, "Failed to set relay HIGH: %s\n", strerror(errno));
            } else {
                if (gpiod_line_set_value(relay_line, 0) < 0)
                    fprintf(stderr, "Failed to set relay LOW: %s\n", strerror(errno));
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance (I2C bus error or sensor absent)\n");
        }
        /* rc == 1 means no new data yet; just wait */

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);

    return ret;
}

