        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            printf("Distance: %d cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD) {
                if (gpiod_line_set_value(relay_line, 1) < 0)
                    fprintf(stderr, "Failed to set relay HIGH: %s\n", strerror(errno));
            } else {
                if (gpiod_line_set_value(relay_line, 0) < 0)
                    fprintf(stderr, "Failed to set relay LOW: %s\n", strerror(errno));
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance (I2C bus error or sensor absent)\n");
        }
        /* rc == 1 means no new data yet; just wait */

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);

    return ret;
}

