#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_PWR_MGMT_2   0x6C
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_GYRO_XOUT_L  0x44
#define MPU6050_REG_GYRO_YOUT_H  0x45
#define MPU6050_REG_GYRO_YOUT_L  0x46
#define MPU6050_REG_GYRO_ZOUT_H  0x47
#define MPU6050_REG_GYRO_ZOUT_L  0x48

/* Scaling factor for gyroscope data (±250°/s range) */
#define GYRO_SCALE 131.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ret = read(fd, value, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive registers */
static int i2c_read_reg16(int fd, uint8_t reg_high, int16_t *out)
{
    uint8_t buf[2];
    ssize_t ret = write(fd, &reg_high, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_high, strerror(errno));
        return -1;
    }
    ret = read(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg_high, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int mpu6050_init(int fd)
{
    /* Wake up the device (clear SLEEP bit in PWR_MGMT_1) */
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Disable sleep mode (set PWR_MGMT_2 = 0x00) */
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_2, 0x00) < 0)
        return -1;

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, MPU6050_REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF config = 0 (gyro bandwidth 8 kHz, delay 0 ms) */
    if (i2c_write_reg8(fd, MPU6050_REG_CONFIG, 0x00) < 0)
        return -1;

    /* Gyro full-scale range = ±250 °/s (FS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6050_REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_XOUT_H, &raw_x) < 0)
        return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_YOUT_H, &raw_y) < 0)
        return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_ZOUT_H, &raw_z) < 0)
        return -1;

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(/dev/i2c-1)");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try reading WHO_AM_I (0x75) to confirm device presence */
    uint8_t whoami = 0;
    if (i2c_read_reg8(g_i2c_fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "MPU-6050 not detected on /dev/i2c-1 at address 0x%02X\n",
                MPU6050_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68\n", whoami);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Logging angular velocity (deg/s)...\n");
    fflush(stdout);

    while (g_running) {
        float x, y, z;

        if (read_gyro_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data; continuing...\n");
            usleep(100000);
            continue;
        }

        printf("X: %+.2f deg/s, Y: %+.2f deg/s, Z: %+.2f deg/s\n", x, y, z);
        fflush(stdout);

        usleep(100000); /* 100 ms → ~10 Hz */
    }

    printf("\nExiting cleanly.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

