/*
 * Automated plant watering system — Raspberry Pi 4 Model B
 * Four 5 V relay modules on BCM GPIO17,18,27,22 (physical pins 11,12,13,15).
 * Active-low: LOW = relay energised (water ON), HIGH = relay de-energised (water OFF).
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS    4
#define RELAY_ON_TIME 5          /* seconds per relay */
#define CYCLE_PERIOD  86400      /* seconds between full cycles (24 h) */
#define POLL_INTERVAL 60         /* seconds between relay activations */
#define LOG_FILE      "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_start_time(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s\n", ts) < 0)
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
static void sleep_seconds(unsigned int seconds)
{
    while (seconds > 0 && g_running) {
        unsigned int remaining = (seconds > 60) ? 60 : seconds;
        sleep(remaining);
        seconds -= remaining;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int line_acquired = 0;
    int rc = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try lookup by label */
        chip = gpiod_chip_open_by_label("pinctrl-bcm2835");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire relay lines as outputs --------------------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering-system", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        line_acquired = 1;
    }

    /* ---- Main loop: one full cycle every 24 h --------------------- */
    while (g_running) {
        log_start_time();

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
            sleep_seconds(RELAY_ON_TIME);
            if (g_running) {
                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    fprintf(stderr, "Failed to set GPIO %u HIGH: %s\n",
                            relay_pins[i], strerror(errno));
                    goto cleanup;
                }
            }
            sleep_seconds(POLL_INTERVAL);
        }

        /* Sleep until next cycle or signal */
        while (g_running && (CYCLE_PERIOD - POLL_INTERVAL * NUM_RELAYS) > 0)
            sleep_seconds(CYCLE_PERIOD - POLL_INTERVAL * NUM_RELAYS);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (line_acquired) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (lines[i])
                gpiod_line_set_value(lines[i], 1);   /* HIGH = off */
        }
    }
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

