#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define STEP_DELAY 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_relay_intensity(int pin, int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > PWM_RANGE) intensity = PWM_RANGE;
    gpioPWM(pin, intensity);
}

static void sunrise_sequence(void) {
    log_event("Starting sunrise sequence");

    for (int i = 0; i <= SUNRISE_DURATION && running; i++) {
        float intensity = (float)i / SUNRISE_DURATION * PWM_RANGE;
        set_relay_intensity(RELAY1_PIN, (int)intensity);
        set_relay_intensity(RELAY2_PIN, (int)intensity);
        set_relay_intensity(RELAY3_PIN, (int)intensity);
        set_relay_intensity(RELAY4_PIN, (int)intensity);

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Sunrise step %d, Intensity: %.2f", i, intensity);
        log_event(log_message);

        sleep(STEP_DELAY);
    }

    log_event("Sunrise sequence complete");
}

static void cleanup(void) {
    log_event("Cleaning up and exiting");
    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    log_file = fopen("smart_lighting.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("Smart lighting system started");

    sunrise_sequence();

    if (running) {
        log_event("Sunrise sequence interrupted by signal");
    }

    cleanup();
    return EXIT_SUCCESS;
}

