#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_GYRO_XOUT_L  0x44
#define MPU6050_REG_GYRO_YOUT_H  0x45
#define MPU6050_REG_GYRO_YOUT_L  0x46
#define MPU6050_REG_GYRO_ZOUT_H  0x47
#define MPU6050_REG_GYRO_ZOUT_L  0x48

/* LED GPIO pin (BCM 17) */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Angular velocity threshold (degrees/second) */
#define ANGULAR_VELOCITY_THRESHOLD 250.0f

/* Sampling period (microseconds) */
#define SAMPLE_PERIOD_US 50000

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Maximum consecutive I2C read failures before exiting */
#define MAX_READ_FAILURES 3

/* Structure to hold gyroscope data */
typedef struct {
    struct timespec timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* I2C handle */
static int i2c_handle = -1;

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
static void store_gyro_data(int16_t x, int16_t y, int16_t z);
static void check_threshold(int16_t x, int16_t y, int16_t z);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize MPU-6050 */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (write PWR_MGMT_1 failed)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settling time */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz internal sample rate) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data from MPU-6050 */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data block\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Store gyroscope data in circular buffer */
static void store_gyro_data(int16_t x, int16_t y, int16_t z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the angular velocity threshold */
static void check_threshold(int16_t x, int16_t y, int16_t z) {
    float x_dps = (float)x / 131.0f;
    float y_dps = (float)y / 131.0f;
    float z_dps = (float)z / 131.0f;

    if (fabsf(x_dps) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(y_dps) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(z_dps) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    int16_t x, y, z;
    int consecutive_failures = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at address 0x%02X\n", I2C_BUS, MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            consecutive_failures = 0;
            store_gyro_data(x, y, z);
            check_threshold(x, y, z);
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: I2C read failure %d/%d\n", consecutive_failures, MAX_READ_FAILURES);

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max consecutive I2C read failures reached. Exiting.\n");
                break;
            }

            /* Attempt to re-initialize MPU-6050 */
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: MPU-6050 re-initialisation failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");

    return EXIT_SUCCESS;
}

