#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_GPIO_OFFSET  8          /* BCM GPIO8 = physical pin 24 */
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_PERIOD_US 10000   /* 10 ms */
#define MAX_RETRIES     3

/* MPU-9250 register addresses (Bank 0) */
#define REG_SMPLRT_DIV   0x19
#define REG_GYRO_CONFIG  0x1B
#define REG_PWR_MGMT_1   0x6B
#define REG_GYRO_XOUT_H  0x43
#define REG_GYRO_XOUT_L  0x44
#define REG_GYRO_YOUT_H  0x45
#define REG_GYRO_YOUT_L  0x46
#define REG_GYRO_ZOUT_H  0x47
#define REG_GYRO_ZOUT_L  0x48

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static FILE *g_log_fp  = NULL;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_chip *g_chip   = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t tx[2] = { reg & 0x7F, val };
    uint8_t rx[2] = { 0 };
    return spi_transfer(fd, tx, rx, 2);
}

static int mpu_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    uint8_t tx[2] = { reg | 0x80, 0x00 };
    uint8_t rx[2] = { 0 };
    if (spi_transfer(fd, tx, rx, 2) < 0)
        return -1;
    *val = rx[1];
    return 0;
}

static int mpu_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t tx[len + 1];
    uint8_t rx[len + 1];
    tx[0] = reg | 0x80;
    memset(&tx[1], 0, len);
    if (spi_transfer(fd, tx, rx, len + 1) < 0)
        return -1;
    memcpy(buf, &rx[1], len);
    return 0;
}

static int mpu_init(int fd)
{
    if (mpu_write_reg(fd, REG_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (mpu_write_reg(fd, REG_SMPLRT_DIV, 0x07) < 0) return -1;
    if (mpu_write_reg(fd, REG_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (mpu_read_burst(fd, REG_GYRO_XOUT_H, buf, 6) == 0) {
            int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
            int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);
            *x = (float)rx / 32768.0f;
            *y = (float)ry / 32768.0f;
            *z = (float)rz / 32768.0f;
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[40];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s.%09ldZ,%.6f,%.6f,%.6f\n", tbuf, ts.tv_nsec, x, y, z);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
    if (g_cs_line) { gpiod_line_release(g_cs_line); g_cs_line = NULL; }
    if (g_chip)   { gpiod_chip_close(g_chip); g_chip = NULL; }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    g_cs_line = gpiod_chip_get_line(g_chip, CS_GPIO_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", CS_GPIO_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (mpu_init(g_spi_fd) < 0) {
        fprintf(stderr, "MPU-9250 init failed\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (g_running) {
        float x, y, z;
        if (read_gyro(g_spi_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Gyro read failed after %d retries\n", MAX_RETRIES);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

