#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 Registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   3900000  /* 3.9 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* GPIO Configuration */
#define LED_PIN 17

/* Threshold for angular velocity (degrees/second) */
#define VELOCITY_THRESHOLD 200.0f

/* Circular buffer size */
#define BUFFER_SIZE 64

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Global variables */
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int spi_read_register(int handle, uint8_t reg, uint8_t *data, uint8_t len);
static int spi_write_register(int handle, uint8_t reg, uint8_t data);
static int init_mpu6050(int handle);
static int read_gyro_data(int handle, gyro_data_t *data);
static void add_to_buffer(gyro_data_t data);
static void check_threshold(gyro_data_t data);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Reads a single register from the MPU-6050 via SPI.
 * Returns 0 on success, -1 on failure.
 */
static int spi_read_register(int handle, uint8_t reg, uint8_t *data, uint8_t len) {
    char tx_buf[1 + 1];
    char rx_buf[1 + 1];

    tx_buf[0] = reg | 0x80; /* MSB = 1 for read */
    tx_buf[1] = 0x00;       /* Dummy byte to clock out data */

    if (spiXfer(handle, tx_buf, rx_buf, len + 1) != (len + 1)) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    for (int i = 0; i < len; i++) {
        data[i] = (uint8_t)rx_buf[i + 1];
    }

    return 0;
}

/*
 * Writes a single register to the MPU-6050 via SPI.
 * Returns 0 on success, -1 on failure.
 */
static int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; /* MSB = 0 for write */
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

/*
 * Initializes the MPU-6050.
 * Returns 0 on success, -1 on failure.
 */
static int init_mpu6050(int handle) {
    uint8_t who_am_i = 0;

    /* Verify device identity */
