#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_PWR_MGMT_2   0x6C

/* Sensitivity scale factor for default ±2g range */
#define ACCEL_SCALE 16384.0f

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 21

/* Threshold for tilt detection (degrees) */
#define TILT_THRESHOLD 45.0f

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int  mpu6050_init(void);
static int  mpu6050_read_accel(float *roll, float *pitch);
static void log_tilt_data(float roll, float pitch);
static void control_led(float roll, float pitch);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize the MPU-6050 */
static int mpu6050_init(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (write PWR_MGMT_1 failed)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set sample rate divider to 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    /* Configure gyroscope: ±250 °/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope\n");
        return -1;
    }

    /* Configure accelerometer: ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer data and compute roll and pitch */
static int mpu6050_read_accel(float *roll, float *pitch) {
    char buf[6];

    /* Read 6 bytes starting at ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* Convert raw values to g-force units */
    float x = (float)raw_x / ACCEL_SCALE;
    float y = (float)raw_y / ACCEL_SCALE;
    float z = (float)raw_z / ACCEL_SCALE;

    /* Compute roll and pitch using the accelerometer data */
    *roll  = atan2f(y, z) * 180.0f / M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / M_PI;

    return 0;
}

/* Log tilt data to a file */
static void log_tilt_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for appending\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Control the LED based on tilt thresholds */
static void control_led(float roll, float pitch) {
    bool tilted = (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD);
    gpioWrite(LED_PIN, tilted ? 1 : 0);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float roll, pitch;

    /* Main loop */
    while (program_running) {
        if (mpu6050_read_accel(&roll, &pitch) == 0) {
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
            log_tilt_data(roll, pitch);
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, retrying...\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Graceful cleanup */
    cleanup();
    return EXIT_SUCCESS;
}

