#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LED        17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE       "biometric_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000
#define SAMPLE_DELAY_US 100000

/* Si1145 register addresses (8-bit, not 16-bit as documented) */
#define SI1145_REG_ALS_VIS_DATA0  0x22
#define SI1145_REG_PS1_DATA0      0x18
#define SI1145_REG_COMMAND        0x18
#define SI1145_CMD_RESET          0x01
#define SI1145_CMD_PS_FORCE       0x05
#define SI1145_CMD_ALS_FORCE      0x06
#define SI1145_CMD_PSALS_FORCE    0x07

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_lo, als_hi, ps_lo, ps_hi;

    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0)
        return -1;
    usleep(10000);

    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &als_lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &als_hi) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_PS1_DATA0, &ps_lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_PS1_DATA0 + 1, &ps_hi) < 0) return -1;

    *ambient_light = ((uint16_t)als_hi << 8) | als_lo;
    *proximity     = ((uint16_t)ps_hi  << 8) | ps_lo;
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    uint16_t ambient_light, proximity;
    int retries;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "si1145_presence", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1145 biometric sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        retries = 0;
        do {
            if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
                log_data(log_fp, ambient_light, proximity);

                if (proximity > PROXIMITY_THRESHOLD) {
                    gpiod_line_set_value(led_line, 1);
                } else {
                    gpiod_line_set_value(led_line, 0);
                }
                break;
            }
            retries++;
            usleep(RETRY_DELAY_US);
        } while (retries < MAX_RETRIES && running);

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

