#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 register addresses (8-bit, OR 0x80 for read) */
#define ADXRS290_REG_XGYRO_OUT 0x00
#define ADXRS290_REG_YGYRO_OUT 0x02
#define ADXRS290_REG_TEMP_OUT  0x04
#define ADXRS290_REG_DIAG_STAT 0x06
#define ADXRS290_REG_GYRO_ID   0x08

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

#define SAMPLE_DELAY_US 10000  /* 10 ms → ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_fp        = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one register from the ADXRS290 (8-bit addressing)              */
/* Returns 0 on success (value stored in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int adxrs290_read_reg(uint8_t reg, int16_t *out)
{
    char tx[3] = { (char)(reg | 0x80), 0x00, 0x00 };
    char rx[3] = { 0, 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "[ERROR] SPI transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    /* ADXRS290 returns data in the low byte of the second transfer word */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXRS290 SPI interface                               */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int adxrs290_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed: %s\n", pigpio_error(g_spi_handle));
        return -1;
    }

    /* Verify device identity */
    int16_t id = 0;
    if (adxrs290_read_reg(ADXRS290_REG_GYRO_ID, &id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read GYRO_ID — sensor absent or bus error\n");
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        return -1;
    }

    /* ADXRS290 GYRO_ID register returns the part number (0x02) */
    if ((id & 0xFF) != 0x02) {
        fprintf(stderr, "[ERROR] Unexpected GYRO_ID 0x%04X (expected 0x02)\n", id);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        return -1;
    }

    printf("[INFO] ADXRS290 initialised (GYRO_ID = 0x%04X)\n", id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — close SPI and file resources                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_fp != NULL) {
        fflush(g_fp);
        fclose(g_fp);
        g_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open CSV file --- */
    g_fp = fopen("gyro_data.csv", "w");
    if (g_fp == NULL) {
        perror("[FATAL] fopen gyro_data.csv");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_fp, "timestamp_s,x_rate_raw,y_rate_raw\n");

    /* --- Install signal handler --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction SIGINT");
    }

    /* --- Initialise SPI --- */
    if (adxrs290_init() != 0) {
        fprintf(stderr, "[FATAL] ADXRS290 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[INFO] Sampling ADXRS290 at ~100 Hz (Ctrl-C to stop)\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t x_raw = 0, y_raw = 0;
        bool ok = true;

        if (adxrs290_read_reg(ADXRS290_REG_XGYRO_OUT, &x_raw) != 0) {
            fprintf(stderr, "[WARN] X-axis read failed\n");
            ok = false;
        }
        if (adxrs290_read_reg(ADXRS290_REG_YGYRO_OUT, &y_raw) != 0) {
            fprintf(stderr, "[WARN] Y-axis read failed\n");
            ok = false;
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Re-initialising SPI...\n");
            spiClose(g_spi_handle);
            g_spi_handle = -1;

            int attempts = 0;
            while (g_running && attempts < MAX_REINIT_ATTEMPTS) {
                attempts++;
                if (adxrs290_init() == 0) {
                    break;
                }
                fprintf(stderr, "[WARN] Re-init attempt %d/%d failed\n",
                        attempts, MAX_REINIT_ATTEMPTS);
                gpioDelay(100000); /* 100 ms back-off */
            }

            if (g_spi_handle < 0) {
                fprintf(stderr, "[FATAL] SPI re-initialisation failed after %d attempts — exiting\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
            continue;
        }

        /* Timestamp with microsecond precision */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("[WARN] clock_gettime");
            ts.tv_sec  = time(NULL);
            ts.tv_nsec = 0;
        }

        fprintf(g_fp, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                x_raw, y_raw);
        fflush(g_fp);

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

