#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17

#define ALERT_DURATION_MS 2000
#define ALERT_THRESHOLD_MS 500

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        log_event("ERROR: Failed to set alert pin HIGH");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        log_event("ERROR: Failed to set alert pin LOW");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static uint32_t s1_start = 0, s2_start = 0;
    static int s1_active = 0, s2_active = 0;

    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            s1_start = gpioTick();
            s1_active = 1;
        } else if (level == 0 && s1_active) {
            uint32_t elapsed = gpioTick() - s1_start;
            if (s2_active && (elapsed >= ALERT_THRESHOLD_MS * 1000)) {
                trigger_alert();
                log_event("Seismic event detected!");
            }
            s1_active = 0;
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            s2_start = gpioTick();
            s2_active = 1;
        } else if (level == 0 && s2_active) {
            uint32_t elapsed = gpioTick() - s2_start;
            if (s1_active && (elapsed >= ALERT_THRESHOLD_MS * 1000)) {
                trigger_alert();
                log_event("Seismic event detected!");
