        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) < 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register alert callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Seismic monitoring started");
    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    log_event("Seismic monitoring stopped");
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

