    uint8_t rx_buf[2] = {0};

    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        return -1;
    }
    *value = rx_buf[1];
    return 0;
}

static int gyro_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2] = { (uint8_t)(reg | GYRO_WRITE_BIT), value };
    uint8_t rx_buf[2] = {0};

    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int gyro_init(void) {
    if (gyro_write_register(GYRO_REG_POWER_MGMT, GYRO_POWER_MGMT_NORMAL) != 0) {
        fprintf(stderr, "Failed to set power management register\n");
        return -1;
    }
    return 0;
}

static int gyro_read_rate(double *rate) {
    uint8_t reg = GYRO_REG_RATE_X;
    uint8_t tx_buf[3] = { (uint8_t)(reg | GYRO_READ_BIT), 0x00, 0x00 };
    uint8_t rx_buf[3] = {0};

    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        return -1;
    }

    int16_t raw_rate = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    *rate = (double)raw_rate * GYRO_SENSITIVITY;
    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

static void buffer_add(circular_buffer_t *cb, gyro_data_t data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

static void check_threshold(double rate) {
    static bool led_on = false;

    if (rate > THRESHOLD && !led_on) {
        gpioWrite(LED_GPIO, 1);
        led_on = true;
        printf("Threshold exceeded! Rate: %.2f deg/s\n", rate);
    } else if (rate <= THRESHOLD && led_on) {
        gpioWrite(LED_GPIO, 0);
        led_on = false;
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gyro_init() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return 1;
    }

    buffer_init(&gyro_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        double rate;
        if (gyro_read_rate(&rate) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            gyro_data_t data = { .timestamp = ts, .rate = rate };
            buffer_add(&gyro_buffer, data);
            check_threshold(rate);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

