/*
 * Smart Sunset Simulator — Raspberry Pi Zero W
 *
 * Fades three dimmable lamps (BCM GPIO17, GPIO18, GPIO27) sequentially
 * from full brightness to off over a user-defined duration (1–3600 s).
 *
 * Hardware PWM is used at 100 Hz, 0–255 duty cycle range.
 * No software PWM is employed.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset sunset.c -lpigpio -lrt
 * Run:    sudo ./sunset <duration_seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP_PIN_1 17
#define LAMP_PIN_2 18
#define LAMP_PIN_3 27

#define PWM_FREQUENCY 100   /* Hz — hardware PWM clock */
#define PWM_RANGE     255   /* duty-cycle granularity */
#define FADE_STEP_US  10000 /* 10 ms per 100 Hz step */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Turn off all three lamps and release pigpio resources.              */
static void cleanup(void)
{
    gpioPWM(LAMP_PIN_1, 0);
    gpioPWM(LAMP_PIN_2, 0);
    gpioPWM(LAMP_PIN_3, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Fade a single lamp from full brightness to off over duration_sec.   */
static void fade_lamp(int pin, int duration_sec)
{
    int steps = (duration_sec * 10);  /* 10 ms per step */
    if (steps <= 0) steps = 1;

    for (int i = 0; i <= PWM_RANGE && g_running; i++) {
        if (gpioPWM(pin, i) < 0) {
            fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
            return;
        }
        if (i % (PWM_RANGE / 10) == 0)
            printf("Lamp on BCM %d: %d%% brightness\n", pin, i * 10);

        /*
         * Sleep in small chunks so signals are caught promptly.
         * 10 ms × steps ≈ duration_sec seconds.
         */
        for (int s = 0; s < steps && g_running; s++)
            usleep(FADE_STEP_US);
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "  duration_seconds: 1–3600\n");
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: duration must be 1–3600 seconds.\n");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- configure PWM on each lamp pin ---- */
    int pins[] = { LAMP_PIN_1, LAMP_PIN_2, LAMP_PIN_3 };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "gpioSetPWMrange failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        /* Start at full brightness */
        if (gpioPWM(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Initial gpioPWM failed on pin %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Smart Sunset Simulator — %d seconds\n", duration);
    printf("Lamps: BCM %d, BCM %d, BCM %d\n",
           LAMP_PIN_1, LAMP_PIN_2, LAMP_PIN_3);
    printf("PWM frequency: %d Hz, duty range: 0–%d\n",
           PWM_FREQUENCY, PWM_RANGE);
    printf("Fading each lamp sequentially...\n\n");

    /* ---- main fade loop ---- */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]) && g_running; i++) {
        printf("Fading lamp on BCM %d...\n", pins[i]);
        fade_lamp(pins[i], duration);
        if (!g_running) break;
    }

    /* ---- graceful shutdown ---- */
    if (g_running)
        printf("\nSimulation complete.\n");
    else
        printf("\nSimulation interrupted by signal.\n");

    cleanup();
    return EXIT_SUCCESS;
}

