        fprintf(stderr, "Error: failed to write ALL_OFF_PIN\n");
        return -1;
    }
    return 0;
}

static int set_light(int pin, int on)
{
    int level = on ? 0 : 1; /* active-low relay */
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: failed to write pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int all_lights_off(void)
{
    int pins[] = {RED_LIGHT_PIN, YELLOW_LIGHT_PIN, GREEN_LIGHT_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (set_light(pins[i], 0) < 0)
            return -1;
    }
    return set_all_off();
}

static int cycle_lights(void)
{
    if (all_lights_off() < 0)
        return -1;

    printf("Red light ON\n");
    fflush(stdout);
    if (set_light(RED_LIGHT_PIN, 1) < 0)
        return -1;

    for (int i = 0; i < 10 && g_running; ++i)
        sleep(1);
    if (!g_running)
