        return 0;

    printf("Yellow light ON\n");
    fflush(stdout);
    if (set_light(YELLOW_LIGHT_PIN, 1) < 0)
        return -1;

    for (int i = 0; i < 3 && g_running; ++i)
        sleep(1);
    if (!g_running)
        return 0;

    return all_lights_off();
}

