#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLL_INTERVAL_US 10000
#define LOG_FILE "touch_relay.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_error(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_init(int handle) {
    if (i2cWriteByteData(handle, MPR121_ECR, 0x00) < 0) {
        log_error("Failed to stop MPR121 during init.");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_CONFIG1, 0x10) < 0) {
        log_error("Failed to write MPR121 CONFIG1.");
        return -1;
    }
    if (i2cWriteByteData(handle, MPR121_CONFIG2, 0x20) < 0) {
        log_error("Failed to write MPR121 CONFIG2.");
        return -1;
    }
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(handle, 0x41 + 2 * i, 0x30) < 0) {
            log_error("Failed to write MPR121 filter data.");
            return -1;
        }
        if (i2cWriteByteData(handle, 0x42 + 2 * i, 0x10) < 0) {
            log_error("Failed to write MPR121 filter data.");
            return -1;
        }
    }
    if (i2cWriteByteData(handle, MPR121_ECR, 0x8F) < 0) {
        log_error("Failed to start MPR121 with 12 electrodes.");
        return -1;
    }
    return 0;
}

