        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, Solenoid1: GPIO%d, Solenoid2: GPIO%d, Duration: %d ms\n",
            timestamp, pin1, pin2, duration_ms);
    fclose(fp);
    return 0;
}

static int dispense(int pin1, int pin2, int duration_ms) {
    int half_ms = duration_ms / 2;

    if (gpioWrite(pin1, 1) < 0) {
        fprintf(stderr, "Error activating solenoid 1 (GPIO%d)\n", pin1);
        return -1;
    }
    if (gpioWrite(pin2, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 2 (GPIO%d)\n", pin2);
        gpioWrite(pin1, 0);
        return -1;
    }

    if (gpioDelay(half_ms * 1000) < 0) {
        fprintf(stderr, "Error during first half delay\n");
        gpioWrite(pin1, 0);
        gpioWrite(pin2, 0);
        return -1;
    }

    if (gpioWrite(pin1, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 1 (GPIO%d)\n", pin1);
        gpioWrite(pin2, 0);
        return -1;
    }
    if (gpioWrite(pin2, 1) < 0) {
        fprintf(stderr, "Error activating solenoid 2 (GPIO%d)\n", pin2);
        gpioWrite(pin1, 0);
        gpioWrite(pin2, 0);
        return -1;
    }

    if (gpioDelay((duration_ms - half_ms) * 1000) < 0) {
        fprintf(stderr, "Error during second half delay\n");
        gpioWrite(pin1, 0);
        gpioWrite(pin2, 0);
        return -1;
    }

    if (gpioWrite(pin1, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 1 (GPIO%d)\n", pin1);
        gpioWrite(pin2, 0);
        return -1;
    }
    if (gpioWrite(pin2, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 2 (GPIO%d)\n", pin2);
        gpioWrite(pin2, 0);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO%d to LOW\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO%d to LOW\n", SOLENOID_2_PIN);
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Dispense failed, exiting.\n");
            break;
        }

        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Logging failed, continuing.\n");
        }

        if (running) {
            gpioDelay(DISPENSE_INTERVAL_MS * 1000);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    printf("Dispensing system stopped.\n");
    return EXIT_SUCCESS;
}

