#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD  17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE   24
#define MOTOR_B_ENABLE   25

#define OBSTACLE_THRESHOLD 20.0
#define LOG_FILE_NAME      "balance_log.txt"
#define PWM_RANGE          255
#define LOOP_DELAY_US      50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int forward_pin, int backward_pin, int enable_pin, int speed) {
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    if (speed >  PWM_RANGE) speed =  PWM_RANGE;

    if (speed > 0) {
        if (gpioWrite(forward_pin, 1) < 0) return -1;
        if (gpioWrite(backward_pin, 0) < 0) return -1;
        if (gpioPWM(enable_pin, speed) < 0) return -1;
    } else if (speed < 0) {
        if (gpioWrite(forward_pin, 0) < 0) return -1;
        if (gpioWrite(backward_pin, 1) < 0) return -1;
        if (gpioPWM(enable_pin, -speed) < 0) return -1;
    } else {
        if (gpioWrite(forward_pin, 0) < 0) return -1;
        if (gpioWrite(backward_pin, 0) < 0) return -1;
        if (gpioPWM(enable_pin, 0) < 0) return -1;
    }
    return 0;
}

static int stop_motors(void) {
    int rc = 0;
    if (gpioWrite(MOTOR_A_FORWARD, 0) < 0) rc = -1;
    if (gpioWrite(MOTOR_A_BACKWARD, 0) < 0) rc = -1;
    if (gpioWrite(MOTOR_B_FORWARD, 0) < 0) rc = -1;
    if (gpioWrite(MOTOR_B_BACKWARD, 0) < 0) rc = -1;
    if (gpioPWM(MOTOR_A_ENABLE, 0) < 0) rc = -1;
    if (gpioPWM(MOTOR_B_ENABLE, 0) < 0) rc = -1;
    return rc;
}

static int log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) return -1;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
                timestamp, tilt_error, distance, motor_a_speed, motor_b_speed) < 0) {
        return -1;
    }
    fflush(log_file);
    return 0;
}

static float simulate_tilt_error(void) {
    return ((float)rand() / (float)RAND_MAX) * 20.0f - 10.0f;
}

static float simulate_distance(void) {
    return ((float)rand() / (float)RAND_MAX) * 380.0f + 20.0f;
}

int main(void) {
    int rc = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_A_ENABLE, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    if (fprintf(log_file, "# timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n") < 0) {
        fprintf(stderr, "Error: cannot write header to log file\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    fflush(log_file);

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (running) {
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        int motor_a_speed = (int)(100.0f * (1.0f + tilt_error / 10.0f));
        int motor_b_speed = (int)(100.0f * (1.0f - tilt_error / 10.0f));

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -128;
            motor_b_speed = -128;
        }

        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

        if (set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_A_ENABLE, motor_a_speed) < 0) {
            fprintf(stderr, "Error: failed to set Motor A speed\n");
            rc = 1;
            break;
        }
        if (set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_B_ENABLE, motor_b_speed) < 0) {
            fprintf(stderr, "Error: failed to set Motor B speed\n");
            rc = 1;
            break;
        }

        if (log_data(tilt_error, distance, motor_a_speed, motor_b_speed) < 0) {
            fprintf(stderr, "Error: failed to log data\n");
            rc = 1;
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    if (stop_motors() < 0) {
        fprintf(stderr, "Warning: failed to stop motors on exit\n");
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    if (rc == 0) {
        printf("Program terminated gracefully.\n");
    }
    return rc;
}

