#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed. "
                        "Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with pull-down (TTP223 output is open-drain) */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF (relay inactive) */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch sensor : GPIO%d (active-HIGH, pull-down)\n", TOUCH_SENSOR_PIN);
    printf("  Relay        : GPIO%d (active-HIGH)\n", RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int last_touch_state = 0;

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge (touch) with debounce */
        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            int confirm = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d during debounce.\n",
                        TOUCH_SENSOR_PIN);
                break;
            }

            if (confirm == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO%d.\n", RELAY_PIN);
                    break;
                }
                printf("Touch detected — relay %s\n", relay_state ? "ON" : "OFF");
            }
        }

        last_touch_state = touch_state;
        gpioDelay(1000);  /* 1 ms poll interval */
    }

    /* Cleanup: ensure relay is OFF and release pigpio resources */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

