/*
 * mood_light_audio.c — Raspberry Pi 3 Model B+
 *
 * Captures 16-bit stereo audio via ALSA (default device, 8000 Hz, 1024 frames),
 * computes the RMS amplitude of each buffer, and maps it non-linearly to
 * a common-cathode RGB LED on GPIO17 (R), GPIO18 (G), GPIO27 (B) using
 * software PWM via the pigpio library.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light_audio mood_light_audio.c \
 *       -lpigpio -lasound -lm
 *
 * Run:
 *   sudo ./mood_light_audio [sensitivity_scale]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define RED_PIN        17
#define GREEN_PIN      18
#define BLUE_PIN       27

#define SAMPLE_RATE    8000
#define PERIOD_FRAMES  1024
#define PERIOD_MS      10
#define PWM_RANGE      255

#define DEFAULT_SENSITIVITY 1.0

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

#ifdef ALSA_AVAILABLE
static snd_pcm_t *g_handle = NULL;
#endif

/* --------------------------- Signal Handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------ ALSA Helpers ----------------------------- */

#ifdef ALSA_AVAILABLE

static int alsa_open_device(void)
{
    int err;

    err = snd_pcm_open(&g_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(g_handle,
                                          snd_pcm_hw_params_alloca(&err),
                                          &rate, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n",
                snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: requested %d Hz, got %u Hz\n",
                SAMPLE_RATE, rate);
    }

    snd_pcm_hw_params_t *params = snd_pcm_hw_params_alloca(&err);
    err = snd_pcm_hw_params_any(g_handle, params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_access(g_handle, params,
                                       SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n",
                snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_format(g_handle, params,
                                       SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n",
                snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }

    unsigned int channels = 2;
    err = snd_pcm_hw_params_set_channels(g_handle, params, channels);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n",
                snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_period_size_near(g_handle, params,
                                                 &PERIOD_FRAMES, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n",
                snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params(g_handle, params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
        return -1;
    }

    err = snd_pcm_prepare(g_handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        snd_pcm_close(g_handle);
        g_handle = NULL;
