    return 0;
}

static int alsa_read_audio(short *buffer, int frames)
{
    int err = snd_pcm_readi(g_handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun (EPIPE)\n");
        if ((err = snd_pcm_prepare(g_handle)) < 0) {
            fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    }
    if (err == -ESTRPIPE) {
        fprintf(stderr, "ALSA suspended (ESTRPIPE)\n");
        if ((err = snd_pcm_resume(g_handle)) < 0) {
            fprintf(stderr, "snd_pcm_resume failed: %s\n", snd_strerror(err));
            return -1;
        }
        return 0;
    }
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    if (err != frames) {
        fprintf(stderr, "Short read: got %d frames, expected %d\n",
                err, frames);
        return -1;
    }
    return 0;
}

static void alsa_close_device(void)
{
    if (g_handle != NULL) {
        snd_pcm_drain(g_handle);
        snd_pcm_close(g_handle);
        g_handle = NULL;
    }
}

#endif /* ALSA_AVAILABLE */

/* ------------------------------ PWM Helpers ------------------------------ */

static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN,   r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN,  b);
}

static void map_amplitude_to_color(double amplitude, double sensitivity,
                                   int *r, int *g, int *b)
{
    /*
     * Non-linear mapping:
     *   amplitude ≈ 0  → (0, 0, 0)   (silence)
     *   amplitude ≈ 1  → (255, 0, 0) (full red)
     *   amplitude ≈ √2 → (0, 255, 0) (full green)
     *   amplitude ≈ 1  → (0, 0, 255) (full blue)
     *
     * Sensitivity scales the amplitude before the mapping.
     */
    double scaled = amplitude * sensitivity;
    if (scaled < 0.0) scaled = 0.0;
    if (scaled > 1.0) scaled = 1.0;

    double r_norm = 0.0;
    double g_norm = 0.0;
    double b_norm = 0.0;

    if (scaled < 0.5) {
        r_norm = 4.0 * scaled;
    } else {
        r_norm = 1.0 - 4.0 * (scaled - 0.5);
    }

    if (scaled < 0.25) {
        g_norm = 4.0 * scaled;
    } else if (scaled < 0.75) {
        g_norm = 1.0 - 4.0 * (scaled - 0.25);
    } else {
        b_norm = 4.0 * (scaled - 0.75);
    }

    *r = (int)(r_norm * PWM_RANGE);
    *g = (int)(g_norm * PWM_RANGE);
    *b = (int)(b_norm * PWM_RANGE);
}

/* ------------------------------- Main Loop ------------------------------- */

int main(int argc, char *argv[])
{
    double sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        char *endptr = NULL;
        double val = strtod(argv[1], &endptr);
        if (endptr == argv[1] || val <= 0.0) {
            fprintf(stderr, "Invalid sensitivity value: '%s'\n", argv[1]);
            return EXIT_FAILURE;
        }
        sensitivity = val;
    }

    printf("Mood light audio monitor — sensitivity %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    /* Start with LED off */
    set_led_color(0, 0, 0);

#ifdef ALSA_AVAILABLE
    if (alsa_open_device() != 0) {
        fprintf(stderr, "Failed to open ALSA device. "
                        "Simulating audio for mood light.\n");
    }
#endif

    struct timespec sleep_time = {0, PERIOD_MS * 1000000L};
    struct timespec remaining;

    while (g_running) {
#ifdef ALSA_AVAILABLE
        if (g_handle != NULL) {
            short buffer[PERIOD_FRAMES * 2];
            int r, g, b;

            if (alsa_read_audio(buffer, PERIOD_FRAMES) == 0) {
                double sum_sq = 0.0;
                for (int i = 0; i < PERIOD_FRAMES * 2; i++) {
                    sum_sq += (double)buffer[i] * (double)buffer[i];
                }
                double amplitude = sqrt(sum_sq / (double)(PERIOD_FRAMES * 2));
                map_amplitude_to_color(amplitude, sensitivity, &r, &g, &b);
                set_led_color(r, g, b);
            } else {
                /* On error, turn LED off for safety */
                set_led_color(0, 0, 0);
            }
        }
#else
        /*
         * Simulated audio: a sine wave that cycles through colors.
         * The mood light cycles through colors at a rate determined by
         * the period.
         */
        static double phase = 0.0;
        double amplitude = 0.5 * (1.0 + sin(phase));
        int r, g, b;
        map_amplitude_to_color(amplitude, sensitivity, &r, &g, &b);
        set_led_color(r, g, b);
        phase += 2.0 * M_PI / (SAMPLE_RATE * PERIOD_MS / 1000.0);
        if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
#endif

        nanosleep(&sleep_time, &remaining);
    }

    /* Clean shutdown */
    set_led_color(0, 0, 0);
#ifdef ALSA_AVAILABLE
    alsa_close_device();
#endif
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

