#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TCS34725_ADDR  0x29
#define CSV_FILENAME   "color_data.csv"
#define SAMPLE_US      500000   /* 500 ms */

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A

/* Enable register bits */
#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

/* Integration time (ATIME) values */
#define TCS34725_ATIME_154MS 0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_fp        = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int tcs34725_init(int handle)
{
    /* Power on */
    if (i2cWriteByteData(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error: failed to write PON bit\n");
        return -1;
    }
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Set integration time to 154 ms */
    if (i2cWriteByteData(handle, TCS34725_ATIME, TCS34725_ATIME_154MS) < 0) {
        fprintf(stderr, "Error: failed to set integration time\n");
        return -1;
    }

    /* Enable RGBC ADC */
    if (i2cWriteByteData(handle, TCS34725_ENABLE,
                         TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error: failed to enable AEN\n");
        return -1;
    }

    return 0;
}

static int tcs34725_read_data(int handle, uint16_t *c, uint16_t *r,
                              uint16_t *g, uint16_t *b)
{
    char buf[8];

    if (i2cReadI2CBlockData(handle, TCS34725_CDATAL, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read color data block\n");
        return -1;
    }

    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);

    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_fp = fopen(CSV_FILENAME, "w");
    if (g_fp == NULL) {
        perror("Error: fopen(" CSV_FILENAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_fp, "timestamp,C,R,G,B\n");
    fflush(g_fp);

    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_data(g_i2c_handle, &c, &r, &g, &b) == 0) {
            time_t now = time(NULL);
            fprintf(g_fp, "%ld,%u,%u,%u,%u\n", (long)now, c, r, g, b);
            fflush(g_fp);
        } else {
            fprintf(stderr, "Warning: sensor read failed, logging zeros\n");
            fprintf(g_fp, "%ld,0,0,0,0\n", (long)time(NULL));
            fflush(g_fp);
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

