#define RELAY1 17
#define RELAY2 27
#define RELAY3 22
#define RELAY4 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 54000

#define PWM_RANGE 100
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", gpio, state);
        return -1;
    }
    return 0;
}

static int set_all_relays(int state) {
    int rc = 0;
    if (set_relay(RELAY1, state) < 0) rc = -1;
    if (set_relay(RELAY2, state) < 0) rc = -1;
    if (set_relay(RELAY3, state) < 0) rc = -1;
    if (set_relay(RELAY4, state) < 0) rc = -1;
    return rc;
}

static int set_relay_pwm(int gpio, int duty) {
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int set_all_pwm(int duty) {
    int rc = 0;
    if (set_relay_pwm(RELAY1, duty) < 0) rc = -1;
    if (set_relay_pwm(RELAY2, duty) < 0) rc = -1;
    if (set_relay_pwm(RELAY3, duty) < 0) rc = -1;
    if (set_relay_pwm(RELAY4, duty) < 0) rc = -1;
    return rc;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(RELAY1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY1);
        return -1;
    }
    if (gpioSetMode(RELAY2, PI_OUTPUT) < 0) {
