        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY3);
        return -1;
    }
    if (gpioSetMode(RELAY4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY4);
        return -1;
    }

    if (gpioSetPWMrange(RELAY1, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", RELAY1, PWM_RANGE);
        return -1;
    }
    if (gpioSetPWMrange(RELAY2, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", RELAY2, PWM_RANGE);
        return -1;
    }
    if (gpioSetPWMrange(RELAY3, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", RELAY3, PWM_RANGE);
        return -1;
    }
    if (gpioSetPWMrange(RELAY4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed\n", RELAY4, PWM_RANGE);
        return -1;
    }

    if (gpioSetPWMfrequency(RELAY1, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", RELAY1, PWM_FREQ);
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY2, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", RELAY2, PWM_FREQ);
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", RELAY3, PWM_FREQ);
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY4, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed\n", RELAY4, PWM_FREQ);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    set_all_relays(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    int duty = 0;
    int increment = 1;

    while (running) {
        if (set_all_pwm(duty) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (duty == 0) {
            increment = 1;
        } else if (duty == PWM_RANGE) {
            increment = -1;
        }

        duty += increment;

        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (duty < 0) duty = 0;

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

