#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);
    return 0;
}

static int capture_video(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d -w 1280 -h 720 -fps 30 2>/dev/null",
             filename, VIDEO_DURATION_S);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n", WEXITSTATUS(result));
        return -1;
    }
    return 0;
}

static int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int generate_filename(char *buf, size_t bufsize) {
    time_t rawtime;
    struct tm *timeinfo;
    if (time(&rawtime) == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }
    if (strftime(buf, bufsize, "%Y%m%d_%H%M%S.h264", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
