#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_GYRO_CONFIG  0x1B

/* Sensitivity scale factor for default ±250°/s range */
#define GYRO_SCALE 131.0f

/* Sampling interval in microseconds (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum consecutive I2C read failures before sensor re-init */
#define MAX_READ_FAILURES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize MPU-6050: wake up, set gyro range, verify device presence */
static int init_mpu6050(void) {
    /* Wake up: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (wake)\n");
        return -1;
    }
    gpioDelay(1000); /* allow oscillator to stabilize */

    /* Set gyro full-scale range to ±250°/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }
    gpioDelay(1000);

    /* Verify device presence by reading back PWR_MGMT_1 */
    int pwr = i2cReadByteData(i2c_handle, MPU6050_PWR_MGMT_1);
    if (pwr < 0) {
        fprintf(stderr, "Error: MPU-6050 not responding (read PWR_MGMT_1 failed)\n");
        return -1;
    }
    if (pwr != 0x00) {
        fprintf(stderr, "Warning: PWR_MGMT_1 = 0x%02X (expected 0x00)\n", pwr);
    }

    return 0;
}

/* Read 6 bytes of gyro data and convert to deg/s */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte gyro block\n");
        return -1;
    }

    raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

/* Log one sample to CSV */
static void log_sample(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    fprintf(log_file, "%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open gyro_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int consecutive_failures = 0;

    while (running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            log_sample(x, y, z);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: I2C read failure %d/%d\n",
                    consecutive_failures, MAX_READ_FAILURES);

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: %d consecutive failures, re-initializing sensor...\n",
                        consecutive_failures);
                i2cClose(i2c_handle);
                i2c_handle = -1;

                gpioDelay(100000); /* 100 ms cool-down */

                i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: i2cOpen failed after re-init (handle=%d)\n",
                            i2c_handle);
                    break;
                }

                if (init_mpu6050() < 0) {
                    fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                    break;
                }

                consecutive_failures = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

