#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int log_data(int r1, int r2, int r3, int r4, int moisture) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(g_log, "%s,%d,%d,%d,%d,%d\n", ts, moisture, r1, r2, r3, r4) < 0) {
        fprintf(stderr, "Error: fprintf() to log failed\n");
        return -1;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "Error: fflush() failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    /* Deactivate all relays (HIGH = inactive for active-low relays) */
    safe_write(RELAY1_PIN, 1);
    safe_write(RELAY2_PIN, 1);
    safe_write(RELAY3_PIN, 1);
    safe_write(RELAY4_PIN, 1);
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pins as outputs */
    if (safe_set_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure all relays start deactivated (HIGH = inactive for active-low) */
    if (safe_write(RELAY1_PIN, 1) != 0 ||
        safe_write(RELAY2_PIN, 1) != 0 ||
        safe_write(RELAY3_PIN, 1) != 0 ||
        safe_write(RELAY4_PIN, 1) != 0) {
        cleanup();
        return EXIT_FAILURE;
