            if (safe_write(RELAY1_PIN, 1) != 0) { r1 = -1; } else { r1 = 0; }
            if (safe_write(RELAY2_PIN, 1) != 0) { r2 = -1; } else { r2 = 0; }
            if (safe_write(RELAY3_PIN, 1) != 0) { r3 = -1; } else { r3 = 0; }
            if (safe_write(RELAY4_PIN, 1) != 0) { r4 = -1; } else { r4 = 0; }
        }

        if (log_data(r1, r2, r3, r4, moisture) != 0) {
