/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2 (I2C bus 1)
 *   ADXL345 SCL  -> GPIO3 (I2C bus 1)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   Alarm LED    -> GPIO27 (BCM) through appropriate series resistor
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 * Run:
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants (datasheet) ---- */
#define ADXL345_ADDRESS        0x53
#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_DEVID_EXPECTED 0xE5

/* ---- Application constants ---- */
#define I2C_BUS              1
#define ALARM_GPIO           27
#define FREEFALL_THRESHOLD   0.2f   /* g */
#define FREEFALL_DURATION_S  0.5f   /* seconds */
#define ALARM_HOLD_S         5.0f   /* seconds */
#define POLL_INTERVAL_US     100000 /* 100 ms */
#define LOG_FILE             "freefall.log"

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  adxl345_init(void);
static int  adxl345_read_xyz(float *x, float *y, float *z);
static bool is_freefall(float x, float y, float z);
static void trigger_alarm(void);
static void log_freefall(float x, float y, float z);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/*  Initialise the ADXL345: verify device ID, set full-resolution,    */
/*  +/-200 g range, and enter standby (measurement bit cleared).       */
/* ------------------------------------------------------------------ */
static int adxl345_init(void)
{
    int rc;

    /* Open the I2C bus to the ADXL345 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, ADXL345_ADDRESS, pigpio_error(g_i2c_handle));
        return -1;
    }

    /* Verify device identity */
    rc = i2cReadByteData(g_i2c_handle, ADXL345_REG_DEVID);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to read DEVID register: %s\n",
                pigpio_error(rc));
        return -1;
    }
    if (rc != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X)\n",
                rc, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby: clear measure bit so configuration changes take effect */
    rc = i2cWriteByteData(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to set standby mode: %s\n",
                pigpio_error(rc));
        return -1;
    }

    /* Data format: full resolution, +/-200 g range (0x0B) */
    rc = i2cWriteByteData(g_i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to set data format: %s\n",
                pigpio_error(rc));
        return -1;
    }

    /* Enter measurement mode */
    rc = i2cWriteByteData(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x08);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to set measurement mode: %s\n",
                pigpio_error(rc));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Read 6 bytes of acceleration data (DATAX0..DATAZ1) and convert to  */
/*  g.  Returns 0 on success, -1 on I2C error.                          */
/* ------------------------------------------------------------------ */
static int adxl345_read_xyz(float *x, float *y, float *z)
{
    char buf[6];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, ADXL345_REG_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d: %s\n",
                rc, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }

    /* 12-bit left-justified two's complement: shift right 4 */
    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]) >> 4;
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]) >> 4;
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]) >> 4;

    /* Full resolution, +/-200 g: 4 mg/LSB = 0.004 g/LSB */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;

    return 0;
}

/* ------------------------------------------------------------------ */
/*  Detect free-fall: all three axes below threshold for the full      */
/*  duration.                                                          */
/* ------------------------------------------------------------------ */
static bool is_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* ------------------------------------------------------------------ */
/*  Drive the alarm GPIO high and hold it for ALARM_HOLD_S seconds.    */
/* ------------------------------------------------------------------ */
static void trigger_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite(high) failed\n");
    }
    gpioDelay((uint32_t)(ALARM_HOLD_S * 1000000));
    if (gpioWrite(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(low) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/*  Append a CSV line to the log file: timestamp,x,y,z                */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "timestamp_error,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/*  Release all resources                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  SIGINT handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO as output, initially low */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise ADXL345 */
    if (adxl345_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 initialised on I2C bus %d, address 0x%02X.\n",
           I2C_BUS, ADXL345_ADDRESS);
    printf("Free-fall detection running. Press Ctrl+C to exit.\n");

    float x, y, z;
    bool   in_freefall = false;
    time_t freefall_start = 0;

    while (g_running) {
        if (adxl345_read_xyz(&x, &y, &z) == 0) {
            if (is_freefall(x, y, z)) {
                if (!in_freefall) {
                    in_freefall = true;
                    freefall_start = time(NULL);
                } else if (difftime(time(NULL), freefall_start) >= FREEFALL_DURATION_S) {
                    printf("Free-fall confirmed! (%.3f g, %.3f g, %.3f g)\n", x, y, z);
                    trigger_alarm();
                    log_freefall(x, y, z);
                    in_freefall = false;   /* reset so next event can start */
                }
            } else {
                in_freefall = false;
            }
        }
        /* On I2C error, in_freefall remains unchanged so a recovery
         * attempt is made next iteration. */

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

