/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO4  (BCM 4)
 *   HC-SR04 ECHO -> GPIO18 (BCM 18)
 *   HC-SR04 VCC  -> 5 V
 *   HC-SR04 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lpthread
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN          4
#define ECHO_PIN          18

#define TRIG_PULSE_US     10          /* 10 µs trigger pulse            */
#define TRIG_CYCLE_MS     200         /* 200 ms between trigger cycles  */
#define ECHO_TIMEOUT_US   100000      /* 100 ms max echo wait           */
#define MAX_DISTANCE_CM   400.0       /* HC-SR04 rated range            */
#define MAX_PULSE_US      23200       /* ~4 m round-trip                */
#define LOG_FILE          "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state                                                        */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log      = NULL;
static pthread_mutex_t       g_mtx;

/*
 * pigpio tick wraps every ~71.6 minutes (2^32 µs).
 * We use a 32-bit delta so the subtraction never overflows.
 */
typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    bool     got_rising;
    bool     got_falling;
} echo_state_t;

static echo_state_t g_echo;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static uint64_t now_ns(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 minutes.
 * Returns (b - a) modulo 2^32.
 */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;            /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Echo interrupt callbacks (runs in pigpio thread)                    */
/* ------------------------------------------------------------------ */

static void echo_rising_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        return;
    }

    pthread_mutex_lock(&g_mtx);
    g_echo.start_tick   = tick;
    g_echo.end_tick     = 0;
    g_echo.got_rising   = true;
    g_echo.got_falling  = false;
    pthread_mutex_unlock(&g_mtx);
}

static void echo_falling_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0) {
        return;
    }

    pthread_mutex_lock(&g_mtx);
    if (g_echo.got_rising) {
        g_echo.end_tick   = tick;
        g_echo.got_falling = true;
    }
    pthread_mutex_unlock(&g_mtx);
}

/* ------------------------------------------------------------------ */
/* Trigger pulse                                                       */
/* ------------------------------------------------------------------ */

static void trigger_pulse(void)
{
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return;
    }
    gpioDelay(TRIG_PULSE_US);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Measurement                                                         */
/* ------------------------------------------------------------------ */

static int measure_distance(double *distance_cm)
{
    pthread_mutex_lock(&g_mtx);
    g_echo.got_rising   = false;
    g_echo.got_falling  = false;
    g_echo.start_tick   = 0;
    g_echo.end_tick     = 0;
    pthread_mutex_unlock(&g_mtx);

    trigger_pulse();

    /*
     * Wait for the falling edge.  Poll with 100 µs slices so we can
     * bail out early if the sensor is disconnected or the echo
     * never arrives.
     */
    uint32_t waited = 0;
    const uint32_t poll_us = 100;
    const uint32_t max_wait = ECHO_TIMEOUT_US / poll_us;

    while (waited < max_wait) {
        pthread_mutex_lock(&g_mtx);
        bool done = g_echo.got_falling;
        pthread_mutex_unlock(&g_mtx);

        if (done) {
            break;
        }
        gpioDelay(poll_us);
        waited++;
    }

    pthread_mutex_lock(&g_mtx);
    bool ok = g_echo.got_falling && g_echo.got_rising;
    uint32_t pulse_us = 0;

    if (ok) {
        pulse_us = tick_diff(g_echo.start_tick, g_echo.end_tick);
    }

    /*
     * Reset so the next cycle can start fresh.
     */
    g_echo.got_rising  = false;
    g_echo.got_falling = false;
    g_echo.start_tick  = 0;
    g_echo.end_tick    = 0;

    pthread_mutex_unlock(&g_mtx);

    if (!ok) {
        return -1;                       /* timeout / no echo */
    }
    if (pulse_us > MAX_PULSE_US) {
        return -2;                       /* out of range      */
    }

    /*
     * speed of sound ≈ 343 m/s
     * distance = (pulse_us / 1e6) * 343 / 2
     */
    *distance_cm = ((double)pulse_us / 1000000.0) * 343.0 / 2.0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(double distance_cm)
{
    uint64_t ts = now_ns();
    if (fprintf(g_log, "%llu,%.2f\n", (unsigned long long)ts, distance_cm) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
    } else {
        fflush(g_log);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&g_mtx);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- mutex ---- */
    if (pthread_mutex_init(&g_mtx, NULL) != 0) {
        fprintf(stderr, "Error: mutex initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Error opening log file");
        pthread_mutex_destroy(&g_mtx);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG, OUTPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) initial failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- callbacks ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_rising_cb, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO rising) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_falling_cb, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO falling) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ranging started.  TRIG=GPIO%d  ECHO=GPIO%d\n",
           TRIG_PIN, ECHO_PIN);
    printf("Logging to '%s'.  Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- main loop ---- */
    while (g_running) {
        double distance = 0.0;
        int rc = measure_distance(&distance);

        if (rc == 0) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: echo timeout (sensor absent or no object)\n");
        } else {
            fprintf(stderr, "Warning: distance out of range (%.2f cm)\n", distance);
        }

        /*
         * Sleep in 100 ms slices so SIGINT is responsive.
         */
        uint32_t remaining = TRIG_CYCLE_MS * 1000;
        while (remaining > 0 && g_running) {
            uint32_t chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

