#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* LIS3DH I2C address (SA0 tied to VDD) */
#define LIS3DH_ADDR 0x19

/* LIS3DH register addresses */
#define CTRL_REG1   0x20
#define CTRL_REG4   0x23
#define OUT_X_L     0x28
#define OUT_X_H     0x29
#define OUT_Y_L     0x2A
#define OUT_Y_H     0x2B
#define OUT_Z_L     0x2C
#define OUT_Z_H     0x2D

/* GPIO pin for the buzzer (BCM numbering) */
#define BUZZER_PIN 17

/* Default thresholds (in g) */
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD   1.5

/* I2C bus on Raspberry Pi 5 */
#define I2C_BUS 1

/* Retry parameters */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_i2c(void);
static int init_lis3dh(void);
static int read_acceleration(float *x, float *y, float *z);
static bool detect_freefall(float x, float y, float z, float threshold);
static bool detect_impact(float x, float y, float z, float threshold);
static void activate_buzzer(void);
static void cleanup(void);
static void signal_handler(int signal);

/*
 * Initialize I2C communication.
 * Returns 0 on success, -1 on failure.
 */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, LIS3DH_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Initialize the LIS3DH accelerometer.
 * Returns 0 on success, -1 on failure.
 */
static int init_lis3dh(void) {
    /* Enable accelerometer: 100 Hz data rate, all axes enabled */
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    /* Normal mode, all axes enabled, +/- 2g full scale */
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/*
 * Read acceleration data from the LIS3DH.
 * Returns 0 on success, -1 on failure.
 */
static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int retries = I2C_RETRIES;

    while (retries > 0) {
        int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6);
        if (result == 6) {
            raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
            raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
            raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

            /* Convert raw values to g (sensitivity = 1 mg/LSB at +/- 2g) */
            *x = (float)raw_x / 1000.0f;
            *y = (float)raw_y / 1000.0f;
            *z = (float)raw_z / 1000.0f;
