/*
 * 28BYJ-48 dual-stepper control with ULN2003 driver boards
 * Board: Raspberry Pi 3 Model B+
 * Motor 1 (X-axis): IN1=GPIO4, IN2=GPIO17, IN3=GPIO27, IN4=GPIO22
 * Motor 2 (Y-axis): IN1=GPIO5, IN2=GPIO6,  IN3=GPIO13, IN4=GPIO19
 *
 * 28BYJ-48: 1/64 gear ratio, 2048 steps/rev
 * 4-step wave drive, 1000 us per step
 * 50 mm square -> 2048 * 50 / 25.4 mm = 10240 steps
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEP_DELAY_US 1000
#define SQUARE_MM 50.0
#define STEPS_PER_REV 2048.0
#define STEPS_PER_MM (STEPS_PER_REV / (SQUARE_MM / 25.4))

static volatile sig_atomic_t g_running = 1;

static const int motor1_pins[4] = { MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4 };
static const int motor2_pins[4] = { MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4 };

static const int step_seq[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int motor_init(const int pins[4]) {
    for (int i = 0; i < 4; i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) < 0) return -1;
        if (safe_write(pins[i], 0) < 0) return -1;
    }
    return 0;
}

static int motor_step(const int pins[4], int step) {
    for (int i = 0; i < 4; i++) {
        if (safe_write(pins[i], step_seq[step][i]) < 0) return -1;
    }
    return 0;
}

static int motor_move(const int pins[4], int steps) {
    for (int i = 0; i < steps; i++) {
        if (!g_running) return -1;
        if (motor_step(pins, i % 4) < 0) return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int motor_stop(const int pins[4]) {
    for (int i = 0; i < 4; i++) {
        if (safe_write(pins[i], 0) < 0) return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (motor_init(motor1_pins) < 0 || motor_init(motor2_pins) < 0) {
        fprintf(stderr, "Motor initialization failed\n");
        motor_stop(motor1_pins);
        motor_stop(motor2_pins);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int steps = (int)(STEPS_PER_MM * SQUARE_MM);
    printf("Moving %d steps (%.1f mm) ...\n", steps, SQUARE_MM);

    if (motor_move(motor1_pins, steps) < 0) {
        fprintf(stderr, "Motor 1 movement failed\n");
    }
    if (motor_move(motor2_pins, steps) < 0) {
        fprintf(stderr, "Motor 2 movement failed\n");
    }

    if (!g_running) {
        printf("\nInterrupted — stopping motors...\n");
    }

    motor_stop(motor1_pins);
    motor_stop(motor2_pins);

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

