/*
 * Autonomous line-following robot for Raspberry Pi 5.
 *
 * Sensors (digital IR reflectance, active-high):
 *   Left   -> GPIO4  (BCM)
 *   Center -> GPIO17 (BCM)
 *   Right  -> GPIO27 (BCM)
 * Alert LED/buzzer:
 *   GPIO22 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o line_follower line_follower.c -lpigpio -lrt
 * Run:
 *   sudo ./line_follower
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_LED_PIN      22

#define BUFFER_SIZE        5
#define POLL_DELAY_US      10000   /* 10 ms */
#define ALERT_DURATION_US  2000000 /* 2 s   */

/* ------------------------------- Types ----------------------------------- */

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* --------------------------- Global state -------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Prototypes ---------------------------------- */

static void signal_handler(int sig);
static void init_gpio(void);
static void cleanup_gpio(void);
static int  read_sensor(int pin);
static void add_to_buffer(CircularBuffer *buf, SensorData data);
static SensorData get_latest_data(const CircularBuffer *buf);
static void check_line(const SensorData *data);
static void move_forward(void);
static void turn_left(void);
static void turn_right(void);
static void stop_robot(void);

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    CircularBuffer sensor_buffer;
    sensor_buffer.head  = 0;
    sensor_buffer.count = 0;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (init_gpio() != 0) {
        fprintf(stderr, "pigpio initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (g_running) {
        SensorData sensor_data;
        sensor_data.left   = read_sensor(LEFT_SENSOR_PIN);
        sensor_data.center = read_sensor(CENTER_SENSOR_PIN);
        sensor_data.right  = read_sensor(RIGHT_SENSOR_PIN);

        add_to_buffer(&sensor_buffer, sensor_data);

        check_line(&get_latest_data(&sensor_buffer));

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    cleanup_gpio();
    return EXIT_SUCCESS;
}

/* --------------------------- Signal handler ------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- GPIO init ----------------------------------- */

static void init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return;
    }
    if (gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_LED_PIN);
        gpioTerminate();
        return;
    }

    /* Ensure alert LED is off at startup */
    if (gpioWrite(ALERT_LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW\n", ALERT_LED_PIN);
        gpioTerminate();
        return;
    }
}

/* --------------------------- GPIO cleanup -------------------------------- */

static void cleanup_gpio(void)
{
    /* Turn off alert LED before terminating */
    gpioWrite(ALERT_LED_PIN, 0);
    gpioTerminate();
}

/* --------------------------- Sensor read --------------------------------- */

static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO%d\n", pin);
        return -1; /* Indicate error */
    }
    return value;
}

/* --------------------- Circular buffer operations ------------------------ */

static void add_to_buffer(CircularBuffer *buf, SensorData data)
{
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

static SensorData get_latest_data(const CircularBuffer *buf)
{
    if (buf->count == 0) {
        return (SensorData){0, 0, 0};
    }
    int index = (buf->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buf->data[index];
}

/* --------------------------- Line logic ---------------------------------- */

static void check_line(const SensorData *data)
{
    /* Center sensor: 1 = no line, 0 = line detected */
    if (data->center == 1) {
        /* No line detected — alert LED on for 2 s */
        if (gpioWrite(ALERT_LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to turn on alert LED\n");
        }
        gpioDelay(ALERT_DURATION_US);
        if (gpioWrite(ALERT_LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to turn off alert LED\n");
        }
    } else if (data->center == 0) {
        /* Line detected — move forward */
        move_forward();
    } else {
        /* Sensor error — stop */
        stop_robot();
    }
}

/* --------------------------- Motor helpers ------------------------------- */

static void move_forward(void)
{
    printf("Moving forward\n");
}

static void turn_left(void)
{
    printf("Turning left\n");
}

static void turn_right(void)
{
    printf("Turning right\n");
}

static void stop_robot(void)
{
    printf("Stopping\n");
}

