#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define RELAY_GPIO 17
#define MAGNETIC_FIELD_THRESHOLD 5.0
#define SAMPLE_INTERVAL_US 100000
#define MAX_POLL_ATTEMPTS 50

/* Si7210 register addresses (from datasheet) */
#define SI7210_REG_DEVICE_ID 0x00
#define SI7210_REG_HALL_CTRL 0x01
#define SI7210_REG_HALL_DATA 0x02
#define SI7210_REG_CTRL 0x03
#define SI7210_REG_INT_STATUS 0x04

/* Expected device ID */
#define SI7210_DEVICE_ID 0x10

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("Error opening magnetic_events.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static int initialize_sensor(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    /* Verify device identity */
    int dev_id = i2cReadByteData(i2c_handle, SI7210_REG_DEVICE_ID);
    if (dev_id < 0) {
        fprintf(stderr, "Error reading DEVICE_ID register: %d\n", dev_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (dev_id != SI7210_DEVICE_ID) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%02X (expected 0x%02X)\n",
                dev_id, SI7210_DEVICE_ID);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Configure HALL_CTRL: enable hall sensor, 100 Hz ODR */
    if (i2cWriteByteData(i2c_handle, SI7210_REG_HALL_CTRL, 0x03) < 0) {
        fprintf(stderr, "Error writing HALL_CTRL register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Configure CTRL: 100 Hz ODR, no interrupts */
    if (i2cWriteByteData(i2c_handle, SI7210_REG_CTRL, 0x03) < 0) {
        fprintf(stderr, "Error writing CTRL register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_magnetic_field(float *field) {
    int raw = i2cReadWordData(i2c_handle, SI7210_REG_HALL_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading HALL_DATA register: %d\n", raw);
        return -1;
    }

    /* Si7210 HALL_DATA is 16-bit two's complement, 1 mT per LSB */
    int16_t signed_raw = (int16_t)raw;
    *field = (float)signed_raw / 32768.0f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "Error writing to relay GPIO %d\n", RELAY_GPIO);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    control_relay(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(0);

    if (initialize_sensor() != 0) {
        log_event("Sensor initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int consecutive_errors = 0;

    while (program_running) {
        float field;
        if (read_magnetic_field(&field) == 0) {
            consecutive_errors = 0;

            char log_message[128];
            snprintf(log_message, sizeof(log_message),
                     "Magnetic field: %.2f mT", field);
            log_event(log_message);

            if (field > MAGNETIC_FIELD_THRESHOLD) {
                if (!relay_state) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= 5) {
                log_event("Too many consecutive read errors, exiting");
                break;
            }
            control_relay(0);
            relay_state = 0;
            log_event("Read error, relay deactivated");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

