#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int server_fd = -1;
static int client_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(line, "relay_control", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static int init_socket(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    return 0;
}

static void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (n < 0) {
        perror("recv");
        log_event("Error receiving data from client");
        return;
    }
    if (n == 0) {
        log_event("Client disconnected");
        return;
    }
    buffer[n] = '\0';
    char *newline = strchr(buffer, '\n');
    if (newline) *newline = '\0';
    char *command = strtok(buffer, " \t\r\n");
    if (!command) {
        log_event("Invalid command format");
        return;
    }
    if (strcasecmp(command, "on") == 0) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value");
            log_event("Error setting relay ON");
            return;
        }
        log_event("Relay turned ON");
    } else if (strcasecmp(command, "off") == 0) {
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            log_event("Error setting relay OFF");
            return;
        }
        log_event("Relay turned OFF");
    } else {
        log_event("Invalid command");
    }
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    log_event("Starting relay control server");

    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        log_event("Error setting up signal handlers");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_event("GPIO initialized successfully");

    if (init_socket() < 0) {
        log_event("Socket initialization failed");
        cleanup();
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_event("Socket initialized successfully");

    printf("Listening on port %d...\n", PORT);
    log_event("Server listening");

    while (running) {
        struct sockaddr_in client_addr = {0};
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            log_event("Error accepting connection");
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));
        log_event("Connection accepted");
        handle_client(client_fd);
        close(client_fd);
        client_fd = -1;
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

