/*
 * SLF3S-1300F dual liquid-flow monitor with relay control.
 *
 * Hardware (Raspberry Pi Zero W):
 *   - Sensor 1: I2C bus 1, address 0x4B (7-bit)
 *   - Sensor 2: I2C bus 1, address 0x4C (7-bit)
 *   - Relay:    GPIO 18 (BCM), active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x4B
#define SENSOR2_ADDR         0x4C
#define RELAY_GPIO           18
#define POLL_INTERVAL_US     100000          /* 100 ms */
#define FLOW_THRESHOLD_MLM   5.0f
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F measurement command (16-bit, big-endian on the wire). */
#define MEASURE_CMD_MSB      0x36
#define MEASURE_CMD_LSB      0x08

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;
static bool g_pigpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static uint8_t crc8(const uint8_t *data, int len);
static int  init_sensor(int bus, int addr);
static int  read_flow_rate(int handle, float *flow_out);
static void log_flow_data(float f1, float f2);
static void control_relay(bool below_threshold);
static void cleanup(void);

/* ----------------------------- CRC-8 (Sensirion) -------------------------- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Sensor init -------------------------------- */
static int init_sensor(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[0x%02X] i2cOpen failed: %d\n", addr, h);
        return -1;
    }

    /* Start continuous measurement: write 2-byte command (big-endian). */
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    int rc = i2cWriteDevice(h, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "[0x%02X] start-measurement write failed: %d\n", addr, rc);
        i2cClose(h);
        return -1;
    }

    /* Allow the first measurement to be ready. */
    gpioDelay(20000); /* 20 ms */
    return h;
}

/* ----------------------------- Read flow rate ----------------------------- */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read returned %d bytes (expected 3)\n", n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_out = (float)raw / 100.0f;   /* 16-bit signed, 1/100 ml/min */
    return 0;
}

/* ----------------------------- Logging ------------------------------------ */
static void log_flow_data(float f1, float f2)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d.%03ld, S1: %.2f, S2: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ts.tv_nsec / 1000000L, f1, f2);
    fclose(fp);
}

/* ----------------------------- Relay control ------------------------------ */
static void control_relay(bool below_threshold)
{
    int level = below_threshold ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, level) < 0)
        fprintf(stderr, "gpioWrite(%d) failed\n", level);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_inited) {
        gpioWrite(RELAY_GPIO, 0);
        if (g_i2c_h1 >= 0) i2cClose(g_i2c_h1);
        if (g_i2c_h2 >= 0) i2cClose(g_i2c_h2);
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    g_i2c_h1 = init_sensor(I2C_BUS, SENSOR1_ADDR);
    if (g_i2c_h1 < 0) { cleanup(); return EXIT_FAILURE; }

    g_i2c_h2 = init_sensor(I2C_BUS, SENSOR2_ADDR);
    if (g_i2c_h2 < 0) { cleanup(); return EXIT_FAILURE; }

    printf("Monitoring SLF3S-1300F sensors. Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        bool ok1 = (read_flow_rate(g_i2c_h1, &f1) == 0);
        bool ok2 = (read_flow_rate(g_i2c_h2, &f2) == 0);

        if (ok1 && ok2) {
            log_flow_data(f1, f2);
            control_relay((f1 < FLOW_THRESHOLD_MLM) || (f2 < FLOW_THRESHOLD_MLM));
        }
        /* On read failure the relay stays unchanged (safe default). */

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

