/*
 * rain_window.c — Raspberry Pi 5
 *
 * Monitors a Seeed Studio Rain Sensor v1.0 digital output on GPIO 17 (BCM)
 * and drives an L298N motor on ENA=22, IN1=23, IN2=24 (BCM) to close a window
 * when the sensor transitions from dry to wet (DO goes LOW).
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lpigpio -lrt
 * Run:    sudo ./rain_window
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define MOTOR_RUN_TIME_US 5000000   /* 5 seconds in microseconds */
#define POLL_INTERVAL_US  200000    /* 200 ms in microseconds     */
#define DEBOUNCE_SAMPLES  3         /* 3 consecutive dry samples  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_stop(void)
{
    int rc = 0;
    rc |= gpioWrite(MOTOR_ENA_PIN, 0);
    rc |= gpioWrite(MOTOR_IN1_PIN, 0);
    rc |= gpioWrite(MOTOR_IN2_PIN, 0);
    if (rc != 0)
        syslog(LOG_ERR, "motor_stop: gpioWrite failed (rc=%d)", rc);
    return rc;
}

static int motor_close(void)
{
    int rc = 0;
    rc |= gpioWrite(MOTOR_ENA_PIN, 1);
    rc |= gpioWrite(MOTOR_IN1_PIN, 1);
    rc |= gpioWrite(MOTOR_IN2_PIN, 0);
    if (rc != 0)
        syslog(LOG_ERR, "motor_close: gpioWrite failed (rc=%d)", rc);
    return rc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- configure pins ---- */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(motor pins) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motor is off at start */
    if (motor_stop() != 0) {
        syslog(LOG_ERR, "Initial motor_stop failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started (GPIO %d), motor ENA=%d IN1=%d IN2=%d",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    /* ---- state ---- */
    bool rain_active = false;          /* true while sensor reads LOW (rain) */
    int  dry_samples = 0;              /* consecutive dry readings */

    while (g_running) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN_SENSOR_PIN) failed (rc=%d)", level);
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (level == 0) {
            /* Rain detected — close window only on a rising edge */
            if (!rain_active) {
                syslog(LOG_INFO, "Rain detected (DO=LOW) — closing window");
                if (motor_close() != 0)
                    syslog(LOG_ERR, "motor_close failed");
                else {
                    /* Hold motor for the configured duration */
                    uint32_t elapsed = 0;
                    while (g_running && elapsed < MOTOR_RUN_TIME_US) {
                        usleep(100000); /* 100 ms slices */
                        elapsed += 100000;
                    }
                    if (gpioWrite(MOTOR_ENA_PIN, 0) != 0)
                        syslog(LOG_ERR, "gpioWrite(ENA,0) after run failed");
                    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0)
                        syslog(LOG_ERR, "gpioWrite(IN1,0) after run failed");
                    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0)
                        syslog(LOG_ERR, "gpioWrite(IN2,0) after run failed");
                    syslog(LOG_INFO, "Window closed, motor stopped");
                }
            }
            rain_active = true;
            dry_samples = 0;
        } else {
            /* Dry — increment debounce counter */
            dry_samples++;
            if (dry_samples >= DEBOUNCE_SAMPLES) {
                rain_active = false;
                dry_samples = 0;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

