/*
 * Hobby servo door-lock actuator control for Raspberry Pi.
 *
 * Wiring:
 *   Servo signal  -> GPIO 18 (BCM 18, physical pin 12)
 *   Lock button   -> GPIO 21 (BCM 21, physical pin 40)  [to GND when pressed]
 *   Unlock button -> GPIO 22 (BCM 22, physical pin 38)  [to GND when pressed]
 *   (Both buttons have internal pull-ups enabled so the line reads HIGH
 *   when the button is released and LOW when pressed.)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 *   (Run as root or with appropriate gpio permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN        18
#define LOCK_BUTTON_PIN  21
#define UNLOCK_BUTTON_PIN 22

#define LOCK_PULSE_US    2000   /* microseconds  */
#define UNLOCK_PULSE_US  1000   /* microseconds  */
#define POLL_DELAY_US    10000  /* 10 ms          */
#define DEBOUNCE_US      50000  /* 50 ms release  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Send a pulse width to the servo.                                    */
/* Returns 0 on success, -1 on pigpio error.                           */
/* ------------------------------------------------------------------ */
static int servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n",
                SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);
    if (servo_pulse(LOCK_PULSE_US) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);
    if (servo_pulse(UNLOCK_PULSE_US) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int stop_servo(void)
{
    /* Send a pulse width of 0 to stop the servo. */
    if (servo_pulse(0) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins -------------------------------------------- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n",
                SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n",
                LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n",
                UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the buttons read HIGH when released. */
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure servo is stopped at startup. */
    if (stop_servo() != 0) {
        fprintf(stderr, "Error: failed to initialise servo to stopped state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control system started.\n");
    printf("  Servo:   GPIO %d\n", SERVO_PIN);
    printf("  Lock:    GPIO %d (to GND)\n", LOCK_BUTTON_PIN);
    printf("  Unlock:  GPIO %d (to GND)\n", UNLOCK_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop ----------------------------------------- */
    while (g_running) {
        int lock_pressed   = (gpioRead(LOCK_BUTTON_PIN) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON_PIN) == 0);

        if (lock_pressed) {
            if (lock_door() != 0) {
                fprintf(stderr, "Error: lock_door() failed\n");
                break;
            }
            gpioDelay(DEBOUNCE_US);   /* debounce + release delay */
        }

        if (unlock_pressed) {
            if (unlock_door() != 0) {
                fprintf(stderr, "Error: unlock_door() failed\n");
                break;
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);   /* 10 ms poll interval */
    }

    /* --- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    fflush(stdout);

    if (stop_servo() != 0) {
        fprintf(stderr, "Warning: failed to stop servo during shutdown\n");
    }

    gpioTerminate();
    printf("Door lock control system stopped.\n");
    return EXIT_SUCCESS;
}

