#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event, int duration_sec) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s - %d\n", timestamp, event, duration_sec) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioWrite(FLOODLIGHT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR_PIN %d as input\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FLOODLIGHT_PIN %d as output\n", FLOODLIGHT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise FLOODLIGHT_PIN %d to LOW\n", FLOODLIGHT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR_PIN %d\n", PIR_PIN);
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");

            if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate floodlight on GPIO %d\n", FLOODLIGHT_PIN);
                break;
            }

            if (log_event("Floodlight Activated", 0) != 0) {
                fprintf(stderr, "Failed to log floodlight activation event\n");
            }

            for (int i = 0; i < FLOODLIGHT_DURATION_S && running; i++) {
                gpioDelay(POLL_INTERVAL_US);
            }

            if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate floodlight on GPIO %d\n", FLOODLIGHT_PIN);
                break;
            }

            if (log_event("Floodlight Deactivated", FLOODLIGHT_DURATION_S) != 0) {
                fprintf(stderr, "Failed to log floodlight deactivation event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

