/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 5
 *
 * Hardware:
 *   - MPR121 on I2C bus 1, address 0x60 (ADDR pin tied to GND)
 *   - Relay on GPIO17 (BCM)
 *
 * Behavior:
 *   On a fresh rising edge of electrode 0, toggle the relay.
 *   Debounce electrode 0 for 200 ms.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 *   (pigpio library must be installed; run with sudo or appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MPR121_ADDR          0x60
#define RELAY_GPIO           17

#define DEBOUNCE_US          200000   /* 200 ms in microseconds */
#define POLL_DELAY_US        10000    /* 10 ms poll interval */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_CONFIG1       0x5B
#define MPR121_CONFIG2       0x5C
#define MPR121_MHD_R         0x2B
#define MPR121_NHD_R         0x2C
#define MPR121_NCL_R         0x2D
#define MPR121_FDL_R         0x2E
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_SOFTRESET     0x80

