static int  mpr121_read(uint8_t reg, uint8_t *val);
static int  mpr121_init(void);
static int  mpr121_read_touch_status(uint16_t *status);
static void relay_set(int state);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C Helpers ------------------------------- */
static int mpr121_write(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X, rc=%d)\n",
                reg, val, rc);
    }
    return rc;
}

static int mpr121_read(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X, rc=%d)\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ----------------------------- MPR121 Init ------------------------------- */
static int mpr121_init(void)
{
    uint8_t cfg1, cfg2;

    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle after reset */

    /* Baseline filtering — rising */
    if (mpr121_write(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_R, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=18 samples, SFI=4 samples, CDT=0.5 us */
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config: 16 µA charge current, 0.5 µS */
    if (mpr121_write(MPR121_ECR, 0x8F) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ECR, 0x9F) < 0) return -1;

    /* Verify configuration was accepted */
    if (mpr121_read(MPR121_ECR, &cfg1) < 0) return -1;
    if (mpr121_read(MPR121_CONFIG1, &cfg2) < 0) return -1;
    if (cfg1 != 0x9F || cfg2 != 0x10) {
        fprintf(stderr, "MPR121 config verification failed (ECR=0x%02X, CFG1=0x%02X)\n",
                cfg1, cfg2);
        return -1;
    }

    return 0;
}

/* ----------------------------- Touch Status ------------------------------ */
static int mpr121_read_touch_status(uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ----------------------------- Relay Control ----------------------------- */
static void relay_set(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "Failed to write relay GPIO %d\n", RELAY_GPIO);
        return;
    }
    g_relay_state = state;
    printf("Relay %s\n", state ? "ON" : "OFF");
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure relay is OFF */
    if (g_relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        g_relay_state = 0;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    uint16_t touch_status = 0;
    uint32_t last_touch_ms = 0;
    bool     first_touch   = true;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    relay_set(0);  /* Start with relay OFF */

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Touch status read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t now_ms = gpioTick() / 1000;  /* pigpio tick is microseconds */

