    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
}

static int set_servo_angle(int angle) {
    int pulse = angle_to_pulse(angle);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        log_message(LOG_ERR, "gpioServo failed for pin %d, pulse %d", SERVO_PIN, pulse);
        return -1;
    }
    return 0;
}

static int read_pir_sensor(void) {
    int val = gpioRead(PIR_PIN);
    if (val < 0) {
        log_message(LOG_ERR, "gpioRead failed for pin %d", PIR_PIN);
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n <= 0) {
        if (n < 0) log_message(LOG_WARNING, "recv error: %s", strerror(errno));
        close(client_fd);
        return;
    }
    buffer[n] = '\0';
    log_message(LOG_INFO, "Received: %s", buffer);

    if (strncmp(buffer, "PIR", 3) == 0) {
        int pir = read_pir_sensor();
        if (pir >= 0) {
            char response[64];
            snprintf(response, sizeof(response), "PIR:%d", pir);
            send(client_fd, response, strlen(response), 0);
            log_message(LOG_INFO, "Sent: %s", response);
        } else {
            send(client_fd, "ERROR: PIR read failed", 21, 0);
            log_message(LOG_ERR, "Failed to read PIR sensor");
        }
    } else if (strncmp(buffer, "the library's API call", 21) == 0) {
        char *angle_str = buffer + 21;
        while (*angle_str == ' ') angle_str++;
        int angle = atoi(angle_str);
        if (angle >= 0 && angle <= 180) {
            if (set_servo_angle(angle) == 0) {
                char response[64];
                snprintf(response, sizeof(response), "OK: angle set to %d", angle);
                send(client_fd, response, strlen(response), 0);
                log_message(LOG_INFO, "Sent: %s", response);
            } else {
                send(client_fd, "ERROR: servo set failed", 22, 0);
                log_message(LOG_ERR, "Failed to set servo angle");
            }
        } else {
            send(client_fd, "ERROR: angle out of range (0-180)", 31, 0);
            log_message(LOG_ERR, "Invalid angle: %s", angle_str);
        }
    } else {
        send(client_fd, "ERROR: unknown command", 23, 0);
        log_message(LOG_ERR, "Unknown command: %s", buffer);
    }
    close(client_fd);
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_message(LOG_ERR, "gpioSetMode failed for PIR pin %d", PIR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "gpioSetMode failed for servo pin %d", SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) < 0) {
        log_message(LOG_ERR, "gpioSetPullUpDown failed for PIR pin %d", PIR_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int setup_socket(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (setup_socket() != 0) {
        gpioTerminate();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Security system started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            if (errno != EINTR) {
                log_message(LOG_ERR, "accept: %s", strerror(errno));
            }
            continue;
        }
        handle_client(client_fd);
    }

    log_message(LOG_INFO, "Shutting down");
    if (server_fd >= 0) close(server_fd);
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_file) fclose(log_file);
    closelog();
    return EXIT_SUCCESS;
}

