/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light monitor with grow-light relay.
 *
 * Hardware:
 *   BH1750  I2C1  (GPIO2 = SDA, GPIO3 = SCL)  — address 0x23
 *   Relay   GPIO23 (BCM)
 *
 * Behaviour:
 *   Samples every 2 s, logs lux to grow_log.txt, drives relay ON when
 *   lux < 150 and OFF when lux >= 150.  Retries on I2C errors or
 *   file-write failures; on any exit path, releases all resources.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o grow_monitor grow_monitor.c -lpigpio -lrt
 *   (pigpio daemon must be running or pigpio_init() must be passed
 *   PIGPIO_INIT_MANUAL so the program can self-initialise.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x23
#define BH1750_CMD_POWER_ON  0x10   /* Continuous high-res mode, ~120 ms */
#define BH1750_CMD_RESET     0x07
#define BH1750_CONV_MS       120    /* max conversion time (ms)          */

#define RELAY_GPIO           23
#define LUX_THRESHOLD        150
#define SAMPLE_INTERVAL_S    2
#define LOG_FILE             "grow_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  bh1750_init(void);
static int  bh1750_read_lux(float *lux_out);
static int  log_data(float lux);
static void relay_set(int on);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- BH1750 helpers ---------------------------- */
static int bh1750_init(void)
{
    /* Power on, then reset to ensure a known state. */
    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_POWER_ON) < 0) {
        fprintf(stderr, "[BH1750] power-on command failed\n");
        return -1;
    }
    gpioDelay(5000);                       /* 5 ms settle */

    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_RESET) < 0) {
        fprintf(stderr, "[BH1750] reset command failed\n");
        return -1;
    }
    gpioDelay(5000);                       /* 5 ms reset settle */
    return 0;
}

/*
 * Trigger a measurement, wait for conversion, and read the 2-byte result.
 * Returns 0 on success and stores lux in *lux_out; -1 on any error.
 */
static int bh1750_read_lux(float *lux_out)
{
    char buf[2];

    /* Trigger a single measurement (no register address needed). */
    if (i2cWriteByte(g_i2c_handle, BH1750_CMD_POWER_ON) < 0) {
        fprintf(stderr, "[BH1750] trigger write failed\n");
        return -1;
    }

    gpioDelay(BH1750_CONV_MS * 1000);     /* 120 ms conversion */

    /* Read 2 bytes of result. */
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "[BH1750] read failed\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;          /* per datasheet */
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_data(float lux)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    time(&t);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[log] localtime_r failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[log] strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f lux\n", ts, lux) < 0) {
        fprintf(stderr, "[log] fprintf failed\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[log] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Relay control ----------------------------- */
static void relay_set(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "[relay] gpioWrite(%d) failed\n", on);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Deactivate relay first for safety. */
    relay_set(0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO. */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_set(0);

    /* Open I2C bus to BH1750. */
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor. */
    if (bh1750_init() != 0) {
        fprintf(stderr, "BH1750 initialisation failed — sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow-light monitor started.  Sampling every %d s.  Ctrl-C to exit.\n",
           SAMPLE_INTERVAL_S);

    /* Main sampling loop. */
    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (log_data(lux) != 0) {
                fprintf(stderr, "Logging failed — continuing\n");
            }

            if (lux < LUX_THRESHOLD) {
                relay_set(1);
            } else {
                relay_set(0);
            }
        } else {
            fprintf(stderr, "Sensor read error — will retry next cycle\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);             /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

