code:
/*
 * Raspberry Pi 3 Model B+ — HX711 Load Cell Monitor with Solenoid Lock
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o weight_lock weight_lock.c -lpigpio -lrt
 * Run:
 *   sudo ./weight_lock [--threshold <grams>] [--scale <factor>] [--duration <ms>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

#define HX711_DOUT_PIN    23
#define HX711_SCK_PIN     24
#define SOLENOID_PIN      25

#define DEFAULT_THRESHOLD 1000.0f   /* grams */
#define DEFAULT_SCALE     1.0f
#define DEFAULT_DURATION  200       /* ms */
#define NUM_READINGS      5
#define TARE_READINGS     10
#define HX711_TIMEOUT_US  1000000   /* 1 s timeout waiting for DOUT low */
#define HX711_SETTLE_US  1000      /* 1 ms settle after SCK high */
#define POLL_DELAY_US     500000    /* 500 ms between measurements */
#define RETRY_DELAY_US    100000    /* 100 ms between retries */
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;
static int32_t g_tare_offset = 0;
static float   g_scale_factor = DEFAULT_SCALE;
static int     g_solenoid_duration = DEFAULT_DURATION;
static float   g_threshold = DEFAULT_THRESHOLD;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Read a 24-bit two's-complement value from the HX711.
 * Returns 0 on success (value stored in *out), -1 on timeout/error.
 */
static int hx711_read(int32_t *out)
{
    int32_t value = 0;
    int i;

    /* Ensure SCK is LOW so the chip is not in power-down mode. */
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(SCK, 0) failed: %s", pigpio_error(0));
        return -1;
    }

    /* Wait for DOUT to go LOW (data ready). */
    for (i = 0; i < HX711_TIMEOUT_US; i += 10) {
        if (gpioRead(HX711_DOUT_PIN) == 0)
            break;
        gpioDelay(10);
    }
    if (i >= HX711_TIMEOUT_US) {
        syslog(LOG_ERR, "HX711 timeout waiting for DOUT low");
        return -1;
    }

    /* Read 24 data bits, MSB first. */
    for (i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            syslog(LOG_ERR, "gpioWrite(SCK, 1) failed: %s", pigpio_error(0));
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);

        value <<= 1;
        if (gpioRead(HX711_DOUT_PIN))
            value |= 1;

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            syslog(LOG_ERR, "gpioWrite(SCK, 0) failed: %s", pigpio_error(0));
            return -1;
        }
        gpioDelay(HX711_SETTLE_US);
    }

    /* 25th clock pulse: Channel A, gain 128. */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        syslog(LOG_ERR, "gpioWrite(SCK, 1) failed: %s", pigpio_error(0));
        return -1;
    }
    gpioDelay(HX711_SETTLE_US);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(SCK, 0) failed: %s", pigpio_error(0));
        return -1;
    }
    gpioDelay(HX711_SETTLE_US);

    /* Convert 24-bit two's complement to 32-bit signed. */
    if (value & 0x800000)
        value |= ~0xFFFFFF;          /* sign-extend */

    *out = value;
    return 0;
}

/*
 * Average TARE_READINGS readings and compute a tare offset.
 * Returns 0 on success, -1 on error.
 */
static int hx711_tare(void)
{
    int32_t sum = 0;
    int i;

    syslog(LOG_INFO, "Starting tare (%d readings)...", TARE_READINGS);

    for (i = 0; i < TARE_READINGS; i++) {
        int32_t raw;
        if (hx711_read(&raw) != 0) {
            syslog(LOG_ERR, "Tare read %d/%d failed", i + 1, TARE_READINGS);
            return -1;
        }
        sum += raw;
        gpioDelay(10000);            /* 10 ms between tare samples */
    }

    g_tare_offset = sum / TARE_READINGS;
    syslog(LOG_INFO, "Tare complete: offset = %d", g_tare_offset);
    return 0;
}

/*
 * Read NUM_READINGS samples and compute the average.
 * Returns 0 on success, -1 on error.
 */
static int hx711_read_average(int32_t *average)
{
    int32_t sum = 0;
    int i;

    for (i = 0; i < NUM_READINGS; i++) {
        int32_t raw;
        if (hx711_read(&raw) != 0) {
            syslog(LOG_ERR, "Read %d/%d failed during average", i + 1, NUM_READINGS);
            return -1;
        }
        sum += raw;
        gpioDelay(1000);             /* 1 ms between samples */
    }

    *average = sum / NUM_READINGS;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                    */
/* ------------------------------------------------------------------ */
static void solenoid_activate(void)
{
    syslog(LOG_INFO, "Solenoid activated for %d ms", g_solenoid_duration);
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        syslog(LOG_ERR, "gpioWrite(solenoid, 1) failed: %s", pigpio_error(0));
