}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure solenoid is OFF before releasing pins. */
    gpioWrite(SOLENOID_PIN, 0);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;

    openlog("weight_lock", LOG_PID | LOG_CONS, LOG_USER);

    while ((opt = getopt(argc, argv, "t:s:d:h")) != -1) {
        switch (opt) {
        case 't':
            g_threshold = atof(optarg);
            break;
        case 's':
            g_scale_factor = atof(optarg);
            break;
        case 'd':
            g_solenoid_duration = atoi(optarg);
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n",
                    argv[0]);
            exit(EXIT_FAILURE);
        }
    }

    if (g_scale_factor <= 0.0f) {
        syslog(LOG_ERR, "Invalid scale factor (%f); using default %.2f",
               g_scale_factor, DEFAULT_SCALE);
        g_scale_factor = DEFAULT_SCALE;
    }
    if (g_solenoid_duration <= 0) {
        syslog(LOG_ERR, "Invalid duration (%d); using default %d ms",
               g_solenoid_duration, DEFAULT_DURATION);
        g_solenoid_duration = DEFAULT_DURATION;
    }

    syslog(LOG_INFO, "Starting weight_lock — threshold=%.2f g, scale=%.2f, duration=%d ms",
           g_threshold, g_scale_factor, g_solenoid_duration);

    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %m");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins. */
    if (gpioSetMode(HX711_DOUT_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(DOUT) failed: %s", pigpio_error(0));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(SCK) failed: %s", pigpio_error(0));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(solenoid) failed: %s", pigpio_error(0));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states. */
    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    /* Tare the load cell. */
    if (hx711_tare() != 0) {
        syslog(LOG_ERR, "Tare failed; aborting");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Entering main loop");

    while (g_running) {
        int32_t raw;
        int retries = 0;
        bool read_ok = false;

        /* Retry on transient HX711 errors. */
        while (retries < MAX_RETRIES && !read_ok && g_running) {
            if (hx711_read(&raw) == 0) {
