            syslog(LOG_ERR, "HX711 read failed after %d retries; exiting", MAX_RETRIES);
            break;
        }

        int32_t adjusted = raw - g_tare_offset;
        float weight = (float)adjusted / g_scale_factor;

        syslog(LOG_INFO, "Raw=%d  Adjusted=%d  Weight=%.2f g", raw, adjusted, weight);

        if (weight > g_threshold) {
            solenoid_activate();
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

