/*
 * relay_controller.c — Raspberry Pi 4 Model B
 * MQTT relay controller for home/lights/control.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *               -lmosquitto -lpthread
 * Run:    ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pthread.h>
#include <errno.h>
#include <mosquitto.h>
#include <gpiod.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LINE      17            /* BCM 17, physical pin 11 */
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s",
               GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, "mqtt_relay", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output: %s", strerror(errno));
        g_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialized: BCM %d as output (LOW = relay OFF)",
           GPIO_LINE);
    return 0;
}

static void gpio_cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);   /* relay OFF */
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata,
                       int result, int flags)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d (client ID %s)",
               MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID);

        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_subscribe: %s",
                   mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s",
               mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata,
                          int rc)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d): %s",
           rc, mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Invalid MQTT message received (empty payload)");
        return;
    }

    /* Ensure NUL-terminated payload for safe string comparison */
    char payload[256];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "MQTT message on %s: %s",
           message->topic ? message->topic : "(null)", payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpiod_line_set_value(g_line, 1) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value(1): %s",
                   strerror(errno));
        } else {
            syslog(LOG_INFO, "Relay ON (GPIO HIGH)");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpiod_line_set_value(g_line, 0) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value(0): %s",
                   strerror(errno));
        } else {
            syslog(LOG_INFO, "Relay OFF (GPIO LOW)");
        }
    } else {
        syslog(LOG_ERR, "Invalid payload: \"%s\" (expected ON or OFF)",
               payload);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed; exiting");
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new: %s", strerror(errno));
        gpio_cleanup();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT,
                               MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
