               mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Entering MQTT main loop");

    while (g_running) {
        rc = mosquitto_loop(g_mosq, POLL_TIMEOUT_MS, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop: %s",
                   mosquitto_strerror(rc));
            if (g_running) {
                sleep(5);
            }
        }
    }

    syslog(LOG_INFO, "Shutting down");

    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    gpio_cleanup();

    closelog();
    return EXIT_SUCCESS;
}

