#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define TARGET_1 1000
#define TARGET_2 1500
#define TARGET_3 2000
#define TARGET_4 500
#define TARGET_5 2500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_range(int x, int in_min, int in_max, int out_min, int out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[5] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int targets[5] = {TARGET_1, TARGET_2, TARGET_3, TARGET_4, TARGET_5};

    for (int i = 0; i < 5; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 5; i++) {
        int pulse_width = map_range(targets[i], MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, 0, 2000000);
        if (gpioServo(pins[i], pulse_width) != 0) {
            fprintf(stderr, "Error: failed to set servo on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Servo %d: pulse width %d us (target %d us)\n", i + 1, pulse_width, targets[i]);
    }

    printf("Moving servos to predefined positions...\n");
    sleep(3);

    for (int i = 0; i < 5; i++) {
        if (gpioServo(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to stop servo on GPIO %d\n", pins[i]);
        }
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

