/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - Two quadrature encoders (1:1 ratio, 64 ticks/rev)
 *   - Two DRV8833 H-bridges on GPIO 17/18 (Motor A) and 22/23 (Motor B)
 *   - Encoder A: phase A = GPIO 4, phase B = GPIO 5
 *   - Encoder B: phase A = GPIO 6, phase B = GPIO 12
 *
 * Behaviour:
 *   - PI control loop every 100 ms (10 kHz PWM)
 *   - Target 50 RPM for both motors
 *   - Anti-windup clamping in the controller
 *   - Stall detection: warn if no ticks for >2 s
 *   - SIGINT clean shutdown
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_ctrl motor_ctrl.c -lpigpio -lpthread
 *   sudo ./motor_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM   17
#define MOTOR_A_DIR   18
#define MOTOR_B_PWM   22
#define MOTOR_B_DIR   23

#define ENCODER_A_A   4
#define ENCODER_A_B   5
#define ENCODER_B_A   6
#define ENCODER_B_B   12

/* ---- Control parameters ---- */
#define TARGET_RPM        50.0
#define PWM_FREQUENCY     10000   /* 10 kHz */
#define PWM_RANGE         255
#define LOOP_DELAY_US     100000  /* 100 ms */
#define STALL_TIMEOUT_S   2
#define ENCODER_TICKS_PER_REV 64

/* ---- Globals ---- */
static volatile int32_t g_ticks_a = 0;
static volatile int32_t g_ticks_b = 0;
static volatile sig_atomic_t g_running = 1;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ---- Function prototypes ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static void signal_handler(int sig);
static void cleanup(void);
static void set_motor_speed(int motor_pwm, int motor_dir, int pwm_value);
static void stop_motors(void);
static void update_rpm(double *rpm_a, double *rpm_b);
static int  init_gpio(void);
static void control_loop(void);

/* ---- ISRs ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;
    int32_t ticks = 1;
    pthread_mutex_lock(&g_mutex);
    g_ticks_a += ticks;
    pthread_mutex_unlock(&g_mutex);
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;
    int32_t ticks = 1;
    pthread_mutex_lock(&g_mutex);
    g_ticks_b += ticks;
    pthread_mutex_unlock(&g_mutex);
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    stop_motors();
    gpioTerminate();
}

/* ---- Motor helpers ---- */
static void set_motor_speed(int motor_pwm, int motor_dir, int pwm_value)
{
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

    if (gpioPWM(motor_pwm, pwm_value) < 0)
        fprintf(stderr, "Warning: gpioPWM failed on pin %d\n", motor_pwm);

    if (gpioWrite(motor_dir, 1) < 0)
        fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", motor_dir);
}

static void stop_motors(void)
{
    gpioWrite(MOTOR_A_DIR, 0);
    gpioPWM(MOTOR_A_PWM, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_B_PWM, 0);
}

/* ---- RPM update ---- */
static void update_rpm(double *rpm_a, double *rpm_b)
{
    pthread_mutex_lock(&g_mutex);
    int32_t ticks = g_ticks_a;
    g_ticks_a = 0;
    pthread_mutex_unlock(&g_mutex);

    *rpm_a = (double)ticks * (60.0 / (double)ENCODER_TICKS_PER_REV) / (double)LOOP_DELAY_US;

    pthread_mutex_lock(&g_mutex);
    ticks = g_ticks_b;
    g_ticks_b = 0;
    pthread_mutex_unlock(&g_mutex);

    *rpm_b = (double)ticks * (60.0 / (double)ENCODER_TICKS_PER_REV) / (double)LOOP_DELAY_US;
}

/* ---- GPIO init ---- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    /* Motor pins */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor pin modes\n");
        return -1;
    }

    /* Encoder pins */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes\n");
        return -1;
    }

    /* Pull-ups (encoders idles high) */
    gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP);

    /* PWM */
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        return -1;
    }

    /* ISRs (rising edge) */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISRs\n");
        return -1;
    }

    return 0;
}

/* ---- Main control loop ---- */
static void control_loop(void)
{
    double rpm_a = 0.0, rpm_b = 0.0;
    double error_a = 0.0, error_b = 0.0;
    double integral_a = 0.0, integral_b = 0.0;
    const double Kp = 10.0, Ki = 0.1;
    const double MAX_PWM = (double)PWM_RANGE;

    while (g_running) {
        update_rpm(&rpm_a, &rpm_b);

        error_a = TARGET_RPM - rpm_a;
        error_b = TARGET_RPM - rpm_b;

        integral_a += error_a;
        integral_b += error_b;

        /* Anti-windup clamp */
        if (integral_a >  MAX_PWM) integral_a =  MAX_PWM;
        if (integral_a < -MAX_PWM) integral_a = -MAX_PWM;
        if (integral_b >  MAX_PWM) integral_b =  MAX_PWM;
        if (integral_b < -MAX_PWM) integral_b = -MAX_PWM;

        double output_a = Kp * error_a + Ki * integral_a;
        double output_b = Kp * error_b + Ki * integral_b;

        if (output_a > MAX_PWM) output_a = MAX_PWM;
        if (output_a < -MAX_PWM) output_a = -MAX_PWM;
        if (output_b > MAX_PWM) output_b = MAX_PWM;
        if (output_b < -MAX_PWM) output_b = -MAX_PWM;

        set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, (int)output_a);
        set_motor_speed(MOTOR_B_PWM, MOTOR_B_DIR, (int)output_b);

        printf("Motor A RPM: %.2f, PWM: %.0f | Motor B RPM: %.2f, PWM: %.0f\n",
               rpm_a, output_a, rpm_b, output_b);

        usleep(LOOP_DELAY_US);
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0)
        return EXIT_FAILURE;

