#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_ONE_TIME_LOW_RES_MODE 0x21
#define BH1750_POWER_DOWN 0x00
#define BH1750_RESET 0x07

#define RELAY_GPIO 17
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define POLL_INTERVAL_SEC 5
#define BH1750_MEASUREMENT_DELAY_US 180000
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(void) {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        return -1;
    }

    if (i2cWriteByte(i2c_handle, BH1750_POWER_DOWN) < 0) {
        fprintf(stderr, "Error writing power-down command to BH1750\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByte(i2c_handle, BH1750_RESET) < 0) {
        fprintf(stderr, "Error writing reset command to BH1750\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    gpioDelay(10000);
    return 0;
}

static int read_lux(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_ONE_TIME_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing measurement command to BH1750\n");
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    int raw = i2cReadWordData(i2c_handle, 0x00);
    if (raw < 0) {
        fprintf(stderr, "Error reading data from BH1750: %d\n", raw);
        return -1;
    }

    *lux_out = (float)raw / 1.2;
    return 0;
}

static int control_relay(int state) {
    int rc = gpioWrite(RELAY_GPIO, state);
    if (rc < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", RELAY_GPIO, rc);
        return -1;
    }
    return 0;
}

static int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time\n");
        return -1;
    }

    char timestamp[20];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_relay(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_bh1750() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_lux = -1;

    while (running) {
        float lux = 0.0f;
        if (read_lux(&lux) < 0) {
            fprintf(stderr, "Sensor read failed, turning off relay for safety\n");
            if (relay_state) {
                if (control_relay(0) < 0) {
                    fprintf(stderr, "Failed to turn off relay\n");
                } else {
                    relay_state = 0;
                }
            }
            log_data(-1.0f, relay_state);
        } else {
            if (lux < LUX_THRESHOLD_LOW && !relay_state) {
                if (control_relay(1) < 0) {
                    fprintf(stderr, "Failed to turn on relay\n");
                } else {
                    relay_state = 1;
                }
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state) {
                if (control_relay(0) < 0) {
                    fprintf(stderr, "Failed to turn off relay\n");
                } else {
                    relay_state = 0;
                }
            }
            log_data(lux, relay_state);
        }

        if (last_lux != (int)lux) {
            printf("Lux: %.2f, Relay: %s\n", lux, relay_state ? "ON" : "OFF");
            last_lux = (int)lux;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    control_relay(0);
    cleanup();
    return EXIT_SUCCESS;
}

