/*
 * touch_relay.c — TTP223 touch sensor → 5 V relay toggle on Raspberry Pi Zero W
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 *
 * Wiring
 *   TTP223 VCC  → 3.3 V (pin 1)
 *   TTP223 GND  → GND   (pin 9)
 *   TTP223 OUT  → GPIO4 (pin 7)
 *   Relay IN    → GPIO17 (pin 11)
 *   Relay VCC   → 5 V
 *   Relay GND   → GND
 *
 * Behaviour
 *   On a valid HIGH → LOW touch transition the relay toggles.
 *   A 50 ms debounce delay is inserted after a valid transition.
 *   The relay stays OFF while the sensor is LOW.
 *   SIGINT (Ctrl-C) turns the relay OFF and releases pigpio resources.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17

#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US     10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

