static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Returns 0 on success, -1 on error.
 * Prints an ISO-8601 timestamp to stdout.
 */
static int log_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    printf("[%s] ", buf);
    return 0;
}

/*
 * Returns 0 on success, -1 on error.
 * Prints the new relay state to stdout.
 */
static int log_relay_state(int state)
{
    if (log_timestamp() != 0)
        return -1;

    printf("Relay is now %s\n", state ? "ON" : "OFF");
    return 0;
}

/*
 * Returns 0 on success, -1 on error.
 * Toggles the relay and logs the new state.
 */
static int toggle_relay(void)
{
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "gpioRead(RELAY_PIN) failed: %s\n", pigpio_error(current));
        return -1;
    }

    int new_state = !current;

    if (gpioWrite(RELAY_PIN, new_state) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", new_state);
        return -1;
    }

    return log_relay_state(new_state);
}

/*
 * Returns 0 on success, -1 on error.
 * Debounces a touch transition by waiting DEBOUNCE_DELAY_US.
 */
static int debounce_touch(void)
{
    gpioDelay(DEBOUNCE_DELAY_US);
    return 0;
}

/*
 * Returns 0 on success, -1 on error.
 * Releases pigpio resources.
 */
static int cleanup(void)
{
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) during cleanup failed\n");
        return -1;
    }

    if (gpioTerminate() < 0) {
        fprintf(stderr, "gpioTerminate failed\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install SIGINT handler ------------------------------------ */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

