#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_S 1
#define LOG_FILE_NAME "water_flow.log"

static volatile int pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        last_pulse_tick = tick;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_lpm(int pulses, double elapsed_s) {
    if (elapsed_s <= 0.0) return 0.0;
    return (double)pulses / elapsed_s * 60.0;
}

static void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow: %.2f LPM, Solenoid: %s\n",
            timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int solenoid_state = 1;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set flow sensor pin mode: %d\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode: %d\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(SOLENOID_PIN, solenoid_state);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to write solenoid pin: %d\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIMEOUT_MS, flow_sensor_isr, NULL);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set ISR for flow sensor: %d\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_data(0.0, solenoid_state);

    while (running) {
        int local_pulses = 0;
        uint32_t now = gpioTick();

        pthread_mutex_lock(&pulse_mutex);
        local_pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double elapsed = (double)(now - last_pulse_tick) / 1000000.0;
        double lpm = calculate_lpm(local_pulses, elapsed);

        if (lpm > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
            solenoid_state = 0;
            ret = gpioWrite(SOLENOID_PIN, solenoid_state);
            if (ret != 0) {
                fprintf(stderr, "Error: Failed to close solenoid: %d\n", ret);
                log_data(lpm, -1);
            } else {
                log_data(lpm, solenoid_state);
            }
        } else if (lpm < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
            solenoid_state = 1;
            ret = gpioWrite(SOLENOID_PIN, solenoid_state);
            if (ret != 0) {
                fprintf(stderr, "Error: Failed to open solenoid: %d\n", ret);
                log_data(lpm, -1);
            } else {
                log_data(lpm, solenoid_state);
            }
        } else {
            log_data(lpm, solenoid_state);
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    fprintf(log_file, "Program terminated by signal.\n");
    fflush(log_file);

    gpioWrite(SOLENOID_PIN, 1);
    cleanup();
    return EXIT_SUCCESS;
}

