#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <config.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN  24
#define SERVO_PIN      18

#define CONFIG_FILE    "config.ini"
#define LOG_FILE       "dispensing_log.json"

#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_KNOWN_WEIGHT       1.0

#define HX711_TIMEOUT_US 1000
#define HX711_SETTLE_US 100000
#define SERVO_SETTLE_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, double *calibration_factor, double *known_weight) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    int found_cf = 0, found_w = 0;

    while (fgets(line, sizeof(line), fp)) {
        char *start = line;
        while (*start == ' ' || *start == '\t') start++;
        if (*start == '\0' || *start == '#' || *start == ';') continue;

        char *eq = strchr(start, '=');
        if (!eq) continue;
        *eq = '\0';

        char *key = start;
        char *val = eq + 1;
        while (*val == ' ' || *val == '\t') val++;

        if (strcmp(key, "calibration_factor") == 0) {
            *calibration_factor = strtod(val, NULL);
            found_cf = 1;
        } else if (strcmp(key, "known_weight") == 0) {
            *known_weight = strtod(val, NULL);
            found_w = 1;
        }
    }

    fclose(fp);

    if (!found_cf) {
        fprintf(stderr, "Warning: 'calibration_factor' not found in config. Using default.\n");
        *calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }
    if (!found_w) {
        fprintf(stderr, "Warning: 'known_weight' not found in config. Using default.\n");
        *known_weight = DEFAULT_KNOWN_WEIGHT;
    }

    return 0;
}

static int hx711_read(double *out) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) return -1;
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) return -1;

    int32_t data = 0;
    int timeout = 0;

    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 timeout waiting for data pin to go LOW.\n");
            return -1;
        }
        gpioDelay(1);
    }

    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

