#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay pin %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    relay_state = 0;
    return 0;
}

static int read_touch_sensor(void) {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        return -1;
    }
    return value;
}

static int toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: failed to write relay pin %d\n", RELAY_PIN);
        return -1;
    }
    return 0;
}

static void log_relay_state(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(stdout);
}

static void cleanup(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;

    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_ms = atoi(argv[2]);
            if (debounce_ms <= 0) {
                fprintf(stderr, "Error: debounce time must be a positive integer\n");
                return EXIT_FAILURE;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Touch sensor pin: GPIO %d, Relay pin: GPIO %d, Debounce: %d ms\n",
           TOUCH_SENSOR_PIN, RELAY_PIN, debounce_ms);
    fflush(stdout);

    int last_touch_state = 0;
    int stable_state = 0;
    int stable_count = 0;
    int last_edge_time = 0;

    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            gpioDelay(100000);
            continue;
        }

        int current_time = gpioTick() / 1000;

        if (touch_state != last_touch_state) {
            last_edge_time = current_time;
        }

        if (touch_state == 1 && (current_time - last_edge_time) * 1000 >= debounce_ms) {
            stable_count++;
            if (stable_count >= 5) {
                stable_state = 1;
            }
        } else {
            stable_count = 0;
            stable_state = 0;
        }

        if (stable_state && touch_state == 1 && last_touch_state == 0) {
            if (toggle_relay() == 0) {
                log_relay_state();
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10000);
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

