/*
 * servo_angle.c — Hobby servo angle control on Raspberry Pi 4/5
 *
 * Drives a hobby servo (e.g. SG90) on GPIO18 (BCM 18, physical pin 12)
 * with hardware PWM at 50 Hz (20 ms period).  Reads +/- keys in raw
 * terminal mode; on 'q' or SIGINT stops PWM and exits cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_angle servo_angle.c -lpigpio -lrt
 * Run:    sudo ./servo_angle
