#define PWM_FREQ_HZ    50          /* 50 Hz — typical for servos */
#define PWM_RANGE      1000        /* 0–1000 → 0–1000 µs pulse width */
#define MIN_PULSE_US   500         /* SG90 safe lower bound (~0°)   */
#define MAX_PULSE_US   2500        /* SG90 safe upper bound (~180°) */
#define ANGLE_STEP_DEG 10
#define START_ANGLE_DEG 90

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Convert angle (0–180°) to pulse width (500–2500 µs).
 * Returns 0 on success, -1 if angle is out of range.
 */
static int angle_to_pulse_us(int angle, int *pulse_us)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Angle %d out of range (0–180)\n", angle);
        return -1;
    }
    *pulse_us = MIN_PULSE_US +
                (int)((long)angle * (MAX_PULSE_US - MIN_PULSE_US) / 180);
    return 0;
}

/*
 * Set servo pulse width on SERVO_PIN.
 * pigpio call() returns 0 on success, negative on error.
 */
static int set_servo_pulse(int pulse_us)
{
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Pulse %d µs out of range (%d–%d)\n",
                pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }

    int rc = gpioHardwarePWM(SERVO_PIN, PWM_FREQ_HZ, pulse_us);
    if (rc < 0) {
        fprintf(stderr, "gpioHardwarePWM failed: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Stop PWM pulses on the servo pin */
    (void)gpioHardwarePWM(SERVO_PIN, PWM_FREQ_HZ, 0);

    /* Restore pigpio to a known safe state */
    (void)gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int angle = START_ANGLE_DEG;
    int pulse_us;

    /* --- Install signal handlers early ------------------------------ */
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on SERVO_PIN --------------------------------- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start at the configured angle ------------------------------ */
    if (angle_to_pulse_us(angle, &pulse_us) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(pulse_us) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo started at %d° (%d µs).  Press +/- to adjust, q to quit.\n",
           angle, pulse_us);
    fflush(stdout);

    /* --- Main loop: raw terminal input ------------------------------ */
    while (g_running) {
        int ch = getchar();
        if (ch == EOF) {
            if (errno == EINTR) {
                continue;          /* interrupted by signal — re-check flag */
            }
            break;                /* unexpected EOF — exit cleanly */
        }

        switch (ch) {
        case '+':
            angle += ANGLE_STEP_DEG;
            if (angle > 180) angle = 180;
            break;
        case '-':
            angle -= ANGLE_STEP_DEG;
            if (angle < 0) angle = 0;
            break;
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        default:
            continue;              /* ignore other characters */
        }

        if (angle_to_pulse_us(angle, &pulse_us) != 0) {
            g_running = 0;
            break;
        }

        if (set_servo_pulse(pulse_us) != 0) {
            g_running = 0;
            break;
        }

        printf("Angle: %3d°  Pulse: %4d µs\n", angle, pulse_us);
        fflush(stdout);
    }

    /* --- Clean shutdown --------------------------------------------- */
    cleanup();
    printf("\nServo stopped. Goodbye.\n");
    return EXIT_SUCCESS;
}

