/*
 * conveyor_rpm.c — Raspberry Pi 3 Model B+
 *
 * Monitors a Hall-effect A3144 sensor on GPIO 17 (BCM) for rising-edge
 * pulses (one per revolution) and computes the motor RPM every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o conveyor_rpm conveyor_rpm.c -lpigpio -lrt
 * Run:    sudo ./conveyor_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          17          /* BCM 17, physical pin 11 */
#define DEBOUNCE_MS       2           /* debounce window (ms)    */
#define SAMPLE_PERIOD_S   5           /* RPM logging interval    */
#define LOG_FILE          "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return elapsed milliseconds between two monotonic clock readings.  */
static double elapsed_ms(const struct timespec *start,
                         const struct timespec *end)
{
    return (double)(end->tv_sec  - start->tv_sec) * 1000.0 +
           (double)(end->tv_nsec - start->tv_nsec) / 1.0e6;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line:  timestamp,rpm\n                              */
static int log_rpm(FILE *fp, double rpm)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (t == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    struct timespec  last_pulse;
    struct timespec  now;
    uint32_t         last_tick = 0;
    uint32_t         pulse_count = 0;
    FILE            *log_fp = NULL;
    int              ret = EXIT_FAILURE;

    /* ---- signal handling ------------------------------------------ */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file -------------------------------------------- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_gpio;
    }

    /* ---- configure GPIO ------------------------------------------- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        goto cleanup_all;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        goto cleanup_all;
    }

    /* ---- seed last_pulse with current time ------------------------ */
    if (clock_gettime(CLOCK_MONOTONIC, &last_pulse) != 0) {
        perror("clock_gettime(CLOCK_MONOTONIC)");
        goto cleanup_all;
    }

    printf("Conveyor RPM monitor started on GPIO %d.  Press Ctrl-C to exit.\n",
           GPIO_PIN);

    /* ---- main loop ------------------------------------------------ */
    while (g_running) {
        uint32_t level;

        /* Sleep 100 ms so we wake every 100 ms to check g_running. */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100 * 1000);          /* 100 ms */

        if (!g_running)
            break;

        /* ---- read current level ----------------------------------- */
        level = gpioRead(GPIO_PIN);
        if (level == PI_BAD_GPIO) {
            fprintf(stderr, "gpioRead(%d) failed\n", GPIO_PIN);
            goto cleanup_all;
        }

        /* ---- rising edge: increment pulse count ------------------- */
        if (level == 1 && last_tick == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                perror("clock_gettime(CLOCK_MONOTONIC)");
                goto cleanup_all;
            }
            if (elapsed_ms(&last_pulse, &now) >= DEBOUNCE_MS) {
                pulse_count++;
                last_pulse = now;
            }
        }
        last_tick = level;

        /* ---- compute RPM every SAMPLE_PERIOD_S -------------------- */
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            perror("clock_gettime(CLOCK_MONOTONIC)");
            goto cleanup_all;
        }
        if (elapsed_ms(&last_pulse, &now) >= (double)SAMPLE_PERIOD_S * 1000.0) {
            double rpm = 0.0;
            if (pulse_count > 0)
                rpm = (double)pulse_count * 60.0 / (double)SAMPLE_PERIOD_S;

            if (log_rpm(log_fp, rpm) != 0)
                fprintf(stderr, "Warning: failed to log RPM data\n");

            printf("RPM: %.2f\n", rpm);

            pulse_count = 0;
            last_pulse  = now;
        }
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0)
            perror("fclose(log_fp)");
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

