/*
 * Closed-loop proportional solenoid valve flow control for Raspberry Pi 4.
 *
 * Hardware:
 *   - ASCO RedHat 8210 series proportional solenoid valve
 *       PWM drive line  -> GPIO 18 (BCM, hardware PWM0)
 *       Enable/Dir line -> GPIO 23 (BCM, active-high)
 *   - YF-S201 flow sensor
 *       Flow output     -> GPIO 24 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_control flow_control.c -lpigpio -lrt
 * Run:
 *   sudo ./flow_control -t 1.0
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define VALVE_PWM_PIN        18          /* BCM 18 — hardware PWM0 */
#define VALVE_ENABLE_PIN     23          /* BCM 23 — valve enable/direction */
#define FLOW_SENSOR_PIN      24          /* BCM 24 — flow sensor interrupt */

#define PWM_FREQUENCY_HZ     1000        /* 1 kHz PWM carrier */
#define PWM_RANGE            255         /* 8-bit resolution */
#define PWM_DUTY_MIN         0
#define PWM_DUTY_MAX         255

#define SAMPLE_PERIOD_US     100000      /* 100 ms between samples */
#define DEBOUNCE_US          2000        /* 2 ms debounce on flow edges */

#define LOG_FILE             "flow_log.csv"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static volatile uint32_t     g_last_tick   = 0;
static volatile bool         g_pulse_armed = true;

static double g_target_flow_rate = 0.0;
static FILE   *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static void flow_isr(int gpio, int level, uint32_t tick, void *userdata);
static void log_data(double flow_rate, int valve_position);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Flow sensor ISR --------------------------- */

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {                       /* rising edge */
        if (g_pulse_armed) {
            g_pulse_count++;
        }
    }
}

/* ----------------------------- Logging ----------------------------------- */

static void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s.%03ld,%.4f,%d\n",
            timestamp, ts.tv_nsec / 1000000L, flow_rate, valve_position);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* Ensure valve is closed (0 % duty) and disable PWM */
    if (gpioInitialise() >= 0) {
        gpioPWM(VALVE_PWM_PIN, 0);
        gpioWrite(VALVE_ENABLE_PIN, 0);
        gpioTerminate();
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(int argc, char *argv[])
{
    /* Parse target flow rate */
    if (argc != 3 || strcmp(argv[1], "-t") != 0) {
        fprintf(stderr,
                "Usage: %s -t <target_flow_rate_lpm>\n"
                "  -t  target flow rate in L/min (required, non-zero)\n",
                argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    g_target_flow_rate = strtod(argv[2], &endptr);
    if (endptr == argv[2] || *endptr != '\0' || g_target_flow_rate <= 0.0) {
        fprintf(stderr,
                "Error: target flow rate must be a positive non-zero number.\n"
                "Usage: %s -t <target_flow_rate_lpm>\n",
                argv[0]);
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure valve enable/direction line as output, initially high */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n",
                VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to drive GPIO %d high.\n",
                VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM on valve PWM pin */
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n",
                VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n",
                VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle on GPIO %d.\n",
                VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure flow sensor pin as input with pull-down */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n",
                FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on flow sensor pin (rising edge) */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0,
                         flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n",
                FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_lpm,valve_position\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.4f L/min\n",
           g_target_flow_rate);
    printf("Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* Main control loop */
    while (g_running) {
        /* Snapshot and reset pulse count */
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;
        g_pulse_armed = false;

        /* Debounce: re-arm after debounce window */
        gpioDelay(DEBOUNCE_US);
        g_pulse_armed = true;

        /* Compute flow rate (L/min) from pulses per sample period */
        double flow_rate = (double)pulses * 60.0 / (double)SAMPLE_PERIOD_US;

        /* Proportional controller: Kp = 1.0 */
        double error = g_target_flow_rate - flow_rate;
        double pwm_duty = error;

        /* Clamp to valid PWM range */
        if (pwm_duty < PWM_DUTY_MIN) pwm_duty = PWM_DUTY_MIN;
        if (pwm_duty > PWM_DUTY_MAX) pwm_duty = PWM_DUTY_MAX;

        int valve_position = (int)(pwm_duty + 0.5);

        /* Apply PWM */
        if (gpioPWM(VALVE_PWM_PIN, valve_position) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d.\n",
                    VALVE_PWM_PIN);
        }

        /* Log data */
        log_data(flow_rate, valve_position);

        /* Print status */
        printf("Flow: %.4f L/min | Valve: %d (%.1f%%)\n",
               flow_rate, valve_position,
               (double)valve_position / (double)PWM_RANGE * 100.0);

        /* Sleep for sample period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

