#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LOCK_1_PIN      17
#define LOCK_2_PIN      27
#define BUTTON_PIN      22
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    100000
#define SPI_BITS         8
#define SPI_DELAY_US     0
#define LOG_FILE         "/var/log/door_access.log"
#define RFID_TAG_LENGTH  10
#define DEBOUNCE_US      50000
#define LOCK_HOLD_SEC    5
#define POLL_DELAY_US    100000
#define MAX_RETRIES      4

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void log_event(const char *msg) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_fp);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }
    unsigned char mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    unsigned char bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    return 0;
}

static int spi_transfer(const unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;
    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    return 0;
}

static int rfid_read(unsigned char tag[RFID_TAG_LENGTH]) {
    unsigned char tx[RFID_TAG_LENGTH] = {0};
    unsigned char rx[RFID_TAG_LENGTH] = {0};
    if (spi_transfer(tx, rx, RFID_TAG_LENGTH) < 0) return -1;
    memcpy(tag, rx, RFID_TAG_LENGTH);
    return 0;
}

static int button_pressed(void) {
    return (gpioRead(BUTTON_PIN) == 0);
}

static void lock_engage(void) {
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
}

static void lock_disengage(void) {
    gpioWrite(LOCK_1_PIN, 0);
    gpioWrite(LOCK_2_PIN, 0);
}

static void cleanup(void) {
    lock_engage();
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
    if (g_log_fp) { fclose(g_log_fp); g_log_fp = NULL; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fclose(g_log_fp); g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    lock_engage();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Door access control system started");

    while (g_running) {
        unsigned char tag[RFID_TAG_LENGTH];
        int rc = rfid_read(tag);

        if (rc < 0) {
            log_event("Error: SPI read failure");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (memcmp(tag, "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00", RFID_TAG_LENGTH) == 0) {
            log_event("Info: No RFID tag detected");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (memcmp(tag, "\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0A", RFID_TAG_LENGTH) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Error: Invalid RFID tag (0x%02X%02X%02X%02X%02X%02X%02X%02X%02X%02X)",
                     tag[0], tag[1], tag[2], tag[3], tag[4], tag[5], tag[6], tag[7], tag[8], tag[9]);
            log_event(msg);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_event("Info: Valid RFID tag detected");

        int button_pressed_count = 0;
        while (g_running && button_pressed_count < MAX_RETRIES) {
            if (button_pressed()) {
                button_pressed_count++;
                gpioDelay(DEBOUNCE_US);
            } else {
                gpioDelay(10000);
            }
        }

        if (button_pressed_count >= MAX_RETRIES) {
            log_event("Error: Button not pressed within 4 polls");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_event("Info: Button pressed, disengaging locks");
        lock_disengage();
        gpioDelay(LOCK_HOLD_SEC * 1000000);
        lock_engage();
        log_event("Info: Locks re-engaged");

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Door access control system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

