#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_PERIOD_US 10000
#define PWM_STEPS 100
#define SAMPLE_TIME_MS 100
#define TARGET_SPEED 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6];
static struct gpiod_line *encoder_lines[4];
static int encoder_counts[2] = {0, 0};
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_motor_speed(int motor, double speed) {
    int pwm_value = (int)(speed * 100.0);
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > 100) pwm_value = 100;
    int on_time = (pwm_value * PWM_PERIOD_US) / 100;
    int off_time = PWM_PERIOD_US - on_time;
    int step_us = PWM_PERIOD_US / PWM_STEPS;
    int on_steps = on_time / step_us;
    int off_steps = off_time / step_us;
    if (on_steps == 0) on_steps = 1;
    if (off_steps == 0) off_steps = 1;
    int total_steps = on_steps + off_steps;
    if (total_steps == 0) total_steps = 1;
    int on_us = on_time / on_steps;
    int off_us = off_time / off_steps;
    if (motor == 1) {
        gpiod_line_set_value(motor_lines[0], 1);
        gpiod_line_set_value(motor_lines[1], 1);
        gpiod_line_set_value(motor_lines[2], 0);
        for (int i = 0; i < on_steps; i++) {
            gpiod_line_set_value(motor_lines[3], 1);
            usleep(on_us);
            gpiod_line_set_value(motor_lines[3], 0);
            usleep(off_us);
        }
    } else if (motor == 2) {
        gpiod_line_set_value(motor_lines[4], 1);
        gpiod_line_set_value(motor_lines[5], 1);
        gpiod_line_set_value(motor_lines[3], 0);
        for (int i = 0; i < on_steps; i++) {
            gpiod_line_set_value(motor_lines[5], 1);
            usleep(on_us);
            gpiod_line_set_value(motor_lines[5], 0);
            usleep(off_us);
        }
    }
}

static void stop_motors(void) {
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) gpiod_line_set_value(motor_lines[i], 0);
    }
}

static void *encoder_thread(void *arg) {
    int encoder_id = *(int *)arg;
    int a_pin = (encoder_id == 1) ? ENCODER1_A : ENCODER2_A;
    int b_pin = (encoder_id == 1) ? ENCODER1_B : ENCODER2_B;
    struct gpiod_line *a_line = encoder_lines[encoder_id * 2 - 2];
    struct gpiod_line *b_line = encoder_lines[encoder_id * 2 - 1];
    int last_a = gpiod_line_get_value(a_line);
    if (last_a < 0) {
        fprintf(stderr, "Failed to read encoder %d A line\n", encoder_id);
        return NULL;
    }
    int count = 0;
    while (running) {
        int a = gpiod_line_get_value(a_line);
        int b = gpiod_line_get_value(b_line);
        if (a < 0 || b < 0) {
            fprintf(stderr, "Encoder %d read error\n", encoder_id);
            usleep(10000);
            continue;
        }
        if (a != last_a) {
            if (a == b) count++;
            else count--;
            last_a = a;
        }
        pthread_mutex_lock(&encoder_mutex);
        if (encoder_id == 1) encoder_counts[0] = count;
        else encoder_counts[1] = count;
        pthread_mutex_unlock(&encoder_mutex);
        usleep(1000);
    }
    return NULL;
}

static void log_data(double speed1, double speed2, double pid_output1, double pid_output2, double p_term1, double i_term1, double d_term1, double p_term2, double i_term2, double d_term2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, speed1, speed2, pid_output1, pid_output2, p_term1, i_term1, d_term1, p_term2, i_term2, d_term2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }
    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d\n", motor_pins[i]);
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output\n", motor_pins[i]);
            gpiod_chip_close(chip);
            return 1;
        }
    }
    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d\n", encoder_pins[i]);
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder_control") < 0) {
            fprintf(stderr, "Failed to request encoder line %d events\n", encoder_pins[i]);
            gpiod_chip_close(chip);
            return 1;
        }
    }
    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_close(chip);
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_Speed,Motor2_Speed,Motor1_PID_Output,Motor2_PID_Output,Motor1_P_Term,Motor1_I_Term,Motor1_D_Term,Motor2_P_Term,Motor2_I_Term,Motor2_D_Term\n");
    pthread_t encoder_threads[2];
    int encoder_ids[2] = {1, 2};
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&encoder_threads[i], NULL, encoder_thread, &encoder_ids[i]) != 0) {
            fprintf(stderr, "Failed to create encoder thread %d\n", i + 1);
            stop_motors();
            fclose(log_file);
            gpiod_chip_close(chip);
            return 1;
        }
    }
    double integral1 = 0.0, integral2 = 0.0;
    while (running) {
        pthread_mutex_lock(&encoder_mutex);
        int counts1 = encoder_counts[0];
        int counts2 = encoder_counts[1];
        encoder_counts[0] = 0;
        encoder_counts[1] = 0;
        pthread_mutex_unlock(&encoder_mutex);
        double speed1 = (double)counts1 * (60000.0 / (SAMPLE_TIME_MS * 1000.0));
        double speed2 = (double)counts2 * (60000.0 / (SAMPLE_TIME_MS * 1000.0));
        double error1 = TARGET_SPEED - speed1;
        double error2 = TARGET_SPEED - speed2;
        integral1 += error1;
        integral2 += error2;
        if (integral1 > 1000.0) integral1 = 1000.0;
        if (integral1 < -1000.0) integral1 = -1000.0;
        if (integral2 > 1000.0) integral2 = 1000.0;
        if (integral2 < -1000.0) integral2 = -1000.0;
        double d_term1 = (error1 - error1) / SAMPLE_TIME_MS;
        double d_term2 = (error2 - error2) / SAMPLE_TIME_MS;
        double pid_output1 = KP * error1 + KI * integral1 + KD * d_term1;
        double pid_output2 = KP * error2 + KI * integral2 + KD * d_term2;
        set_motor_speed(1, pid_output1);
        set_motor_speed(2, pid_output2);
        log_data(speed1, speed2, pid_output1, pid_output2, KP * error1, KI * integral1, KD * d_term1, KP * error2, KI * integral2, KD * d_term2);
        usleep(SAMPLE_TIME_MS * 1000);
    }
    stop_motors();
    for (int i = 0; i < 2; i++) pthread_join(encoder_threads[i], NULL);
    fclose(log_file);
    for (int i = 0; i < 6; i++) gpiod_line_release(motor_lines[i]);
    for (int i = 0; i < 4; i++) gpiod_line_release(encoder_lines[i]);
    gpiod_chip_close(chip);
    return 0;
}

