#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5C
#define I2C_BUS "/dev/i2c-1"
#define RELAY_GPIO 17
#define NUM_ELECTRODES 12

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_ELECTRODE_CURRENT 0x5D
#define MPR121_FILTER_CONFIG 0x5C
#define MPR121_CHARGE_TIME 0x5B
#define MPR121_RELEASE_TIME 0x5C
#define MPR121_TOUCH_THRESH_BASE 0x41
#define MPR121_RELEASE_THRESH_BASE 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;
    usleep(1000);

    if (i2c_write_reg8(fd, MPR121_FILTER_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CHARGE_TIME, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_RELEASE_TIME, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2c_write_reg8(fd, MPR121_TOUCH_THRESH_BASE + 2 * i, 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_RELEASE_THRESH_BASE + 2 * i, 0x0A) < 0) return -1;
    }

    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODE_CURRENT, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8F) < 0) return -1;

    usleep(100000);
    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static int relay_toggle(void) {
    int val = gpiod_line_get_value(relay_line);
    if (val < 0) {
        perror("gpiod_line_get_value failed");
        return -1;
    }
    val = !val;
    if (gpiod_line_set_value(relay_line, val) < 0) {
        perror("gpiod_line_set_value failed");
        return -1;
    }
    return val;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        close(i2c_fd);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("gpiod_line_request_output failed");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("MPR121 initialized. Monitoring touch...\n");

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        if (touch_status > 0) {
            int relay_state = relay_toggle();
            if (relay_state >= 0) {
                printf("Touch detected! Relay toggled to %d\n", relay_state);
            } else {
                fprintf(stderr, "Relay toggle failed\n");
            }
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

