#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_STEP_MS 50
#define MAX_STEP_MS 200
#define MIN_PATTERN_STEPS 5
#define MAX_PATTERN_STEPS 15
#define PATTERN_GEN_DELAY_MS 100

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

static int generate_pattern(int *motor1_duty, int *motor2_duty, int *step_duration_ms, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        motor1_duty[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        motor2_duty[i] = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        step_duration_ms[i] = rand() % (MAX_STEP_MS - MIN_STEP_MS + 1) + MIN_STEP_MS;
    }
    return 0;
}

static int play_pattern(const int *motor1_duty, const int *motor2_duty, const int *step_duration_ms, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        if (gpioPWM(MOTOR1_PIN, motor1_duty[i]) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", MOTOR1_PIN);
            return -1;
        }
        if (gpioPWM(MOTOR2_PIN, motor2_duty[i]) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", MOTOR2_PIN);
            return -1;
        }
        gpioDelay(step_duration_ms[i] * 1000);
    }
    return 0;
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int *motor1_duty = NULL;
    int *motor2_duty = NULL;
    int *step_duration_ms = NULL;

    while (!shutdown_flag) {
        int num_steps = rand() % (MAX_PATTERN_STEPS - MIN_PATTERN_STEPS + 1) + MIN_PATTERN_STEPS;

        motor1_duty = (int *)realloc(motor1_duty, num_steps * sizeof(int));
        motor2_duty = (int *)realloc(motor2_duty, num_steps * sizeof(int));
        step_duration_ms = (int *)realloc(step_duration_ms, num_steps * sizeof(int));

        if (motor1_duty == NULL || motor2_duty == NULL || step_duration_ms == NULL) {
            fprintf(stderr, "Error: memory allocation failed.\n");
            break;
        }

        if (generate_pattern(motor1_duty, motor2_duty, step_duration_ms, num_steps) != 0) {
            fprintf(stderr, "Error: pattern generation failed.\n");
            break;
        }

        if (play_pattern(motor1_duty, motor2_duty, step_duration_ms, num_steps) != 0) {
            fprintf(stderr, "Error: pattern playback failed.\n");
            break;
        }

        gpioDelay(PATTERN_GEN_DELAY_MS * 1000);
    }

    free(motor1_duty);
    free(motor2_duty);
    free(step_duration_ms);

    cleanup();
    return 0;
}

