#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

#define READ_TIMEOUT_US 500000
#define READ_INTERVAL_US 500000
#define CALIBRATION_SAMPLES 100
#define WEIGHT_THRESHOLD 10.0

static volatile sig_atomic_t running = 1;

static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: calibration file not found, using defaults (scale=1.0, offset=0.0)\n");
        return -1;
    }
    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: calibration file invalid, using defaults (scale=1.0, offset=0.0)\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration loaded: scale=%lf, offset=%lf\n", scale_factor, offset);
    return 0;
}

static int write_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error writing calibration file");
        return -1;
    }
    fprintf(fp, "%lf %lf\n", scale_factor, offset);
    fclose(fp);
    return 0;
}

static int read_hx711(void) {
    int32_t data = 0;
    int timeout = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    while (gpioRead(HX711_DATA_PIN) && timeout < READ_TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= READ_TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 data pin timeout\n");
        return -1;
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static double calculate_weight(int32_t raw_value) {
    return (double)raw_value / scale_factor - offset;
}

static int calibrate_sensor(void) {
    double sum = 0.0;
    int valid_samples = 0;

    printf("Calibrating sensor... Remove all weight and press Enter.\n");
    getchar();

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw = read_hx711();
        if (raw < 0) {
            fprintf(stderr, "Warning: calibration read %d failed\n", i);
            continue;
        }
        sum += (double)raw;
        valid_samples++;
        gpioDelay(10000);
    }

    if (valid_samples == 0) {
        fprintf(stderr, "Error: no valid calibration samples\n");
        return -1;
    }

    offset = sum / valid_samples;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", s, weight);
    fclose(fp);
}

static void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1);
        printf("Solenoid engaged (weight: %.2f kg)\n", weight);
    } else {
        gpioWrite(SOLENOID_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0);

    if (read_calibration() != 0) {
        if (calibrate_sensor() != 0) {
            fprintf(stderr, "Sensor calibration failed\n");
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting weight monitoring... Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711();
        if (raw < 0) {
            fprintf(stderr, "Skipping iteration due to read error\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw);
        log_weight(weight);
        control_solenoid(weight);

        gpioDelay(READ_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

