    fprintf(fp, "%s, %.2f\n", s, weight);
    fclose(fp);
}

static void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1);
        printf("Solenoid engaged (weight: %.2f kg)\n", weight);
    } else {
        gpioWrite(SOLENOID_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0);

    if (read_calibration() != 0) {
        if (calibrate_sensor() != 0) {
            fprintf(stderr, "Sensor calibration failed\n");
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting weight monitoring... Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711();
        if (raw < 0) {
            fprintf(stderr, "Skipping iteration due to read error\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw);
        log_weight(weight);
        control_solenoid(weight);

        gpioDelay(READ_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

