#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define RAIN_THRESHOLD 3
#define MOTOR_DUTY_CYCLE 150
#define MOTOR_PWM_FREQ 1000
#define MOTOR_RUN_TIME_S 5
#define SENSOR_CHECK_INTERVAL_S 60
#define POST_OPERATION_COOLDOWN_S 60

#define LOG_FILE "/var/log/window_control.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val < 0) {
            syslog(LOG_ERR, "Error reading rain sensor on GPIO%d: %d", RAIN_SENSOR_PIN, val);
            return -1;
        }
        if (val == 0) low_count++;
        if (i < DEBOUNCE_READINGS - 1) gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

static int control_motor(int close_window) {
    if (gpioWrite(MOTOR_IN1_PIN, close_window ? 1 : 0) < 0) {
        syslog(LOG_ERR, "Failed to write IN1 (GPIO%d)", MOTOR_IN1_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, close_window ? 0 : 1) < 0) {
        syslog(LOG_ERR, "Failed to write IN2 (GPIO%d)", MOTOR_IN2_PIN);
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, close_window ? MOTOR_DUTY_CYCLE : 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on GPIO%d", MOTOR_PWM_PIN);
        return -1;
    }
    return 0;
}

static void log_event(const char *event_type, int rain_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s - %s - Rain: %s\n", timestamp, event_type, rain_detected ? "Yes" : "No");
        fflush(log_file);
    }
    syslog(LOG_INFO, "%s - %s - Rain: %s", timestamp, event_type, rain_detected ? "Yes" : "No");
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
}

