    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register signal handlers");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Window control system started");

    while (program_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            syslog(LOG_ERR, "Sensor read error, retrying in 1s");
            sleep(1);
            continue;
        }

        if (rain) {
            log_event("Rain detected", 1);
            syslog(LOG_INFO, "Rain detected, closing window");

            if (control_motor(1) < 0) {
                syslog(LOG_ERR, "Motor control failed");
            } else {
