                sleep(MOTOR_RUN_TIME_S);
                if (control_motor(0) < 0) {
                    syslog(LOG_ERR, "Motor stop failed");
                } else {
                    log_event("Window closed", 1);
                }
            }

            sleep(POST_OPERATION_COOLDOWN_S);
        } else {
            log_event("No rain", 0);
            sleep(SENSOR_CHECK_INTERVAL_S);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

