#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_hx711(long *raw_value) {
    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) != 0) {
        log_event("Error setting HX711 DT pin as input");
        return -1;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0) {
        log_event("Error setting HX711 SCK pin as output");
        return -1;
    }
    if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
        log_event("Error resetting HX711 SCK pin");
        return -1;
    }

    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DT_PIN) == 1) {
        if ((gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            log_event("HX711 timeout waiting for data line to go low");
            return -1;
        }
        gpioDelay(10);
    }

    unsigned long count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
            log_event("Error setting HX711 SCK high");
            return -1;
        }
        gpioDelay(1);
        count <<= 1;
        if (gpioRead(HX711_DT_PIN) == 1) {
            count++;
        }
        if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
            log_event("Error setting HX711 SCK low");
            return -1;
        }
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK_PIN, 1) != 0) {
        log_event("Error setting HX711 SCK high for gain 128");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) != 0) {
        log_event("Error setting HX711 SCK low after gain 128");
        return -1;
    }
    gpioDelay(1);

    if (count & 0x800000) {
        count |= 0xFF000000;
    }

    *raw_value = (long)count;
    return 0;
}

static double convert_to_grams(long raw_value) {
    return (double)raw_value / 1000.0;
}

static void activate_solenoid(int duration_seconds) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        log_event("Error activating solenoid (GPIO write high failed)");
        return;
    }
    log_event("Solenoid lock activated");
    sleep(duration_seconds);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Error deactivating solenoid (GPIO write low failed)");
        return;
    }
    log_event("Solenoid lock deactivated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        log_event("Error setting solenoid pin as output");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Error initializing solenoid pin to low");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (running) {
        long raw_value = 0;
        if (read_hx711(&raw_value) != 0) {
            log_event("Error reading HX711 sensor");
        } else {
            double weight = convert_to_grams(raw_value);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
            log_event(log_message);

            if (weight < WEIGHT_THRESHOLD) {
                log_event("Weight below threshold, activating solenoid lock");
                activate_solenoid(LOCK_DURATION);
            }
        }
        sleep(1);
    }

    log_event("System shutting down");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

