/*
 * Raspberry Pi 4 Model B — HX711 Load Cell Reader with Solenoid Door Lock
 *
 * Wiring:
 *   HX711 DATA  -> GPIO4  (BCM 4)
 *   HX711 CLK   -> GPIO17 (BCM 17)
 *   Solenoid    -> GPIO27 (BCM 27)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hx711_lock hx711_lock.c -lpigpio -lrt
 * Run:
 *   sudo ./hx711_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HX711_DATA_PIN    4
#define HX711_CLOCK_PIN   17
#define SOLENOID_PIN      27

#define WEIGHT_THRESHOLD  5.0f   /* kg */
#define CALIBRATION_FILE  "calibration.txt"
#define LOG_FILE          "security.log"

#define CALIBRATION_TIMEOUT_US 100000   /* 100 ms */
#define HX711_TIMEOUT_US       100000   /* 100 ms */
#define SOLENOID_HOLD_US       5000000  /* 5 s   */
#define SAMPLE_INTERVAL_US     100000   /* 100 ms */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static FILE *g_cal_fp = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  read_hx711_raw(int32_t *out);
static float calibrate_hx711(void);
static int  save_calibration(float factor);
static float load_calibration(void);
static void log_event(float weight);
static void activate_solenoid(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- HX711 read ------------------------------ */
/*
 * Read 24 bits from the HX711, then pulse the clock to set the chip
 * into power-down mode.  Returns 0 on success, -1 on timeout or error.
 */
static int read_hx711_raw(int32_t *out)
{
    if (out == NULL)
        return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if ((gpioTick() - start) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t count = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "gpioWrite(clock high) failed\n");
            return -1;
        }
        gpioDelay(1);

        count <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1)
            count |= 1;

        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "gpioWrite(clock low) failed\n");
            return -1;
        }
        gpioDelay(1);
    }

    /* 25th pulse: set chip into power-down mode */
    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(clock high) failed\n");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(clock low) failed\n");
        return -1;
    }
    gpioDelay(1);

    /* Convert 24-bit two's-complement to signed 32-bit */
    if (count & 0x800000)
        count |= 0xFF000000;

    *out = (int32_t)count;
    return 0;
}

/* --------------------------- Calibration storage -------------------------- */
static float calibrate_hx711(void)
{
    printf("Place a known weight on the load cell and press Enter.\n");
    printf("When ready, the raw value will be printed. Record this value.\n");
    (void)getchar();

    int32_t raw;
    if (read_hx711_raw(&raw) != 0) {
        fprintf(stderr, "Calibration failed: HX711 read error\n");
        return 0.0f;
    }
    printf("Raw value: %d\n", raw);
    return (float)raw;
}

static int save_calibration(float factor)
{
    if (g_cal_fp == NULL) {
        g_cal_fp = fopen(CALIBRATION_FILE, "w");
        if (g_cal_fp == NULL) {
            perror("fopen(" CALIBRATION_FILE ")");
            return -1;
        }
    }
    if (fprintf(g_cal_fp, "%.6f\n", factor) < 0) {
        perror("fprintf(calibration)");
        return -1;
    }
    if (fflush(g_cal_fp) != 0) {
        perror("fflush(calibration)");
        return -1;
    }
    return 0;
}

static float load_calibration(void)
{
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        perror("fopen(" CALIBRATION_FILE ")");
        return 0.0f;
    }

    float factor = 0.0f;
    if (fscanf(fp, "%f", &factor) != 1) {
        fprintf(stderr, "Calibration file is empty or invalid\n");
        factor = 0.0f;
    }
    fclose(fp);
    fp = NULL;
    return factor;
}

/* ------------------------------- Logging ---------------------------------- */
static void log_event(float weight)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (g_log_fp == NULL) {
            perror("fopen(" LOG_FILE ")");
            return;
        }
    }

    if (fprintf(g_log_fp, "%s, Weight: %.2f kg\n", ts, weight) < 0)
        perror("fprintf(log)");
    else if (fflush(g_log_fp) != 0)
        perror("fflush(log)");
}

/* --------------------------- Solenoid activation -------------------------- */
static void activate_solenoid(void)
{
    printf("Weight threshold exceeded! Activating solenoid.\n");
    if (gpioWrite(SOLENOID_PIN, 1) < 0)
        fprintf(stderr, "Failed to set solenoid pin high\n");
    else {
        /* Hold for 5 s, checking g_running so SIGINT can interrupt */
        uint32_t hold_start = gpioTick();
        while (g_running && (gpioTick() - hold_start) < SOLENOID_HOLD_US)
            gpioDelay(100000);

        if (gpioWrite(SOLENOID_PIN, 0) < 0)
            fprintf(stderr, "Failed to set solenoid pin low\n");
        else
            printf("Solenoid deactivated.\n");
    }
}

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Ensure solenoid is released */
    if (gpioInitialise() >= 0) {
        gpioWrite(SOLENOID_PIN, 0);
        gpioTerminate();
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cal_fp != NULL) {
        fclose(g_cal_fp);
        g_cal_fp = NULL;
    }
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(HX711_DATA) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(HX711_CLOCK) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SOLENOID) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with clock low */
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(clock low) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure solenoid is off */
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(solenoid off) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Load calibration factor */
    float calibration_factor = load_calibration();
    if (calibration_factor == 0.0f) {
        printf("No valid calibration factor found. Starting calibration.\n");
        calibration_factor = calibrate_hx711();
        if (calibration_factor == 0.0f) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        if (save_calibration(calibration_factor) != 0) {
            fprintf(stderr, "Warning: could not save calibration factor.\n");
        }
    }
    printf("Calibration factor: %.6f\n", calibration_factor);

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int32_t raw;
        if (read_hx711_raw(&raw) != 0) {
            fprintf(stderr, "HX711 read error — skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float weight = (float)raw / calibration_factor;

        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            activate_solenoid();
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

