#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int toggle_relay(int current_state) {
    int new_state = !current_state;
    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Failed to write to relay pin\n");
        return -1;
    }
    return new_state;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to initialize relay state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin\n");
            log_event("Error reading sensor pin");
            gpioDelay(100000);
            continue;
        }

        if (sensor_value == 0) {
            int new_state = toggle_relay(relay_state);
            if (new_state >= 0) {
                relay_state = new_state;
                char log_message[64];
                snprintf(log_message, sizeof(log_message),
                         "Obstacle detected, relay toggled to %s",
                         relay_state ? "ON" : "OFF");
                log_event(log_message);
            }
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

