        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin\n");
            log_event("Error reading sensor pin");
            gpioDelay(100000);
            continue;
        }

        if (sensor_value == 0) {
            int new_state = toggle_relay(relay_state);
            if (new_state >= 0) {
