                         relay_state ? "ON" : "OFF");
                log_event(log_message);
            }
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

