/*
 * watering.c — Raspberry Pi 3 Model B+
 *
 * Reads a duration (1–3600 s) from watering.conf (duration=<seconds>),
 * drives GPIO18 (BCM) high to energise a solenoid valve via an
 * external N-channel MOSFET or relay module, waits the configured
 * duration, then drives the line low and exits.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_PIN    18          /* BCM 18 */
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_stop = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                        */
/* ------------------------------------------------------------------ */

/*
 * Reads "duration=<seconds>" from CONFIG_FILE.
 * Returns 0 on success and stores duration in *out_duration;
 * returns -1 on any error.
 */
static int read_duration_from_config(int *out_duration)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open '%s': %s\n",
                CONFIG_FILE, strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        /* Strip trailing whitespace / newline */
        line[strcspn(line, "\r\n")] = '\0';

        /* Skip empty lines and comments */
        if (line[0] == '\0' || line[0] == '#')
            continue;

        if (sscanf(line, "duration=%d", out_duration) == 1) {
            if (*out_duration >= MIN_DURATION && *out_duration <= MAX_DURATION) {
                found = 1;
                break;
            }
            fprintf(stderr,
                    "Error: duration out of range (%d–%d).\n",
                    MIN_DURATION, MAX_DURATION);
            fclose(fp);
            return -1;
        }
        fprintf(stderr, "Error: malformed line in '%s'.\n", CONFIG_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: read error on '%s': %s\n",
                CONFIG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (!found) {
        fprintf(stderr, "Error: 'duration=<seconds>' not found in '%s'.\n",
                CONFIG_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing '%s': %s\n",
                CONFIG_FILE, strerror(errno));
        /* Non-fatal: we have the value already. */
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /*
     * Set the line to a safe default: valve OFF.
     * active-low: 0 = valve OFF, 1 = valve ON.
     */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure valve is OFF before releasing the line. */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, 0) during cleanup failed.\n",
                GPIO_PIN);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    int duration = 0;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (initialize_gpio() != 0)
        return EXIT_FAILURE;

    printf("Watering system started. Reading configuration...\n");

    if (read_duration_from_config(&duration) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Configuration loaded: duration = %d seconds\n", duration);

    /* Activate valve (active-low: 1 = ON) */
    if (gpioWrite(GPIO_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate valve on GPIO%d.\n", GPIO_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    printf("Valve activated on GPIO%d.\n", GPIO_PIN);

    /*
     * Interruptible sleep so SIGINT/SIGTERM can interrupt the
     * watering cycle and turn the valve off promptly.
     */
    while (duration > 0 && !g_stop) {
        unsigned int sleep_seconds = (unsigned int)((duration > 60)
                                                    ? 60
                                                    : (unsigned int)duration);
        unsigned int remaining = sleep_seconds;

        while (remaining > 0 && !g_stop) {
            unsigned int chunk = (remaining > 60) ? 60 : remaining;
            remaining -= chunk;
            sleep(chunk);
        }

        if (g_stop)
            break;

        duration -= sleep_seconds;
    }

    /* Deactivate valve (active-low: 0 = OFF) */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate valve on GPIO%d.\n",
                GPIO_PIN);
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    printf("Valve deactivated on GPIO%d.\n", GPIO_PIN);

    cleanup_gpio();

    if (g_stop)
        printf("Watering system interrupted.\n");
    else
        printf("Watering cycle complete.\n");

    return EXIT_SUCCESS;
}

