#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27

#define MOTOR_LEFT_PWM_PIN 22
#define MOTOR_RIGHT_PWM_PIN 23

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define BASE_SPEED         150
#define SAMPLE_DELAY_US    10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int set_motor_speed(int left_speed, int right_speed) {
    int rc = 0;
    if (left_speed < 0 || left_speed > PWM_RANGE) {
        fprintf(stderr, "Invalid left motor speed: %d\n", left_speed);
        return -1;
    }
    if (right_speed < 0 || right_speed > PWM_RANGE) {
        fprintf(stderr, "Invalid right motor speed: %d\n", right_speed);
        return -1;
    }
    if (gpioPWM(MOTOR_LEFT_PWM_PIN, left_speed) < 0) {
        fprintf(stderr, "Error setting left motor PWM: %s\n", pigpio_error(rc));
        rc = -1;
