#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, msg);
    fflush(log_file);
}

static int read_lux(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_ONE_TIME_HIGH_RES) < 0) {
        log_message("Error: Failed to send measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    int raw = i2cReadWordData(i2c_handle, 0);
    if (raw < 0) {
        log_message("Error: Failed to read lux value from BH1750");
        return -1;
    }
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        log_message("Error: Failed to write to relay GPIO");
        return;
    }
    log_message(state ? "Relay turned ON" : "Relay turned OFF");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    while (running) {
        float lux = 0.0f;
        if (read_lux(&lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);
            if (lux < LUX_THRESHOLD) {
                control_relay(1);
            } else {
                control_relay(0);
            }
        } else {
            log_message("Sensor read failed, skipping cycle");
        }
        gpioDelay(500000);
    }

    log_message("Program exiting");
    control_relay(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

