#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_LOCK_PULSE_WIDTH  1000   /* ~0 degrees   */
#define SERVO_UNLOCK_PULSE_WIDTH 2000   /* ~180 degrees */
#define DEBOUNCE_DELAY_US       100000 /* 100 ms       */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int angle)
{
    int pulse_width;

    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle %d (must be 0-180).\n", angle);
        return -1;
    }

    pulse_width = 500 + (angle * 2000) / 180;

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d us.\n", pulse_width);
        return -1;
    }

    return 0;
}

static int lock_door(void)
{
    if (set_servo_angle(0) != 0)
        return -1;
    printf("Door locked.\n");
    fflush(stdout);
    return 0;
}

static int unlock_door(void)
{
    if (set_servo_angle(180) != 0)
        return -1;
    printf("Door unlocked.\n");
    fflush(stdout);
    return 0;
}

int main(void)
{
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Ensure servo is off before configuring pins */
    gpioServo(SERVO_PIN, 0);

    /* Configure button pins as inputs with pull-up resistors */
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", LOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not install SIGINT handler.\n");
    }

    printf("Door lock control system started.\n");
    printf("  Servo: GPIO%d\n", SERVO_PIN);
    printf("  Lock:  GPIO%d (active-low)\n", LOCK_BUTTON_PIN);
    printf("  Unlock: GPIO%d (active-low)\n", UNLOCK_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        /* Lock button pressed (active-low) */
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                if (lock_door() != 0)
                    fprintf(stderr, "Warning: Lock operation failed.\n");
            }
        }

        /* Unlock button pressed (active-low) */
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                if (unlock_door() != 0)
                    fprintf(stderr, "Warning: Unlock operation failed.\n");
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown: stop servo and release pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

