/*
 * Haptic feedback generator for Raspberry Pi 4 Model B.
 *
 * Pulse two Precision Microdrives 310-101 vibration motors sequentially
 * on GPIO17 (BCM) and GPIO27 (BCM), looping repeatedly.
 *
 * NOTE: The PMD-310 is a 3 V, 60 mA motor.  It MUST be driven through an
 * external driver circuit (NPN transistor + flyback diode) rather than
 * directly to a GPIO pin (5 V logic).  The GPIO pins are 3.3 V logic-level
 * and cannot safely drive a 3 V motor.
 *
 * Build:  gcc -O2 -Wall -Wextra -o haptic haptic.c -lpigpio -lrt
 * Run:    sudo ./haptic
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define PULSE_MS_MOTOR1 200
#define PULSE_MS_MOTOR2 300

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_delay_ms(unsigned ms)
{
    if (gpioDelay(ms * 1000) < 0) {
        fprintf(stderr, "Error: gpioDelay(%u ms) failed\n", ms);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Ensure both motor lines are LOW before releasing. */
    (void)safe_write(MOTOR1_PIN, 0);
    (void)safe_write(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure motor pins as outputs, initialise LOW --- */
    if (safe_set_mode(MOTOR1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_write(MOTOR1_PIN, 0) != 0 ||
        safe_write(MOTOR2_PIN, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Haptic feedback generator started.\n");
    printf("Motor 1 on GPIO%d (%d ms), Motor 2 on GPIO%d (%d ms).\n",
           MOTOR1_PIN, PULSE_MS_MOTOR1, MOTOR2_PIN, PULSE_MS_MOTOR2);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main pulsing loop --- */
    while (g_running) {
        /* Motor 1: ON */
        if (safe_write(MOTOR1_PIN, 1) != 0) {
            break;
        }
        if (safe_delay_ms(PULSE_MS_MOTOR1) != 0) {
            break;
        }
        if (safe_write(MOTOR1_PIN, 0) != 0) {
            break;
        }

        /* Motor 2: ON */
        if (safe_write(MOTOR2_PIN, 1) != 0) {
            break;
        }
        if (safe_delay_ms(PULSE_MS_MOTOR2) != 0) {
            break;
        }
        if (safe_write(MOTOR2_PIN, 0) != 0) {
            break;
        }
    }

    /* --- Graceful cleanup --- */
    cleanup();
    printf("\nHaptic feedback generator stopped.\n");
    return EXIT_SUCCESS;
}

