/*
 * sound_alarm.c — Raspberry Pi 5 sound-triggered alarm
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c -lzmq -lpthread
 * Run:    ./sound_alarm <mode>   (mode = sound_sensor | alarm_node)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN  17
#define ALARM_LED_PIN     27
#define ZMQ_ENDPOINT      "tcp://*:5555"
#define ZMQ_SUB_ENDPOINT  "tcp://localhost:5555"
#define ZMQ_TOPIC         "SOUND_ALERTS"
#define POLL_INTERVAL_MS  10
#define ALARM_DURATION_S  1

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ---- GPIO helpers ---- */

static int gpio_init(struct gpiod_chip **chip_out,
                     struct gpiod_line **sound_line_out,
                     struct gpiod_line **alarm_line_out)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
            return -1;
        }
    }

    struct gpiod_line *sound = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound) {
        fprintf(stderr, "Failed to get sound sensor line (GPIO%d): %s\n",
                SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm) {
        fprintf(stderr, "Failed to get alarm LED line (GPIO%d): %s\n",
                ALARM_LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(sound, "sound_alarm") < 0) {
        fprintf(stderr, "Failed to request sound sensor line as input: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(alarm, "sound_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request alarm LED line as output: %s\n",
                strerror(errno));
        gpiod_line_release(sound);
        gpiod_chip_close(chip);
        return -1;
    }

    *chip_out      = chip;
    *sound_line_out = sound;
    *alarm_line_out = alarm;
    return 0;
}

static void gpio_cleanup(struct gpiod_chip *chip,
                         struct gpiod_line *sound,
                         struct gpiod_line *alarm)
{
    if (alarm) {
        gpiod_line_set_value(alarm, 0);
        gpiod_line_release(alarm);
    }
    if (sound)
        gpiod_line_release(sound);
    if (chip)
        gpiod_chip_close(chip);
}

/* ---- ZeroMQ helpers ---- */

static void *zmq_socket_ctx(void)
{
    void *ctx = zmq_ctx_new();
    if (!ctx) {
        fprintf(stderr, "zmq_ctx_new failed: %s\n", zmq_strerror(errno));
        return NULL;
    }
    return ctx;
}

static int zmq_bind(void *ctx, const char *endpoint)
{
    void *sock = zmq_socket(ctx, ZMQ_PUB);
    if (!sock) {
        fprintf(stderr, "zmq_socket(PUB) failed: %s\n", zmq_strerror(errno));
        return -1;
    }
    int hb = 1;
    if (zmq_setsockopt(sock, ZMQ_HEARTBEAT_IVL, &hb, sizeof(hb)) < 0) {
        fprintf(stderr, "zmq_setsockopt(HEARTBEAT_IVL) failed: %s\n",
                zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }
    if (zmq_bind(sock, endpoint) < 0) {
        fprintf(stderr, "zmq_bind(%s) failed: %s\n", endpoint, zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }
    return (int)(intptr_t)sock;
}

static int zmq_connect(void *ctx, const char *endpoint)
{
    void *sock = zmq_socket(ctx, ZMQ_SUB);
    if (!sock) {
        fprintf(stderr, "zmq_socket(SUB) failed: %s\n", zmq_strerror(errno));
        return -1;
    }
    int hb = 1;
    if (zmq_setsockopt(sock, ZMQ_HEARTBEAT_IVL, &hb, sizeof(hb)) < 0) {
        fprintf(stderr, "zmq_setsockopt(HEARTBEAT_IVL) failed: %s\n",
                zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }
    if (zmq_connect(sock, endpoint) < 0) {
        fprintf(stderr, "zmq_connect(%s) failed: %s\n", endpoint, zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }
    if (zmq_setsockopt(sock, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        fprintf(stderr, "zmq_setsockopt(SUBSCRIBE) failed: %s\n",
                zmq_strerror(errno));
        zmq_close(sock);
        return -1;
    }
    return (int)(intptr_t)sock;
}

static void zmq_close_all(void *ctx, int pub_sock, int sub_sock)
{
    if (pub_sock >= 0)
        zmq_close((void *)(intptr_t)pub_sock);
    if (sub_sock >= 0)
        zmq_close((void *)(intptr_t)sub_sock);
    if (ctx)
        zmq_ctx_destroy(ctx);
}

/* ---- Sound sensor mode ---- */

static void *sound_sensor_thread(void *arg)
{
    struct gpiod_line *sound = (struct gpiod_line *)arg;
    void *ctx = zmq_socket_ctx();
    if (!ctx)
        return (void *)(intptr_t)-1;

    int pub_sock = zmq_bind(ctx, ZMQ_ENDPOINT);
    if (pub_sock < 0) {
        zmq_ctx_destroy(ctx);
        return (void *)(intptr_t)-1;
    }

    printf("Sound sensor mode: publishing to %s\n", ZMQ_ENDPOINT);

    while (g_running) {
        int val = gpiod_line_get_value(sound);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n",
                    strerror(errno));
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }
        if (val == 0) {
            char msg[2] = "1";
            if (zmq_send((void *)(intptr_t)pub_sock, msg, 1, 0) < 0) {
                fprintf(stderr, "zmq_send failed: %s\n", zmq_strerror(errno));
            }
        }
        sleep_ms(POLL_INTERVAL_MS);
    }

    zmq_close((void *)(intptr_t)pub_sock);
    zmq_ctx_destroy(ctx);
    return NULL;
}

/* ---- Alarm node mode ---- */

static void *alarm_node_thread(void *arg)
{
    struct gpiod_line *alarm = (struct gpiod_line *)arg;
    void *ctx = zmq_socket_ctx();
    if (!ctx)
        return (void *)(intptr_t)-1;

    int sub_sock = zmq_connect(ctx, ZMQ_SUB_ENDPOINT);
    if (sub_sock < 0) {
        zmq_ctx_destroy(ctx);
        return (void *)(intptr_t)-1;
    }

    printf("Alarm node mode: subscribing to %s\n", ZMQ_SUB_ENDPOINT);

    while (g_running) {
        zmq_msg_t msg;
        int rc = zmq_msg_init(&msg);
        if (rc < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "zmq_msg_init failed: %s\n", zmq_strerror(errno));
            break;
        }
        rc = zmq_recvmsg((void *)(intptr_t)sub_sock, &msg, 0);
        if (rc < 0) {
            if (errno == EINTR) continue;
            if (errno == EAGAIN || errno == ETIMEDOUT) continue;
            fprintf(stderr, "zmq_recvmsg failed: %s\n", zmq_strerror(errno));
            break;
        }

        if (zmq_msg_size(&msg) > 0) {
            printf("Sound detected — alarm ON for %d s\n", ALARM_DURATION_S);
            if (gpiod_line_set_value(alarm, 1) < 0)
                fprintf(stderr, "Failed to set alarm LED on: %s\n",
                        strerror(errno));
            sleep_ms(ALARM_DURATION_S * 1000);
            if (gpiod_line_set_value(alarm, 0) < 0)
                fprintf(stderr, "Failed to set alarm LED off: %s\n",
                        strerror(errno));
        }
        zmq_msg_close(&msg);
    }

    zmq_close((void *)(intptr_t)sub_sock);
    zmq_ctx_destroy(ctx);
    return NULL;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound = NULL;
    struct gpiod_line *alarm = NULL;

    if (strcmp(mode, "sound_sensor") == 0) {
        if (gpio_init(&chip, &sound, &alarm) < 0)
            return EXIT_FAILURE;

        pthread_t tid;
        if (pthread_create(&tid, NULL, sound_sensor_thread, sound) != 0) {
            fprintf(stderr, "pthread_create failed: %s\n", strerror(errno));
            gpio_cleanup(chip, sound, alarm);
            return EXIT_FAILURE;
        }
        pthread_join(tid, NULL);
        gpio_cleanup(chip, sound, alarm);
        return EXIT_SUCCESS;
    }

    if (gpio_init(&chip, NULL, &alarm) < 0)
        return EXIT_FAILURE;

    pthread_t tid;
    if (pthread_create(&tid, NULL, alarm_node_thread, alarm) != 0) {
        fprintf(stderr, "pthread_create failed: %s\n", strerror(errno));
        gpio_cleanup(chip, NULL, alarm);
        return EXIT_FAILURE;
    }
    pthread_join(tid, NULL);
    gpio_cleanup(chip, NULL, alarm);
    return EXIT_SUCCESS;
}

