/*
 * NEC IR Decoder for Raspberry Pi 3 Model B+
 * Sensor : TSOP38238 on GPIO17 (BCM)
 * Broker : localhost:1883
 * Topic  : ir/decoded
 *
 * Build  : gcc -O2 -Wall -Wextra -o ir_nec ir_nec.c -lpigpio -lmosquitto -lrt
 * Run    : sudo ./ir_nec
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO          17
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC       "ir/decoded"
#define MAX_PULSES       100
#define NEC_BITS         32
#define NEC_HDR_MARK    9000
#define NEC_HDR_SPACE   4500
#define NEC_BIT_MARK     560
#define NEC_ONE_SPACE   1690
#define NEC_ZERO_SPACE   560
#define TOLERANCE        300

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_pulses[MAX_PULSES];
static volatile int         g_pulse_count = 0;
static volatile uint32_t    g_last_tick = 0;

static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* NEC decoder                                                         */
/* ------------------------------------------------------------------ */
static bool nec_checksum(uint32_t raw, uint32_t inv)
{
    uint8_t r = raw & 0xFF;
    uint8_t i = inv & 0xFF;
    return (r == (uint8_t)(~i)) &&
           ((raw >> 8) & 0xFF) == (uint8_t)(~((inv >> 8) & 0xFF)) &&
           ((raw >> 16) & 0xFF) == (uint8_t)(~((inv >> 16) & 0xFF)) &&
           ((raw >> 24) & 0xFF) == (uint8_t)(~((inv >> 24) & 0xFF));
}

static bool decode_nec(const uint32_t *p, int n, uint32_t *out)
{
    if (n < 12) return false;

    /* Header: mark ~9000 us, space ~4500 us */
    if (p[0] < NEC_HDR_MARK - TOLERANCE || p[0] > NEC_HDR_MARK + TOLERANCE) return false;
    if (p[1] < NEC_HDR_SPACE - TOLERANCE || p[1] > NEC_HDR_SPACE + TOLERANCE) return false;

    uint32_t raw   = 0;
    uint32_t inv   = 0;

    for (int i = 0; i < NEC_BITS; i++) {
        int idx = 2 + i * 2;
        if (idx + 1 >= n) return false;

        if (p[idx] < NEC_BIT_MARK - TOLERANCE || p[idx] > NEC_BIT_MARK + TOLERANCE) return false;

        if (p[idx + 1] >= NEC_ONE_SPACE - TOLERANCE && p[idx + 1] <= NEC_ONE_SPACE + TOLERANCE) {
            raw   |= (1u << i);
            inv   |= (1u << (NEC_BITS - 1 - i));
        } else if (p[idx + 1] >= NEC_ZERO_SPACE - TOLERANCE && p[idx + 1] <= NEC_ZERO_SPACE + TOLERANCE) {
            /* bit 0 is inverted in NEC */
            if (i == 0) inv |= 1u;
        } else {
            return false;
        }
    }

    if (!nec_checksum(raw, inv)) return false;

    *out = raw;
    return true;
}

/* ------------------------------------------------------------------ */
/* MQTT                                                                */
/* ------------------------------------------------------------------ */
static void mqtt_connect_cb(struct mosquitto *m, void *ud, int rc)
{
    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS)
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
    else
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
}

static void mqtt_disconnect_cb(struct mosquitto *m, void *ud, int rc)
{
    (void)m; (void)ud;
    if (rc != MOSQ_ERR_SUCCESS)
        syslog(LOG_WARNING, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
}

static int mqtt_init(void)
{
    mosquitto_lib_init();
    g_mosq = mosquitto_new(NULL, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        return -1;
    }
    mosquitto_connect_callback_set(g_mosq, mqtt_connect_cb);
    mosquitto_disconnect_callback_set(g_mosq, mqtt_disconnect_cb);
    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    return 0;
}

static void mqtt_publish(uint32_t cmd)
{
    char payload[64];
    snprintf(payload, sizeof(payload),
             "{\"command\":\"0x%08X\"}", cmd);

    int rc = mosquitto_publish(g_mosq, NULL, MQTT_TOPIC,
                               (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS)
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
}

/* ------------------------------------------------------------------ */
/* GPIO alert callback (falling edge)                                  */
/* ------------------------------------------------------------------ */
static void ir_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)userdata;

    if (level != 0) return; /* only falling edges */

    uint32_t elapsed = tick - g_last_tick;
    g_last_tick = tick;

    if (g_pulse_count < MAX_PULSES) {
        g_pulses[g_pulse_count++] = elapsed;
    } else {
        syslog(LOG_WARNING, "Pulse buffer overflow, resetting");
        g_pulse_count = 0;
        return;
    }

    if (g_pulse_count == 12) {
        uint32_t cmd;
        if (decode_nec(g_pulses, g_pulse_count, &cmd)) {
            syslog(LOG_INFO, "Decoded NEC command: 0x%08X", cmd);
            mqtt_publish(cmd);
        } else {
            syslog(LOG_WARNING, "Invalid NEC frame");
        }
        g_pulse_count = 0;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("ir_nec", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_WARNING, "gpioSetPullUpDown failed for GPIO%d", IR_GPIO);
    }

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "gpioSetAlertFuncEx failed for GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR NEC decoder started on GPIO%d", IR_GPIO);

    while (g_running) {
        if (g_mosq) mosquitto_loop(g_mosq, 100, 1);
        usleep(100000);
    }

    syslog(LOG_INFO, "Shutting down");

    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

