    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(IR_GPIO, PI_PUD_UP) != 0) {
        syslog(LOG_WARNING, "gpioSetPullUpDown failed for GPIO%d", IR_GPIO);
    }

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "gpioSetAlertFuncEx failed for GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "IR NEC decoder started on GPIO%d", IR_GPIO);

    while (g_running) {
        if (g_mosq) mosquitto_loop(g_mosq, 100, 1);
        usleep(100000);
    }

    syslog(LOG_INFO, "Shutting down");

    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

