/*
 * Raspberry Pi 3 Model B+ — four BH1750FVI ambient-light sensors on I2C-1.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bh1750_mcast bh1750_mcast.c
 *
 * Each sensor is addressed individually via ioctl(I2C_SLAVE, addr) before
 * sending the one-byte command 0x10 (continuous high-resolution mode, ~120 ms).
 * A 180 ms conversion wait is inserted after each command.
 *
 * Broadcasts UDP multicast packets to 239.255.255.250:5005 once per second.
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <math.h>
#include <netinet/in.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_CMD_OT_H  0x10   /* one-time high-res, ~120 ms */
#define BH1750_CONV_MS  180
#define BH1750_ADDR_BASE 0x5C
#define NUM_SENSORS     4
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define SAMPLE_PERIOD_S 1

static const int sensor_addrs[NUM_SENSORS] = {
    0x5C, 0x5D, 0x5E, 0x5F
};
static const int sensor_ids[NUM_SENSORS] = { 1, 2, 3, 4 };

static volatile sig_atomic_t g_terminate = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_terminate = 1;
}

/* Open /dev/i2c-1 and set the slave address for a single sensor. */
static int i2c_open_sensor(int addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read one lux value from a BH1750FVI.
 * Returns 0 on success and stores the value in *lux; returns -1 on error.
 */
static int bh1750_read(int fd, float *lux)
{
    uint8_t cmd = BH1750_CMD_OT_H;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x%02X): %s\n", cmd,
                w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    /* Wait for the conversion to complete. */
    struct timespec ts = { BH1750_CONV_MS / 1000,
                           (long)(BH1750_CONV_MS % 1000) * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 2 bytes of measurement data. */
    uint8_t buf[2];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != 2) {
        fprintf(stderr, "read: %s\n",
                r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

/*
 * Broadcast a UDP multicast packet containing semicolon-separated
 * sensor_id,lux pairs.  NaN values are represented as "nan".
 */
static void broadcast_data(const float lux[NUM_SENSORS])
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        return;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "inet_pton(%s): invalid address\n", MULTICAST_ADDR);
        close(sockfd);
        return;
    }

    char msg[256];
    size_t off = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i > 0) {
            msg[off++] = ';';
            if (off + 16 > sizeof(msg)) {
                fprintf(stderr, "message buffer overflow\n");
                close(sockfd);
                return;
            }
        }
        if (isnan(lux[i])) {
            snprintf(msg + off, sizeof(msg) - off, "%d,nan", sensor_ids[i]);
        } else {
            snprintf(msg + off, sizeof(msg) - off, "%d,%.1f",
                     sensor_ids[i], lux[i]);
        }
        off = strlen(msg);
    }

    if (sendto(sockfd, msg, off, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
    }

    close(sockfd);
}

int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open each sensor individually so we can target each address. */
    int fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        fds[i] = i2c_open_sensor(sensor_addrs[i]);
        if (fds[i] < 0) {
            fprintf(stderr, "Failed to open sensor %d (addr 0x%02X)\n",
                    sensor_ids[i], sensor_addrs[i]);
            /* Continue with what we have; report the failure in the data. */
        }
    }

    float lux[NUM_SENSORS];
    memset(lux, 0, sizeof(lux));

    while (!g_terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (fds[i] < 0) {
                lux[i] = NAN;
                continue;
            }
            if (bh1750_read(fds[i], &lux[i]) < 0) {
                lux[i] = NAN;
            }
        }

        broadcast_data(lux);

        /* Sleep SAMPLE_PERIOD_S seconds, but wake early on signal. */
        for (int s = 0; s < SAMPLE_PERIOD_S && !g_terminate; s++) {
            sleep(1);
        }
    }

    /* Clean up all file descriptors. */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fds[i] >= 0) {
            close(fds[i]);
        }
    }

    return EXIT_SUCCESS;
}

