/*
 * airflow_logger.c — Raspberry Pi Zero W
 *
 * Reads a Honeywell AWM7300V mass airflow sensor over I2C (bus /dev/i2c-1,
 * address 0x28) and logs timestamped SLPM flow values to airflow_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 * Run:    ./airflow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

/* AWM7300V 14-bit flow data is in the lower 14 bits of the first two bytes. */
#define FLOW_MASK      0x3FFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and target the AWM7300V.                           */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Write a zero-length message to generate a start condition.         */
/* ------------------------------------------------------------------ */
static int i2c_start(int fd)
{
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "I2C start write: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor.                           */
/* ------------------------------------------------------------------ */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Extract the 14-bit flow value from the first two bytes.             */
/* ------------------------------------------------------------------ */
static uint16_t extract_flow(const uint8_t *data)
{
    return ((uint16_t)data[0] << 8) | data[1];
}

/* ------------------------------------------------------------------ */
/* Convert the 14-bit raw value to SLPM.                               */
/* ------------------------------------------------------------------ */
static float raw_to_slpm(uint16_t raw)
{
    /*
     * AWM7300V: 14-bit flow data, LSB = 0.01 SLPM.
     * The 14-bit value is left-justified in the 16-bit word, so
     * we shift right by 2 to get the true flow count.
     */
    return (float)((raw >> 2) & FLOW_MASK) * 0.01f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flow record to the log file.                   */
/* ------------------------------------------------------------------ */
static int log_flow(FILE *fp, float slpm)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, slpm) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus --------------------------------------------- */
    g_i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (g_i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow logger started.  Bus=%s  Addr=0x%02X  Log=%s\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop --------------------------------------- */
    while (g_running) {
        uint8_t data[2] = {0, 0};
        int ok = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (i2c_start(g_i2c_fd) < 0) {
                if (errno == ENXIO) {
                    fprintf(stderr, "Sensor absent (ENXIO) — retry %d/%d\n",
                            attempt, MAX_RETRIES);
                } else {
                    fprintf(stderr, "I2C start failed (attempt %d/%d): %s\n",
                            attempt, MAX_RETRIES, strerror(errno));
                }
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            if (i2c_read_bytes(g_i2c_fd, data, sizeof(data)) == 0) {
                ok = 1;
                break;
            }

            if (errno == EIO) {
                fprintf(stderr, "I2C bus error (attempt %d/%d): %s\n",
                        attempt, MAX_RETRIES, strerror(errno));
            } else {
                fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                        attempt, MAX_RETRIES, strerror(errno));
            }
            usleep(RETRY_DELAY_MS * 1000);
        }

        if (!ok) {
            fprintf(stderr, "Failed to read sensor after %d attempts.\n",
                    MAX_RETRIES);
            /* Continue running; transient errors may recover. */
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        uint16_t raw = extract_flow(data);
        float slpm = raw_to_slpm(raw);

        if (log_flow(g_log_fp, slpm) < 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        printf("Flow: %.2f SLPM\n", slpm);

        /* Sleep but wake early on SIGINT so the cleanup loop runs. */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; ++s) {
            sleep(1);
        }
    }

    /* ---- Clean shutdown ------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

