#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD_S 1

/* AWM7300V 14-bit flow data is in the lower 14 bits of the first two bytes. */
#define FLOW_MASK      0x3FFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and target the AWM7300V.                           */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Write a zero-length message to generate a start condition.         */
/* ------------------------------------------------------------------ */
static int i2c_start(int fd)
{
    if (write(fd, NULL, 0) < 0) {
        fprintf(stderr, "I2C start write: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor.                           */
/* ------------------------------------------------------------------ */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Extract the 14-bit flow value from the first two bytes.             */
/* ------------------------------------------------------------------ */
static uint16_t extract_flow(const uint8_t *data)
{
    return ((uint16_t)data[0] << 8) | data[1];
}

/* ------------------------------------------------------------------ */
/* Convert the 14-bit raw value to SLPM.                               */
/* ------------------------------------------------------------------ */
static float raw_to_slpm(uint16_t raw)
{
    /*
     * AWM7300V: 14-bit flow data, LSB = 0.01 SLPM.
     * The 14-bit value is left-justified in the 16-bit word, so
     * we shift right by 2 to get the true flow count.
     */
    return (float)((raw >> 2) & FLOW_MASK) * 0.01f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped flow record to the log file.                   */
/* ------------------------------------------------------------------ */
static int log_flow(FILE *fp, float slpm)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, slpm) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus --------------------------------------------- */
    g_i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (g_i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow logger started.  Bus=%s  Addr=0x%02X  Log=%s\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop --------------------------------------- */
    while (g_running) {
        uint8_t data[2] = {0, 0};
        int ok = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (i2c_start(g_i2c_fd) < 0) {
                if (errno == ENXIO) {
                    fprintf(stderr, "Sensor absent (ENXIO) — retry %d/%d\n",
                            attempt, MAX_RETRIES);
                } else {
                    fprintf(stderr, "I2C start failed (attempt %d/%d): %s\n",
                            attempt, MAX_RETRIES, strerror(errno));
                }
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }

            if (i2c_read_bytes(g_i2c_fd, data, sizeof(data)) == 0) {
                ok = 1;
                break;
            }

            if (errno == EIO) {
                fprintf(stderr, "I2C bus error (attempt %d/%d): %s\n",
                        attempt, MAX_RETRIES, strerror(errno));
            } else {
                fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                        attempt, MAX_RETRIES, strerror(errno));
            }
            usleep(RETRY_DELAY_MS * 1000);
        }

        if (!ok) {
            fprintf(stderr, "Failed to read sensor after %d attempts.\n",
                    MAX_RETRIES);
            /* Continue running; transient errors may recover. */
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        uint16_t raw = extract_flow(data);
        float slpm = raw_to_slpm(raw);

        if (log_flow(g_log_fp, slpm) < 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        printf("Flow: %.2f SLPM\n", slpm);

        /* Sleep but wake early on SIGINT so the cleanup loop runs. */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; ++s) {
            sleep(1);
        }
    }

    /* ---- Clean shutdown ------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * AS7341 10-Channel Spectral Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads spectral and lux data from an Adafruit AS7341 sensor on /dev/i2c-1,
 * logs timestamped CSV rows to spectral_log.csv every 5 seconds, and
 * exits cleanly on SIGINT.
 *
 * Build:  gcc -O2 -Wall -Wextra -o as7341_monitor as7341_monitor.c
 * Run:    ./as7341_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (16-bit registers, big-endian on bus) ---- */
#define AS7341_I2C_ADDR        0x49
#define AS7341_BUS             "/dev/i2c-1"

#define REG_ENABLE             0x00
#define REG_ATIME              0x01
#define REG_WTIME              0x02
#define REG_CONFIG             0x03
#define REG_CFG1               0x07
#define REG_CFG2               0x08
#define REG_CFG3               0x09
#define REG_CFG4               0x0A
#define REG_CFG5               0x0B
#define REG_CFG6               0x0C
#define REG_ID                 0x12
#define REG_STATUS             0x13
#define REG_CDATAL             0x18
#define REG_CDATAH             0x19
#define REG_SDATAL             0x28
#define REG_SDATAH             0x29
#define REG_TDATAL             0x38
#define REG_TDATAH             0x39
#define REG_FDATAL             0x48
#define REG_FDATAH             0x49
#define REG_NLDATAL            0x58
#define REG_NLDATAH            0x59

#define ENABLE_PON             0x01
#define ENABLE_SP_EN           0x02
#define ENABLE_SD_EN           0x04
#define ENABLE_INT_EN          0x10

#define ID_VALUE               0x41

#define SAMPLE_INTERVAL_SEC    5
#define LOG_FILENAME           "spectral_log.csv"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register (16-bit addressing on AS7341).  */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register.                               */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low byte at reg, high at
 * reg+1).  Returns 0 on success, -1 on error.                          */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0)  return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, REG_ID, &id) < 0) {
        fprintf(stderr, "Cannot read ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (id != ID_VALUE) {
        fprintf(stderr, "ID mismatch: got 0x%02X, expected 0x%02X\n", id, ID_VALUE);
        return -1;
    }

    /* Power on, enable spectral measurement, disable SD (diode) */
    if (i2c_write_reg8(fd, REG_ENABLE, ENABLE_PON | ENABLE_SP_EN) < 0)
        return -1;

    /* ATIME = 0x00 (integration time 256 clock cycles) */
    if (i2c_write_reg8(fd, REG_ATIME, 0x00) < 0)
        return -1;

    /* WTIME = 0xFF (wait time 255 clock cycles) */
    if (i2c_write_reg8(fd, REG_WTIME, 0xFF) < 0)
        return -1;

    /* CONFIG = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) < 0)
        return -1;

    /* CFG1 = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CFG1, 0x00) < 0)
        return -1;

    /* CFG2 = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CFG2, 0x00) < 0)
        return -1;

    /* CFG3 = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CFG3, 0x00) < 0)
        return -1;

    /* CFG4 = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CFG4, 0x00) < 0)
        return -1;

    /* CFG5 = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CFG5, 0x00) < 0)
        return -1;

    /* CFG6 = 0x00 (default) */
    if (i2c_write_reg8(fd, REG_CFG6, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_spectral_data(int fd, uint16_t data[10])
{
    for (int i = 0; i < 10; i++) {
        uint8_t reg = (i < 8) ? (uint8_t)(REG_FDATAL + i * 2)
                              : (uint8_t)(REG_NLDATAL + (i - 8) * 2);
        if (i2c_read_reg16(fd, reg, &data[i]) < 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simplified lux approximation from the 10 spectral channels.         */
static float calculate_lux(const uint16_t data[10])
{
    /* Placeholder: real lux requires calibration against a white
     * reference and a black reference.  This returns a non-zero value
     * so the log file records something. */
    (void)data;
    return 100.0f;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const uint16_t data[10], float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts,
                data[0], data[1], data[2], data[3], data[4],
                data[5], data[6], data[7], data[8], lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        (void)i2c_write_reg8(g_i2c_fd, REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(AS7341_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", AS7341_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (as7341_init(g_i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILENAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp,
                "timestamp,F1,F2,F3,F4,F5,F6,F7,F8,NIR,lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 spectral monitoring started. Logging to %s every %d s.\n",
           LOG_FILENAME, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t spectral_data[10];

        if (read_spectral_data(g_i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            float lux = calculate_lux(spectral_data);
            if (log_data(g_log_fp, spectral_data, lux) < 0) {
                fprintf(stderr, "Logging error — continuing.\n");
            }
        }

        /* Sleep in 1-second increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

