        if (i2c_read_reg16(fd, reg, &data[i]) < 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Simplified lux approximation from the 10 spectral channels.         */
static float calculate_lux(const uint16_t data[10])
{
    /* Placeholder: real lux requires calibration against a white
     * reference and a black reference.  This returns a non-zero value
     * so the log file records something. */
    (void)data;
    return 100.0f;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const uint16_t data[10], float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                ts,
                data[0], data[1], data[2], data[3], data[4],
                data[5], data[6], data[7], data[8], lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        (void)i2c_write_reg8(g_i2c_fd, REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(AS7341_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", AS7341_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AS7341_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (as7341_init(g_i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILENAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp,
                "timestamp,F1,F2,F3,F4,F5,F6,F7,F8,NIR,lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 spectral monitoring started. Logging to %s every %d s.\n",
           LOG_FILENAME, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t spectral_data[10];

        if (read_spectral_data(g_i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            float lux = calculate_lux(spectral_data);
            if (log_data(g_log_fp, spectral_data, lux) < 0) {
                fprintf(stderr, "Logging error — continuing.\n");
            }
        }

        /* Sleep in 1-second increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

