/*
 * Omron D7S seismic sensor reader for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration (g) from the D7S over I2C and logs
 * timestamped X/Y/Z data to a CSV file.  Errors are logged to
 * seismic_error.log.  SIGINT/SIGTERM trigger graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_logger seismic_logger.c
 *
 * Defaults:
 *   I2C bus   : /dev/i2c-1
 *   Address   : 0x08 (D7S default)
 *   Interval  : 1 s
 *   CSV file  : seismic_data.csv
 *
 * Usage:
 *   ./seismic_logger [-a i2c_addr] [-i interval_s] [-f csv_file]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS  0x08
#define DEFAULT_INTERVAL_S   1
#define DEFAULT_CSV_FILE     "seismic_data.csv"
#define DEFAULT_ERROR_LOG    "seismic_error.log"
#define I2C_BUS              "/dev/i2c-1"
#define MAX_RETRIES          3
#define RETRY_DELAY_MS       10
#define READ_LEN             6

/* D7S register map (16-bit big-endian, 2-byte data) */
#define D7S_REG_XOUT_L       0x00
#define D7S_REG_XOUT_H       0x01
#define D7S_REG_YOUT_L       0x02
#define D7S_REG_YOUT_H       0x03
#define D7S_REG_ZOUT_L       0x04
#define D7S_REG_ZOUT_H       0x05
#define D7S_REG_STATUS       0x06
#define D7S_REG_CTRL         0x07

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a D7S register; returns 0 on success, -1 on error. */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read `len` bytes starting at `reg`; returns 0 on success, -1 on error. */
static int d7s_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C set register pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/*
 * Read acceleration in g.
 * D7S outputs 16-bit two's-complement data; sensitivity is ±2g
 * => divide by 32768 for g.
 */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t x_buf[READ_LEN], y_buf[READ_LEN], z_buf[READ_LEN];

    if (d7s_read_burst(fd, D7S_REG_XOUT_L, x_buf, READ_LEN) != 0)
        return -1;
    if (d7s_read_burst(fd, D7S_REG_YOUT_L, y_buf, READ_LEN) != 0)
        return -1;
    if (d7s_read_burst(fd, D7S_REG_ZOUT_L, z_buf, READ_LEN) != 0)
        return -1;

    int16_t raw_x = (int16_t)((uint16_t)x_buf[1] << 8 | x_buf[0]);
    int16_t raw_y = (int16_t)((uint16_t)y_buf[1] << 8 | y_buf[0]);
    int16_t raw_z = (int16_t)((uint16_t)z_buf[1] << 8 | z_buf[0]);

    *x = (float)raw_x / 32768.0f;
    *y = (float)raw_y / 32768.0f;
    *z = (float)raw_z / 32768.0f;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    FILE *fp = fopen(DEFAULT_ERROR_LOG, "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    } else {
        fprintf(stderr, "%s: %s (also failed to open error log)\n", ts, msg);
    }
}

static void log_data(FILE *fp, float x, float y, float z)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

int main(int argc, char *argv[])
{
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval_s  = DEFAULT_INTERVAL_S;
    char *csv_file  = DEFAULT_CSV_FILE;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a':
            i2c_address = (int)strtol(optarg, NULL, 0);
            if (i2c_address <= 0 || i2c_address > 0x7F) {
                fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            interval_s = (int)strtol(optarg, NULL, 10);
            if (interval_s <= 0) {
                fprintf(stderr, "Invalid interval: %s\n", optarg);
                return EXIT_FAILURE;
            }
            break;
        case 'f':
            csv_file = optarg;
            break;
        case 'h':
        default:
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f csv_file]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                i2c_address, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    FILE *fp = fopen(csv_file, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open CSV file %s: %s\n", csv_file, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,x_g,y_g,z_g\n");
        fflush(fp);
    }

    printf("Logging D7S data to %s every %d s (I2C addr 0x%02X). Ctrl+C to stop.\n",
           csv_file, interval_s, i2c_address);

    /* Main loop */
    while (g_running) {
        float x, y, z;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
        }

        if (ok) {
            log_data(fp, x, y, z);
        } else {
            log_error("Failed to read acceleration after retries");
        }

        /* Sleep interval_s, but wake early on signal */
        for (int s = 0; s < interval_s && g_running; s++)
            sleep(1);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    fflush(fp);
    fclose(fp);
    close(i2c_fd);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

