#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x5C
#define BH1750_CMD_PWR_ON  0x01
#define BH1750_CMD_RESET   0x07
#define BH1750_CMD_CONT_H  0x10
#define BH1750_CMD_CONT_L  0x20
#define BH1750_CMD_ONE_T   0x21
#define BH1750_CMD_ONE_H   0x22
#define BH1750_CMD_ONE_L   0x23
#define BH1750_CONV_MS     180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_sock_fd = -1;

static void handle_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_cmd(fd, BH1750_CMD_PWR_ON) < 0) return -1;
