/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 *
 * Reads the 8-byte little-endian magic word, validates TLV payloads,
 * extracts range (meters) and velocity (m/s), and logs each detected
 * object to radar_data.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c
 * Run:    ./radar_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include "awr1642_uart.h"

#define UART_DEVICE   "/dev/ttyS0"
#define BAUD_RATE     921600
#define CSV_FILENAME  "radar_data.csv"
#define MAGIC_WORD    0x01020304U
#define FRAME_BUF_SZ  8192
#define TLV_HEADER_SZ 8
#define TLV_TYPE_DETECTED_POINTS 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];
    if (localtime_r(&now, &tm_buf))
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/*
 * Search for the 8-byte magic word in buf[0..len-1].
 * Returns index of the first byte of the magic word, or -1 if not found.
 */
static int find_magic(const uint8_t *buf, size_t len)
{
    if (len < 8)
        return -1;

    for (size_t i = 0; i <= len - 8; i++) {
        if (buf[i]     == (MAGIC_WORD >> 24) &&
            buf[i + 1] == (MAGIC_WORD >> 16) &&
            buf[i + 2] == (MAGIC_WORD >>  8) &&
            buf[i + 3] == (MAGIC_WORD     ))
            return (int)i;
    }
    return -1;
}

/*
 * Process one complete frame starting at *frame_start in buf.
 * frame_len is the number of valid bytes after the magic word.
 * Returns the number of bytes consumed (including magic word).
 */
static size_t process_frame(const uint8_t *frame_start, size_t frame_len,
                            FILE *csv, int *object_index)
{
    if (frame_len < 4) {
        log_error("Frame too short for total packet length");
        return 8;
    }

    uint32_t total_packet_len = (uint32_t)frame_start[4]
                              | ((uint32_t)frame_start[5] << 8)
                              | ((uint32_t)frame_start[6] << 16)
                              | ((uint32_t)frame_start[7] << 24);

    if (total_packet_len < 8 || total_packet_len > frame_len) {
        log_error("Total packet length out of range");
        return 8;
    }

    size_t offset = 8;
    int obj_count = 0;

    while (offset + TLV_HEADER_SZ <= total_packet_len) {
        uint32_t tlv_type = (uint32_t)frame_start[offset]
                          | ((uint32_t)frame_start[offset + 1] << 8)
                          | ((uint32_t)frame_start[offset + 2] << 16)
                          | ((uint32_t)frame_start[offset + 3] << 24);

        uint32_t tlv_len = (uint32_t)frame_start[offset + 4]
                         | ((uint32_t)frame_start[offset + 5] << 8)
                         | ((uint32_t)frame_start[offset + 6] << 16)
                         | ((uint32_t)frame_start[offset + 7] << 24);

        offset += TLV_HEADER_SZ;

        if (offset + tlv_len > total_packet_len) {
            log_error("TLV payload exceeds frame bounds");
            break;
        }

        if (tlv_type == TLV_TYPE_DETECTED_POINTS) {
            if (tlv_len < 4) {
                log_error("Detected points TLV too short");
                break;
            }

            uint16_t num_detected = (uint16_t)frame_start[offset]
                                  | ((uint16_t)frame_start[offset + 1] << 8);

            size_t expected = 4 + (size_t)num_detected * 12;
            if (tlv_len < expected) {
                log_error("Detected points TLV payload truncated");
                break;
            }

            for (uint16_t i = 0; i < num_detected; i++) {
                size_t idx = 4 + i * 12;
                uint16_t range_idx = (uint16_t)frame_start[offset + idx]
                                   | ((uint16_t)frame_start[offset + idx + 1] << 8);
                int16_t  x = (int16_t)frame_start[offset + idx + 2]
                           | ((int16_t)frame_start[offset + idx + 3] << 8);
                int16_t  y = (int16_t)frame_start[offset + idx + 4]
                           | ((int16_t)frame_start[offset + idx + 5] << 8);
                int16_t  z = (int16_t)frame_start[offset + idx + 6]
                           | ((int16_t)frame_start[offset + idx + 7] << 8);
                int16_t  vel = (int16_t)frame_start[offset + idx + 8]
                             | ((int16_t)frame_start[offset + idx + 9] << 8);

                (void)range_idx;

                float range_m = sqrtf((float)x * x + (float)y * y + (float)z * z);
                float vel_mps = (float)vel / 100.0f;

                time_t now = time(NULL);
                struct tm tm_buf;
                char ts[32];
                if (localtime_r(&now, &tm_buf))
                    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
                else
                    snprintf(ts, sizeof(ts), "unknown-time");

                if (fprintf(csv, "%s,%d,%.3f,%.3f\n",
                            ts, *object_index, range_m, vel_mps) < 0) {
                    log_error("fprintf to CSV failed");
                } else {
                    (*object_index)++;
                }
            }
        }

        offset += tlv_len;
    }

    return 8 + total_packet_len;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        return EXIT_FAILURE;
    }

    FILE *csv = fopen(CSV_FILENAME, "a");
    if (!csv) {
        log_error("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    if (fprintf(csv, "timestamp,object_index,range_m,velocity_mps\n") < 0) {
        log_error("Failed to write CSV header");
        fclose(csv);
        return EXIT_FAILURE;
    }
    fflush(csv);

    int object_index = 0;

    uint8_t frame_buf[FRAME_BUF_SZ];
    size_t  frame_len = 0;

    struct awr1642_uart_ctx *ctx = awr1642_uart_open(UART_DEVICE, BAUD_RATE);
    if (!ctx) {
        log_error("awr1642_uart_open failed");
        fclose(csv);
        return EXIT_FAILURE;
    }

    while (g_running) {
        size_t space = FRAME_BUF_SZ - frame_len;
        if (space == 0) {
            /* Buffer full without a magic word — discard to resync */
            frame_len = 0;
            space = FRAME_BUF_SZ;
        }

        size_t n = awr1642_uart_read(ctx, (char *)(frame_buf + frame_len), space);
        if (n == 0) {
            /* No data available right now — brief sleep and retry */
            usleep(10000);
            continue;
        }
        if (n == (size_t)-1) {
            log_error("awr1642_uart_read error");
            break;
        }

        frame_len += n;

        for (;;) {
            int magic_pos = find_magic(frame_buf, frame_len);
            if (magic_pos < 0) {
                /* Discard everything before the last 7 bytes in case a
                   partial magic word spans reads */
                if (frame_len > 7) {
                    size_t keep = frame_len - 7;
                    memmove(frame_buf, frame_buf + frame_len - 7, keep);
                    frame_len = keep;
                }
                break;
            }

            if (magic_pos > 0) {
                /* Discard bytes before the magic word */
                size_t consume = (size_t)magic_pos;
                memmove(frame_buf, frame_buf + consume, frame_len - consume);
                frame_len -= consume;
            }

            if (frame_len < 8) {
                /* Need more data for the full 8-byte magic + header */
                break;
            }

            size_t consumed = process_frame(frame_buf, frame_len, csv, &object_index);
            if (consumed == 0) {
                /* Malformed frame — discard and resync */
                frame_len = 0;
                break;
            }

            if (consumed > frame_len) {
                log_error("Consumed more bytes than available");
                frame_len = 0;
                break;
            }

            size_t remain = frame_len - consumed;
            memmove(frame_buf, frame_buf + consumed, remain);
            frame_len = remain;
        }
    }

    awr1642_uart_close(ctx);
    fflush(csv);
    fclose(csv);

    return EXIT_SUCCESS;
}

