    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        return EXIT_FAILURE;
    }

    FILE *csv = fopen(CSV_FILENAME, "a");
    if (!csv) {
        log_error("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    if (fprintf(csv, "timestamp,object_index,range_m,velocity_mps\n") < 0) {
        log_error("Failed to write CSV header");
        fclose(csv);
        return EXIT_FAILURE;
    }
    fflush(csv);

    int object_index = 0;

    uint8_t frame_buf[FRAME_BUF_SZ];
    size_t  frame_len = 0;

    struct awr1642_uart_ctx *ctx = awr1642_uart_open(UART_DEVICE, BAUD_RATE);
    if (!ctx) {
        log_error("awr1642_uart_open failed");
        fclose(csv);
        return EXIT_FAILURE;
    }

    while (g_running) {
        size_t space = FRAME_BUF_SZ - frame_len;
        if (space == 0) {
            /* Buffer full without a magic word — discard to resync */
            frame_len = 0;
            space = FRAME_BUF_SZ;
        }

        size_t n = awr1642_uart_read(ctx, (char *)(frame_buf + frame_len), space);
        if (n == 0) {
            /* No data available right now — brief sleep and retry */
            usleep(10000);
            continue;
        }
        if (n == (size_t)-1) {
            log_error("awr1642_uart_read error");
            break;
        }

        frame_len += n;

        for (;;) {
            int magic_pos = find_magic(frame_buf, frame_len);
            if (magic_pos < 0) {
                /* Discard everything before the last 7 bytes in case a
                   partial magic word spans reads */
                if (frame_len > 7) {
                    size_t keep = frame_len - 7;
                    memmove(frame_buf, frame_buf + frame_len - 7, keep);
                    frame_len = keep;
                }
                break;
            }

            if (magic_pos > 0) {
                /* Discard bytes before the magic word */
                size_t consume = (size_t)magic_pos;
                memmove(frame_buf, frame_buf + consume, frame_len - consume);
                frame_len -= consume;
            }

            if (frame_len < 8) {
                /* Need more data for the full 8-byte magic + header */
                break;
            }

            size_t consumed = process_frame(frame_buf, frame_len, csv, &object_index);
            if (consumed == 0) {
                /* Malformed frame — discard and resync */
                frame_len = 0;
                break;
            }

            if (consumed > frame_len) {
                log_error("Consumed more bytes than available");
                frame_len = 0;
                break;
            }

            size_t remain = frame_len - consumed;
            memmove(frame_buf, frame_buf + consumed, remain);
            frame_len = remain;
        }
    }

    awr1642_uart_close(ctx);
    fflush(csv);
    fclose(csv);

    return EXIT_SUCCESS;
}

