/*
 * AWR1642 mmWave radar range-detection reader for Raspberry Pi 4.
 *
 * UART:  /dev/serial0  (GPIO14 = RXD, GPIO15 = TXD)
 * Baud:  115200 8N1
 * Format: <unix_timestamp_seconds>,<range_meters>\n
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/select.h>
#include <termios.h>

#define UART_DEVICE   "/dev/serial0"
#define BAUD_RATE     B115200
#define LINE_BUF_SIZE 512
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* UART configuration                                                  */
/* ------------------------------------------------------------------ */

static int configure_uart(int fd)
{
    struct termios tty;

    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    /* 8N1, no flow control, raw mode */
    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  (CLOCAL | CREAD | CS8);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~(OPOST | ONLCR);

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    /* VMIN=0, VTIME=5 → 0.5 s inter-byte timeout */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }

    /* Flush any stale data */
    if (tcflush(fd, TCIOFLUSH) != 0) {
        perror("tcflush");
        /* non-fatal */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Line parsing                                                        */
/* ------------------------------------------------------------------ */

/*
 * Returns 1 on success (timestamp and range parsed),
 * 0 on incomplete line, -1 on parse error.
 */
static int parse_radar_line(const char *line, time_t *timestamp, float *range)
{
    char *endptr = NULL;
    errno = 0;
    long val = strtol(line, &endptr, 10);

    if (errno != 0 || endptr == line) {
        fprintf(stderr, "Parse error: invalid timestamp '%s'\n", line);
        return -1;
    }

    *timestamp = (time_t)val;

    /* Skip comma */
    if (*endptr != ',') {
        fprintf(stderr, "Parse error: missing comma after timestamp\n");
        return -1;
    }
    endptr++;

    char *endptr_range = NULL;
    errno = 0;
    double range_d = strtod(endptr, &endptr_range);

    if (errno != 0 || endptr_range == endptr) {
        fprintf(stderr, "Parse error: invalid range value '%s'\n", endptr);
        return -1;
    }

    *range = (float)range_d;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[LINE_BUF_SIZE];

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (g_uart_fd == -1) {
        perror("open(" UART_DEVICE ")");
        return EXIT_FAILURE;
    }

    if (configure_uart(g_uart_fd) != 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
        return EXIT_FAILURE;
    }

    printf("UART %s configured at 115200 8N1. Reading AWR1642 data...\n",
           UART_DEVICE);
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec  = READ_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int rc = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);

        if (rc == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        }

        if (rc == 0) {
            /* Timeout — sensor may be absent or not sending */
            fprintf(stderr, "Warning: select timeout (no data for %d s)\n",
                    READ_TIMEOUT_SEC);
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (n == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read");
            break;
        }
        if (n == 0) {
            /* Should not happen on a tty, but handle defensively */
            continue;
        }

        read_buf[n] = '\0';

        /* Accumulate bytes into line buffer */
        for (ssize_t i = 0; i < n; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                if (line_len > 0) {
                    time_t ts;
                    float  rng;

                    if (parse_radar_line(line_buf, &ts, &rng) == 0) {
                        struct tm tm_info;
                        char ts_str[32];

                        if (localtime_r(&ts, &tm_info) != NULL &&
                            strftime(ts_str, sizeof(ts_str),
                                     "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                            printf("Timestamp: %s, Range: %.2f meters\n",
                                   ts_str, rng);
                            fflush(stdout);
                        } else {
                            fprintf(stderr,
                                    "Failed to format timestamp\n");
                        }
                    }
                }

                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    /* Line too long — discard and reset */
                    fprintf(stderr,
                            "Warning: line exceeded buffer, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    /* Graceful cleanup */
    if (g_uart_fd != -1) {
        if (close(g_uart_fd) != 0) {
            perror("close");
        }
        g_uart_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

