#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define UART_DEVICE        "/dev/ttyAMA0"
#define BAUD_RATE          115200
#define POLL_INTERVAL_US   100000  /* 100 ms → 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_uart_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin: returns 0 (obstacle) or 1 (clear)                */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Send a string over UART; reports errors but does not abort          */
/* ------------------------------------------------------------------ */
static void send_uart(const char *msg)
{
    if (g_uart_handle < 0) {
        fprintf(stderr, "UART not initialised; cannot send: %s\n", msg);
        return;
    }

    int n = serWrite(g_uart_handle, (char *)msg, strlen(msg));
    if (n < 0) {
        fprintf(stderr, "serWrite failed: %s\n", pigpio_error(n));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — close UART, terminate pigpio, release resources          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- configure sensor pins as inputs with pull-ups ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", LEFT_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", MIDDLE_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", RIGHT_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for pin %d\n", LEFT_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for pin %d\n", MIDDLE_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for pin %d\n", RIGHT_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- open UART ---- */
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        fprintf(stderr, "Failed to open UART %s: %s\n",
                UART_DEVICE, pigpio_error(g_uart_handle));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("KY-033 obstacle detection started.  Press Ctrl-C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        int l = read_sensor(LEFT_SENSOR_PIN);
        int m = read_sensor(MIDDLE_SENSOR_PIN);
        int r = read_sensor(RIGHT_SENSOR_PIN);

        if (l < 0 || m < 0 || r < 0) {
            /* Sensor read error — log and continue */
            fprintf(stderr, "Sensor read error, continuing...\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            if (t) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            } else {
                strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
                ts[sizeof(ts) - 1] = '\0';
            }

            printf("[%s] L:%d M:%d R:%d\n", ts, l, m, r);

            if (l == 0 && m == 0 && r == 0) {
                printf("EMERGENCY STOP!\n");
                send_uart("EMERGENCY STOP!\n");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

